window.Q=window.Q||{};Q["m37_S4"]=[{"i":"S4-1-1-학개론-01","r":"S4","g":1,"c":1,"n":1,"s":"학개론","q":"토지 관련 용어의 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["필지는 가격수준이 비슷하여 이용·개발·평가의 기준이 되는 일단의 토지를 말한다.","일단지는 하나의 지번이 부여된 토지의 등록단위를 말한다.","빈지는 소유권이 인정되던 전·답 등이 물에 침식되어 수면 밑으로 잠긴 토지를 말한다.","후보지는 택지지역·농지지역·임지지역 상호 간에 용도가 전환되고 있는 토지를 말한다.","법지는 소유권이 인정되지 않는 바다와 육지 사이의 해변토지를 말한다."],"a":[4],"L":"학1-2","o":"변형","x":{"한줄":"후보지는 택지·농지·임지라는 대분류 사이에서 용도가 바뀌어 가는 토지다.","근거":[{"이론":"감정평가이론 — 토지 용어","내용":"후보지는 용도적 지역의 대분류(택지지역·농지지역·임지지역) 상호 간에 전환 중인 토지, 이행지는 같은 대분류 안의 세분(주거·상업·공업 등) 사이에서 이행 중인 토지다."},{"이론":"감정평가이론 — 토지 용어","내용":"필지는 지번 하나가 붙은 등록단위, 획지는 가격수준이 비슷한 일단의 토지, 일단지는 용도상 불가분 관계의 2필지 이상이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"가격수준이 비슷한 일단의 토지는 획지다. 필지는 지번 하나가 붙은 등록단위로 소유권·매매의 단위가 된다."},{"번호":2,"판정":"틀림","설명":"지번 하나가 붙은 등록단위는 필지다. 일단지는 용도상 불가분의 관계에 있는 2필지 이상의 토지를 말한다."},{"번호":3,"판정":"틀림","설명":"소유권이 있던 전·답이 물에 깎여 하천·수면 밑으로 변한 땅은 포락지다. 빈지는 소유권이 인정되지 않는 바다와 육지 사이의 해변이다."},{"번호":4,"판정":"옳음","설명":"후보지는 대분류 간 전환, 이행지는 같은 대분류 안의 소분류 간 이행이다."},{"번호":5,"판정":"틀림","설명":"소유권이 인정되지 않는 해변은 빈지다. 법지는 소유권이 인정되지만 택지 경계의 경사지처럼 이용 가치가 낮은 땅이다."}],"개념":[{"종류":"표","제목":"땅을 묶는 말과 물가의 땅","머리":["구분","뜻","소유권"],"행":[["필지","지번 하나가 붙은 등록단위(소유·매매 단위)","○"],["획지","가격수준이 비슷한 일단의 토지(이용·개발·평가 단위)","-"],["일단지","용도상 불가분인 2필지 이상","○"],["빈지","바다와 육지 사이 해변·갯벌, 쓸모 있음","✕"],["포락지","등록된 전·답이 물에 깎여 수면 밑으로 잠김","원래 ○"],["법지","택지 경계의 경사지, 쓸모 적음","○"]]},{"종류":"비교","제목":"후보지와 이행지","왼쪽":{"이름":"후보지","항목":["대분류 간 전환 중","택지 ↔ 농지 ↔ 임지","예: 농지지역 → 택지지역으로 바뀌는 땅"]},"오른쪽":{"이름":"이행지","항목":["같은 대분류 안 소분류 간 이행 중","택지지역 안에서 주거 → 상업, 공업 → 상업","예: 주거지역 → 상업지역으로 바뀌는 땅"]}}],"함정":"획지와 필지를 서로 바꿔 쓴 선지가 단골이다. 빈지·포락지·법지는 소유권 유무와 쓸모로 가른다. 소유권 ✕는 빈지뿐이고, 물에 잠긴 옛 논밭은 포락지다."}},{"i":"S4-1-1-학개론-02","r":"S4","g":1,"c":1,"n":2,"s":"학개론","q":"토지의 이용 상태에 따른 용어에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부지는 개발되기 이전의 자연 상태 그대로의 토지를 말한다.","포락지는 소유권이 인정되지 않는 바다와 육지 사이의 해변토지를 말한다.","법지는 소유권은 인정되나 택지 경계의 경사지처럼 이용 가치가 낮은 토지를 말한다.","건부지는 지상에 건물 등 정착물이 없는 상태의 토지를 말한다.","유휴지는 지력을 회복하기 위해 정상적으로 쉬게 하는 토지를 말한다."],"a":[3],"L":"학1-2","o":"변형","x":{"한줄":"법지는 소유권이 있으나 택지 경계의 경사진 부분이라 쓸모가 적은 땅이다.","근거":[{"이론":"감정평가이론 — 토지 용어","내용":"법지는 소유권이 인정되는 경사지(택지 경계), 빈지는 소유권이 인정되지 않는 해변, 포락지는 물에 침식되어 잠긴 옛 전·답이다."},{"이론":"감정평가이론 — 토지 용어","내용":"나지는 건물 등 정착물이 없고 지상권 등 사법상 제한이 없는 토지, 건부지는 건물 등이 있는 토지다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개발 이전의 자연 상태 토지는 소지(원지)다. 부지는 어떤 용도에 쓰이는 바닥 땅을 널리 이르는 말이다."},{"번호":2,"판정":"틀림","설명":"소유권이 인정되지 않는 해변은 빈지다. 포락지는 소유권이 있던 땅이 물에 깎여 잠긴 것이다."},{"번호":3,"판정":"옳음","설명":"법지는 소유권 ○, 쓸모가 적다."},{"번호":4,"판정":"틀림","설명":"정착물이 없는 토지는 나지다. 건부지는 건물 등이 있어 건물 부지로 쓰이는 토지다."},{"번호":5,"판정":"틀림","설명":"지력 회복을 위해 정상적으로 쉬는 땅은 휴한지다. 유휴지는 바람직하지 않게 놀리는 땅이다."}],"개념":[{"종류":"표","제목":"건물 유무·쓰임에 따른 토지 용어","머리":["용어","뜻"],"행":[["나지","건물 등 정착물 없음 + 지상권 등 사법상 제한 없음(공법상 제한은 받음)"],["건부지","건물 등이 있어 건물 부지로 쓰이는 땅"],["공지","건부지 중 건물 부분을 뺀 나머지, 건폐율 등으로 비워 둔 땅"],["소지(원지)","개발 이전의 자연 상태 그대로의 땅"],["휴한지","지력 회복을 위해 정상적으로 쉬는 땅"],["유휴지","바람직하지 않게 놀리고 있는 땅"],["공한지","도시 안에서 지가 상승만 노리고 방치한 땅"]]},{"종류":"비교","제목":"맹지와 자루형 땅(대지 袋地)","왼쪽":{"이름":"맹지","항목":["도로에 접한 부분이 전혀 없다","다른 사람 땅에 둘러싸여 있다"]},"오른쪽":{"이름":"자루형 땅(대지 袋地)","항목":["좁은 통로로만 도로와 이어진다","입구가 좁고 안쪽이 넓은 모양"]}}],"함정":"나지와 건부지, 휴한지와 유휴지는 서로 바꿔 놓기 쉽다. 건물이 없으면 나지, 정상적으로 쉬면 휴한지다. 건부지 중 건물을 뺀 나머지는 공지이고 부지가 아니다."}},{"i":"S4-1-1-학개론-03","r":"S4","g":1,"c":1,"n":3,"s":"학개론","q":"토지의 특성에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["용도의 다양성으로 인해 두 개 이상의 용도가 동시에 경합할 수 없고 용도의 전환 및 합병ㆍ분할을 어렵게 한다.","부증성으로 인해 토지의 물리적 공급이 어려우므로 토지이용의 집약화가 요구된다.","부동성으로 인해 주변 환경의 변화에 따른 외부효과가 나타날 수 있다.","영속성으로 인해 재화의 소모를 전제로 하는 재생산이론과 물리적 감가상각이 적용되지 않는다.","개별성으로 인해 토지별 완전한 대체 관계가 제약된다."],"a":[1],"L":"학1-3","o":"기출","x":{"한줄":"용도의 다양성 때문에 한 토지에 둘 이상의 용도가 경합할 수 있고, 용도 전환과 합병·분할도 가능하다.","근거":[{"이론":"토지의 특성","내용":"자연적 특성은 부동성·영속성·부증성·개별성이다. 인문적 특성에는 용도의 다양성, 합병·분할의 가능성, 위치의 가변성이 있다. 용도의 다양성은 하나의 토지를 여러 용도로 쓸 수 있다는 뜻이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"용도의 다양성은 두 개 이상의 용도가 경합할 수 있게 하고, 용도 전환과 합병·분할을 가능하게 한다."},{"번호":2,"판정":"옳음","설명":"부증성은 토지의 물리적 공급을 늘릴 수 없게 하므로 이미 있는 토지를 집약적으로 이용해야 한다."},{"번호":3,"판정":"옳음","설명":"부동성으로 이동이 불가능해 주변 환경의 영향을 그대로 받으며, 외부효과가 나타난다."},{"번호":4,"판정":"옳음","설명":"영속성 때문에 토지에는 소모를 전제로 한 재생산이론과 물리적 감가상각이 적용되지 않는다."},{"번호":5,"판정":"옳음","설명":"개별성으로 같은 토지가 둘 있을 수 없어 완전한 대체재가 제약되고 비교가 어렵다."}],"개념":[{"종류":"표","제목":"자연적 특성과 파생현상","머리":["특성","뜻","파생현상"],"행":[["부동성(지리적 위치의 고정성)","위치를 옮길 수 없다","지역분석, 국지적 시장, 외부효과, 임장활동"],["영속성(비소모성)","사용해도 닳아 없어지지 않는다","재생산이론·감가상각 배제, 가격 보존, 소유이익과 이용이익 분리"],["부증성(비생산성)","물리적 양을 늘릴 수 없다","물리적 공급 한계, 지대·지가 발생, 토지이용 집약화"],["개별성(비동질성)","똑같은 토지가 없다","비교 곤란, 완전한 대체재 없음, 시장 비표준화"]]},{"종류":"표","제목":"인문적 특성","머리":["특성","뜻"],"행":[["용도의 다양성","한 토지에 여러 용도가 경합하고 전환될 수 있다"],["합병·분할의 가능성","필지 단위로 합치거나 나눌 수 있다"],["위치의 가변성","사회적·경제적·행정적 위치가 변한다"],["부동산의 인문적 위치","도로·교통 같은 인문 환경에 따라 가치가 달라진다"]]}],"함정":"용도의 다양성을 '동시에 경합 불가'로 뒤집은 선지를 맞는 말로 읽기 쉽다. 용도 경합과 전환이 가능하다는 것이 이 특성의 요지다."}},{"i":"S4-1-1-학개론-04","r":"S4","g":1,"c":1,"n":4,"s":"학개론","q":"저량(stock)의 경제변수에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["주택재고","가계소득","주택거래량","임대료 수입","신규주택 공급량"],"a":[1],"L":"학2-1","o":"기출","x":{"한줄":"저량은 일정 시점에 존재하는 양이고, 주택재고가 이에 해당한다.","근거":[{"이론":"수요·공급의 변수","내용":"저량(stock)은 일정 시점에 측정하는 변수(주택재고, 인구, 자산 등), 유량(flow)은 일정 기간에 측정하는 변수(소득, 거래량, 신규공급량, 임대료 수입 등)다."}],"선지":[{"번호":1,"판정":"-","설명":"주택재고는 어느 시점에 존재하는 주택 수라서 저량이다."},{"번호":2,"판정":"-","설명":"가계소득은 일정 기간에 벌어들이는 양이므로 유량이다."},{"번호":3,"판정":"-","설명":"주택거래량은 일정 기간에 이루어진 거래 수라서 유량이다."},{"번호":4,"판정":"-","설명":"임대료 수입도 일정 기간의 수입이므로 유량이다."},{"번호":5,"판정":"-","설명":"신규주택 공급량은 일정 기간에 새로 공급되는 양이라 유량이다."}],"개념":[{"종류":"표","제목":"저량과 유량","머리":["구분","측정 방식","부동산 예"],"행":[["저량(stock)","일정 시점","주택재고, 인구, 자산, 통화량"],["유량(flow)","일정 기간","소득, 거래량, 신규 공급량, 임대료 수입, 소비, 투자"],["수요량·공급량","일정 기간","기간을 정해 말하므로 유량"],["가격","-","저량·유량 어느 쪽도 아닌 시장가격"]]},{"종류":"비교","제목":"수요의 변화와 수요량의 변화","왼쪽":{"이름":"수요의 변화","항목":["수요곡선 자체가 이동","소득·선호·인구·대체재 가격·기대 등 가격 이외 요인","소득 증가(정상재) → 오른쪽 이동"]},"오른쪽":{"이름":"수요량의 변화","항목":["같은 수요곡선 위의 점이 이동","해당 재화 가격 변화가 원인","가격 하락 → 수요량 증가"]}}],"함정":"신규주택 공급량·거래량처럼 '량'으로 끝나도 기간으로 재면 유량이다. 주택재고만 시점의 양이다."}},{"i":"S4-1-1-학개론-05","r":"S4","g":1,"c":1,"n":5,"s":"학개론","q":"주택 공급 변화요인과 공급량 변화요인이 옳게 묶인 것은?(단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["공급변화요인 : 해당 주택가격 하락, 공급량 변화요인 : 주택건설업체수의 증가","공급변화요인 : 건축자재 가격의 상승, 공급량 변화요인 : 건설노동자 임금의 상승","공급변화요인 : 건설기술의 개발, 공급량 변화요인 : 건설자금 대출금리의 하락","공급변화요인 : 주택건설용 토지가격의 하락, 공급량 변화요인 : 해당 주택가격의 상승","공급변화요인 : 해당 주택가격의 상승, 공급량 변화요인 : 토지이용규제의 완화"],"a":[4],"L":"학2-1","o":"변형","x":{"한줄":"해당 주택가격의 변화만 공급량 변화요인이고, 투입요소 가격·기술·업체수·금리·규제는 공급변화요인이다.","근거":[{"이론":"공급의 변화와 공급량의 변화","내용":"해당 재화의 가격이 변하면 같은 공급곡선 위에서 공급량이 변한다. 생산기술, 투입요소 가격, 생산자 수, 이자율, 정책·규제, 미래 기대 등이 변하면 공급곡선 자체가 이동한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"두 요인이 서로 바뀌었다. 해당 주택가격 하락은 공급량 변화요인이고, 건설업체수 증가는 공급변화요인이다."},{"번호":2,"판정":"틀림","설명":"건축자재 가격과 임금은 모두 투입요소 가격이라 공급변화요인이다. 공급량 변화요인 칸이 틀렸다."},{"번호":3,"판정":"틀림","설명":"건설기술 개발은 공급변화요인이 맞다. 건설자금 대출금리도 공급변화요인이라서 공급량 변화요인으로 볼 수 없다."},{"번호":4,"판정":"옳음","설명":"토지가격 하락은 건축비가 줄어 공급곡선을 오른쪽으로 옮기고, 해당 주택가격 상승은 같은 곡선 위에서 공급량을 늘린다."},{"번호":5,"판정":"틀림","설명":"해당 주택가격 상승은 공급량 변화요인, 토지이용규제 완화는 공급변화요인이다. 두 칸이 서로 바뀌었다."}],"개념":[{"종류":"표","제목":"공급곡선을 이동시키는 요인","머리":["요인","변화","공급곡선"],"행":[["원자재 가격·임금·토지가격","하락","오른쪽 이동(공급 증가)"],["건설기술","발달","오른쪽 이동"],["건설업체 수","증가","오른쪽 이동"],["담보대출 금리","상승","왼쪽 이동(공급 감소)"],["건축규제","강화","왼쪽 이동"],["해당 주택가격","상승","곡선 위에서 공급량 증가(점의 이동)"]]},{"종류":"비교","제목":"공급과 공급량","왼쪽":{"이름":"공급의 변화","항목":["공급곡선 자체의 이동","원인은 해당 재화 가격 이외 요인"]},"오른쪽":{"이름":"공급량의 변화","항목":["같은 공급곡선 위 점의 이동","원인은 해당 재화의 가격뿐"]}}],"함정":"대출금리·규제·기술을 공급량 변화요인으로 적은 선지가 나온다. 공급량 변화요인은 해당 주택의 가격 하나다."}},{"i":"S4-1-1-학개론-06","r":"S4","g":1,"c":1,"n":6,"s":"학개론","q":"부동산 공급에 관한 설명으로 틀린 것은?(단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["건축비가 하락하면 주택의 공급곡선은 오른쪽으로 이동한다.","해당 부동산 가격의 변화에 따른 공급량의 변화는 동일한 공급곡선상의 점의 이동으로 나타난다.","수요가 증가할 때 공급곡선이 비탄력적일수록 균형가격은 더 작게 상승하고 균형거래량은 더 크게 증가한다.","토지의 물리적 공급은 가격에 대해 완전비탄력적이지만, 용도 전환이 쉬운 토지의 용도별 공급은 상대적으로 탄력적일 수 있다.","주택 공급은 건설에 시간이 걸리므로 단기가 장기보다 비탄력적이다."],"a":[3],"L":"학2-1","o":"변형","x":{"한줄":"공급이 비탄력적일수록 수요 증가 때 가격은 더 크게 오르고 거래량은 덜 늘어난다.","근거":[{"이론":"공급의 가격탄력성","내용":"공급곡선이 비탄력적(가파름)일수록 수요 증가의 효과는 가격 상승으로 많이 나타나고 거래량 증가는 작다. 완전비탄력적이면 거래량은 그대로이고 가격만 오른다."},{"이론":"토지공급","내용":"물리적 토지공급은 가격과 무관하게 일정하나, 용도별 토지공급은 용도 전환이 가능한 만큼 탄력적이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건축비가 줄어들면 같은 가격에서 더 많이 공급하므로 공급곡선이 오른쪽으로 이동한다."},{"번호":2,"판정":"옳음","설명":"해당 재화 가격 변화로 인한 공급량 변화는 같은 곡선 위에서 일어난다."},{"번호":3,"판정":"틀림","설명":"비탄력적일수록 가격 상승폭이 크고 거래량 증가폭은 작다."},{"번호":4,"판정":"옳음","설명":"물리적 공급은 고정이고, 용도별 공급은 용도 전환이 쉬울수록 탄력적이다."},{"번호":5,"판정":"옳음","설명":"생산 기간이 길어 단기에 공급을 조절하기 어려우므로 단기 공급이 더 비탄력적이다."}],"개념":[{"종류":"표","제목":"공급 탄력성의 결정요인","머리":["요인","탄력적","비탄력적"],"행":[["생산비 증가율","작을수록","클수록"],["생산(건설) 기간","짧을수록","길수록"],["용도 전환","쉬울수록","어려울수록"],["규제","약할수록","강할수록"],["측정 기간","길수록(장기)","짧을수록(단기)"]]},{"종류":"비교","제목":"수요 증가 때 공급곡선 모양별 결과","왼쪽":{"이름":"공급이 비탄력적","항목":["균형가격 크게 상승","균형거래량 조금 증가","완전비탄력이면 가격만 상승"]},"오른쪽":{"이름":"공급이 탄력적","항목":["균형가격 조금 상승","균형거래량 크게 증가","완전탄력이면 거래량만 증가"]}}],"함정":"가격과 거래량 중 어느 쪽이 크게 움직이는지를 거꾸로 적은 선지가 단골이다. 비탄력적일수록 가격이 더 오른다."}},{"i":"S4-1-1-학개론-07","r":"S4","g":1,"c":1,"n":7,"s":"학개론","q":"부동산 수요의 탄력성에 관한 설명으로 틀린 것은?(단, x축은 수량, y축은 가격이며, 수요의 가격탄력성은 절대값을 의미하고, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요의 가격탄력성이 1보다 크면 임대료가 하락할 때 임대업자의 총수입은 증가한다.","수요의 가격탄력성이 비탄력적이면 가격의 변화율보다 수요량의 변화율이 더 크다.","대체재가 많을수록 수요의 가격탄력성은 커진다.","수요의 소득탄력성이 음(-)이면 그 재화는 열등재이다.","수요의 교차탄력성이 양(+)이면 두 재화는 대체재이다."],"a":[2],"L":"학2-2","o":"변형","x":{"한줄":"비탄력적이면 수요량 변화율이 가격 변화율보다 작다.","근거":[{"이론":"수요의 탄력성","내용":"가격탄력성 = 수요량 변화율 ÷ 가격 변화율(절대값). 1보다 크면 탄력적, 1보다 작으면 비탄력적이다. 소득탄력성이 음(-)이면 열등재, 교차탄력성이 양(+)이면 대체재, 음(-)이면 보완재다."}],"선지":[{"번호":1,"판정":"옳음","설명":"탄력적(ε>1)이면 가격 하락률보다 수요량 증가율이 커서 총수입이 늘어난다."},{"번호":2,"판정":"틀림","설명":"비탄력적(ε<1)은 가격 변화율보다 수요량 변화율이 작은 경우다."},{"번호":3,"판정":"옳음","설명":"대체재가 많을수록 다른 재화로 옮기기 쉬워 가격 변화에 수요량이 크게 반응한다."},{"번호":4,"판정":"옳음","설명":"소득이 늘 때 수요량이 줄면 소득탄력성이 음(-)이고 열등재다."},{"번호":5,"판정":"옳음","설명":"한 재화 가격이 오를 때 다른 재화 수요량이 늘면 교차탄력성은 양(+)이고 대체재다."}],"개념":[{"종류":"계산","제목":"가격탄력성 계산과 총수입","단계":[{"설명":"공식","식":"ε = 수요량 변화율(%) ÷ 가격 변화율(%)","값":"절대값으로 판정"},{"설명":"대입: 임대료 10% 상승, 수요량 5% 감소","식":"ε = 5 ÷ 10","값":"0.5(비탄력적)"},{"설명":"총수입 변화","식":"1.10 × 0.95 = 1.045","값":"총수입 4.5% 증가"}]},{"종류":"표","제목":"탄력성 크기별 구분","머리":["ε","명칭","수요곡선","가격 상승 시 총수입"],"행":[["0","완전비탄력","수직선","증가"],["0<ε<1","비탄력","가파름","증가"],["1","단위탄력","직각쌍곡선","불변"],["1<ε<∞","탄력","완만함","감소"],["∞","완전탄력","수평선","0으로 감소"]]},{"종류":"표","제목":"소득·교차탄력성의 부호","머리":["탄력성","값","재화의 성격"],"행":[["소득탄력성","음(-)","열등재"],["소득탄력성","0과 1 사이","정상재(필수재)"],["소득탄력성","1보다 큼","정상재(사치재)"],["교차탄력성","양(+)","대체재"],["교차탄력성","음(-)","보완재"]]}],"함정":"완전탄력과 완전비탄력을 바꾸는 선지에 주의한다. 수직선은 완전비탄력, 수평선은 완전탄력이다."}},{"i":"S4-1-1-학개론-08","r":"S4","g":1,"c":1,"n":8,"s":"학개론","q":"부동산경기변동에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산경기는 지역별로 다르게 변동할 수 있고 같은 지역에서도 부분시장에 따라 다른 양상을 보일 수 있다.","하향시장에서는 직전에 거래된 거래사례가격이 새로운 거래가격의 상한이 되는 경향이 있다.","상향시장에서는 매도자 우위, 하향시장에서는 매수자 우위의 시장이 되는 경향이 있다.","후퇴국면에서는 거래량이 감소하고 매수자가 우위에 서는 경향이 있다.","부동산경기변동은 항상 같은 주기와 진폭으로 규칙적으로 되풀이되므로 정점과 저점의 시기를 정확히 예측할 수 있다."],"a":[5],"L":"학2-3","o":"변형","x":{"한줄":"부동산경기는 주기와 진폭이 일정하지 않아 정점·저점의 시기를 정확히 예측하기 어렵다.","근거":[{"이론":"부동산경기변동","내용":"부동산경기는 일반경기와 달리 지역별·부분시장별로 다르게 나타나고, 순환의 주기와 진폭이 불규칙하며, 국면 사이의 시차가 있다."},{"이론":"국면별 시장 성격","내용":"상향시장은 매도자 중시·과거 사례가격이 하한, 하향시장은 매수자 중시·과거 사례가격이 상한이 된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동산경기는 지역성이 있어 지역별·부분시장별로 다르게 움직인다."},{"번호":2,"판정":"옳음","설명":"하향시장에서는 가격이 내리는 중이라 직전 사례가격이 거래가격의 상한이 된다."},{"번호":3,"판정":"옳음","설명":"상향시장은 매도자 우위, 하향시장은 매수자 우위다."},{"번호":4,"판정":"옳음","설명":"후퇴국면에서는 거래가 줄고 매수자가 협상에서 우위를 갖기 시작한다."},{"번호":5,"판정":"틀림","설명":"순환의 주기와 진폭은 일정하지 않고 규칙적이지 않아 정점과 저점을 정확히 예측하기 어렵다."}],"개념":[{"종류":"표","제목":"부동산경기 국면별 특징","머리":["국면","시장 성격","거래사례가격의 역할","그 밖의 특징"],"행":[["회복","매도자 쪽으로 기울기 시작","사례가격이 하한 쪽","저점 통과 후 거래 증가"],["상향","매도자 우위","새 거래가격의 하한","건축 활동 활발, 공실 감소"],["후퇴","매수자 우위로 바뀌기 시작","상한 쪽","거래 감소"],["하향","매수자 우위","새 거래가격의 상한","거래 부진, 공실 증가"],["안정","가격 변동 작음","현재 가격의 지표로 신뢰","국면 구분 뚜렷하지 않음"]]},{"종류":"표","제목":"거미집모형(수렴·발산·순환)","머리":["수요·공급 탄력성 관계","가격 변동","결과"],"행":[["수요의 탄력성 > 공급의 탄력성","진폭 축소","수렴형(균형으로 접근)"],["수요의 탄력성 < 공급의 탄력성","진폭 확대","발산형(균형에서 멀어짐)"],["수요의 탄력성 = 공급의 탄력성","진폭 일정","순환형(진동 지속)"],["모형 전제","공급에 시차(생산기간)가 있다","수요는 당기 가격, 공급은 전기 가격에 반응"]]}],"함정":"'동일한 주기와 진폭으로 규칙적'이라는 표현이 들어간 선지는 틀리다. 국면별 거래사례가격의 상한·하한도 자주 바꿔 나온다."}},{"i":"S4-1-1-학개론-09","r":"S4","g":1,"c":1,"n":9,"s":"학개론","q":"부동산시장에 관한 설명으로 틀린 것은?(단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["부동산시장은 지역·유형·규모·품질에 따라 하위시장으로 나뉘며 하위시장별 가격이 다를 수 있다.","강성 효율적 시장에서는 공표된 정보와 공표되지 않은 정보를 이용해도 초과이윤을 얻을 수 없다.","약성 효율적 시장에서는 과거의 가격 정보를 이용한 기술적 분석으로 초과이윤을 얻을 수 없다.","준강성 효율적 시장에서는 공표되지 않은 내부정보를 이용해도 초과이윤을 얻을 수 없다.","불완전경쟁시장이더라도 정보 비용을 넘는 초과이윤을 얻을 수 없다면 할당효율적 시장이 될 수 있다."],"a":[4],"L":"학3-1","o":"변형","x":{"한줄":"준강성 효율적 시장은 공표된 정보까지만 가격에 반영하므로 내부정보로는 초과이윤이 가능하다.","근거":[{"이론":"효율적 시장가설","내용":"약성은 과거 정보, 준강성은 과거 정보와 공표된 정보, 강성은 공표·비공표 정보를 모두 가격에 반영한다. 정보가 반영된 범위의 정보로는 초과이윤을 얻을 수 없다."},{"이론":"할당효율적 시장","내용":"정보 비용을 초과하는 초과이윤을 얻을 수 없는 시장을 말하며, 완전경쟁이 아니어도 성립할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동산은 개별성·지역성이 있어 하위시장이 나뉘고 가격이 다르다."},{"번호":2,"판정":"옳음","설명":"강성은 비공개 정보까지 반영하므로 어떤 정보로도 초과이윤이 없다."},{"번호":3,"판정":"옳음","설명":"약성은 과거 가격 정보가 반영되어 기술적 분석이 소용없다. 공표된 정보를 쓰는 기본적 분석으로는 가능하다."},{"번호":4,"판정":"틀림","설명":"준강성은 공표된 정보만 반영하므로 비공개 내부정보로는 초과이윤을 얻을 수 있다."},{"번호":5,"판정":"옳음","설명":"정보를 구하는 데 드는 비용보다 큰 초과이윤이 없다면 할당효율적이다."}],"개념":[{"종류":"표","제목":"효율적 시장의 세 형태","머리":["형태","가격에 반영된 정보","초과이윤이 불가능한 분석","초과이윤이 가능한 경우"],"행":[["약성","과거의 정보","기술적 분석","공표된 정보(기본적 분석), 내부정보"],["준강성","과거 + 공표된 정보","기술적·기본적 분석","내부정보"],["강성","공표 + 비공표 정보 전부","어떤 분석도","없음"],["할당효율적","정보 비용 반영","정보 비용 초과 이윤 불가","-"]]},{"종류":"계산","제목":"정보의 현재가치","단계":[{"설명":"공식","식":"정보가치 = 확실성하의 현재가치 − 불확실성하의 현재가치","값":"할인율 10%, 1년 뒤 가치 기준"},{"설명":"불확실성하: 개발 확률 60%, 개발 시 11억, 무산 시 5.5억","식":"기대가치 = 0.6×11 + 0.4×5.5 = 8.8억 → 8.8 ÷ 1.1","값":"8억"},{"설명":"확실성하: 개발이 확정된 경우","식":"11억 ÷ 1.1","값":"10억"},{"설명":"정보가치","식":"10억 − 8억","값":"2억"}]}],"함정":"약성·준강성·강성이 반영하는 정보 범위를 한 칸씩 어긋나게 적은 선지가 나온다. 준강성은 공표된 정보까지다."}},{"i":"S4-1-1-학개론-10","r":"S4","g":1,"c":1,"n":10,"s":"학개론","q":"도시공간구조이론 및 지대이론에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["버제스(E. Burgess)의 동심원이론에 따르면 중심업무지구와 저소득층 주거지대 사이에 점이지대가 위치한다.","호이트(H. Hoyt)의 선형이론에 따르면 도시공간구조의 성장과 분화는 주요 교통축을 따라 부채꼴 모양으로 확대되면서 나타난다.","해리스(C. Harris)와 울만(E. Ullman)의 다핵심이론에 교통축을 적용하여 개선한 이론이 호이트의 선형이론이다.","헤이그(R. Haig)의 마찰비용이론에 따르면 마찰비용은 교통비와 지대로 구성된다.","알론소(W. Alonso)의 입찰지대곡선은 도심에서 외곽으로 나감에따라 가장 높은 지대를 지불할 수 있는 각 산업의 지대곡선들을 연결한 것이다."],"a":[3],"L":"학3-3","o":"기출","x":{"한줄":"다핵심이론은 동심원이론과 선형이론의 한계를 보완해 나온 이론이므로, 선형이론이 다핵심이론을 개선했다는 선지는 선후가 뒤바뀌었다.","근거":[{"이론":"도시공간구조이론","내용":"버제스(1925)의 동심원이론 → 호이트(1939)의 선형이론 → 해리스·울만(1945)의 다핵심이론 순으로 나왔다. 다핵심이론은 동심원·선형이론이 설명하지 못한 여러 핵의 존재를 반영했다."},{"이론":"지대이론","내용":"헤이그는 마찰비용(교통비 + 지대)의 최소화로 입지를 설명했고, 알론소는 도심에서 거리에 따른 입찰지대곡선의 포락선으로 토지이용 배분을 설명했다."}],"선지":[{"번호":1,"판정":"옳음","설명":"동심원이론의 지대는 중심업무지구 → 점이지대 → 저소득층 주거지대 → 중산층 주거지대 → 통근자지대 순이다."},{"번호":2,"판정":"옳음","설명":"선형이론은 도시가 교통망을 따라 부채꼴(쐐기형)로 뻗는다고 본다."},{"번호":3,"판정":"틀림","설명":"호이트의 선형이론(1939)은 해리스·울만의 다핵심이론(1945)보다 먼저 나왔다. 다핵심이론이 동심원·선형이론을 보완했다."},{"번호":4,"판정":"옳음","설명":"헤이그는 마찰비용을 교통비와 지대의 합으로 보고 이를 최소화하는 곳에 입지한다고 설명했다."},{"번호":5,"판정":"옳음","설명":"알론소는 업종별 입찰지대곡선 중 가장 높은 지대를 낼 수 있는 부분을 이은 선으로 토지이용을 설명했다."}],"개념":[{"종류":"표","제목":"도시공간구조 3대 이론","머리":["이론","주장자","핵심 내용"],"행":[["동심원이론","버제스","중심업무지구 → 점이지대 → 저소득층 → 중산층 → 통근자지대, 침입·경쟁·천이로 외곽 확대"],["선형(부채꼴)이론","호이트","교통망을 따라 쐐기형으로 확대, 고급주택지가 한 방향으로 확대"],["다핵심이론","해리스·울만","도시에 여러 핵이 있고 도시가 클수록 핵의 수 증가, 유사 기능은 모이고 해로운 기능은 분리"]]},{"종류":"표","제목":"지대이론","머리":["이론","주장자","핵심"],"행":[["차액지대","리카도","토지 비옥도 차이에서 생기는 차액, 지대는 곡물가격의 결과"],["절대지대","마르크스","최열등지에도 지대 발생(토지 소유 자체)"],["위치(입지)지대","튀넨","시장까지 거리에 따라 지대 차이, 고립국"],["준지대","마샬","단기에 공급이 고정된 생산요소의 소득"],["경제지대","파레토","요소 수입 중 전용수입을 초과한 부분"],["입찰지대","알론소","거리에 따라 지불할 수 있는 최고 지대, 업종별 곡선의 포락선"]]}],"함정":"이론의 선후와 보완 관계를 뒤집은 선지가 나온다. 선형이론과 다핵심이론을 서로 개선했다고 적은 선지는 틀리다."}},{"i":"S4-1-1-학개론-11","r":"S4","g":1,"c":1,"n":11,"s":"학개론","q":"도시공간구조이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["호이트(H. Hoyt)는 도시의 성장과 분화가 침입, 경쟁, 천이의 과정을 거쳐 동심원 모양으로 나타난다고 보았다.","해리스(C. Harris)와 울만(E. Ullman)은 도시 안에 여러 개의 핵이 있고 도시가 성장하면 핵의 수가 늘어나며 기능별로 분화될 수 있다고 보았다.","버제스(E. Burgess)의 동심원이론에서 점이지대는 저소득층 주거지대보다 도심에서 멀리 위치한다.","호이트(H. Hoyt)의 선형이론에 따르면 고소득층 주거지는 교통축과 무관하게 도심에서 가장 먼 곳에 형성된다.","도시공간구조의 변화에는 교통의 발달만 영향을 주고 소득의 증가나 기술 변화는 영향을 주지 못한다."],"a":[2],"L":"학3-3","o":"변형","x":{"한줄":"다핵심이론은 도시 안에 여러 핵이 있고 도시가 클수록 핵이 늘어나 기능이 분화된다고 본다.","근거":[{"이론":"도시공간구조이론","내용":"동심원이론(버제스)은 침입·경쟁·천이 과정으로 동심원 확대, 선형이론(호이트)은 교통축을 따른 쐐기형 확대, 다핵심이론(해리스·울만)은 여러 핵이 성장·분화한다고 설명한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"침입·경쟁·천이로 동심원 모양으로 확대된다고 본 사람은 버제스다. 호이트는 교통축을 따라 확대된다고 보았다."},{"번호":2,"판정":"옳음","설명":"다핵심이론의 핵심요소에는 공업, 소매, 고급주택 등이 있고, 도시가 커질수록 핵의 수가 늘어난다."},{"번호":3,"판정":"틀림","설명":"점이지대는 중심업무지구와 저소득층 주거지대 사이에 있어 저소득층 주거지대보다 도심에 가깝다."},{"번호":4,"판정":"틀림","설명":"호이트는 고소득층 주거지가 교통축을 따라 한 방향(쐐기형)으로 확대된다고 보았다."},{"번호":5,"판정":"틀림","설명":"교통의 발달뿐 아니라 소득 증가, 기술 변화, 인구 증가 등도 도시공간구조를 바꾸는 요인이다."}],"개념":[{"종류":"표","제목":"이론별 비교","머리":["구분","동심원","선형","다핵심"],"행":[["제안자","버제스","호이트","해리스·울만"],["확대 방향","중심에서 고리 모양으로","교통축을 따라 쐐기형","여러 핵을 중심으로"],["핵심 개념","침입·경쟁·천이","교통망, 고급주택지 확대","핵의 수 증가, 기능 분화"],["중심 지대","중심업무지구","중심업무지구","중심업무지구 외 다수 핵"]]},{"종류":"비교","제목":"동심원 이론의 지대 순서","왼쪽":{"이름":"도심 쪽","항목":["① 중심업무지구","② 점이지대(전이지대)"]},"오른쪽":{"이름":"외곽 쪽","항목":["③ 저소득층 주거지대","④ 중산층 주거지대","⑤ 통근자지대(고소득층)"]}}],"함정":"침입·경쟁·천이는 버제스의 개념이다. 호이트와 버제스의 이름을 바꿔 적은 선지가 나온다."}},{"i":"S4-1-1-학개론-12","r":"S4","g":1,"c":1,"n":12,"s":"학개론","q":"A시와 B시 사이에 컨버스(P. Converse)의 상권분기점 모형을 적용할 때, A시로부터 상권분기점까지의 거리는? (단, A시 인구 160만 명, B시 인구 40만 명, 두 도시 간 직선거리 60km이며 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["20km","30km","40km","48km","50km"],"a":[3],"L":"학3-4","o":"신작","x":{"한줄":"D_A = 60 ÷ (1 + √(40/160)) = 60 ÷ 1.5 = 40km이다.","근거":[{"이론":"컨버스의 상권분기점 모형","내용":"A시로부터 분기점까지의 거리 D_A = 두 도시 간 거리 ÷ (1 + √(B시 인구 ÷ A시 인구)). 분기점은 인구가 작은 도시 쪽에 위치한다."}],"선지":[{"번호":1,"판정":"-","설명":"20km는 B시로부터 분기점까지의 거리(60−40)다. A시 기준 거리가 아니다."},{"번호":2,"판정":"-","설명":"30km는 두 도시의 중간점이다. 인구가 다르면 분기점은 중간점이 아니다."},{"번호":3,"판정":"-","설명":"D_A = 60 ÷ (1 + 0.5) = 40km."},{"번호":4,"판정":"-","설명":"48km는 거리를 인구 비율(160/200)로 나눈 값이다. 제곱근을 쓰지 않은 오답이다."},{"번호":5,"판정":"-","설명":"50km는 √를 빼고 B시 인구 비율 40/200만 분모에 넣은 값(60 ÷ 1.2)이다."}],"개념":[{"종류":"계산","제목":"컨버스 분기점 계산","단계":[{"설명":"공식","식":"D_A = D_AB ÷ (1 + √(P_B ÷ P_A))","값":"A시 기준 거리"},{"설명":"인구비 대입","식":"√(40 ÷ 160) = √0.25","값":"0.5"},{"설명":"분기점 거리","식":"60 ÷ (1 + 0.5)","값":"40km"},{"설명":"B시 기준 거리 검산","식":"60 − 40","값":"20km (A시 인구가 4배라 √4 = 2배 차이: 40 : 20)"}]},{"종류":"표","제목":"상업입지 이론","머리":["이론","주장자","내용"],"행":[["소매인력법칙","레일리","두 도시의 소매 흡인력은 인구에 비례, 거리의 제곱에 반비례"],["상권분기점 모형","컨버스","레일리 법칙으로 두 도시의 분기점을 구하는 공식"],["확률모형","허프","소비자의 점포 선택 확률은 점포 면적에 비례, 거리의 λ 제곱에 반비례"],["소매입지 원칙","넬슨","누적적 흡인력, 양립성, 상호보완성 등 8원칙"]]}],"함정":"분기점이 A시와 B시 중 어느 쪽 기준인지 확인한다. 20km는 B시 기준 거리이고, 인구 비율을 그대로 쓰면 48km가 나온다."}},{"i":"S4-1-1-학개론-13","r":"S4","g":1,"c":1,"n":13,"s":"학개론","q":"입지이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["레일리(W. Reilly)의 소매인력법칙에 따르면 두 도시의 소매 흡인력은 인구에 반비례하고 거리의 제곱에 비례한다.","허프(D. Huff)모형에서 거리마찰계수가 클수록 소비자가 점포를 선택할 때 거리의 영향이 작아진다.","베버(A. Weber)의 최소비용이론에서 원료지수가 1보다 큰 산업은 운송비를 줄이기 위해 원료산지 가까이에 입지하는 경향이 있다.","넬슨(R. Nelson)의 누적적 흡인력의 원칙에 따르면 동종 업종이 집중할수록 고객 유인력이 줄어 매출이 감소한다.","입지계수가 1보다 작은 산업은 그 지역의 기반산업으로 판단한다."],"a":[3],"L":"학3-4","o":"신작","x":{"한줄":"원료지수가 1보다 크면 원료가 무거워 운송비가 줄어드는 원료산지에 입지한다.","근거":[{"이론":"베버의 최소비용이론","내용":"원료지수 = 국지원료의 중량 ÷ 제품의 중량. 1보다 크면 원료지향, 1보다 작으면 시장(소비지)지향 입지를 한다."},{"이론":"입지계수","내용":"입지계수(LQ) = (지역 내 특정 산업 비중) ÷ (전국 내 같은 산업 비중). 1보다 크면 기반(수출)산업이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소매 흡인력은 인구에 비례하고 거리의 제곱에 반비례한다."},{"번호":2,"판정":"틀림","설명":"거리마찰계수가 클수록 거리가 멀수록 선택 확률이 급격히 떨어지므로 거리의 영향이 커진다."},{"번호":3,"판정":"옳음","설명":"국지원료 중량이 제품보다 크면 운송비 최소점이 원료산지 쪽이다."},{"번호":4,"판정":"틀림","설명":"누적적 흡인력의 원칙은 유사·보완 업종이 모일수록 고객 유인력이 커져 매출이 늘어난다는 원칙이다."},{"번호":5,"판정":"틀림","설명":"입지계수가 1보다 큰 산업이 기반산업이다. 1보다 작으면 비기반산업이다."}],"개념":[{"종류":"표","제목":"공업입지 이론","머리":["이론","주장자","내용"],"행":[["최소비용이론","베버","운송비 최소점, 원료지수, 노동비·집적이익 보정(등비용선)"],["최대수요이론","뢰시","수요가 최대인 곳이 이윤극대화 입지"],["중심지이론","크리스탈러","중심지 기능의 도달범위·최소요구범위"],["입지계수","-","LQ>1 기반산업, LQ<1 비기반산업"]]},{"종류":"비교","제목":"원료지수에 따른 입지","왼쪽":{"이름":"원료지수 > 1","항목":["국지원료가 제품보다 무겁다","원료산지에 입지","예: 시멘트·철강"]},"오른쪽":{"이름":"원료지수 < 1","항목":["제품이 원료보다 무겁다","시장(소비지)에 입지","예: 음료·가구"]}}],"함정":"비례·반비례와 1보다 큰지·작은지를 뒤집은 선지가 나온다. 레일리는 인구에 비례하고 거리 제곱에 반비례한다."}},{"i":"S4-1-1-학개론-14","r":"S4","g":1,"c":1,"n":14,"s":"학개론","q":"부동산시장의 시장실패와 정부개입에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공공재는 비경합성과 비배제성 때문에 무임승차 문제가 생겨 시장에서 과소공급되는 경향이 있다.","정보의 비대칭성은 역선택과 도덕적 해이를 낳아 시장의 효율성을 해칠 수 있다.","긍정적 외부효과가 있는 경우 시장에서의 생산량은 사회적 최적 수준보다 적다.","부정적 외부효과를 일으키는 활동에 비용을 부과하면 사적 비용과 사회적 비용의 차이를 줄일 수 있다.","독점이나 과점 같은 불완전경쟁시장에서는 가격이 한계비용과 같아지므로 자원이 효율적으로 배분된다."],"a":[5],"L":"학4-1","o":"변형","x":{"한줄":"불완전경쟁시장은 가격이 한계비용을 넘어서므로 자원이 비효율적으로 배분되어 시장실패의 원인이 된다.","근거":[{"이론":"시장실패의 원인","내용":"시장실패는 불완전경쟁(독점·과점), 외부효과, 공공재, 정보의 비대칭성에서 생긴다. 재화의 동질성은 완전경쟁시장의 조건이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공공재는 비경합·비배제 때문에 무임승차가 생겨 민간 공급이 부족하다."},{"번호":2,"판정":"옳음","설명":"정보 비대칭은 역선택(계약 전)·도덕적 해이(계약 후)를 일으킨다."},{"번호":3,"판정":"옳음","설명":"긍정적 외부효과는 사회적 편익이 사적 편익보다 커 시장 생산량이 최적 수준에 못 미친다."},{"번호":4,"판정":"옳음","설명":"부정적 외부효과에 부담금·세금을 부과하면 사적 비용에 사회적 비용이 반영된다."},{"번호":5,"판정":"틀림","설명":"불완전경쟁에서는 가격이 한계비용보다 높게 형성되어 자원배분이 비효율적이다."}],"개념":[{"종류":"표","제목":"시장실패의 원인과 정부 대응","머리":["원인","내용","대응"],"행":[["불완전경쟁","독점·과점으로 가격이 한계비용보다 높음","경쟁 촉진, 가격 규제"],["외부효과","거래 당사자 밖에 영향이 미침(정·부)","보조금·부담금, 용도지역제"],["공공재","비경합·비배제, 무임승차","정부가 직접 공급"],["정보의 비대칭","역선택·도덕적 해이","정보 공개, 자격·등록 제도"]]},{"종류":"표","제목":"정부 개입 수단","머리":["구분","수단","예"],"행":[["직접 개입","토지 수용·비축, 공영개발, 공공임대주택","토지은행, 공공주택 공급"],["간접 개입","조세, 금융, 보조금","취득세·양도세, 대출 규제"],["규제","용도지역·지구제, 개발제한구역","국토의 계획 및 이용에 관한 법률"],["이익 환수","개발부담금","개발이익 환수에 관한 법률 제2조제4호: 개발이익 중 이 법에 따라 부과·징수하는 금액"]]}],"함정":"재화의 동질성은 완전경쟁시장의 조건이므로 시장실패 원인이 아니다. 불완전경쟁을 효율적 배분으로 적은 선지는 틀리다."}},{"i":"S4-1-1-학개론-15","r":"S4","g":1,"c":1,"n":15,"s":"학개론","q":"용도지역·지구제에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["용도지역제는 상충하는 토지이용을 분리하여 부(-)의 외부효과를 줄이는 수단이다.","국토의 계획 및 이용에 관한 법령상 제1종일반주거지역은 저층주택을 중심으로 편리한 주거환경을 조성하기 위하여 필요한 지역이다.","국토의 계획 및 이용에 관한 법령상 용도지구는 용도지역의 제한을 강화하거나 완화하여 적용함으로써 용도지역의 기능을 증진시키기 위한 지역이다.","국토의 계획 및 이용에 관한 법령상 제2종전용주거지역은 단독주택 중심의 양호한 주거환경을 보호하기 위하여 필요한 지역이다.","국토의 계획 및 이용에 관한 법령상 계획관리지역은 도시지역으로의 편입이 예상되는 지역이나 자연환경을 고려하여 제한적인 이용·개발을 하려는 지역이다."],"a":[4],"L":"학4-1","o":"변형","x":{"한줄":"단독주택 중심은 제1종전용주거지역이고, 제2종전용주거지역은 공동주택 중심이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제30조제1항제1호","원문":"가. 전용주거지역 : 양호한 주거환경을 보호하기 위하여 필요한 지역 (1) 제1종전용주거지역 : 단독주택 중심의 양호한 주거환경을 보호하기 위하여 필요한 지역 (2) 제2종전용주거지역 : 공동주택 중심의 양호한 주거환경을 보호하기 위하여 필요한 지역 나. 일반주거지역 : 편리한 주거환경을 조성하기 위하여 필요한 지역 (1) 제1종일반주거지역 : 저층주택을 중심으로 편리한 주거환경을 조성하기 위하여 필요한 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제16호","원문":"\"용도지구\"란 토지의 이용 및 건축물의 용도ㆍ건폐율ㆍ용적률ㆍ높이 등에 대한 용도지역의 제한을 강화하거나 완화하여 적용함으로써 용도지역의 기능을 증진시키고 경관ㆍ안전 등을 도모하기 위하여 도시ㆍ군관리계획으로 결정하는 지역을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제36조제1항제2호다목","원문":"계획관리지역: 도시지역으로의 편입이 예상되는 지역이나 자연환경을 고려하여 제한적인 이용ㆍ개발을 하려는 지역으로서 계획적ㆍ체계적인 관리가 필요한 지역"}],"선지":[{"번호":1,"판정":"옳음","설명":"용도지역제는 주거와 공업 같은 상충 용도를 분리해 부(-)의 외부효과를 줄인다."},{"번호":2,"판정":"옳음","설명":"제1종일반주거지역은 저층주택 중심이다(시행령 제30조제1항제1호 나목 (1))."},{"번호":3,"판정":"옳음","설명":"용도지구는 용도지역의 제한을 강화하거나 완화하는 지역이다(법 제2조제16호)."},{"번호":4,"판정":"틀림","설명":"제2종전용주거지역은 공동주택 중심이다. 단독주택 중심은 제1종전용주거지역이다(시행령 제30조제1항제1호 가목)."},{"번호":5,"판정":"옳음","설명":"계획관리지역은 도시지역 편입이 예상되는 지역이다(법 제36조제1항제2호 다목)."}],"개념":[{"종류":"표","제목":"주거지역의 세분(시행령 제30조)","머리":["구분","중심 주택","목적"],"행":[["제1종전용주거지역","단독주택","양호한 주거환경 보호"],["제2종전용주거지역","공동주택","양호한 주거환경 보호"],["제1종일반주거지역","저층주택","편리한 주거환경 조성"],["제2종일반주거지역","중층주택","편리한 주거환경 조성"],["제3종일반주거지역","중고층주택","편리한 주거환경 조성"],["준주거지역","주거기능 + 일부 상업·업무기능","주거기능 위주, 상업·업무 보완"]]},{"종류":"표","제목":"용도지역의 큰 구분(법 제6조, 제36조)","머리":["대분류","세분","특징"],"행":[["도시지역","주거·상업·공업·녹지지역","체계적 개발·정비·관리·보전이 필요한 지역"],["관리지역","보전·생산·계획관리지역","도시지역에 준하거나 농림·자연환경보전지역에 준하여 관리"],["농림지역","-","농업진흥지역·보전산지 등"],["자연환경보전지역","-","자연환경·수자원·해안·생태계 보전"]]}],"함정":"전용주거지역의 '단독'과 '공동'을 서로 바꾼 선지가 나온다. 제1종은 단독주택, 제2종은 공동주택이다. 일반주거지역은 1종 저층, 2종 중층, 3종 중고층이다."}},{"i":"S4-1-1-학개론-16","r":"S4","g":1,"c":1,"n":16,"s":"학개론","q":"현재 우리나라에서 시행되고 있는 주택정책수단이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["공공임대주택제도","주거급여제도","주택청약종합저축제도","개발권양도제도","재건축초과이익환수제도"],"a":[4],"L":"학4-2","o":"기출","x":{"한줄":"개발권양도제도(TDR)는 우리나라에서 아직 시행되지 않는다.","근거":[{"법령":"공공주택 특별법","조문":"제2조제1호가목","원문":"임대 또는 임대한 후 분양전환을 할 목적으로 공급하는 「주택법」 제2조제1호에 따른 주택으로서 대통령령으로 정하는 주택(이하 \"공공임대주택\"이라 한다)"}],"선지":[{"번호":1,"판정":"-","설명":"공공임대주택은 공공주택 특별법에 따라 공급되는 제도로 시행 중이다."},{"번호":2,"판정":"-","설명":"주거급여는 저소득 가구의 임차료·수선유지비를 지원하는 제도로 시행 중이다."},{"번호":3,"판정":"-","설명":"주택청약종합저축은 주택도시기금이 운영하는 청약저축으로 시행 중이다."},{"번호":4,"판정":"-","설명":"개발권양도제는 규제로 개발이 제한된 토지의 개발권을 다른 곳에 팔게 하는 제도이며 현재 시행되지 않는다."},{"번호":5,"판정":"-","설명":"재건축 초과이익 환수에 관한 법률에 따라 시행 중이다."}],"개념":[{"종류":"표","제목":"주택정책수단","머리":["수단","내용","시행 여부"],"행":[["공공임대주택","국가·지자체 재정·주택도시기금으로 공급하는 임대주택","시행"],["주거급여","저소득 가구 임차료·수선유지비 지원(임대료 보조)","시행"],["분양가상한제","공공택지 등에서 분양가격을 제한(주택법 제57조)","시행"],["재건축초과이익환수제","재건축으로 생긴 초과이익 환수","시행"],["개발권양도제(TDR)","개발제한 토지의 개발권을 거래","미시행"]]},{"종류":"표","제목":"공공임대주택 유형(공공주택 특별법 시행령 제2조)","머리":["유형","대상·성격"],"행":[["영구임대주택","최저소득 계층, 50년 이상 또는 영구 임대"],["국민임대주택","저소득 서민, 30년 이상 장기 임대"],["행복주택","대학생·사회초년생·신혼부부 등 젊은 층"],["통합공공임대주택","최저소득 계층·저소득 서민·젊은 층·취약계층 통합"]]}],"함정":"토지정책 이론에 나오는 개발권양도제(TDR)는 현재 시행되지 않는다. 이름이 익숙해도 제도 시행 여부는 별개다."}},{"i":"S4-1-1-학개론-17","r":"S4","g":1,"c":1,"n":17,"s":"학개론","q":"부동산조세에 관한 설명으로 옳은 것을 모두 고른 것은? (단, 다른 조건은 동일함)","b":"ㄱ. 취득세는 지방자치단체의 재정수요를 충족시키는 기능이 있다.\nㄴ. 부동산 거래세를 부과하면 총잉여가 증가하므로 경제적 순손실이 발생하지 않는다.\nㄷ. 양도소득세가 강화되어 동결효과(lock-in effect)가 발생하면 부동산가격이 하락한다.\nㄹ. 공급의 가격탄력성이 수요의 가격탄력성보다 작은 경우 공급자가 수요자보다 조세부담이 더 크다.\nㅁ. 헨리 조지(H. George)는 토지세가 임차인에게 모두 전가되는 것을 근거로 토지단일세 도입을 주장하였다.","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ, ㅁ","ㄴ, ㄹ, ㅁ","ㄱ, ㄷ, ㄹ, ㅁ"],"a":[2],"L":"학4-3","o":"기출","x":{"한줄":"옳은 것은 ㄱ(취득세는 지방세로 재정수요 충족)과 ㄹ(탄력성이 작은 쪽이 조세를 더 부담)이다.","근거":[{"이론":"조세의 귀착","내용":"조세 부담은 가격에 덜 탄력적인 쪽이 더 크게 진다. 공급이 수요보다 비탄력적이면 공급자 부담이 더 크다."},{"이론":"거래세와 경제적 순손실","내용":"거래세를 부과하면 거래량이 줄어 총잉여가 감소하고 경제적 순손실(자중손실)이 생긴다."},{"이론":"동결효과","내용":"양도소득세가 강화되면 매도를 미루어 매물이 감소하고 부동산가격은 상승한다."},{"이론":"헨리 조지","내용":"토지 공급이 고정되어 토지세는 임차인에게 전가되지 않고 지주가 부담한다. 이를 근거로 토지단일세를 주장했다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ이 틀리므로 조합이 맞지 않는다."},{"번호":2,"판정":"-","설명":"ㄱ과 ㄹ이 옳은 조합이다."},{"번호":3,"판정":"-","설명":"ㄴ, ㄷ, ㅁ이 모두 틀리므로 조합이 맞지 않는다."},{"번호":4,"판정":"-","설명":"ㄴ과 ㅁ이 틀리므로 조합이 맞지 않는다."},{"번호":5,"판정":"-","설명":"ㄷ과 ㅁ이 틀리므로 조합이 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"취득세는 지방세로, 지방자치단체의 재정수요를 충족시킨다."},{"기호":"ㄴ","판정":"틀림","설명":"거래세를 부과하면 거래량이 줄어 총잉여가 감소하고 경제적 순손실이 발생한다."},{"기호":"ㄷ","판정":"틀림","설명":"동결효과로 매물이 줄어 부동산가격은 상승한다."},{"기호":"ㄹ","판정":"옳음","설명":"공급이 수요보다 비탄력적이면 공급자가 조세를 더 많이 부담한다."},{"기호":"ㅁ","판정":"틀림","설명":"헨리 조지는 토지세가 전가되지 않고 지주가 부담한다는 점을 근거로 토지단일세를 주장했다."}],"개념":[{"종류":"표","제목":"부동산 관련 조세 분류","머리":["단계","국세","지방세"],"행":[["취득","상속세, 증여세, 인지세","취득세, 등록면허세"],["보유","종합부동산세","재산세, 지방교육세"],["처분","양도소득세","지방소득세(양도소득분)"]]},{"종류":"비교","제목":"조세 귀착","왼쪽":{"이름":"수요가 비탄력적(공급이 탄력적)","항목":["수요자의 조세부담이 더 큼","예: 필수 주거용 부동산"]},"오른쪽":{"이름":"공급이 비탄력적(수요가 탄력적)","항목":["공급자의 조세부담이 더 큼","예: 토지 — 완전비탄력이면 전부 공급자(지주) 부담"]}}],"함정":"동결효과를 가격 하락으로 읽기 쉽다. 매물이 줄어 가격은 오른다. 거래세 부과로 총잉여가 늘어난다는 보기도 틀리다."}},{"i":"S4-1-1-학개론-18","r":"S4","g":1,"c":1,"n":18,"s":"학개론","q":"포트폴리오이론에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["개별자산의 기대수익률 간 상관계수가 “0”인 두 개의 자산으로 포트폴리오를 구성할 때 포트폴리오의 위험감소효과가 최대로 나타난다.","포트폴리오의 기대수익률은 개별자산의 기대수익률을 가중평균하여 구한다.","동일한 자산들로 포트폴리오를 구성하여도 개별자산의 투자비중에 따라 포트폴리오의 기대수익률과 분산은 다를 수 있다.","무차별곡선은 투자자에게 동일한 효용을 주는 수익과 위험의 조합을 나타낸 곡선이다.","최적 포트폴리오의 선정은 투자자의 위험에 대한 태도에 따라 달라질 수 있다."],"a":[1],"L":"학5-1","o":"기출","x":{"한줄":"위험감소효과가 최대인 것은 상관계수가 −1일 때이고, 0일 때가 아니다.","근거":[{"이론":"포트폴리오이론","내용":"상관계수가 +1이면 분산효과가 없고, −1이면 위험감소효과가 최대다. 포트폴리오의 기대수익률은 자산별 기대수익률의 가중평균이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"상관계수가 −1일 때 위험이 가장 크게 줄어든다. 0이면 일부만 줄어든다."},{"번호":2,"판정":"옳음","설명":"포트폴리오 기대수익률 = Σ(투자비중 × 개별자산 기대수익률)."},{"번호":3,"판정":"옳음","설명":"같은 자산이라도 투자비중이 달라지면 기대수익률과 분산이 달라진다."},{"번호":4,"판정":"옳음","설명":"무차별곡선은 효용이 같은 수익-위험 조합을 이은 선이다."},{"번호":5,"판정":"옳음","설명":"위험회피도가 투자자마다 달라 최적 포트폴리오도 달라진다."}],"개념":[{"종류":"표","제목":"상관계수와 분산투자 효과","머리":["상관계수","의미","위험감소효과"],"행":[["+1","같은 방향으로 완전히 움직임","없음"],["0","서로 무관하게 움직임","일부 있음"],["−1","반대 방향으로 완전히 움직임","최대(위험 제거 가능)"],["−1 < r < +1","일반 경우","상관계수가 낮을수록 효과 큼"]]},{"종류":"계산","제목":"포트폴리오 기대수익률","단계":[{"설명":"공식","식":"E(R_p) = Σ(w_i × E(R_i))","값":"가중평균"},{"설명":"대입: A 40%·기대수익률 12%, B 60%·기대수익률 7%","식":"0.4 × 12 + 0.6 × 7 = 4.8 + 4.2","값":"9.0%"}]}],"함정":"상관계수 0과 −1을 혼동한다. 최대 효과는 −1이고, 같은 방향(+1)이면 효과가 없다."}},{"i":"S4-1-1-학개론-19","r":"S4","g":1,"c":1,"n":19,"s":"학개론","q":"부동산투자의 수익과 위험에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["투자안의 기대수익률이 요구수익률보다 크면 투자 타당성이 인정된다.","투자자의 위험회피 성향이 강할수록 요구수익률에 포함되는 위험할증률은 낮아진다.","평균-분산 지배원리에 따르면 기대수익률이 같은 투자안 중에서는 표준편차가 작은 투자안이 우월하다.","변동계수(변이계수)는 기대수익률 한 단위당 위험을 나타내며 값이 작은 투자안이 유리하다.","사업위험, 금융위험, 법적 위험, 유동성 위험은 부동산투자의 위험을 구성하는 요인이다."],"a":[2],"L":"학5-1","o":"변형","x":{"한줄":"위험회피 성향이 강할수록 위험을 감수하는 대가인 위험할증률이 높아진다.","근거":[{"이론":"요구수익률","내용":"요구수익률 = 무위험률 + 위험할증률 (+ 예상 인플레이션율). 위험회피도가 클수록 위험할증률이 커진다."},{"이론":"변동계수","내용":"변동계수 = 표준편차 ÷ 기대수익률. 기대수익률 한 단위당 위험을 나타내며 작을수록 유리하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기대수익률이 요구수익률보다 크면 투자안을 채택한다."},{"번호":2,"판정":"틀림","설명":"위험회피 성향이 강할수록 더 높은 위험할증률을 요구하므로 위험할증률이 높아진다."},{"번호":3,"판정":"옳음","설명":"기대수익률이 같으면 표준편차가 작은 쪽이 지배한다."},{"번호":4,"판정":"옳음","설명":"변동계수가 작을수록 기대수익 한 단위당 위험이 낮다."},{"번호":5,"판정":"옳음","설명":"사업위험·금융위험·법적 위험·유동성 위험·인플레이션 위험 등이 있다."}],"개념":[{"종류":"계산","제목":"기대수익률·표준편차·변동계수","단계":[{"설명":"자료","식":"호황 50% 시 12%, 불황 50% 시 4%","값":"확률가중"},{"설명":"기대수익률","식":"0.5×12 + 0.5×4","값":"8%"},{"설명":"분산","식":"0.5×(12−8)² + 0.5×(4−8)² = 0.5×16 + 0.5×16","값":"16"},{"설명":"표준편차 · 변동계수","식":"√16 = 4 → 4 ÷ 8","값":"변동계수 0.5"}]},{"종류":"표","제목":"투자위험의 종류","머리":["위험","내용"],"행":[["사업위험","경기·시장·입지 변화로 수익 변동"],["금융위험","차입에 따른 이자 부담 위험(레버리지)"],["법적 위험","법령·제도 변경 위험"],["유동성 위험","원하는 시기에 현금화하지 못할 위험"],["인플레이션 위험","물가 상승으로 실질수익 하락"]]}],"함정":"요구수익률은 무위험률과 위험할증률의 합이다. 위험회피도와 위험할증률의 방향을 거꾸로 적은 선지를 조심한다."}},{"i":"S4-1-1-학개론-20","r":"S4","g":1,"c":1,"n":20,"s":"학개론","q":"부동산투자의 포트폴리오이론에 관한 설명으로 옳은 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["인플레이션, 경기변동 등의 체계적 위험은 분산투자를 통해 제거할 수 없다.","2개 투자자산의 수익률이 서로 아무런 관계없이 움직인다면 상관계수는 1이다.","투자자가 효용이 동일하다고 느끼는 조합을 연결한 선을 효율적 투자선이라 한다.","포트폴리오 구성자산의 수익률이 같은 방향으로 움직일 경우 위험감소의 효과가 크다.","기대수익률의 분산 또는 표준편차는 투자안의 수익을 측정하는 전통적인 방법이다."],"a":[1],"L":"학5-1","o":"기출","x":{"한줄":"체계적 위험은 시장 전체에 영향을 주는 위험이라 분산투자로 제거할 수 없다.","근거":[{"이론":"체계적 위험과 비체계적 위험","내용":"체계적 위험(인플레이션·경기변동·금리)은 분산투자로 제거할 수 없고, 비체계적 위험(개별 자산 고유 위험)은 분산투자로 줄일 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"체계적 위험은 모든 자산에 공통으로 작용해 분산투자로 제거되지 않는다."},{"번호":2,"판정":"틀림","설명":"서로 아무 관계가 없으면 상관계수는 0이다. 1은 완전히 같은 방향으로 움직이는 경우다."},{"번호":3,"판정":"틀림","설명":"효용이 같은 조합을 이은 선은 무차별곡선이다. 효율적 투자선은 같은 위험에서 기대수익률이 최대인 점들을 이은 선이다."},{"번호":4,"판정":"틀림","설명":"같은 방향으로 움직이면 위험감소효과가 작다. 반대 방향으로 움직일수록 위험감소효과가 크다."},{"번호":5,"판정":"틀림","설명":"분산·표준편차는 수익이 아니라 위험을 측정하는 전통적인 방법이다."}],"개념":[{"종류":"비교","제목":"체계적 위험과 비체계적 위험","왼쪽":{"이름":"체계적 위험(시장위험)","항목":["경기변동·인플레이션·금리 변화","모든 자산에 공통","분산투자로 제거 불가"]},"오른쪽":{"이름":"비체계적 위험(고유위험)","항목":["개별 부동산의 입지·관리·임차인 문제","자산마다 다름","분산투자로 감소 가능"]}},{"종류":"표","제목":"포트폴리오이론 용어","머리":["용어","뜻"],"행":[["무차별곡선","투자자에게 효용이 같은 수익-위험 조합을 이은 곡선"],["효율적 전선(투자선)","같은 위험에서 최대 수익률을 주는 포트폴리오들의 집합"],["최적 포트폴리오","무차별곡선과 효율적 전선이 접하는 점"],["분산·표준편차","수익률의 흩어진 정도, 위험의 척도"]]}],"함정":"무차별곡선과 효율적 전선의 정의를 서로 바꿔 놓은 선지가 나온다. 분산·표준편차는 수익이 아니라 위험의 척도다."}},{"i":"S4-1-1-학개론-21","r":"S4","g":1,"c":1,"n":21,"s":"학개론","q":"연 이자율 10%(연 복리)를 적용할 때 화폐의 시간가치에 관한 설명으로 옳은 것은? (단, 현금흐름은 모두 매년 말에 발생하며, 계수는 소수점 아래 다섯째 자리에서 반올림하고, 주어진 조건에 한함)","b":null,"bs":"없음","img":[],"ch":["현재 1,000만원을 3년간 예치하면 3년 후 원리금 합계는 1,300만원이다.","매년 말 1,000만원씩 3년간 적립하면 3년 말 원리금 합계는 3,310만원이다.","3년 후 3,000만원을 만들기 위해 매년 말 적립할 금액은 1,000만원이다.","매년 말 1,000만원씩 3년간 받는 연금의 현재가치는 3,000만원이다.","3,000만원을 3년간 매년 말 원리금균등상환 방식으로 대출받으면 매년 상환할 원리금은 1,000만원이다."],"a":[2],"L":"학5-2","o":"신작","x":{"한줄":"매년 말 적립액에 연금의 내가계수 3.31(= (1.331 − 1) ÷ 0.1)을 곱하면 1,000만원 × 3.31 = 3,310만원이다.","근거":[{"이론":"연금의 내가계수","내용":"[(1+r)ⁿ − 1] ÷ r. 매기 같은 금액을 적립할 때 n기 말 원리금 합계를 구하는 계수다. r = 10%, n = 3이면 (1.331 − 1) ÷ 0.1 = 3.31이다."},{"이론":"감채기금계수·저당상수","내용":"감채기금계수 r ÷ [(1+r)ⁿ − 1]는 연금의 내가계수의 역수이고, 저당상수 r(1+r)ⁿ ÷ [(1+r)ⁿ − 1]는 연금의 현가계수의 역수다."}],"선지":[{"번호":1,"판정":"틀림","설명":"1,000만원 × 일시불의 내가계수 1.331 = 1,331만원이다. 1,300만원은 단리로 3년치 이자 300만원을 더한 값이다."},{"번호":2,"판정":"옳음","설명":"첫해 말 적립금은 2년간 이자가 붙어 1,210만원, 둘째 해 말 적립금은 1년간 이자가 붙어 1,100만원, 셋째 해 말 적립금은 1,000만원이다. 합계 3,310만원이며 1,000 × 3.31과 같다."},{"번호":3,"판정":"틀림","설명":"목표액 × 감채기금계수로 구한다. 3,000만원 × 0.3021 ≈ 906만원이다."},{"번호":4,"판정":"틀림","설명":"연금의 현재가치 = 매기 금액 × 연금의 현가계수 = 1,000만원 × 2.4869 ≈ 2,487만원이다. 3,000만원은 할인 없이 더한 값이다."},{"번호":5,"판정":"틀림","설명":"원리금균등상환액 = 대출액 × 저당상수 = 3,000만원 × 0.4021 ≈ 1,206만원이다."}],"개념":[{"종류":"계산","제목":"연 10%, 3년 계수와 선지 ②·③·④·⑤ 계산","단계":[{"설명":"일시불의 내가계수","식":"(1+r)ⁿ","값":"1.1³ = 1.3310"},{"설명":"연금의 내가계수 → 선지 ②","식":"[(1+r)ⁿ − 1] ÷ r = (1.331 − 1) ÷ 0.1","값":"3.3100, 1,000만원 × 3.31 = 3,310만원"},{"설명":"감채기금계수 → 선지 ③","식":"r ÷ [(1+r)ⁿ − 1] = 0.1 ÷ 0.331","값":"0.3021, 3,000만원 × 0.3021 ≈ 906만원"},{"설명":"연금의 현가계수 → 선지 ④","식":"[(1+r)ⁿ − 1] ÷ [r(1+r)ⁿ] = 0.331 ÷ 0.1331","값":"2.4869, 1,000만원 × 2.4869 ≈ 2,487만원"},{"설명":"저당상수 → 선지 ⑤","식":"연금의 현가계수의 역수 = 1 ÷ 2.4869","값":"0.4021, 3,000만원 × 0.4021 ≈ 1,206만원"}]},{"종류":"표","제목":"6계수 값 (r = 10%, n = 3)","머리":["계수","식","값","곱하는 금액"],"행":[["일시불의 내가계수","(1+r)ⁿ","1.3310","현재 금액 → n년 후 금액"],["일시불의 현가계수","1 ÷ (1+r)ⁿ","0.7513","n년 후 금액 → 현재 금액"],["연금의 내가계수","[(1+r)ⁿ − 1] ÷ r","3.3100","매기 적립액 → n기 말 합계"],["연금의 현가계수","[(1+r)ⁿ − 1] ÷ [r(1+r)ⁿ]","2.4869","매기 수령액 → 현재 가치"],["감채기금계수","r ÷ [(1+r)ⁿ − 1]","0.3021","목표액 → 매기 적립액"],["저당상수","r(1+r)ⁿ ÷ [(1+r)ⁿ − 1]","0.4021","대출액 → 매기 원리금"]]}],"함정":"③·④·⑤는 이자를 반영하지 않고 3,000 ÷ 3 = 1,000, 1,000 × 3 = 3,000으로 계산한 값이다. 모으는 돈은 감채기금계수, 빌린 돈은 저당상수, 받을 연금을 지금 가치로 바꿀 때는 현가계수를 쓴다. 연금의 내가계수와 현가계수는 서로 역수가 아니다."}},{"i":"S4-1-1-학개론-22","r":"S4","g":1,"c":1,"n":22,"s":"학개론","q":"부동산투자의 현금흐름 추정에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["순영업소득은 가능총소득에서 공실손실상당액과 불량부채액을 차감하고 기타 수입을 더한 소득이다.","영업경비에는 광고비와 수선비 외에 감가상각비와 부채서비스액이 포함된다.","세후현금흐름은 세전현금흐름에서 감가상각비를 차감한 소득이다.","세전지분복귀액은 부동산 매도가격에서 매도경비와 미상환 저당잔금을 차감한 금액이다.","세후지분복귀액은 세전지분복귀액에서 영업소득세를 차감한 금액이다."],"a":[4],"L":"학5-3","o":"변형","x":{"한줄":"세전지분복귀액은 매도가격에서 매도경비를 뺀 순매도액에서 미상환 저당잔금을 차감해 구한다.","근거":[{"이론":"투자부동산의 현금흐름 추정","내용":"가능총소득 − 공실·불량부채 + 기타 수입 = 유효총소득, 유효총소득 − 영업경비 = 순영업소득, 순영업소득 − 부채서비스액 = 세전현금흐름, 세전현금흐름 − 영업소득세 = 세후현금흐름. 처분 시점에는 순매도액 − 미상환 저당잔금 = 세전지분복귀액, 세전지분복귀액 − 자본이득세 = 세후지분복귀액."}],"선지":[{"번호":1,"판정":"틀림","설명":"가능총소득에서 공실·불량부채를 빼고 기타 수입을 더한 값은 유효총소득이다. 순영업소득은 유효총소득에서 영업경비를 뺀 값이다."},{"번호":2,"판정":"틀림","설명":"영업경비는 광고비, 수선비, 재산세, 보험료처럼 운영에 드는 경비다. 감가상각비와 부채서비스액(원금·이자)은 영업경비에서 제외한다."},{"번호":3,"판정":"틀림","설명":"세전현금흐름에서 차감하는 항목은 영업소득세다. 감가상각비는 현금이 나가지 않는 비용이라 현금흐름에서 빼지 않고, 영업소득세 계산 때 소득에서 공제한다."},{"번호":4,"판정":"옳음","설명":"순매도액(매도가격 − 매도경비)에서 미상환 저당잔금을 차감한 금액이 세전지분복귀액이다. 지분투자자 몫으로 돌아오는 금액이다."},{"번호":5,"판정":"틀림","설명":"세후지분복귀액은 세전지분복귀액에서 자본이득세(양도소득세)를 차감한 금액이다. 영업소득세는 보유 기간 중 영업소득에 붙는 세금이다."}],"개념":[{"종류":"흐름","제목":"부동산 투자 현금흐름 산정 순서","단계":[{"이름":"가능총소득","설명":"단위면적당 추정 임대료 × 임대면적"},{"이름":"유효총소득","설명":"가능총소득 − 공실손실상당액·불량부채액 + 기타 수입"},{"이름":"순영업소득","설명":"유효총소득 − 영업경비 (감가상각비·부채서비스액·소득세는 영업경비가 아님)"},{"이름":"세전현금흐름","설명":"순영업소득 − 부채서비스액(원금상환액 + 이자)"},{"이름":"세후현금흐름","설명":"세전현금흐름 − 영업소득세"},{"이름":"지분복귀액(처분 시)","설명":"세전지분복귀액 = 매도가격 − 매도경비 − 미상환 저당잔금, 세후지분복귀액 = 세전지분복귀액 − 자본이득세"}]},{"종류":"표","제목":"영업경비 포함 항목과 제외 항목","머리":["구분","항목","이유"],"행":[["포함","재산세, 보험료","자산 보유·운영에 드는 경비"],["포함","수선유지비, 관리비","건물 운영에 직접 필요한 경비"],["포함","광고비, 전기·수도료","임대 영업과 직접 관련"],["제외","감가상각비","현금 지출이 없는 회계상 비용, 세금 계산에서만 공제"],["제외","부채서비스액(원금·이자)","자금 조달 비용이라 세전현금흐름 단계에서 차감"],["제외","영업소득세","세후현금흐름 단계에서 차감"]]}],"함정":"⑤에서 영업소득세와 자본이득세를 혼동하기 쉽다. 영업소득세는 운영 기간 소득에 붙고 세후현금흐름에서 차감한다. 처분 때 생기는 자본이득세는 지분복귀액에서 차감한다. ③은 감가상각비를 현금 지출처럼 빼서 틀린 선지가 된다."}},{"i":"S4-1-1-학개론-23","r":"S4","g":1,"c":1,"n":23,"s":"학개론","q":"부동산 투자분석기법에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부동산 투자분석기법 중 화폐의 시간가치를 고려한 방법에는 순현재가치법, 내부수익률법, 회계적이익률법이 있다.","내부수익률이란 순현가를 '1'로 만드는 할인율이고, 기대수익률은 순현가를 '0'으로 만드는 할인율이다.","어림셈법 중 순소득승수법의 경우 승수값이 작을수록 자본회수기간이 길어진다.","순현가법에서는 재투자율로 시장수익률을 사용하고, 내부수익률법에서는 요구수익률을 사용한다.","내부수익률법에서는 내부수익률이 요구수익률보다 작은 경우 해당 투자안을 선택하지 않는다."],"a":[5],"L":"학5-3","o":"기출","x":{"한줄":"내부수익률이 요구수익률보다 작으면 투자안의 수익이 요구수준에 못 미치므로 채택하지 않는다.","근거":[{"이론":"내부수익률법의 채택 기준","내용":"내부수익률(IRR)은 순현재가치를 0으로 만드는 할인율이다. IRR > 요구수익률이면 채택하고, IRR < 요구수익률이면 기각한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"회계적이익률법은 화폐의 시간가치를 고려하지 않는다. 시간가치를 고려하는 방법은 순현재가치법, 내부수익률법, 수익성지수법이다."},{"번호":2,"판정":"틀림","설명":"내부수익률은 순현가를 0으로 만드는 할인율이다. 순현가를 1로 만드는 할인율이라는 설명이 틀리고, 기대수익률이 순현가를 0으로 만든다는 설명도 맞지 않는다."},{"번호":3,"판정":"틀림","설명":"순소득승수 = 총투자액 ÷ 순영업소득이다. 승수가 작을수록 투자액을 회수하는 기간이 짧다."},{"번호":4,"판정":"틀림","설명":"순현가법의 재투자율은 요구수익률이고 내부수익률법의 재투자율은 내부수익률이다. 선지는 반대로 서술했다."},{"번호":5,"판정":"옳음","설명":"IRR이 요구수익률보다 작으면 순현가가 0보다 작아지므로 투자안을 선택하지 않는다."}],"개념":[{"종류":"표","제목":"투자분석기법 비교","머리":["기법","시간가치","채택 기준","재투자율 가정"],"행":[["순현재가치법(NPV)","고려","NPV > 0 (유입 현가 > 유출 현가)","요구수익률"],["내부수익률법(IRR)","고려","IRR > 요구수익률","내부수익률"],["수익성지수법(PI)","고려","PI > 1 (유입 현가 ÷ 유출 현가)","요구수익률"],["회수기간법","고려 안 함","회수기간이 짧은 안","해당 없음"],["회계적이익률법","고려 안 함","평균 회계이익률이 높은 안","해당 없음"]]},{"종류":"비교","제목":"NPV법과 IRR법","왼쪽":{"이름":"순현재가치법","항목":["금액(절대값)으로 표시","가치가산원리가 성립해 여러 투자안의 NPV를 합산할 수 있음","재투자율은 요구수익률","NPV를 0으로 만드는 할인율이 IRR"]},"오른쪽":{"이름":"내부수익률법","항목":["비율(%)로 표시","가치가산원리가 성립하지 않음","재투자율은 내부수익률","IRR을 구하려면 NPV = 0 방정식을 풀어야 함"]}}],"함정":"④는 재투자율을 반대로 짝지어 틀린다. ① 회계적이익률법은 이름에 이익률이 있어도 시간가치를 고려하지 않는 방법이다. ③ 순소득승수는 작을수록 회수가 빠르다."}},{"i":"S4-1-1-학개론-24","r":"S4","g":1,"c":1,"n":24,"s":"학개론","q":"다음 자료를 이용하여 산정한 연간 순영업소득은? (단, 연간 기준이며, 주어진 조건에 한함)","b":"○ 임대면적: 2,000m²\n○ 임대면적 m²당 연 임대료: 10만원\n○ 공실손실상당액 및 불량부채액: 가능총소득의 10%\n○ 주차장 수입 등 기타 수입: 1,000만원\n○ 영업경비: 수선유지비 2,000만원, 재산세 1,000만원, 광고비 500만원, 전기·수도료 1,500만원\n○ 감가상각비: 3,000만원\n○ 대출 원리금 상환액: 4,000만원","bs":"글자","img":[],"ch":["7,000만원","1억원","1억 1,000만원","1억 3,000만원","1억 4,000만원"],"a":[5],"L":"학5-3","o":"변형","x":{"한줄":"가능총소득 2억원에서 공실·불량부채 2,000만원을 빼고 기타 수입 1,000만원을 더한 유효총소득 1억 9,000만원에서 영업경비 5,000만원을 빼면 1억 4,000만원이다.","근거":[{"이론":"순영업소득","내용":"순영업소득 = 유효총소득 − 영업경비. 유효총소득 = 가능총소득 − 공실·불량부채 + 기타 수입. 감가상각비와 부채서비스액은 영업경비가 아니다."}],"선지":[{"번호":1,"판정":"-","설명":"순영업소득에서 감가상각비 3,000만원과 대출 원리금 4,000만원을 모두 빼서 7,000만원이 된 값이다."},{"번호":2,"판정":"-","설명":"대출 원리금 4,000만원을 뺀 1억원은 세전현금흐름이다."},{"번호":3,"판정":"-","설명":"감가상각비 3,000만원을 영업경비로 넣어 뺀 값이다."},{"번호":4,"판정":"-","설명":"기타 수입 1,000만원을 더하지 않고 계산한 값이다. 유효총소득이 1억 8,000만원이 되어 순영업소득 1억 3,000만원이 나온다."},{"번호":5,"판정":"-","설명":"2,000m² × 10만원 = 2억원, 2억원 − 2,000만원 + 1,000만원 = 1억 9,000만원, 1억 9,000만원 − 5,000만원 = 1억 4,000만원이다."}],"개념":[{"종류":"계산","제목":"순영업소득 산정","단계":[{"설명":"가능총소득","식":"임대면적 × m²당 임대료 = 2,000m² × 10만원","값":"2억원"},{"설명":"공실손실상당액·불량부채액","식":"가능총소득 × 10%","값":"2,000만원"},{"설명":"유효총소득","식":"가능총소득 − 공실·불량부채 + 기타 수입 = 2억원 − 2,000만원 + 1,000만원","값":"1억 9,000만원"},{"설명":"영업경비","식":"수선유지비 + 재산세 + 광고비 + 전기·수도료 = 2,000 + 1,000 + 500 + 1,500","값":"5,000만원"},{"설명":"순영업소득","식":"유효총소득 − 영업경비 = 1억 9,000만원 − 5,000만원","값":"1억 4,000만원"}]},{"종류":"표","제목":"자료 항목별 처리 위치","머리":["자료 항목","반영하는 단계","순영업소득 계산에 쓰는가"],"행":[["공실손실상당액·불량부채액","유효총소득 계산에서 차감","쓴다"],["기타 수입(주차장 등)","유효총소득 계산에서 가산","쓴다"],["영업경비 4항목","순영업소득 계산에서 차감","쓴다"],["감가상각비","영업소득세 계산에서 소득공제","쓰지 않는다"],["대출 원리금 상환액","세전현금흐름 계산에서 차감 (1억 4,000만원 − 4,000만원 = 1억원)","쓰지 않는다"]]}],"함정":"자료에 나온 숫자를 전부 쓰려는 데서 틀린다. 감가상각비와 대출 원리금은 순영업소득을 구할 때 쓰지 않는다. 대출 원리금을 빼면 세전현금흐름 1억원(②)이 된다. 기타 수입을 빠뜨리면 ④가 된다."}},{"i":"S4-1-1-학개론-25","r":"S4","g":1,"c":1,"n":25,"s":"학개론","q":"甲은 A은행에서 주택을 담보로 5,000만원을 대출받은 상태이다. 甲이 A은행에서 동일한 주택을 담보로 받을 수 있는 추가대출의 최대금액은? (단, 제시된 두 가지 대출승인기준을 모두 충족하여야 하며, 주어진 조건에 한함)","b":"○ 담보주택의 시장가치: 4억원\n○ 연소득: 7,000만원\n○ 연간 저당상수: 0.2\n○ 대출승인기준\n  - 담보인정비율(LTV): 60% 이하\n  - 총부채상환비율(DTI): 40% 이하","bs":"글자","img":[],"ch":["2,800만원","9,000만원","1억 4,000만원","1억 9,000만원","2억 4,000만원"],"a":[2],"L":"학6-1","o":"기출","x":{"한줄":"DTI 기준 총 대출한도 1억 4,000만원이 LTV 기준 한도 2억 4,000만원보다 작으므로 총 한도는 1억 4,000만원이고, 기존 대출 5,000만원을 빼면 추가대출 최대금액은 9,000만원이다.","근거":[{"이론":"LTV·DTI에 의한 대출한도","내용":"LTV 한도 = 담보가치 × LTV, DTI 한도(대출금액) = 연소득 × DTI ÷ 저당상수. 두 기준을 모두 충족해야 하므로 작은 쪽이 총 한도이고, 기존 대출을 뺀 금액이 추가대출 한도다."}],"선지":[{"번호":1,"판정":"-","설명":"7,000만원 × 40% = 2,800만원은 연간 원리금 상환 한도다. 저당상수로 나누기 전의 값이라 대출금액이 아니다."},{"번호":2,"판정":"-","설명":"총 한도 min(2억 4,000만원, 1억 4,000만원) = 1억 4,000만원에서 기존 대출 5,000만원을 뺀 9,000만원이다."},{"번호":3,"판정":"-","설명":"DTI 기준 총 한도이며 기존 대출 5,000만원을 빼지 않았다."},{"번호":4,"판정":"-","설명":"LTV 기준 추가대출액(2억 4,000만원 − 5,000만원)이다. DTI 기준을 반영하지 않았다."},{"번호":5,"판정":"-","설명":"LTV 기준 총 한도이며 DTI도 기존 대출도 반영하지 않았다."}],"개념":[{"종류":"계산","제목":"추가대출 최대금액","단계":[{"설명":"DTI 기준 연간 원리금 한도","식":"연소득 × DTI = 7,000만원 × 40%","값":"2,800만원"},{"설명":"DTI 기준 총 대출한도","식":"연간 원리금 한도 ÷ 저당상수 = 2,800만원 ÷ 0.2","값":"1억 4,000만원"},{"설명":"LTV 기준 총 대출한도","식":"담보가치 × LTV = 4억원 × 60%","값":"2억 4,000만원"},{"설명":"총 대출한도","식":"두 기준을 모두 충족 → 작은 값","값":"1억 4,000만원"},{"설명":"추가대출 최대금액","식":"총 한도 − 기존 대출 = 1억 4,000만원 − 5,000만원","값":"9,000만원"}]},{"종류":"표","제목":"LTV·DTI·DSR 비교","머리":["구분","계산식","높을수록","과열기 정책 방향"],"행":[["LTV(담보인정비율)","대출금액 ÷ 담보가치","대출 가능액이 커지고 자기자본 비율은 낮아짐","낮춰서 대출 억제"],["DTI(총부채상환비율)","해당 주택담보대출 연간 원리금 ÷ 연소득 (기타 대출은 이자만 합산)","연소득 대비 상환 부담이 커짐","낮춰서 대출 억제"],["DSR(총부채원리금상환비율)","모든 대출의 연간 원리금 ÷ 연소득","전체 부채 상환 부담이 커짐","낮춰서 대출 억제"],["침체기 정책 방향","LTV·DTI를 높여 대출 확대","주택 수요 증가","-"]]}],"함정":"저당상수를 곱해야 하는지 나눠야 하는지 헷갈리면 ①을 고르게 된다. 연간 원리금 한도를 대출금액으로 바꿀 때는 저당상수로 나눈다. 둘 중 작은 값을 쓰지 않고 LTV 한도만 보면 ④·⑤가 나온다."}},{"i":"S4-1-1-학개론-26","r":"S4","g":1,"c":1,"n":26,"s":"학개론","q":"甲은 은행으로부터 다음 조건으로 대출을 받았다. 이에 관한 설명으로 옳은 것은? (단, 만원 미만은 반올림하며, 주어진 조건에 한함)","b":"○ 대출금액: 2,100만원\n○ 연 이자율: 10% (고정금리)\n○ 대출기간: 2년\n○ 상환방식: 원리금균등상환, 매년 말 상환\n○ 2년, 10%의 저당상수: 0.5762","bs":"글자","img":[],"ch":["매년 말 상환할 원리금은 1,210만원이다.","1회차에 상환하는 원금은 1,100만원이다.","1회차 상환 직후 대출잔액은 1,000만원이다.","2년간 납부하는 이자 합계는 420만원이다.","2회차에 납부하는 이자는 210만원이다."],"a":[1],"L":"학6-1","o":"신작","x":{"한줄":"원리금균등상환액은 대출액 × 저당상수 = 2,100만원 × 0.5762 ≈ 1,210만원이다.","근거":[{"이론":"원리금균등상환","내용":"매기 원리금 = 대출액 × 저당상수. 이자는 직전 잔액 × 이자율이고, 원금상환액 = 원리금 − 이자이므로 회차가 지날수록 원금상환액이 늘어난다."}],"선지":[{"번호":1,"판정":"옳음","설명":"2,100만원 × 0.5762 = 1,210.02만원, 반올림하면 1,210만원이다."},{"번호":2,"판정":"틀림","설명":"1회차 이자는 2,100 × 10% = 210만원이고, 원금은 1,210 − 210 = 1,000만원이다."},{"번호":3,"판정":"틀림","설명":"1회차에 원금 1,000만원을 갚았으므로 잔액은 2,100 − 1,000 = 1,100만원이다."},{"번호":4,"판정":"틀림","설명":"이자는 1회차 210만원, 2회차 110만원으로 합계 320만원이다. 420만원은 이자 210만원을 두 번 더한 값이다."},{"번호":5,"판정":"틀림","설명":"2회차 이자는 1회차 상환 후 잔액 1,100만원의 10%인 110만원이다."}],"개념":[{"종류":"계산","제목":"원리금균등상환 상환표","단계":[{"설명":"매기 원리금","식":"대출액 × 저당상수 = 2,100만원 × 0.5762","값":"1,210만원"},{"설명":"1회차 이자","식":"대출액 × 이자율 = 2,100만원 × 10%","값":"210만원"},{"설명":"1회차 원금상환액과 잔액","식":"원리금 − 이자 = 1,210 − 210 → 잔액 2,100 − 1,000","값":"원금 1,000만원, 잔액 1,100만원"},{"설명":"2회차 이자와 원금","식":"1,100만원 × 10% = 110만원, 1,210 − 110","값":"이자 110만원, 원금 1,100만원 (잔액 0)"},{"설명":"이자 합계","식":"210 + 110 (= 1,210 × 2 − 2,100)","값":"320만원"}]},{"종류":"표","제목":"대출 상환방식 비교","머리":["구분","매기 원리금","매기 원금상환액","총이자"],"행":[["원금균등","점점 감소","일정 (대출액 ÷ 기간)","가장 적음"],["원리금균등","일정","점점 증가","원금균등보다 많음"],["체증식","점점 증가","초기에는 이자에도 못 미쳐 잔액이 늘 수 있음","원리금균등보다 많음"],["만기일시","만기까지 이자만 납부","만기에 전액","가장 많음"]]}],"함정":"원리금균등상환에서는 원리금이 일정하고 원금상환액이 늘어난다. 1회차 원금상환액 1,000만원과 잔액 1,100만원을 서로 바꿔 쓰거나(②·③), 2회차 이자를 최초 대출액 기준으로 계산하면(④·⑤) 틀린다. 이자는 매번 직전 잔액에 이자율을 곱한다."}},{"i":"S4-1-1-학개론-27","r":"S4","g":1,"c":1,"n":27,"s":"학개론","q":"주택연금(주택담보노후연금) 관련 법령상 주택연금의 보증기관은?","b":null,"bs":"없음","img":[],"ch":["한국부동산원","신용보증기금","주택도시보증공사","한국토지주택공사","한국주택금융공사"],"a":[5],"L":"학6-2","o":"기출","x":{"한줄":"주택담보노후연금보증은 한국주택금융공사가 하는 업무로 한국주택금융공사법에 규정되어 있다.","근거":[{"법령":"한국주택금융공사법","조문":"제1조","원문":"이 법은 한국주택금융공사를 설립하여 주택저당채권 등의 유동화(流動化)와 주택금융 신용보증 및 주택담보노후연금보증 업무를 수행하게 함으로써 주택금융 등의 장기적ㆍ안정적 공급을 촉진하여 국민의 복지증진과 국민경제의 발전에 이바지함을 목적으로 한다."},{"법령":"한국주택금융공사법","조문":"제22조제1항제9호","원문":"공사는 다음 각 호의 업무를 수행한다. … 9. 주택담보노후연금보증"},{"법령":"한국주택금융공사법","조문":"제2조제8호의2","원문":"\"주택담보노후연금보증\"이란 주택소유자가 주택에 저당권 설정 또는 주택소유자와 공사가 체결하는 신탁계약(주택소유자 또는 주택소유자의 배우자를 수익자로 하되, 공사를 공동수익자로 하는 계약을 말한다)에 따른 신탁을 등기하고 금융기관으로부터 대통령령으로 정하는 연금 방식으로 노후생활자금을 대출받음으로써 부담하는 금전채무를 공사가 계정의 부담으로 보증하는 행위를 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한국부동산원은 표준주택가격과 공동주택가격의 조사·산정을 의뢰받는 기관이다(부동산 가격공시에 관한 법률 제16조제4항, 제18조제6항). 주택연금 보증기관이 아니다."},{"번호":2,"판정":"틀림","설명":"주택담보노후연금보증을 수행하는 주체는 한국주택금융공사로 법에 정해져 있다(한국주택금융공사법 제22조제1항제9호). 신용보증기금은 보증기관이 아니다."},{"번호":3,"판정":"틀림","설명":"주택도시보증공사는 주택분양보증 등을 하는 기관이다. 주택연금의 보증기관은 아니다."},{"번호":4,"판정":"틀림","설명":"한국토지주택공사는 택지 개발과 공공주택 공급을 하는 기관이다. 주택연금 보증 업무는 법에 없다."},{"번호":5,"판정":"옳음","설명":"주택소유자가 금융기관에서 연금 방식으로 대출받는 채무를 공사가 보증한다(한국주택금융공사법 제2조제8호의2). 보증기관은 한국주택금융공사다."}],"개념":[{"종류":"흐름","제목":"주택담보노후연금보증 성립부터 이행까지","단계":[{"이름":"설명","설명":"공사는 보증을 받으려는 사람에게 연금 지급액·변제시기, 저당권 설정 또는 신탁 등기, 채권 행사 범위, 설정 제한, 보증료를 설명한다(제43조의2제1항)"},{"이름":"담보 등기","설명":"담보로 제공하는 주택에 공사를 저당권자로 하는 등기 또는 공사를 공동수익자로 하는 신탁 등기를 한다(제43조의2제2항)"},{"이름":"보증 결정 통지","설명":"공사가 보증하기로 결정하면 보증받는 사람과 채권자가 될 자에게 각각 통지한다(제43조의2제3항)"},{"이름":"채권채무관계 성립","설명":"통지일부터 60일 이내에 주된 채권채무관계가 성립하지 않으면 보증관계는 성립하지 않는다(제43조의2제4항·제5항)"},{"이름":"보증채무 이행","설명":"보증받은 사람의 사망 등 사유가 생기면 금융기관이 공사에 보증채무 이행을 청구하고, 공사는 지체 없이 이행한다(제43조의3)"},{"이름":"채권 행사 범위","설명":"연금채권과 구상권은 담보주택에 대해서만 행사한다. 조세채권·임금채권 등 예외 항목만 채무자의 다른 재산에도 행사한다(제43조의4)"}]},{"종류":"표","제목":"주택담보노후연금보증 관련 법 규정","머리":["항목","내용","조문"],"행":[["보증 주체","한국주택금융공사","제2조제8호의2, 제22조제1항제9호"],["연금 수급권 보호","연금을 받을 권리는 양도·압류하거나 담보로 제공할 수 없다","제43조의6제1항"],["담보주택 제한","저당권·가등기담보권 설정, 전세권 설정, 임대를 하여서는 안 된다(대통령령으로 정하는 경우 제외)","제43조의7제1항"],["초기보증료","담보주택 가격에 2% 이하의 범위에서 대통령령으로 정하는 요율을 곱한 금액","제43조의8제1항"],["보증료","보증금액에 연 2% 이하의 범위에서 대통령령으로 정하는 요율을 곱한 금액","제43조의8제2항"]]}],"함정":"한국부동산원(가격공시), 주택도시보증공사(분양·전세 보증), 한국토지주택공사(택지·공공주택)는 각각 하는 일이 달라 보증기관 후보로 자주 나온다. 주택연금은 공사가 보증하고 금융기관이 연금을 지급한다. 지급 주체와 보증 주체를 구별한다."}},{"i":"S4-1-1-학개론-28","r":"S4","g":1,"c":1,"n":28,"s":"학개론","q":"저당담보부증권(MBS) 도입에 따른 부동산시장의 효과에 관한 설명으로 옳은 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["저당채권이 유동화되면 1차 저당시장 대출기관의 유동성이 줄어들어 주택자금 대출 규모가 축소된다.","2차 저당시장에서 저당채권이 거래되면 1차 저당시장의 대출금리는 상승한다.","대출기관은 보유한 저당채권을 유동화하여 회수한 자금으로 새로운 주택담보대출을 할 수 있다.","MBS 발행으로 주택구입 자금을 융자받기 쉬워지면 자가소유가구의 비중은 감소한다.","저당채권이 증권으로 발행되면 투자자는 소액으로 투자할 수 없게 되어 투자기회가 축소된다."],"a":[3],"L":"학6-2","o":"변형","x":{"한줄":"대출기관이 저당채권을 팔아 자금을 회수하면 그 자금으로 신규 주택담보대출을 늘릴 수 있다.","근거":[{"법령":"한국주택금융공사법","조문":"제2조제5호","원문":"\"주택저당증권\"이란 공사가 주택저당채권을 기초로 하여 발행하는 수익증권을 말한다."},{"법령":"한국주택금융공사법","조문":"제22조제1항제1호","원문":"공사는 다음 각 호의 업무를 수행한다. 1. 채권유동화"},{"이론":"저당유동화의 시장 효과","내용":"1차 시장 대출기관은 저당채권을 2차 시장에 팔아 자금을 회수하므로 대출 재원이 늘고, 대출금리 하락·융자 확대·주택구입능력 향상으로 이어진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유동화로 대출기관이 자금을 회수하므로 유동성이 늘고 대출 재원이 커진다."},{"번호":2,"판정":"틀림","설명":"대출 재원이 늘어 1차 시장의 대출금리에는 하락 압력이 생긴다."},{"번호":3,"판정":"옳음","설명":"저당채권을 유동화하면 자금이 회수되어 같은 자본으로 대출을 되풀이할 수 있다."},{"번호":4,"판정":"틀림","설명":"융자 접근성이 높아지면 주택구입능력이 커져 자가소유가구의 비중은 증가하는 방향이다."},{"번호":5,"판정":"틀림","설명":"증권화는 저당채권을 잘게 나눠 소액 투자자도 투자할 수 있게 한다. 투자기회가 넓어진다."}],"개념":[{"종류":"흐름","제목":"저당유동화 구조 (MBS 발행)","단계":[{"이름":"1차 저당시장","설명":"차주가 은행 등 대출기관에서 주택담보대출을 받고 원리금을 상환한다"},{"이름":"저당채권 양도","설명":"대출기관이 보유한 주택저당채권을 유동화기관(한국주택금융공사 등)에 양도하고 자금을 회수한다"},{"이름":"증권 발행","설명":"유동화기관이 저당채권을 기초로 주택저당증권(MBS)을 발행해 투자자에게 판다"},{"이름":"원리금 지급","설명":"차주의 원리금이 유동화기관을 거쳐 투자자에게 지급된다"},{"이름":"재대출","설명":"회수한 자금으로 대출기관이 다시 주택담보대출을 한다"}]},{"종류":"표","제목":"MBS의 종류","머리":["구분","성격","저당채권 소유와 장부 처리"],"행":[["MPTS(지분이전증권)","지분형. 원리금이 투자자에게 그대로 이전된다","저당채권이 투자자에게 넘어가고 발행자 대차대조표에서 제외"],["MBB(저당담보부채권)","채권형. 한국주택금융공사법상 공사가 주택저당채권을 담보로 발행하는 채권","저당채권을 발행자가 보유하고 대차대조표에 남는다"],["MPTB(원리금이체채권)","MPTS와 MBB의 혼합형","저당채권은 발행자 소유, 원리금은 투자자에게 이전"],["CMO(다계층증권)","하나의 저당풀을 만기·위험이 다른 여러 트란셰로 나눠 발행","트란셰별로 조기상환 위험과 만기를 달리 배분"]]}],"함정":"MBS의 효과는 대출 재원 확대 → 대출금리 하락·융자 확대 → 주택구입 증가의 방향이다. ①·②·④는 이 방향을 거꾸로 서술해 틀린다. ⑤는 증권화가 소액 투자를 가능하게 한다는 점을 반대로 쓴 선지다."}},{"i":"S4-1-1-학개론-29","r":"S4","g":1,"c":1,"n":29,"s":"학개론","q":"프로젝트 금융(PF)에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["상환재원은 사업주가 이미 운영 중인 사업의 현금흐름과 신용도에 의존한다.","사업이 실패하면 금융기관은 사업주의 다른 재산에 대해서도 전액 상환을 청구할 수 있다.","프로젝트 자금은 시행사가 자체 계좌로 직접 관리하며 금융기관은 인출에 관여하지 않는다.","프로젝트회사의 차입금은 사업주의 재무상태표에 부채로 계상되므로 사업주의 부채비율이 반드시 높아진다.","해당 프로젝트에서 장래 생길 현금흐름과 사업 자산을 담보로 자금을 조달하며, 비소구 또는 제한적 소구의 성격을 가진다."],"a":[5],"L":"학6-3","o":"변형","x":{"한줄":"프로젝트 금융은 사업주의 신용이 아니라 프로젝트의 미래 현금흐름과 사업 자산을 담보로 하고, 비소구 또는 제한적 소구 금융이다.","근거":[{"이론":"프로젝트 금융(PF)","내용":"특정 프로젝트의 미래 현금흐름과 사업 자산을 담보로 별도의 프로젝트회사(SPC)에 자금을 대출하는 금융기법이다. 비소구 또는 제한적 소구이며 자금은 금융기관이 통제하는 계좌로 관리한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기업금융의 설명이다. 프로젝트 금융의 상환재원은 해당 프로젝트에서 나오는 현금흐름이다."},{"번호":2,"판정":"틀림","설명":"비소구 또는 제한적 소구 금융이다. 사업이 실패해도 사업주의 다른 재산에 대한 청구는 계약으로 정한 범위에 한정된다."},{"번호":3,"판정":"틀림","설명":"프로젝트 자금은 금융기관이 관리하는 별도 계좌(에스크로 계좌)로 들어오고, 인출은 금융기관이 통제한다."},{"번호":4,"판정":"틀림","설명":"별도 프로젝트회사가 차입하므로 사업주의 재무상태표에 나타나지 않는 부외금융 효과가 있을 수 있다."},{"번호":5,"판정":"옳음","설명":"프로젝트 금융은 프로젝트 자체의 미래 현금흐름과 자산에 기대는 비소구·제한적 소구 금융이다."}],"개념":[{"종류":"비교","제목":"프로젝트 금융과 기업금융","왼쪽":{"이름":"프로젝트 금융(PF)","항목":["상환재원: 해당 프로젝트의 미래 현금흐름","담보: 프로젝트 자산과 사업권","차주: 별도 설립한 프로젝트회사(SPC)","비소구 또는 제한적 소구","자금관리: 금융기관이 통제하는 계좌","사업주의 재무상태표에 나타나지 않는 부외금융 효과 가능","기업대출보다 금리가 높은 편"]},"오른쪽":{"이름":"기업금융(기업대출)","항목":["상환재원: 기업 전체의 현금흐름과 신용","담보: 기업 보유 자산","차주: 기업 자신","소구 금융","자금은 기업이 자체 계좌로 운용","차입금이 기업 재무상태표에 부채로 계상","프로젝트 금융보다 금리가 낮은 편"]}},{"종류":"표","제목":"부동산투자회사(리츠)의 유형","머리":["유형","정의","조문"],"행":[["자기관리 부동산투자회사","자산운용 전문인력을 포함한 임직원을 상근으로 두고 자산의 투자·운용을 직접 수행하는 회사","부동산투자회사법 제2조제1호가목"],["위탁관리 부동산투자회사","자산의 투자·운용을 자산관리회사에 위탁하는 회사","제2조제1호나목"],["기업구조조정 부동산투자회사","제49조의2제1항 각 호의 부동산을 투자 대상으로 하며 투자·운용을 자산관리회사에 위탁하는 회사","제2조제1호다목"],["자산관리회사","위탁관리·기업구조조정 부동산투자회사의 위탁을 받아 투자·운용 업무를 수행하는 회사","제2조제5호"]]}],"함정":"금융기관이 사업주의 다른 재산까지 쫓을 수 있다고 쓴 선지(②)와 사업주 신용이 상환재원이라는 선지(①)는 기업금융의 특징이다. 프로젝트 금융은 자금 인출을 금융기관이 통제하는 점도 구별 포인트다."}},{"i":"S4-1-1-학개론-30","r":"S4","g":1,"c":1,"n":30,"s":"학개론","q":"부동산개발에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산개발사업 진행시 행정의 변화에 따른 사업의 인ㆍ허가 지연위험은 사업시행자가 스스로 관리할 수 없는 위험이다.","공영(공공)개발은 공공성과 공익성을 위해 택지를 조성한 후 분양 또는 임대하는 토지개발방식을 말한다.","환지방식은 택지가 개발되기 전 토지의 위치ㆍ지목ㆍ면적 등을 고려하여 택지개발 후 개발된 토지를 토지소유자에게 재분배하는 방식을 말한다.","부동산개발은 미래의 불확실한 수익을 근거로 개발을 진행하기 때문에 위험성이 수반된다.","흡수율분석은 재무적 사업타당성분석에서 사용했던 주요 변수들의 투입 값을 낙관적, 비관적 상황으로 적용하여 수익성을 예측하는 것을 말한다."],"a":[5],"L":"학7-1","o":"기출","x":{"한줄":"⑤는 민감도분석의 설명이다. 흡수율분석은 시장성 분석에서 시장이 새 공급을 흡수하는 속도와 비율을 분석하는 방법이다.","근거":[{"이론":"흡수율분석과 민감도분석","내용":"흡수율분석은 시장성 분석의 도구로 일정 기간 동안 시장에서 분양·임대되는 면적(호수)의 비율을 분석한다. 민감도분석은 재무적 타당성 분석의 투입변수를 낙관적·비관적 상황으로 바꿔 수익성의 변화를 보는 방법이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"행정 변화에 따른 인·허가 지연은 사업시행자가 스스로 관리할 수 없는 위험이다. 시장위험, 공사 중 문화재 발굴 등도 같다."},{"번호":2,"판정":"옳음","설명":"공영(공공)개발은 공공성·공익성을 위해 공공이 택지를 조성한 뒤 분양 또는 임대하는 방식이다."},{"번호":3,"판정":"옳음","설명":"환지방식은 개발 전 토지의 위치·지목·면적 등을 고려해 개발 후 토지를 소유자에게 재분배한다."},{"번호":4,"판정":"옳음","설명":"개발은 미래의 불확실한 수익을 근거로 하므로 위험이 따른다."},{"번호":5,"판정":"틀림","설명":"투입 값을 낙관적·비관적으로 바꿔 수익성을 예측하는 방법은 민감도분석이다. 흡수율분석은 시장성 분석 단계에서 쓴다."}],"개념":[{"종류":"표","제목":"부동산 분석 5단계","머리":["단계","내용","핵심 도구·포인트"],"행":[["지역경제 분석","도시 전체의 기본 수요","인구·고용·소득"],["시장 분석","특정 유형 부동산의 수요·공급","시장지역 설정부터"],["시장성 분석","대상 부동산이 매매·임대될 가능성","흡수율분석"],["타당성 분석","법률적·기술적·경제적 타당성, 경제적 타당성이 중심","민감도분석(낙관·비관·기대 값)"],["투자 분석","여러 대안 중 최종 선택","타당성이 있다고 모두 채택하지 않음"]]},{"종류":"비교","제목":"흡수율분석과 민감도분석","왼쪽":{"이름":"흡수율분석","항목":["시장성 분석 단계에서 사용","시장에서 공급이 흡수되는 속도·비율을 분석","과거 흡수 추세로 분양·임대 기간을 예측"]},"오른쪽":{"이름":"민감도분석","항목":["재무적 타당성 분석 단계에서 사용","임대료·공실률·이자율 등 투입 변수를 낙관적·비관적으로 바꿈","변수 변화에 따른 수익성 변동을 측정"]}}],"함정":"분석 이름이 비슷해 단계를 섞기 쉽다. 시장성 분석에는 흡수율분석, 타당성 분석에는 민감도분석이 대응한다. 선지 ①의 통제 불가 위험은 시장위험·인허가 지연·문화재 발굴이고, 부실공사는 통제할 수 있는 위험이다."}},{"i":"S4-1-1-학개론-31","r":"S4","g":1,"c":1,"n":31,"s":"학개론","q":"다음 설명에 해당하는 민간투자사업 방식을 순서대로 나열한 것은?","b":"ㄱ. 시설 준공과 동시에 소유권이 국가 또는 지방자치단체에 귀속되고, 사업시행자가 일정 기간 시설을 운영하여 이용자가 내는 사용료로 투자비를 회수한다.\nㄴ. 시설 준공과 동시에 소유권이 국가 또는 지방자치단체에 귀속되고, 국가 등이 그 시설을 임차하여 사용하면서 사업시행자에게 임대료를 지급한다.\nㄷ. 시설 준공 후 일정 기간 사업시행자가 소유권을 가지고 직접 운영하며, 그 기간이 끝나면 소유권을 국가 또는 지방자치단체에 이전한다.","bs":"글자","img":[],"ch":["ㄱ: BTL, ㄴ: BTO, ㄷ: BOT","ㄱ: BTO, ㄴ: BTL, ㄷ: BOO","ㄱ: BOT, ㄴ: BTO, ㄷ: BTL","ㄱ: BTO, ㄴ: BTL, ㄷ: BOT","ㄱ: BTO, ㄴ: BOT, ㄷ: BTL"],"a":[4],"L":"학7-1","o":"신작","x":{"한줄":"준공 즉시 국가 귀속이면 BTO 또는 BTL이고, 사용료로 회수하면 BTO, 임대료를 받으면 BTL이다. 준공 후 민간이 소유하다가 기간이 끝나 이전하면 BOT다.","근거":[{"이론":"민간투자사업 방식","내용":"BTO: 준공 후 소유권 이전, 민간이 운영하며 이용자 사용료로 회수. BTL: 준공 후 소유권 이전, 국가 등이 임차해 임대료 지급. BOT: 준공 후 민간이 소유·운영하다가 기간 종료 시 이전. BOO: 민간이 소유·운영하고 이전하지 않음."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 사용료 회수이므로 BTO이고 ㄴ은 임대료 지급이므로 BTL이다. ㄱ과 ㄴ이 서로 바뀌었다."},{"번호":2,"판정":"-","설명":"ㄷ은 기간 종료 후 소유권을 이전하므로 BOO가 아니라 BOT다. BOO는 이전 없이 민간이 계속 소유한다."},{"번호":3,"판정":"-","설명":"ㄱ·ㄴ은 준공 즉시 국가에 귀속되는 BTO·BTL이고, ㄷ은 BOT다. 세 항목 모두 틀리게 짝지었다."},{"번호":4,"판정":"-","설명":"ㄱ은 BTO, ㄴ은 BTL, ㄷ은 BOT로 모두 맞다."},{"번호":5,"판정":"-","설명":"ㄴ은 준공 즉시 국가에 귀속되고 임대료를 받는 BTL이며, ㄷ은 BOT다. ㄴ과 ㄷ이 틀렸다."}],"개념":[{"종류":"표","제목":"민간투자사업 방식 비교","머리":["구분","BTO","BTL","BOT","BOO","BLT"],"행":[["준공 시 소유권","국가 등","국가 등","민간","민간","민간"],["기간 중 운영·회수","민간이 운영하며 이용자 사용료로 회수","민간이 운영하고 국가 등이 임차해 임대료 지급","민간이 소유·운영","민간이 소유·운영","민간이 소유하며 임대"],["기간 종료 후","이미 국가 소유","이미 국가 소유","국가 등에 이전","이전 없음","국가 등에 이전"]]},{"종류":"비교","제목":"수용방식과 환지방식","왼쪽":{"이름":"수용(매수)방식","항목":["사업구역의 토지를 전부 매수해 개발","사업 속도는 빠르나 보상비·사업비 부담이 큼","보상금이 대토 수요로 이어져 구역 밖 지가가 오를 수 있음"]},"오른쪽":{"이름":"환지방식","항목":["개발 전 권리를 개발 후 토지로 재분배","소유자 동의 등 절차가 복잡","개발이익이 종전 소유자에게 돌아감"]}}],"함정":"BTO와 BTL은 둘 다 준공 즉시 국가 소유다. 기간 중 투자비를 이용자에게서 거두면 BTO, 국가에게서 임대료로 받으면 BTL이다. 이름 순서(Build 뒤에 Transfer가 바로 오는가)를 외우면 구별된다."}},{"i":"S4-1-1-학개론-32","r":"S4","g":1,"c":1,"n":32,"s":"학개론","q":"민간임대주택에 관한 특별법령상 주택임대관리업에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["위탁관리형 주택임대관리업은 주택의 소유자로부터 수수료를 받고 임대료 부과·징수 및 시설물 유지·관리 등을 대행하는 형태의 업이다.","자기관리형 주택임대관리업으로 등록한 자가 위탁관리형 주택임대관리업을 하려면 따로 등록하여야 한다.","위탁관리형 주택임대관리업을 하는 주택임대관리업자도 임대인 및 임차인의 권리보호를 위한 보증상품에 가입하여야 한다.","주택임대관리업자가 수행하는 임차인의 입주 및 명도·퇴거 등의 업무에는 공인중개사법상 중개업이 포함된다.","임대료의 부과·징수 업무는 주택임대관리업자가 부수적으로 수행할 수 있는 업무이다."],"a":[1],"L":"학7-2","o":"변형","x":{"한줄":"위탁관리형은 소유자에게서 수수료를 받고 임대료 부과·징수와 시설물 유지·관리 등을 대행하는 형태의 업이다.","근거":[{"법령":"민간임대주택에 관한 특별법","조문":"제2조제10호","원문":"\"주택임대관리업\"이란 주택의 소유자로부터 임대관리를 위탁받아 관리하는 업(業)을 말하며, 다음 각 목으로 구분한다. 가. 자기관리형 주택임대관리업: 주택의 소유자로부터 주택을 임차하여 자기책임으로 전대(轉貸)하는 형태의 업 나. 위탁관리형 주택임대관리업: 주택의 소유자로부터 수수료를 받고 임대료 부과ㆍ징수 및 시설물 유지ㆍ관리 등을 대행하는 형태의 업"},{"법령":"민간임대주택에 관한 특별법","조문":"제7조제2항","원문":"제1항에 따라 등록하는 경우에는 자기관리형 주택임대관리업과 위탁관리형 주택임대관리업을 구분하여 등록하여야 한다. 이 경우 자기관리형 주택임대관리업을 등록한 경우에는 위탁관리형 주택임대관리업도 등록한 것으로 본다."},{"법령":"민간임대주택에 관한 특별법","조문":"제11조","원문":"① 주택임대관리업자는 임대를 목적으로 하는 주택에 대하여 다음 각 호의 업무를 수행한다. 1. 임대차계약의 체결ㆍ해제ㆍ해지ㆍ갱신 및 갱신거절 등 2. 임대료의 부과ㆍ징수 등 3. 임차인의 입주 및 명도ㆍ퇴거 등(「공인중개사법」 제2조제3호에 따른 중개업은 제외한다) ② 주택임대관리업자는 임대를 목적으로 하는 주택에 대하여 부수적으로 다음 각 호의 업무를 수행할 수 있다. 1. 시설물 유지ㆍ보수ㆍ개량 및 그 밖의 주택관리 업무 2. 그 밖에 임차인의 주거 편익을 위하여 필요하다고 대통령령으로 정하는 업무"},{"법령":"민간임대주택에 관한 특별법","조문":"제14조제1항","원문":"자기관리형 주택임대관리업을 하는 주택임대관리업자는 임대인 및 임차인의 권리보호를 위하여 보증상품에 가입하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제2조제10호나목이 위탁관리형을 이렇게 정의한다."},{"번호":2,"판정":"틀림","설명":"자기관리형으로 등록하면 위탁관리형도 등록한 것으로 본다(법 제7조제2항). 따로 등록할 필요가 없다."},{"번호":3,"판정":"틀림","설명":"보증상품 가입 의무가 있는 업자는 자기관리형 주택임대관리업자뿐이다(법 제14조제1항)."},{"번호":4,"판정":"틀림","설명":"입주 및 명도·퇴거 업무에서 공인중개사법상 중개업은 제외된다(법 제11조제1항제3호)."},{"번호":5,"판정":"틀림","설명":"임대료의 부과·징수는 주택임대관리업자가 수행하는 업무로 법에 정해져 있다(법 제11조제1항제2호). 부수적으로 할 수 있는 업무는 시설물 유지·보수·개량 등이다(같은 조 제2항)."}],"개념":[{"종류":"비교","제목":"자기관리형과 위탁관리형 주택임대관리업","왼쪽":{"이름":"자기관리형","항목":["소유자에게서 주택을 임차해 자기책임으로 전대","등록하면 위탁관리형도 등록한 것으로 봄(법 제7조제2항)","보증상품 가입 의무 있음(법 제14조제1항)","임대사업자인 임대인이 위탁하면 위탁받은 범위에서 임대사업자의 의무를 이행(법 제15조)"]},"오른쪽":{"이름":"위탁관리형","항목":["소유자에게서 수수료를 받고 임대료 부과·징수, 시설물 유지·관리 등을 대행","위탁관리형만 하려면 위탁관리형으로 등록","보증상품 가입 의무는 법에 규정 없음"]}},{"종류":"표","제목":"주택임대관리업자의 업무 (법 제11조)","머리":["업무","구분","조문"],"행":[["임대차계약의 체결·해제·해지·갱신 및 갱신거절 등","수행하는 업무","제11조제1항제1호"],["임대료의 부과·징수 등","수행하는 업무","제11조제1항제2호"],["임차인의 입주 및 명도·퇴거 등 (공인중개사법상 중개업 제외)","수행하는 업무","제11조제1항제3호"],["시설물 유지·보수·개량 및 그 밖의 주택관리 업무","부수적으로 할 수 있는 업무","제11조제2항제1호"],["임차인의 주거 편익에 필요하다고 대통령령으로 정하는 업무 (주거공간 관리, 안전 확보, 입주 지원 등)","부수적으로 할 수 있는 업무","제11조제2항제2호, 시행령 제10조"]]}],"함정":"필수 업무와 부수 업무를 바꿔 쓴 ⑤가 자주 함정이 된다. 보증상품은 자기관리형만 가입한다(③). 시설물 유지·보수를 위탁관리형의 핵심 업무로만 외우면 임대료 징수가 필수 업무인 점을 놓친다."}},{"i":"S4-1-1-학개론-33","r":"S4","g":1,"c":1,"n":33,"s":"학개론","q":"부동산관리와 임대차에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["자기관리방식은 소유자의 직접 통제가 쉽고 관리업무의 기밀 유지에 유리하지만, 관리의 전문성이 낮을 수 있다.","위탁관리방식은 관리업무를 전문업체에 맡기므로 소유자의 직접 통제력이 높아지고 기밀 유지에 유리하다.","혼합관리방식은 관리업무 중 필요한 부분만 외부 전문업체에 맡기고 나머지는 소유자가 직접 수행하는 방식이다.","비율임대차는 임대료를 임차인 매출액의 일정 비율로 정하는 방식이어서 임대료가 임차인의 영업실적에 따라 달라진다.","순임대차는 임차인이 임대료 외에 재산세·보험료·유지수선비 등 건물 운영비용을 부담하는 방식이다."],"a":[2],"L":"학7-2","o":"변형","x":{"한줄":"위탁관리방식은 전문업체가 관리를 맡으므로 소유자의 직접 통제력이 약해지고 업무 기밀 유지도 어렵다.","근거":[{"이론":"부동산관리 방식","내용":"자기관리는 소유자가 직접 수행해 통제·기밀 유지에 유리하고 전문성이 낮다. 위탁관리는 전문업체를 이용해 전문성·효율성이 높고 소유자의 통제가 약하며 기밀 유지가 어렵다. 혼합관리는 일부 업무만 위탁한다."},{"이론":"임대차 유형","내용":"총임대차는 임대인이 운영경비를 부담하고, 순임대차는 임차인이 운영경비를 부담한다. 비율임대차는 임대료를 임차인 매출액의 일정 비율로 정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소유자가 직접 관리하므로 통제와 기밀 유지에는 유리하지만 전문업체보다 전문성은 낮을 수 있다."},{"번호":2,"판정":"틀림","설명":"위탁관리는 전문성은 높아지지만 소유자의 통제력이 약해지고 기밀 유지가 어렵다. 통제력과 기밀 유지에 유리한 방식은 자기관리다."},{"번호":3,"판정":"옳음","설명":"혼합관리는 자기관리와 위탁관리를 병용한다. 업무 일부(예: 설비·청소)만 위탁하는 형태다."},{"번호":4,"판정":"옳음","설명":"비율임대차는 매출액에 연동해 임대료를 정하므로 임차인 영업실적에 따라 임대료가 변한다. 주로 상업용 부동산에서 쓴다."},{"번호":5,"판정":"옳음","설명":"순임대차에서는 임차인이 순임대료 외에 재산세·보험료·유지수선비 등 운영비용을 부담한다."}],"개념":[{"종류":"표","제목":"부동산관리 방식 비교","머리":["구분","자기관리","위탁관리","혼합관리"],"행":[["수행 주체","소유자 직접","전문 관리업체","일부만 위탁"],["소유자 통제력","강함","약함","중간"],["기밀 유지","유리","어려움","부분적으로 유리"],["전문성·효율성","낮을 수 있음","높음","위탁한 업무는 높음"]]},{"종류":"표","제목":"임대차 유형 비교","머리":["유형","임대료 구성","운영경비 부담","특징"],"행":[["총임대차","운영경비를 포함한 임대료","임대인","경비가 오르는 위험을 임대인이 진다"],["순임대차","순임대료에 운영경비를 별도로 더함","임차인","경비가 오르는 위험이 임차인에게 넘어간다"],["비율임대차","임차인 매출액의 일정 비율","계약으로 정함","임차인의 매출이 늘면 임대인도 이익을 나눈다"],["조정(수정)임대차","총임대차와 순임대차의 중간 형태","임대인·임차인이 나눔","경비 일부를 임차인에게 넘긴다"]]}],"함정":"위탁관리의 장점(전문성)과 자기관리의 장점(통제·기밀 유지)을 서로 바꿔 쓰는 선지가 단골이다. ②는 위탁관리에 자기관리의 장점을 붙여 틀린다. 순임대차와 총임대차의 경비 부담 주체도 서로 반대다."}},{"i":"S4-1-1-학개론-34","r":"S4","g":1,"c":1,"n":34,"s":"학개론","q":"감정평가 과정상 지역분석 및 개별분석에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["동일수급권(同一需給圈)이란 대상부동산과 대체ㆍ경쟁관계가 성립하고 가치 형성에 서로 영향을 미치는 관계에 있는 다른 부동산이 존재하는 권역(圈域)을 말하며, 인근지역과 유사지역을 포함한다.","지역분석이란 대상부동산이 속해 있는 지역의 지역요인을 분석하여 대상부동산의 최유효이용을 판정하는 것을 말한다.","인근지역이란 대상부동산이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 개별요인을 공유하는 지역을 말한다.","개별분석이란 대상부동산의 개별적 요인을 분석하여 해당 지역 내 부동산의 표준적 이용과 가격수준을 판정하는 것을 말한다.","지역분석보다 개별분석을 먼저 실시하는 것이 일반적이다."],"a":[1],"L":"학8-1","o":"기출","x":{"한줄":"동일수급권은 대상부동산과 대체·경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 다른 부동산이 존재하는 권역이며, 인근지역과 유사지역을 포함한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제15호","원문":"\"동일수급권(同一需給圈)\"이란 대상부동산과 대체ㆍ경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 관계에 있는 다른 부동산이 존재하는 권역(圈域)을 말하며, 인근지역과 유사지역을 포함한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제13호","원문":"\"인근지역\"이란 감정평가의 대상이 된 부동산(이하 \"대상부동산\"이라 한다)이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제14호","원문":"\"유사지역\"이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"동일수급권의 정의 그대로이며 인근지역과 유사지역을 포함한다(규칙 제2조제15호)."},{"번호":2,"판정":"틀림","설명":"지역분석은 지역요인을 분석해 그 지역의 표준적 이용과 가격수준을 판정하는 것이다. 대상부동산의 최유효이용을 판정하는 것은 개별분석이다."},{"번호":3,"판정":"틀림","설명":"인근지역은 가치형성요인 중 개별요인이 아니라 지역요인을 공유하는 지역이다(규칙 제2조제13호)."},{"번호":4,"판정":"틀림","설명":"개별분석은 대상부동산의 개별요인을 분석해 최유효이용을 판정한다. 표준적 이용과 가격수준의 판정은 지역분석이다."},{"번호":5,"판정":"틀림","설명":"지역분석을 먼저 하고 그 결과를 바탕으로 개별분석을 한다."}],"개념":[{"종류":"비교","제목":"지역분석과 개별분석","왼쪽":{"이름":"지역분석","항목":["분석 대상: 대상부동산이 속한 지역","분석 요인: 일반요인·지역요인","판정 내용: 지역의 표준적 이용과 가격수준","순서: 먼저 실시","범위: 거시적·전체적"]},"오른쪽":{"이름":"개별분석","항목":["분석 대상: 대상부동산 자체","분석 요인: 개별요인","판정 내용: 대상부동산의 최유효이용과 구체적 가격","순서: 지역분석 다음","범위: 미시적·개별적"]}},{"종류":"표","제목":"인근지역·유사지역·동일수급권","머리":["용어","정의 요지","조문"],"행":[["인근지역","대상부동산이 속한 지역으로서 이용이 동질적이고 지역요인을 공유하는 지역","규칙 제2조제13호"],["유사지역","대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역","규칙 제2조제14호"],["동일수급권","대체·경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 부동산이 존재하는 권역. 인근지역과 유사지역을 포함","규칙 제2조제15호"],["비교표준지 선정 순서","인근지역의 표준지를 먼저 고르고, 적절한 표준지가 없으면 동일수급권 안 유사지역의 표준지를 고름","규칙 제14조제2항제1호"]]}],"함정":"③에서 인근지역은 지역요인을 공유하는 지역인데 개별요인으로 바꿔 쓴다. ②와 ④는 지역분석의 결과(표준적 이용·가격수준)와 개별분석의 결과(최유효이용)를 서로 바꿔 썼다. 분석은 지역분석이 먼저다."}},{"i":"S4-1-1-학개론-35","r":"S4","g":1,"c":1,"n":35,"s":"학개론","q":"다음 자료를 이용하여 원가법으로 산정한 대상 건물의 적산가액은? (단, 감가수정은 정액법에 의하며, 주어진 조건에 한함)","b":"○ 건물 연면적: 200m²\n○ 기준시점 현재 재조달원가: m²당 150만원\n○ 사용승인일부터 기준시점까지의 경과연수: 10년\n○ 기준시점 현재 잔존 경제적 내용연수: 40년\n○ 내용연수 만료 시 잔존가치율: 10%","bs":"글자","img":[],"ch":["2억 1,000만원","2억 4,000만원","2억 4,600만원","2억 7,000만원","2억 9,400만원"],"a":[3],"L":"학8-2","o":"신작","x":{"한줄":"재조달원가 3억원에서 정액법 감가누계액 5,400만원을 빼면 2억 4,600만원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"\"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제12호","원문":"\"감가수정\"이란 대상물건에 대한 재조달원가를 감액하여야 할 요인이 있는 경우에 물리적 감가, 기능적 감가 또는 경제적 감가 등을 고려하여 그에 해당하는 금액을 재조달원가에서 공제하여 기준시점에 있어서의 대상물건의 가액을 적정화하는 작업을 말한다."},{"이론":"정액법","내용":"감가누계액 = (재조달원가 − 잔존가치) × 경과연수 ÷ 경제적 내용연수. 경제적 내용연수는 경과연수와 잔존 경제적 내용연수의 합이다."}],"선지":[{"번호":1,"판정":"-","설명":"감가누계액에 잔존가치(3,000만원)를 한 번 더 뺀 값이다. 3억원 − 6,000만원 − 3,000만원 = 2억 1,000만원."},{"번호":2,"판정":"-","설명":"잔존가치를 반영하지 않고 3억원 × 10/50 = 6,000만원만 뺀 값이다."},{"번호":3,"판정":"-","설명":"(3억원 − 3,000만원) × 10/50 = 5,400만원을 빼면 2억 4,600만원이다."},{"번호":4,"판정":"-","설명":"경과연수 비율을 곱하지 않고 재조달원가의 10%인 3,000만원만 감가한 값이다."},{"번호":5,"판정":"-","설명":"감가 대상 금액을 잔존가치 3,000만원으로 보고 10/50을 곱한 600만원만 뺀 값이다."}],"개념":[{"종류":"계산","제목":"정액법에 의한 적산가액","단계":[{"설명":"재조달원가","식":"연면적 × m²당 재조달원가 = 200m² × 150만원","값":"3억원"},{"설명":"경제적 내용연수","식":"경과연수 + 잔존 경제적 내용연수 = 10년 + 40년","값":"50년"},{"설명":"잔존가치","식":"재조달원가 × 잔존가치율 = 3억원 × 10%","값":"3,000만원"},{"설명":"감가누계액","식":"(재조달원가 − 잔존가치) × 경과연수 ÷ 경제적 내용연수 = 2억 7,000만원 × 10/50","값":"5,400만원"},{"설명":"적산가액","식":"재조달원가 − 감가누계액 = 3억원 − 5,400만원","값":"2억 4,600만원"}]},{"종류":"표","제목":"감가수정 방법 비교","머리":["구분","정액법","정률법","상환기금법"],"행":[["감가 방식","매년 감가액이 일정","매년 감가율이 일정, 감가액은 해마다 줄어듦","감채기금계수로 적립하며 이자 포함"],["첫해 감가액","중간","가장 큼","가장 작음"],["같은 조건의 적산가액","중간","가장 작음","가장 큼"],["어울리는 대상","건물 등 일반 자산","기계·설비처럼 초기 감가가 큰 자산","-"]]}],"함정":"경제적 내용연수를 잔존 경제적 내용연수 40년으로 그대로 쓰면 6,750만원이 감가되어 2억 3,250만원이 나와 답이 달라진다. 경과연수와 잔존연수를 더한 50년을 분모로 쓴다. 잔존가치는 감가 대상에서 제외한다."}},{"i":"S4-1-1-학개론-36","r":"S4","g":1,"c":1,"n":36,"s":"학개론","q":"다음 자료를 이용하여 거래사례비교법으로 산정한 대상토지의 비준가액은? (단, 주어진 조건에 한함)","b":"○ 대상토지: 면적 100m²\n○ 거래사례: 대상토지와 같은 인근지역에 있는 토지로, 거래가격은 m²당 500만원\n○ 거래사례는 정상적인 가격보다 25% 높게 거래된 것으로 판단됨\n○ 거래시점부터 기준시점까지 지가가 5% 하락함\n○ 개별요인: 대상토지가 거래사례보다 10% 열세","bs":"글자","img":[],"ch":["3억 4,200만원","3억 6,000만원","3억 8,000만원","4억 2,750만원","5억원"],"a":[1],"L":"학8-2","o":"신작","x":{"한줄":"사례가격 500만원에 사정보정 0.8, 시점수정 0.95, 지역요인 1.00, 개별요인 0.9를 곱한 m²당 342만원에 면적 100m²를 곱한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제7호","원문":"\"거래사례비교법\"이란 대상물건과 가치형성요인이 같거나 비슷한 물건의 거래사례와 비교하여 대상물건의 현황에 맞게 사정보정(事情補正), 시점수정, 가치형성요인 비교 등의 과정을 거쳐 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"이론":"비준가액의 산정","내용":"비준가액 = 사례가격 × 사정보정치 × 시점수정치 × 지역요인 비교치 × 개별요인 비교치 × 면적 비교치. 사정보정치 = 정상가격 ÷ 사례가격이고, 비교치는 대상 ÷ 사례로 구한다."}],"선지":[{"번호":1,"판정":"-","설명":"500만원 × 0.8 × 0.95 × 1.00 × 0.9 = 342만원, 342만원 × 100m² = 3억 4,200만원이다."},{"번호":2,"판정":"-","설명":"시점수정(0.95)을 빠뜨린 값이다. 500 × 0.8 × 0.9 × 100 = 3억 6,000만원."},{"번호":3,"판정":"-","설명":"개별요인 비교(0.9)를 빠뜨린 값이다. 500 × 0.8 × 0.95 × 100 = 3억 8,000만원."},{"번호":4,"판정":"-","설명":"사정보정(0.8)을 빠뜨린 값이다. 500 × 0.95 × 0.9 × 100 = 4억 2,750만원."},{"번호":5,"판정":"-","설명":"보정을 하나도 하지 않고 사례가격 500만원에 면적만 곱한 값이다."}],"개념":[{"종류":"계산","제목":"거래사례비교법 비준가액","단계":[{"설명":"사정보정치","식":"정상가격 ÷ 사례가격 = 100 ÷ 125","값":"0.8"},{"설명":"시점수정치","식":"1 + 지가변동률 = 1 − 0.05","값":"0.95"},{"설명":"지역요인 비교치","식":"같은 인근지역이므로","값":"1.00"},{"설명":"개별요인 비교치","식":"대상 ÷ 사례 = 90 ÷ 100","값":"0.9"},{"설명":"m²당 비준가격","식":"500만원 × 0.8 × 0.95 × 1.00 × 0.9","값":"342만원"},{"설명":"비준가액","식":"342만원 × 대상토지 면적 100m²","값":"3억 4,200만원"}]},{"종류":"흐름","제목":"거래사례비교법 적용 순서","단계":[{"이름":"사례 선정","설명":"사정보정·시점수정이 가능하고, 대상과 지역요인·개별요인을 비교할 수 있는 정상적인 사례를 고른다"},{"이름":"사정보정","설명":"사례에 낀 특수 사정을 정상 가격으로 되돌린다 (정상가격 ÷ 사례가격)"},{"이름":"시점수정","설명":"거래시점의 가격수준을 기준시점의 가격수준으로 바꾼다 (1 + 지가변동률)"},{"이름":"가치형성요인 비교","설명":"지역요인과 개별요인을 대상 ÷ 사례로 비교한다. 인근지역이면 지역요인은 1.00"},{"이름":"비준가액 결정","설명":"보정·수정·비교한 값을 곱하고 면적을 반영한다"}]}],"함정":"분모와 분자를 거꾸로 쓰기 쉽다. 사례가 고가 거래이면 사정보정치는 1보다 작은 100/125이고, 대상이 열세이면 개별요인 비교치도 1보다 작다. 지가가 하락하면 시점수정치가 1보다 작아진다. 보정을 빠뜨린 값들이 ②~⑤로 제시된다."}},{"i":"S4-1-1-학개론-37","r":"S4","g":1,"c":1,"n":37,"s":"학개론","q":"다음 자료를 이용하여 직접환원법으로 산정한 대상부동산의 수익가액은? (단, 순영업소득은 매년 동일하게 영구히 발생하며, 주어진 조건에 한함)","b":"○ 순영업소득: 연 6,000만원\n○ 자금조달: 저당대출 50%, 자기자본(지분) 50%\n○ 저당상수: 0.08\n○ 지분환원율: 12%","bs":"글자","img":[],"ch":["5억원","6억원","7억 5,000만원","10억원","15억원"],"a":[2],"L":"학8-2","o":"신작","x":{"한줄":"저당·지분 투자결합법으로 구한 종합환원율은 0.5 × 0.08 + 0.5 × 0.12 = 10%이고, 수익가액은 6,000만원 ÷ 0.10 = 6억원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제10호","원문":"\"수익환원법(收益還元法)\"이란 대상물건이 장래 산출할 것으로 기대되는 순수익이나 미래의 현금흐름을 환원하거나 할인하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"이론":"금융적 투자결합법","내용":"종합환원율 = 저당비율 × 저당상수 + 지분비율 × 지분환원율. 수익가액 = 순영업소득 ÷ 종합환원율."}],"선지":[{"번호":1,"판정":"-","설명":"지분환원율 12%만 적용한 값이다. 6,000만원 ÷ 0.12 = 5억원."},{"번호":2,"판정":"-","설명":"종합환원율 0.10으로 나눈 6억원이다."},{"번호":3,"판정":"-","설명":"저당상수 8%만 적용한 값이다. 6,000만원 ÷ 0.08 = 7억 5,000만원."},{"번호":4,"판정":"-","설명":"지분 몫 0.5 × 0.12 = 0.06만 환원율로 쓴 값이다. 6,000만원 ÷ 0.06 = 10억원."},{"번호":5,"판정":"-","설명":"저당 몫 0.5 × 0.08 = 0.04만 환원율로 쓴 값이다. 6,000만원 ÷ 0.04 = 15억원."}],"개념":[{"종류":"계산","제목":"직접환원법 수익가액","단계":[{"설명":"저당 부분의 환원율","식":"저당비율 × 저당상수 = 0.5 × 0.08","값":"0.04"},{"설명":"지분 부분의 환원율","식":"지분비율 × 지분환원율 = 0.5 × 0.12","값":"0.06"},{"설명":"종합환원율","식":"저당 부분 + 지분 부분 = 0.04 + 0.06","값":"0.10"},{"설명":"수익가액","식":"순영업소득 ÷ 종합환원율 = 6,000만원 ÷ 0.10","값":"6억원"}]},{"종류":"표","제목":"환원율을 구하는 방법","머리":["방법","내용"],"행":[["시장추출법","유사 부동산의 순수익과 거래가격에서 환원율을 뽑는다"],["조성법","무위험률에 위험률(유동성·관리 난이도 등)을 더해 구성한다"],["투자결합법(물리적)","토지환원율과 건물환원율을 가치 비율로 가중평균한다"],["투자결합법(금융적)","저당상수와 지분환원율을 자금조달 비율로 가중평균한다"],["엘우드법","보유기간 중 지분수익과 가치 변동을 반영해 구한다"],["부채감당법","환원율 = 부채감당률 × 저당비율 × 저당상수"]]}],"함정":"종합환원율은 각 비율을 곱해 더한 값이다. 저당 몫이나 지분 몫만 환원율로 쓰면 ④·⑤가 나오고, 한쪽 환원율만 쓰면 ①·③이 나온다. 수익가액은 순영업소득을 환원율로 나눈다."}},{"i":"S4-1-1-학개론-38","r":"S4","g":1,"c":1,"n":38,"s":"학개론","q":"감정평가에 관한 규칙상 용어 정의로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["기준시점이란 감정평가를 의뢰받은 날짜를 말한다.","원가법이란 대상물건의 재조달원가에 시점수정을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다.","인근지역이란 대상부동산이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다.","수익분석법이란 대상물건이 장래 산출할 것으로 기대되는 순수익이나 미래의 현금흐름을 환원하거나 할인하여 대상물건의 가액을 산정하는 감정평가방법을 말한다.","유사지역이란 대상부동산이 속한 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다."],"a":[3],"L":"학8-3","o":"변형","x":{"한줄":"인근지역은 대상부동산이 속한 지역으로서 이용이 동질적이고 지역요인을 공유하는 지역이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제13호","원문":"\"인근지역\"이란 감정평가의 대상이 된 부동산(이하 \"대상부동산\"이라 한다)이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제2호","원문":"\"기준시점\"이란 대상물건의 감정평가액을 결정하는 기준이 되는 날짜를 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"\"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제11호","원문":"\"수익분석법\"이란 일반기업 경영에 의하여 산출된 총수익을 분석하여 대상물건이 일정한 기간에 산출할 것으로 기대되는 순수익에 대상물건을 계속하여 임대하는 데에 필요한 경비를 더하여 대상물건의 임대료를 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제14호","원문":"\"유사지역\"이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기준시점은 대상물건의 감정평가액을 결정하는 기준이 되는 날짜다(규칙 제2조제2호). 기준시점은 원칙적으로 대상물건의 가격조사를 완료한 날짜다(규칙 제9조제2항)."},{"번호":2,"판정":"틀림","설명":"원가법은 재조달원가에 감가수정을 하는 방법이다(규칙 제2조제5호). 시점수정은 거래사례비교법과 공시지가기준법의 과정이다."},{"번호":3,"판정":"옳음","설명":"규칙 제2조제13호의 정의 그대로다."},{"번호":4,"판정":"틀림","설명":"서술된 내용은 수익환원법의 정의다(규칙 제2조제10호). 수익분석법은 총수익을 분석해 순수익에 필요경비를 더해 임대료를 산정한다(같은 조 제11호)."},{"번호":5,"판정":"틀림","설명":"유사지역은 대상부동산이 속하지 아니하는 지역이다(규칙 제2조제14호). 속한 지역은 인근지역이다."}],"개념":[{"종류":"표","제목":"용어 정의 요지 (규칙 제2조)","머리":["용어","정의 요지","호"],"행":[["기준시점","감정평가액을 결정하는 기준이 되는 날짜","제2호"],["원가법","재조달원가에 감가수정을 하여 가액을 산정","제5호"],["적산법","기초가액 × 기대이율 = 기대수익에 계속 임대하는 데 필요한 경비를 더해 임대료를 산정","제6호"],["수익환원법","장래 순수익이나 미래의 현금흐름을 환원 또는 할인해 가액을 산정","제10호"],["수익분석법","총수익을 분석해 얻은 순수익에 필요경비를 더해 임대료를 산정","제11호"],["감가수정","재조달원가를 감액할 요인을 고려해 해당 금액을 재조달원가에서 공제","제12호"]]},{"종류":"표","제목":"3방식 6방법 (규칙 제11조)","머리":["방식(원리)","가액을 구하는 방법","임대료를 구하는 방법"],"행":[["원가방식(비용성)","원가법","적산법"],["비교방식(시장성)","거래사례비교법, 공시지가기준법","임대사례비교법"],["수익방식(수익성)","수익환원법","수익분석법"]]}],"함정":"비슷한 용어를 정의 문장과 바꿔 붙인 선지가 나온다. ④는 수익환원법의 정의를 수익분석법에 붙였고, ②는 감가수정 자리에 시점수정을 넣었다. 가액을 구하는 방법과 임대료를 구하는 방법의 짝(원가법↔적산법, 거래사례↔임대사례, 수익환원↔수익분석)을 함께 외운다."}},{"i":"S4-1-1-학개론-39","r":"S4","g":1,"c":1,"n":39,"s":"학개론","q":"감정평가에 관한 규칙상 대상물건과 주된 감정평가방법의 연결로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과수원 − 수익환원법","건설기계 − 거래사례비교법","광업재단 − 원가법","영업권 − 수익환원법","비상장채권 − 거래사례비교법"],"a":[4],"L":"학8-3","o":"변형","x":{"한줄":"영업권을 비롯한 무형자산은 수익환원법을 적용한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제23조제3항","원문":"감정평가법인등은 영업권, 특허권, 실용신안권, 디자인권, 상표권, 저작권, 전용측선이용권(專用側線利用權), 그 밖의 무형자산을 감정평가할 때에 수익환원법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제18조","원문":"감정평가법인등은 과수원을 감정평가할 때에 거래사례비교법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제20조제2항","원문":"감정평가법인등은 건설기계를 감정평가할 때에 원가법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제19조제2항","원문":"감정평가법인등은 광업재단을 감정평가할 때에 수익환원법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제24조제2항제2호","원문":"비상장채권(거래소에서 거래가 이루어지지 아니하는 등 형성된 시세가 없는 채권을 말한다): 수익환원법을 적용할 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"과수원은 거래사례비교법을 적용한다(규칙 제18조)."},{"번호":2,"판정":"틀림","설명":"건설기계는 원가법을 적용한다(규칙 제20조제2항)."},{"번호":3,"판정":"틀림","설명":"광업재단은 수익환원법을 적용한다(규칙 제19조제2항)."},{"번호":4,"판정":"옳음","설명":"영업권 등 무형자산은 수익환원법이다(규칙 제23조제3항)."},{"번호":5,"판정":"틀림","설명":"비상장채권은 수익환원법이고, 상장채권이 거래사례비교법이다(규칙 제24조제2항)."}],"개념":[{"종류":"표","제목":"대상물건별 주된 감정평가방법 (규칙 제14조~제24조)","머리":["대상물건","주된 방법","조문"],"행":[["토지","공시지가기준법 (적정한 실거래가 기준이면 거래사례비교법)","제14조제1항·제3항"],["건물","원가법","제15조제1항"],["토지와 건물 일괄","거래사례비교법","제16조"],["산림","산지와 입목을 구분, 입목은 거래사례비교법(소경목림은 원가법 가능)","제17조제1항"],["과수원","거래사례비교법","제18조"],["공장재단","구성 물건별 감정평가액 합산 (일괄평가 시 수익환원법 가능)","제19조제1항"],["광업재단","수익환원법","제19조제2항"],["자동차","거래사례비교법","제20조제1항"],["건설기계·선박·항공기","원가법 (선박은 선체·기관·의장별로 구분)","제20조제2항~제4항"],["동산","거래사례비교법 (기계·기구류는 원가법)","제21조"],["임대료","임대사례비교법","제22조"],["무형자산(영업권 등)","수익환원법","제23조제3항"],["상장주식·상장채권","거래사례비교법","제24조제1항제1호·제2항제1호"],["비상장채권·기업가치","수익환원법","제24조제2항제2호·제3항"]]}],"함정":"광업재단(수익환원법)과 공장재단(구성 물건 합산)을 혼동하고, 과수원을 토지처럼 공시지가기준법으로 평가하는 것으로 착각한다. 상장 여부에 따라 채권의 방법이 갈린다는 점도 놓치기 쉽다."}},{"i":"S4-1-1-학개론-40","r":"S4","g":1,"c":1,"n":40,"s":"학개론","q":"부동산 가격공시에 관한 법률상 부동산 가격공시에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["표준지공시지가에 이의가 있는 자는 공시일부터 60일 이내에 시장·군수 또는 구청장에게 이의를 신청할 수 있다.","개별공시지가는 국토교통부장관이 중앙부동산가격공시위원회의 심의를 거쳐 결정·공시한다.","공동주택가격은 시장·군수 또는 구청장이 시·군·구부동산가격공시위원회의 심의를 거쳐 공시한다.","국토교통부장관은 비주거용 표준부동산가격을 반드시 공시하여야 한다.","표준주택으로 선정된 단독주택에 대하여는 개별주택가격을 결정·공시하지 아니할 수 있으며, 이 경우 해당 주택의 표준주택가격을 개별주택가격으로 본다."],"a":[5],"L":"학8-4","o":"변형","x":{"한줄":"표준주택으로 선정된 단독주택은 개별주택가격을 결정·공시하지 않을 수 있고, 그 경우 표준주택가격이 개별주택가격으로 간주된다.","근거":[{"법령":"부동산 가격공시에 관한 법률","조문":"제17조제2항","원문":"제1항에도 불구하고 표준주택으로 선정된 단독주택, 그 밖에 대통령령으로 정하는 단독주택에 대하여는 개별주택가격을 결정ㆍ공시하지 아니할 수 있다. 이 경우 표준주택으로 선정된 주택에 대하여는 해당 주택의 표준주택가격을 개별주택가격으로 본다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제7조제1항","원문":"표준지공시지가에 이의가 있는 자는 그 공시일부터 30일 이내에 서면(전자문서를 포함한다. 이하 같다)으로 국토교통부장관에게 이의를 신청할 수 있다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제10조제1항","원문":"시장ㆍ군수 또는 구청장은 국세ㆍ지방세 등 각종 세금의 부과, 그 밖의 다른 법령에서 정하는 목적을 위한 지가산정에 사용되도록 하기 위하여 제25조에 따른 시ㆍ군ㆍ구부동산가격공시위원회의 심의를 거쳐 매년 공시지가의 공시기준일 현재 관할 구역 안의 개별토지의 단위면적당 가격(이하 \"개별공시지가\"라 한다)을 결정ㆍ공시하고, 이를 관계 행정기관 등에 제공하여야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제18조제1항","원문":"국토교통부장관은 공동주택에 대하여 매년 공시기준일 현재의 적정가격(이하 \"공동주택가격\"이라 한다)을 조사ㆍ산정하여 제24조에 따른 중앙부동산가격공시위원회의 심의를 거쳐 공시하고, 이를 관계 행정기관 등에 제공하여야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제20조제1항","원문":"국토교통부장관은 용도지역, 이용상황, 건물구조 등이 일반적으로 유사하다고 인정되는 일단의 비주거용 일반부동산 중에서 선정한 비주거용 표준부동산에 대하여 매년 공시기준일 현재의 적정가격(이하 \"비주거용 표준부동산가격\"이라 한다)을 조사ㆍ산정하고, 제24조에 따른 중앙부동산가격공시위원회의 심의를 거쳐 이를 공시할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"표준지공시지가의 이의신청은 공시일부터 30일 이내에 국토교통부장관에게 한다(법 제7조제1항)."},{"번호":2,"판정":"틀림","설명":"개별공시지가는 시장·군수 또는 구청장이 시·군·구부동산가격공시위원회의 심의를 거쳐 결정·공시한다(법 제10조제1항)."},{"번호":3,"판정":"틀림","설명":"공동주택가격은 국토교통부장관이 중앙부동산가격공시위원회의 심의를 거쳐 공시한다(법 제18조제1항)."},{"번호":4,"판정":"틀림","설명":"비주거용 표준부동산가격은 공시할 수 있다(법 제20조제1항). 공시가 의무인 것은 표준지공시지가·표준주택가격·공동주택가격이다."},{"번호":5,"판정":"옳음","설명":"법 제17조제2항 그대로다."}],"개념":[{"종류":"표","제목":"부동산 가격공시 종류별 비교","머리":["종류","공시 주체","이의신청","공시기준일·공시 기한"],"행":[["표준지공시지가","국토교통부장관 (법 제3조)","공시일부터 30일 이내, 국토교통부장관 (법 제7조)","1월 1일 (시행령 제3조)"],["개별공시지가","시장·군수·구청장 (법 제10조)","결정·공시일부터 30일 이내, 시장·군수·구청장 (법 제11조)","1월 1일, 매년 5월 31일까지 (시행령 제21조)"],["표준주택가격","국토교통부장관 (법 제16조)","30일 이내, 국토교통부장관 (법 제16조제7항, 제7조 준용)","1월 1일 (시행령 제27조)"],["개별주택가격","시장·군수·구청장 (법 제17조)","30일 이내, 시장·군수·구청장 (법 제17조제8항, 제11조 준용)","매년 4월 30일까지 (시행령 제38조)"],["공동주택가격","국토교통부장관 (법 제18조)","30일 이내, 국토교통부장관 (법 제18조제8항, 제7조 준용)","1월 1일, 매년 4월 30일까지 (시행령 제40조·제43조)"],["비주거용 표준부동산가격","국토교통부장관, 공시할 수 있음 (법 제20조)","법 제20조제7항(제7조 준용)","1월 1일 (시행령 제49조)"]]},{"종류":"비교","제목":"표준과 개별 가격의 관계","왼쪽":{"이름":"표준지·표준주택·비주거용 표준부동산","항목":["국토교통부장관이 중앙부동산가격공시위원회 심의를 거쳐 공시","각 개별가격 산정의 기준이 됨","선정된 부동산은 개별가격을 따로 공시하지 않을 수 있고, 표준 가격이 개별 가격으로 간주됨"]},"오른쪽":{"이름":"개별공시지가·개별주택가격·비주거용 개별부동산가격","항목":["시장·군수·구청장이 시·군·구부동산가격공시위원회 심의를 거쳐 결정·공시","가격비준표를 사용해 표준 가격과 균형을 유지하도록 산정","과세 등의 기준으로 활용됨"]}}],"함정":"공시 주체를 바꿔 쓰는 선지가 많다. 개별 가격은 시장·군수·구청장, 공동주택가격은 국토교통부장관이 공시한다. 이의신청 기간은 모두 30일이고, 표준지·표준주택·공동주택의 이의신청은 국토교통부장관에게, 개별공시지가·개별주택가격은 시장·군수·구청장에게 한다."}},{"i":"S4-1-1-민법-01","r":"S4","g":1,"c":1,"n":41,"s":"민법","q":"다음 중 무효인 법률행위는? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 임대인으로서 직접 중개의뢰인과 체결한 주택임대차계약","공인중개사 자격이 없는 자가 우연히 1회성으로 행한 중개행위에 대한 적정한 수준의 수수료 약정","민사사건에서 변호사와 의뢰인 사이에 체결된 적정한 수준의 성공보수약정","매도인이 실수로 상가지역을 그보다 가격이 비싼 상업지역이라 칭하였고, 부동산 거래의 경험이 없는 매수인이 이를 믿고서 실제 가격보다 2배 높은 대금을 지급한 매매계약","보험계약자가 오로지 보험사고를 가장하여 보험금을 취득할 목적으로 선의의 보험자와 체결한 생명보험계약"],"a":[5],"L":"민1-1","o":"기출","x":{"한줄":"보험금을 부정하게 취득할 목적으로 체결한 보험계약은 사회질서에 반하는 내용을 목적으로 하여 제103조에 따라 무효이다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제104조","원문":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."},{"법령":"공인중개사법","조문":"제33조제1항제6호","원문":"중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"판례":"대법원 판례","요지":"보험금을 취득할 목적으로 보험사고를 가장하거나 고의로 일으키려는 보험계약은 사회질서에 반하여 무효이다. 변호사의 성공보수약정은 형사사건에서는 무효이나 민사사건에서 적정한 수준이면 유효하다. 불공정한 법률행위는 궁박·경솔·무경험과 현저한 불균형에 더해 상대방이 이를 알고 이용하려는 의사가 있어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개업공인중개사가 임대인으로서 직접 거래하는 행위는 금지행위(공인중개사법 제33조제1항제6호)이지만 단속규정이라 임대차계약의 사법상 효력은 유효하다."},{"번호":2,"판정":"틀림","설명":"우연히 1회 한 중개행위는 중개업에 해당하지 않아 공인중개사법의 규제를 받지 않고, 적정한 수준의 보수약정은 유효하다."},{"번호":3,"판정":"틀림","설명":"민사사건의 성공보수약정은 적정한 수준이면 유효하다. 무효가 되는 것은 형사사건의 성공보수약정이다."},{"번호":4,"판정":"틀림","설명":"매도인의 실수는 상대방의 궁박·무경험을 알고 이용한 것이 아니므로 불공정한 법률행위(제104조)가 되지 않는다. 매매계약은 유효하다."},{"번호":5,"판정":"옳음","설명":"보험금 취득을 목적으로 보험사고를 가장한 보험계약은 반사회질서의 법률행위로 무효이다(제103조). 보험자가 선의여도 같다."}],"개념":[{"종류":"표","제목":"강행규정 위반의 효과: 효력규정과 단속규정","머리":["구분","의미","대표 예"],"행":[["효력규정","위반하면 사법상 효력도 무효","중개보수 한도 초과 약정(초과 부분), 부동산 명의신탁약정"],["단속규정","위반하면 처벌·제재만 받고 사법상 효력은 유효","개업공인중개사의 직접거래, 무허가 음식점의 판매행위, 중간생략등기 합의"],["판단 기준","규정의 목적, 위반 시 거래 안전에 미치는 영향","입법 취지가 행위의 법률상 효과를 막는 데 있으면 효력규정"],["일부무효","효력규정 위반 시 위반 부분만 무효로 하는 경우가 많음","한도를 넘은 초과 보수만 무효(제137조)"]]},{"종류":"표","제목":"제103조와 제104조 비교","머리":["구분","제103조 반사회질서","제104조 불공정"],"행":[["요건","법률행위의 내용이 사회질서에 반함(동기가 표시되거나 알려진 경우 포함)","궁박·경솔·무경험 + 현저한 불균형 + 상대방의 악용 의사"],["판단 시점","법률행위 성립 시","법률행위 성립 시"],["효과","절대적 무효, 추인해도 유효가 되지 않음","절대적 무효, 추인해도 유효가 되지 않음"],["불법원인급여(제746조)","적용됨","적용되지 않음(판례)"],["무효 예","보험금 부정취득 목적 보험, 허위진술 대가 약정, 형사사건 성공보수","상대방의 무경험을 알고 이용해 시세와 현저히 다른 대금을 받은 매매"]]}],"함정":"선지 4는 대금이 2배라도 매도인의 단순 실수이므로 제104조의 요건(상대방의 악용 의사)이 빠진다. 선지 1의 직접거래는 처벌 대상이어도 계약은 유효하다. 선지 3은 민사 성공보수가 유효하고 형사만 무효이다."}},{"i":"S4-1-1-민법-02","r":"S4","g":1,"c":1,"n":42,"s":"민법","q":"반사회질서의 법률행위에 해당하는 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["법령에서 정한 한도를 초과하는 부동산 중개수수료 약정","강제집행을 면할 목적으로 허위의 근저당권을 설정하는 행위","다수의 보험계약을 통해 보험금을 부정취득할 목적으로 체결한 보험계약","반사회적 행위에 의하여 조성된 비자금을 소극적으로 은닉하기 위한 임치계약","양도소득세를 회피할 목적으로 실제 거래가액보다 낮은 금액을 대금으로 기재한 매매계약"],"a":[3],"L":"민1-1","o":"기출","x":{"한줄":"다수의 보험계약으로 보험금을 부정하게 취득하려는 목적의 보험계약은 사회질서에 반하는 법률행위로 무효이다(제103조).","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제108조제1항","원문":"상대방과 통정한 허위의 의사표시는 무효로 한다."},{"법령":"공인중개사법","조문":"제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한도를 넘는 중개보수 약정은 강행규정(효력규정) 위반으로 초과 부분만 무효가 될 뿐 반사회질서의 법률행위는 아니다."},{"번호":2,"판정":"틀림","설명":"강제집행을 면하려고 상대방과 짜고 허위로 근저당권을 설정하면 통정허위표시로 무효이다(제108조제1항). 반사회질서가 아니라 허위표시로 다룬다."},{"번호":3,"판정":"옳음","설명":"보험금을 부정취득할 목적으로 다수의 보험계약을 체결한 경우 그 보험계약은 사회질서에 반하여 무효이다(제103조)."},{"번호":4,"판정":"틀림","설명":"반사회적 행위로 만든 비자금을 소극적으로 숨겨 두는 임치는 반사회질서에 해당하지 않아 유효하다."},{"번호":5,"판정":"틀림","설명":"양도소득세를 줄이려고 대금을 낮게 기재해도 매매계약 자체는 유효하다. 조세포탈은 별도로 처벌한다."}],"개념":[{"종류":"표","제목":"무효 사유별 비교","머리":["무효 사유","근거","대표 예","선의 제3자 보호"],"행":[["반사회질서","제103조","보험금 부정취득 목적의 보험계약, 이중매매에 적극 가담한 매수","없음(절대적 무효)"],["불공정한 법률행위","제104조","궁박을 알고 이용한 현저히 불균형한 매매","없음(절대적 무효)"],["통정허위표시","제108조","강제집행 면탈용 허위 근저당권, 허위 매매","있음(선의 제3자에게 대항 불가)"],["효력규정 위반","개별 법령","한도를 초과한 중개보수 약정(초과 부분)","개별 사안에 따라 다름"],["유효로 보는 예","-","비자금의 소극적 은닉 임치, 다운계약서식 매매대금 기재","-"]]}],"함정":"허위 근저당권은 제108조의 통정허위표시로 무효가 되고 선의 제3자가 보호된다. 반사회질서 무효에는 이런 보호가 없다. 선지 1은 초과 부분만 무효가 되는 효력규정 위반이다."}},{"i":"S4-1-1-민법-03","r":"S4","g":1,"c":1,"n":43,"s":"민법","q":"甲과 乙은 乙 소유의 X토지를 甲이 매수하기로 합의하고 계약서를 작성하였으나, 계약서에는 乙 소유의 인접한 Y토지로 잘못 기재하였다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["계약서에 Y토지로 기재되어 있으므로 Y토지에 관하여 매매계약이 성립한다.","甲과 乙이 X토지를 매매목적물로 하기로 일치하여 합의하였다면 X토지에 관하여 매매계약이 성립한다.","甲은 乙에게 Y토지의 소유권이전등기를 청구할 수 없다.","甲은 착오를 이유로 취소하지 않고도 대금을 지급하고 X토지의 소유권이전등기를 청구할 수 있다.","乙이 Y토지에 관하여 甲 앞으로 소유권이전등기를 마쳤다면, 그 등기는 매매계약의 뒷받침이 없어 원인 없는 등기이다."],"a":[1],"L":"민1-2","o":"변형","x":{"한줄":"당사자가 목적물에 관하여 일치된 의사를 가졌다면 계약서에 잘못 적힌 표시와 상관없이 일치된 의사대로 계약이 성립한다(오표시 무해). Y토지로 성립한다는 진술이 틀렸다.","근거":[{"이론":"오표시 무해의 원칙","내용":"당사자가 같은 대상을 염두에 두고 합의하였으나 표시를 잘못한 경우, 잘못된 표시에도 불구하고 당사자가 일치하여 의욕한 대상으로 계약이 성립한다(자연적 해석)."},{"법령":"민법","조문":"제109조제1항","원문":"의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다. 그러나 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"계약서의 기재가 아니라 당사자가 일치하여 합의한 X토지로 계약이 성립한다. Y토지에는 합의가 없어 계약이 성립하지 않는다."},{"번호":2,"판정":"옳음","설명":"양 당사자의 의사가 X토지로 일치하므로 계약서 표시와 관계없이 X토지에 관하여 매매계약이 성립한다."},{"번호":3,"판정":"옳음","설명":"Y토지에 관한 합의가 없어 Y토지를 목적으로 한 매매계약이 성립하지 않으므로 등기청구권도 생기지 않는다."},{"번호":4,"판정":"옳음","설명":"일치된 의사가 있으면 표시와 내심의 불일치가 없어 착오 취소가 문제 되지 않는다. 甲은 대금 지급과 맞바꾸어 X토지의 등기를 청구할 수 있다."},{"번호":5,"판정":"옳음","설명":"Y토지에 관한 매매계약이 성립하지 않으므로 Y토지 앞으로 마친 이전등기는 원인이 없어 무효이다."}],"개념":[{"종류":"표","제목":"의사와 표시가 어긋나는 경우의 정리","머리":["유형","의사표시의 효력","취소·무효 주장 제한"],"행":[["비진의표시(제107조)","원칙 유효, 상대방이 알았거나 알 수 있었으면 무효","선의 제3자에게 대항 불가"],["통정허위표시(제108조)","무효","선의 제3자에게 대항 불가"],["착오(제109조)","중요부분의 착오이면 취소 가능","표의자의 중대한 과실이 있으면 취소 불가, 선의 제3자에게 대항 불가"],["사기·강박(제110조)","취소 가능","제3자의 사기·강박은 상대방이 알았거나 알 수 있었을 때만 취소, 선의 제3자에게 대항 불가"],["오표시 무해","일치한 의사대로 성립","착오 문제 자체가 생기지 않음"]]},{"종류":"비교","제목":"착오 취소와 사기 취소","왼쪽":{"이름":"착오(제109조)","항목":["표의자 자신의 잘못된 인식","법률행위 내용의 중요부분에 착오가 있어야 함","표의자에게 중대한 과실이 있으면 취소 불가","선의 제3자에게 취소를 대항하지 못함"]},"오른쪽":{"이름":"사기(제110조)","항목":["타인의 기망행위로 생긴 의사표시","기망행위가 위법하고 고의가 있어야 함","표의자의 과실 여부와 관계없이 취소 가능","제3자가 사기한 경우 상대방이 알았거나 알 수 있었을 때에만 취소 가능"]}}],"함정":"계약서 문언에 묶이면 Y토지로 성립한다고 답하게 된다. 일치된 의사가 있으면 표시 오류는 성립에 영향이 없고, 착오 취소는 의사가 어긋날 때 쓰는 제도이다."}},{"i":"S4-1-1-민법-04","r":"S4","g":1,"c":1,"n":44,"s":"민법","q":"甲의 乙에 대한 의사표시에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲이 부동산 매수청약의 의사표시를 발송한 후 사망하였다면 그 효력은 발생하지 않는다.","乙이 의사표시를 받은 때에 제한능력자이더라도 甲은 원칙적으로 그 의사표시의 효력을 주장할 수 있다.","甲의 의사표시가 乙에게 도달되었다고 보기 위해서는 乙이 그 내용을 알았을 것을 요한다.","甲의 의사표시가 등기우편의 방법으로 발송된 경우, 상당한 기간 내에 도달되었다고 추정할 수 없다.","乙이 정당한 사유 없이 계약해지 통지의 수령을 거절한 경우, 乙이 그 통지의 내용을 알 수 있는 객관적 상태에 놓여 있는 때에 의사표시의 효력이 생긴다."],"a":[5],"L":"민1-2","o":"기출","x":{"한줄":"상대방이 정당한 이유 없이 수령을 거절한 경우에는 그 내용을 알 수 있는 객관적 상태에 놓인 때 의사표시가 도달한 것으로 본다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다.\n② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제112조","원문":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자인 경우에는 의사표시자는 그 의사표시로써 대항할 수 없다. 다만, 그 상대방의 법정대리인이 의사표시가 도달한 사실을 안 후에는 그러하지 아니하다."},{"판례":"대법원 판례","요지":"도달은 상대방이 의사표시의 내용을 알 수 있는 객관적 상태에 놓인 것을 뜻하고 내용을 실제로 알아야 하는 것은 아니다. 등기우편으로 발송된 것이 증명되면 특별한 사정이 없는 한 상당한 기간 내에 도달한 것으로 추정된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"발신 후 표의자가 사망해도 의사표시의 효력에는 영향이 없다(제111조제2항)."},{"번호":2,"판정":"틀림","설명":"상대방이 받을 때 제한능력자이면 의사표시자는 그 의사표시로 대항할 수 없다(제112조). 법정대리인이 도달 사실을 안 뒤에는 대항할 수 있다."},{"번호":3,"판정":"틀림","설명":"도달은 상대방이 알 수 있는 객관적 상태에 놓이면 충분하다. 상대방이 실제로 내용을 알 필요는 없다."},{"번호":4,"판정":"틀림","설명":"등기우편은 발송 사실이 증명되면 상당한 기간 내 도달한 것으로 추정된다."},{"번호":5,"판정":"옳음","설명":"수령을 정당한 이유 없이 거절한 경우에도 상대방이 내용을 알 수 있는 객관적 상태에 놓인 때 효력이 생긴다."}],"개념":[{"종류":"표","제목":"의사표시의 효력발생 정리","머리":["상황","효력","근거"],"행":[["상대방 있는 의사표시","상대방에게 도달한 때(도달주의)","제111조제1항"],["발송 후 표의자의 사망·제한능력","효력에 영향 없음","제111조제2항"],["수령 당시 상대방이 제한능력자","의사표시자는 대항 불가, 법정대리인이 안 뒤에는 가능","제112조"],["수령 거절","알 수 있는 객관적 상태에 놓인 때 도달","판례"],["등기우편 발송","상당한 기간 내 도달 추정","판례"]]},{"종류":"표","제목":"도달주의의 예외(발신주의)","머리":["제도","발신주의가 적용되는 내용","근거"],"행":[["제한능력자 상대방의 확답 촉구","능력자가 된 사람이 기간 내에 확답을 발송하지 않으면 추인한 것으로 봄","제15조"],["사단법인 총회 소집","1주간 전에 목적사항을 적은 통지를 발송","제71조"],["격지자 간 계약의 성립","승낙의 통지를 발송한 때 성립","제531조"]]}],"함정":"도달은 상대방이 내용을 이해한 시점이 아니라 알 수 있는 객관적 상태에 놓인 시점이다. 상대방이 제한능력자일 때는 표의자가 효력을 주장하지 못한다는 점(제112조)이 선지 2의 반대 내용이다."}},{"i":"S4-1-1-민법-05","r":"S4","g":1,"c":1,"n":45,"s":"민법","q":"甲은 자신의 X주택을 임대하기 위하여 乙에게 대리권을 수여하였고, 乙은 甲을 위한 것임을 표시하고 丙과 X주택에 관한 임대차계약을 체결하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 미성년자인 경우 乙의 법정대리인의 동의가 없으면 甲은 乙의 대리행위를 취소할 수 있다.","乙이 丙의 사기로 계약을 체결한 경우 사기 여부는 甲을 표준으로 정하므로 甲이 사기를 몰랐다면 취소할 수 없다.","乙이 甲의 허락 없이 丙을 위해서도 대리인으로서 같은 계약을 체결하였다면, 甲과 丙이 모두 추인하더라도 그 계약은 효력이 없다.","乙이 甲을 위한 것임을 표시하지 않았더라도 丙이 乙이 대리인으로서 한 것임을 알 수 있었다면 그 계약의 효력은 甲에게 생긴다.","乙이 대리권 수여 후 성년후견개시의 심판을 받더라도 乙의 대리권은 소멸하지 않는다."],"a":[4],"L":"민1-3","o":"변형","x":{"한줄":"대리인이 본인을 위한 것임을 표시하지 않아도 상대방이 대리인으로서 한 행위임을 알 수 있었다면 효과는 본인에게 직접 귀속한다(제115조 단서).","근거":[{"법령":"민법","조문":"제115조","원문":"대리인이 본인을 위한 것임을 표시하지 아니한 때에는 그 의사표시는 자기를 위한 것으로 본다. 그러나 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때에는 전조제1항의 규정을 준용한다."},{"법령":"민법","조문":"제116조제1항","원문":"의사표시의 효력이 의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우에 그 사실의 유무는 대리인을 표준하여 결정한다."},{"법령":"민법","조문":"제117조","원문":"대리인은 행위능력자임을 요하지 아니한다."},{"법령":"민법","조문":"제124조","원문":"대리인은 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자쌍방을 대리하지 못한다. 그러나 채무의 이행은 할 수 있다."},{"법령":"민법","조문":"제127조","원문":"대리권은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 소멸된다.\n  1. 본인의 사망\n  2. 대리인의 사망, 성년후견의 개시 또는 파산"}],"선지":[{"번호":1,"판정":"틀림","설명":"대리인은 행위능력자임을 요하지 않는다(제117조). 미성년자가 한 대리행위는 제한능력을 이유로 취소할 수 없다."},{"번호":2,"판정":"틀림","설명":"사기 여부는 대리인 乙을 표준으로 정한다(제116조제1항). 乙이 속았다면 사기에 의한 의사표시로서 취소할 수 있다."},{"번호":3,"판정":"틀림","설명":"본인의 허락 없는 쌍방대리는 무권대리여서 甲과 丙이 모두 추인하면 유효하게 된다(제124조 위반의 효과)."},{"번호":4,"판정":"옳음","설명":"상대방이 대리인으로서 한 행위임을 알 수 있었다면 현명하지 않았더라도 본인에게 효력이 생긴다(제115조 단서)."},{"번호":5,"판정":"틀림","설명":"대리인이 성년후견개시 심판을 받으면 대리권은 소멸한다(제127조제2호)."}],"개념":[{"종류":"표","제목":"대리권의 소멸사유(제127조)","머리":["사유","대리권","비고"],"행":[["본인의 사망","소멸","제127조제1호"],["대리인의 사망","소멸","제127조제2호"],["대리인의 성년후견개시","소멸","제127조제2호"],["대리인의 파산","소멸","제127조제2호"],["대리인의 한정후견개시","소멸 사유로 규정되어 있지 않음","제127조에 열거 없음"]]},{"종류":"표","제목":"대리행위의 효과와 하자","머리":["쟁점","기준","근거"],"행":[["효과의 귀속","대리인이 권한 내에서 본인을 위한 것임을 표시하면 본인에게 직접 효력","제114조제1항"],["현명하지 않은 행위","원칙은 대리인 자신을 위한 것, 상대방이 알았거나 알 수 있었으면 본인에게 귀속","제115조"],["의사의 흠결·사기·강박·선악","대리인을 표준으로 결정","제116조제1항"],["대리인의 능력","행위능력 불요","제117조"],["자기계약·쌍방대리","본인의 허락이 없으면 금지, 채무이행은 가능","제124조"]]}],"함정":"대리인에게는 행위능력이 필요 없어서 미성년 대리인의 행위도 취소 사유가 아니다. 사기·선악 판단은 본인이 아닌 대리인을 기준으로 한다. 쌍방대리는 허락이 없어도 추인으로 유효가 된다."}},{"i":"S4-1-1-민법-06","r":"S4","g":1,"c":1,"n":46,"s":"민법","q":"복대리에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때에만 복대리인을 선임할 수 있다.","법정대리인이 부득이한 사유로 복대리인을 선임한 경우에도 복대리인의 행위에 관하여 본인에게 모든 책임을 진다.","복대리인은 대리인의 대리인이다.","대리인이 복대리인을 선임한 후 사망하더라도 복대리인의 대리권은 존속한다.","임의대리인이 본인의 지명으로 복대리인을 선임한 경우, 그 부적임이나 불성실을 알았더라도 본인에 대하여 책임이 없다."],"a":[1],"L":"민1-3","o":"변형","x":{"한줄":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다(제120조).","근거":[{"법령":"민법","조문":"제120조","원문":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니면 복대리인을 선임하지 못한다."},{"법령":"민법","조문":"제121조제2항","원문":"대리인이 본인의 지명에 의하여 복대리인을 선임한 경우에는 그 부적임 또는 불성실함을 알고 본인에게 대한 통지나 그 해임을 태만한 때가 아니면 책임이 없다."},{"법령":"민법","조문":"제122조","원문":"법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 그러나 부득이한 사유로 인한 때에는 전조제1항에 정한 책임만이 있다."},{"법령":"민법","조문":"제123조제1항","원문":"복대리인은 그 권한내에서 본인을 대리한다."},{"법령":"민법","조문":"제127조","원문":"대리권은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 소멸된다.\n  1. 본인의 사망\n  2. 대리인의 사망, 성년후견의 개시 또는 파산"}],"선지":[{"번호":1,"판정":"옳음","설명":"임의대리인의 복임권은 본인의 승낙 또는 부득이한 사유가 있을 때로 제한된다(제120조)."},{"번호":2,"판정":"틀림","설명":"법정대리인이 부득이한 사유로 선임한 때에는 선임·감독상 책임만 진다(제122조 단서)."},{"번호":3,"판정":"틀림","설명":"복대리인은 대리인이 아니라 본인의 대리인이다(제123조제1항)."},{"번호":4,"판정":"틀림","설명":"복대리권은 대리권을 기초로 하므로 대리인의 대리권이 소멸하면 복대리권도 소멸한다. 대리인의 사망은 대리권 소멸사유이다(제127조제2호)."},{"번호":5,"판정":"틀림","설명":"본인의 지명으로 선임해도 부적임·불성실을 알고 통지나 해임을 게을리하면 책임을 진다(제121조제2항)."}],"개념":[{"종류":"표","제목":"복임권과 책임","머리":["구분","복임권","선임·감독 책임"],"행":[["임의대리인","본인의 승낙 또는 부득이한 사유가 있을 때만(제120조)","선임·감독상 책임(제121조제1항)"],["임의대리인, 본인 지명 선임","본인의 지명에 따라 선임","부적임·불성실을 알고 통지·해임을 태만한 때만 책임(제121조제2항)"],["법정대리인","자유롭게 선임 가능, 그 책임으로(제122조)","원칙은 복대리인의 행위에 대한 전부 책임"],["법정대리인, 부득이한 사유","선임 가능","선임·감독상 책임만(제122조 단서)"]]},{"종류":"비교","제목":"대리인과 복대리인","왼쪽":{"이름":"대리인","항목":["본인이 수권하여 정함","권한 범위 안에서 본인을 대리","대리권이 소멸하면 복대리권도 소멸"]},"오른쪽":{"이름":"복대리인","항목":["대리인이 자기 책임으로 선임","본인의 대리인(대리인의 대리인이 아님)","권한 범위 안에서 본인이나 제3자에 대해 대리인과 동일한 권리의무"]}}],"함정":"복대리인은 본인의 대리인이다. 대리인이 복대리인을 선임한 책임은 임의대리인(원칙 선임·감독 책임)과 법정대리인(원칙 전부 책임)에서 다르다. 복대리권은 대리권이 소멸하면 함께 소멸한다."}},{"i":"S4-1-1-민법-07","r":"S4","g":1,"c":1,"n":47,"s":"민법","q":"법률행위의 취소에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["취소권은 추인할 수 있는 날로부터 3년내에 법률행위를 한 날로부터 10년내에 행사해야 한다.","취소할 수 있는 법률행위에 관하여 법정추인이 되려면 취소권자가 취소권의 존재를 인식해야 한다.","취소된 법률행위는 처음부터 무효인 것으로 본다.","취소권의 법적성질은 형성권이다.","취소할 수 있는 법률행위의 상대방이 확정된 경우, 그 취소는 그 상대방에 대한 의사표시로 하여야 한다."],"a":[2],"L":"민1-4","o":"기출","x":{"한줄":"법정추인은 취소권자가 취소권의 존재를 알았는지와 관계없이 제145조 각호의 사유가 있으면 성립한다.","근거":[{"법령":"민법","조문":"제145조","원문":"취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다.\n  1. 전부나 일부의 이행\n  2. 이행의 청구\n  3. 경개\n  4. 담보의 제공\n  5. 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도\n  6. 강제집행"},{"법령":"민법","조문":"제146조","원문":"취소권은 추인할 수 있는 날로부터 3년내에 법률행위를 한 날로부터 10년내에 행사하여야 한다."},{"법령":"민법","조문":"제141조","원문":"취소된 법률행위는 처음부터 무효인 것으로 본다. 다만, 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환(償還)할 책임이 있다."},{"법령":"민법","조문":"제142조","원문":"취소할 수 있는 법률행위의 상대방이 확정한 경우에는 그 취소는 그 상대방에 대한 의사표시로 하여야 한다."},{"판례":"대법원 판례","요지":"법정추인이 성립하려면 취소할 수 있는 행위임을 알고 있을 필요가 없고, 제145조 각호의 사유가 있으면 족하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년의 기간 안에 행사한다(제146조). 둘 중 먼저 끝나는 기간에 소멸하는 제척기간이다."},{"번호":2,"판정":"틀림","설명":"법정추인에는 취소권의 존재를 인식할 필요가 없다(제145조, 판례)."},{"번호":3,"판정":"옳음","설명":"취소하면 소급하여 처음부터 무효로 본다(제141조)."},{"번호":4,"판정":"옳음","설명":"취소권은 일방적 의사표시로 법률관계를 바꾸는 형성권이다."},{"번호":5,"판정":"옳음","설명":"상대방이 확정된 경우 취소는 그 상대방에 대한 의사표시로 한다(제142조)."}],"개념":[{"종류":"표","제목":"취소의 방법과 기간","머리":["쟁점","내용","근거"],"행":[["취소권자","제한능력자, 착오·사기·강박에 의한 의사표시를 한 자, 그 대리인 또는 승계인","제140조"],["취소의 상대방","상대방이 확정된 경우 그 상대방","제142조"],["취소의 효과","소급적 무효, 제한능력자는 현존이익 한도에서 반환","제141조"],["행사기간","추인할 수 있는 날부터 3년, 행위한 날부터 10년(제척기간)","제146조"],["추인의 요건","취소 원인이 소멸한 후(법정대리인·후견인은 예외)","제144조"]]},{"종류":"표","제목":"법정추인 사유(제145조)","머리":["사유","유의점"],"행":[["전부나 일부의 이행","취소권자가 이행하거나 상대방의 이행을 받은 경우 모두 해당(판례)"],["이행의 청구","취소권자가 상대방에게 청구한 경우"],["경개","채무를 새 채무로 바꾼 경우"],["담보의 제공","취소권자가 담보를 제공하거나 받은 경우"],["취소할 수 있는 행위로 취득한 권리의 양도","전부나 일부의 양도"],["강제집행","취소권자가 한 강제집행"],["공통 요건","추인할 수 있는 후에 있어야 하고, 이의를 보류하면 법정추인이 되지 않음(제145조 단서)"]]}],"함정":"법정추인은 제145조 각호의 사유가 있으면 성립하고, 취소권자가 취소권을 알았는지는 묻지 않는다. 3년과 10년은 모두 제척기간이다."}},{"i":"S4-1-1-민법-08","r":"S4","g":1,"c":1,"n":48,"s":"민법","q":"법률행위의 무효에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["무효인 법률행위의 추인은 그 무효의 원인이 소멸한 후에 하여야 그 효력이 인정된다.","무효인 법률행위는 무효임을 안 날로부터 3년이 지나면 추인할 수 없다.","법률행위의 일부분이 무효일 때, 그 나머지 부분의 유효성을 판단함에 있어 나머지 부분을 유효로 하려는 당사자의 가정적 의사는 고려되지 않는다.","무효인 법률행위의 추인은 묵시적인 방법으로 할 수는 없다.","강행법규 위반으로 무효인 법률행위를 추인한 때에는 다른 정함이 없으면 그 법률행위는 처음부터 유효한 법률행위가 된다."],"a":[1],"L":"민1-4","o":"기출","x":{"한줄":"무효행위의 추인은 무효 원인이 소멸한 뒤에 해야 효력이 있고, 추인하면 소급하지 않고 새로운 법률행위로 본다(제139조).","근거":[{"법령":"민법","조문":"제139조","원문":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제137조","원문":"법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 그러나 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다."},{"판례":"대법원 판례","요지":"무효인 법률행위의 추인은 무효 원인이 소멸한 후에 해야 효력이 있고, 묵시적으로도 할 수 있다. 무효 행위는 시간이 지나도 유효가 되지 않으며 추인에 기간 제한이 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"무효의 원인이 소멸한 후에 추인해야 새로운 법률행위로 효력이 인정된다."},{"번호":2,"판정":"틀림","설명":"무효는 기간 경과로 유효해지지도, 추인이 막히지도 않는다. 3년의 기간 제한은 취소권(제146조)에 있는 제도이다."},{"번호":3,"판정":"틀림","설명":"일부무효의 나머지 부분 유효 여부는 당사자의 가정적 의사로 판단한다(제137조 단서)."},{"번호":4,"판정":"틀림","설명":"무효행위의 추인은 묵시적으로도 할 수 있다."},{"번호":5,"판정":"틀림","설명":"무효행위를 추인해도 소급하여 유효가 되지 않고 추인한 때 새로운 법률행위가 된 것으로 본다(제139조 단서)."}],"개념":[{"종류":"비교","제목":"무효와 취소","왼쪽":{"이름":"무효","항목":["처음부터 당연히 효력이 없음","누구든지 주장할 수 있음","주장 기간의 제한이 없음","추인해도 소급 유효가 되지 않고 새로운 법률행위로 봄(제139조)"]},"오른쪽":{"이름":"취소","항목":["취소 전에는 유효, 취소하면 소급하여 무효(제141조)","취소권자만 취소할 수 있음(제140조)","추인할 수 있는 날부터 3년, 행위한 날부터 10년(제146조)","추인하면 취소권이 소멸하여 확정적으로 유효(제143조)"]}},{"종류":"표","제목":"무효행위의 처리","머리":["제도","요건","효과"],"행":[["일부무효(제137조)","법률행위의 일부만 무효","원칙은 전부 무효, 무효 부분이 없어도 했으리라고 인정되면 나머지는 유효"],["무효행위의 전환(제138조)","다른 법률행위의 요건을 갖추고 당사자가 알았더라면 의욕했으리라고 인정됨","다른 법률행위로서 효력"],["무효행위의 추인(제139조)","당사자가 무효임을 알고 추인","추인한 때부터 새로운 법률행위"],["유동적 무효(토지거래허가)","허가를 받기 전 계약","허가를 받으면 소급 유효, 불허가 확정이면 확정적 무효(판례)"]]}],"함정":"무효행위의 추인에는 소급효가 없고 추인한 때 새로운 법률행위가 성립한다. 선지 2의 3년은 취소권의 행사기간이다."}},{"i":"S4-1-1-민법-09","r":"S4","g":1,"c":1,"n":49,"s":"민법","q":"조건에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["조건성취의 효력은 특별한 사정이 없는 한 소급하지 않는다.","해제조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 특별한 사정이 없는 한 조건 없는 법률행위로 된다.","정지조건과 이행기로서의 불확정기한은 표시된 사실이 발생하지 않는 것으로 확정된 때에 채무를 이행하여야 하는지 여부로 구별될 수 있다.","이행지체의 경우 채권자는 상당한 기간을 정한 최고와 함께 그 기간 내에 이행이 없을 것을 정지조건으로 하여 계약을 해제할 수 있다.","신의성실에 반하는 방해로 말미암아 조건이 성취된 것으로 의제되는 경우, 성취의 의제시점은 그 방해가 없었더라면 조건이 성취되었으리라고 추산되는 시점이다."],"a":[2],"L":"민1-5","o":"기출","x":{"한줄":"불법조건이 붙은 법률행위는 정지조건이든 해제조건이든 법률행위 전체가 무효이다(제151조제1항). 조건 없는 법률행위로 되는 것은 아니다.","근거":[{"법령":"민법","조문":"제147조","원문":"①정지조건있는 법률행위는 조건이 성취한 때로부터 그 효력이 생긴다.\n②해제조건있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다.\n③당사자가 조건성취의 효력을 그 성취전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다."},{"법령":"민법","조문":"제150조제1항","원문":"조건의 성취로 인하여 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취한 것으로 주장할 수 있다."},{"법령":"민법","조문":"제151조제1항","원문":"조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"조건성취의 효력은 성취한 때부터 생기고 소급하지 않는 것이 원칙이다(제147조제1항·제2항, 제3항은 소급 약정을 허용)."},{"번호":2,"판정":"틀림","설명":"불법조건이 붙은 법률행위는 그 법률행위 전체가 무효이다(제151조제1항)."},{"번호":3,"판정":"옳음","설명":"표시된 사실이 발생하지 않는 것으로 확정된 때에도 채무를 이행해야 하면 불확정기한이고, 이행할 필요가 없으면 정지조건이다(판례)."},{"번호":4,"판정":"옳음","설명":"최고와 함께 그 기간 내에 이행이 없을 것을 정지조건으로 한 해제의 의사표시는 유효하다(판례)."},{"번호":5,"판정":"옳음","설명":"조건 성취를 신의칙에 반하여 방해한 경우 성취된 것으로 주장할 수 있고(제150조제1항), 의제 시점은 방해가 없었더라면 성취되었을 시점이다(판례)."}],"개념":[{"종류":"표","제목":"조건과 기한 비교","머리":["구분","조건","기한"],"행":[["의미","발생 여부가 불확실한 사실","발생이 확실한 사실"],["종류","정지조건, 해제조건","시기(始期), 종기(終期), 확정기한, 불확정기한"],["효력 발생","정지조건은 성취한 때 효력 발생, 해제조건은 성취한 때 효력 상실(제147조)","기한 도래 시 효력 발생·소멸"],["소급효","원칙 없음, 당사자가 소급 약정 가능(제147조제3항)","소급효 없음"],["이익","-","기한의 이익은 채무자를 위한 것으로 추정(제153조제1항)"]]},{"종류":"표","제목":"조건을 붙일 수 없는 법률행위","머리":["유형","예","이유"],"행":[["친족법·상속법상 행위","혼인, 입양, 상속 승인·포기","신분관계의 안정"],["상대방에게 불이익을 주는 단독행위","취소, 추인, 해제, 상계","상대방의 지위를 불안정하게 함(상계는 제493조제1항이 명시)"],["불법조건","범죄를 하지 않으면 금전을 주겠다는 약정 등","조건 때문에 법률행위 전체 무효(제151조제1항)"]]}],"함정":"불법조건은 정지조건이든 해제조건이든 법률행위 전체가 무효이다. 기성조건·불능조건은 정지·해제에 따라 결과가 반대로 갈린다(제151조제2항·제3항)."}},{"i":"S4-1-1-민법-10","r":"S4","g":1,"c":1,"n":50,"s":"민법","q":"물권적 청구권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["소유자는 소유물을 불법점유한 자의 특별승계인에 대하여도 그 반환을 청구할 수 있다.","물권적 청구권이 발생한 후 소유자가 소유권을 상실하면 그 청구권만 따로 행사할 수 없다.","소유권에 기한 방해제거청구권은 이미 생긴 방해의 결과를 제거하는 것까지 내용으로 한다.","불법원인으로 물건을 급여한 사람은 소유권에 기하여 그 물건의 반환을 청구할 수 없다.","소유자는 소유권을 가지고 있는 한 물권적 청구권이 소멸시효에 걸리지 않는다."],"a":[3],"L":"민2-1","o":"변형","x":{"한줄":"방해제거청구권은 현재 계속되는 방해의 원인을 제거하는 청구이고, 이미 끝난 방해의 결과를 없애는 것은 손해배상의 영역이다.","근거":[{"법령":"민법","조문":"제213조","원문":"소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 그러나 점유자가 그 물건을 점유할 권리가 있는 때에는 반환을 거부할 수 있다."},{"법령":"민법","조문":"제214조","원문":"소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."},{"법령":"민법","조문":"제746조","원문":"불법의 원인으로 인하여 재산을 급여하거나 노무를 제공한 때에는 그 이익의 반환을 청구하지 못한다. 그러나 그 불법원인이 수익자에게만 있는 때에는 그러하지 아니하다."},{"판례":"대법원 판례","요지":"소유권에 기한 방해제거청구권의 대상은 현재 계속되고 있는 방해의 원인이고 이미 발생한 방해결과가 아니다. 물권적 청구권은 소유권에서 파생하므로 소유권을 잃으면 청구권도 행사할 수 없고, 소유권이 존속하는 동안은 소멸시효에 걸리지 않는다. 불법원인급여의 반환은 소유권에 기한 청구로도 허용되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"반환청구의 상대방은 현재 점유자이므로 불법점유자의 특별승계인도 상대방이 된다."},{"번호":2,"판정":"옳음","설명":"물권적 청구권은 소유권에 종속하는 권리이므로 소유권을 상실하면 따로 행사하지 못한다."},{"번호":3,"판정":"틀림","설명":"방해제거는 현재 계속되는 방해의 원인을 제거하는 것이다. 방해 결과의 제거나 이미 입은 손해의 회복은 손해배상으로 구한다."},{"번호":4,"판정":"옳음","설명":"불법원인급여는 반환을 청구할 수 없고(제746조), 판례는 소유권에 기한 반환청구도 막는다."},{"번호":5,"판정":"옳음","설명":"소유권은 소멸시효에 걸리지 않고, 이에 기한 물권적 청구권도 소유권이 존속하는 한 소멸시효의 대상이 아니다."}],"개념":[{"종류":"표","제목":"소유권에 기한 물권적 청구권","머리":["종류","요건","내용","근거"],"행":[["소유물반환청구권","소유자가 점유를 빼앗긴 경우","현재 점유자에게 반환 청구, 점유할 권리가 있으면 거부 가능","제213조"],["소유물방해제거청구권","소유권을 방해하는 현재의 상태","방해 원인의 제거 청구","제214조 전단"],["소유물방해예방청구권","방해할 염려가 있는 행위","예방 또는 손해배상의 담보 청구","제214조 후단"],["공통","상대방의 고의·과실 불요","소유권이 존속하는 한 소멸시효 없음","판례"]]},{"종류":"비교","제목":"물권적 청구권과 불법행위 손해배상","왼쪽":{"이름":"물권적 청구권","항목":["상대방의 고의·과실이 필요 없음","현재 계속되는 침해의 제거가 목적","소유권이 존속하는 동안 소멸시효 없음"]},"오른쪽":{"이름":"불법행위 손해배상(제750조)","항목":["가해자의 고의·과실이 필요함","이미 발생한 손해의 금전 배상이 목적","소멸시효에 걸림"]}}],"함정":"방해제거의 대상은 지금 계속되는 방해의 원인이고, 이미 생긴 결과나 손해는 손해배상으로 구한다. 선지 5의 소멸시효는 소유권이 존속하는 한 물권적 청구권에는 적용되지 않는다."}},{"i":"S4-1-1-민법-11","r":"S4","g":1,"c":1,"n":51,"s":"민법","q":"등기 없이도 물권변동의 효력이 생기는 경우는? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["점유취득시효의 완성에 따른 점유자의 소유권 취득","매매계약에 따른 매수인의 토지 소유권 취득","공유물분할 협의가 성립한 경우 각 공유자의 단독소유권 취득","상속에 의한 상속인의 부동산 소유권 취득","전세권설정계약에 따른 전세권자의 전세권 취득"],"a":[4],"L":"민2-2","o":"변형","x":{"한줄":"상속에 의한 부동산 물권 취득은 법률의 규정에 의한 취득이므로 등기 없이 효력이 생긴다(제187조). 다만 등기하지 않으면 처분하지 못한다.","근거":[{"법령":"민법","조문":"제186조","원문":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."},{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"법령":"민법","조문":"제245조제1항","원문":"20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"판례":"대법원 판례","요지":"공유물분할의 협의가 성립하거나 조정이 성립한 것만으로는 단독소유권을 취득하지 못하고 분할에 따른 등기를 마쳐야 소유권이 변동된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"점유취득시효는 점유 요건을 갖춘 뒤 등기해야 소유권을 취득한다(제245조제1항)."},{"번호":2,"판정":"틀림","설명":"매매는 법률행위이므로 등기해야 소유권이 이전한다(제186조)."},{"번호":3,"판정":"틀림","설명":"공유물분할의 협의는 법률행위이므로 분할에 따른 등기를 해야 단독소유권을 취득한다(제186조, 판례)."},{"번호":4,"판정":"옳음","설명":"상속은 제187조에 따라 등기 없이 소유권을 취득한다."},{"번호":5,"판정":"틀림","설명":"전세권은 설정계약과 등기로 성립한다(제186조)."}],"개념":[{"종류":"표","제목":"등기가 필요한 경우와 필요 없는 경우","머리":["구분","대표 사례","등기"],"행":[["법률행위로 인한 변동(제186조)","매매·증여의 소유권 이전, 지상권·전세권·저당권의 설정","등기해야 효력 발생"],["상속(제187조)","피상속인의 사망으로 상속인이 취득","등기 불요, 처분하려면 등기 필요"],["공용징수·판결(제187조)","토지수용, 형성판결(재판상 공유물분할 등)","등기 불요"],["경매(제187조)","경매 매수인의 소유권 취득(대금 완납 시)","등기 불요"],["기타 법률 규정","건물의 신축, 법정지상권의 취득, 법정갱신된 전세권, 분묘기지권의 시효취득","등기 불요"],["점유취득시효(제245조)","20년간 점유 후 소유권 취득","점유 요건을 갖춘 뒤 등기해야 취득"]]},{"종류":"비교","제목":"제186조와 제187조","왼쪽":{"이름":"제186조(법률행위)","항목":["당사자의 의사표시로 인한 변동","등기해야 효력이 생김(성립요건주의)","매매·증여·설정계약·공유물분할 협의"]},"오른쪽":{"이름":"제187조(법률 규정)","항목":["상속·공용징수·판결·경매 등","등기 없이 효력이 생김","등기하지 않으면 처분하지 못함"]}}],"함정":"공유물분할의 협의와 조정은 합의에 의한 변동이라 등기가 필요하다. 재판상 분할의 확정판결은 등기 없이 변동된다. 점유취득시효는 점유 요건을 갖춘 뒤 등기해야 소유권이 생긴다."}},{"i":"S4-1-1-민법-12","r":"S4","g":1,"c":1,"n":52,"s":"민법","q":"甲은 자신의 토지를 乙에게 매도하여 인도하였고, 乙은 그 토지를 점유ㆍ사용하다가 다시 丙에게 매도하여 인도하였다. 甲과 乙은 모두 대금 전부를 수령하였고, 甲ㆍ乙ㆍ丙 사이에 중간생략등기의 합의가 있었다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 丙을 상대로 소유물반환을 청구할 수 있다.","甲은 乙을 상대로 소유물반환을 청구할 수 없다.","丙은 직접 甲을 상대로 소유권이전등기를 청구할 수 없다.","丙은 乙을 대위하여 甲을 상대로 소유권이전등기를 청구할 수 없다.","만약 乙이 인도받은 후 현재 10년이 지났다면, 乙은 甲에 대해 소유권이전등기를 청구할 수 없다."],"a":[2],"L":"민2-2","o":"기출","x":{"한줄":"甲은 乙에게 대금을 받고 토지를 인도하였으므로 乙은 점유할 권리가 있고, 甲의 소유물반환청구는 제213조 단서에 막힌다.","근거":[{"법령":"민법","조문":"제213조","원문":"소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 그러나 점유자가 그 물건을 점유할 권리가 있는 때에는 반환을 거부할 수 있다."},{"법령":"부동산등기 특별조치법","조문":"제8조제1호","원문":"조세부과를 면하려 하거나 다른 시점간의 가격변동에 따른 이득을 얻으려 하거나 소유권등 권리변동을 규제하는 법령의 제한을 회피할 목적으로 제2조제2항 또는 제3항의 규정에 위반한 때"},{"판례":"대법원 판례","요지":"순차 매매에서 세 당사자가 중간생략등기에 합의하면 최종 매수인은 최초 매도인에게 직접 이전등기를 청구할 수 있다. 중간생략등기 합의는 단속규정 위반이어도 사법상 유효하다. 매수인이 목적물을 인도받아 사용·수익하는 동안에는 이전등기청구권의 소멸시효가 진행하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"丙은 乙에게서 매수하여 인도받은 점유자로서 점유할 권리가 있어 甲의 반환청구에 대항할 수 있다(제213조 단서)."},{"번호":2,"판정":"옳음","설명":"乙은 대금을 지급하고 인도받은 매수인으로서 점유할 권리가 있어 甲은 소유물반환을 청구할 수 없다."},{"번호":3,"판정":"틀림","설명":"甲·乙·丙 3자 합의가 있으므로 丙은 甲에게 직접 이전등기를 청구할 수 있다."},{"번호":4,"판정":"틀림","설명":"丙은 乙의 甲에 대한 이전등기청구권을 대위행사할 수 있다."},{"번호":5,"판정":"틀림","설명":"매수인이 목적물을 인도받아 사용·수익하는 동안에는 이전등기청구권의 소멸시효가 진행하지 않는다."}],"개념":[{"종류":"표","제목":"중간생략등기","머리":["쟁점","내용"],"행":[["의의","甲→乙→丙으로 순차 매매한 부동산을 중간 등기 없이 甲에서 丙으로 바로 등기하는 것"],["이미 마친 중간생략등기","실체관계에 부합하면 유효(판례)"],["3자 합의가 있는 경우","丙이 甲에게 직접 이전등기 청구 가능"],["3자 합의가 없는 경우","丙은 甲에게 직접 청구할 수 없고, 乙의 이전등기청구권을 대위행사해야 함"],["처벌","조세 회피 등의 목적으로 부동산등기 특별조치법 제2조제2항 등을 위반하면 처벌(제8조제1호), 합의의 사법상 효력은 유효"]]},{"종류":"표","제목":"이전등기청구권의 소멸시효","머리":["상황","시효 진행 여부"],"행":[["매수인이 목적물을 인도받아 점유·사용 중","진행하지 않음(판례)"],["매수인이 점유를 타인에게 양도한 뒤","양도 시부터 진행(판례)"],["매수인이 인도받지 않은 경우","권리를 행사할 수 있는 때부터 진행"]]}],"함정":"매수인이 인도받아 사용·수익하는 동안에는 이전등기청구권의 소멸시효가 진행하지 않으므로 10년이 지나도 청구할 수 있다. 선지 1은 丙의 점유할 권리(제213조 단서)를 놓치면 틀린다."}},{"i":"S4-1-1-민법-13","r":"S4","g":1,"c":1,"n":53,"s":"민법","q":"점유자와 회복자의 관계에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["선의의 점유자는 점유물의 과실을 취득한 경우에도 통상의 필요비의 상환을 청구할 수 있다.","점유자가 점유물을 개량하기 위하여 유익비를 지출한 경우, 가액의 증가가 현존하는 때에 한하여 회복자의 선택에 따라 지출금액이나 증가액의 상환을 청구할 수 있다.","악의의 점유자는 수취한 과실을 반환하여야 하지만 이미 소비한 과실의 대가는 보상할 필요가 없다.","선의의 자주점유자가 책임 있는 사유로 점유물을 멸실한 경우에는 손해의 전부를 배상하여야 한다.","선의의 점유자가 본권에 관한 소에서 패소한 경우, 그 판결이 확정된 때부터 악의의 점유자로 본다."],"a":[2],"L":"민2-3","o":"변형","x":{"한줄":"유익비는 가액의 증가가 현존하는 경우에 한하여, 회복자의 선택에 따라 지출금액 또는 증가액을 상환한다(제203조제2항).","근거":[{"법령":"민법","조문":"제203조","원문":"①점유자가 점유물을 반환할 때에는 회복자에 대하여 점유물을 보존하기 위하여 지출한 금액 기타 필요비의 상환을 청구할 수 있다. 그러나 점유자가 과실을 취득한 경우에는 통상의 필요비는 청구하지 못한다.\n②점유자가 점유물을 개량하기 위하여 지출한 금액 기타 유익비에 관하여는 그 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 그 지출금액이나 증가액의 상환을 청구할 수 있다.\n③전항의 경우에 법원은 회복자의 청구에 의하여 상당한 상환기간을 허여할 수 있다."},{"법령":"민법","조문":"제201조제2항","원문":"악의의 점유자는 수취한 과실을 반환하여야 하며 소비하였거나 과실로 인하여 훼손 또는 수취하지 못한 경우에는 그 과실의 대가를 보상하여야 한다."},{"법령":"민법","조문":"제202조","원문":"점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"법령":"민법","조문":"제197조제2항","원문":"선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"과실을 취득한 점유자는 통상의 필요비를 청구하지 못한다(제203조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"유익비는 가액 증가가 현존할 때만 청구하고, 지출액과 증가액 중 무엇을 상환할지는 회복자가 고른다(제203조제2항)."},{"번호":3,"판정":"틀림","설명":"악의의 점유자는 소비한 과실의 대가도 보상해야 한다(제201조제2항)."},{"번호":4,"판정":"틀림","설명":"선의의 자주점유자는 이익이 현존하는 한도에서만 배상한다(제202조 전단). 전부 배상은 악의 점유자와 소유의 의사 없는 점유자이다."},{"번호":5,"판정":"틀림","설명":"패소한 경우 그 소가 제기된 때부터 악의의 점유자로 본다(제197조제2항). 판결 확정 시점이 아니다."}],"개념":[{"종류":"표","제목":"점유자의 선악·자주타주에 따른 효과","머리":["구분","과실","멸실·훼손 책임","비용상환"],"행":[["선의 자주점유자","과실 취득(제201조제1항)","현존이익 한도(제202조)","통상 필요비 청구 불가, 특별 필요비·유익비 청구 가능"],["악의 자주점유자","과실 반환, 소비 등은 대가 보상(제201조제2항)","전부 배상(제202조)","필요비·유익비 청구 가능"],["타주점유자","선의면 과실 취득","선의여도 전부 배상(제202조)","필요비·유익비 청구 가능"],["선의 점유자가 본권소송 패소","소 제기 시부터 악의로 간주(제197조제2항)","소 제기 후는 악의 기준","-"]]},{"종류":"비교","제목":"필요비와 유익비","왼쪽":{"이름":"필요비(제203조제1항)","항목":["점유물 보존을 위해 지출한 비용","원칙적으로 지출액 전부 상환","과실을 취득한 점유자는 통상의 필요비 청구 불가"]},"오른쪽":{"이름":"유익비(제203조제2항)","항목":["점유물 개량을 위해 지출한 비용","가액 증가가 현존할 때만 청구","지출액과 증가액 중 회복자가 선택, 법원이 상환기간 허여 가능"]}}],"함정":"유익비의 상환 방법(지출액 또는 증가액)은 회복자가 고른다. 선의 점유자는 현존이익만 배상하고, 악의 점유자와 소유 의사 없는 점유자가 전부 배상한다."}},{"i":"S4-1-1-민법-14","r":"S4","g":1,"c":1,"n":54,"s":"민법","q":"상린관계에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["인접지의 수목 가지가 경계를 넘은 경우 토지소유자는 그 소유자에게 청구하지 않고도 임의로 가지를 제거할 수 있다.","주위토지통행권을 가진 사람은 통행지 소유자의 손해를 보상할 필요가 없다.","경계에 설치된 담이 상린자의 공유로 추정되는 경우에도 각 공유자는 공유물분할을 청구할 수 있다.","분할로 인하여 공로에 통하지 못하게 된 토지의 소유자는 다른 분할자의 토지를 통행할 수 있고, 이 경우 보상할 의무가 없다.","경계로부터 1미터 이내의 거리에서 이웃 주택의 내부를 관망할 수 있는 창을 설치하는 경우에 한하여 차면시설을 해야 한다."],"a":[4],"L":"민2-4","o":"변형","x":{"한줄":"분할로 공로에 통하지 못하게 된 토지의 소유자는 다른 분할자의 토지를 보상 없이 통행할 수 있다(제220조제1항).","근거":[{"법령":"민법","조문":"제220조제1항","원문":"분할로 인하여 공로에 통하지 못하는 토지가 있는 때에는 그 토지소유자는 공로에 출입하기 위하여 다른 분할자의 토지를 통행할 수 있다. 이 경우에는 보상의 의무가 없다."},{"법령":"민법","조문":"제219조제2항","원문":"전항의 통행권자는 통행지소유자의 손해를 보상하여야 한다."},{"법령":"민법","조문":"제240조","원문":"①인접지의 수목가지가 경계를 넘은 때에는 그 소유자에 대하여 가지의 제거를 청구할 수 있다.\n②전항의 청구에 응하지 아니한 때에는 청구자가 그 가지를 제거할 수 있다.\n③인접지의 수목뿌리가 경계를 넘은 때에는 임의로 제거할 수 있다."},{"법령":"민법","조문":"제268조제3항","원문":"전2항의 규정은 제215조, 제239조의 공유물에는 적용하지 아니한다."},{"법령":"민법","조문":"제243조","원문":"경계로부터 2미터 이내의 거리에서 이웃 주택의 내부를 관망할 수 있는 창이나 마루를 설치하는 경우에는 적당한 차면시설을 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"가지는 먼저 소유자에게 제거를 청구하고 응하지 않을 때 청구자가 제거한다(제240조제1항·제2항). 뿌리만 임의로 제거할 수 있다(제3항)."},{"번호":2,"판정":"틀림","설명":"주위토지통행권자는 통행지 소유자의 손해를 보상해야 한다(제219조제2항). 보상이 없는 것은 분할·일부양도의 경우(제220조)이다."},{"번호":3,"판정":"틀림","설명":"경계표·담의 공유물에는 분할청구에 관한 제268조 제1항·제2항이 적용되지 않는다(제268조제3항). 분할을 청구할 수 없다."},{"번호":4,"판정":"옳음","설명":"제220조제1항은 분할자의 토지를 무상으로 통행할 수 있게 한다."},{"번호":5,"판정":"틀림","설명":"차면시설 의무는 경계로부터 2미터 이내에서 창이나 마루를 설치할 때 생긴다(제243조)."}],"개념":[{"종류":"표","제목":"상린관계 주요 규정","머리":["규정","내용","근거"],"행":[["인지사용청구","경계 근처의 담·건물 축조·수선에 필요한 범위에서 이웃 토지 사용 청구, 승낙 없이 주거 출입 불가, 손해 보상 청구","제216조"],["주위토지통행권","공로에 통하는 통로가 없으면 주위 토지 통행, 손해가 가장 적은 장소·방법, 손해 보상","제219조"],["분할·일부양도와 통행","다른 분할자 토지 통행, 보상 의무 없음","제220조"],["경계선 부근 건축","경계에서 반미터 이상 거리, 건축 착수 후 1년 경과 또는 완성 후에는 손해배상만 청구","제242조"],["차면시설","경계에서 2미터 이내의 창·마루","제243조"],["수목","가지는 청구 후 제거, 뿌리는 임의 제거","제240조"],["경계표·담","상린자의 공유로 추정, 분할청구 불가","제239조, 제268조제3항"]]},{"종류":"비교","제목":"주위토지통행권: 제219조와 제220조","왼쪽":{"이름":"제219조(일반)","항목":["공로와의 사이에 토지 용도에 필요한 통로가 없을 때","주위 토지 어디든 손해가 가장 적은 곳을 통행","통행지 소유자의 손해 보상 필요"]},"오른쪽":{"이름":"제220조(분할·일부양도)","항목":["분할·일부양도로 공로에 통하지 못하게 된 때","다른 분할자의 토지만 통행(일부양도에도 준용, 제220조제2항)","보상 의무 없음"]}}],"함정":"가지는 청구 후에야 제거할 수 있고 임의 제거는 뿌리에만 허용된다. 분할에 따른 통행권(제220조)은 무상이고 일반 주위통행권(제219조)은 보상이 필요하다."}},{"i":"S4-1-1-민법-15","r":"S4","g":1,"c":1,"n":55,"s":"민법","q":"주위토지통행권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["토지와 공로 사이에 이미 통로가 있어 그곳으로 출입할 수 있더라도, 더 편리한 길을 원하면 주위의 다른 토지를 통행할 수 있다.","주위토지통행권은 통행지 소유자와 통행에 관한 계약을 하고 등기를 마쳐야 비로소 효력이 생긴다.","주위토지통행권자는 통로를 개설하는 경우 그 비용을 부담하고 통행지 소유자의 손해를 보상하여야 한다.","주위토지통행권의 범위는 장래 건립할 건물의 이용 상황까지 미리 대비하여 정해야 한다.","통행지 소유자가 통행에 방해되는 담장을 설치한 경우, 통행권자는 철거를 청구할 수 없고 손해배상만 청구할 수 있다."],"a":[3],"L":"민2-4","o":"변형","x":{"한줄":"통로 개설에 드는 비용은 통행권자가 부담하고(판례), 통행권자는 통행지 소유자의 손해를 보상해야 한다(제219조제2항).","근거":[{"법령":"민법","조문":"제219조","원문":"①어느 토지와 공로사이에 그 토지의 용도에 필요한 통로가 없는 경우에 그 토지소유자는 주위의 토지를 통행 또는 통로로 하지 아니하면 공로에 출입할 수 없거나 과다한 비용을 요하는 때에는 그 주위의 토지를 통행할 수 있고 필요한 경우에는 통로를 개설할 수 있다. 그러나 이로 인한 손해가 가장 적은 장소와 방법을 선택하여야 한다.\n②전항의 통행권자는 통행지소유자의 손해를 보상하여야 한다."},{"판례":"대법원 판례","요지":"주위토지통행권은 법정의 권리로서 등기나 별도의 계약 없이 성립한다. 이미 통로가 있어도 그 토지의 용도에 적합하지 않아 통로 기능을 하지 못하면 인정되지만, 기존 통로로 출입할 수 있으면 더 편리하다는 이유로는 인정되지 않는다. 범위는 현재의 토지 용도에 필요한 한도이고 장래의 이용 상황까지 미리 대비하지는 않는다. 통로 개설 비용은 통행권자가 부담하고, 통행지 소유자가 방해되는 축조물을 설치하면 철거 의무를 진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기존 통로로 공로에 출입할 수 있으면 더 편리하다는 이유만으로 다른 토지에 통행권을 주장할 수 없다."},{"번호":2,"판정":"틀림","설명":"주위토지통행권은 법률이 정한 권리로서 계약이나 등기가 없어도 성립한다."},{"번호":3,"판정":"옳음","설명":"통로 개설·유지 비용은 통행권자가 부담하고, 통행지 소유자의 손해는 보상해야 한다(제219조제2항)."},{"번호":4,"판정":"틀림","설명":"범위는 현재의 토지 용도에 필요한 한도이며 장래의 이용 상황까지 미리 대비해 정하지 않는다."},{"번호":5,"판정":"틀림","설명":"통행지 소유자는 통행을 방해하는 축조물을 철거할 의무를 부담하므로 통행권자는 철거를 청구할 수 있다."}],"개념":[{"종류":"표","제목":"주위토지통행권의 법리","머리":["쟁점","내용"],"행":[["성립","공로에 통하는 토지 용도에 필요한 통로가 없고, 과다한 비용 없이는 출입할 수 없을 때(제219조제1항)"],["통행 장소·방법","손해가 가장 적은 장소와 방법"],["범위","현재의 토지 용도에 필요한 범위, 장래 이용 상황까지 대비하지 않음(판례)"],["기존 통로","있어도 토지 이용에 부적합하여 통로 기능을 못 하면 인정, 편리함만으로는 부정(판례)"],["비용·보상","통로 개설 비용은 통행권자 부담, 통행지 소유자의 손해 보상(제219조제2항)"],["등기","불요, 법정 권리(판례)"],["방해물","통행지 소유자가 철거 의무 부담(판례)"]]},{"종류":"비교","제목":"주위토지통행권과 통행지역권","왼쪽":{"이름":"주위토지통행권","항목":["법률에 의한 법정 권리","등기 없이 성립","통행지 소유자의 손해 보상 필요(제219조제2항)","시효취득의 대상이 아님"]},"오른쪽":{"이름":"통행지역권","항목":["설정계약과 등기로 성립(제186조), 계속·표현된 경우 시효취득 가능(제294조)","요역지 소유권에 부종(제292조)","대가는 당사자가 정함","요역지와 분리하여 양도 불가(제292조제2항)"]}}],"함정":"기존 통로가 통로 기능을 하는지가 기준이고 더 편리한 길은 이유가 되지 않는다. 범위는 현재 토지 용도를 기준으로 하며 장래 건축 계획까지 반영하지 않는다."}},{"i":"S4-1-1-민법-16","r":"S4","g":1,"c":1,"n":56,"s":"민법","q":"甲은 3/5, 乙은 1/5, 丙은 1/5의 지분으로 X토지를 공유하고 있다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲이 乙·丙과 협의 없이 X토지 전부를 丁에게 임대하여 차임을 받았다면, 乙과 丙은 甲에게 각자의 지분에 상응하는 차임 상당액의 반환을 청구할 수 있다.","乙이 甲·丙과 협의 없이 X토지 전부를 독점적으로 사용하고 있다면, 丙은 보존행위로서 乙에게 X토지 전부의 인도를 청구할 수 있다.","甲·乙·丙이 10년간 X토지를 분할하지 않기로 약정하였다면 그 약정은 10년간 유효하다.","乙이 1년 이상 공유물의 관리비용을 부담하지 않더라도 甲은 乙의 지분을 매수할 수 없다.","甲은 과반수 지분권자이므로 乙·丙의 동의 없이 X토지 위에 건물을 신축하는 등 공유물을 변경할 수 있다."],"a":[1],"L":"민2-4","o":"변형","x":{"한줄":"과반수 지분권자의 임대는 관리행위로 유효하므로, 임대수익 중 소수지분권자의 지분 비율 몫은 과반수 지분권자가 부당이득으로 반환해야 한다.","근거":[{"법령":"민법","조문":"제265조","원문":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제264조","원문":"공유자는 다른 공유자의 동의없이 공유물을 처분하거나 변경하지 못한다."},{"법령":"민법","조문":"제266조","원문":"①공유자는 그 지분의 비율로 공유물의 관리비용 기타 의무를 부담한다.\n②공유자가 1년 이상 전항의 의무이행을 지체한 때에는 다른 공유자는 상당한 가액으로 지분을 매수할 수 있다."},{"법령":"민법","조문":"제268조제1항","원문":"공유자는 공유물의 분할을 청구할 수 있다. 그러나 5년내의 기간으로 분할하지 아니할 것을 약정할 수 있다."},{"판례":"대법원 2018다287522 전원합의체","요지":"공유물의 소수지분권자가 다른 공유자와 협의 없이 공유물을 독점적으로 점유하는 경우, 다른 소수지분권자는 보존행위로서 공유물 전부의 인도를 청구할 수 없다. 독점으로 침해된 지분 비율 상당의 부당이득 반환은 별도로 청구할 수 있다."},{"판례":"대법원 판례","요지":"과반수 지분권자가 공유물을 임대하는 것은 관리행위로서 유효하며, 임대수익 중 다른 공유자의 지분 비율에 해당하는 부분은 부당이득으로 반환해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"甲의 임대는 과반수 지분(3/5)에 의한 관리행위로 유효하다. 乙·丙은 차임 중 자기 지분 비율 몫을 甲에게 청구할 수 있다."},{"번호":2,"판정":"틀림","설명":"소수지분권자 乙의 독점 사용에 대해 다른 소수지분권자 丙은 보존행위로 공유물 전부의 인도를 청구할 수 없다(2018다287522 전원합의체)."},{"번호":3,"판정":"틀림","설명":"분할금지 특약은 5년을 넘지 못한다(제268조제1항). 10년으로 약정해도 5년으로 본다."},{"번호":4,"판정":"틀림","설명":"1년 이상 관리비용 의무의 이행을 지체한 공유자의 지분은 다른 공유자가 상당한 가액으로 매수할 수 있다(제266조제2항)."},{"번호":5,"판정":"틀림","설명":"공유물의 처분·변경은 다른 공유자 전원의 동의가 필요하다(제264조). 과반수로 결정하는 것은 관리행위이다."}],"개념":[{"종류":"표","제목":"공유물에 관한 의사결정","머리":["행위","결정 방법","근거"],"행":[["지분의 처분","각 공유자가 자유롭게","제263조"],["공유물의 처분·변경","다른 공유자 전원의 동의","제264조"],["공유물의 관리(임대 등)","지분의 과반수","제265조 본문"],["공유물의 보존","각자 단독으로","제265조 단서"],["공유물 분할 청구","각 공유자가 청구, 협의가 안 되면 법원에 청구","제268조제1항, 제269조제1항"]]},{"종류":"표","제목":"공유 관련 기간과 귀속","머리":["쟁점","내용","근거"],"행":[["분할금지 특약","5년을 넘지 못하며, 갱신해도 갱신한 날부터 5년","제268조제1항·제2항"],["관리비용 부담","지분 비율로 부담, 1년 이상 지체하면 다른 공유자가 상당한 가액으로 지분 매수 가능","제266조"],["지분 포기·상속인 없는 사망","다른 공유자에게 지분 비율로 귀속","제267조"],["현물분할이 불가능한 경우","법원이 경매를 명할 수 있음","제269조제2항"],["소수지분권자의 독점 점유","다른 소수지분권자는 인도 청구 불가, 지분 비율 부당이득 반환 청구 가능","2018다287522 전원합의체"]]}],"함정":"과반수 지분으로 결정할 수 있는 것은 관리행위이고 처분·변경은 전원 동의가 필요하다. 소수지분권자끼리는 인도를 청구하지 못하고 부당이득 반환으로 다툰다."}},{"i":"S4-1-1-민법-17","r":"S4","g":1,"c":1,"n":57,"s":"민법","q":"지역권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["지역권은 요역지 소유권과 분리하여 양도하거나 다른 권리의 목적으로 할 수 있다.","지역권은 승역지 소유자에게 대가를 지급하기로 약정해야 성립한다.","지역권은 계속되고 표현된 것에 한하여 점유취득시효에 관한 규정을 준용하여 시효취득할 수 있다.","계약으로 승역지 소유자가 자기 비용으로 공작물을 설치·수선할 의무를 부담한 경우에도, 승역지의 특별승계인은 그 의무를 부담하지 않는다.","승역지 소유자는 지역권에 필요한 부분의 토지소유권을 지역권자에게 이전하더라도 공작물 설치·수선 의무를 면할 수 없다."],"a":[3],"L":"민2-5","o":"변형","x":{"한줄":"지역권은 계속되고 표현된 것에 한하여 점유취득시효 규정을 준용해 시효취득할 수 있다(제294조).","근거":[{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."},{"법령":"민법","조문":"제292조제2항","원문":"지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제298조","원문":"계약에 의하여 승역지소유자가 자기의 비용으로 지역권의 행사를 위하여 공작물의 설치 또는 수선의 의무를 부담한 때에는 승역지소유자의 특별승계인도 그 의무를 부담한다."},{"법령":"민법","조문":"제299조","원문":"승역지의 소유자는 지역권에 필요한 부분의 토지소유권을 지역권자에게 위기하여 전조의 부담을 면할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지역권은 요역지 소유권에 부종하므로 요역지와 분리하여 양도하거나 다른 권리의 목적으로 할 수 없다(제292조제2항)."},{"번호":2,"판정":"틀림","설명":"대가의 지급은 지역권의 성립요건이 아니다. 무상의 지역권도 가능하다(제291조)."},{"번호":3,"판정":"옳음","설명":"계속되고 표현된 지역권만 점유취득시효 규정을 준용해 취득한다(제294조)."},{"번호":4,"판정":"틀림","설명":"승역지 소유자의 특별승계인도 그 의무를 부담한다(제298조)."},{"번호":5,"판정":"틀림","설명":"승역지 소유자는 필요한 부분의 토지소유권을 지역권자에게 위기하여 의무를 면할 수 있다(제299조)."}],"개념":[{"종류":"표","제목":"지역권의 주요 규정","머리":["쟁점","내용","근거"],"행":[["내용","자기 토지(요역지)의 편익을 위해 타인 토지(승역지)를 이용","제291조"],["부종성","요역지 소유권에 부종하여 이전, 요역지와 분리하여 양도·담보 불가","제292조"],["불가분성","공유자 1인이 지분에 관해 지역권을 소멸시키지 못함, 토지 분할 시 각 부분에 존속","제293조"],["시효취득","계속되고 표현된 것에 한함","제294조"],["취득의 불가분","공유자 1인이 취득하면 다른 공유자도 취득, 취득시효 중단은 모든 공유자에 대한 사유가 아니면 무효","제295조"],["승역지 소유자의 의무","약정한 공작물 설치·수선 의무는 특별승계인도 부담","제298조"],["위기","필요한 부분의 토지소유권을 지역권자에게 이전하여 부담 면제","제299조"]]},{"종류":"비교","제목":"지상권과 지역권","왼쪽":{"이름":"지상권","항목":["건물 기타 공작물이나 수목을 소유하기 위해 타인의 토지를 사용(제279조)","독립한 물권으로 양도·임대 가능(제282조)","존속기간의 최단 기간 제한이 있음(제280조)"]},"오른쪽":{"이름":"지역권","항목":["자기 토지의 편익을 위해 타인의 토지를 이용(제291조)","요역지 소유권에 부종하여 분리 양도 불가(제292조)","계속되고 표현된 것만 시효취득(제294조)"]}}],"함정":"지역권은 요역지에 부종하여 따로 양도하거나 담보로 쓸 수 없다. 대가 지급은 성립요건이 아니고, 시효취득은 계속·표현 요건을 갖춘 경우에 한한다."}},{"i":"S4-1-1-민법-18","r":"S4","g":1,"c":1,"n":58,"s":"민법","q":"지상권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["지상권의 존속기간을 영구로 약정하는 것은 허용되지 않는다.","지상권자는 토지소유자의 동의가 있어야 지상권을 타인에게 양도할 수 있다.","지료를 약정하지 않은 지상권은 성립하지 않는다.","지상권자가 1년분의 지료를 연체하면 지상권설정자는 지상권의 소멸을 청구할 수 있다.","건물 소유를 목적으로 한 지상권이 소멸한 경우 건물이 현존하고 지상권설정자가 계약의 갱신을 원하지 않으면, 지상권자는 상당한 가액으로 그 건물의 매수를 청구할 수 있다."],"a":[5],"L":"민2-5","o":"변형","x":{"한줄":"지상권이 소멸한 때 건물이 현존하고 설정자가 갱신을 원하지 않으면 지상권자가 상당한 가액으로 매수를 청구할 수 있다(제283조제2항).","근거":[{"법령":"민법","조문":"제283조","원문":"①지상권이 소멸한 경우에 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다.\n②지상권설정자가 계약의 갱신을 원하지 아니하는 때에는 지상권자는 상당한 가액으로 전항의 공작물이나 수목의 매수를 청구할 수 있다."},{"법령":"민법","조문":"제282조","원문":"지상권자는 타인에게 그 권리를 양도하거나 그 권리의 존속기간 내에서 그 토지를 임대할 수 있다."},{"법령":"민법","조문":"제287조","원문":"지상권자가 2년 이상의 지료를 지급하지 아니한 때에는 지상권설정자는 지상권의 소멸을 청구할 수 있다."},{"판례":"대법원 판례","요지":"지상권의 존속기간을 영구로 약정하는 것도 허용된다. 지료는 지상권의 성립요소가 아니어서 지료의 약정이 없으면 무상의 지상권이 된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"영구 존속기간의 약정도 유효하다(판례). 민법은 최단 기간만 제한한다(제280조)."},{"번호":2,"판정":"틀림","설명":"지상권자는 토지소유자의 동의 없이 지상권을 양도할 수 있다(제282조)."},{"번호":3,"판정":"틀림","설명":"지료는 지상권의 성립요소가 아니다. 약정이 없으면 무상의 지상권이다."},{"번호":4,"판정":"틀림","설명":"소멸청구는 2년 이상의 지료를 지급하지 않은 경우에 할 수 있다(제287조)."},{"번호":5,"판정":"옳음","설명":"갱신청구에 설정자가 응하지 않으면 지상권자는 지상물의 매수를 청구할 수 있다(제283조제2항)."}],"개념":[{"종류":"표","제목":"지상권의 존속기간","머리":["구분","최단 존속기간","근거"],"행":[["석조·석회조·연와조 등 견고한 건물이나 수목의 소유","30년","제280조제1항제1호"],["그 밖의 건물의 소유","15년","제280조제1항제2호"],["건물 이외의 공작물의 소유","5년","제280조제1항제3호"],["기간을 약정하지 않은 경우","위 최단 존속기간","제281조제1항"],["공작물의 종류와 구조를 정하지 않은 경우","건물 소유 목적(15년)으로 봄","제281조제2항"],["단축한 기간을 약정한 경우","최단 기간까지 연장","제280조제2항"],["갱신","갱신한 날부터 최단 존속기간보다 단축 불가","제284조"]]},{"종류":"비교","제목":"지상권 소멸 후 지상물 처리","왼쪽":{"이름":"지상권자의 청구","항목":["계약 갱신 청구(제283조제1항)","설정자가 갱신을 원하지 않으면 상당한 가액으로 지상물 매수 청구(제283조제2항)"]},"오른쪽":{"이름":"설정자의 청구와 의무","항목":["지상권자는 지상물을 수거하여 토지를 원상회복(제285조제1항)","설정자가 상당한 가액을 제공하여 매수를 청구하면 정당한 이유 없이 거절 불가(제285조제2항)"]}}],"함정":"지료는 성립요소가 아니어서 약정이 없으면 무상 지상권이다. 소멸청구는 2년 이상 연체해야 하고, 지상권이 저당권의 목적이면 저당권자에게 통지한 뒤 상당한 기간이 지나야 효력이 생긴다(제288조)."}},{"i":"S4-1-1-민법-19","r":"S4","g":1,"c":1,"n":59,"s":"민법","q":"甲은 그 소유 X건물의 일부에 관하여 乙 명의의 전세권을 설정하였다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["전세권의 존속기간을 15년으로 약정하면 15년간 존속한다.","건물에 대한 전세권의 존속기간을 6개월로 정하면 그 기간 동안 존속한다.","甲이 존속기간 만료 전 6월부터 1월까지 사이에 갱신거절의 통지를 하지 않으면 전세권은 전 전세권과 동일한 조건으로 다시 설정된 것으로 보고, 그 존속기간은 1년이다.","전세권이 소멸한 때에는 甲의 전세금 반환과 乙의 목적물 인도 및 전세권설정등기 말소등기에 필요한 서류의 교부는 동시이행의 관계에 있다.","전세권의 양도를 금지하는 약정이 설정행위에 있더라도 乙은 전세권을 타인에게 양도할 수 있다."],"a":[4],"L":"민2-6","o":"변형","x":{"한줄":"전세권이 소멸하면 설정자의 전세금 반환과 전세권자의 목적물 인도·말소등기 서류 교부가 동시이행 관계에 선다(제317조).","근거":[{"법령":"민법","조문":"제317조","원문":"전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다."},{"법령":"민법","조문":"제312조","원문":"①전세권의 존속기간은 10년을 넘지 못한다. 당사자의 약정기간이 10년을 넘는 때에는 이를 10년으로 단축한다.\n②건물에 대한 전세권의 존속기간을 1년 미만으로 정한 때에는 이를 1년으로 한다.\n③전세권의 설정은 이를 갱신할 수 있다. 그 기간은 갱신한 날로부터 10년을 넘지 못한다.\n④건물의 전세권설정자가 전세권의 존속기간 만료전 6월부터 1월까지 사이에 전세권자에 대하여 갱신거절의 통지 또는 조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 전세권의 존속기간은 그 정함이 없는 것으로 본다."},{"법령":"민법","조문":"제306조","원문":"전세권자는 전세권을 타인에게 양도 또는 담보로 제공할 수 있고 그 존속기간내에서 그 목적물을 타인에게 전전세 또는 임대할 수 있다. 그러나 설정행위로 이를 금지한 때에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세권의 존속기간은 10년을 넘지 못하고 넘으면 10년으로 단축된다(제312조제1항)."},{"번호":2,"판정":"틀림","설명":"건물 전세권의 존속기간을 1년 미만으로 정하면 1년으로 본다(제312조제2항)."},{"번호":3,"판정":"틀림","설명":"법정갱신된 전세권의 존속기간은 정함이 없는 것으로 본다(제312조제4항 후단)."},{"번호":4,"판정":"옳음","설명":"제317조가 정하는 동시이행 관계이다."},{"번호":5,"판정":"틀림","설명":"설정행위로 양도를 금지한 때에는 전세권을 양도할 수 없다(제306조 단서)."}],"개념":[{"종류":"표","제목":"전세권의 존속기간과 소멸","머리":["쟁점","내용","근거"],"행":[["최장 기간","10년, 넘으면 10년으로 단축","제312조제1항"],["건물 전세권의 최단 기간","1년 미만으로 정하면 1년","제312조제2항"],["갱신","갱신한 날부터 10년을 넘지 못함","제312조제3항"],["법정갱신","건물 전세권설정자가 만료 전 6월~1월 사이에 갱신거절 통지를 하지 않으면 동일 조건으로 재설정, 존속기간은 정함이 없음","제312조제4항"],["존속기간을 정하지 않은 경우","각 당사자가 언제든 소멸 통고, 통고를 받은 날부터 6월 경과 시 소멸","제313조"],["전세금 반환 지체","전세권자는 민사집행법에 따라 목적물의 경매 청구 가능","제318조"]]},{"종류":"흐름","제목":"건물 전세권의 법정갱신과 소멸","단계":[{"이름":"갱신거절 통지 기간","설명":"존속기간 만료 전 6월부터 1월까지 사이"},{"이름":"통지 없이 만료","설명":"전 전세권과 동일한 조건으로 다시 설정한 것으로 봄(제312조제4항)"},{"이름":"존속기간","설명":"정함이 없는 것으로 봄"},{"이름":"소멸 통고","설명":"각 당사자가 언제든 통고, 상대방이 받은 날부터 6월 경과 시 소멸(제313조)"},{"이름":"소멸 후 정산","설명":"전세금 반환과 목적물 인도·말소등기 서류 교부를 동시에 이행(제317조)"}]}],"함정":"법정갱신된 전세권은 존속기간의 정함이 없고 소멸 통고를 받은 날부터 6월이 지나야 소멸한다. 전세금 반환과 목적물 인도·말소서류 교부는 선후 없는 동시이행이다."}},{"i":"S4-1-1-민법-20","r":"S4","g":1,"c":1,"n":60,"s":"민법","q":"유치권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["유치권자가 채무자의 승낙 없이 유치물을 타인에게 대여한 경우, 채무자는 유치권의 소멸을 청구할 수 있다.","유치권자는 유치물을 경매할 수 없고 점유를 계속하는 방법으로만 채권의 변제를 압박할 수 있다.","건물 임차인이 임대인에게 지급한 임차보증금의 반환채권은 그 건물에 관하여 생긴 채권이므로 유치권이 성립한다.","유치권에 관한 규정은 강행규정이므로 유치권을 배제하기로 한 특약은 효력이 없다.","채무자 소유 부동산에 경매개시결정의 기입등기가 마쳐진 후에 점유를 이전받은 유치권자는 경매절차의 매수인에게 유치권을 주장할 수 있다."],"a":[1],"L":"민2-7","o":"변형","x":{"한줄":"유치권자가 채무자의 승낙 없이 유치물을 대여하거나 담보로 제공하면 채무자는 유치권의 소멸을 청구할 수 있다(제324조제2항·제3항).","근거":[{"법령":"민법","조문":"제320조","원문":"①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다.\n②전항의 규정은 그 점유가 불법행위로 인한 경우에 적용하지 아니한다."},{"법령":"민법","조문":"제322조제1항","원문":"유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있다."},{"법령":"민법","조문":"제324조","원문":"①유치권자는 선량한 관리자의 주의로 유치물을 점유하여야 한다.\n②유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다. 그러나 유치물의 보존에 필요한 사용은 그러하지 아니하다.\n③유치권자가 전2항의 규정에 위반한 때에는 채무자는 유치권의 소멸을 청구할 수 있다."},{"판례":"대법원 판례","요지":"임대차보증금·권리금 반환채권은 건물에 관하여 생긴 채권이 아니어서 유치권이 성립하지 않는다. 유치권 규정은 임의규정이어서 배제 특약은 유효하다. 경매개시결정의 기입등기 후에 점유를 취득한 유치권자는 압류의 처분금지 효력 때문에 경매절차의 매수인에게 유치권을 주장할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"승낙 없는 대여는 제324조제2항 위반이고, 채무자는 소멸을 청구할 수 있다(제324조제3항)."},{"번호":2,"판정":"틀림","설명":"유치권자는 채권의 변제를 받기 위해 유치물을 경매할 수 있다(제322조제1항)."},{"번호":3,"판정":"틀림","설명":"임차보증금 반환채권은 건물 자체에서 생긴 채권이 아니어서 견련성이 없고 유치권이 성립하지 않는다(판례)."},{"번호":4,"판정":"틀림","설명":"유치권 규정은 임의규정이어서 배제 특약은 유효하다(판례)."},{"번호":5,"판정":"틀림","설명":"경매개시결정의 기입등기 후에 점유를 취득한 유치권자는 매수인에게 대항할 수 없다(판례)."}],"개념":[{"종류":"표","제목":"유치권의 성립요건","머리":["요건","내용","근거"],"행":[["목적물","타인의 물건 또는 유가증권(채무자 소유일 필요 없음)","제320조제1항"],["견련성","그 물건이나 유가증권에 관하여 생긴 채권","제320조제1항"],["변제기","채권이 변제기에 있어야 함","제320조제1항"],["점유","점유를 계속해야 함, 점유를 잃으면 소멸","제328조"],["소극적 요건","점유가 불법행위로 인한 경우 제외, 유치권 배제 특약이 없을 것","제320조제2항, 판례"]]},{"종류":"표","제목":"유치권의 효력과 소멸","머리":["쟁점","내용","근거"],"행":[["경매권","변제를 받기 위해 유치물을 경매","제322조제1항"],["간이변제충당","정당한 이유가 있으면 감정인의 평가로 직접 변제충당을 법원에 청구, 미리 채무자에게 통지","제322조제2항"],["과실수취권","과실을 수취하여 다른 채권보다 먼저 변제에 충당, 먼저 이자 후 원본에 충당","제323조"],["선관의무","승낙 없는 사용·대여·담보제공 금지(보존에 필요한 사용 제외), 위반 시 채무자가 소멸 청구","제324조"],["비용상환","필요비는 소유자에게 상환 청구, 유익비는 가액 증가가 현존할 때 소유자의 선택","제325조"],["소멸시효","유치권의 행사는 피담보채권의 소멸시효 진행에 영향 없음","제326조"],["타담보 제공","채무자가 상당한 담보를 제공하고 소멸 청구","제327조"],["점유 상실","유치권 소멸","제328조"]]}],"함정":"유치권자는 경매권이 있다. 임차보증금 반환채권은 견련성이 없어 유치권이 성립하지 않고, 경매개시결정 기입등기 후에 점유를 취득한 유치권은 매수인에게 대항하지 못한다."}},{"i":"S4-1-1-민법-21","r":"S4","g":1,"c":1,"n":61,"s":"민법","q":"甲은 乙에 대한 2억 4천만원의 채권을 담보하기 위하여 乙소유의 X토지와 Y건물에 각각 1번 공동저당권을 취득하였다. 丙은 X토지에 피담보채권 2억원의 2번 저당권을, 丁은 Y건물에 피담보채권 1억원의 2번 저당권을 취득하였다. X토지의 경매대가 3억원과 Y건물의 경매대가 1억원이 동시에 배당되는 경우, 甲이 Y건물의 경매대가에서 배당받을 수 있는 금액은? (경매비용이나 이자 등은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["4천만원","6천만원","1억원","1억 2천만원","1억 8천만원"],"a":[2],"L":"민2-8","o":"변형","x":{"한줄":"공동저당 목적물을 동시에 배당하면 채권 2억 4천만원을 경매대가 3억 : 1억의 비율로 나누므로 甲은 Y건물에서 6천만원을 받는다.","근거":[{"법령":"민법","조문":"제368조제1항","원문":"동일한 채권의 담보로 수개의 부동산에 저당권을 설정한 경우에 그 부동산의 경매대가를 동시에 배당하는 때에는 각부동산의 경매대가에 비례하여 그 채권의 분담을 정한다."},{"법령":"민법","조문":"제368조제2항","원문":"전항의 저당부동산중 일부의 경매대가를 먼저 배당하는 경우에는 그 대가에서 그 채권전부의 변제를 받을 수 있다. 이 경우에 그 경매한 부동산의 차순위저당권자는 선순위저당권자가 전항의 규정에 의하여 다른 부동산의 경매대가에서 변제를 받을 수 있는 금액의 한도에서 선순위자를 대위하여 저당권을 행사할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"Y건물 경매대가 1억원에서 甲의 몫 6천만원을 뺀 나머지다. 이 금액을 받는 사람은 甲이 아니라 2번 저당권자 丁이다."},{"번호":2,"판정":"-","설명":"2억 4천만원 × 1억/(3억+1억) = 6천만원이다. 나머지 1억 8천만원은 X토지 대가에서 甲이 받는다(제368조제1항)."},{"번호":3,"판정":"-","설명":"Y건물만 먼저 경매하는 이시배당이면 甲이 Y대가 1억원 전부를 가져간다(제368조제2항). 이 문항은 동시배당이어서 이 값이 나오지 않는다."},{"번호":4,"판정":"-","설명":"채권액을 X, Y에 반씩 나눈 값이다. 분담 기준은 목적물 수가 아니라 경매대가 비율이다."},{"번호":5,"판정":"-","설명":"X토지에서 甲이 받는 분담액이다(2억 4천만원 × 3/4). Y건물 몫이 아니다."}],"개념":[{"종류":"계산","제목":"공동저당 동시배당 계산","단계":[{"설명":"분담 비율: 각 부동산의 경매대가 비율","식":"X : Y = 3억 : 1억","값":"3 : 1"},{"설명":"1번 공동저당권자 甲의 채권 2억 4천만원을 비율대로 분담","식":"X 2.4억 × 3/4, Y 2.4억 × 1/4","값":"X 1억 8천만원, Y 6천만원"},{"설명":"Y건물 대가에서 甲 몫을 빼고 후순위 丁에게 배당","식":"1억 - 6천만원 (丁 채권 1억원 한도)","값":"丁 4천만원"},{"설명":"X토지 대가에서 甲 몫을 빼고 후순위 丙에게 배당","식":"3억 - 1억 8천만원 (丙 채권 2억원 한도)","값":"丙 1억 2천만원"}]},{"종류":"표","제목":"공동저당 배당: 동시배당과 이시배당","머리":["구분","배당 방법","1번 공동저당권자","후순위 저당권자","근거"],"행":[["동시배당","각 부동산 경매대가 비율로 채권 분담","부동산별로 분담액만 배당","각 부동산에서 남은 금액을 순위대로","제368조제1항"],["이시배당(일부 먼저 경매)","먼저 경매한 부동산 대가에서 채권 전부 변제 가능","그 대가에서 전액 변제","동시배당이었다면 1번이 다른 부동산에서 받았을 금액 한도에서 1번 저당권을 대위","제368조제2항"],["이 문항에서 Y건물만 먼저 경매","Y대가 1억원 전부 甲에게","1억원","丁 0원, 대신 甲이 X에서 받을 4천만원 한도에서 甲의 X저당권 대위","제368조제2항"],["대위 한도 계산","동시배당 때 Y에서 받을 6천만원과 이시배당 때 받은 1억원의 차액","","丁 4천만원","제368조제2항"]]}],"함정":"채권액을 부동산 수로 균등하게 나눈 1억 2천만원을 고르기 쉽다. 비율의 기준은 경매대가다. Y대가 1억원을 甲이 전부 가져가는 이시배당 결과(1억원)와 섞는 경우도 많다. 6천만원이 甲 몫이고, 丁이 받는 돈은 남은 4천만원이다."}},{"i":"S4-1-1-민법-22","r":"S4","g":1,"c":1,"n":62,"s":"민법","q":"저당권의 피담보채권 범위에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["이자는 약정이 있으면 등기하지 않아도 후순위 저당권자에게 대항할 수 있다.","지연배상은 원본의 이행기일을 경과한 후의 2년분까지 저당권으로 담보된다.","저당목적물의 하자로 인한 손해배상금도 저당권이 담보한다.","채무불이행으로 인한 지연배상은 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다.","저당권의 실행비용은 저당권이 담보하는 범위에 속하지 않는다."],"a":[4],"L":"민2-8","o":"변형","x":{"한줄":"저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상, 실행비용을 담보하되 지연배상은 이행기 경과 후 1년분까지만 행사할 수 있다.","근거":[{"법령":"민법","조문":"제360조","원문":"저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."},{"법령":"부동산등기법","조문":"제75조제1항제4호","원문":"이자 및 그 발생기ㆍ지급시기"},{"법령":"민법","조문":"제357조제2항","원문":"전항의 경우에는 채무의 이자는 최고액 중에 산입한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이자는 저당권 등기사항이다(부동산등기법 제75조제1항제4호). 이자 약정을 등기하지 않으면 후순위 권리자 등 제3자에게 대항하지 못한다."},{"번호":2,"판정":"틀림","설명":"지연배상은 이행기 경과 후 1년분에 한한다(제360조 단서). 2년분이 아니다."},{"번호":3,"판정":"틀림","설명":"제360조가 열거한 담보 범위는 원본, 이자, 위약금, 채무불이행으로 인한 손해배상, 실행비용이다. 저당목적물의 하자로 생긴 손해배상금은 여기에 들어 있지 않다."},{"번호":4,"판정":"옳음","설명":"제360조 단서 그대로다. 1년분 제한은 지연배상에만 걸린다."},{"번호":5,"판정":"틀림","설명":"저당권의 실행비용은 제360조 본문이 열거한 담보 범위에 들어간다."}],"개념":[{"종류":"표","제목":"저당권이 담보하는 범위","머리":["항목","담보 여부","제한·요건","근거"],"행":[["원본","담보","피담보채권 자체","제360조"],["이자","담보","약정 + 등기해야 제3자에게 대항","제360조, 부동산등기법 제75조"],["위약금","담보","약정, 등기사항(손해배상 약정)","제360조"],["채무불이행 손해배상","담보","지연배상은 이행기 경과 후 1년분까지","제360조 단서"],["저당권 실행비용","담보","제한 없음","제360조"],["근저당의 이자","최고액에 산입","최고액을 넘지 못함","제357조제2항"]]},{"종류":"비교","제목":"저당권과 근저당권의 담보 범위","왼쪽":{"이름":"저당권","항목":["특정된 채권을 담보","채권액과 이자를 등기","지연배상은 이행기 경과 후 1년분 한도(제360조 단서)","피담보채권이 소멸하면 저당권도 소멸(제369조)"]},"오른쪽":{"이름":"근저당권","항목":["채무의 최고액만 정하고 확정은 장래로 보류(제357조제1항)","이자는 최고액 중에 산입한 것으로 봄(제357조제2항)","확정 전 채무의 소멸·이전은 저당권에 영향 없음","확정 이후에는 확정된 채권을 최고액 범위에서 담보"]}}],"함정":"지연배상 기간을 2년으로 바꿔 놓은 선지와 실행비용을 담보 범위에서 빼 놓은 선지에 걸린다. 이자는 약정만으로 제3자에게 대항하지 못하고 등기해야 한다는 점도 놓치기 쉽다."}},{"i":"S4-1-1-민법-23","r":"S4","g":1,"c":1,"n":63,"s":"민법","q":"저당권의 효력이 미치는 목적물의 범위에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["당사자는 설정계약으로 저당권의 효력이 종물에 미치지 않는 것으로 정할 수 있다.","저당권의 목적토지가 ｢공익사업을 위한 토지 등의 취득 및 보상에 관한 법률｣에 따라 협의취득된 경우, 저당권자는 그 보상금청구권에 대해 물상대위권을 행사할 수 없다.","건물 소유를 목적으로 토지를 임차한 자가 그 토지 위에 소유하는 건물에 저당권을 설정한 경우 건물 소유를 목적으로 한 토지 임차권에도 저당권의 효력이 미친다.","저당목적물의 변형물인 금전에 대해 이미 제3자가 압류한 경우 저당권자는 물상대위권을 행사할 수 없다.","저당부동산에 대한 압류 이후의 저당권설정자의 저당부동산에 관한 차임채권에도 저당권의 효력이 미친다."],"a":[4],"L":"민2-8","o":"기출","x":{"한줄":"물상대위의 압류는 금전이 설정자에게 지급되기 전에 특정되게 하려는 것이어서, 다른 채권자가 먼저 압류했더라도 저당권자는 물상대위권을 행사할 수 있다.","근거":[{"법령":"민법","조문":"제358조","원문":"저당권의 효력은 저당부동산에 부합된 물건과 종물에 미친다. 그러나 법률에 특별한 규정 또는 설정행위에 다른 약정이 있으면 그러하지 아니하다."},{"법령":"민법","조문":"제359조","원문":"저당권의 효력은 저당부동산에 대한 압류가 있은 후에 저당권설정자가 그 부동산으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다. 그러나 저당권자가 그 부동산에 대한 소유권, 지상권 또는 전세권을 취득한 제삼자에 대하여는 압류한 사실을 통지한 후가 아니면 이로써 대항하지 못한다."},{"법령":"민법","조문":"제342조","원문":"질권은 질물의 멸실, 훼손 또는 공용징수로 인하여 질권설정자가 받을 금전 기타 물건에 대하여도 이를 행사할 수 있다. 이 경우에는 그 지급 또는 인도전에 압류하여야 한다."},{"판례":"대법원 판례(물상대위)","요지":"저당목적물의 변형물에 대해 다른 채권자가 압류·전부명령을 얻었더라도 금전이 아직 지급되지 않았다면 저당권자는 배당요구의 종기까지 물상대위권을 행사할 수 있다. 협의취득은 공용징수가 아니라 매매에 해당하므로 보상금청구권에는 물상대위권이 미치지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제358조 단서가 설정행위로 종물에 효력이 미치지 않게 정할 수 있다고 한다."},{"번호":2,"판정":"옳음","설명":"협의취득은 매매의 성질을 가져 제342조의 공용징수에 해당하지 않으므로 물상대위가 인정되지 않는다(판례)."},{"번호":3,"판정":"옳음","설명":"건물에 설정한 저당권의 효력은 그 건물의 소유에 필요한 종된 권리인 토지임차권에도 미친다(판례)."},{"번호":4,"판정":"틀림","설명":"제3자가 먼저 압류했어도 저당권자는 금전이 지급되기 전이면 물상대위권을 행사할 수 있다(제370조, 제342조, 판례)."},{"번호":5,"판정":"옳음","설명":"저당부동산 압류 이후의 차임채권은 제359조의 과실로서 저당권의 효력이 미친다."}],"개념":[{"종류":"표","제목":"저당권의 효력이 미치는 범위","머리":["대상","미치는지","내용","근거"],"행":[["부합물","미침","부동산에 부합된 물건","제358조"],["종물","미침","설정행위로 제외 가능","제358조"],["종된 권리","미침","건물 저당권은 건물 소유를 위한 토지임차권에도 미침(판례)","판례"],["과실","압류 후에만 미침","압류 후 설정자가 수취한 과실·수취할 수 있는 과실","제359조"],["물상대위","미침","멸실·훼손·공용징수로 설정자가 받을 금전. 지급 전 압류","제370조, 제342조"],["협의취득 보상금","미치지 않음","공용징수가 아님(판례)","판례"]]},{"종류":"흐름","제목":"물상대위권 행사","단계":[{"이름":"변형물 발생","설명":"목적물의 멸실·훼손·공용징수로 설정자가 금전 기타 물건을 받게 됨"},{"이름":"지급·인도 전 압류","설명":"저당권자가 지급 또는 인도 전에 압류(판례는 배당요구의 종기까지 압류 또는 배당요구)"},{"이름":"특정","설명":"압류로 금전이 설정자의 일반재산과 구별되어 특정됨"},{"이름":"우선변제","설명":"저당권자가 그 금전에서 다른 채권자보다 먼저 변제"}]}],"함정":"제3자가 이미 압류했으면 저당권자가 늦었다고 보기 쉽다. 압류 요구는 지급 전에 금전을 특정시키려는 것이어서 다른 채권자의 압류가 있어도 저당권자는 권리를 행사한다. 협의취득 보상금에 물상대위가 안 된다는 선지는 옳다."}},{"i":"S4-1-1-민법-24","r":"S4","g":1,"c":1,"n":64,"s":"민법","q":"위험부담에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["계약 체결 전부터 이미 불능이었던 경우에도 위험부담의 법리가 적용된다.","채권자의 책임 있는 사유로 채무가 이행불능이 된 경우 채무자는 상대방의 이행을 청구하지 못한다.","당사자 쌍방의 책임 없는 사유로 매도인의 채무가 이행불능이 되어 매매계약이 종료된 경우, 매수인은 이미 지급한 대금의 반환을 청구할 수 있다.","대상청구권을 행사하는 채권자는 반대급부의무를 면한다.","채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 채무가 이행불능이 된 경우 채무자는 상대방의 이행을 청구하지 못한다."],"a":[3],"L":"민3-1","o":"변형","x":{"한줄":"쌍방 무책 이행불능이면 채무자는 반대급부를 청구하지 못하므로, 매수인이 이미 낸 대금은 법률상 원인이 없어져 부당이득으로 돌려받는다.","근거":[{"법령":"민법","조문":"제537조","원문":"쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제538조제1항","원문":"쌍무계약의 당사자 일방의 채무가 채권자의 책임있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에도 같다."},{"법령":"민법","조문":"제535조제1항","원문":"목적이 불능한 계약을 체결할 때에 그 불능을 알았거나 알 수 있었을 자는 상대방이 그 계약의 유효를 믿었음으로 인하여 받은 손해를 배상하여야 한다. 그러나 그 배상액은 계약이 유효함으로 인하여 생길 이익액을 넘지 못한다."},{"판례":"대법원 판례(대상청구권)","요지":"이행불능의 원인이 된 사정으로 채무자가 이익을 얻은 경우 채권자는 대상청구권을 행사할 수 있고, 이 경우 채권자도 자기의 반대급부를 이행해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"위험부담은 계약 성립 후에 생긴 후발적 불능에 적용된다. 계약 체결 때 이미 불능이었으면 계약체결상의 과실 문제다(제535조)."},{"번호":2,"판정":"틀림","설명":"채권자의 책임 있는 사유로 불능이 되면 채무자는 상대방의 이행을 청구할 수 있다(제538조제1항)."},{"번호":3,"판정":"옳음","설명":"제537조에 따라 매도인은 대금을 청구하지 못하고, 이미 받은 대금은 부당이득이 되어 반환해야 한다."},{"번호":4,"판정":"틀림","설명":"대상청구권을 행사하는 채권자는 자기 반대급부를 이행해야 한다(판례)."},{"번호":5,"판정":"틀림","설명":"채권자 수령지체 중 쌍방 무책으로 불능이 된 경우에도 채무자는 반대급부를 청구할 수 있다(제538조제1항 후문)."}],"개념":[{"종류":"표","제목":"이행불능의 책임 소재에 따른 효과","머리":["불능 원인","채무자의 반대급부청구","채권자의 구제","근거"],"행":[["쌍방 무책","못 함(채무자위험부담주의)","이미 이행한 급부는 부당이득으로 반환","제537조"],["채권자 책임","할 수 있음. 채무를 면해 얻은 이익은 상환","-","제538조"],["수령지체 중 쌍방 무책","할 수 있음. 얻은 이익은 상환","-","제538조제1항 후문"],["채무자 책임","-","계약 해제, 손해배상","제546조, 제390조"],["계약 체결 때 이미 불능","위험부담 문제가 아님","신뢰이익 배상(이행이익 한도)","제535조"]]},{"종류":"비교","제목":"위험부담과 대상청구권","왼쪽":{"이름":"위험부담(제537조)","항목":["쌍방 무책 이행불능 때 반대급부 위험을 누가 지는가의 문제","채무자는 반대급부를 청구하지 못함","쌍무계약에 적용, 편무계약은 적용 없음"]},"오른쪽":{"이름":"대상청구권","항목":["이행불능을 원인으로 채무자가 얻은 이익을 채권자가 넘겨받는 제도","명문 규정 없이 판례가 인정","행사하면 채권자는 반대급부를 이행해야 함"]}}],"함정":"우리 민법이 채무자위험부담주의여서 대상청구권도 부정된다고 단정하기 쉽다. 판례는 대상청구권을 인정하되 반대급부 이행을 조건으로 한다. 수령지체 중 쌍방 무책 불능은 제537조가 아니라 제538조로 처리하는 점도 자주 틀린다."}},{"i":"S4-1-1-민법-25","r":"S4","g":1,"c":1,"n":65,"s":"민법","q":"약관에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["고객에게 부당하게 과중한 지연 손해금 등의 손해배상의무를 부담시키는 약관 조항은 무효로 한다.","약관내용이 명백하지 못한 때에는 약관작성자에게 불리하게 제한해석해야 한다.","보통거래약관은 신의성실의 원칙에 따라 그 약관의 목적과 취지를 고려하여 공정하고 합리적으로 해석해야 한다.","고객에게 부당하게 불리한 약관조항은 공정을 잃은 것으로 추정된다.","보통거래약관의 내용은 개개 계약체결자의 의사나 구체적인 사정을 고려하여 구체적ㆍ주관적으로 해석해야 한다."],"a":[5],"L":"민3-1","o":"기출","x":{"한줄":"약관은 고객에 따라 다르게 해석하지 않고 객관적·획일적으로 해석하므로, 개별 계약체결자의 주관적 사정을 고려한다는 설명이 틀리다.","근거":[{"법령":"약관의 규제에 관한 법률","조문":"제5조제1항","원문":"약관은 신의성실의 원칙에 따라 공정하게 해석되어야 하며 고객에 따라 다르게 해석되어서는 아니 된다."},{"법령":"약관의 규제에 관한 법률","조문":"제5조제2항","원문":"약관의 뜻이 명백하지 아니한 경우에는 고객에게 유리하게 해석되어야 한다."},{"법령":"약관의 규제에 관한 법률","조문":"제6조제2항제1호","원문":"약관의 내용 중 고객에게 부당하게 불리한 조항은 공정성을 잃은 것으로 추정된다."},{"법령":"약관의 규제에 관한 법률","조문":"제8조","원문":"고객에게 부당하게 과중한 지연 손해금 등의 손해배상의무를 부담시키는 약관의 조항은 무효로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지연 손해금을 고객에게 부당하게 과중하게 부담시키는 조항은 무효다(제8조)."},{"번호":2,"판정":"옳음","설명":"뜻이 명백하지 않은 약관은 작성자에게 불리하게, 곧 고객에게 유리하게 해석한다(제5조제2항)."},{"번호":3,"판정":"옳음","설명":"약관은 신의성실의 원칙에 따라 공정하고 합리적으로, 목적과 취지를 고려해 해석한다(제5조제1항, 판례)."},{"번호":4,"판정":"옳음","설명":"고객에게 부당하게 불리한 조항은 공정성을 잃은 것으로 추정된다(제6조제2항제1호)."},{"번호":5,"판정":"틀림","설명":"약관은 고객에 따라 다르게 해석되어서는 안 되고(제5조제1항), 판례는 객관적·획일적 해석을 원칙으로 한다. 개별 당사자의 의사나 사정은 해석 기준이 아니다."}],"개념":[{"종류":"표","제목":"약관의 규제에 관한 법률 핵심 조문","머리":["쟁점","내용","조문"],"행":[["해석의 원칙","신의성실, 공정. 고객에 따라 다르게 해석하지 않음(객관적·획일적)","제5조제1항"],["작성자 불이익 원칙","뜻이 명백하지 않으면 고객에게 유리하게","제5조제2항"],["개별약정 우선","계약 당사자가 합의한 사항은 약관보다 우선","제4조"],["불공정 약관","신의성실에 반해 공정성을 잃으면 무효. 고객에게 부당하게 불리하면 추정","제6조"],["면책조항 금지","사업자의 고의·중과실 책임 배제 조항 등 무효","제7조"],["손해배상액 예정","부당하게 과중한 지연 손해금 부담 조항 무효","제8조"]]},{"종류":"비교","제목":"약관 해석과 일반 계약 해석","왼쪽":{"이름":"약관 해석","항목":["객관적·획일적으로 해석","고객에 따라 다르게 해석하지 않음","뜻이 불명확하면 작성자 불이익 원칙"]},"오른쪽":{"이름":"개별 계약 해석","항목":["당사자의 진정한 의사를 탐구","구체적 사정과 거래 경위를 고려","개별약정이 있으면 약관보다 우선"]}}],"함정":"약관도 계약이니 당사자 의사를 살펴 구체적으로 해석한다고 고르기 쉽다. 약관은 다수 고객에게 같은 내용으로 쓰이므로 객관적·획일적으로 해석한다. 작성자 불이익 원칙을 틀린 선지로 오인하는 경우도 있다."}},{"i":"S4-1-1-민법-26","r":"S4","g":1,"c":1,"n":66,"s":"민법","q":"민법상 계약에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["매매계약은 요물계약이다.","도급계약은 편무계약이다.","교환계약은 무상계약이다.","증여계약은 요식계약이다.","임대차계약은 유상계약이다."],"a":[5],"L":"민3-1","o":"기출","x":{"한줄":"임대차는 임대인이 사용·수익하게 할 의무를, 임차인이 차임을 지급할 의무를 서로 대가로 부담하는 유상계약이다.","근거":[{"법령":"민법","조문":"제618조","원문":"임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제563조","원문":"매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제664조","원문":"도급은 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제596조","원문":"교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매는 합의만으로 성립하는 낙성계약이다(제563조). 물건 인도가 있어야 성립하는 요물계약이 아니다."},{"번호":2,"판정":"틀림","설명":"도급은 일의 완성과 보수 지급이 서로 대가인 쌍무계약이다(제664조)."},{"번호":3,"판정":"틀림","설명":"교환은 서로 재산권을 이전하는 유상계약이다(제596조)."},{"번호":4,"판정":"틀림","설명":"증여는 일정한 방식을 요하지 않는 불요식계약이다. 서면이 없으면 각 당사자가 해제할 수 있을 뿐이다(제555조)."},{"번호":5,"판정":"옳음","설명":"임대차는 사용·수익과 차임이 대가 관계에 있는 유상계약이며 쌍무계약이다(제618조)."}],"개념":[{"종류":"표","제목":"전형계약의 성질 분류","머리":["계약","쌍무·편무","유상·무상","낙성·요물","근거"],"행":[["매매","쌍무","유상","낙성","제563조"],["교환","쌍무","유상","낙성","제596조"],["임대차","쌍무","유상","낙성","제618조"],["도급","쌍무","유상","낙성","제664조"],["증여","편무","무상","낙성","제554조"],["사용대차","편무","무상","낙성","제609조"],["무상임치","편무","무상","낙성","제693조"],["현상광고(통설)","편무","-","요물","제675조"]]}],"함정":"증여를 요식계약으로, 도급을 편무계약으로 오인하는 선지가 자주 나온다. 서면은 증여의 성립요건이 아니라 해제를 막는 요건이다. 매매를 요물계약으로 쓴 선지도 대표적인 오답이다."}},{"i":"S4-1-1-민법-27","r":"S4","g":1,"c":1,"n":67,"s":"민법","q":"계약의 종류와 그에 해당하는 예가 잘못 짝지어진 것은?","b":null,"bs":"없음","img":[],"ch":["쌍무계약 - 교환계약","유상계약 - 도급계약","낙성계약 - 임대차계약","무상계약 - 증여계약","요물계약 - 사용대차계약"],"a":[5],"L":"민3-1","o":"변형","x":{"한줄":"사용대차는 당사자의 합의만으로 성립하는 낙성계약이므로 요물계약의 예가 아니다.","근거":[{"법령":"민법","조문":"제609조","원문":"사용대차는 당사자 일방이 상대방에게 무상으로 사용, 수익하게 하기 위하여 목적물을 인도할 것을 약정하고 상대방은 이를 사용, 수익한 후 그 물건을 반환할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제596조","원문":"교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제554조","원문":"증여는 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 이를 승낙함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"교환은 쌍방이 재산권을 서로 이전할 의무를 지는 쌍무계약이다(제596조)."},{"번호":2,"판정":"옳음","설명":"도급은 보수를 대가로 일을 완성하는 유상계약이다(제664조)."},{"번호":3,"판정":"옳음","설명":"임대차는 합의로 성립하는 낙성계약이다(제618조)."},{"번호":4,"판정":"옳음","설명":"증여는 대가 없이 재산을 수여하는 무상계약이다(제554조)."},{"번호":5,"판정":"틀림","설명":"사용대차는 목적물을 인도할 것을 약정함으로써 성립한다(제609조). 인도는 성립요건이 아니라 사용대주의 의무 내용이다. 요물계약의 대표 예는 현상광고(통설)와 계약금계약이다."}],"개념":[{"종류":"표","제목":"계약 분류별 대표 예","머리":["분류 기준","종류","대표 예","구별 포인트"],"행":[["채무 부담","쌍무 / 편무","매매·교환·임대차·도급 / 증여·사용대차·무상임치","서로 대가적 채무를 지는지"],["대가 유무","유상 / 무상","매매·임대차 / 증여·사용대차","재산상 출연이 서로 대가인지"],["성립 요건","낙성 / 요물","매매·임대차·사용대차 / 현상광고(통설)·계약금계약","합의만으로 성립하는지, 물건 교부가 필요한지"],["방식","불요식 / 요식","증여·매매 / 법에 정한 방식이 필요한 계약","서면 등이 성립요건인지"]]}],"함정":"사용대차에 '인도'가 들어 있어서 요물계약처럼 읽힌다. 조문은 인도할 것을 약정하면 효력이 생긴다고 쓴다. 요물계약은 합의 외에 물건 교부가 있어야 성립하는 계약이다."}},{"i":"S4-1-1-민법-28","r":"S4","g":1,"c":1,"n":68,"s":"민법","q":"계약의 해지에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["계약을 해지하면 계약은 장래에 대하여 효력을 잃는다.","계약을 해지한 당사자는 상대방에게 손해배상을 청구할 수 없다.","당사자 일방이 수인인 경우 계약의 해지는 그 전원으로부터 또는 전원에 대하여 하여야 한다.","합의해지에 따른 원상회복에서 반환할 금전에는 특약이 없는 한 받은 날로부터의 이자를 가산해야 하는 것은 아니다.","기간의 약정이 없는 토지임대차에서 임대인이 해지를 통고한 경우 그 통고를 받은 날부터 6개월이 지나면 해지의 효력이 생긴다."],"a":[2],"L":"민3-1","o":"변형","x":{"한줄":"계약의 해지는 손해배상 청구에 영향을 미치지 않으므로 해지한 당사자도 손해배상을 청구할 수 있다.","근거":[{"법령":"민법","조문":"제551조","원문":"계약의 해지 또는 해제는 손해배상의 청구에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제550조","원문":"당사자 일방이 계약을 해지한 때에는 계약은 장래에 대하여 그 효력을 잃는다."},{"법령":"민법","조문":"제547조제1항","원문":"당사자의 일방 또는 쌍방이 수인인 경우에는 계약의 해지나 해제는 그 전원으로부터 또는 전원에 대하여 하여야 한다."},{"법령":"민법","조문":"제635조","원문":"①임대차기간의 약정이 없는 때에는 당사자는 언제든지 계약해지의 통고를 할 수 있다. ②상대방이 전항의 통고를 받은 날로부터 다음 각호의 기간이 경과하면 해지의 효력이 생긴다. 1. 토지, 건물 기타 공작물에 대하여는 임대인이 해지를 통고한 경우에는 6월, 임차인이 해지를 통고한 경우에는 1월"}],"선지":[{"번호":1,"판정":"옳음","설명":"해지는 장래에 대해서만 효력이 있어 이미 이행된 부분의 원상회복의무는 생기지 않는다(제550조)."},{"번호":2,"판정":"틀림","설명":"해지는 손해배상 청구에 영향을 미치지 않는다(제551조). 채무불이행 해지라면 손해배상도 청구한다."},{"번호":3,"판정":"옳음","설명":"해지권은 불가분이다. 당사자 일방이 여럿이면 전원으로부터, 또는 전원에 대하여 해지한다(제547조제1항)."},{"번호":4,"판정":"옳음","설명":"합의해지는 제548조제2항의 이자 가산 규정이 당연히 적용되지 않는다. 이자는 특약이 있어야 붙는다(판례)."},{"번호":5,"판정":"옳음","설명":"기간 약정 없는 토지임대차에서 임대인이 통고하면 6개월, 임차인이 통고하면 1개월이 지나 해지된다(제635조제2항제1호)."}],"개념":[{"종류":"비교","제목":"해지와 해제","왼쪽":{"이름":"해지","항목":["계속적 계약(임대차·고용·위임 등)에 적용","장래에 대해서만 효력(제550조)","원상회복의무 없음","손해배상 청구에 영향 없음(제551조)"]},"오른쪽":{"이름":"해제","항목":["일시적 계약(매매 등)에 적용","소급하여 계약이 소멸(판례: 직접효과설)","원상회복의무, 반환 금전에 받은 날부터 이자(제548조)","손해배상 청구에 영향 없음(제551조)"]}},{"종류":"표","제목":"기간 약정 없는 임대차의 해지통고 기간(제635조)","머리":["목적물","통고한 사람","효력 발생"],"행":[["토지·건물 기타 공작물","임대인","통고 받은 날부터 6개월"],["토지·건물 기타 공작물","임차인","통고 받은 날부터 1개월"],["동산","임대인·임차인","통고 받은 날부터 5일"],["묵시갱신된 임대차","당사자","제635조에 따라 해지통고 가능(제639조제1항 단서)"]]}],"함정":"해지하면 계약관계가 끝나니 손해배상도 못 받는다고 생각하기 쉽다. 제551조는 해지·해제가 손해배상 청구와 별개라고 정한다. 합의해지의 이자 문제도 법정해제와 섞어 틀린다."}},{"i":"S4-1-1-민법-29","r":"S4","g":1,"c":1,"n":69,"s":"민법","q":"甲은 자신의 X토지를 乙에게 매도하면서 계약금을 수령하였다. 계약금에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["계약금을 지급하기로 약정만 하고 실제로 교부하지 않은 경우에도 甲은 계약금의 배액을 상환하고 매매계약을 해제할 수 있다.","甲과 乙 사이의 매매계약이 무효이거나 취소되면 계약금계약도 효력을 잃는다.","甲과 乙은 약정으로 해약금에 기한 해제권을 배제할 수 있다.","乙이 중도금을 지급하여 이행에 착수한 후에는 甲이 계약금의 배액을 상환하고 매매계약을 해제할 수 없다.","甲과 乙이 계약금을 위약금으로 약정한 경우 그 위약금은 손해배상액의 예정으로 추정되고, 부당히 과다하면 법원이 감액할 수 있다."],"a":[1],"L":"민3-2","o":"변형","x":{"한줄":"계약금계약은 금전 기타 물건을 실제로 교부해야 성립하므로, 교부 없이 지급을 약정만 한 단계에서는 해약금에 기한 해제를 할 수 없다.","근거":[{"법령":"민법","조문":"제565조","원문":"①매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다. ②제551조의 규정은 전항의 경우에 이를 적용하지 아니한다."},{"법령":"민법","조문":"제398조제2항·제4항","원문":"②손해배상의 예정액이 부당히 과다한 경우에는 법원은 적당히 감액할 수 있다. ④위약금의 약정은 손해배상액의 예정으로 추정한다."},{"판례":"대법원 판례(계약금계약)","요지":"계약금계약은 계약금 교부로 성립하는 요물계약이다. 교부가 없으면 계약금 지급 약정만으로는 제565조의 해약금 해제를 할 수 없다. 계약금계약은 매매계약에 종된 계약이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"교부 없이 약정만 있으면 계약금계약이 성립하지 않아 배액 상환으로 해제할 수 없다(제565조제1항, 판례)."},{"번호":2,"판정":"옳음","설명":"계약금계약은 매매계약의 종된 계약이어서 주된 계약이 무효·취소되면 함께 효력을 잃는다."},{"번호":3,"판정":"옳음","설명":"제565조제1항은 '다른 약정이 없는 한'이라고 정한다. 해약금 해제권을 배제하는 약정은 유효하다."},{"번호":4,"판정":"옳음","설명":"상대방(乙)이 이행에 착수한 뒤에는 해약금 해제를 할 수 없다(제565조제1항). 중도금 지급은 이행의 착수다."},{"번호":5,"판정":"옳음","설명":"위약금 약정은 손해배상액의 예정으로 추정되고(제398조제4항), 부당히 과다하면 법원이 감액할 수 있다(제398조제2항)."}],"개념":[{"종류":"표","제목":"계약금의 성질","머리":["성질","내용","요건","근거"],"행":[["증약금","계약이 체결되었다는 증거","계약금 교부(모든 계약금의 기본 성질)","판례"],["해약금","이행에 착수할 때까지 교부자는 포기, 수령자는 배액 상환으로 해제","계약금 교부 + 특약 없음. 추정 규정","제565조제1항"],["위약금","채무불이행 시 몰취·손해배상액의 예정","특약 필요. 예정으로 추정, 감액 가능","제398조제2항·제4항"],["해약금 해제의 효과","손해배상 청구 불가","제551조 적용 배제","제565조제2항"]]},{"종류":"비교","제목":"해약금 해제와 채무불이행 해제","왼쪽":{"이름":"해약금 해제(제565조)","항목":["이행착수 전까지만 가능","교부자는 계약금 포기, 수령자는 배액 상환","손해배상 청구 불가","당사자가 배제 가능"]},"오른쪽":{"이름":"채무불이행 해제(제544조 이하)","항목":["상대방의 채무불이행이 있어야 가능","이행착수 후에도 가능","손해배상 청구 가능(제551조)","원상회복의무 발생"]}}],"함정":"계약금을 주기로 하는 약정을 하면 이미 계약금계약이 있는 것으로 보기 쉽다. 계약금계약은 실제 교부로 성립한다. 중도금 지급 약정만 있고 지급이 없는 단계와 지급한 단계를 섞는 오답도 많다."}},{"i":"S4-1-1-민법-30","r":"S4","g":1,"c":1,"n":70,"s":"민법","q":"甲은 그 소유의 X부동산에 관하여 乙과 매매의 일방예약을 체결하면서 예약완결권은 乙이 가지고 20년 내에 행사하기로 약정하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 예약체결시로부터 1년 뒤에 예약완결권을 행사한 경우, 매매는 예약체결시로 소급하여 그 효력이 발생한다.","乙의 예약완결권은 형성권에 속하므로 甲과의 약정에도 불구하고 그 행사기간은 10년으로 단축된다.","乙이 가진 예약완결권은 재산권이므로 특별한 사정이 없는 한 타인에게 양도할 수 있다.","乙이 예약완결권을 행사기간 내에 행사하였는지에 관해 甲의 주장이 없다면 법원은 이를 고려할 수 없다.","乙이 예약완결권을 행사하더라도 甲의 승낙이 있어야 비로소 매매계약은 그 효력이 발생한다."],"a":[3],"L":"민3-2","o":"기출","x":{"한줄":"예약완결권은 재산권이므로 특별한 사정이 없으면 양도할 수 있다.","근거":[{"법령":"민법","조문":"제564조제1항","원문":"매매의 일방예약은 상대방이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다."},{"판례":"대법원 판례(예약완결권)","요지":"예약완결권은 형성권으로서 행사기간은 제척기간이다. 당사자가 기간을 약정하면 그에 따르고, 약정이 없으면 예약이 성립한 때부터 10년이다. 제척기간은 직권조사사항이다. 예약완결권은 재산권으로서 양도할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매의 효력은 완결의 의사표시가 있는 때에 생긴다(제564조제1항). 예약체결시로 소급하지 않는다."},{"번호":2,"판정":"틀림","설명":"당사자가 행사기간을 약정하면 그 기간(20년)에 따른다. 약정이 없을 때 10년이다(판례)."},{"번호":3,"판정":"옳음","설명":"예약완결권은 재산권이어서 특별한 사정이 없는 한 양도할 수 있다(판례)."},{"번호":4,"판정":"틀림","설명":"제척기간은 직권조사사항이어서 당사자의 주장이 없어도 법원이 고려한다(판례)."},{"번호":5,"판정":"틀림","설명":"일방예약은 상대방이 완결의 의사표시를 하면 예약자의 승낙 없이 매매의 효력이 생긴다(제564조제1항)."}],"개념":[{"종류":"표","제목":"매매의 일방예약과 예약완결권","머리":["쟁점","내용","근거"],"행":[["성립","상대방이 완결의 의사표시를 하는 때 매매의 효력 발생(예약자의 승낙 불요)","제564조제1항"],["성질","형성권, 재산권(양도 가능)","판례"],["행사기간","약정이 있으면 그 기간, 없으면 예약성립시부터 10년. 제척기간","판례"],["기간 약정 없을 때 최고","예약자는 상당한 기간을 정해 확답을 최고, 답이 없으면 예약 효력 상실","제564조제2항·제3항"],["제척기간 도과","당사자 주장 없어도 법원이 직권으로 조사","판례"],["효력 발생 시점","완결 의사표시 시점(소급 없음)","제564조제1항"]]},{"종류":"흐름","제목":"예약완결권 행사 절차","단계":[{"이름":"일방예약 체결","설명":"예약자와 상대방이 장래 매매를 성립시킬 권리(예약완결권)를 상대방에게 부여"},{"이름":"행사기간 확인","설명":"약정 기간이 있으면 그에 따르고, 없으면 예약 성립 후 10년"},{"이름":"완결 의사표시","설명":"상대방이 매매를 완결하겠다고 예약자에게 표시"},{"이름":"매매 성립","설명":"의사표시가 도달한 때 매매의 효력 발생, 예약자의 승낙 불요"}]}],"함정":"형성권은 모두 10년으로 본다고 기억하면 약정 기간(20년)이 있는 이 사례에서 틀린다. 약정이 없을 때의 보충 기간이 10년이다. 제척기간 도과를 상대방이 주장해야 한다는 선지도 함정이다."}},{"i":"S4-1-1-민법-31","r":"S4","g":1,"c":1,"n":71,"s":"민법","q":"甲은 자신의 X부동산을 乙에게 5억원에 매도하면서 계약금 5천만원을 수령하였고, 중도금은 2개월 뒤에 받기로 하였다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙이 달리 약정하지 않았다면, 乙이 중도금을 지급하기 전이고 甲도 이행에 착수하지 않았다면 乙은 계약금을 포기하고 매매계약을 해제할 수 있다.","甲이 계약금의 배액을 제공하며 해제하려 했으나 乙이 수령을 거절한 경우, 甲은 반드시 배액을 공탁해야 해제의 효력이 생긴다.","乙이 중도금을 지급하여 이행에 착수한 후에는 甲이 계약금의 배액을 상환하더라도 해제할 수 없다.","乙이 계약금을 포기하고 해제한 경우 甲은 손해가 있더라도 그 배상을 청구하지 못한다.","甲이 해약금에 기하여 해제하려면 이미 받은 계약금 5천만원에 같은 금액을 더한 1억원을 상환해야 한다."],"a":[2],"L":"민3-2","o":"변형","x":{"한줄":"배액 상환은 이행의 제공으로 충분하고, 상대방이 수령을 거절하더라도 공탁까지 해야 해제의 효력이 생기는 것은 아니다.","근거":[{"법령":"민법","조문":"제565조","원문":"①매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다. ②제551조의 규정은 전항의 경우에 이를 적용하지 아니한다."},{"판례":"대법원 판례(해약금 해제)","요지":"매도인이 계약금의 배액을 상환하여 해제하려면 배액의 현실 제공이 있어야 한다. 상대방이 수령을 거절해도 공탁까지 할 필요는 없다. 상대방이 이행에 착수한 후에는 해약금 해제를 할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"쌍방 모두 이행에 착수하지 않았으므로 乙은 계약금을 포기하고 해제할 수 있다(제565조제1항)."},{"번호":2,"판정":"틀림","설명":"현실 제공으로 충분하다. 수령 거절 시 공탁은 해제의 요건이 아니다(판례)."},{"번호":3,"판정":"옳음","설명":"상대방 乙의 이행착수(중도금 지급) 후에는 甲의 해약금 해제가 막힌다(제565조제1항, 판례)."},{"번호":4,"판정":"옳음","설명":"해약금 해제에는 손해배상 청구에 관한 제551조가 적용되지 않는다(제565조제2항)."},{"번호":5,"판정":"옳음","설명":"'그 배액'은 수령한 계약금의 2배, 곧 1억원이다(제565조제1항)."}],"개념":[{"종류":"흐름","제목":"해약금에 기한 해제 절차","단계":[{"이름":"계약금 교부","설명":"계약 당시 금전 기타 물건을 계약금 명목으로 교부(요물계약)"},{"이름":"해제 시기 판단","설명":"해제하려는 상대방이 이행에 착수하기 전이어야 함"},{"이름":"해제 의사표시","설명":"교부자: 계약금 포기 / 수령자: 배액 상환(현실 제공)"},{"이름":"해제 효과","설명":"계약 소멸, 손해배상 청구 불가(제565조제2항)"}]},{"종류":"표","제목":"해약금 해제의 요건과 한계","머리":["쟁점","내용","근거"],"행":[["이행착수의 의미","상대방이 이행에 착수하기 전까지 가능. 중도금 지급은 이행착수","제565조제1항, 판례"],["배액 상환","수령한 금액의 2배. 현실 제공으로 충분하고 공탁은 불요","제565조제1항, 판례"],["특약","해약금 해제권을 배제하는 약정 가능","제565조제1항"],["손해배상","해약금 해제에는 청구 불가","제565조제2항"],["위약금 특약","손해배상액의 예정으로 추정","제398조제4항"]]}],"함정":"상대방이 수령을 거절하면 공탁까지 해야 한다는 설명은 이행제공 문제와 혼동한 것이다. 배액 상환은 제공으로 충분하다. 이행착수 시점에 따라 해제 가능 여부가 달라지는 것도 같이 정리한다."}},{"i":"S4-1-1-민법-32","r":"S4","g":1,"c":1,"n":72,"s":"민법","q":"민법상 임대차계약에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임대인이 목적물을 임대할 권한이 없어도 임대차계약은 유효하게 성립한다.","임차기간을 영구로 정한 임대차약정은 특별한 사정이 없는 한 허용된다.","임차인은 특별한 사정이 없는 한 자신이 지출한 임차물의 보존에 관한 필요비 금액의 한도에서 차임의 지급을 거절할 수 있다.","임대차가 묵시의 갱신이 된 경우, 전임대차에 대해 제3자가 제공한 담보는 원칙적으로 소멸하지 않는다.","임대차 종료로 인한 임차인의 원상회복의무에는 임대인이 임대 당시의 부동산 용도에 맞게 다시 사용할 수 있도록 협력할 의무까지 포함된다."],"a":[4],"L":"민3-3","o":"기출","x":{"한줄":"묵시갱신이 되면 전임대차에 대하여 제3자가 제공한 담보는 기간 만료로 소멸한다.","근거":[{"법령":"민법","조문":"제639조제2항","원문":"전항의 경우에 전임대차에 대하여 제삼자가 제공한 담보는 기간의 만료로 인하여 소멸한다."},{"법령":"민법","조문":"제626조제1항","원문":"임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다."},{"법령":"민법","조문":"제618조","원문":"임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"임대차는 임대인에게 처분권한이 없어도 채권계약으로서 유효하다(제618조)."},{"번호":2,"판정":"옳음","설명":"임대차 존속기간 20년 상한을 정한 제651조가 2016.1.6. 삭제되어 영구 약정도 허용된다."},{"번호":3,"판정":"옳음","설명":"필요비상환청구권과 차임지급의무는 대가 관계에 있어 임차인은 필요비 한도에서 차임 지급을 거절할 수 있다(제626조제1항, 판례)."},{"번호":4,"판정":"틀림","설명":"묵시갱신 때 전임대차의 제3자 담보는 소멸한다(제639조제2항). 보증인·물상보증인이 계속 책임을 지지 않는다."},{"번호":5,"판정":"옳음","설명":"원상회복의무에는 임대인이 목적물을 종전 용도에 맞게 다시 사용할 수 있게 하는 협력 의무가 포함된다(판례)."}],"개념":[{"종류":"표","제목":"묵시의 갱신(제639조)","머리":["쟁점","내용","근거"],"행":[["요건","기간 만료 후 임차인이 사용·수익을 계속하고 임대인이 상당한 기간 내에 이의하지 않음","제639조제1항"],["효과","전임대차와 동일한 조건으로 다시 임대차한 것으로 봄","제639조제1항"],["존속기간","기간의 약정 없는 임대차로 보아 각 당사자가 해지통고 가능","제639조제1항 단서, 제635조"],["제3자 담보","기간 만료로 소멸(보증, 저당권 등)","제639조제2항"],["주택·상가","주택임대차보호법은 묵시갱신 2년, 상가건물 임대차보호법은 1년","주임법 제6조, 상임법 제10조제4항"]]},{"종류":"표","제목":"임대차 존속기간 관련 정리","머리":["구분","내용","근거"],"행":[["최장 기간 제한","없음(영구 약정 허용)","제651조 삭제 <2016.1.6>"],["처분권한 없는 자의 단기임대차","건물 3년, 토지 5년 등으로 제한","제619조"],["기간 약정 없는 임대차","언제든 해지통고, 토지·건물은 임대인 6개월 임차인 1개월","제635조"],["차임연체 해지(건물)","2기의 차임액에 달하면 해지","제640조"]]}],"함정":"임대차 기간은 20년을 넘지 못한다는 구법 지식으로 2번을 틀린 선지로 고르기 쉽다. 제651조는 삭제되어 영구 약정도 허용된다. 묵시갱신 때 제3자 담보가 소멸하는 점은 보증인 보호 취지다.","개정":"제651조(임대차 존속기간 20년 제한)는 2016.1.6. 삭제되었다. 이전에는 20년을 넘는 약정 기간이 20년으로 단축되었다."}},{"i":"S4-1-1-민법-33","r":"S4","g":1,"c":1,"n":73,"s":"민법","q":"임차인의 비용상환청구권과 부속물매수청구권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인은 보존에 관한 필요비를 지출한 경우 임대차 종료 시에 비로소 상환을 청구할 수 있다.","임차인은 임대인의 동의 없이 부속시킨 물건에 대하여도 임대차 종료 시 부속물매수청구를 할 수 있다.","일시사용을 위한 임대차임이 명백한 경우 임차인은 부속물의 매수를 청구할 수 있다.","임차인이 유익비상환청구권을 포기하기로 하는 약정은 임차인에게 불리하므로 무효이다.","임차인의 유익비상환청구권은 임대인이 목적물을 반환받은 날부터 6개월 내에 행사하여야 한다."],"a":[5],"L":"민3-3","o":"변형","x":{"한줄":"임차인의 비용상환청구는 임대인이 목적물을 반환받은 날부터 6개월 내에 하여야 한다.","근거":[{"법령":"민법","조문":"제654조","원문":"제610조제1항, 제615조 내지 제617조의 규정은 임대차에 이를 준용한다."},{"법령":"민법","조문":"제617조","원문":"계약 또는 목적물의 성질에 위반한 사용, 수익으로 인하여 생긴 손해배상의 청구와 차주가 지출한 비용의 상환청구는 대주가 물건의 반환을 받은 날로부터 6월내에 하여야 한다."},{"법령":"민법","조문":"제626조","원문":"①임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다. ②임차인이 유익비를 지출한 경우에는 임대인은 임대차종료시에 그 가액의 증가가 현존한 때에 한하여 임차인의 지출한 금액이나 그 증가액을 상환하여야 한다. 이 경우에 법원은 임대인의 청구에 의하여 상당한 상환기간을 허여할 수 있다."},{"법령":"민법","조문":"제646조제1항","원문":"건물 기타 공작물의 임차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 임대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다."},{"법령":"민법","조문":"제652조","원문":"제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조 내지 제647조의 규정에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 그 효력이 없다."},{"법령":"민법","조문":"제653조","원문":"제628조, 제638조, 제640조, 제646조 내지 제648조, 제650조 및 전조의 규정은 일시사용하기 위한 임대차 또는 전대차인 것이 명백한 경우에는 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"필요비는 지출 즉시 상환을 청구할 수 있다(제626조제1항). 임대차 종료 시를 기다리지 않는다."},{"번호":2,"판정":"틀림","설명":"부속물매수청구는 임대인의 동의를 얻어 부속한 물건이거나 임대인에게서 매수한 물건이 대상이다(제646조)."},{"번호":3,"판정":"틀림","설명":"일시사용을 위한 임대차임이 명백하면 제646조가 적용되지 않는다(제653조)."},{"번호":4,"판정":"틀림","설명":"제626조는 제652조의 강행규정 목록에 없다. 유익비상환청구권을 배제하는 약정은 유효하다(판례)."},{"번호":5,"판정":"옳음","설명":"임차인의 비용상환청구는 임대인이 목적물을 반환받은 날부터 6개월 내에 하여야 한다(제654조, 제617조)."}],"개념":[{"종류":"표","제목":"임차인의 비용상환·매수청구권 비교","머리":["구분","요건","행사 시기","강행규정 여부","근거"],"행":[["필요비상환청구권","보존에 관한 필요비 지출","즉시","임의규정(제652조에 없음)","제626조제1항"],["유익비상환청구권","가치 증가 + 임대차 종료 시 현존","임대차 종료 시. 법원이 상환기간 허여 가능","임의규정(판례)","제626조제2항"],["부속물매수청구권","임대인 동의로 부속 또는 임대인에게서 매수. 독립성이 있어야 함(판례)","임대차 종료 시","강행규정(불리한 약정 무효)","제646조, 제652조"],["지상물매수청구권","건물 소유 등 목적 토지임대차의 기간 만료 + 지상시설 현존","기간 만료 후 갱신 거절 시","강행규정","제643조, 제283조, 제652조"],["청구 기간","임대인이 목적물을 반환받은 날부터 6개월","","","제654조, 제617조"],["일시사용 임대차","부속물매수청구 등 적용 없음","","","제653조"]]},{"종류":"비교","제목":"필요비와 유익비","왼쪽":{"이름":"필요비","항목":["목적물의 보존·유지에 필요한 비용","지출 즉시 상환 청구","차임 지급 거절의 근거가 됨"]},"오른쪽":{"이름":"유익비","항목":["객관적 가치를 증가시키는 비용","임대차 종료 시 가액 증가가 현존할 때만","지출액 또는 증가액을 상환, 법원이 상환기간 허여 가능"]}}],"함정":"필요비를 유익비처럼 임대차 종료 때 청구한다고 외우기 쉽다. 필요비는 즉시, 유익비는 종료 시다. 제652조의 강행규정에 제626조가 없어서 유익비상환청구권 포기 약정이 유효하다는 점을 놓치기도 한다."}},{"i":"S4-1-1-민법-34","r":"S4","g":1,"c":1,"n":74,"s":"민법","q":"주택임대차보호법상의 대항력에 관한 설명으로 틀린 것은? (단, 일시사용을 위한 임대차가 아니고 임차권 등기가 이루어지지 아니한 경우를 전제하며 다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인이 타인의 점유를 매개로 임차주택을 간접점유하는 경우에도 대항요건인 점유가 인정될 수 있다.","임차인이 지위를 강화하고자 별도로 전세권 설정등기를 마친 후 ｢주택임대차보호법｣상의 대항요건을 상실한 경우, ｢주택임대차보호법｣상의 대항력을 상실한다.","주민등록을 마치고 거주하던 자기 명의의 주택을 매도한 자가 매도와 동시에 이를 다시 임차하기로 약정한 경우, 매수인 명의의 소유권 이전등기 여부와 관계없이 대항력이 인정된다.","임차인이 주택의 인도와 주민등록을 마친 때에는 그 다음 날 오전 영시부터 대항력이 생긴다.","임차인이 가족과 함께 임차주택의 점유를 계속하면서 가족의 주민등록은 그대로 둔 채 임차인의 주민등록만 일시적으로 옮긴 경우 대항력을 상실하지 않는다."],"a":[3],"L":"민4-1","o":"기출","x":{"한줄":"자기 주택을 매도하며 재임차한 경우 대항력은 매수인 명의의 소유권이전등기가 마쳐진 때부터 생기므로, 이전등기와 관계없이 인정된다는 설명이 틀리다.","근거":[{"법령":"주택임대차보호법","조문":"제3조제1항","원문":"임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다."},{"판례":"대법원 판례(매도 후 재임차)","요지":"주민등록을 마친 채 거주하던 자가 주택을 매도하고 곧바로 임차한 경우, 임차인의 대항력은 매수인 명의의 소유권이전등기가 마쳐진 다음 날부터 생긴다. 이전등기 이전에는 임차인이 전 소유자이므로 대항력을 논할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"점유는 직접점유뿐 아니라 간접점유로도 대항요건을 갖출 수 있다(판례)."},{"번호":2,"판정":"옳음","설명":"전세권 설정등기를 한 임차인이 주임법상 대항요건을 잃으면 주임법상 대항력도 잃는다(판례)."},{"번호":3,"판정":"틀림","설명":"대항력은 매수인 명의 소유권이전등기가 마쳐진 때를 기준으로 생긴다(판례)."},{"번호":4,"판정":"옳음","설명":"인도와 주민등록을 마친 다음 날부터 효력이 생긴다(제3조제1항). 판례는 그 다음 날 오전 영시로 본다."},{"번호":5,"판정":"옳음","설명":"가족의 주민등록이 그대로 있고 점유를 계속하면 대항력을 상실하지 않는다(판례)."}],"개념":[{"종류":"표","제목":"주택임차인의 대항력·우선변제권·임차권등기","머리":["구분","요건","효력 발생","근거"],"행":[["대항력","주택의 인도 + 주민등록(전입신고)","그 다음 날부터","제3조제1항"],["우선변제권","대항요건 + 임대차계약증서상 확정일자","경매·공매 환가대금에서 후순위권리자보다 우선. 경매는 배당요구 필요(판례)","제3조의2제2항"],["최우선변제","경매신청 등기 전 대항요건 + 보증금 중 일정액","시행령이 정한 범위","제8조"],["임차권등기명령","임대차 종료 후 보증금 미반환","등기 완료 시 대항력·우선변제권 취득 또는 유지, 이후 대항요건을 잃어도 상실 없음","제3조의3"],["양수인의 지위","임차주택 양수인","임대인 지위 승계","제3조제4항"]]},{"종류":"흐름","제목":"대항력 취득과 경매 시 보증금 회수","단계":[{"이름":"인도와 전입신고","설명":"임차주택을 인도받고 주민등록(전입신고)을 마침"},{"이름":"대항력 발생","설명":"그 다음 날부터 제3자에 대하여 효력"},{"이름":"확정일자","설명":"임대차계약증서에 확정일자를 받으면 우선변제권"},{"이름":"경매 배당","설명":"배당요구종기까지 배당요구를 해야 순위에 따라 배당(판례)"}]}],"함정":"자기 집을 팔고 재임차하는 구조에서는 매수인 명의 등기 전에는 임차인이 소유자이므로 대항력이 없다. 등기 여부와 관계없이 대항력이 인정된다는 선지에 속지 않는다. 전세권 설정 임차인이 대항요건을 잃으면 주임법상 대항력은 사라진다."}},{"i":"S4-1-1-민법-35","r":"S4","g":1,"c":1,"n":75,"s":"민법","q":"甲은 2023. 1. 5. 乙로부터 그 소유의 X주택을 보증금 2억원, 월 임료 50만원, 기간은 계약일로부터 1년으로 정하여 임차하는 내용의 계약을 체결하고, 당일 乙에게 보증금을 지급함과 동시에 X주택을 인도받아 주민등록을 마치고 확정일자를 받았다. 다음 중 주택임대차보호법의 적용에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 2023. 1. 6. 오전 영시부터 대항력을 취득한다.","제3자에 의해 2023. 5. 9. 경매가 개시되어 X주택이 매각된 경우, 甲은 경매절차에서 배당요구를 하지 않아도 보증금에 대해 우선변제를 받을 수 있다.","乙이 X주택을 丙에게 매도하고 소유권이전등기를 마친 경우, 乙은 특별한 사정이 없는 한 보증금반환의무를 면한다.","甲이 2기의 차임액에 달하는 차임을 연체하면 묵시적 갱신이 인정되지 않는다.","묵시적 갱신이 된 경우, 갱신된 임대차계약의 존속기간은 2년이다."],"a":[2],"L":"민4-1","o":"기출","x":{"한줄":"확정일자를 받은 임차인도 경매에서 우선변제를 받으려면 배당요구종기까지 배당요구를 해야 한다.","근거":[{"법령":"주택임대차보호법","조문":"제3조의2제2항","원문":"제3조제1항ㆍ제2항 또는 제3항의 대항요건(對抗要件)과 임대차계약증서(제3조제2항 및 제3항의 경우에는 법인과 임대인 사이의 임대차계약증서를 말한다)상의 확정일자(確定日字)를 갖춘 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매(公賣)를 할 때에 임차주택(대지를 포함한다)의 환가대금(換價代金)에서 후순위권리자(後順位權利者)나 그 밖의 채권자보다 우선하여 보증금을 변제(辨濟)받을 권리가 있다."},{"법령":"주택임대차보호법","조문":"제6조제1항·제2항·제3항","원문":"①…그 기간이 끝난 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 임차인이 임대차기간이 끝나기 2개월 전까지 통지하지 아니한 경우에도 또한 같다. ②제1항의 경우 임대차의 존속기간은 2년으로 본다. ③2기(期)의 차임액(借賃額)에 달하도록 연체하거나 그 밖에 임차인으로서의 의무를 현저히 위반한 임차인에 대하여는 제1항을 적용하지 아니한다."},{"법령":"주택임대차보호법","조문":"제3조제4항","원문":"임차주택의 양수인(讓受人)(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인(賃貸人)의 지위를 승계한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"인도와 주민등록을 마친 다음 날 오전 영시부터 대항력이 생긴다(제3조제1항, 판례). 계약일이 1월 5일이므로 1월 6일 오전 영시다."},{"번호":2,"판정":"틀림","설명":"대항요건과 확정일자를 갖춘 임차인도 배당요구종기까지 배당요구를 해야 우선변제를 받는다(판례). 배당요구가 없으면 배당에서 제외된다."},{"번호":3,"판정":"옳음","설명":"대항력 있는 임차주택의 양수인은 임대인의 지위를 승계하므로 양도인 乙은 보증금반환의무를 면한다(제3조제4항)."},{"번호":4,"판정":"옳음","설명":"2기의 차임액에 달하는 연체가 있으면 묵시적 갱신이 인정되지 않는다(제6조제3항)."},{"번호":5,"판정":"옳음","설명":"묵시적 갱신의 존속기간은 2년으로 본다(제6조제2항)."}],"개념":[{"종류":"표","제목":"주택임대차 갱신 정리","머리":["구분","요건·효과","근거"],"행":[["묵시적 갱신","임대인은 기간 만료 6개월~2개월 전, 임차인은 2개월 전까지 통지하지 않으면 전 임대차와 동일 조건으로 갱신. 존속기간 2년","제6조제1항·제2항"],["묵시적 갱신 배제","2기 차임 연체 또는 의무 현저 위반","제6조제3항"],["묵시적 갱신 후 해지","임차인은 언제든 통지, 임대인이 통지를 받은 날부터 3개월 후 효력","제6조의2"],["계약갱신요구권","1회 행사, 갱신 존속기간 2년, 임대인은 법정 사유 없이 거절 못 함(실거주 포함)","제6조의3"],["최단 존속기간","기간 미정 또는 2년 미만이면 2년으로 봄","제4조제1항"]]},{"종류":"흐름","제목":"경매 시 임차인의 보증금 회수 절차","단계":[{"이름":"대항요건과 확정일자","설명":"인도 + 주민등록 + 임대차계약증서의 확정일자 (우선변제권은 대항요건과 확정일자를 모두 갖춘 때부터)"},{"이름":"경매 개시","설명":"경매가 개시되면 법원이 배당요구종기를 정해 공고"},{"이름":"배당요구","설명":"배당요구종기까지 배당요구를 해야 우선변제를 받을 수 있음(판례)"},{"이름":"인도","설명":"임차주택을 양수인에게 인도해야 보증금을 받을 수 있음(제3조의2제3항)"}]}],"함정":"대항력과 확정일자가 있으면 배당요구 없이도 순위대로 배당받는다고 오해하기 쉽다. 우선변제는 배당요구를 전제로 한다. 대항력이 있는 임차인은 낙찰자에게 보증금을 청구할 수도 있어서 배당요구 여부를 선택할 수 있다."}},{"i":"S4-1-1-민법-36","r":"S4","g":1,"c":1,"n":76,"s":"민법","q":"상가건물 임대차보호법에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인이 건물의 인도를 받으면 사업자등록을 신청하지 않더라도 그 다음 날부터 제3자에 대하여 대항력이 생긴다.","임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 5년을 초과하지 않는 범위에서만 행사할 수 있다.","임차인이 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우, 임대인은 임차인의 계약갱신요구를 거절할 수 있다.","임대차가 종료한 후 보증금이 반환되지 않으면 임차인은 건물 소재지 관할 세무서장에게 임차권등기명령을 신청할 수 있다.","보증금액이 대통령령으로 정한 기준을 초과하는 임대차에는 계약갱신요구권 규정이 적용되지 않는다."],"a":[3],"L":"민4-2","o":"변형","x":{"한줄":"임차인이 3기의 차임액에 이르도록 차임을 연체한 사실이 있으면 임대인은 갱신요구를 거절할 수 있다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조제1항제1호","원문":"임대인은 임차인이 임대차기간이 만료되기 6개월 전부터 1개월 전까지 사이에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. 다만, 다음 각 호의 어느 하나의 경우에는 그러하지 아니하다. 1. 임차인이 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우"},{"법령":"상가건물 임대차보호법","조문":"제10조제2항","원문":"임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 아니하는 범위에서만 행사할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제6조제1항","원문":"임대차가 종료된 후 보증금이 반환되지 아니한 경우 임차인은 임차건물의 소재지를 관할하는 지방법원, 지방법원지원 또는 시ㆍ군법원에 임차권등기명령을 신청할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제2조제3항","원문":"제1항 단서에도 불구하고 제3조, 제10조제1항, 제2항, 제3항 본문, 제10조의2부터 제10조의9까지의 규정, 제11조의2 및 제19조는 제1항 단서에 따른 보증금액을 초과하는 임대차에 대하여도 적용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대항력은 건물의 인도와 사업자등록 신청을 모두 갖춘 다음 날부터 생긴다(제3조제1항)."},{"번호":2,"판정":"틀림","설명":"갱신요구권의 전체 임대차기간 상한은 10년이다(제10조제2항)."},{"번호":3,"판정":"옳음","설명":"3기 차임 연체 사실은 갱신 거절 사유다(제10조제1항제1호)."},{"번호":4,"판정":"틀림","설명":"임차권등기명령은 관할 지방법원, 지방법원지원 또는 시·군법원에 신청한다(제6조제1항). 세무서장은 확정일자와 정보제공 업무를 맡는다."},{"번호":5,"판정":"틀림","설명":"환산보증금 기준을 초과하는 임대차에도 제10조제1항·제2항·제3항 본문(갱신요구권)이 적용된다(제2조제3항)."}],"개념":[{"종류":"표","제목":"상가건물 임대차보호법 핵심 정리","머리":["구분","내용","근거"],"행":[["대항력","건물 인도 + 사업자등록 신청, 그 다음 날부터","제3조제1항"],["확정일자","관할 세무서장이 부여, 우선변제권","제4조, 제5조제2항"],["임차권등기명령","임대차 종료 후 보증금 미반환 시 관할 지방법원·지원·시군법원에 신청","제6조제1항"],["최단 기간","기간 미정 또는 1년 미만이면 1년으로 봄","제9조제1항"],["계약갱신요구권","임대차 만료 6개월~1개월 전, 전체 10년 이내. 거절 사유는 제10조제1항 각 호","제10조제1항·제2항"],["묵시적 갱신","갱신거절 통지가 없으면 전 임대차와 동일 조건, 존속기간 1년. 임차인은 언제든 해지통고, 3개월 후 효력","제10조제4항·제5항"],["환산보증금 초과","대항력, 갱신요구권, 권리금 등 일부 규정은 그대로 적용","제2조제3항"]]},{"종류":"비교","제목":"주택임대차와 상가임대차의 갱신","왼쪽":{"이름":"주택임대차보호법","항목":["갱신요구권 1회, 갱신 기간 2년(제6조의3)","묵시적 갱신 2년(제6조제2항)","거절 사유 중 2기 차임 연체","실거주 사유 거절 가능"]},"오른쪽":{"이름":"상가건물 임대차보호법","항목":["갱신요구권 전체 10년(제10조제2항)","묵시적 갱신 1년(제10조제4항)","거절 사유 중 3기 차임 연체","실거주 사유 없음"]}}],"함정":"갱신요구권의 상한은 법 개정으로 10년이 되었는데, 5년·7년으로 알고 있다가 틀린다. 3기와 2기 차임 연체도 주택·상가가 다르다. 임차권등기명령 신청처는 세무서가 아니라 법원이다.","개정":"갱신요구권의 전체 임대차기간 상한은 제10조제2항 <개정 2018.10.16>으로 10년이 되었다. 그 이전 기출은 5년 기준이다."}},{"i":"S4-1-1-민법-37","r":"S4","g":1,"c":1,"n":77,"s":"민법","q":"甲은 乙에게 무이자로 빌려준 1억원을 담보하기 위해, 丙명의의 저당권(피담보채권 5,000만원)이 설정된 乙소유의 X건물(시가 2억원)에 관하여 담보가등기를 마쳤고, 乙은 변제기가 도래한 甲에 대한 차용금을 지급하지 않고 있다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲이 귀속정산절차에 따라 적법하게 X건물의 소유권을 취득하면 丙의 저당권은 소멸한다.","甲이 乙에게 청산금을 지급하지 않고 자신의 명의로 본 등기를 마친 경우, 그 등기는 무효이다.","甲의 청산금지급채무와 乙의 가등기에 기한 본등기 및 X건물 인도채무는 동시이행관계에 있다.","경매절차에서 丁이 X건물의 소유권을 취득하면 특별한 사정이 없는 한 甲의 가등기담보권은 소멸한다.","만약 청산금이 없는 경우, 적법하게 실행통지를 하여 2개월의 청산기간이 지나면 청산절차의 종료와 함께 X건물에 대한 사용ㆍ수익권은 甲에게 귀속된다."],"a":[1],"L":"민4-3","o":"기출","x":{"한줄":"담보가등기권자가 소유권을 취득해도 선순위 저당권은 소멸하지 않고, 가등기권자는 그 부담을 안은 채 소유권을 얻는다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제4조제1항","원문":"채권자는 제3조제1항에 따른 통지 당시의 담보목적부동산의 가액에서 그 채권액을 뺀 금액(이하 \"청산금\"이라 한다)을 채무자등에게 지급하여야 한다. 이 경우 담보목적부동산에 선순위담보권(先順位擔保權) 등의 권리가 있을 때에는 그 채권액을 계산할 때에 선순위담보 등에 의하여 담보된 채권액을 포함한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제4조제3항","원문":"청산금의 지급채무와 부동산의 소유권이전등기 및 인도채무(引渡債務)의 이행에 관하여는 동시이행의 항변권(抗辯權)에 관한 「민법」 제536조를 준용한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제15조","원문":"담보가등기를 마친 부동산에 대하여 강제경매등이 행하여진 경우에는 담보가등기권리는 그 부동산의 매각에 의하여 소멸한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"丙의 선순위 저당권은 甲이 소유권을 취득해도 소멸하지 않는다. 청산금 계산 때 丙의 채권액 5,000만원이 공제될 뿐이다(제4조제1항)."},{"번호":2,"판정":"옳음","설명":"청산금을 지급하지 않고 마친 본등기는 무효다(판례)."},{"번호":3,"판정":"옳음","설명":"청산금 지급채무와 본등기·인도채무는 동시이행관계다(제4조제3항)."},{"번호":4,"판정":"옳음","설명":"담보가등기를 마친 부동산이 경매로 매각되면 담보가등기권리는 소멸한다(제15조)."},{"번호":5,"판정":"옳음","설명":"청산금이 없는 경우 청산기간 2개월이 지나면 사용·수익권이 채권자에게 귀속된다(판례)."}],"개념":[{"종류":"흐름","제목":"가등기담보권 실행(귀속정산)","단계":[{"이름":"변제기 도래","설명":"채무자가 변제하지 않음. 채권자는 변제기 후에 실행 통지"},{"이름":"청산금 평가액 통지","설명":"채무자등에게 통지, 통지 당시 부동산 평가액과 채권액을 밝힘. 청산금이 없다고 인정되면 그 뜻을 통지"},{"이름":"청산기간 2개월","설명":"통지가 도달한 날부터 2개월이 지나야 함(제3조제1항)"},{"이름":"청산금 지급","설명":"청산금 = 평가액 - 채권액(선순위 담보채권 포함). 청산금 지급과 본등기·인도는 동시이행"},{"이름":"소유권 취득","설명":"가등기담보는 청산기간이 지나야 본등기 청구 가능(제4조제2항)"}]},{"종류":"표","제목":"이 문항의 청산금 계산","머리":["항목","금액","설명"],"행":[["부동산 평가액","2억원","통지 당시 가액"],["甲의 채권액","1억원","무이자 대여금"],["선순위 저당권 피담보채권","5,000만원","채권액 계산에 포함(제4조제1항)"],["청산금","5,000만원","2억 - (1억 + 5,000만원)"],["丙의 저당권","존속","甲이 소유권을 취득해도 소멸하지 않음"],["경매로 매각될 때 甲의 가등기","소멸","제15조"]]}],"함정":"담보가등기권자가 소유권을 취득하면 저당권이 정리된다고 생각하기 쉽다. 선순위 저당권은 존속하고 청산금 계산에서 공제될 뿐이다. 경매가 되면 담보가등기가 소멸한다는 제15조와 구분해서 정리한다."}},{"i":"S4-1-1-민법-38","r":"S4","g":1,"c":1,"n":78,"s":"민법","q":"집합건물의 소유 및 관리에 관한 법률의 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["규약의 설정ㆍ변경 및 폐지는 관리단집회에서 구분소유자의 과반수 및 의결권의 과반수의 결의로 한다.","각 공유자의 공용부분 지분은 규약에 다른 정함이 없으면 그가 가지는 전유부분의 면적 비율에 따른다.","재건축 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상의 결의에 따른다.","관리단집회를 소집하려면 관리단집회일 1주일 전에 회의의 목적사항을 구체적으로 밝혀 각 구분소유자에게 통지하여야 한다.","구분소유자는 규약으로 달리 정한 경우를 제외하고는 그가 가지는 전유부분과 분리하여 대지사용권을 처분할 수 없다."],"a":[1],"L":"민4-4","o":"변형","x":{"한줄":"규약의 설정·변경·폐지는 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 찬성이 필요하다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제29조제1항","원문":"규약의 설정ㆍ변경 및 폐지는 관리단집회에서 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 찬성을 얻어서 한다. 이 경우 규약의 설정ㆍ변경 및 폐지가 일부 구분소유자의 권리에 특별한 영향을 미칠 때에는 그 구분소유자의 승낙을 받아야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제12조제1항","원문":"각 공유자의 지분은 그가 가지는 전유부분의 면적 비율에 따른다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제47조제2항","원문":"제1항의 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상의 결의에 따른다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제34조제1항","원문":"관리단집회를 소집하려면 관리단집회일 1주일 전에 회의의 목적사항을 구체적으로 밝혀 각 구분소유자에게 통지하여야 한다. 다만, 이 기간은 규약으로 달리 정할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제20조제2항","원문":"구분소유자는 그가 가지는 전유부분과 분리하여 대지사용권을 처분할 수 없다. 다만, 규약으로써 달리 정한 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"규약 설정·변경·폐지는 4분의 3 이상 및 4분의 3 이상이다(제29조제1항). 과반수는 통상의 집회결의 기준이다(제38조제1항)."},{"번호":2,"판정":"옳음","설명":"공유자의 지분은 전유부분의 면적 비율에 따른다(제12조제1항)."},{"번호":3,"판정":"옳음","설명":"재건축 결의는 구분소유자 5분의 4 이상 및 의결권 5분의 4 이상이다(제47조제2항)."},{"번호":4,"판정":"옳음","설명":"소집통지는 1주일 전에 목적사항을 구체적으로 밝혀 한다. 이 기간은 규약으로 달리 정할 수 있다(제34조제1항)."},{"번호":5,"판정":"옳음","설명":"대지사용권은 전유부분과 분리하여 처분하지 못한다. 규약으로 달리 정하면 예외다(제20조제2항)."}],"개념":[{"종류":"표","제목":"관리단집회 결의 정족수","머리":["결의 사항","구분소유자","의결권","근거"],"행":[["통상의 집회결의","과반수","과반수","제38조제1항"],["공용부분 변경","3분의 2 이상","3분의 2 이상(개량이 과다 비용이 아니면 통상 결의)","제15조제1항"],["규약 설정·변경·폐지","4분의 3 이상","4분의 3 이상","제29조제1항"],["재건축 결의","5분의 4 이상","5분의 4 이상","제47조제2항"],["소집절차 생략","전원 동의","","제35조"]]},{"종류":"표","제목":"관리단집회 소집","머리":["구분","내용","근거"],"행":[["정기 집회","관리인이 매년 회계연도 종료 후 3개월 이내 소집","제32조"],["임시 집회 청구","구분소유자의 5분의 1 이상이 목적사항을 밝혀 청구(규약으로 감경 가능)","제33조제2항"],["소집 통지","1주일 전, 목적사항 구체적으로. 규약으로 달리 정할 수 있음","제34조제1항"],["관리인 선임","구분소유자 10인 이상이면 선임 의무, 관리단집회 결의로 선임·해임","제24조제1항·제3항"]]}],"함정":"규약 설정·변경·폐지를 통상의 집회결의(과반수)로 오인하기 쉽다. 규약은 4분의 3이다. 공용부분 변경은 3분의 2이고, 개량 목적에 비용이 과다하지 않으면 통상 결의로 족하다는 예외도 같이 익힌다.","개정":"공용부분 변경에서 개량 목적이면서 비용이 과다하지 않은 경우 통상의 집회결의로 결정할 수 있도록 한 제15조제1항 단서는 <개정 2020.2.4>이다."}},{"i":"S4-1-1-민법-39","r":"S4","g":1,"c":1,"n":79,"s":"민법","q":"甲은 법령상의 제한을 피하여 乙소유의 X부동산을 매수하고자 자신의 친구 丙과 X부동산의 매수에 관한 명의신탁약정을 체결하였다. 그에 따라 2021년 5월 丙은 乙과 X부동산 매매계약을 체결하고, 甲의 자금으로 그 대금을 지급하여 丙명의로 등기 이전을 마쳤다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 丙사이의 명의신탁약정은 무효이다.","乙이 매매계약 체결 당시 그 명의신탁약정이 있다는 사실을 알았다면 丙은 X부동산의 소유권을 취득할 수 없다.","乙이 매매계약 체결 당시 그 명의신탁약정이 있다는 사실을 몰랐다면, 그 후 명의신탁약정 사실을 알게 되었어도 丙은 X부동산의 소유권을 취득한다.","丙이 X부동산의 소유권을 취득한 경우 甲은 丙에게 제공한 X부동산의 매수자금 상당액을 부당이득으로 반환 청구할 수 있다.","X부동산의 소유권을 유효하게 취득한 丙이 명의신탁약정 외의 적법한 원인에 의하여 甲앞으로 X부동산에 대한 소유권이전등기를 마친다고 해도 그 소유권이전등기는 무효이다."],"a":[5],"L":"민4-5","o":"기출","x":{"한줄":"계약명의신탁에서 수탁자가 유효하게 소유권을 취득한 뒤 명의신탁약정 외의 적법한 원인으로 신탁자에게 이전등기를 하면 그 등기는 유효하다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항","원문":"명의신탁약정은 무효로 한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제2항","원문":"명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제3항","원문":"제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(계약명의신탁)","요지":"매도인의 선의·악의는 계약 체결 당시를 기준으로 판단한다. 매도인이 선의이면 수탁자가 소유권을 취득하고 신탁자는 수탁자에게 매수자금 상당액의 부당이득반환을 청구한다. 수탁자가 명의신탁약정 외의 적법한 원인으로 신탁자에게 이전등기를 하면 그 등기는 유효하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 무효다(제4조제1항)."},{"번호":2,"판정":"옳음","설명":"매도인이 명의신탁약정을 알았으면 제4조제2항 단서가 적용되지 않아 물권변동이 무효이고 丙은 소유권을 취득하지 못한다."},{"번호":3,"판정":"옳음","설명":"매도인의 선의는 계약 체결 시를 기준으로 하므로 이후에 알았더라도 丙은 소유권을 취득한다(판례)."},{"번호":4,"판정":"옳음","설명":"甲은 丙에게 매수자금 상당액을 부당이득으로 반환 청구할 수 있다(판례)."},{"번호":5,"판정":"틀림","설명":"丙이 명의신탁약정 외의 적법한 원인으로 甲에게 이전등기를 마치면 그 등기는 유효하다(판례)."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","명의신탁약정","수탁자 명의 등기","소유권 귀속","신탁자 구제"],"행":[["양자간(2자간) 등기명의신탁","무효(제4조제1항)","무효(제4조제2항 본문)","신탁자","말소 또는 진정명의회복 이전등기 청구"],["3자간 등기명의신탁(중간생략형)","무효","무효","매도인","신탁자는 매도인을 대위하여 말소 청구, 매도인에게 이전 청구"],["계약명의신탁, 매도인 선의","무효","유효(제4조제2항 단서)","수탁자","매수자금 상당액 부당이득반환 청구"],["계약명의신탁, 매도인 악의","무효","무효","매도인","매수자금 상당액 부당이득반환 청구(상대는 수탁자)"],["제3자","무효를 제3자에게 대항 못함(제4조제3항)","","",""]]},{"종류":"흐름","제목":"계약명의신탁의 소유권 판단","단계":[{"이름":"계약 당사자 확인","설명":"명의수탁자가 매도인과 직접 매매계약을 체결했는지 확인"},{"이름":"매도인의 인식 판단","설명":"계약 체결 당시 명의신탁약정을 알았는지(선의·악의)로 갈림"},{"이름":"선의일 때","설명":"수탁자가 소유권을 취득, 신탁자는 부당이득반환 청구권만 가짐"},{"이름":"악의일 때","설명":"물권변동 무효, 매도인이 소유권 보유"}]}],"함정":"수탁자가 신탁자에게 소유권을 넘기는 이전등기는 명의신탁의 연장이라 무효라고 생각하기 쉽다. 새로운 원인에 기한 이전등기는 유효하다. 매도인의 선의 판단 시점이 계약 체결 시라는 점도 같이 출제된다."}},{"i":"S4-1-1-민법-40","r":"S4","g":1,"c":1,"n":80,"s":"민법","q":"甲은 조세포탈ㆍ강제집행의 면탈 또는 법령상 제한의 회피를 목적으로 하지 않고, 배우자 乙과의 명의신탁약정에 따라 자신의 X토지를 乙명의로 소유권이전등기를 마쳐주었다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙의 명의신탁약정은 유효하다.","乙이 X토지를 丙에게 처분하고 이전등기를 마친 경우, 특별한 사정이 없는 한 丙은 X토지의 소유권을 취득한다.","甲은 乙에게 명의신탁을 해지하고 X토지의 소유권이전등기를 청구할 수 있다.","丁이 X토지를 불법점유하는 경우, 甲은 자신의 소유권에 기하여 직접 丁에게 X토지의 반환을 청구할 수 있다.","甲과 乙이 조세포탈을 목적으로 명의신탁약정을 하였다면 배우자 사이라도 그 약정과 乙명의의 등기는 무효이다."],"a":[4],"L":"민4-5","o":"변형","x":{"한줄":"특례가 적용되는 유효한 명의신탁에서 대외적 소유자는 수탁자 乙이므로, 신탁자 甲은 丁에게 직접 소유물반환을 청구할 수 없다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조제2호","원문":"다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우"},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항·제2항","원문":"①명의신탁약정은 무효로 한다. ②명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다."},{"판례":"대법원 판례(유효한 명의신탁)","요지":"종중·배우자 특례가 적용되는 명의신탁은 유효하다. 대외적으로는 수탁자가 소유자이므로 신탁자는 제3자에게 직접 소유물반환을 청구할 수 없고 수탁자를 대위해서만 청구한다. 신탁자는 신탁 해지를 원인으로 수탁자에게 이전등기를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"목적이 없는 배우자 사이의 명의신탁에는 제4조가 적용되지 않아 약정이 유효하다(제8조제2호)."},{"번호":2,"판정":"옳음","설명":"대외적으로 소유권은 수탁자 乙에게 있어 乙의 처분은 유효하다. 丙은 소유권을 취득한다(판례)."},{"번호":3,"판정":"옳음","설명":"신탁자는 신탁을 해지하고 수탁자에게 이전등기를 청구할 수 있다(판례)."},{"번호":4,"판정":"틀림","설명":"대외적 소유자는 乙이다. 甲은 丁에게 직접 청구할 수 없고 乙을 대위하여 청구한다(판례)."},{"번호":5,"판정":"옳음","설명":"조세포탈 등 목적이 있으면 제8조 특례가 적용되지 않는다. 약정과 등기 모두 무효가 된다(제4조제1항·제2항, 제8조)."}],"개념":[{"종류":"표","제목":"부동산 실권리자명의 등기에 관한 법률 제8조 특례","머리":["특례 대상","요건","효과","근거"],"행":[["종중","종중 보유 부동산을 종중 외의 자 명의로 등기","제4조~제7조 등 적용 제외(유효)","제8조제1호"],["배우자","배우자 명의로 등기. 법률혼 배우자(사실혼 제외, 판례)","제4조~제7조 등 적용 제외(유효)","제8조제2호"],["종교단체","산하 조직 보유 부동산을 종교단체 명의로 등기","제4조~제7조 등 적용 제외(유효)","제8조제3호"],["공통 요건","조세 포탈, 강제집행 면탈, 법령상 제한 회피를 목적으로 하지 않을 것","목적이 있으면 특례 배제, 명의신탁 무효","제8조"]]},{"종류":"비교","제목":"일반 명의신탁과 특례 명의신탁","왼쪽":{"이름":"일반 명의신탁(제4조)","항목":["약정 무효","등기 무효(계약명의신탁에서 매도인 선의 제외)","소유권은 신탁자 또는 매도인","제3자에게 무효를 대항할 수 없음"]},"오른쪽":{"이름":"특례 명의신탁(제8조)","항목":["약정 유효","수탁자가 대외적 소유자","신탁자는 해지 후 이전등기 청구, 제3자에게는 수탁자를 대위","수탁자의 처분은 유효"]}}],"함정":"배우자 특례라고 해서 신탁자가 대외적 소유자라고 보기 쉽다. 특례가 적용되면 명의신탁이 유효하게 되어 소유권은 수탁자에게 있다. 제3자에 대한 소유물반환은 수탁자를 대위해서 청구한다."}},{"i":"S4-2-1-중개사법-01","r":"S4","g":2,"c":2,"n":1,"s":"중개사법","q":"공인중개사법령상 용어의 정의와 중개대상물에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사인 법인의 임원으로서 공인중개사인 자는 소속공인중개사에 해당한다.","미성년자는 중개보조원이 될 수 없다.","「공장 및 광업재단 저당법」에 따른 공장재단은 중개대상물에 해당한다.","자기 소유의 건물을 직접 임대하는 행위는 다른 사람의 의뢰에 의한 것이 아니므로 중개업에 해당하지 않는다.","중개보조원은 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."],"a":[5],"L":"중1-1","o":"변형","x":{"한줄":"중개보조원은 현장안내·일반서무 같은 단순한 업무만 보조하고 중개업무를 수행하지 못하므로 5번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제2조제5호","원문":"5. \"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제6호","원문":"6. \"중개보조원\"이라 함은 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개대상물에 대한 현장안내 및 일반서무 등 개업공인중개사의 중개업무와 관련된 단순한 업무를 보조하는 자를 말한다."},{"법령":"공인중개사법 시행령","조문":"제2조","원문":"법 제3조제3호에 따른 중개대상물은 다음 각 호와 같다. 1. 「입목에 관한 법률」에 따른 입목 2. 「공장 및 광업재단 저당법」에 따른 공장재단 및 광업재단"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인의 사원·임원으로서 공인중개사인 자도 소속공인중개사다(법 제2조제5호 괄호)."},{"번호":2,"판정":"옳음","설명":"미성년자는 결격사유(법 제10조제1항제1호)이고, 제1호~제11호 해당자는 소속공인중개사·중개보조원이 될 수 없다(법 제10조제2항)."},{"번호":3,"판정":"옳음","설명":"법 제3조제3호에 따라 영 제2조가 입목, 공장재단, 광업재단을 중개대상물로 정한다."},{"번호":4,"판정":"옳음","설명":"중개업은 다른 사람의 의뢰를 받아 보수를 받고 중개를 업으로 하는 것이다(법 제2조제3호). 자기 물건의 직접 임대는 의뢰·알선 구조가 없다."},{"번호":5,"판정":"틀림","설명":"중개업무를 '수행하거나 보조'하는 자는 소속공인중개사다(법 제2조제5호). 중개보조원은 공인중개사가 아니라서 현장안내·일반서무 등 단순 업무의 보조만 한다(법 제2조제6호)."}],"개념":[{"종류":"표","제목":"용어의 정의 5가지","머리":["용어","뜻","근거"],"행":[["중개","중개대상물에 대하여 매매·교환·임대차 그 밖의 권리의 득실변경에 관한 행위를 알선","법 제2조제1호"],["중개업","다른 사람의 의뢰 + 일정한 보수 + 업으로 중개","법 제2조제3호"],["개업공인중개사","중개사무소의 개설등록을 한 자(공인중개사·법인)","법 제2조제4호"],["소속공인중개사","개업공인중개사에 소속된 공인중개사(법인의 사원·임원인 공인중개사 포함)로서 중개업무를 수행하거나 보조","법 제2조제5호"],["중개보조원","공인중개사가 아닌 자로서 현장안내·일반서무 등 단순한 업무를 보조","법 제2조제6호"]]},{"종류":"표","제목":"중개대상물의 범위","머리":["구분","내용","근거"],"행":[["토지","법 제3조제1호","법 제3조"],["건축물, 그 밖의 토지의 정착물","법 제3조제2호","법 제3조"],["입목","「입목에 관한 법률」에 따른 입목","영 제2조제1호"],["공장재단","「공장 및 광업재단 저당법」에 따른 공장재단","영 제2조제2호"],["광업재단","「공장 및 광업재단 저당법」에 따른 광업재단","영 제2조제2호"]]}],"함정":"중개를 '수행하거나 보조'한다는 문구는 소속공인중개사의 정의다. 중개보조원 정의에 그 문구가 들어가면 법문과 어긋난다. 자격이 없는 사람은 중개를 수행할 수 없다."}},{"i":"S4-2-1-중개사법-02","r":"S4","g":2,"c":2,"n":2,"s":"중개사법","q":"공인중개사법령상 공인중개사 정책심의위원회에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["심의위원회는 위원장 1명을 포함하여 5명 이상 9명 이내의 위원으로 구성한다.","위원장을 제외한 위원의 임기는 3년으로 한다.","심의위원회의 회의는 재적위원 3분의 1 이상의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다.","국토교통부장관이 직접 공인중개사자격시험 문제를 출제하려는 경우에는 심의위원회의 의결을 미리 거쳐야 한다.","심의위원회에서 심의한 사항 중 중개보수 변경에 관한 사항은 시·도지사가 이에 따라야 한다."],"a":[4],"L":"중1-2","o":"변형","x":{"한줄":"국토교통부장관이 시험문제를 직접 출제하거나 시험을 시행하려면 심의위원회 의결을 미리 거쳐야 하므로 4번이 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"제3조","원문":"국토교통부장관이 법 제4조제2항에 따라 직접 시험문제를 출제하거나 시험을 시행하려는 경우에는 심의위원회의 의결을 미리 거쳐야 한다."},{"법령":"공인중개사법 시행령","조문":"제1조의2제1항","원문":"심의위원회는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"제1조의2제3항","원문":"제2항제2호부터 제8호까지의 규정에 따른 위원의 임기는 2년으로 하되, 위원의 사임 등으로 새로 위촉된 위원의 임기는 전임위원 임기의 남은 기간으로 한다."},{"법령":"공인중개사법 시행령","조문":"제1조의5제2항","원문":"심의위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다."},{"법령":"공인중개사법","조문":"제2조의2제3항","원문":"제1항에 따라 공인중개사 정책심의위원회에서 심의한 사항 중 제1호의 경우에는 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 이에 따라야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"위원장 포함 7명 이상 11명 이내다(영 제1조의2제1항)."},{"번호":2,"판정":"틀림","설명":"임기는 2년이다(영 제1조의2제3항). 위원장은 국토교통부 제1차관이 맡는다."},{"번호":3,"판정":"틀림","설명":"재적위원 과반수 출석으로 개의한다(영 제1조의5제2항). 출석위원 과반수 찬성 의결은 맞다."},{"번호":4,"판정":"옳음","설명":"법 제4조제2항에 따라 국토교통부장관이 직접 출제·시행하려면 미리 의결을 거친다(영 제3조)."},{"번호":5,"판정":"틀림","설명":"시·도지사가 따라야 하는 것은 제1호(공인중개사 자격취득에 관한 사항)다. 중개보수 변경은 제3호라 구속력이 없다(법 제2조의2제3항)."}],"개념":[{"종류":"표","제목":"공인중개사 정책심의위원회 심의사항","머리":["호","심의사항","시·도지사 구속"],"행":[["제1호","공인중개사의 시험 등 자격취득에 관한 사항","따라야 함"],["제2호","부동산 중개업의 육성에 관한 사항","구속력 없음"],["제3호","중개보수 변경에 관한 사항","구속력 없음"],["제4호","손해배상책임의 보장 등에 관한 사항","구속력 없음"]]},{"종류":"표","제목":"심의위원회 구성·운영 수치","머리":["항목","내용","근거"],"행":[["위원 수","위원장 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","2년","영 제1조의2제3항"],["회의 소집","개최 7일 전까지 일시·장소·안건 통보(긴급 시 전날까지)","영 제1조의5제3항"],["개의·의결","재적위원 과반수 출석 / 출석위원 과반수 찬성","영 제1조의5제2항"],["기피 신청","안건 당사자가 신청, 심의위원회가 의결로 결정(대상 위원은 참여 못 함)","영 제1조의3제2항"]]}],"함정":"'시·도지사가 따라야 한다'는 효과를 심의사항 전체로 넓히면 5번을 고르게 된다. 구속력은 자격취득 사항 하나에만 있다. 3번은 의결 정족수는 맞고 개의 정족수만 바꾼 선지다."}},{"i":"S4-2-1-중개사법-03","r":"S4","g":2,"c":2,"n":3,"s":"중개사법","q":"공인중개사법령상 중개사무소의 개설등록을 위한 제출 서류에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공인중개사자격증 사본을 제출하여야 한다.","사용승인을 받았으나 건축물대장에 기재되지 아니한 건물에 중개사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류를 제출하여야 한다.","여권용 사진을 제출하여야 한다.","실무교육을 위탁받은 기관이 실무교육 수료 여부를 등록관청이 전자적으로 확인할 수 있도록 조치한 경우에는 실무교육의 수료확인증 사본을 제출하지 않아도 된다.","외국에 주된 영업소를 둔 법인의 경우에는 「상법」 상 외국회사 규정에 따른 영업소의 등기를 증명할 수 있는 서류를 제출하여야 한다."],"a":[1],"L":"중1-3","o":"기출","x":{"한줄":"자격증 사본은 제출 서류 목록에 없고 등록관청이 자격증을 발급한 시·도지사에게 자격 확인을 요청하므로 1번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제4조제1항 본문(후단)","원문":"이 경우 등록관청은 법 제5조제2항에 따라 공인중개사 자격증을 발급한 시ㆍ도지사에게 개설등록을 하려는 자(법인의 경우에는 대표자를 포함한 공인중개사인 임원 또는 사원을 말한다)의 공인중개사 자격 확인을 요청하여야 하고, 「전자정부법」 제36조제1항에 따라 행정정보의 공동이용을 통하여 법인 등기사항증명서(신청인이 법인인 경우에만 해당한다)과 건축물대장(「건축법」 제20조제5항에 따른 가설건축물대장은 제외한다. 이하 같다)을 확인하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제4조제1항제3호·제4호","원문":"3. 법 제34조제1항의 규정에 따른 실무교육의 수료확인증 사본(영 제36조제1항에 따라 실무교육을 위탁받은 기관 또는 단체가 실무교육 수료 여부를 등록관청이 전자적으로 확인할 수 있도록 조치한 경우는 제외한다) 4. 여권용 사진"},{"법령":"공인중개사법 시행규칙","조문":"제4조제1항제5호","원문":"5. 건축물대장에 기재된 건물(…)에 중개사무소를 확보(…)하였음을 증명하는 서류. 다만, 건축물대장에 기재되지 아니한 건물에 중개사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류도 함께 내야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제4조제1항제6호나목","원문":"나. 「상법」 제614조의 규정에 따른 영업소의 등기를 증명할 수 있는 서류"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격증 사본은 제출 서류가 아니다. 등록관청이 시·도지사에게 자격 확인을 요청한다(칙 제4조제1항)."},{"번호":2,"판정":"옳음","설명":"사용승인 후 대장 미기재 건물이면 기재 지연 사유서를 함께 낸다(칙 제4조제1항제5호 단서)."},{"번호":3,"판정":"옳음","설명":"여권용 사진을 낸다(칙 제4조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"위탁기관이 전자 확인 조치를 한 경우 수료확인증 사본 제출이 면제된다(칙 제4조제1항제3호 괄호)."},{"번호":5,"판정":"옳음","설명":"외국에 주된 영업소를 둔 법인은 상법 제614조의 영업소 등기 증명서류를 낸다(칙 제4조제1항제6호나목)."}],"개념":[{"종류":"흐름","제목":"중개사무소 개설등록 절차","단계":[{"이름":"실무교육","설명":"등록신청일 전 1년 이내 시·도지사 실시 실무교육 수료(법인은 사원·임원 전원). 폐업 후 1년 이내 재신청, 소속공인중개사 고용관계 종료 신고 후 1년 이내 신청은 면제(법 제34조제1항)"},{"이름":"신청서 제출","설명":"중개사무소 소재지 관할 등록관청에 개설등록신청서와 첨부서류 제출(칙 제4조제1항)"},{"이름":"자격·대장 확인","설명":"등록관청이 자격증 발급 시·도지사에게 자격 확인 요청, 법인 등기사항증명서·건축물대장은 행정정보 공동이용으로 확인"},{"이름":"등록·통지","설명":"신청받은 날부터 7일 이내에 법인/공인중개사로 구분해 등록하고 서면 통지(칙 제4조제2항)"},{"이름":"보증 설정·신고","설명":"업무개시 전 손해배상책임 보증을 설정하고 증명서류를 갖춰 등록관청에 신고(영 제24조제2항)"}]},{"종류":"표","제목":"개설등록 신청 시 서류","머리":["서류","제출 여부","근거"],"행":[["공인중개사자격증 사본","제출하지 않음(시·도지사에게 자격 확인 요청)","칙 제4조제1항"],["실무교육 수료확인증 사본","제출(전자 확인 조치된 경우 제외)","칙 제4조제1항제3호"],["여권용 사진","제출","칙 제4조제1항제4호"],["사무소 확보 증명서류","제출(대장 미기재 시 지연 사유서 추가)","칙 제4조제1항제5호"],["외국인·외국법인 서류","결격사유 부존재 증명서류 / 외국법인은 영업소 등기 증명서류","칙 제4조제1항제6호"]]}],"함정":"법인 등기사항증명서와 건축물대장은 등록관청이 직접 확인하므로 신청인이 낼 서류가 아니다. 자격증 사본도 같은 방식이라 1번이 그럴듯해 보인다."}},{"i":"S4-2-1-중개사법-04","r":"S4","g":2,"c":2,"n":4,"s":"중개사법","q":"공인중개사법령상 법인이 중개사무소를 개설하려는 경우 그 등록기준으로 옳은 것은? (다른 법률에 따라 중개업을 할 수 있는 경우는 제외함)","b":null,"bs":"없음","img":[],"ch":["「협동조합 기본법」에 따른 사회적협동조합으로서 자본금이 5천만원 이상일 것","법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것","대표자를 제외한 임원 또는 사원의 2분의 1 이상이 공인중개사일 것","대표자, 임원 또는 사원 중 공인중개사인 자가 실무교육을 받았을 것","건축물대장에 기재된 건물로서 전용면적 33제곱미터 이상인 중개사무소를 확보할 것"],"a":[2],"L":"중1-3","o":"변형","x":{"한줄":"법인은 법 제14조의 업무만 영위할 목적으로 설립된 법인이어야 하므로 2번이 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"제13조제1항제2호","원문":"2. 법인이 중개사무소를 개설하려는 경우 가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것 나. 법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것 다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(…)의 3분의 1 이상은 공인중개사일 것 라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(…)가 법 제34조제1항에 따른 실무교육을 받았을 것 마. 건축물대장에 기재된 건물에 중개사무소를 확보(…)할 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"사회적협동조합은 제외된다(영 제13조제1항제2호가목)."},{"번호":2,"판정":"옳음","설명":"영 제13조제1항제2호나목."},{"번호":3,"판정":"틀림","설명":"3분의 1 이상이다(영 제13조제1항제2호다목)."},{"번호":4,"판정":"틀림","설명":"공인중개사인지와 관계없이 대표자·임원·사원 전원이 받아야 한다(영 제13조제1항제2호라목)."},{"번호":5,"판정":"틀림","설명":"건축물대장에 기재된 건물에 사무소를 확보하면 되고 면적 기준은 없다(영 제13조제1항제2호마목)."}],"개념":[{"종류":"비교","제목":"공인중개사 개설등록 기준과 법인 개설등록 기준","왼쪽":{"이름":"공인중개사","항목":["실무교육 수료(법 제34조제1항)","건축물대장에 기재된 건물에 사무소 확보(소유·전세·임대차·사용대차 등 사용권)","자본금 요건 없음","겸업 제한 없음(법 제14조제1항은 법인 대상)"]},"오른쪽":{"이름":"법인","항목":["상법상 회사 또는 협동조합(사회적협동조합 제외), 자본금 5천만원 이상","법 제14조 업무만 영위할 목적으로 설립","대표자는 공인중개사, 나머지 임원·사원의 3분의 1 이상 공인중개사","대표자·임원·사원 전원(분사무소 설치 시 책임자 포함) 실무교육 수료","건축물대장에 기재된 건물에 사무소 확보"]}},{"종류":"표","제목":"개설등록 결격사유 기간 정리","머리":["사유","기간","근거"],"행":[["금고 이상 실형","집행 종료·면제일부터 3년","법 제10조제1항제4호"],["금고 이상 집행유예","유예기간 만료일부터 2년","법 제10조제1항제5호"],["공인중개사 자격취소","취소 후 3년","법 제10조제1항제6호"],["이 법 위반 벌금 300만원 이상","선고 후 3년","법 제10조제1항제11호"],["사원·임원 중 결격자가 있는 법인","결격 해당 자체(2개월 내 해소 시 취소 제외)","법 제10조제1항제12호, 제38조제1항제3호"]]}],"함정":"공인중개사 요건의 '3분의 1 이상'을 분모로 착각하기 쉽다. 대표자는 별도로 공인중개사여야 하고 비율은 대표자를 뺀 임원·사원에 적용한다. 실무교육은 비율이 아니라 전원이 대상이다."}},{"i":"S4-2-1-중개사법-05","r":"S4","g":2,"c":2,"n":5,"s":"중개사법","q":"공인중개사법령상 인장의 등록에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사와 소속공인중개사는 업무를 개시하기 전에 중개행위에 사용할 인장을 등록관청에 등록하여야 한다.","등록한 인장을 변경한 경우에는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록하여야 한다.","소속공인중개사의 인장 등록은 그에 대한 고용 신고와 같이 할 수 있다.","공인중개사인 개업공인중개사가 등록할 인장은 가로·세로 각각 5밀리미터 이상 20밀리미터 이내의 크기이어야 한다.","법인인 개업공인중개사의 분사무소에서 사용할 인장은 「상업등기규칙」에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다."],"a":[4],"L":"중1-4","o":"변형","x":{"한줄":"공인중개사인 개업공인중개사의 인장은 가로·세로 각각 7밀리미터 이상 30밀리미터 이내여야 하므로 4번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제9조제1항·제2항","원문":"① 개업공인중개사 및 소속공인중개사는 법 제16조제1항의 규정에 따라 업무를 개시하기 전에 중개행위에 사용할 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다. ② 제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제9조제3항","원문":"(…) 가족관계등록부 또는 주민등록표에 기재되어 있는 성명이 나타난 인장으로서 그 크기가 가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내인 인장이어야 하며, 법인인 개업공인중개사의 경우에는 「상업등기규칙」에 따라 신고한 법인의 인장이어야 한다. 다만, 분사무소에서 사용할 인장의 경우에는 「상업등기규칙」 제35조제3항에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"제9조제6항","원문":"제1항에 따른 인장의 등록은 다음 각 호의 신청이나 신고와 같이 할 수 있다. 1. 제4조에 따른 중개사무소 개설등록신청 2. 제8조에 따른 소속공인중개사ㆍ중개보조원에 대한 고용 신고"}],"선지":[{"번호":1,"판정":"옳음","설명":"칙 제9조제1항."},{"번호":2,"판정":"옳음","설명":"변경일부터 7일 이내 재등록(칙 제9조제2항)."},{"번호":3,"판정":"옳음","설명":"고용 신고와 같이 할 수 있다(칙 제9조제6항제2호)."},{"번호":4,"판정":"틀림","설명":"크기는 7밀리미터 이상 30밀리미터 이내다(칙 제9조제3항)."},{"번호":5,"판정":"옳음","설명":"분사무소 인장은 대표자 보증 인장을 등록할 수 있다(칙 제9조제3항 단서)."}],"개념":[{"종류":"표","제목":"인장등록 요점","머리":["항목","내용","근거"],"행":[["등록 대상","개업공인중개사, 소속공인중개사(중개보조원은 대상 아님)","법 제16조제1항"],["등록 시기","업무를 개시하기 전","칙 제9조제1항"],["변경 시","변경일부터 7일 이내 등록","칙 제9조제2항"],["인장 크기","가로·세로 각각 7mm 이상 30mm 이내, 가족관계등록부·주민등록표상 성명","칙 제9조제3항"],["법인 인장","상업등기규칙에 따라 신고한 법인 인장, 등록은 인감증명서 제출로 갈음","칙 제9조제3항·제4항"],["분사무소 인장","법인 대표자가 보증하는 인장 등록 가능","칙 제9조제3항 단서"],["같이 할 수 있는 절차","개설등록 신청, 고용 신고","칙 제9조제6항"],["위반 제재","개업공인중개사 업무정지 3개월 / 소속공인중개사 자격정지 3월","법 제39조제1항제2호, 제36조제1항제2호, 칙 별표 4·별표 3"]]}],"함정":"7이라는 숫자가 두 번 나온다. 변경 등록 기한 7일과 인장 크기 7밀리미터를 서로 바꿔 쓰면 헷갈린다. 중개보조원은 인장등록 대상이 아니다."}},{"i":"S4-2-1-중개사법-06","r":"S4","g":2,"c":2,"n":6,"s":"중개사법","q":"공인중개사법령상 법인인 개업공인중개사가 중개업과 함께 할 수 없는 업무는? (단, 다른 법률의 규정은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["주택의 임대업","상업용 건축물의 분양대행","부동산의 이용ㆍ개발 및 거래에 관한 상담","중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개","개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공"],"a":[1],"L":"중1-4","o":"기출","x":{"한줄":"법인은 주택의 '임대관리'는 할 수 있어도 '임대업' 자체는 법 제14조제1항에 열거되지 않아 할 수 없다.","근거":[{"법령":"공인중개사법","조문":"제14조제1항","원문":"법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다. 1. 상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행 2. 부동산의 이용ㆍ개발 및 거래에 관한 상담 3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공 4. 상업용 건축물 및 주택의 분양대행 5. 그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무"},{"법령":"공인중개사법 시행령","조문":"제17조제2항","원문":"법 제14조제1항제5호에서 \"대통령령이 정하는 업무\"라 함은 중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개 등 주거이전에 부수되는 용역의 알선을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"임대업은 열거 업무가 아니라 겸업할 수 없다. 열거된 것은 임대관리 등 관리대행이다(법 제14조제1항제1호)."},{"번호":2,"판정":"-","설명":"분양대행은 겸업할 수 있다(법 제14조제1항제4호)."},{"번호":3,"판정":"-","설명":"이용·개발 및 거래에 관한 상담은 겸업할 수 있다(법 제14조제1항제2호)."},{"번호":4,"판정":"-","설명":"도배·이사업체 소개는 영 제17조제2항에 따라 겸업할 수 있다(법 제14조제1항제5호)."},{"번호":5,"판정":"-","설명":"개업공인중개사 대상 경영기법·경영정보 제공은 겸업할 수 있다(법 제14조제1항제3호)."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사가 중개업과 함께 할 수 있는 업무","머리":["구분","업무","근거"],"행":[["1호","상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행","법 제14조제1항제1호"],["2호","부동산의 이용·개발 및 거래에 관한 상담","법 제14조제1항제2호"],["3호","개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공","법 제14조제1항제3호"],["4호","상업용 건축물 및 주택의 분양대행","법 제14조제1항제4호"],["5호","중개업에 부수되는 업무: 도배·이사업체 소개 등 주거이전에 부수되는 용역의 알선","법 제14조제1항제5호, 영 제17조제2항"],["제2항","경매·공매 대상 부동산의 권리분석·취득 알선, 매수신청·입찰신청 대리","법 제14조제2항"]]},{"종류":"비교","제목":"겸업 제한과 위반 효과","왼쪽":{"이름":"겸업 제한 대상","항목":["법인인 개업공인중개사만 해당(법 제14조제1항)","개인인 개업공인중개사는 이 조항의 겸업 제한이 없음","경매 매수신청 대리는 법원에 등록하고 감독을 받음(법 제14조제3항)"]},"오른쪽":{"이름":"위반 시","항목":["개설등록 취소 가능(법 제38조제2항제4호)","6개월 범위 업무정지 가능(법 제39조제1항제11호)","청문 대상(법 제38조제3항)"]}}],"함정":"임대'관리'(관리대행)와 임대'업'은 다르다. 관리대행은 남의 부동산을 맡아 관리하는 일이라 열거 업무이고, 자기 주택을 임대하는 임대업은 열거에 없다."}},{"i":"S4-2-1-중개사법-07","r":"S4","g":2,"c":2,"n":7,"s":"중개사법","q":"공인중개사법령상 인터넷 표시ㆍ광고 모니터링 등에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 국토교통부장관은 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관에 모니터링 업무를 위탁할 수 있다.\nㄴ. 모니터링 기관은 기본 모니터링 업무에 관한 결과보고서를 해당 모니터링 업무를 완료한 날부터 15일 이내에 국토교통부장관에게 제출해야 한다.\nㄷ. 국토교통부장관은 모니터링 기관으로부터 모니터링 업무에 관하여 제출받은 결과보고서를 시·도지사 및 등록관청 등에 통보하고 필요한 조사 및 조치를 요구할 수 있다.","bs":"글자","img":[],"ch":["ㄴ","ㄷ","ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[4],"L":"중1-4","o":"기출","x":{"한줄":"ㄱ과 ㄷ은 맞고, ㄴ은 완료일부터 15일 이내가 수시 모니터링의 기한이라 틀려서 4번이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제17조의3제1항제1호","원문":"국토교통부장관은 법 제18조의3제4항에 따라 다음 각 호의 어느 하나에 해당하는 기관에 같은 조 제1항에 따른 모니터링 업무를 위탁할 수 있다. 1. 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관"},{"법령":"공인중개사법 시행규칙","조문":"제10조의3제3항","원문":"모니터링 기관은 제1항에 따라 업무를 수행한 경우 해당 업무에 따른 결과보고서를 다음 각 호의 구분에 따른 기한까지 국토교통부장관에게 제출해야 한다. 1. 기본 모니터링 업무: 매 분기의 마지막 날부터 30일 이내 2. 수시 모니터링 업무: 해당 모니터링 업무를 완료한 날부터 15일 이내"},{"법령":"공인중개사법 시행규칙","조문":"제10조의3제4항","원문":"국토교통부장관은 제3항에 따라 제출받은 결과보고서를 시ㆍ도지사 및 등록관청 등에 통보하고 필요한 조사 및 조치를 요구할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ만으로는 부족하다. ㄴ이 틀렸다."},{"번호":2,"판정":"-","설명":"ㄷ만 고르면 ㄱ이 빠진다."},{"번호":3,"판정":"-","설명":"ㄴ이 틀렸으므로 포함할 수 없다."},{"번호":4,"판정":"-","설명":"ㄱ, ㄷ이 옳은 조합이다."},{"번호":5,"판정":"-","설명":"ㄴ이 틀렸으므로 3개 전부는 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"공공기관은 위탁 가능 기관이다(영 제17조의3제1항제1호)."},{"기호":"ㄴ","판정":"틀림","설명":"기본 모니터링은 매 분기 마지막 날부터 30일 이내다. 완료일부터 15일 이내는 수시 모니터링이다(칙 제10조의3제3항)."},{"기호":"ㄷ","판정":"옳음","설명":"칙 제10조의3제4항."}],"개념":[{"종류":"표","제목":"기본 모니터링과 수시 모니터링","머리":["구분","기본 모니터링","수시 모니터링"],"행":[["실시","기본계획서에 따라 분기별","위반 의심 등 국토교통부장관이 필요하다고 판단할 때"],["계획서 제출","다음 연도 기본계획서를 매년 12월 31일까지","기간·내용·방법 등을 담은 계획서 제출"],["결과보고서 기한","매 분기의 마지막 날부터 30일 이내","업무 완료일부터 15일 이내"],["근거","칙 제10조의3제1항제1호·제2항제1호·제3항제1호","칙 제10조의3제1항제2호·제2항제2호·제3항제2호"]]},{"종류":"흐름","제목":"모니터링 결과 처리","단계":[{"이름":"모니터링 실시","설명":"국토교통부장관이 인터넷 표시·광고의 법 제18조의2 준수 여부를 점검, 업무는 위탁 가능(법 제18조의3제1항·제4항)"},{"이름":"결과보고서 제출","설명":"모니터링 기관이 국토교통부장관에게 제출(기본 분기 말일부터 30일, 수시 완료일부터 15일)"},{"이름":"통보·조치 요구","설명":"국토교통부장관이 시·도지사·등록관청 등에 통보하고 조사·조치 요구(칙 제10조의3제4항)"},{"이름":"결과 회신","설명":"시·도지사·등록관청 등이 조사·조치를 완료한 날부터 10일 이내에 국토교통부장관에게 통보(칙 제10조의3제5항)"}]}],"함정":"15일과 30일을 서로 바꿔 놓은 선지가 반복된다. 분기 단위로 도는 기본 모니터링이 30일, 건별로 도는 수시 모니터링이 15일이다."}},{"i":"S4-2-1-중개사법-08","r":"S4","g":2,"c":2,"n":8,"s":"중개사법","q":"공인중개사법령상 중개사무소의 이전·휴업·폐업에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 중개사무소를 등록관청의 관할 지역 안으로 이전한 경우에는 이전한 날부터 7일 이내에 등록관청에 신고하여야 한다.","개업공인중개사는 질병으로 인한 요양 등 대통령령으로 정하는 부득이한 사유가 있는 경우에는 6개월을 초과하여 휴업할 수 있다.","개업공인중개사가 2개월 동안 휴업한 중개업을 재개하는 경우에도 등록관청에 재개 신고를 하여야 한다.","개업공인중개사가 폐업신고를 하는 경우에는 중개사무소등록증을 첨부할 필요가 없다.","분사무소를 둔 법인인 개업공인중개사는 휴업·폐업 신고를 주된 사무소 단위로만 할 수 있다."],"a":[2],"L":"중1-4","o":"변형","x":{"한줄":"휴업은 6개월을 넘길 수 없지만 질병으로 인한 요양 같은 부득이한 사유가 있으면 예외이므로 2번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제21조제2항","원문":"제1항에 따른 휴업은 6개월을 초과할 수 없다. 다만, 질병으로 인한 요양등 대통령령으로 정하는 부득이한 사유가 있는 경우에는 그러하지 아니하다."},{"법령":"공인중개사법 시행령","조문":"제18조제6항","원문":"법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. 1. 질병으로 인한 요양 2. 징집으로 인한 입영 3. 취학 4. 임신 또는 출산 5. 그 밖에 제1호부터 제4호까지의 규정에 준하는 부득이한 사유로서 국토교통부장관이 정하여 고시하는 사유"},{"법령":"공인중개사법","조문":"제20조제1항 본문","원문":"개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제18조제1항","원문":"(…) 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(…)해야 한다. 1. 3개월을 초과하여 휴업(…)하려는 경우 2. 폐업하려는 경우 3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우 4. 신고한 휴업기간을 변경하려는 경우"},{"법령":"공인중개사법 시행령","조문":"제18조제2항 전단","원문":"법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이전 신고는 이전한 날부터 10일 이내다(법 제20조제1항)."},{"번호":2,"판정":"옳음","설명":"법 제21조제2항 단서, 영 제18조제6항."},{"번호":3,"판정":"틀림","설명":"재개 신고 대상은 3개월을 초과하여 휴업한 중개업의 재개다(영 제18조제1항제3호). 2개월 휴업은 신고 없이 재개한다."},{"번호":4,"판정":"틀림","설명":"휴업(3개월 초과)·폐업 신고에는 등록증을 첨부한다(영 제18조제1항)."},{"번호":5,"판정":"틀림","설명":"분사무소별로 신고할 수 있다(영 제18조제2항)."}],"개념":[{"종류":"표","제목":"이전·휴업·폐업 신고 정리","머리":["사유","신고 시기·방법","근거"],"행":[["사무소 이전","이전한 날부터 10일 이내 신고. 관할 외로 이전하면 이전 후 등록관청에 신고","법 제20조제1항"],["3개월 초과 휴업","미리 신고, 등록증 첨부. 휴업은 6개월 초과 불가(부득이한 사유 예외)","법 제21조, 영 제18조"],["폐업","미리 신고, 등록증 첨부","영 제18조제1항제2호"],["3개월 초과 휴업 후 재개","신고(등록증 반환받음)","영 제18조제1항제3호·제5항"],["휴업기간 변경","신고","영 제18조제1항제4호"],["간판 철거","이전·폐업 신고 또는 등록취소 시 지체 없이 철거, 미이행 시 대집행 가능","법 제21조의2"],["신고 불이행","100만원 이하 과태료","법 제51조제3항제3호·제4호"]]},{"종류":"표","제목":"휴업을 6개월 넘길 수 있는 부득이한 사유","머리":["번호","사유"],"행":[["1","질병으로 인한 요양"],["2","징집으로 인한 입영"],["3","취학"],["4","임신 또는 출산"],["5","준하는 사유로서 국토교통부장관이 고시하는 사유"]]}],"함정":"이전 신고의 10일, 재개 신고의 '3개월 초과' 요건을 놓치기 쉽다. 3개월 이하 휴업은 휴업·재개 모두 신고 대상이 아니다."}},{"i":"S4-2-1-중개사법-09","r":"S4","g":2,"c":2,"n":9,"s":"중개사법","q":"공인중개사법령상 개업공인중개사가 의뢰받은 중개대상물에 대하여 표시·광고를 하는 경우에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["중개보조원이 있는 경우 개업공인중개사의 성명과 함께 중개보조원의 성명도 명시할 수 있다.","개업공인중개사가 아닌 자도 인터넷을 이용한 중개대상물의 표시·광고는 할 수 있다.","중개대상물의 가격 등 내용을 사실과 다르게 거짓으로 표시·광고한 개업공인중개사는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.","모니터링 기관은 기본 모니터링 업무의 결과보고서를 매 분기의 마지막 날부터 15일 이내에 국토교통부장관에게 제출해야 한다.","법인인 개업공인중개사가 중개대상물을 표시·광고하는 경우 개업공인중개사의 성명으로 대표자의 성명을 명시하여야 한다."],"a":[5],"L":"중1-4","o":"변형","x":{"한줄":"법인은 개업공인중개사 성명 항목에 대표자의 성명을 명시하므로 5번이 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"제17조의2제1항","원문":"법 제18조의2제1항에서 \"대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 중개사무소의 명칭, 소재지, 연락처 및 등록번호 2. 개업공인중개사의 성명(법인인 경우에는 대표자의 성명)"},{"법령":"공인중개사법","조문":"제18조의2제1항","원문":"개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(…)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법","조문":"제18조의2제3항","원문":"개업공인중개사가 아닌 자는 중개대상물에 대한 표시ㆍ광고를 하여서는 아니 된다."},{"법령":"공인중개사법","조문":"제51조제2항제1호","원문":"제18조의2제4항 각 호를 위반하여 부당한 표시ㆍ광고를 한 자 [500만원 이하의 과태료]"}],"선지":[{"번호":1,"판정":"틀림","설명":"중개보조원에 관한 사항은 명시할 수 없다(법 제18조의2제1항)."},{"번호":2,"판정":"틀림","설명":"개업공인중개사가 아닌 자의 중개대상물 표시·광고는 금지된다(법 제18조의2제3항)."},{"번호":3,"판정":"틀림","설명":"거짓 표시·광고는 부당한 표시·광고로 500만원 이하 과태료다(법 제18조의2제4항제2호, 제51조제2항제1호). 징역·벌금은 비개업자의 표시·광고에 적용된다(법 제49조제1항제6호의2)."},{"번호":4,"판정":"틀림","설명":"기본 모니터링 결과보고서는 분기 마지막 날부터 30일 이내다(칙 제10조의3제3항제1호)."},{"번호":5,"판정":"옳음","설명":"영 제17조의2제1항제2호."}],"개념":[{"종류":"표","제목":"표시·광고 규제 정리","머리":["구분","내용","근거·제재"],"행":[["명시사항","중개사무소 명칭·소재지·연락처·등록번호, 개업공인중개사 성명(법인은 대표자)","영 제17조의2제1항. 위반 시 100만원 이하 과태료(법 제51조제3항제2호의2)"],["인터넷 추가 명시","소재지, 면적, 가격, 중개대상물 종류, 거래 형태, 건축물은 총 층수·사용승인일 등","영 제17조의2제2항"],["중개보조원","중개보조원에 관한 사항은 명시 금지","법 제18조의2제1항"],["비개업자","중개대상물 표시·광고 금지","법 제18조의2제3항, 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제6호의2)"],["부당 표시·광고","존재하지 않는 물건, 거짓·과장, 거래질서를 해칠 우려가 있는 내용","법 제18조의2제4항, 500만원 이하 과태료(법 제51조제2항제1호)"],["세부 방법","국토교통부장관 고시","법 제18조의2제5항, 영 제17조의2제3항"]]},{"종류":"표","제목":"영 제17조의2제4항: 부당 표시·광고(제3호 위임 내용)","머리":["번호","내용"],"행":[["1","존재하지만 실제로 중개의 대상이 될 수 없는 중개대상물에 대한 표시·광고"],["2","존재하지만 실제로 중개할 의사가 없는 중개대상물에 대한 표시·광고"],["3","입지조건·생활여건·가격 및 거래조건 등 중요한 사실을 빠뜨리거나 은폐·축소하여 소비자를 속이는 표시·광고"],["참고","비개업자의 표시·광고(법 제18조의2제3항 위반)를 신고·고발한 자는 포상금 지급 대상(법 제46조제1항제4호, 1건당 50만원)"]]}],"함정":"같은 광고 위반이라도 비개업자의 표시·광고는 형벌(1년 이하 징역·1천만원 이하 벌금)이고 개업공인중개사의 부당 표시·광고는 과태료다. 징역·벌금 선지는 주체를 먼저 본다."}},{"i":"S4-2-1-중개사법-10","r":"S4","g":2,"c":2,"n":10,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 고용인에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["소속공인중개사의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다.","개업공인중개사 甲이 소속공인중개사 2명을 고용한 경우 甲은 중개보조원을 최대 15명까지 고용할 수 있다.","중개보조원은 현장안내 등 중개업무를 보조하는 경우 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알려야 한다.","고용 신고를 받은 등록관청은 결격사유 해당 여부와 교육 수료 여부를 확인하여야 한다.","개업공인중개사는 중개보조원을 고용한 날부터 10일 이내에 등록관청에 신고하여야 한다."],"a":[5],"L":"중1-5","o":"변형","x":{"한줄":"고용 신고는 업무개시 전까지 하고, 10일 이내 기한은 고용관계 종료 신고에 적용되므로 5번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제8조제1항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원을 고용한 경우에는 법 제34조제2항 또는 제3항에 따른 교육을 받도록 한 후 법 제15조제1항에 따라 업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제8조제4항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원과의 고용관계가 종료된 때에는 법 제15조제1항에 따라 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다."},{"법령":"공인중개사법","조문":"제15조제3항","원문":"개업공인중개사가 고용할 수 있는 중개보조원의 수는 개업공인중개사와 소속공인중개사를 합한 수의 5배를 초과하여서는 아니 된다. <신설 2023.4.18>"},{"법령":"공인중개사법 시행규칙","조문":"제8조제3항","원문":"제1항에 따른 고용 신고를 받은 등록관청은 법 제10조제2항에 따른 결격사유 해당 여부와 법 제34조제2항 또는 제3항에 따른 교육 수료 여부를 확인하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제15조제2항."},{"번호":2,"판정":"옳음","설명":"(개업공인중개사 1명 + 소속공인중개사 2명) × 5 = 15명이 상한이다(법 제15조제3항)."},{"번호":3,"판정":"옳음","설명":"법 제18조의4."},{"번호":4,"판정":"옳음","설명":"칙 제8조제3항."},{"번호":5,"판정":"틀림","설명":"고용은 업무개시 전까지 신고한다(칙 제8조제1항). 고용관계 종료만 종료일부터 10일 이내다(칙 제8조제4항)."}],"개념":[{"종류":"표","제목":"고용인 규율 정리","머리":["항목","내용","근거·제재"],"행":[["고용 신고","교육을 받게 한 후 업무개시 전까지 등록관청에 신고(전자문서 가능)","칙 제8조제1항"],["종료 신고","고용관계 종료일부터 10일 이내","칙 제8조제4항"],["행위 귀속","소속공인중개사·중개보조원의 업무상 행위는 고용한 개업공인중개사의 행위","법 제15조제2항"],["중개보조원 수","(개업공인중개사 + 소속공인중개사) × 5 초과 금지","법 제15조제3항. 위반 시 등록취소(법 제38조제1항제5호의2), 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제5호의2)"],["신분 고지","중개보조원은 중개의뢰인에게 미리 중개보조원임을 알림","법 제18조의4. 위반 시 500만원 이하 과태료(법 제51조제2항제1호의4)"],["결격자 고용","결격사유(법 제10조제1항제1호~제11호) 해당자를 고용하면 6개월 범위 업무정지, 2개월 내 해소하면 제외","법 제39조제1항제1호"]]},{"종류":"표","제목":"고용 전 교육","머리":["대상","교육","시기·시간","면제"],"행":[["소속공인중개사","실무교육","고용 신고일 전 1년 이내(영 제28조제1항 시간)","고용관계 종료 신고 후 1년 이내 재신고 등(법 제34조제2항)"],["중개보조원","직무교육","고용 신고일 전 1년 이내, 3시간 이상 4시간 이하","고용관계 종료 신고 후 1년 이내 재신고(법 제34조제3항, 영 제28조제2항)"]]}],"함정":"10일이라는 기한은 고용 종료 신고에만 있다. 고용 신고는 날짜 기한이 아니라 '업무개시 전'이다. 중개보조원 수 계산에서 개업공인중개사 본인을 빼먹는 실수도 잦다.","개정":"중개보조원 수 제한은 법 제15조제3항(신설 2023.4.18)이다. 이를 위반한 중개보조원 고용은 등록취소 사유(법 제38조제1항제5호의2)가 되었다."}},{"i":"S4-2-1-중개사법-11","r":"S4","g":2,"c":2,"n":11,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 일반중개계약과 전속중개계약에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["일반중개계약은 중개의뢰인이 중개대상물의 중개를 의뢰하기 위해 특정한 개업공인중개사를 정하여 그 개업공인중개사에 한정하여 중개대상물을 중개하도록 하는 계약을 말한다.","개업공인중개사가 일반중개계약을 체결한 때에는 중개의뢰인이 비공개를 요청하지 않은 경우, 부동산거래정보망에 해당 중개대상물에 관한 정보를 공개해야 한다.","개업공인중개사가 일반중개계약을 체결한 때에는 중개의뢰인에게 2주일에 1회 이상 중개업무 처리상황을 문서로 통지해야 한다.","개업공인중개사가 국토교통부령으로 정하는 전속중개계약서에 의하지 아니하고 전속중개계약을 체결한 행위는 업무정지 사유에 해당하지 않는다.","표준서식인 일반중개계약서와 전속중개계약서에는 개업공인중개사가 중개보수를 과다수령 시 그 차액의 환급을 공통적으로 규정하고 있다."],"a":[5],"L":"중1-6","o":"기출","x":{"한줄":"일반·전속 두 표준서식 모두 중개보수 또는 실비를 과다수령하면 차액을 환급하도록 정하므로 5번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제23조제1항","원문":"중개의뢰인은 중개대상물의 중개를 의뢰하는 경우 특정한 개업공인중개사를 정하여 그 개업공인중개사에 한정하여 해당 중개대상물을 중개하도록 하는 계약(이하 \"전속중개계약\"이라 한다)을 체결할 수 있다."},{"법령":"공인중개사법","조문":"제23조제3항","원문":"개업공인중개사는 전속중개계약을 체결한 때에는 제24조에 따른 부동산거래정보망 또는 일간신문에 해당 중개대상물에 관한 정보를 공개하여야 한다. 다만, 중개의뢰인이 비공개를 요청한 경우에는 이를 공개하여서는 아니된다."},{"법령":"공인중개사법","조문":"제39조제1항제3호","원문":"제23조제2항의 규정을 위반하여 국토교통부령으로 정하는 전속중개계약서에 의하지 아니하고 전속중개계약을 체결하거나 계약서를 보존하지 아니한 경우"},{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서) 5.","원문":"을의 손해배상 책임 … 1) 중개보수 또는 실비의 과다수령: 차액 환급 2) 중개대상물의 확인ㆍ설명을 소홀히 하여 재산상의 피해를 발생하게 한 경우: 손해액 배상"},{"법령":"공인중개사법 시행규칙","조문":"별지 제14호서식(일반중개계약서) 손해배상 책임","원문":"1) 중개보수 또는 실비의 과다수령: 차액 환급"}],"선지":[{"번호":1,"판정":"틀림","설명":"특정 개업공인중개사에 한정하는 계약은 전속중개계약이다(법 제23조제1항). 일반중개계약은 한정하지 않는다."},{"번호":2,"판정":"틀림","설명":"정보 공개 의무는 전속중개계약을 체결한 때 생긴다(법 제23조제3항). 일반중개계약에는 공개 의무가 없다."},{"번호":3,"판정":"틀림","설명":"2주일에 1회 이상 문서 통지는 전속중개계약서의 개업공인중개사 의무다(칙 전속중개계약서 1.①)."},{"번호":4,"판정":"틀림","설명":"전속중개계약서 서식 위반은 업무정지 사유다(법 제39조제1항제3호, 칙 별표 4: 3개월)."},{"번호":5,"판정":"옳음","설명":"두 서식 모두 과다수령 시 차액 환급을 규정한다."}],"개념":[{"종류":"비교","제목":"일반중개계약과 전속중개계약","왼쪽":{"이름":"일반중개계약","항목":["중개의뢰인이 필요하면 작성을 요청할 수 있음(법 제22조)","여러 개업공인중개사에게 중복 의뢰 가능","표준서식 사용을 권장(영 제19조)","정보 공개 의무·처리상황 통지 의무 없음","서식 위반은 업무정지 사유 아님"]},"오른쪽":{"이름":"전속중개계약","항목":["특정 개업공인중개사에 한정해 중개하도록 하는 계약(법 제23조제1항)","국토교통부령 서식(별지 제15호)에 의해야 함","체결 후 7일 이내 정보망·일간신문에 공개(비공개 요청 시 공개 금지)","계약 체결 후 2주일에 1회 이상 처리상황을 문서로 통지","서식 위반·계약서 미보존은 업무정지 사유(법 제39조제1항제3호)"]}},{"종류":"표","제목":"일반중개계약서 기재사항(법 제22조)","머리":["호","기재사항"],"행":[["1","중개대상물의 위치 및 규모"],["2","거래예정가격"],["3","거래예정가격에 대하여 제32조에 따라 정한 중개보수"],["4","그 밖에 개업공인중개사와 중개의뢰인이 준수하여야 할 사항"]]}],"함정":"일반중개계약에 전속계약의 의무(공개, 2주 통지, 서식 강제)를 붙인 선지가 번갈아 나온다. 두 계약에 공통인 것은 과다수령 시 차액 환급 같은 서식 내용뿐이다."}},{"i":"S4-2-1-중개사법-12","r":"S4","g":2,"c":2,"n":12,"s":"중개사법","q":"甲 소유의 X부동산을 매도하기 위한 甲과 개업공인중개사 乙의 전속중개계약에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙은 甲과 체결한 전속중개계약의 계약서를 3년 동안 보존하여야 한다.","甲과 乙이 전속중개계약의 유효기간을 약정하지 않은 경우 유효기간은 6개월로 한다.","乙이 전속중개계약서를 보존하지 아니한 경우 이는 업무정지 사유에 해당한다.","乙이 X부동산에 관한 정보를 공개하는 경우 각 권리자의 주소·성명 등 인적 사항은 공개하여서는 아니 된다.","甲이 비공개를 요청하였음에도 乙이 X부동산에 관한 정보를 공개한 경우 이는 등록관청이 개설등록을 취소할 수 있는 사유에 해당한다."],"a":[2],"L":"중1-6","o":"변형","x":{"한줄":"전속중개계약의 유효기간은 약정이 없으면 3개월이므로 6개월이라고 한 2번이 틀렸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"제14조제2항","원문":"법 제23조제2항에서 \"국토교통부령이 정하는 기간\"이라 함은 3년을 말한다."},{"법령":"공인중개사법 시행령","조문":"제20조제2항제5호","원문":"소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항. 다만, 각 권리자의 주소ㆍ성명 등 인적 사항에 관한 정보는 공개하여서는 아니 된다."},{"법령":"공인중개사법","조문":"제38조제2항제6호","원문":"제23조제3항의 규정을 위반하여 중개대상물에 관한 정보를 공개하지 아니하거나 중개의뢰인의 비공개요청에도 불구하고 정보를 공개한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"보존기간은 3년이다(법 제23조제2항, 칙 제14조제2항)."},{"번호":2,"판정":"틀림","설명":"약정이 없으면 3개월이다(영 제20조제1항)."},{"번호":3,"판정":"옳음","설명":"계약서 미보존은 업무정지 사유다(법 제39조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"영 제20조제2항제5호 단서."},{"번호":5,"판정":"옳음","설명":"비공개 요청을 어긴 공개는 임의적 등록취소 사유다(법 제38조제2항제6호)."}],"개념":[{"종류":"흐름","제목":"전속중개계약 체결 후 개업공인중개사의 의무","단계":[{"이름":"계약서 작성","설명":"별지 제15호서식 전속중개계약서로 체결. 유효기간은 약정이 없으면 3개월(영 제20조제1항)"},{"이름":"정보 공개","설명":"체결 후 7일 이내에 부동산거래정보망 또는 일간신문에 공개. 중개의뢰인이 비공개를 요청하면 공개 금지(법 제23조제3항, 서식 1.②)"},{"이름":"공개 통지","설명":"공개한 때에는 지체 없이 중개의뢰인에게 그 내용을 문서로 통지(서식 1.②)"},{"이름":"처리상황 통지","설명":"계약 체결 후 2주일에 1회 이상 중개업무 처리상황을 문서로 통지(서식 1.①)"},{"이름":"계약서 보존","설명":"3년 보존(칙 제14조제2항). 위반 시 업무정지 3개월(칙 별표 4)"}]},{"종류":"표","제목":"전속중개계약 공개 정보와 중개의뢰인의 위약금","머리":["항목","내용","근거"],"행":[["공개 정보 1","중개대상물을 특정하는 사항(종류·소재지·지목·면적·용도·구조·건축연도)","영 제20조제2항제1호"],["공개 정보 2","벽면·도배 상태, 수도·전기·가스 등 설비 상태","영 제20조제2항제2호·제3호"],["공개 정보 3","도로·대중교통 연계성, 입지·환경 조건","영 제20조제2항제4호"],["공개 정보 4","권리관계(권리자 인적 사항은 공개 금지), 공법상 이용제한·거래규제","영 제20조제2항제5호·제6호"],["공개 정보 5","거래예정금액 및 공시지가(임대차는 공시지가 생략 가능)","영 제20조제2항제7호"],["위약금(서식 2.①)","유효기간 내 다른 개업공인중개사에게 의뢰해 거래하거나 乙을 배제하고 직접 거래한 경우 중개보수 상당액, 甲이 스스로 발견한 상대방과 거래한 경우 중개보수의 50% 범위의 소요비용","별지 제15호서식"]]}],"함정":"일반적으로 외우는 '3개월'이 유효기간이고 '3년'이 계약서 보존기간이며 '7일'이 공개 기한이다. 숫자 세 개를 서로 바꿔 놓은 선지가 나온다."}},{"i":"S4-2-1-중개사법-13","r":"S4","g":2,"c":2,"n":13,"s":"중개사법","q":"공인중개사법령상 부동산거래질서교란행위 신고센터(이하 \"신고센터\"라 함)에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 국토교통부장관은 부동산 시장의 건전한 거래질서를 조성하기 위하여 신고센터를 설치·운영할 수 있다.\nㄴ. 국토교통부장관은 신고센터의 업무를 「한국산업인력공단법」에 따른 한국산업인력공단에 위탁한다.\nㄷ. 누구든지 부동산거래질서교란행위를 발견하는 경우 그 사실을 신고센터에 신고할 수 있다.","bs":"글자","img":[],"ch":["ㄱ","ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[3],"L":"중1-7","o":"기출","x":{"한줄":"신고센터 업무는 한국부동산원에 위탁하므로 ㄴ이 틀리고, ㄱ과 ㄷ이 옳아 3번이다.","근거":[{"법령":"공인중개사법","조문":"제47조의2제1항","원문":"국토교통부장관은 부동산 시장의 건전한 거래질서를 조성하기 위하여 부동산거래질서교란행위 신고센터(이하 이 조에서 \"신고센터\"라 한다)를 설치ㆍ운영할 수 있다."},{"법령":"공인중개사법","조문":"제47조의2제2항 본문","원문":"누구든지 부동산중개업 및 부동산 시장의 건전한 거래질서를 해치는 다음 각 호의 어느 하나에 해당하는 행위(이하 \"부동산거래질서교란행위\"라 한다)를 발견하는 경우 그 사실을 신고센터에 신고할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제37조제7항","원문":"국토교통부장관은 법 제47조의2제4항에 따라 같은 조 제3항에 따른 신고센터의 업무를 「한국부동산원법」에 따른 한국부동산원(이하 \"한국부동산원\"이라 한다)에 위탁한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄷ이 빠졌다."},{"번호":2,"판정":"-","설명":"ㄴ은 틀린 보기다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄷ이 옳은 조합이다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀렸다."},{"번호":5,"판정":"-","설명":"ㄴ이 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"법 제47조의2제1항."},{"기호":"ㄴ","판정":"틀림","설명":"위탁 기관은 한국부동산원이다(영 제37조제7항)."},{"기호":"ㄷ","판정":"옳음","설명":"누구든지 신고할 수 있다(법 제47조의2제2항)."}],"개념":[{"종류":"흐름","제목":"신고센터 처리 절차","단계":[{"이름":"신고","설명":"누구든지 신고인·피신고인 인적사항, 발생일시·장소·내용, 증거자료 등을 서면(전자문서 포함)으로 제출(영 제37조제1항)"},{"이름":"보완 요청","설명":"보완이 필요하면 기간을 정해 신고인에게 요청(영 제37조제2항)"},{"이름":"조사·조치 요구","설명":"시·도지사 및 등록관청 등에 요구. 명백한 거짓 등은 국토교통부장관 승인을 받아 종결 가능(영 제37조제3항)"},{"이름":"결과 통보","설명":"시·도지사·등록관청 등은 완료한 날부터 10일 이내 신고센터에 통보, 신고센터는 신고인에게 처리결과 통보(영 제37조제4항·제5항)"},{"이름":"월간 보고","설명":"신고센터는 매월 10일까지 직전 달의 접수·처리 결과를 국토교통부장관에게 제출(영 제37조제6항)"}]},{"종류":"표","제목":"부동산거래질서교란행위(법 제47조의2제2항)","머리":["호","위반 대상 조문"],"행":[["제1호","법 제7조~제9조, 제18조의4, 제33조제2항 위반(자격증 대여, 유사명칭, 무등록 중개업, 중개보조원 고지의무, 업무방해 등)"],["제2호","법 제48조제2호 해당 행위(거짓·부정한 방법으로 개설등록)"],["제3호","개업공인중개사가 제12조제1항, 제13조제1항·제2항, 제14조제1항, 제15조제3항, 제17조, 제18조, 제19조, 제25조제1항, 제25조의3, 제26조제3항을 위반"],["제4호","개업공인중개사등이 제12조제2항, 제29조제2항, 제33조제1항 위반"],["제5호","「부동산 거래신고 등에 관한 법률」 제3조, 제3조의2, 제4조 위반"]]}],"함정":"위탁 기관을 모르면 ㄴ이 그럴듯하다. 자격시험·교육 위탁 기관(공기업·준정부기관·협회 등)과 신고센터 위탁 기관(한국부동산원)을 섞지 않는다.","개정":"신고센터는 법 제47조의2(개정 2023.6.1)에 따라 운영되며 신고 대상 행위가 같은 항 각 호로 열거된다."}},{"i":"S4-2-1-중개사법-14","r":"S4","g":2,"c":2,"n":14,"s":"중개사법","q":"개업공인중개사 甲과 그의 소속공인중개사 乙이 법정한도를 초과하는 중개보수를 받았다. 공인중개사법령상 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["등록관청은 甲의 중개사무소 개설등록을 취소할 수 있다.","등록관청은 甲에게 6개월의 범위에서 업무의 정지를 명할 수 있다.","乙은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처해질 수 있다.","시·도지사는 乙의 공인중개사 자격을 취소하여야 한다.","법정한도를 초과하는 중개보수 약정은 그 초과하는 부분만 무효이다."],"a":[4],"L":"중1-7","o":"변형","x":{"한줄":"금지행위를 한 소속공인중개사는 자격정지(6개월 범위) 대상이지 자격취소 대상이 아니어서 4번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제33조제1항제3호","원문":"사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위"},{"법령":"공인중개사법","조문":"제36조제1항제7호","원문":"시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다. … 7. 제33조제1항 각 호에 규정된 금지행위를 한 경우"},{"법령":"공인중개사법","조문":"제38조제2항제9호","원문":"제33조제1항 각 호에 규정된 금지행위를 한 경우 [등록관청은 중개사무소의 개설등록을 취소할 수 있다]"},{"법령":"공인중개사법","조문":"제39조제1항제11호","원문":"제38조제2항 각 호의 어느 하나에 해당하는 경우 [6개월의 범위 안에서 업무의 정지를 명할 수 있다]"},{"법령":"공인중개사법","조문":"제49조제1항제10호","원문":"제33조제1항제1호부터 제4호까지의 규정을 위반한 자 [1년 이하의 징역 또는 1천만원 이하의 벌금]"},{"판례":"대법원 판례(중개보수 한도 초과 약정)","요지":"공인중개사법령이 정한 한도를 초과하는 중개보수 약정은 한도를 초과하는 부분에 한하여 무효다. 한도 이내의 보수 약정까지 무효가 되지는 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"금지행위는 임의적 등록취소 사유다(법 제38조제2항제9호)."},{"번호":2,"판정":"옳음","설명":"법 제38조제2항 사유는 업무정지 사유이기도 하다(법 제39조제1항제11호)."},{"번호":3,"판정":"옳음","설명":"제33조제1항제3호 위반은 제49조제1항제10호 대상이고, 행위자는 소속공인중개사여도 개업공인중개사등에 포함된다."},{"번호":4,"판정":"틀림","설명":"자격취소 사유는 법 제35조제1항 각 호(부정 취득, 자격증 대여, 정지기간 중 업무, 일정 범죄 형 선고)로 한정된다. 금지행위는 자격정지(6개월 범위, 칙 별표 3: 6월) 사유다(법 제36조제1항제7호)."},{"번호":5,"판정":"옳음","설명":"판례 요지. 한도 초과분만 무효다."}],"개념":[{"종류":"표","제목":"금지행위(법 제33조제1항) 형벌 구분","머리":["호","금지행위","벌칙"],"행":[["1호","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["2호","무등록 중개업자인 사실을 알면서 중개를 의뢰받거나 명의를 이용하게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금"],["3호","보수·실비를 초과하여 금품을 받는 행위","1년 이하 징역 또는 1천만원 이하 벌금"],["4호","중요사항에 관한 거짓된 언행으로 판단을 그르치게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금"],["5호~9호","전매금지 증서 중개, 직접 거래·쌍방 대리, 투기 조장, 시세 조작, 단체 구성 제한 등","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"]]},{"종류":"표","제목":"금지행위 위반의 행정처분","머리":["대상","처분","근거"],"행":[["개업공인중개사","개설등록 취소 가능(청문), 6개월 범위 업무정지 가능","법 제38조제2항제9호, 제39조제1항제11호"],["소속공인중개사","6개월 범위 자격정지(기준 6월), 가중해도 6월 초과 불가","법 제36조제1항제7호, 칙 제22조, 별표 3"],["개업공인중개사(양벌)","소속공인중개사 등의 위반에 상당한 주의·감독을 게을리하지 않았다면 면책","법 제50조"]]}],"함정":"소속공인중개사의 금지행위는 자격'정지'다. 자격취소는 법 제35조의 4가지 사유뿐이다. 개업공인중개사의 등록취소는 '할 수 있다'(임의적)라서 '하여야 한다'로 쓰면 틀린다."}},{"i":"S4-2-1-중개사법-15","r":"S4","g":2,"c":2,"n":15,"s":"중개사법","q":"공인중개사법령상 개업공인중개사가 거래계약서를 작성하는 경우에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 중개가 완성된 때 거래계약서를 작성하여 거래당사자에게 교부하고 5년 동안 보존하여야 한다(공인전자문서센터에 보관된 경우는 제외한다).","중개대상물 확인·설명서 교부일자는 거래계약서에 기재하여야 한다.","해당 중개행위를 한 소속공인중개사가 있는 경우 개업공인중개사와 소속공인중개사가 함께 거래계약서에 서명 및 날인하여야 한다.","개업공인중개사는 중개대상물 확인·설명서를 거래계약서와 마찬가지로 5년 동안 보존하여야 한다(공인전자문서센터에 보관된 경우는 제외한다).","개업공인중개사가 하나의 거래에 대하여 서로 다른 둘 이상의 거래계약서를 작성한 경우 등록관청은 중개사무소의 개설등록을 취소할 수 있다."],"a":[4],"L":"중1-8","o":"변형","x":{"한줄":"거래계약서 보존기간은 5년이지만 중개대상물 확인·설명서 보존기간은 3년이므로 4번이 틀렸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제22조제2항","원문":"법 제26조제1항에서 \"대통령령이 정하는 기간\"이라 함은 5년을 말한다."},{"법령":"공인중개사법 시행령","조문":"제21조제4항","원문":"법 제25조제3항 본문에서 \"대통령령이 정하는 기간\"이란 3년을 말한다."},{"법령":"공인중개사법 시행령","조문":"제22조제1항제8호","원문":"중개대상물확인ㆍ설명서 교부일자"},{"법령":"공인중개사법","조문":"제26조제2항","원문":"제25조제4항의 규정은 제1항에 따른 거래계약서의 작성에 관하여 이를 준용한다."},{"법령":"공인중개사법","조문":"제38조제2항제7호","원문":"제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제26조제1항, 영 제22조제2항."},{"번호":2,"판정":"옳음","설명":"영 제22조제1항제8호."},{"번호":3,"판정":"옳음","설명":"법 제26조제2항이 제25조제4항을 준용한다."},{"번호":4,"판정":"틀림","설명":"확인·설명서는 3년이다(영 제21조제4항)."},{"번호":5,"판정":"옳음","설명":"임의적 등록취소 사유다(법 제38조제2항제7호)."}],"개념":[{"종류":"표","제목":"거래계약서 필수 기재사항(영 제22조제1항)","머리":["호","기재사항"],"행":[["1","거래당사자의 인적 사항"],["2","물건의 표시"],["3","계약일"],["4","거래금액·계약금액 및 그 지급일자 등 지급에 관한 사항"],["5","물건의 인도일시"],["6","권리이전의 내용"],["7","계약의 조건이나 기한이 있는 경우 그 조건 또는 기한"],["8","중개대상물확인·설명서 교부일자"],["9","그 밖의 약정내용"]]},{"종류":"비교","제목":"확인·설명서와 거래계약서","왼쪽":{"이름":"중개대상물 확인·설명서","항목":["중개가 완성되기 전 확인·설명, 거래계약서 작성 시 서면 교부(법 제25조)","보존 3년(영 제21조제4항)","개업공인중개사(법인은 대표자, 분사무소는 책임자)와 중개행위를 한 소속공인중개사가 서명 및 날인","미교부·미보존: 업무정지 3개월(법 제39조제1항제6호)"]},"오른쪽":{"이름":"거래계약서","항목":["중개가 완성된 때 작성·교부(법 제26조제1항)","보존 5년(영 제22조제2항)","같은 방식으로 서명 및 날인(법 제26조제2항)","미작성·미보존: 업무정지 3개월(법 제39조제1항제8호)","거짓 기재·이중 계약서: 등록취소 가능(법 제38조제2항제7호), 소속공인중개사 자격정지 6월(법 제36조제1항제6호)"]}}],"함정":"3년과 5년 중 어느 서류가 어느 기간인지 바꿔 놓는 유형이다. 거래계약서가 5년, 확인·설명서가 3년이다. 이중 계약서에는 '취소하여야 한다'가 아니라 '취소할 수 있다'가 맞다."}},{"i":"S4-2-1-중개사법-16","r":"S4","g":2,"c":2,"n":16,"s":"중개사법","q":"개업공인중개사 甲이 공인중개사법령에 따라 중개대상물을 확인·설명하는 경우에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 중개대상물에 관한 권리를 이전하려는 중개의뢰인에게 확인·설명사항을 성실·정확하게 설명하여야 한다.","매도의뢰인이 중개대상물의 상태에 관한 자료요구에 불응한 경우 甲은 그 사실을 매수의뢰인에게 설명하고 확인·설명서에 기재하여야 한다.","주택 임대차를 중개하는 경우 관리비 금액과 그 산출내역은 확인·설명사항에 포함된다.","확인·설명서에는 甲(법인인 경우 대표자)이 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있으면 그 소속공인중개사도 함께 서명 및 날인하여야 한다.","甲이 설명의 근거자료를 제시하지 아니한 경우 500만원 이하의 과태료 부과 대상이 된다."],"a":[1],"L":"중1-8","o":"변형","x":{"한줄":"확인·설명의 상대방은 권리를 이전하려는 쪽이 아니라 취득하려는 중개의뢰인이므로 1번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제25조제1항","원문":"개업공인중개사는 중개를 의뢰받은 경우에는 중개가 완성되기 전에 다음 각 호의 사항을 확인하여 이를 해당 중개대상물에 관한 권리를 취득하고자 하는 중개의뢰인에게 성실ㆍ정확하게 설명하고, 토지대장 등본 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등본 등 설명의 근거자료를 제시하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제21조제2항","원문":"개업공인중개사는 매도의뢰인ㆍ임대의뢰인 등이 법 제25조제2항의 규정에 따른 중개대상물의 상태에 관한 자료요구에 불응한 경우에는 그 사실을 매수의뢰인ㆍ임차의뢰인 등에게 설명하고, 제3항의 규정에 따른 중개대상물확인ㆍ설명서에 기재하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제21조제1항제3호의2","원문":"관리비 금액과 그 산출내역 [제3호의2는 주택 임대차 중개의 경우에만 적용한다]"},{"법령":"공인중개사법","조문":"제25조제4항","원문":"제3항에 따른 확인ㆍ설명서에는 개업공인중개사(법인인 경우에는 대표자를 말하며, 법인에 분사무소가 설치되어 있는 경우에는 분사무소의 책임자를 말한다)가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"공인중개사법","조문":"제51조제2항제1호의6","원문":"제25조제1항을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 자 [500만원 이하의 과태료]"}],"선지":[{"번호":1,"판정":"틀림","설명":"권리를 '취득하고자 하는' 중개의뢰인(매수·임차인)에게 설명한다(법 제25조제1항)."},{"번호":2,"판정":"옳음","설명":"영 제21조제2항."},{"번호":3,"판정":"옳음","설명":"영 제21조제1항제3호의2(주택 임대차 중개에만 적용)."},{"번호":4,"판정":"옳음","설명":"법 제25조제4항."},{"번호":5,"판정":"옳음","설명":"근거자료 미제시는 500만원 이하 과태료다(법 제51조제2항제1호의6)."}],"개념":[{"종류":"흐름","제목":"확인·설명 절차","단계":[{"이름":"중개 의뢰","설명":"개업공인중개사가 중개를 의뢰받음"},{"이름":"자료 요구","설명":"필요하면 매도·임대의뢰인에게 중개대상물 상태에 관한 자료 요구. 불응하면 그 사실을 상대방에게 설명하고 확인·설명서에 기재(법 제25조제2항, 영 제21조제2항)"},{"이름":"확인·설명","설명":"중개가 완성되기 전에 권리를 취득하려는 중개의뢰인에게 성실·정확하게 설명하고 근거자료(토지대장 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등) 제시"},{"이름":"확인·설명서 교부","설명":"거래계약서 작성 시 서면으로 작성해 거래당사자에게 교부, 서명 및 날인(법 제25조제3항·제4항)"},{"이름":"보존","설명":"3년(영 제21조제4항)"}]},{"종류":"표","제목":"위반 제재 비교","머리":["위반","개업공인중개사","소속공인중개사"],"행":[["확인·설명 불성실 또는 근거자료 미제시","500만원 이하 과태료(법 제51조제2항제1호의6)","자격정지 3월(법 제36조제1항제3호)"],["확인·설명서 미교부·미보존","업무정지 3개월(법 제39조제1항제6호)","-"],["확인·설명서 서명·날인 누락","업무정지 3개월(법 제39조제1항제7호)","자격정지 3월(법 제36조제1항제4호)"]]}],"함정":"누가 설명 상대방인지 묻는 선지다. 매도인·임대인은 자료 제공 의무의 상대일 뿐이고, 설명을 받는 쪽은 권리를 취득하는 매수인·임차인이다."}},{"i":"S4-2-1-중개사법-17","r":"S4","g":2,"c":2,"n":17,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 손해배상책임의 보장에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사는 2억원 이상을 보장하는 보증보험 또는 공제에 가입하거나 공탁을 하여야 하고, 분사무소를 두는 경우에도 추가로 설정할 금액은 없다.","개업공인중개사가 보증보험금으로 손해배상을 한 때에는 30일 이내에 보증보험에 다시 가입하여야 한다.","공탁한 공탁금은 개업공인중개사가 폐업한 날부터 1년이 지나면 회수할 수 있다.","개업공인중개사는 중개를 개시하기 전에 거래당사자에게 손해배상책임의 보장에 관한 사항을 설명하고 관계 증서의 사본을 교부하여야 한다.","개업공인중개사는 보증을 설정한 후 그 증명서류를 갖추어 등록관청에 신고하여야 하지만, 보증기관이 보증사실을 등록관청에 직접 통보한 경우에는 신고를 생략할 수 있다."],"a":[5],"L":"중1-9","o":"변형","x":{"한줄":"보증기관이 보증사실을 등록관청에 직접 통보하면 개업공인중개사의 신고를 생략할 수 있으므로 5번이 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"제24조제1항","원문":"개업공인중개사는 법 제30조제3항에 따라 다음 각 호의 구분에 따른 금액을 보장하는 보증보험 또는 공제에 가입하거나 공탁을 해야 한다. 1. 법인인 개업공인중개사 : 4억원 이상. 다만, 분사무소를 두는 경우에는 분사무소마다 2억원 이상을 추가로 설정해야 한다. 2. 법인이 아닌 개업공인중개사 : 2억원 이상"},{"법령":"공인중개사법 시행령","조문":"제24조제2항","원문":"개업공인중개사는 중개사무소 개설등록을 한 때에는 업무를 시작하기 전에 제1항의 규정에 따른 손해배상책임을 보장하기 위한 조치(…)를 한 후 그 증명서류를 갖추어 등록관청에 신고하여야 한다. 다만, 보증보험회사ㆍ공제사업자 또는 공탁기관(…)이 보증사실을 등록관청에 직접 통보한 경우에는 신고를 생략할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제26조제2항","원문":"개업공인중개사는 보증보험금ㆍ공제금 또는 공탁금으로 손해배상을 한 때에는 15일 이내에 보증보험 또는 공제에 다시 가입하거나 공탁금 중 부족하게 된 금액을 보전하여야 한다."},{"법령":"공인중개사법","조문":"제30조제4항","원문":"제3항에 따라 공탁한 공탁금은 개업공인중개사가 폐업 또는 사망한 날부터 3년 이내에는 이를 회수할 수 없다."},{"법령":"공인중개사법","조문":"제30조제5항 본문","원문":"개업공인중개사는 중개가 완성된 때에는 거래당사자에게 손해배상책임의 보장에 관한 다음 각 호의 사항을 설명하고 관계 증서의 사본을 교부하거나 관계 증서에 관한 전자문서를 제공하여야 한다. 1. 보장금액 2. 보증보험회사, 공제사업을 행하는 자, 공탁기관 및 그 소재지 3. 보장기간"}],"선지":[{"번호":1,"판정":"틀림","설명":"법인은 4억원 이상이고 분사무소마다 2억원 이상을 추가한다(영 제24조제1항제1호). 2억원은 법인이 아닌 개업공인중개사의 금액이다."},{"번호":2,"판정":"틀림","설명":"15일 이내다(영 제26조제2항)."},{"번호":3,"판정":"틀림","설명":"폐업 또는 사망한 날부터 3년 이내에는 회수할 수 없다(법 제30조제4항)."},{"번호":4,"판정":"틀림","설명":"설명 시점은 중개가 완성된 때다(법 제30조제5항)."},{"번호":5,"판정":"옳음","설명":"영 제24조제2항 단서."}],"개념":[{"종류":"표","제목":"손해배상책임 보장 수치 모음","머리":["항목","내용","근거"],"행":[["법인","4억원 이상, 분사무소마다 2억원 이상 추가","영 제24조제1항제1호"],["법인이 아닌 개업공인중개사","2억원 이상","영 제24조제1항제2호"],["다른 법률에 따라 중개업을 하는 자","2천만원 이상, 업무 개시 전 설정·신고","영 제24조제3항"],["설정 시기","개설등록을 한 때 업무를 시작하기 전","법 제30조제3항, 영 제24조제2항"],["재가입·보전","보증금 지급 후 15일 이내","영 제26조제2항"],["공탁금 회수","폐업 또는 사망일부터 3년 이내 불가","법 제30조제4항"],["설명·증서 교부","중개가 완성된 때(보장금액, 보증기관·소재지, 보장기간)","법 제30조제5항. 위반 시 100만원 이하 과태료(법 제51조제3항제5호)"],["업무개시 전 미설정","등록취소 가능","법 제38조제2항제8호"]]},{"종류":"흐름","제목":"보증 설정과 보험금 지급","단계":[{"이름":"보증 설정","설명":"개설등록 후 업무 시작 전에 보증보험·공제 가입 또는 공탁"},{"이름":"등록관청 신고","설명":"증명서류를 갖춰 신고(보증기관이 직접 통보하면 생략 가능)"},{"이름":"손해 발생","설명":"고의·과실로 거래당사자에게 재산상 손해를 발생시키거나 자기 사무소를 다른 사람의 중개행위 장소로 제공해 손해를 발생시킨 경우 배상책임(법 제30조제1항·제2항)"},{"이름":"지급 청구","설명":"손해배상합의서·화해조서·확정판결문 사본 등을 첨부해 보증기관에 청구(영 제26조제1항)"},{"이름":"재가입·보전","설명":"배상한 날부터 15일 이내"}]}],"함정":"숫자 선지가 몰려 있다. 4억/2억, 15일, 3년을 정확히 짝지어 둔다. 법 제30조제1항 책임은 고의·과실이 있어야 하지만, 제2항(사무소 제공) 책임은 사무소를 제공한 사실만으로 성립한다는 차이도 구분한다."}},{"i":"S4-2-1-중개사법-18","r":"S4","g":2,"c":2,"n":18,"s":"중개사법","q":"공인중개사법령상 중개보수의 한도와 계산 등에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임대차 중 보증금 외에 월 단위의 차임이 있는 경우에는 월 차임액에 100을 곱한 금액을 보증금에 합산한 금액을 거래금액으로 하되, 합산한 금액이 5천만원 미만이면 월 차임액에 70을 곱한 금액과 보증금을 합산한 금액을 거래금액으로 한다.","교환계약의 경우 중개보수는 교환대상 중개대상물 중 거래금액이 작은 중개대상물의 가액을 거래금액으로 하여 계산한다.","중개대상물의 소재지와 중개사무소의 소재지가 다른 경우 개업공인중개사는 중개사무소의 소재지를 관할하는 시·도의 조례에서 정한 기준에 따라 중개보수를 받아야 한다.","중개대상물인 건축물 중 주택의 면적이 2분의 1 이상인 경우에는 주택의 중개보수 규정을 적용한다.","중개보수의 지급시기는 개업공인중개사와 중개의뢰인 간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."],"a":[2],"L":"중1-10","o":"변형","x":{"한줄":"교환계약의 거래금액은 교환대상 중개대상물 중 거래금액이 '큰' 쪽의 가액이므로 2번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제5항","원문":"제1항 및 제4항의 경우 거래금액의 계산은 다음 각 호에 따른다. 1. 임대차 중 보증금 외에 차임이 있는 경우에는 월 단위의 차임액에 100을 곱한 금액을 보증금에 합산한 금액을 거래금액으로 한다. 다만, 본문의 규정에 따라 합산한 금액이 5천만원 미만인 경우에는 본문의 규정에 불구하고 월 단위의 차임액에 70을 곱한 금액과 보증금을 합산한 금액을 거래금액으로 한다. 2. 교환계약의 경우에는 교환대상 중개대상물 중 거래금액이 큰 중개대상물의 가액을 거래금액으로 한다. 3. 동일한 중개대상물에 대하여 동일 당사자간에 매매를 포함한 둘 이상의 거래가 동일 기회에 이루어지는 경우에는 매매계약에 관한 거래금액만을 적용한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제3항","원문":"제1항 및 제2항의 경우에 중개대상물의 소재지와 중개사무소의 소재지가 다른 경우에는 개업공인중개사는 중개사무소의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라 중개보수 및 실비를 받아야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제6항","원문":"중개대상물인 건축물 중 주택의 면적이 2분의 1이상인 경우에는 제1항의 규정을 적용하고, 주택의 면적이 2분의 1미만인 경우에는 제4항의 규정을 적용한다."},{"법령":"공인중개사법 시행령","조문":"제27조의2","원문":"법 제32조제3항에 따른 중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"칙 제20조제5항제1호."},{"번호":2,"판정":"틀림","설명":"큰 중개대상물의 가액이 기준이다(칙 제20조제5항제2호)."},{"번호":3,"판정":"옳음","설명":"칙 제20조제3항."},{"번호":4,"판정":"옳음","설명":"칙 제20조제6항."},{"번호":5,"판정":"옳음","설명":"영 제27조의2."}],"개념":[{"종류":"계산","제목":"주택 임대차 중개보수: 보증금 3천만원, 월 차임 50만원","단계":[{"설명":"거래금액 = 보증금 + 월 차임 × 100 (합산액이 5천만원 이상이면 이 식)","식":"3,000만원 + 50만원 × 100","값":"8,000만원"},{"설명":"합산액이 5천만원 미만이면 월 차임 × 70으로 다시 계산한다. 8,000만원은 5천만원 이상이므로 해당 없음","식":"8,000만원 ≥ 5,000만원","값":"거래금액 8,000만원"},{"설명":"별표 1 임대차 등: 5천만원 이상 1억원 미만의 상한요율은 1천분의 4, 한도액 30만원","식":"8,000만원 × 4/1,000","값":"32만원"},{"설명":"산출액 32만원이 한도액 30만원을 넘으므로 한도액이 상한","식":"min(32만원, 30만원)","값":"30만원(일방 상한)"}]},{"종류":"표","제목":"주택 중개보수 상한요율(칙 별표 1)","머리":["거래내용","거래금액","상한요율","한도액"],"행":[["매매·교환","5천만원 미만","1천분의 6","25만원"],["매매·교환","5천만원 이상 2억원 미만","1천분의 5","80만원"],["매매·교환","2억원 이상 9억원 미만","1천분의 4","-"],["매매·교환","9억원 이상 12억원 미만 / 12억원 이상 15억원 미만 / 15억원 이상","1천분의 5 / 6 / 7","-"],["임대차 등","5천만원 미만","1천분의 5","20만원"],["임대차 등","5천만원 이상 1억원 미만","1천분의 4","30만원"],["임대차 등","1억원 이상 6억원 미만 / 6억원 이상 12억원 미만 / 12억원 이상 15억원 미만 / 15억원 이상","1천분의 3 / 4 / 5 / 6","-"]]}],"함정":"월 차임 환산 배수는 기본 100, 합산액이 5천만원 미만일 때만 70이다. 70을 기본으로 외우면 큰 거래에서 틀린다. 교환은 '큰 쪽'이다.","개정":"주택 중개보수 한도는 시행규칙 별표 1(신설 2021.10.19)의 구간별 상한요율·한도액으로 정한다. 일방으로부터 받을 수 있는 금액은 시·도 조례의 요율한도 이내에서 협의로 정한다(칙 제20조제1항)."}},{"i":"S4-2-1-중개사법-19","r":"S4","g":2,"c":2,"n":19,"s":"중개사법","q":"공인중개사법령상 개업공인중개사등의 교육에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["소속공인중개사는 고용 신고일 전 1년 이내에 시·도지사 또는 등록관청이 실시하는 직무교육을 받아야 한다.","시·도지사는 연수교육을 실시하려는 경우 실무교육 또는 연수교육을 받은 후 2년이 되기 1개월 전까지 연수교육의 일시·장소·내용 등을 대상자에게 통지하여야 한다.","소속공인중개사로서 고용관계 종료 신고 후 1년 이내에 중개사무소 개설등록을 신청하려는 자는 실무교육을 받지 않아도 된다.","중개보조원의 직무교육 시간은 12시간 이상 16시간 이하이다.","정당한 사유 없이 연수교육을 받지 아니한 개업공인중개사는 업무정지 3개월의 처분을 받는다."],"a":[3],"L":"중1-11","o":"변형","x":{"한줄":"소속공인중개사로서 고용관계 종료 신고 후 1년 이내에 개설등록을 신청하는 자는 실무교육이 면제되므로 3번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제34조제1항제2호","원문":"소속공인중개사로서 고용관계 종료 신고 후 1년 이내에 중개사무소의 개설등록을 신청하려는 자 [실무교육 면제]"},{"법령":"공인중개사법","조문":"제34조제2항·제3항","원문":"② 소속공인중개사는 제15조제1항에 따른 고용 신고일 전 1년 이내에 시ㆍ도지사가 실시하는 실무교육을 받아야 한다. (…) ③ 중개보조원은 제15조제1항에 따른 고용 신고일 전 1년 이내에 시ㆍ도지사 또는 등록관청이 실시하는 직무교육을 받아야 한다. (…)"},{"법령":"공인중개사법 시행령","조문":"제28조제2항·제3항·제4항","원문":"② (…) 2. 교육시간: 3시간 이상 4시간 이하 ③ (…) 2. 교육시간: 12시간 이상 16시간 이하 ④ 시ㆍ도지사는 법 제34조제4항에 따른 연수교육을 실시하려는 경우 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 연수교육의 일시ㆍ장소ㆍ내용 등을 대상자에게 통지하여야 한다."},{"법령":"공인중개사법","조문":"제51조제2항제5호의2","원문":"제34조제4항에 따른 연수교육을 정당한 사유 없이 받지 아니한 자 [500만원 이하의 과태료]"}],"선지":[{"번호":1,"판정":"틀림","설명":"소속공인중개사는 실무교육 대상이다. 직무교육은 중개보조원이 받는다(법 제34조제2항·제3항)."},{"번호":2,"판정":"틀림","설명":"2개월 전까지 통지한다(영 제28조제4항)."},{"번호":3,"판정":"옳음","설명":"법 제34조제1항제2호."},{"번호":4,"판정":"틀림","설명":"직무교육은 3시간 이상 4시간 이하다. 12시간 이상 16시간 이하는 연수교육이다(영 제28조제2항·제3항)."},{"번호":5,"판정":"틀림","설명":"연수교육 불이행은 500만원 이하 과태료이고 시·도지사가 부과한다(법 제51조제2항제5호의2, 제5항제2호)."}],"개념":[{"종류":"표","제목":"교육 종류별 정리","머리":["교육","대상","시기","시간","근거"],"행":[["실무교육","개설등록 신청자(법인은 사원·임원, 분사무소 설치 시 책임자), 소속공인중개사","등록신청일(분사무소 설치는 신고일)·고용 신고일 전 1년 이내","영 제28조제1항: 45시간","법 제34조제1항·제2항"],["직무교육","중개보조원","고용 신고일 전 1년 이내","3시간 이상 4시간 이하","법 제34조제3항, 영 제28조제2항"],["연수교육","실무교육을 받은 개업공인중개사·소속공인중개사","실무교육 후 2년마다(2년 되기 2개월 전까지 통지)","12시간 이상 16시간 이하","법 제34조제4항, 영 제28조제3항·제4항"]]},{"종류":"표","제목":"실무·직무교육 면제 사유","머리":["대상","면제되는 경우","근거"],"행":[["개설등록 신청자","폐업신고 후 1년 이내 재신청","법 제34조제1항제1호"],["개설등록 신청자","소속공인중개사로서 고용관계 종료 신고 후 1년 이내 신청","법 제34조제1항제2호"],["소속공인중개사","고용관계 종료 신고 후 1년 이내 재고용 신고, 또는 폐업신고 후 1년 이내 소속공인중개사로 고용 신고","법 제34조제2항"],["중개보조원","고용관계 종료 신고 후 1년 이내 재고용 신고","법 제34조제3항"]]}],"함정":"소속공인중개사는 '실무교육', 중개보조원은 '직무교육'이다. 시간 숫자(45시간, 3~4시간, 12~16시간)를 교육 종류와 바꿔 붙인 선지가 많다. 연수교육을 안 받으면 업무정지가 아니라 과태료다.","개정":"영 제28조제1항 실무교육 시간은 현행 조문에 '45시간'으로 규정되어 있다(개정 표시 <2025.10.21>). 예전 기출에 나온 실무교육 시간 수치는 이 조문으로 다시 확인해야 한다."}},{"i":"S4-2-1-중개사법-20","r":"S4","g":2,"c":2,"n":20,"s":"중개사법","q":"공인중개사법령상 한국공인중개사협회(이하 '협회'라 함) 및 공제사업에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["협회는 총회의 의결내용을 10일 이내에 시ㆍ도지사에게 보고하여야 한다.","협회는 매 회계연도 종료 후 3개월 이내에 공제사업 운용실적을 일간신문에 공시하거나 협회의 인터넷 홈페이지에 게시해야 한다.","협회의 정관을 변경하려는 경우에는 시ㆍ도지사의 인가를 받아야 한다.","공제규정에는 책임준비금의 적립비율을 공제료 수입액의 100분의 5 이상으로 정한다.","협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 한다."],"a":[5],"L":"중1-12","o":"기출","x":{"한줄":"협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리해야 하므로 5번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제42조제4항","원문":"협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다."},{"법령":"공인중개사법 시행령","조문":"제32조제1항","원문":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다."},{"법령":"공인중개사법","조문":"제41조제2항","원문":"협회는 법인으로 하며, 정관을 제정하거나 변경하려는 경우에는 국토교통부장관의 인가를 받아야 한다. <개정 2026.2.27>"},{"법령":"공인중개사법 시행령","조문":"제34조제3호","원문":"책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."},{"법령":"공인중개사법 시행령","조문":"제35조","원문":"협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"총회 의결내용은 지체 없이 국토교통부장관에게 보고한다(법 제41조의2제3항, 영 제32조제1항)."},{"번호":2,"판정":"틀림","설명":"일간신문 또는 협회보에 공시하고 홈페이지에도 게시해야 한다. 어느 하나만 하면 되는 것이 아니다(영 제35조)."},{"번호":3,"판정":"틀림","설명":"정관 제정·변경은 국토교통부장관의 인가다(법 제41조제2항)."},{"번호":4,"판정":"틀림","설명":"공제료 수입액의 100분의 10 이상이다(영 제34조제3호)."},{"번호":5,"판정":"옳음","설명":"법 제42조제4항."}],"개념":[{"종류":"표","제목":"협회 관련 보고·인가·승인 주체","머리":["사항","내용","근거"],"행":[["정관 제정·변경","국토교통부장관 인가(총회 의결 사항)","법 제41조제2항, 제41조의2제3항"],["총회 의결내용","지체 없이 국토교통부장관에게 보고","법 제41조의2제3항, 영 제32조제1항"],["윤리규정","국토교통부장관 승인을 받아 제정","법 제41조의3제1항"],["공제규정 제정·변경","국토교통부장관 승인","법 제42조제2항"],["책임준비금 다른 용도 사용","국토교통부장관 승인","법 제42조제4항"],["시·도회·지회 설치","시·도회는 시·도지사에게, 지회는 등록관청에 신고","영 제32조제2항"]]},{"종류":"표","제목":"공제사업 수치","머리":["항목","내용","근거"],"행":[["회계","다른 회계와 구분해 별도 관리, 손해배상기금과 복지기금으로 구분","법 제42조제4항, 영 제34조제2호"],["책임준비금 적립비율","공제료 수입액의 100분의 10 이상","영 제34조제3호"],["운용실적 공시","회계연도 종료 후 3개월 이내, 일간신문 또는 협회보 공시 + 협회 홈페이지 게시","영 제35조. 위반 시 500만원 이하 과태료(법 제51조제2항제7호)"],["운영위원회","공제사업을 심의하고 업무집행을 감독, 위원 19명 이내","법 제42조의2"],["공제사업의 성격","비영리, 회원 간 상호부조","영 제31조제6호"]]}],"함정":"협회가 법정단체가 되면서 협회 관련 인가·보고 주체는 모두 국토교통부장관이다. 시·도지사로 바꿔 놓은 선지(1, 3)를 먼저 걸러낸다. 영 제35조는 '또는 협회보에 공시하고 홈페이지에 게시'로, 두 방식을 모두 해야 한다.","개정":"법 제41조가 2026.2.27 개정되어 협회는 법률로 설립되고(설립인가·창립총회 제도 삭제, 제41조제3항 삭제), 정관 제정·변경만 국토교통부장관의 인가를 받는다. 명칭도 '한국공인중개사협회'로 쓴다. 이에 따라 구 선지(창립총회 개최 인원)를 정관 변경 인가 주체를 묻는 선지로 바꿨고 정답은 5번 그대로다."}},{"i":"S4-2-1-중개사법-21","r":"S4","g":2,"c":2,"n":21,"s":"중개사법","q":"공인중개사법령상 공인중개사의 자격취소에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["자격취소처분을 받은 자는 처분을 받은 날부터 14일 이내에 자격증을 교부한 시·도지사에게 자격증을 반납해야 한다.","시·도지사는 공인중개사의 자격취소처분을 한 때에는 10일 이내에 국토교통부장관과 다른 시·도지사에게 통보해야 한다.","공인중개사의 직무와 관련하여 「형법」 제347조(사기)를 위반하여 벌금형을 선고받은 경우 자격취소사유에 해당한다.","자격증을 교부한 시·도지사와 공인중개사 사무소의 소재지를 관할하는 시·도지사가 다른 경우, 사무소 소재지 관할 시·도지사가 자격취소처분에 필요한 절차를 모두 이행한 후 자격증을 교부한 시·도지사에게 통보해야 한다.","분실 등의 사유로 자격증을 반납할 수 없는 자는 반납의무가 면제되므로 사유서를 제출하지 않아도 된다."],"a":[4],"L":"중1-13","o":"변형","x":{"한줄":"자격취소처분의 절차는 사무소 소재지 관할 시·도지사가 모두 이행하고, 그 뒤 자격증을 교부한 시·도지사에게 통보한다.","근거":[{"법령":"공인중개사법 시행령","조문":"제29조","원문":"①법 제35조의 규정에 따른 공인중개사의 자격취소처분 및 법 제36조의 규정에 따른 자격정지처분은 그 공인중개사자격증(이하 \"자격증\"이라 한다)을 교부한 시ㆍ도지사가 행한다.\n②자격증을 교부한 시ㆍ도지사와 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 서로 다른 경우에는 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 자격취소처분 또는 자격정지처분에 필요한 절차를 모두 이행한 후 자격증을 교부한 시ㆍ도지사에게 통보하여야 한다.\n③시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제21조","원문":"법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법","조문":"제35조","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n④분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"반납기한은 자격취소처분을 받은 날부터 7일 이내이다(시행규칙 제21조). 14일이 아니다."},{"번호":2,"판정":"틀림","설명":"통보기한은 5일 이내이다(시행령 제29조제3항). 통보 상대방이 국토교통부장관과 다른 시·도지사인 점은 맞다."},{"번호":3,"판정":"틀림","설명":"형법 제347조 위반으로 자격이 취소되려면 금고 이상의 형(집행유예 포함)을 선고받아야 한다. 벌금형은 해당하지 않는다(법 제35조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"소재지 관할 시·도지사가 처분에 필요한 절차를 모두 이행한 뒤 교부한 시·도지사에게 통보한다(시행령 제29조제2항). 처분 자체는 교부한 시·도지사가 한다(같은 조 제1항)."},{"번호":5,"판정":"틀림","설명":"자격증을 반납할 수 없는 자는 반납을 대신하여 그 이유를 적은 사유서를 시·도지사에게 제출해야 한다(법 제35조제4항). 사유서를 내지 않으면 100만원 이하 과태료 대상이다(법 제51조제3항제6호)."}],"개념":[{"종류":"표","제목":"자격취소 사유와 후속 절차","머리":["구분","내용","근거"],"행":[["사유 1","부정한 방법으로 자격 취득","법 제35조제1항제1호"],["사유 2","다른 사람에게 자기 성명을 사용하여 중개업무를 하게 하거나 자격증을 양도·대여","같은 항 제2호"],["사유 3","자격정지 기간 중 중개업무(다른 개업공인중개사의 소속공인중개사·중개보조원, 법인의 사원·임원이 되는 경우 포함)","같은 항 제3호"],["사유 4","직무 관련 형법 제114조·제231조·제234조·제347조·제355조·제356조 위반으로 금고 이상 형(집행유예 포함) 선고","같은 항 제4호"],["청문","자격취소 전 청문 실시","법 제35조제2항"],["처분권자","자격증을 교부한 시·도지사","시행령 제29조제1항"]]},{"종류":"흐름","제목":"자격취소 후 절차","단계":[{"이름":"취소처분","설명":"자격증 교부 시·도지사가 처분. 사무소 소재지가 다르면 소재지 관할 시·도지사가 절차를 모두 이행하고 교부 시·도지사에게 통보"},{"이름":"자격증 반납","설명":"처분을 받은 날부터 7일 이내에 교부 시·도지사에게 반납. 분실 등은 사유서 제출"},{"이름":"통보","설명":"취소처분 후 5일 이내 국토교통부장관과 다른 시·도지사에게 통보"},{"이름":"결격 기간","설명":"취소 후 3년이 지나지 않으면 중개사무소 개설등록 불가(법 제10조제1항제6호)"}]}],"함정":"자격취소의 기한 숫자(반납 7일, 통보 5일)를 서로 바꾸거나 늘려 놓은 선지가 1·2번이다. 4번 대신 \"교부한 시·도지사가 절차를 이행한다\"는 문장을 옳다고 보기 쉬운데, 절차는 소재지 관할 시·도지사가 이행하고 교부한 시·도지사에게는 통보만 한다.","개정":"자격취소 통보 문언이 보고에서 통보로 바뀌었고 기한은 5일이다(시행령 제29조제3항 <개정 2023.11.16>)."}},{"i":"S4-2-1-중개사법-22","r":"S4","g":2,"c":2,"n":22,"s":"중개사법","q":"공인중개사법령상 공인중개사인 개업공인중개사 甲의 폐업 및 재등록에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["甲이 2025. 3. 10. 1개월의 업무정지처분을 받은 후 2025. 6. 2. 폐업신고를 하였다가 2026. 1. 20. 다시 중개사무소 개설등록을 한 경우, 종전 업무정지처분의 효과는 甲에게 승계된다.","甲이 2025. 1. 8. 업무정지처분에 해당하는 행위를 하였으나 2025. 3. 5. 폐업신고를 하였다가 2026. 9. 1. 다시 개설등록을 한 경우, 종전의 위반행위에 대하여 업무정지처분을 할 수 있다.","甲이 2024. 2. 5. 등록취소처분에 해당하는 행위를 하였으나 2024. 3. 6. 폐업신고를 하였다가 2026. 8. 20. 다시 개설등록을 한 경우, 종전의 위반행위에 대하여 등록취소처분을 할 수 없다.","甲이 폐업신고 후 다시 중개사무소 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계하지 않고 새로 등록한 개업공인중개사로 본다.","등록관청이 재등록한 甲에게 폐업신고 전의 위반행위로 행정처분을 하는 경우에는 폐업기간과 폐업의 사유를 고려하지 않아도 된다."],"a":[1],"L":"중1-13","o":"변형","x":{"한줄":"업무정지처분의 효과는 처분일부터 1년간 재등록 개업공인중개사에게 승계되며, 2025. 3. 10.부터 1년은 2026. 3. 10.이라 2026. 1. 20. 재등록은 그 안에 든다.","근거":[{"법령":"공인중개사법","조문":"제40조","원문":"①개업공인중개사가 제21조에 따른 폐업신고후 제9조에 따라 다시 중개사무소의 개설등록을 한 때에는 폐업신고 전의 개업공인중개사의 지위를 승계한다.\n②제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다.\n③제1항의 경우 재등록 개업공인중개사에 대하여 폐업신고 전의 제38조제1항 각 호, 같은 조 제2항 각 호 및 제39조제1항 각 호의 위반행위에 대한 행정처분을 할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우는 제외한다.\n1. 폐업신고를 한 날부터 다시 중개사무소의 개설등록을 한 날까지의 기간(이하 제2호에서 \"폐업기간\"이라 한다)이 3년을 초과한 경우\n2. 폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우\n④제3항에 따라 행정처분을 하는 경우에는 폐업기간과 폐업의 사유 등을 고려하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"처분일(2025. 3. 10.)부터 1년간 효과가 승계되고 재등록일(2026. 1. 20.)은 그 기간 안이다(법 제40조제2항)."},{"번호":2,"판정":"틀림","설명":"폐업기간이 2025. 3. 5.~2026. 9. 1.로 1년을 넘는다. 업무정지에 해당하는 위반행위는 폐업기간이 1년을 초과하면 처분할 수 없다(법 제40조제3항제2호)."},{"번호":3,"판정":"틀림","설명":"폐업기간이 2024. 3. 6.~2026. 8. 20.로 3년 이내이다. 폐업기간이 3년을 초과해야 처분할 수 없으므로 등록취소처분을 할 수 있다(법 제40조제3항 본문, 제1호)."},{"번호":4,"판정":"틀림","설명":"재등록한 개업공인중개사는 폐업신고 전 개업공인중개사의 지위를 승계한다(법 제40조제1항)."},{"번호":5,"판정":"틀림","설명":"처분할 때는 폐업기간과 폐업의 사유 등을 고려해야 한다(법 제40조제4항)."}],"개념":[{"종류":"표","제목":"폐업 후 재등록 때의 승계와 처분","머리":["구분","내용","근거"],"행":[["지위 승계","재등록하면 폐업신고 전 개업공인중개사의 지위 승계","법 제40조제1항"],["처분효과 승계","업무정지·과태료 처분의 효과가 처분일부터 1년간 승계","같은 조 제2항"],["위반행위 처분 가능","재등록 개업공인중개사에게 폐업 전 위반행위로 등록취소·업무정지 처분 가능","같은 조 제3항"],["처분 불가 1","폐업기간 3년 초과","같은 항 제1호"],["처분 불가 2","업무정지에 해당하는 위반행위로 폐업기간 1년 초과","같은 항 제2호"],["고려사항","처분 때 폐업기간과 폐업 사유 고려","같은 조 제4항"],["법인 대표자","법인의 대표자에도 준용","같은 조 제5항"],["처분 시효","업무정지는 사유 발생일부터 3년이 지나면 불가","법 제39조제3항"]]},{"종류":"비교","제목":"처분효과 승계와 위반행위 처분","왼쪽":{"이름":"처분효과의 승계(제40조제2항)","항목":["이미 받은 처분이 대상","처분일부터 1년간","업무정지·과태료 처분 등"]},"오른쪽":{"이름":"위반행위 처분(제40조제3항)","항목":["아직 처분받지 않은 위반행위가 대상","폐업기간 3년 초과이면 불가, 업무정지 해당이면 1년 초과 시 불가","등록취소·업무정지 처분 가능"]}}],"함정":"폐업기간은 날짜를 직접 계산한다. 등록취소에 해당하는 행위는 폐업기간 3년까지, 업무정지에 해당하는 행위는 1년까지 처분할 수 있다. 두 기간을 바꿔 적용하면 2·3번에서 걸린다."}},{"i":"S4-2-1-중개사법-23","r":"S4","g":2,"c":2,"n":23,"s":"중개사법","q":"공인중개사법령상 중개사무소 개설등록의 절대적 취소사유가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["개인인 개업공인중개사가 사망한 경우","개업공인중개사가 업무정지기간 중에 중개업무를 한 경우","개업공인중개사가 다른 사람에게 자기의 상호를 사용하여 중개업무를 하게 한 경우","개업공인중개사가 최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우","개업공인중개사가 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"],"a":[5],"L":"중1-13","o":"변형","x":{"한줄":"거래계약서의 거짓 기재와 이중 계약서 작성은 등록관청이 취소할 수 있는 임의적 취소사유이다.","근거":[{"법령":"공인중개사법","조문":"제38조","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다.\n1. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우\n6. 제19조제1항의 규정을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 양도 또는 대여한 경우\n7. 업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우\n8. 최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우\n②등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소할 수 있다.\n7. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"개인인 개업공인중개사의 사망은 필요적 등록취소 사유이다(법 제38조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"업무정지기간 중 중개업무는 필요적 등록취소 사유이다(법 제38조제1항제7호)."},{"번호":3,"판정":"옳음","설명":"다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하면 필요적 등록취소이다(법 제38조제1항제6호)."},{"번호":4,"판정":"옳음","설명":"최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지에 해당하는 행위를 하면 필요적 등록취소이다(법 제38조제1항제8호)."},{"번호":5,"판정":"틀림","설명":"임의적 등록취소 사유이다(법 제38조제2항제7호). 업무정지 사유이기도 하다(법 제39조제1항제11호)."}],"개념":[{"종류":"표","제목":"필요적(절대적) 등록취소 사유 - 법 제38조제1항","머리":["호","사유"],"행":[["1","개인인 개업공인중개사의 사망, 법인인 개업공인중개사의 해산"],["2","거짓이나 그 밖의 부정한 방법으로 개설등록"],["3","결격사유(제10조제1항 제2~6호, 제11·12호) 해당. 제12호 사유는 2개월 이내 해소하면 제외"],["4","이중등록"],["5","다른 개업공인중개사의 소속공인중개사·중개보조원, 법인의 사원·임원이 된 경우"],["5의2","제15조제3항을 위반하여 중개보조원을 고용"],["6","성명·상호를 사용하게 하거나 등록증 양도·대여"],["7","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 함"],["8","최근 1년 이내 2회 이상 업무정지 후 다시 업무정지 해당 행위"]]},{"종류":"표","제목":"임의적 등록취소 사유 - 법 제38조제2항","머리":["호","사유"],"행":[["1","등록기준 미달"],["2","둘 이상의 중개사무소"],["3","임시 중개시설물 설치"],["4","겸업 제한 위반"],["5","계속 6개월 초과 휴업"],["6","정보 비공개 위반(공개 안 함 또는 비공개 요청에도 공개)"],["7","거래계약서 거짓 기재·이중 계약서"],["8","손해배상책임 보장 조치 없이 업무 개시"],["9","금지행위(제33조제1항)"],["10","최근 1년 이내 3회 이상 업무정지·과태료 후 다시 해당 행위"],["11","사업자단체 공정거래법 처분 2년 이내 2회 이상"]]}],"함정":"필요적 사유와 임의적 사유를 섞으면 5번 같은 문장에서 걸린다. 거래계약서 위반, 이중 사무소, 임시 시설물, 겸업, 금지행위는 임의적 사유이다. 이중등록(제12조제1항)과 이중 사무소(제13조제1항)는 이름이 비슷하지만 앞은 필요적, 뒤는 임의적이다."}},{"i":"S4-2-1-중개사법-24","r":"S4","g":2,"c":2,"n":24,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 행위 중 과태료 부과대상이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["중개대상물의 거래상의 중요사항에 관해 거짓된 언행으로 중개의뢰인의 판단을 그르치게 한 경우","휴업신고에 따라 휴업한 중개업을 재개하면서 등록관청에 그 사실을 신고하지 않은 경우","중개대상물에 관한 권리를 취득하려는 중개의뢰인에게 해당 중개대상물의 권리관계를 성실ㆍ정확하게 확인ㆍ설명하지 않은 경우","인터넷을 이용하여 중개대상물에 대한 표시ㆍ광고를 하면서 중개대상물의 종류별로 가격 및 거래형태를 명시하지 않은 경우","연수교육을 정당한 사유 없이 받지 않은 경우"],"a":[1],"L":"중1-14","o":"기출","x":{"한줄":"거래상 중요사항에 관한 거짓된 언행은 금지행위로, 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.","근거":[{"법령":"공인중개사법","조문":"제49조","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제33조","원문":"① 개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다.\n4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위"},{"법령":"공인중개사법","조문":"제51조","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n1의6. 제25조제1항을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 자\n5의2. 제34조제4항에 따른 연수교육을 정당한 사유 없이 받지 아니한 자"},{"법령":"공인중개사법","조문":"제51조","원문":"③ 다음 각 호의 어느 하나에 해당하는 자에게는 100만원 이하의 과태료를 부과한다.\n2의2. 제18조의2제1항 또는 제2항을 위반하여 중개대상물의 중개에 관한 표시ㆍ광고를 한 자\n4. 제21조제1항을 위반하여 휴업, 폐업, 휴업한 중개업의 재개 또는 휴업기간의 변경 신고를 하지 아니한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"과태료가 아니라 형사처벌 대상이다. 제33조제1항제4호 위반은 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제10호)."},{"번호":2,"판정":"옳음","설명":"휴업한 중개업의 재개 신고를 하지 않으면 100만원 이하 과태료이다(법 제51조제3항제4호)."},{"번호":3,"판정":"옳음","설명":"확인ㆍ설명을 성실ㆍ정확하게 하지 않으면 500만원 이하 과태료이다(법 제51조제2항제1호의6)."},{"번호":4,"판정":"옳음","설명":"인터넷 표시ㆍ광고에서 종류별 명시사항을 빠뜨리면(법 제18조의2제2항 위반) 100만원 이하 과태료이다(법 제51조제3항제2호의2)."},{"번호":5,"판정":"옳음","설명":"연수교육을 정당한 사유 없이 받지 않으면 500만원 이하 과태료이며 시ㆍ도지사가 부과한다(법 제51조제2항제5호의2, 제5항제2호)."}],"개념":[{"종류":"표","제목":"과태료 금액과 부과권자","머리":["금액","대표 사유","부과권자"],"행":[["500만원 이하","확인ㆍ설명 불성실·근거자료 미제시, 부당한 표시ㆍ광고, 중개보조원 신분 미고지","등록관청"],["500만원 이하","연수교육 미이수","시ㆍ도지사"],["500만원 이하","거래정보사업자의 보고·검사 거부, 공제사업 관련 보고·공시·개선명령 위반","국토교통부장관"],["100만원 이하","등록증 미게시, 명칭ㆍ옥외광고물 위반, 표시ㆍ광고 명시사항 위반(제18조의2제1·2항), 이전ㆍ휴업ㆍ폐업ㆍ재개 미신고, 손해배상 설명 및 증서 미교부, 등록증 미반납","등록관청"],["100만원 이하","자격증 미반납, 반납 불가 사유서 미제출·거짓 제출","시ㆍ도지사"]]},{"종류":"표","제목":"금지행위 위반의 처벌","머리":["조문","내용","처벌"],"행":[["제33조제1항제1~4호","중개대상물 매매업, 무등록업자와 거래, 초과 보수, 거짓된 언행","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조)"],["제33조제1항제5~9호","증서 등 매매, 직접거래·쌍방대리, 투기조장, 시세 교란, 단체 구성 제한","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["제33조제2항","시세 부당 영향 목적의 업무방해","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제4호)"]]}],"함정":"금지행위를 모두 3년 이하로 외우다 보면 처벌 수위를 헷갈린다. 거짓된 언행은 과태료도 3년 이하도 아니고 1년 이하 징역이다. 표시ㆍ광고 위반은 제18조의2제1·2항이 100만원, 제4항 부당 표시ㆍ광고가 500만원이다."}},{"i":"S4-2-1-중개사법-25","r":"S4","g":2,"c":2,"n":25,"s":"중개사법","q":"공인중개사법령상 다음의 행위를 한 자에 대하여 3년의 징역에 처할 수 있는 경우는?","b":null,"bs":"없음","img":[],"ch":["거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우","공인중개사가 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 한 경우","등록관청의 관할 구역안에 2개의 중개사무소를 둔 경우","개업공인중개사가 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치한 경우","공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 경우"],"a":[1],"L":"중1-14","o":"기출","x":{"한줄":"거짓이나 그 밖의 부정한 방법으로 개설등록을 한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","근거":[{"법령":"공인중개사법","조문":"제48조","원문":"다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자"},{"법령":"공인중개사법","조문":"제49조","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"제48조제2호에 따라 3년 이하의 징역 또는 3천만원 이하의 벌금이다."},{"번호":2,"판정":"틀림","설명":"자기 성명으로 중개업무를 하게 하는 행위(제7조제1항 위반)는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"둘 이상의 중개사무소를 두면 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제4호)."},{"번호":4,"판정":"틀림","설명":"임시 중개시설물 설치는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제5호)."},{"번호":5,"판정":"틀림","설명":"공인중개사 유사명칭 사용(제8조 위반)은 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제2호)."}],"개념":[{"종류":"표","제목":"3년 이하 징역·3천만원 이하 벌금 - 법 제48조","머리":["호","사유"],"행":[["1","무등록 중개업"],["2","거짓이나 그 밖의 부정한 방법으로 개설등록"],["3","금지행위 제33조제1항 제5~9호 위반"],["4","시세 부당 영향 목적의 업무방해(제33조제2항)"]]},{"종류":"표","제목":"1년 이하 징역·1천만원 이하 벌금 - 법 제49조제1항(주요 사유)","머리":["호","사유"],"행":[["1","자격증 양도·대여, 성명 사용하게 함, 양수·대여받음"],["2","공인중개사 유사명칭 사용"],["3","이중등록, 둘 이상의 중개사무소 소속"],["4","둘 이상의 중개사무소"],["5","임시 중개시설물"],["5의2","중개보조원 고용 한도 초과"],["7","등록증 대여·양도, 타인 성명·상호 사용"],["8","부동산거래정보망 정보 공개 위반(제24조제4항)"],["9","업무상 비밀 누설(피해자 명시 의사에 반하여 벌하지 않음)"],["10","금지행위 제33조제1항 제1~4호"]]}],"함정":"이중등록·이중 사무소·임시 시설물·명칭 사용은 등록취소 사유라서 무거워 보이지만 형사처벌은 1년 이하이다. 3년 이하는 무등록 중개업, 부정 등록, 금지행위 5~9호로 외운다."}},{"i":"S4-2-1-중개사법-26","r":"S4","g":2,"c":2,"n":26,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산 거래신고에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 거래계약서를 작성ㆍ교부한 경우에도 거래당사자가 계약체결일부터 30일 이내에 공동으로 신고해야 한다.","개업공인중개사의 위임을 받은 소속공인중개사 또는 중개보조원은 부동산거래계약 신고서 등의 제출을 대행할 수 있다.","지방공단과 개인이 토지 매매계약을 체결한 경우 지방공단이 단독으로 신고해야 한다.","거래당사자 중 일방이 신고를 거부하여 단독으로 신고하는 경우에는 부동산 거래계약서 사본과 단독신고사유서만 첨부하면 되고, 계약금의 지급을 확인할 수 있는 서류는 첨부하지 않아도 된다.","부동산 거래계약 신고 후 계약이 해제된 경우 거래당사자는 해제등이 확정된 날부터 60일 이내에 공동으로 해제등 신고를 해야 한다."],"a":[3],"L":"중2-1","o":"변형","x":{"한줄":"거래당사자 중 일방이 지방공사·지방공단 등 국가등에 해당하면 국가등이 단독으로 신고한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다.\n② 제1항에도 불구하고 거래당사자 중 일방이 신고를 거부하는 경우에는 국토교통부령으로 정하는 바에 따라 단독으로 신고할 수 있다.\n③ 「공인중개사법」 제2조제4호에 따른 개업공인중개사(이하 \"개업공인중개사\"라 한다)가 같은 법 제26조제1항에 따라 거래계약서를 작성ㆍ교부한 경우에는 제1항에도 불구하고 해당 개업공인중개사가 같은 항에 따른 신고를 하여야 한다. 이 경우 공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제2조","원문":"③ 법 제3조제2항 또는 제4항에 따라 단독으로 부동산 거래계약을 신고하려는 자는 부동산거래계약 신고서에 단독으로 서명 또는 날인한 후 다음 각 호의 서류를 첨부하여 신고관청에 제출해야 한다. 이 경우 신고관청은 단독신고 사유에 해당하는지 여부를 확인해야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제5조","원문":"② 제2조제4항, 제3조제2항ㆍ제4항 및 제4조제1항ㆍ제2항의 개업공인중개사의 위임을 받은 소속공인중개사(「공인중개사법」 제2조제5호에 따른 소속공인중개사를 말한다. 이하 같다)는 부동산거래계약 신고서 등의 제출을 대행할 수 있다. 이 경우 소속공인중개사는 신분증명서를 신고관청에 보여줘야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조의2","원문":"① 거래당사자는 제3조에 따라 신고한 후 해당 거래계약이 해제, 무효 또는 취소(이하 \"해제등\"이라 한다)된 경우 해제등이 확정된 날부터 30일 이내에 해당 신고관청에 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 신고를 거부하는 경우에는 국토교통부령으로 정하는 바에 따라 단독으로 신고할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개업공인중개사가 거래계약서를 작성ㆍ교부한 경우에는 해당 개업공인중개사가 신고한다(법 제3조제3항). 거래당사자가 공동으로 신고하는 것은 직접 거래일 때이다."},{"번호":2,"판정":"틀림","설명":"신고서 제출을 대행할 수 있는 사람은 개업공인중개사의 위임을 받은 소속공인중개사이다. 중개보조원은 해당하지 않는다(시행규칙 제5조제2항)."},{"번호":3,"판정":"옳음","설명":"「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단은 국가등에 해당하고(시행령 제3조제2항제2호), 거래당사자 중 일방이 국가등이면 국가등이 신고한다(법 제3조제1항 단서)."},{"번호":4,"판정":"틀림","설명":"단독신고에는 거래계약서 사본, 계약금의 지급을 확인할 수 있는 영수증 사본 또는 통장 사본 등, 단독신고사유서를 모두 첨부한다(시행규칙 제2조제3항)."},{"번호":5,"판정":"틀림","설명":"해제등 신고기한은 해제등이 확정된 날부터 30일 이내이다(법 제3조의2제1항)."}],"개념":[{"종류":"표","제목":"거래신고의 주체와 기한","머리":["구분","신고 주체","기한·근거"],"행":[["직접거래","거래당사자 공동","계약체결일부터 30일 이내(법 제3조제1항)"],["중개거래","계약서를 작성·교부한 개업공인중개사(공동중개면 공동)","같은 조 제3항"],["일방이 국가등","국가등이 단독","같은 조 제1항 단서. 국가·지방자치단체·공공기관·지방직영기업·지방공사·지방공단"],["일방이 신고 거부","다른 일방 단독(계약서 사본·계약금 지급 확인서류·단독신고사유서 첨부)","같은 조 제2항·제4항, 시행규칙 제2조제3항"],["해제등 신고","거래당사자 공동(중개거래는 개업공인중개사도 가능)","해제등 확정일부터 30일 이내(법 제3조의2)"],["제출 대행","거래당사자의 위임을 받은 사람 / 개업공인중개사의 위임을 받은 소속공인중개사","시행규칙 제5조"]]},{"종류":"흐름","제목":"거래신고 절차","단계":[{"이름":"계약 체결","설명":"부동산 매매, 공급계약, 공급계약으로 선정된 지위 및 정비사업 입주자 지위의 매매"},{"이름":"신고서 제출","설명":"계약체결일부터 30일 이내 부동산 소재지 관할 신고관청에 제출"},{"이름":"신고필증 발급","설명":"신고 내용을 확인한 후 지체 없이 발급. 매수인은 검인을 받은 것으로 봄(법 제3조제5항·제6항)"},{"이름":"검증·통보","설명":"신고관청이 검증체계로 적정성 검증, 결과를 관할 세무관서의 장에게 통보(법 제5조)"}]}],"함정":"개업공인중개사가 계약서를 작성했는데 거래당사자가 신고한다고 보면 1번에 걸린다. 대행은 소속공인중개사까지만 가능하고 중개보조원은 안 된다. 해제등 신고기한도 신고기한과 같은 30일이다."}},{"i":"S4-2-1-중개사법-27","r":"S4","g":2,"c":2,"n":27,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산거래계약 신고서 작성방법으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["외국인이 부동산을 매수하는 경우 체류자격 및 국내에 주소를 두거나 183일 이상 거소를 두고 있는지 여부를 표시한다.","개업공인중개사가 거래계약서를 작성한 중개거래의 경우 거래당사자 중 일방이 신고서를 제출한다.","거래당사자가 다수인 경우 매도인과 매수인의 거래지분 비율은 일치해야 한다.","\"공급계약\"은 시행사 또는 건축주 등이 최초로 부동산을 공급(분양)하는 계약을 말한다.","분양권 전매계약의 총 실제 거래가격에는 부가가치세를 포함한 금액을 적고, 그 외 거래대상의 경우에는 부가가치세를 제외한 금액을 적는다."],"a":[2],"L":"중2-1","o":"변형","x":{"한줄":"중개거래에서는 개업공인중개사가 신고서를 제출하고, 거래당사자 중 일방이 제출하는 것은 직접거래의 경우이다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 유의사항 2","원문":"거래당사자 간 직접거래의 경우에는 공동으로 신고서에 서명 또는 날인을 하여 거래당사자 중 일방이 신고서를 제출하고, 중개거래의 경우에는 개업공인중개사가 신고서를 제출해야 하며, 거래당사자 중 일방이 국가 및 지자체, 공공기관인 경우(국가등)에는 국가등이 신고해야 합니다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 유의사항 5","원문":"거래대상의 종류가 공급계약(분양) 또는 전매계약(분양권, 입주권)인 경우 ⑧ 물건별 거래가격 및 ⑨ 총 실제거래가격에 부가가치세를 포함한 금액을 적고, 그 외의 거래대상의 경우 부가가치세를 제외한 금액을 적습니다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 1","원문":"거래당사자가 다수인 경우 매도인 또는 매수인의 주소란에 ⑥의 거래대상별 거래지분을 기준으로 각자의 거래 지분 비율(매도인과 매수인의 거래지분 비율은 일치해야 합니다)을 표시하고, 거래당사자가 외국인인 경우 거래당사자의 국적을 반드시 적어야 하며, 외국인이 부동산등을 매수하는 경우 체류자격 및 국내에 주소를 두거나 183일 이상 거소를 두고 있는지 여부를 표시하고,"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 4","원문":"공급계약은 시행사 또는 건축주 등이 최초로 부동산을 공급(분양)하는 계약을 말하며, 준공 전과 준공 후 계약 여부에 따라 √표시 하고,"}],"선지":[{"번호":1,"판정":"옳음","설명":"외국인이 매수하는 경우 체류자격과 국내 주소 또는 183일 이상 거소 여부를 표시한다(서식 작성방법 1, 영 별표 1 제1호 아목)."},{"번호":2,"판정":"틀림","설명":"중개거래의 경우 개업공인중개사가 신고서를 제출한다. 거래당사자 중 일방이 제출하는 것은 직접거래의 경우이다(서식 유의사항 2, 법 제3조제3항)."},{"번호":3,"판정":"옳음","설명":"거래당사자가 다수이면 거래지분 비율을 표시하며 매도인과 매수인의 비율은 일치해야 한다(서식 작성방법 1)."},{"번호":4,"판정":"옳음","설명":"공급계약은 최초로 부동산을 공급(분양)하는 계약이다(서식 작성방법 4). 이후 분양권·입주권의 매매는 전매이다."},{"번호":5,"판정":"옳음","설명":"공급계약·전매계약은 부가가치세를 포함하고 그 외 거래대상은 제외한다(서식 유의사항 5)."}],"개념":[{"종류":"표","제목":"신고서 제출 방법","머리":["거래 형태","제출자","서명·날인"],"행":[["직접거래","거래당사자 중 일방","거래당사자 공동"],["중개거래","개업공인중개사","개업공인중개사(공동중개면 공동으로)"],["국가등이 일방","국가등","국가등 단독"],["일방이 신고 거부","신고하려는 일방","단독(단독신고 서류 첨부)"],["부동산거래계약시스템 이용","체결 시 신고서 제출한 것으로 봄","시행규칙 제2조제14항"]]},{"종류":"표","제목":"신고서 작성방법 요점","머리":["항목","작성 방법"],"행":[["거래당사자 외국인","국적을 반드시 적음. 매수인이면 체류자격, 국내 주소 또는 183일 이상 거소 여부 표시"],["계약대상 면적","실제 거래면적. 집합건축물은 전용면적, 그 밖의 건축물은 연면적"],["소재지","지번(집합건축물은 동·호수)까지"],["거래가격 부가가치세","공급계약·전매계약은 포함, 그 외는 제외"],["법인신고서등란","법인 주택 거래계약 신고서, 자금조달·입주계획서 등을 함께 또는 별도로 제출하는지 표시. 그 밖에는 해당 없음에 표시"],["임대주택 분양전환","법인인 임대주택사업자가 임대기한 완료로 분양전환하는 주택"]]}],"함정":"직접거래와 중개거래의 제출자를 바꾼 문장이 가장 잦다. 직접거래는 공동 서명·날인 후 일방이 제출하고, 중개거래는 개업공인중개사가 제출한다. 부가가치세는 분양 계열만 포함이다.","개정":"현행 서식은 법인신고서등란을 두며, 예전 서식의 자금조달 및 입주계획란은 없다(시행규칙 별지 제1호서식 작성방법 2, 시행령 별표 1 제3호 <개정 2020.10.27>)."}},{"i":"S4-2-1-중개사법-28","r":"S4","g":2,"c":2,"n":28,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산 거래의 신고 내용에 대한 검증 및 조사에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["신고관청으로부터 신고 내용의 검증 결과를 통보받은 세무서장은 해당 신고 내용을 국세 또는 지방세 부과를 위한 과세자료로 활용할 수 있다.","신고관청은 신고내용조사를 위하여 「공인중개사법」에 따른 공인중개사의 자격취소, 자격정지, 등록취소 및 업무정지에 관한 자료를 관계 행정기관의 장에게 요청할 수 있다.","국토교통부장관은 신고 받은 내용의 확인을 위하여 필요한 때에는 신고내용조사를 직접 또는 신고관청과 공동으로 실시할 수 있다.","군수 또는 구청장이 신고 내용을 조사한 경우 그 조사 결과를 국토교통부장관에게 보고하여야 한다.","신고관청은 신고 내용을 조사하기 위하여 거래당사자 또는 개업공인중개사에게 거래대금의 지급을 확인할 수 있는 입금표 또는 통장사본의 제출을 요구할 수 있다."],"a":[4],"L":"중2-1","o":"기출","x":{"한줄":"신고관청은 조사 결과를 시·도지사에게 보고하고, 시·도지사가 국토교통부장관에게 보고한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제5조","원문":"③ 신고관청은 제2항에 따른 검증 결과를 해당 부동산의 소재지를 관할하는 세무관서의 장에게 통보하여야 하며, 통보받은 세무관서의 장은 해당 신고 내용을 국세 또는 지방세 부과를 위한 과세자료로 활용할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조","원문":"① 신고관청은 제3조, 제3조의2 또는 제8조에 따라 신고 받은 내용이 누락되어 있거나 정확하지 아니하다고 판단하는 경우에는 국토교통부령으로 정하는 바에 따라 신고인에게 신고 내용을 보완하게 하거나 신고한 내용의 사실 여부를 확인하기 위하여 소속 공무원으로 하여금 거래당사자 또는 개업공인중개사에게 거래계약서, 거래대금 지급을 증명할 수 있는 자료 등 관련 자료의 제출을 요구하는 등 필요한 조치를 취할 수 있다.\n② 제1항에 따라 신고 내용을 조사(이하 이 조에서 \"신고내용조사\"라 한다)한 경우 신고관청은 조사 결과를 특별시장, 광역시장, 특별자치시장, 도지사, 특별자치도지사(이하 \"시ㆍ도지사\"라 한다)에게 보고하여야 하며, 시ㆍ도지사는 이를 국토교통부령으로 정하는 바에 따라 국토교통부장관에게 보고하여야 한다.\n③ 제1항에도 불구하고 국토교통부장관은 제3조, 제3조의2 또는 제8조에 따라 신고 받은 내용의 확인을 위하여 필요한 때에는 신고내용조사를 직접 또는 신고관청과 공동으로 실시할 수 있다.\n④ 국토교통부장관 및 신고관청은 제1항 및 제3항에 따른 신고내용조사를 위하여 국세ㆍ지방세에 관한 자료, 소득ㆍ재산에 관한 자료 등 대통령령으로 정하는 자료를 관계 행정기관의 장에게 요청할 수 있다. 이 경우 요청을 받은 관계 행정기관의 장은 정당한 사유가 없으면 그 요청에 따라야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제6조","원문":"① 국토교통부장관 또는 신고관청(이하 \"조사기관\"이라 한다)은 법 제6조제1항 또는 제3항에 따라 신고 내용을 조사하기 위하여 거래당사자 또는 개업공인중개사에게 다음 각 호의 자료를 제출하도록 요구할 수 있다.\n1. 거래계약서 사본\n2. 거래대금의 지급을 확인할 수 있는 입금표 또는 통장 사본"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 2 제5호","원문":"「공인중개사법」 제35조, 제36조, 제38조 및 제39조에 따른 공인중개사의 자격취소, 자격정지, 등록취소 및 업무정지에 관한 자료"}],"선지":[{"번호":1,"판정":"옳음","설명":"신고관청은 검증 결과를 관할 세무관서의 장에게 통보하고, 통보받은 세무관서의 장은 과세자료로 활용할 수 있다(법 제5조제3항)."},{"번호":2,"판정":"옳음","설명":"국세·지방세, 소득·재산 자료 등 대통령령으로 정하는 자료를 관계 행정기관의 장에게 요청할 수 있고(법 제6조제4항), 공인중개사법에 따른 자격취소·자격정지·등록취소·업무정지 자료가 포함된다(시행령 별표 2 제5호)."},{"번호":3,"판정":"옳음","설명":"국토교통부장관은 직접 또는 신고관청과 공동으로 신고내용조사를 할 수 있다(법 제6조제3항)."},{"번호":4,"판정":"틀림","설명":"신고관청은 조사 결과를 시·도지사에게 보고하고, 시·도지사가 국토교통부장관에게 보고한다(법 제6조제2항). 시·도지사가 월 1회 취합하여 보고한다(시행규칙 제6조제4항)."},{"번호":5,"판정":"옳음","설명":"거래계약서 사본, 입금표 또는 통장 사본 등의 제출을 요구할 수 있다(시행규칙 제6조제1항제1호·제2호)."}],"개념":[{"종류":"흐름","제목":"신고내용 검증·조사 체계","단계":[{"이름":"검증","설명":"신고관청이 국토교통부장관의 거래가격 검증체계로 신고가격의 적정성을 검증(법 제5조제2항)"},{"이름":"통보","설명":"검증 결과를 해당 부동산 소재지 관할 세무관서의 장에게 통보, 과세자료로 활용(같은 조 제3항)"},{"이름":"조사","설명":"누락·부정확 신고 시 보완 요구 또는 자료 제출 요구(법 제6조제1항). 국토교통부장관은 직접 또는 공동 조사 가능(같은 조 제3항)"},{"이름":"보고","설명":"신고관청 → 시·도지사 → 국토교통부장관(같은 조 제2항). 시·도지사는 월 1회 보고(시행규칙 제6조제4항)"},{"이름":"후속 조치","설명":"법 위반이 있으면 수사기관 고발 또는 관계 행정기관 통보(같은 조 제5항)"}]},{"종류":"표","제목":"자료제출 요구 대상(시행규칙 제6조제1항)","머리":["호","자료"],"행":[["1","거래계약서 사본"],["2","거래대금의 지급을 확인할 수 있는 입금표 또는 통장 사본"],["3","매수인이 대출, 정기예금 등 만기수령·해약, 주식·채권 등 처분을 하였음을 증명할 자료"],["4","매도인이 받은 거래대금을 예금 외의 용도로 지출한 경우 이를 증명할 자료"],["5","그 밖에 사실 확인에 필요한 자료"]]}],"함정":"보고 경로는 신고관청, 시·도지사, 국토교통부장관 순이다. 군수·구청장이 국토교통부장관에게 바로 보고한다는 문장이 틀린 선지이다. 자료제출 요구는 요구사유·자료범위·제출기한을 적은 서면으로 한다(시행규칙 제6조제2항)."}},{"i":"S4-2-1-중개사법-29","r":"S4","g":2,"c":2,"n":29,"s":"중개사법","q":"임대인 甲과 임차인 乙은 주택임대차보호법에 따른 X주택에 대해 보증금 1억원의 임대차 계약을 체결하였다. 부동산 거래신고 등에 관한 법령상 주택 임대차 계약의 신고에 관한 설명으로 옳은 것은? (단, 甲과 乙은 자연인임)","b":null,"bs":"없음","img":[],"ch":["X주택이 경상북도의 관할구역에 있는 군에 소재한 경우에는 주택 임대차 계약의 신고를 하여야 한다.","甲과 乙의 임대차 계약이 종전의 보증금을 그대로 유지하면서 임대차 기간만 연장하는 갱신계약인 경우에도 주택 임대차 계약의 신고를 하여야 한다.","甲이 주택 임대차 계약의 신고를 거부하여 乙이 단독으로 신고하는 경우 乙은 신분증명서를 신고관청에 보여줘야 한다.","甲과 乙이 공동으로 주택 임대차 계약의 신고를 한 후 해당 계약의 보증금이 8천만원으로 감액된 경우에는 변경신고를 하지 않아도 된다.","甲이 「부동산 거래신고 등에 관한 법률」에 따른 주택 임대차 계약의 신고를 한 경우 「주민등록법」에 따라 전입신고를 한 것으로 본다."],"a":[3],"L":"중2-2","o":"기출","x":{"한줄":"단독으로 주택 임대차 계약을 신고하려는 사람도 신분증명서를 신고관청에 보여줘야 한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제4조의3","원문":"① 법 제6조의2제1항 본문에서 \"대통령령으로 정하는 금액을 초과하는 임대차 계약\"이란 보증금이 6천만원을 초과하거나 월 차임이 30만원을 초과하는 주택 임대차 계약(계약을 갱신하는 경우로서 보증금 및 차임의 증감 없이 임대차 기간만 연장하는 계약은 제외한다)을 말한다.\n② 법 제6조의2제2항에서 \"대통령령으로 정하는 지역\"이란 특별자치시ㆍ특별자치도ㆍ시ㆍ군(광역시 및 경기도의 관할구역에 있는 군으로 한정한다)ㆍ구(자치구를 말한다)를 말한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제6조의2","원문":"⑤ 임대차계약당사자 중 일방이 신고를 거부해 법 제6조의2제3항에 따라 단독으로 주택 임대차 계약을 신고하려는 임대차계약당사자는 임대차 신고서에 서명 또는 날인한 후 제3항 각 호에 따른 서류 등과 단독신고사유서를 첨부해 신고관청에 제출해야 한다. 이 경우 신고관청은 단독신고 사유에 해당하는지를 확인해야 한다.\n⑥ 제2항부터 제5항까지의 규정에 따라 신고하려는 자는 신분증명서를 신고관청에 보여줘야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조의3","원문":"① 임대차계약당사자는 제6조의2에 따라 신고한 후 해당 주택 임대차 계약의 보증금, 차임 등 임대차 가격이 변경되거나 임대차 계약이 해제된 때에는 변경 또는 해제가 확정된 날부터 30일 이내에 해당 신고관청에 공동으로 신고하여야 한다. 다만, 임대차계약당사자 중 일방이 국가등인 경우에는 국가등이 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조의5","원문":"① 제6조의2에도 불구하고 임차인이 「주민등록법」에 따라 전입신고를 하는 경우 이 법에 따른 주택 임대차 계약의 신고를 한 것으로 본다.\n③ 제6조의2, 제6조의3에 따른 신고의 접수를 완료한 때에는 「주택임대차보호법」 제3조의6제1항에 따른 확정일자를 부여한 것으로 본다(임대차계약서가 제출된 경우로 한정한다). 이 경우 신고관청은 「주택임대차보호법」 제3조의6제2항에 따라 확정일자부를 작성하거나 「주택임대차보호법」 제3조의6의 확정일자부여기관에 신고 사실을 통보하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신고 지역은 특별자치시·특별자치도·시·군(광역시와 경기도 관할구역의 군에 한정)·구이다. 경상북도의 군은 해당하지 않는다(시행령 제4조의3제2항)."},{"번호":2,"판정":"틀림","설명":"보증금·차임의 증감 없이 임대차 기간만 연장하는 갱신계약은 신고 대상에서 제외된다(시행령 제4조의3제1항)."},{"번호":3,"판정":"옳음","설명":"공동신고, 단독신고, 국가등 신고 모두 신분증명서를 보여줘야 한다(시행규칙 제6조의2제5항·제6항)."},{"번호":4,"판정":"틀림","설명":"보증금·차임 등 임대차 가격이 변경되면 변경이 확정된 날부터 30일 이내에 공동으로 변경신고를 해야 한다. 감액도 같다(법 제6조의3제1항)."},{"번호":5,"판정":"틀림","설명":"반대이다. 임차인이 「주민등록법」에 따라 전입신고를 하면 주택 임대차 계약의 신고를 한 것으로 본다(법 제6조의5제1항)."}],"개념":[{"종류":"표","제목":"주택 임대차 계약 신고 요건","머리":["항목","내용","근거"],"행":[["대상 금액","보증금 6천만원 초과 또는 월 차임 30만원 초과","시행령 제4조의3제1항"],["제외","보증금·차임 증감 없이 기간만 연장하는 갱신계약","같은 항"],["대상 지역","특별자치시·특별자치도·시·군(광역시·경기도 관할 군만)·구","같은 조 제2항"],["기한·장소","계약체결일부터 30일 이내 주택 소재지 관할 신고관청","법 제6조의2제1항"],["변경·해제","확정일부터 30일 이내 공동 신고","법 제6조의3제1항"],["의제","전입신고 시 임대차 신고 의제, 신고 접수 완료 시 확정일자 부여 의제(계약서 제출 시)","법 제6조의5제1항·제3항"],["과태료","신고 불이행·거짓 신고 100만원 이하","법 제28조제5항제3호"]]},{"종류":"비교","제목":"임대차 신고와 확정일자","왼쪽":{"이름":"신고 접수 완료","항목":["임대차계약서가 제출된 경우","확정일자를 부여한 것으로 봄","신고관청이 확정일자부 작성 또는 통보"]},"오른쪽":{"이름":"전입신고","항목":["임차인이 주민등록법에 따라 한 경우","주택 임대차 계약의 신고를 한 것으로 봄","주민등록 대항요건도 별도로 충족"]}}],"함정":"신고 지역을 광역시와 경기도 군까지만 잡는 점을 놓치기 쉽다. 의제 방향(전입신고 → 임대차 신고)이 뒤집힌 5번도 단골이다."}},{"i":"S4-2-1-중개사법-30","r":"S4","g":2,"c":2,"n":30,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 외국인등의 대한민국 안의 부동산(이하 “국내 부동산”이라 함) 취득에 관한 설명으로 틀린 것은? (단, 상호주의에 따른 제한은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["정부간 기구는 외국인등에 포함된다.","외국의 법령에 따라 설립된 법인이 건축물의 신축으로 국내 부동산을 취득한 때에는 부동산을 취득한 날부터 60일 이내에 신고관청에 취득신고를 하여야 한다.","외국인이 국내 부동산을 취득하는 교환계약을 체결하였을 때에는 계약체결일부터 60일 이내에 신고관청에 취득신고를 하여야 한다.","외국인이 국내 부동산을 매수하기 위하여 체결한 매매계약은 부동산 거래신고의 대상이다.","국내 부동산을 가지고 있는 대한민국국민이 외국인으로 변경된 경우 그 외국인이 해당 부동산을 계속보유하려는 때에는 외국인으로 변경된 날부터 6개월 이내에 신고관청에 계속보유신고를 하여야 한다."],"a":[2],"L":"중2-3","o":"기출","x":{"한줄":"신축으로 취득하는 것은 계약 외의 원인이라 취득한 날부터 6개월 이내에 신고한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제2조","원문":"2. 정부간 기구"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제8조","원문":"① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n③ 대한민국 안의 부동산등을 가지고 있는 대한민국국민이나 대한민국의 법령에 따라 설립된 법인 또는 단체가 외국인등으로 변경된 경우 그 외국인등이 해당 부동산등을 계속보유하려는 경우에는 외국인등으로 변경된 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제5조","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n4. 건축물의 신축ㆍ증축ㆍ개축ㆍ재축"}],"선지":[{"번호":1,"판정":"옳음","설명":"정부간 기구는 외국인등에 해당하는 국제기구이다(시행령 제2조제2호, 법 제2조제4호사목)."},{"번호":2,"판정":"틀림","설명":"건축물의 신축은 계약 외의 원인이므로 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항, 시행령 제5조제2항제4호). 60일은 계약으로 취득할 때의 기한이다."},{"번호":3,"판정":"옳음","설명":"교환계약은 거래신고 대상 계약(법 제3조제1항 각 호)이 아니므로 계약으로 취득하는 경우로서 계약체결일부터 60일 이내에 취득신고한다(법 제8조제1항)."},{"번호":4,"판정":"옳음","설명":"외국인등도 거래당사자에 포함되므로 매매계약은 법 제3조에 따른 부동산 거래신고 대상이다(법 제2조제3호)."},{"번호":5,"판정":"옳음","설명":"국민이 외국인등으로 변경된 경우 변경된 날부터 6개월 이내에 계속보유신고를 한다(법 제8조제3항)."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득·보유 신고","머리":["취득 원인","기한","근거"],"행":[["거래신고 대상 계약(매매 등)","계약체결일부터 30일 이내 부동산 거래신고","법 제3조"],["그 외 계약(교환·증여 등)","계약체결일부터 60일 이내 취득신고","법 제8조제1항"],["상속·경매","취득한 날부터 6개월 이내","같은 조 제2항"],["환매권 행사, 법원의 확정판결, 법인의 합병, 건축물의 신축·증축·개축·재축","취득한 날부터 6개월 이내","시행령 제5조제2항"],["국민·내국법인이 외국인등으로 변경","변경된 날부터 6개월 이내 계속보유신고","법 제8조제3항"]]},{"종류":"표","제목":"외국인등 해당 유형","머리":["유형","내용"],"행":[["개인","대한민국 국적이 없는 개인"],["법인·단체","외국 법령에 따라 설립, 사원·임원 1/2 이상이 외국인, 외국인·외국법인이 자본금·의결권 1/2 이상 보유"],["정부","외국 정부"],["국제기구","국제연합과 그 산하기구·전문기구, 정부간 기구, 준정부간 기구, 비정부간 국제기구"]]}],"함정":"신고기한 60일과 6개월을 취득 원인으로 가르는 문제다. 매매는 거래신고 30일, 교환·증여는 취득신고 60일, 상속·경매·신축 등은 6개월이다."}},{"i":"S4-2-1-중개사법-31","r":"S4","g":2,"c":2,"n":31,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 토지거래허가구역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["허가구역이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우에는 관할 시ㆍ도지사가 공동으로 허가구역을 지정해야 한다.","시ㆍ도지사가 허가구역을 지정하려면 시ㆍ도도시계획위원회의 심의를 거쳐야 하나, 지정기간이 끝나는 허가구역을 계속하여 다시 지정하는 경우에는 심의 없이 시장ㆍ군수 또는 구청장의 의견만 들으면 된다.","허가구역의 지정기간은 10년 이내로 한다.","지정 공고 내용을 통지받은 시장ㆍ군수 또는 구청장은 지체 없이 그 공고 내용을 5일간 일반이 열람할 수 있도록 하여야 한다.","허가구역의 지정은 허가구역의 지정을 공고한 날부터 5일 후에 효력이 발생한다."],"a":[5],"L":"중2-4","o":"변형","x":{"한줄":"허가구역의 지정은 지정을 공고한 날부터 5일 후에 효력이 발생한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조","원문":"① 국토교통부장관 또는 시ㆍ도지사는 국토의 이용 및 관리에 관한 계획의 원활한 수립과 집행, 합리적인 토지 이용 등을 위하여 토지의 투기적인 거래가 성행하거나 지가(地價)가 급격히 상승하는 지역과 그러한 우려가 있는 지역으로서 대통령령으로 정하는 지역에 대해서는 다음 각 호의 구분에 따라 5년 이내의 기간을 정하여 제11조제1항에 따른 토지거래계약에 관한 허가구역(이하 \"허가구역\"이라 한다)으로 지정할 수 있다. 이 경우 국토교통부장관 또는 시ㆍ도지사는 대통령령으로 정하는 바에 따라 허가대상자(외국인등을 포함한다. 이하 이 조에서 같다), 허가대상 용도와 지목 등을 특정하여 허가구역을 지정할 수 있다.\n1. 허가구역이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우: 국토교통부장관이 지정\n② 국토교통부장관 또는 시ㆍ도지사는 제1항에 따라 허가구역을 지정하려면 「국토의 계획 및 이용에 관한 법률」 제106조에 따른 중앙도시계획위원회(이하 \"중앙도시계획위원회\"라 한다) 또는 같은 법 제113조제1항에 따른 시ㆍ도도시계획위원회(이하 \"시ㆍ도도시계획위원회\"라 한다)의 심의를 거쳐야 한다. 다만, 지정기간이 끝나는 허가구역을 계속하여 다시 허가구역으로 지정하려면 중앙도시계획위원회 또는 시ㆍ도도시계획위원회의 심의 전에 미리 시ㆍ도지사(국토교통부장관이 허가구역을 지정하는 경우만 해당한다) 및 시장ㆍ군수 또는 구청장의 의견을 들어야 한다.\n④ 제3항에 따라 통지를 받은 시장ㆍ군수 또는 구청장은 지체 없이 그 공고 내용을 그 허가구역을 관할하는 등기소의 장에게 통지하여야 하며, 지체 없이 그 사실을 7일 이상 공고하고, 그 공고 내용을 15일간 일반이 열람할 수 있도록 하여야 한다.\n⑤ 허가구역의 지정은 제3항에 따라 허가구역의 지정을 공고한 날부터 5일 후에 그 효력이 발생한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"둘 이상의 시ㆍ도에 걸쳐 있으면 국토교통부장관이 지정한다(법 제10조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"재지정의 경우에도 도시계획위원회의 심의는 거쳐야 한다. 심의 전에 미리 시장ㆍ군수 또는 구청장(국토교통부장관이 지정하는 경우는 시ㆍ도지사도)의 의견을 듣는 것이 다를 뿐이다(법 제10조제2항 단서)."},{"번호":3,"판정":"틀림","설명":"지정기간은 5년 이내이다(법 제10조제1항)."},{"번호":4,"판정":"틀림","설명":"시장ㆍ군수 또는 구청장은 공고 내용을 등기소장에게 통지하고, 그 사실을 7일 이상 공고하며, 공고 내용을 15일간 열람할 수 있게 한다(법 제10조제4항)."},{"번호":5,"판정":"옳음","설명":"효력은 공고한 날부터 5일 후에 발생한다(법 제10조제5항)."}],"개념":[{"종류":"흐름","제목":"허가구역 지정 절차","단계":[{"이름":"지정권자","설명":"둘 이상의 시ㆍ도에 걸치면 국토교통부장관, 동일 시ㆍ도 안이면 시ㆍ도지사(국가 개발사업 등은 국토교통부장관도 가능). 5년 이내"},{"이름":"심의","설명":"중앙도시계획위원회 또는 시ㆍ도도시계획위원회. 재지정은 심의 전에 의견 청취"},{"이름":"공고·통지","설명":"지체 없이 공고. 국토교통부장관은 시ㆍ도지사를 거쳐 시장ㆍ군수ㆍ구청장에게, 시ㆍ도지사는 국토교통부장관과 시장ㆍ군수ㆍ구청장에게 통지"},{"이름":"등기소·열람","설명":"시장ㆍ군수ㆍ구청장이 등기소장에 통지, 7일 이상 공고, 15일간 열람"},{"이름":"효력","설명":"공고한 날부터 5일 후"}]},{"종류":"표","제목":"허가 면제 면적(시행령 제9조제1항)","머리":["구분","면적"],"행":[["도시지역 주거지역","60㎡ 이하"],["상업지역·공업지역","150㎡ 이하"],["녹지지역","200㎡ 이하"],["용도지역 지정 없는 구역","60㎡ 이하"],["도시지역 외","250㎡ 이하(농지 500㎡, 임야 1천㎡)"]]}],"함정":"기간 숫자(5년, 5일 후, 7일 공고, 15일 열람)를 서로 바꿔 놓은 선지가 나온다. 주거지역 면제 면적은 60㎡이다."}},{"i":"S4-2-1-중개사법-32","r":"S4","g":2,"c":2,"n":32,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 토지거래계약을 허가받은 자가 그 토지를 허가받은 목적대로 이용하지 않을 수 있는 예외사유가 아닌 것은? (단, 그 밖의 사유로 시ㆍ군ㆍ구도시계획위원회가 인정한 경우는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["「건축법 시행령」에 따른 제1종 근린생활시설인 건축물을 취득하여 실제로 이용하는 자가 해당 건축물의 일부를 임대하는 경우","「건축법 시행령」에 따른 단독주택 중 다중주택인 건축물을 취득하여 실제로 이용하는 자가 해당 건축물의 일부를 임대하는 경우","「산업집적활성화 및 공장설립에 관한 법률」에 따른 공장을 취득하여 실제로 이용하는 자가 해당 공장의 일부를 임대하는 경우","「건축법 시행령」에 따른 제2종 근린생활시설인 건축물을 취득하여 실제로 이용하는 자가 해당 건축물의 일부를 임대하는 경우","「건축법 시행령」에 따른 공동주택 중 다세대주택인 건축물을 취득하여 실제로 이용하는 자가 해당 건축물의 일부를 임대하는 경우"],"a":[2],"L":"중2-4","o":"기출","x":{"한줄":"단독주택 중 다중주택과 공관은 일부 임대 예외에서 빠진다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제14조","원문":"① 법 제17조제1항에서 \"대통령령으로 정하는 사유가 있는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n9. 다음 각 목의 건축물을 취득하여 실제로 이용하는 자가 해당 건축물의 일부를 임대하는 경우\n가. 「건축법 시행령」 별표 1 제1호의 단독주택[다중주택 및 공관(公館)은 제외한다]\n나. 「건축법 시행령」 별표 1 제2호의 공동주택(기숙사는 제외한다)\n다. 「건축법 시행령」 별표 1 제3호의 제1종 근린생활시설\n라. 「건축법 시행령」 별표 1 제4호의 제2종 근린생활시설\n10. 「산업집적활성화 및 공장설립에 관한 법률」 제2조제1호에 따른 공장을 취득하여 실제로 이용하는 자가 해당 공장의 일부를 임대하는 경우"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제17조","원문":"① 제11조에 따라 토지거래계약을 허가받은 자는 대통령령으로 정하는 사유가 있는 경우 외에는 5년의 범위에서 대통령령으로 정하는 기간에 그 토지를 허가받은 목적대로 이용하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제1종 근린생활시설을 취득하여 실제로 이용하는 자가 일부를 임대하는 경우는 예외사유이다(시행령 제14조제1항제9호다목)."},{"번호":2,"판정":"틀림","설명":"단독주택 중 다중주택은 예외에서 제외된다(시행령 제14조제1항제9호가목). 일부 임대는 이용의무 위반이다."},{"번호":3,"판정":"옳음","설명":"공장을 취득하여 실제로 이용하는 자가 일부를 임대하는 경우는 예외사유이다(시행령 제14조제1항제10호)."},{"번호":4,"판정":"옳음","설명":"제2종 근린생활시설의 일부 임대는 예외사유이다(시행령 제14조제1항제9호라목)."},{"번호":5,"판정":"옳음","설명":"공동주택(기숙사 제외)인 다세대주택의 일부 임대는 예외사유이다(시행령 제14조제1항제9호나목)."}],"개념":[{"종류":"표","제목":"토지 이용의무 기간(시행령 제14조제2항)","머리":["허가 목적","기간"],"행":[["자기 거주용 주택용지, 주민 복지·편익시설, 농업·임업·어업 경영","토지 취득일부터 2년"],["공익사업, 지정 지역·지구 사업, 허가구역 지정 당시 사업 시행자 등(법 제12조제1호 라~바목)","토지 취득일부터 4년(분양 목적은 개발 착수 후 4년 이내 분양 완료 시 완료한 때)"],["협의양도·수용 대체토지 취득","토지 취득일부터 2년"],["현상 보존 목적","토지 취득일부터 5년"],["그 밖의 경우","토지 취득일부터 5년"]]},{"종류":"표","제목":"이행강제금(시행령 제16조제3항)","머리":["위반 유형","금액"],"행":[["방치","토지 취득가액의 10%"],["직접 이용하지 않고 임대","토지 취득가액의 7%"],["허가관청 승인 없이 이용목적 변경","토지 취득가액의 5%"],["그 밖의 경우","토지 취득가액의 7%"],["부과 절차","문서 이행명령(이행기간 3개월 이내) → 문서 계고 → 부과. 이의제기는 부과처분 고지일부터 30일 이내"]]}],"함정":"일부 임대 예외는 단독주택 중 다중주택·공관과 공동주택 중 기숙사만 빠진다. 다중주택을 다가구주택이나 다세대주택과 섞어 기억하면 오답으로 간다."}},{"i":"S4-2-1-중개사법-33","r":"S4","g":2,"c":2,"n":33,"s":"중개사법","q":"개업공인중개사가 묘지를 설치하고자 토지를 매수하려는 중개의뢰인에게 장사 등에 관한 법령에 관하여 설명한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["가족묘지는 가족당 1개소로 제한하되, 그 면적은 100제곱미터 이하여야 한다.","개인묘지란 1기의 분묘 또는 해당 분묘에 매장된 자와 배우자 관계였던 자의 분묘를 같은 구역 안에 설치하는 묘지를 말한다.","법인묘지에는 폭 4미터 이상의 도로와 그 도로로부터 각 분묘로 통하는 충분한 진출입로를 설치하여야 한다.","화장한 유골을 매장하는 경우 매장 깊이는 지면으로부터 30센티미터 이상이어야 한다.","민법 에 따라 설립된 사단법인은 법인묘지의 설치 허가를 받을 수 없다."],"a":[3],"L":"중3-1","o":"기출","x":{"한줄":"법인묘지에는 폭 5미터 이상의 도로와 각 분묘로 통하는 진출입로를 설치한다.","근거":[{"법령":"장사 등에 관한 법률 시행령","조문":"별표 2 제2호가목","원문":"가족묘지는 가족당 1개소로 제한하되, 그 면적은 100제곱미터 이하여야 한다."},{"법령":"장사 등에 관한 법률 시행령","조문":"별표 2 제4호라목","원문":"법인묘지에는 폭 5미터 이상의 도로와 그 도로로부터 각 분묘로 통하는 충분한 진출입로를 설치하고, 주차장을 마련하여야 한다."},{"법령":"장사 등에 관한 법률","조문":"제14조","원문":"① 국가, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장이 아닌 자는 다음 각 호의 구분에 따른 묘지(이하 \"사설묘지\"라 한다)를 설치ㆍ관리할 수 있다.\n1. 개인묘지 : 1기의 분묘 또는 해당 분묘에 매장된 자와 배우자 관계였던 자의 분묘를 같은 구역 안에 설치하는 묘지\n⑤ 시장등은 묘지의 설치ㆍ관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정하여 법인묘지의 설치ㆍ관리를 허가할 수 있다."},{"법령":"장사 등에 관한 법률 시행령","조문":"제7조","원문":"법 제9조제2항에 따른 매장ㆍ화장 및 개장의 방법과 기준은 다음 각 호와 같다.\n나. 화장한 유골을 매장하는 경우 매장 깊이는 지면으로부터 30센티미터 이상이어야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"가족묘지는 가족당 1개소, 100㎡ 이하이다(시행령 별표 2 제2호가목)."},{"번호":2,"판정":"옳음","설명":"개인묘지의 정의이다(법 제14조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"도로 폭은 5미터 이상이다(시행령 별표 2 제4호라목)."},{"번호":4,"판정":"옳음","설명":"화장한 유골의 매장 깊이는 30센티미터 이상이다. 시신이나 화장하지 않은 유골은 1미터 이상이다(시행령 제7조제1호)."},{"번호":5,"판정":"옳음","설명":"법인묘지는 묘지의 설치·관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정하여 허가할 수 있다(법 제14조제5항). 사단법인은 허가받을 수 없다."}],"개념":[{"종류":"표","제목":"사설묘지 4종","머리":["구분","내용","절차","면적"],"행":[["개인묘지","1기의 분묘 또는 그 분묘에 묻힌 자와 배우자 관계였던 자의 분묘","설치 후 30일 이내 시장등에게 신고(법 제14조제2항)","30㎡ 초과 금지(법 제18조제2항)"],["가족묘지","「민법」에 따라 친족관계였던 자의 분묘","시장등의 허가","가족당 1개소, 100㎡ 이하"],["종중·문중묘지","종중·문중 구성원의 분묘","시장등의 허가","종중·문중별 1개소, 1천㎡ 이하"],["법인묘지","법인이 불특정 다수인의 분묘를 설치","시장등의 허가(재단법인에 한정)","10만㎡ 이상"]]},{"종류":"표","제목":"설치기준 숫자","머리":["항목","기준","근거"],"행":[["매장 깊이","시신·화장하지 않은 유골 1미터 이상, 화장한 유골 30센티미터 이상","시행령 제7조"],["봉분·평분 높이","봉분 1미터, 평분 50센티미터 이하","시행령 별표 2"],["분묘 1기 구역","10㎡(합장 15㎡) 초과 금지. 개인묘지는 해당 없음","법 제18조제1항"],["분묘 설치기간","30년. 연장 신청 시 1회에 한하여 30년 연장","법 제19조제1·2항"],["법인묘지 도로","폭 5미터 이상 도로와 진출입로, 주차장","시행령 별표 2 제4호라목"]]}],"함정":"법인묘지 도로 폭 5미터를 4미터로 바꿔 놓았다. 개인묘지는 신고, 나머지 셋은 허가이고, 법인묘지는 재단법인만 받을 수 있다는 점도 함께 묻는다."}},{"i":"S4-2-1-중개사법-34","r":"S4","g":2,"c":2,"n":34,"s":"중개사법","q":"개업공인중개사가 분묘가 있는 토지에 관하여 중개 의뢰인에게 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["분묘기지권은 등기 없이도 그 토지를 양수한 제3자에게 주장할 수 있다.","자기 소유 토지에 분묘를 설치한 자가 분묘를 이장한다는 특약 없이 토지만 처분하여 분묘기지권을 취득한 경우, 분묘기지권이 성립한 때부터 지료를 지급할 의무가 있다.","승낙 없이 설치한 분묘의 기지를 20년간 평온ㆍ공연하게 점유하여 분묘기지권을 시효취득한 자는 토지 소유자가 지료를 청구하면 그 청구한 날부터의 지료를 지급할 의무가 있다.","분묘기지권이 미치는 범위 안에서는 기존 분묘 외에 부부의 쌍분이나 합장을 위한 새로운 분묘를 설치할 수 있다.","봉분 없이 평장되거나 암장된 분묘에는 분묘기지권이 성립하지 않는다."],"a":[4],"L":"중3-1","o":"변형","x":{"한줄":"분묘기지권은 기존 분묘를 수호·봉제사하기 위한 권리라서, 그 범위 안이라도 새로운 분묘를 설치할 권능은 없다.","근거":[{"판례":"대법원 2017다228007 전원합의체(2021. 4. 29.)","요지":"장사법 시행일(2001. 1. 13.) 이전에 타인의 토지에 분묘를 설치하고 20년간 평온·공연하게 점유하여 분묘기지권을 시효로 취득하였더라도, 분묘기지권자는 토지 소유자가 분묘기지에 관한 지료를 청구하면 그 청구한 날부터의 지료를 지급할 의무가 있다."},{"이론":"분묘기지권의 성질과 범위","내용":"분묘기지권은 타인의 토지에 있는 분묘를 수호하고 제사를 지내기 위해 그 기지를 사용하는 관습법상 물권이다. 등기 없이 제3자에게 주장할 수 있고, 분묘의 기지뿐 아니라 수호·제사에 필요한 주위 공지에 미치되 기존 분묘에 관한 권리라서 새 분묘를 설치할 권능은 포함하지 않는다."},{"법령":"장사 등에 관한 법률","조문":"제27조","원문":"① 토지 소유자(점유자나 그 밖의 관리인을 포함한다. 이하 이 조에서 같다), 묘지 설치자 또는 연고자는 다음 각 호의 어느 하나에 해당하는 분묘에 대하여 보건복지부령으로 정하는 바에 따라 그 분묘를 관할하는 시장등의 허가를 받아 분묘에 매장된 시신 또는 유골을 개장할 수 있다.\n③ 제1항 각 호의 어느 하나에 해당하는 분묘의 연고자는 해당 토지 소유자, 묘지 설치자 또는 연고자에게 토지 사용권이나 그 밖에 분묘의 보존을 위한 권리를 주장할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"분묘기지권은 관습법상 물권으로 등기 없이 제3자에게 주장할 수 있다."},{"번호":2,"판정":"옳음","설명":"자기 토지에 분묘를 설치한 뒤 토지만 처분한 경우(양도형)는 분묘기지권이 성립한 때부터 지료를 낸다."},{"번호":3,"판정":"옳음","설명":"시효취득형 분묘기지권자는 토지 소유자가 지료를 청구한 날부터의 지료를 낸다(대법원 2017다228007 전원합의체)."},{"번호":4,"판정":"틀림","설명":"분묘기지권의 효력 범위 안이라도 기존 분묘 외에 쌍분이나 합장을 위한 새 분묘를 설치할 권능은 없다."},{"번호":5,"판정":"옳음","설명":"분묘기지권은 시신(유골)이 안장되고 봉분 등 외부에서 분묘임을 인식할 수 있는 형태를 갖추어야 성립한다. 평장·암장 분묘는 해당하지 않는다."}],"개념":[{"종류":"표","제목":"성립 유형별 지료","머리":["유형","성립 원인","지료"],"행":[["승낙형","토지 소유자의 승낙을 받아 분묘 설치","약정에 따름. 지료 약정은 토지 승계인에게도 효력이 있음"],["양도형","자기 토지에 분묘를 설치한 자가 이장 특약 없이 토지만 처분","분묘기지권이 성립한 때부터"],["시효취득형","승낙 없이 설치 후 20년 평온·공연한 점유","소유자가 청구한 날부터(대법원 2017다228007 전원합의체)"]]},{"종류":"표","제목":"분묘기지권 요점","머리":["항목","내용"],"행":[["시효취득","장사법 시행일(2001. 1. 13.) 이전 설치 분묘에 한정. 시행 후 승낙 없이 설치한 분묘의 연고자는 토지사용권을 주장할 수 없음(장사법 제27조제3항)"],["성립 요건","시신·유골 안장 + 봉분 등 외부에서 인식 가능한 형태"],["효력 범위","분묘 기지와 수호·제사에 필요한 주위 공지. 새 분묘 설치 불가"],["존속","약정이 없으면 권리자가 분묘를 수호·봉제사하며 분묘가 존재하는 동안"],["소멸","분묘 멸실이어도 유골이 있어 복구 가능한 일시적 멸실이면 존속. 권리 포기는 의사표시로 족하고 점유까지 포기할 필요 없음"],["대항력","등기 없이 제3자에게 주장 가능"]]}],"함정":"시효취득형과 양도형의 지료 시점을 맞바꾼 문장이 단골이다. 시효취득형은 청구한 날부터, 양도형은 성립한 때부터이다. 분묘기지권의 범위를 주위 공지까지로 알고 새 분묘 설치까지 허용된다고 확장하면 틀린다."}},{"i":"S4-2-1-중개사법-35","r":"S4","g":2,"c":2,"n":35,"s":"중개사법","q":"개업공인중개사가 대전광역시 소재 다세대주택을 보증금 8천만원으로 임대차하도록 중개하면서 임차인에게 설명한 내용으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["주택의 인도와 주민등록을 마친 당일부터 제3자에 대하여 임대차의 효력이 생긴다.","임차인이 경매신청의 등기 전에 주택의 인도와 주민등록을 마치면 확정일자를 받지 않았더라도 보증금 중 2천8백만원은 담보물권자보다 우선하여 변제받을 수 있다(주택가액의 2분의 1 범위 안).","임차인이 가족과 함께 주민등록을 다른 곳으로 옮겼다가 며칠 뒤 다시 전입한 경우, 대항력은 최초 전입일의 다음 날부터 계속 유지된 것으로 본다.","대항력을 갖춘 임차인이 저당권설정등기 이후 보증금을 증액한 경우, 증액된 보증금 전액에 대해서도 경매로 주택을 취득한 매수인에게 대항할 수 있다.","확정일자는 주택 소재지 관할 세무서장이 부여한다."],"a":[2],"L":"중3-2","o":"변형","x":{"한줄":"광역시의 소액임차인은 보증금 8천5백만원 이하이고 최우선변제액은 2천8백만원이며, 경매신청 등기 전에 대항요건만 갖추면 확정일자는 필요 없다.","근거":[{"법령":"주택임대차보호법","조문":"제8조","원문":"① 임차인은 보증금 중 일정액을 다른 담보물권자(擔保物權者)보다 우선하여 변제받을 권리가 있다. 이 경우 임차인은 주택에 대한 경매신청의 등기 전에 제3조제1항의 요건을 갖추어야 한다.\n③ 제1항에 따라 우선변제를 받을 임차인 및 보증금 중 일정액의 범위와 기준은 제8조의2에 따른 주택임대차위원회의 심의를 거쳐 대통령령으로 정한다. 다만, 보증금 중 일정액의 범위와 기준은 주택가액(대지의 가액을 포함한다)의 2분의 1을 넘지 못한다."},{"법령":"주택임대차보호법 시행령","조문":"제10조","원문":"① 법 제8조에 따라 우선변제를 받을 보증금 중 일정액의 범위는 다음 각 호의 구분에 의한 금액 이하로 한다.\n3. 광역시(「수도권정비계획법」에 따른 과밀억제권역에 포함된 지역과 군지역은 제외한다), 안산시, 광주시, 파주시, 이천시 및 평택시: 2천800만원\n② 임차인의 보증금 중 일정액이 주택가액의 2분의 1을 초과하는 경우에는 주택가액의 2분의 1에 해당하는 금액까지만 우선변제권이 있다."},{"법령":"주택임대차보호법 시행령","조문":"제11조","원문":"3. 광역시(「수도권정비계획법」에 따른 과밀억제권역에 포함된 지역과 군지역은 제외한다), 안산시, 광주시, 파주시, 이천시 및 평택시: 8천500만원"},{"법령":"주택임대차보호법","조문":"제3조","원문":"① 임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다."},{"법령":"주택임대차보호법","조문":"제3조의6","원문":"① 제3조의2제2항의 확정일자는 주택 소재지의 읍ㆍ면사무소, 동 주민센터 또는 시(특별시ㆍ광역시ㆍ특별자치시는 제외하고, 특별자치도는 포함한다)ㆍ군ㆍ구(자치구를 말한다)의 출장소, 지방법원 및 그 지원과 등기소 또는 「공증인법」에 따른 공증인(이하 이 조에서 \"확정일자부여기관\"이라 한다)이 부여한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대항력은 인도와 주민등록을 마친 때의 다음 날부터 생긴다(법 제3조제1항)."},{"번호":2,"판정":"옳음","설명":"대전광역시는 광역시(과밀억제권역·군지역 제외)로서 보증금 8천5백만원 이하 임차인이 소액임차인이고 최우선변제 범위는 2천8백만원이다(시행령 제10조제1항제3호, 제11조제3호). 경매신청 등기 전에 법 제3조제1항의 요건을 갖추면 된다(법 제8조제1항)."},{"번호":3,"판정":"틀림","설명":"주민등록을 이탈하면 대항력을 잃고, 다시 전입한 때에 새로 대항요건을 갖춘 것이 된다. 그 다음 날부터 대항력이 생긴다(판례의 취지, 법 제3조제1항)."},{"번호":4,"판정":"틀림","설명":"저당권설정등기 이후 증액된 보증금 부분은 저당권에 기해 주택을 취득한 매수인에게 대항할 수 없다(판례)."},{"번호":5,"판정":"틀림","설명":"확정일자는 읍·면사무소, 동 주민센터, 출장소, 지방법원 및 그 지원과 등기소, 공증인이 부여한다(법 제3조의6제1항). 세무서장은 상가건물 임대차의 확정일자 부여기관이다."}],"개념":[{"종류":"표","제목":"주택 소액임차인(시행령 제10조·제11조)","머리":["지역","보증금 범위","최우선변제액"],"행":[["서울특별시","1억6천5백만원 이하","5천5백만원"],["과밀억제권역(서울 제외)·세종·용인·화성·김포","1억4천5백만원 이하","4천8백만원"],["광역시(과밀억제권역·군지역 제외)·안산·광주·파주·이천·평택","8천5백만원 이하","2천8백만원"],["그 밖의 지역","7천5백만원 이하","2천5백만원"],["한도","주택가액(대지 포함)의 2분의 1","법 제8조제3항, 시행령 제10조제2항"]]},{"종류":"표","제목":"대항력·우선변제권","머리":["구분","요건·효과","근거"],"행":[["대항력","인도 + 주민등록(전입신고), 다음 날부터","법 제3조제1항"],["우선변제권","대항요건 + 확정일자, 경매·공매 환가대금에서 후순위권리자보다 우선","법 제3조의2제2항"],["최우선변제","경매신청 등기 전에 대항요건(확정일자 불요)","법 제8조제1항"],["확정일자 부여기관","읍·면사무소, 동 주민센터, 시·군·구 출장소, 지방법원·지원, 등기소, 공증인","법 제3조의6제1항"]]}],"함정":"효력 발생 시점은 당일이 아니라 다음 날이다. 최우선변제는 지역별 보증금 한도를 넘으면 한 푼도 못 받는다. 확정일자 부여기관을 상가의 세무서장과 섞는 선지도 나온다.","개정":"소액임차인 기준은 현행 시행령(2023.2.21 개정)의 금액이다. 27회 당시 대구 2천만원 기준과 다르다."}},{"i":"S4-2-1-중개사법-36","r":"S4","g":2,"c":2,"n":36,"s":"중개사법","q":"개업공인중개사 甲의 중개로 丙은 2025. 10. 17. 乙 소유의 성남시 소재 X주택에 대하여 보증금 7,000만원에 2년 기간으로 乙과 임대차계약을 체결하고, 계약 당일 주택의 인도와 주민등록 이전, 임대차계약증서상의 확정일자를 받았다. 임대차가 끝났는데도 보증금을 돌려받지 못한 丙이 임차권등기명령을 신청하는 경우 주택임대차보호법령의 적용에 관한 甲의 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["丙은 X주택의 소재지를 관할하는 지방법원, 지방법원지원 또는 시ㆍ군 법원에 신청할 수 있으며, 신청서에 신청의 이유와 임차권등기의 원인이 된 사실을 소명해야 한다.","임차권등기명령 신청을 기각하는 결정에 대하여 丙은 불복할 수 없다.","임차권등기와 관련하여 든 비용과 임차권등기명령 신청과 관련하여 든 비용은 모두 丙이 부담하며 乙에게 청구할 수 없다.","丙은 임대차기간이 끝나기 전이라도 乙이 보증금 반환을 지체하면 임차권등기명령을 신청할 수 있다.","임차권등기명령의 집행에 따른 임차권등기가 끝난 X주택을 그 이후에 임차한 丁도 소액보증금 요건을 갖추면 최우선변제를 받을 수 있다."],"a":[1],"L":"중3-2","o":"변형","x":{"한줄":"임차권등기명령은 임대차가 끝난 뒤 보증금을 돌려받지 못한 임차인이 주택 소재지 관할 법원에 신청하고, 신청의 이유와 등기 원인 사실을 소명해야 한다.","근거":[{"법령":"주택임대차보호법","조문":"제3조의3","원문":"① 임대차가 끝난 후 보증금이 반환되지 아니한 경우 임차인은 임차주택의 소재지를 관할하는 지방법원ㆍ지방법원지원 또는 시ㆍ군 법원에 임차권등기명령을 신청할 수 있다.\n② 임차권등기명령의 신청서에는 다음 각 호의 사항을 적어야 하며, 신청의 이유와 임차권등기의 원인이 된 사실을 소명(疎明)하여야 한다.\n④ 임차권등기명령의 신청을 기각(棄却)하는 결정에 대하여 임차인은 항고(抗告)할 수 있다.\n⑥ 임차권등기명령의 집행에 따른 임차권등기가 끝난 주택(임대차의 목적이 주택의 일부분인 경우에는 해당 부분으로 한정한다)을 그 이후에 임차한 임차인은 제8조에 따른 우선변제를 받을 권리가 없다.\n⑧ 임차인은 제1항에 따른 임차권등기명령의 신청과 그에 따른 임차권등기와 관련하여 든 비용을 임대인에게 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"임대차가 끝난 후 보증금이 반환되지 않은 경우 소재지 관할 지방법원ㆍ지원 또는 시ㆍ군 법원에 신청하며, 신청의 이유와 임차권등기의 원인이 된 사실을 소명한다(법 제3조의3제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"신청을 기각하는 결정에 대하여 임차인은 항고할 수 있다(법 제3조의3제4항)."},{"번호":3,"판정":"틀림","설명":"임차권등기명령의 신청과 임차권등기와 관련하여 든 비용을 임대인에게 청구할 수 있다(법 제3조의3제8항)."},{"번호":4,"판정":"틀림","설명":"신청은 임대차가 끝난 후 보증금이 반환되지 않은 경우에 할 수 있다(법 제3조의3제1항)."},{"번호":5,"판정":"틀림","설명":"등기가 끝난 주택을 그 이후에 임차한 임차인은 소액보증금의 우선변제를 받을 권리가 없다(법 제3조의3제6항)."}],"개념":[{"종류":"흐름","제목":"임차권등기명령 절차","단계":[{"이름":"요건","설명":"임대차가 끝난 후 보증금이 반환되지 않은 경우"},{"이름":"신청","설명":"주택 소재지 관할 지방법원·지원 또는 시·군 법원. 신청 취지·이유와 등기 원인 사실 소명"},{"이름":"재판·집행","설명":"가압류 규정 준용. 기각 결정은 임차인이 항고 가능"},{"이름":"등기 효과","설명":"대항력·우선변제권 취득. 이미 취득했다면 유지. 이후 주민등록·점유를 옮겨도 이미 취득한 권리 상실하지 않음"},{"이름":"비용","설명":"신청·등기 관련 비용을 임대인에게 청구 가능"}]},{"종류":"표","제목":"임차권등기명령 요점","머리":["항목","내용","근거"],"행":[["신청 시기","임대차 종료 후 보증금 미반환","제3조의3제1항"],["소명","신청 이유와 임차권등기 원인 사실","같은 조 제2항"],["불복","기각 결정에 항고","같은 조 제4항"],["효과","대항력·우선변제권 취득 또는 유지","같은 조 제5항"],["후속 임차인","등기 후 임차한 임차인은 소액보증금 최우선변제 불가","같은 조 제6항"],["비용","임대인에게 청구 가능","같은 조 제8항"],["금융기관등","임차인을 대위하여 신청 가능","같은 조 제9항"]]}],"함정":"등기 후 주민등록을 옮겨도 대항력을 잃지 않는다는 점과, 등기 후 새로 들어온 임차인은 최우선변제가 없다는 점을 구분해야 한다. 비용은 신청 비용과 등기 비용 모두 임대인에게 청구할 수 있다."}},{"i":"S4-2-1-중개사법-37","r":"S4","g":2,"c":2,"n":37,"s":"중개사법","q":"개업공인중개사가 구분소유권의 목적인 건물을 매수하려는 중개의뢰인에게 ｢집합건물의 소유 및 관리에 관한 법률｣에 관하여 설명한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["일부의 구분소유자만이 공용하도록 제공되는 것임이 명백한 공용부분도 구분소유자 전원의 공유에 속한다.","대지의 공유자는 그 대지에 구분소유권의 목적인 1동의 건물이 있을 때에도 그 건물 사용에 필요한 범위의 대지에 대해 분할을 청구할 수 있다.","구분소유자는 공용부분을 개량하기 위해서 필요한 범위에서 다른 구분소유자의 전유부분의 사용을 청구할 수 있다.","전유부분이 속하는 1동의 건물의 설치 또는 보존의 흠으로 인하여 다른 자에게 손해를 입힌 경우에는 그 흠은 전유부분에 존재하는 것으로 추정한다.","대지사용권이 없는 구분소유자는 대지사용권자에게 대지사용권을 시가(時價)로 매도할 것을 청구할 수 있다."],"a":[3],"L":"중3-2","o":"기출","x":{"한줄":"구분소유자는 전유부분이나 공용부분을 보존하거나 개량하기 위해 필요한 범위에서 다른 구분소유자의 전유부분의 사용을 청구할 수 있고, 손해가 생기면 보상한다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제5조","원문":"③ 구분소유자는 그 전유부분이나 공용부분을 보존하거나 개량하기 위하여 필요한 범위에서 다른 구분소유자의 전유부분 또는 자기의 공유(共有)에 속하지 아니하는 공용부분의 사용을 청구할 수 있다. 이 경우 다른 구분소유자가 손해를 입었을 때에는 보상하여야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제6조","원문":"전유부분이 속하는 1동의 건물의 설치 또는 보존의 흠으로 인하여 다른 자에게 손해를 입힌 경우에는 그 흠은 공용부분에 존재하는 것으로 추정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제7조","원문":"대지사용권을 가지지 아니한 구분소유자가 있을 때에는 그 전유부분의 철거를 청구할 권리를 가진 자는 그 구분소유자에 대하여 구분소유권을 시가(時價)로 매도할 것을 청구할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제8조","원문":"대지 위에 구분소유권의 목적인 건물이 속하는 1동의 건물이 있을 때에는 그 대지의 공유자는 그 건물 사용에 필요한 범위의 대지에 대하여는 분할을 청구하지 못한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제10조","원문":"① 공용부분은 구분소유자 전원의 공유에 속한다. 다만, 일부의 구분소유자만이 공용하도록 제공되는 것임이 명백한 공용부분(이하 \"일부공용부분\"이라 한다)은 그들 구분소유자의 공유에 속한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"일부공용부분은 그들 일부 구분소유자의 공유에 속한다(제10조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"대지 위에 구분소유권의 목적인 건물이 있으면 건물 사용에 필요한 범위의 대지에 대한 분할을 청구하지 못한다(제8조)."},{"번호":3,"판정":"옳음","설명":"보존·개량을 위해 필요한 범위에서 다른 구분소유자의 전유부분 사용을 청구할 수 있고, 손해를 입은 구분소유자에게는 보상한다(제5조제3항)."},{"번호":4,"판정":"틀림","설명":"흠은 공용부분에 존재하는 것으로 추정한다(제6조)."},{"번호":5,"판정":"틀림","설명":"매도청구의 내용은 대지사용권 매도가 아니라 전유부분의 철거를 청구할 권리를 가진 자가 대지사용권 없는 구분소유자에게 구분소유권을 시가로 매도하라고 청구하는 것이다(제7조)."}],"개념":[{"종류":"표","제목":"집합건물법 조문별 핵심","머리":["조문","내용"],"행":[["제5조제3항","보존·개량에 필요한 범위에서 다른 구분소유자의 전유부분 사용 청구, 손해 보상"],["제6조","설치·보존상의 흠은 공용부분에 있는 것으로 추정"],["제7조","전유부분 철거청구권자가 대지사용권 없는 구분소유자에게 구분소유권을 시가로 매도 청구"],["제8조","대지공유자의 건물 사용에 필요한 범위 분할청구 금지"],["제10조제1항","공용부분은 전원 공유, 일부공용부분은 그들 구분소유자 공유"]]},{"종류":"비교","제목":"매도청구의 방향","왼쪽":{"이름":"제7조 구분소유권 매도청구","항목":["청구하는 사람: 전유부분의 철거를 청구할 권리를 가진 자","청구 상대방: 대지사용권 없는 구분소유자","목적물: 구분소유권, 가격은 시가"]},"오른쪽":{"이름":"오답 방향","항목":["대지사용권 없는 구분소유자가 대지사용권자에게 대지사용권 매도 청구(제7조는 그 반대)"]}}],"함정":"제6조는 \"공용부분\"에 흠이 있는 것으로 추정하고, 제7조는 대지사용권 없는 쪽에서 청구하지 않고 그 상대방이 청구한다. 제8조는 분할청구 금지, 제10조는 일부공용부분의 귀속이다."}},{"i":"S4-2-1-중개사법-38","r":"S4","g":2,"c":2,"n":38,"s":"중개사법","q":"개업공인중개사 甲의 중개로 乙과 丙은 丙소유의 주택에 관하여 임대차계약(이하 '계약'이라 함)을 체결하려 한다. ｢주택임대차보호법｣의 적용에 관한 甲의 설명으로 틀린 것은? (임차인 乙은 자연인임)","b":null,"bs":"없음","img":[],"ch":["乙과 丙이 임대차기간을 2년 미만으로 정한다면 乙은 그 임대차기간이 유효함을 주장할 수 없다.","계약이 묵시적으로 갱신되면 임대차의 존속기간은 2년으로 본다.","계약이 묵시적으로 갱신되면 乙은 언제든지 丙에게 계약해지를 통지할 수 있고, 丙이 그 통지를 받은 날부터 3개월이 지나면 해지의 효력이 발생한다.","乙이 丙에게 계약갱신요구권을 행사하여 계약이 갱신되면, 갱신되는 임대차의 존속기간은 2년으로 본다.","乙이 丙에게 계약갱신요구권을 행사하여 계약이 갱신된 경우 乙은 언제든지 丙에게 계약해지를 통지할 수 있다."],"a":[1],"L":"중3-2","o":"기출","x":{"한줄":"2년 미만으로 정한 기간은 임차인이 유효함을 주장할 수 있다.","근거":[{"법령":"주택임대차보호법","조문":"제4조","원문":"① 기간을 정하지 아니하거나 2년 미만으로 정한 임대차는 그 기간을 2년으로 본다. 다만, 임차인은 2년 미만으로 정한 기간이 유효함을 주장할 수 있다."},{"법령":"주택임대차보호법","조문":"제6조","원문":"② 제1항의 경우 임대차의 존속기간은 2년으로 본다."},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다.\n② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제6조의3","원문":"② 임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다.\n④ 제1항에 따라 갱신되는 임대차의 해지에 관하여는 제6조의2를 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기간을 2년 미만으로 정하면 2년으로 보지만, 임차인은 2년 미만으로 정한 기간이 유효함을 주장할 수 있다(법 제4조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"묵시적 갱신의 존속기간은 2년이다(법 제6조제2항)."},{"번호":3,"판정":"옳음","설명":"임차인은 언제든지 해지를 통지할 수 있고, 임대인이 통지를 받은 날부터 3개월이 지나면 효력이 생긴다(법 제6조의2)."},{"번호":4,"판정":"옳음","설명":"계약갱신요구권 행사로 갱신되는 임대차의 존속기간은 2년이다(법 제6조의3제2항)."},{"번호":5,"판정":"옳음","설명":"갱신되는 임대차의 해지에는 제6조의2가 준용되어 임차인은 언제든지 해지를 통지할 수 있다(법 제6조의3제4항)."}],"개념":[{"종류":"비교","제목":"묵시적 갱신과 계약갱신요구권","왼쪽":{"이름":"묵시적 갱신(제6조)","항목":["임대인이 만료 6개월~2개월 전, 임차인이 만료 2개월 전까지 통지 안 한 경우","존속기간 2년","임차인만 언제든 해지 통지, 3개월 후 효력","2기 차임 연체 등 의무 현저 위반 임차인에게는 적용 안 함"]},"오른쪽":{"이름":"계약갱신요구(제6조의3)","항목":["임차인이 만료 6개월~2개월 전에 요구","1회만, 존속기간 2년","차임·보증금은 20분의 1 범위에서 증감(제7조)","임대인은 제1항 각 호 사유가 있으면 거절 가능(2기 연체, 실거주 등)"]}},{"종류":"표","제목":"기간 숫자","머리":["항목","숫자","근거"],"행":[["최단 기간","2년(임차인은 2년 미만 주장 가능)","제4조제1항"],["갱신 통지","6개월~2개월 전","제6조제1항"],["묵시적 갱신 기간","2년","제6조제2항"],["해지 효력","통지받은 날부터 3개월","제6조의2제2항"],["증액 한도","약정액의 20분의 1, 증액 후 1년 내 재증액 불가","제7조"]]}],"함정":"2년 미만 임대차에서 임차인만 유효를 주장할 수 있다는 점을 놓치면 1번을 옳다고 고른다. 묵시적 갱신과 갱신요구는 모두 임차인 해지 통지 후 3개월에 효력이 생긴다.","개정":"갱신 통지 기한은 2020. 6. 9. 개정으로 임대인 6개월~2개월 전, 임차인 2개월 전이다(법 제6조제1항)."}},{"i":"S4-2-1-중개사법-39","r":"S4","g":2,"c":2,"n":39,"s":"중개사법","q":"개업공인중개사가 ｢민사집행법｣에 따른 강제경매에 관하여 중개의뢰인에게 설명한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법원이 경매절차를 개시하는 결정을 할 때에는 동시에 그 부동산의 압류를 명하여야 한다.","압류는 부동산에 대한 채무자의 관리ㆍ이용에 영향을 미치지 아니한다.","제3자는 권리를 취득할 때에 경매신청 또는 압류가 있다는 것을 알았을 경우에도 압류에 대항할 수 있다.","경매개시결정이 등기된 뒤에 가압류를 한 채권자는 배당요구를 할 수 있다.","이해관계인은 매각대금이 모두 지급될 때까지 법원에 경매개시결정에 대한 이의신청을 할 수 있다."],"a":[3],"L":"중3-3","o":"기출","x":{"한줄":"제3자가 권리를 취득할 때 경매신청이나 압류가 있다는 것을 알았다면 압류에 대항하지 못한다.","근거":[{"법령":"민사집행법","조문":"제83조","원문":"①경매절차를 개시하는 결정에는 동시에 그 부동산의 압류를 명하여야 한다.\n②압류는 부동산에 대한 채무자의 관리ㆍ이용에 영향을 미치지 아니한다."},{"법령":"민사집행법","조문":"제92조","원문":"①제3자는 권리를 취득할 때에 경매신청 또는 압류가 있다는 것을 알았을 경우에는 압류에 대항하지 못한다."},{"법령":"민사집행법","조문":"제88조","원문":"①집행력 있는 정본을 가진 채권자, 경매개시결정이 등기된 뒤에 가압류를 한 채권자, 민법ㆍ상법, 그 밖의 법률에 의하여 우선변제청구권이 있는 채권자는 배당요구를 할 수 있다."},{"법령":"민사집행법","조문":"제86조","원문":"①이해관계인은 매각대금이 모두 지급될 때까지 법원에 경매개시결정에 대한 이의신청을 할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"경매개시결정에는 동시에 압류를 명한다(제83조제1항)."},{"번호":2,"판정":"옳음","설명":"압류는 채무자의 관리·이용에 영향을 미치지 않는다(제83조제2항)."},{"번호":3,"판정":"틀림","설명":"알았을 경우에는 압류에 대항하지 못한다(제92조제1항)."},{"번호":4,"판정":"옳음","설명":"경매개시결정이 등기된 뒤에 가압류를 한 채권자는 배당요구를 할 수 있다(제88조제1항)."},{"번호":5,"판정":"옳음","설명":"이해관계인은 매각대금이 모두 지급될 때까지 경매개시결정에 대한 이의신청을 할 수 있다(제86조제1항)."}],"개념":[{"종류":"흐름","제목":"강제경매 절차","단계":[{"이름":"개시결정","설명":"경매개시결정과 동시에 압류 명령. 법원사무관등이 즉시 등기 촉탁(제83조·제94조)"},{"이름":"배당요구의 종기","설명":"압류 효력 발생 때부터 1주 이내 결정·공고. 종기는 첫 매각기일 이전(제84조)"},{"이름":"매각기일","설명":"매각물건명세서 작성(제105조). 호가경매, 기일입찰, 기간입찰 중 법원이 정한 방법(제103조)"},{"이름":"매각결정기일","설명":"매각기일부터 1주 이내(제109조). 허가·불허가 결정 선고, 확정되어야 효력(제126조)"},{"이름":"대금 납부","설명":"매각허가결정 확정 후 대금지급기한 통지, 대금을 다 낸 때 권리 취득(제142조·제135조)"},{"이름":"배당","설명":"배당받을 채권자는 제148조 각 호의 채권자"}]},{"종류":"표","제목":"배당받을 채권자(제148조)·배당요구 가능 채권자(제88조)","머리":["구분","내용"],"행":[["제148조제1호","배당요구의 종기까지 경매신청한 압류채권자"],["제148조제2호","배당요구의 종기까지 배당요구한 채권자"],["제148조제3호","첫 경매개시결정등기 전에 등기된 가압류채권자"],["제148조제4호","첫 경매개시결정등기 전에 등기되고 매각으로 소멸하는 저당권·전세권 등 우선변제청구권자"],["제88조제1항","집행력 있는 정본을 가진 채권자, 개시결정 등기 후 가압류채권자, 법률상 우선변제청구권자는 배당요구 가능"]]}],"함정":"제92조제1항은 \"알았을 경우 대항하지 못한다\"는 문장이다. 알지 못했을 때를 뒤집어 외우면 3번을 맞다고 본다. 가압류채권자는 등기 시점에 따라 당연 배당(제148조제3호)과 배당요구(제88조)로 갈린다."}},{"i":"S4-2-1-중개사법-40","r":"S4","g":2,"c":2,"n":40,"s":"중개사법","q":"매수신청대리인으로 등록한 개업공인중개사가 매수신청대리 위임인에게 민사집행법에 따른 부동산경매에 관하여 설명한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["최고가매수신고액이 6억원이고 제공한 매수신청의 보증이 5천만원인 경우, 차순위매수신고는 신고액이 5억 5천만원을 넘는 때에만 할 수 있다.","매수인은 매각허가결정이 확정된 때가 아니라 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다.","저당권보다 먼저 등기된 지상권은 경매로 매각되면 소멸한다.","매수인이 대금지급기한까지 의무를 이행하지 않았고 차순위매수신고인이 없으면 법원은 직권으로 재매각을 명해야 한다.","매각부동산 위의 저당권은 선순위인지 후순위인지를 가리지 않고 매각으로 모두 소멸한다."],"a":[3],"L":"중3-3","o":"변형","x":{"한줄":"저당권보다 먼저 등기된 지상권은 저당권에 대항할 수 있으므로 매각으로 소멸하지 않고 매수인이 인수한다.","근거":[{"법령":"민사집행법","조문":"제114조","원문":"②차순위매수신고는 그 신고액이 최고가매수신고액에서 그 보증액을 뺀 금액을 넘는 때에만 할 수 있다."},{"법령":"민사집행법","조문":"제135조","원문":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다."},{"법령":"민사집행법","조문":"제91조","원문":"②매각부동산 위의 모든 저당권은 매각으로 소멸된다.\n③지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없는 경우에는 매각으로 소멸된다.\n④제3항의 경우 외의 지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 매수인이 인수한다. 다만, 그중 전세권의 경우에는 전세권자가 제88조에 따라 배당요구를 하면 매각으로 소멸된다."},{"법령":"민사집행법","조문":"제138조","원문":"①매수인이 대금지급기한 또는 제142조제4항의 다시 정한 기한까지 그 의무를 완전히 이행하지 아니하였고, 차순위매수신고인이 없는 때에는 법원은 직권으로 부동산의 재매각을 명하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"차순위매수신고는 신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘어야 한다. 6억원 − 5천만원 = 5억 5천만원이다(제114조제2항)."},{"번호":2,"판정":"옳음","설명":"매수인은 매각대금을 다 낸 때에 권리를 취득한다(제135조)."},{"번호":3,"판정":"틀림","설명":"지상권 등은 저당권·압류채권·가압류채권에 대항할 수 없는 경우에 소멸하고, 그 외의 경우에는 매수인이 인수한다(제91조제3항·제4항). 저당권보다 먼저 등기된 지상권은 인수 대상이다."},{"번호":4,"판정":"옳음","설명":"차순위매수신고인이 없고 매수인이 의무를 완전히 이행하지 않으면 법원은 직권으로 재매각을 명해야 한다(제138조제1항)."},{"번호":5,"판정":"옳음","설명":"매각부동산 위의 모든 저당권은 매각으로 소멸한다(제91조제2항)."}],"개념":[{"종류":"표","제목":"매각으로 소멸하는 권리와 인수하는 권리(제91조)","머리":["권리","소멸·인수","근거"],"행":[["저당권","모두 소멸","제91조제2항"],["지상권·지역권·전세권·등기된 임차권","저당권·압류채권·가압류채권에 대항할 수 없으면 소멸","같은 조 제3항"],["위 권리 중 그 외의 경우","매수인 인수. 전세권은 전세권자가 배당요구를 하면 소멸","같은 조 제4항"],["유치권","매수인이 유치권으로 담보하는 채권을 변제할 책임","같은 조 제5항"]]},{"종류":"표","제목":"매수신청대리인 등록 규칙 요점","머리":["항목","내용","근거"],"행":[["등록 장소","중개사무소 소재지 관할 지방법원장(법인은 주된 사무소)","규칙 제4조"],["실무교육","등록신청일 전 1년 이내 부동산경매 실무교육 이수","규칙 제10조제1항"],["보증금액","법인 4억원 이상(분사무소마다 2억원 추가), 법인 아닌 개업공인중개사 2억원 이상","규칙 제13조제1항"],["대리 행위","보증 제공, 입찰표 작성·제출, 차순위매수신고, 보증 반환 신청, 공유자 우선매수신고 등","규칙 제2조"],["출석","매각장소 또는 집행법원에 직접 출석","규칙 제14조제3항"],["사건카드 보존","5년","규칙 제15조제1항"],["신고","사무소 이전·휴업·폐업·자격 취소 등 사유 발생일부터 10일 이내 지방법원장에게 신고","규칙 제18조제4항"]]}],"함정":"지상권·전세권의 인수 여부는 저당권보다 먼저 등기됐는지로 가른다. 저당권만 무조건 소멸한다. 차순위매수신고는 \"최고가에서 보증액을 뺀 금액을 넘는\" 때에만 가능하다."}},{"i":"S4-2-1-공법-01","r":"S4","g":2,"c":2,"n":41,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 광역계획권에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["광역계획권이 둘 이상의 도의 관할 구역에 걸쳐 있는 경우, 해당 도지사들은 공동으로 광역계획권을 지정하여야 한다.","광역계획권이 하나의 도의 관할 구역에 속하여 있는 경우, 도지사는 국토교통부장관과 공동으로 광역계획권을 지정 또는 변경하여야 한다.","도지사가 광역계획권을 지정하려면 관계 중앙행정기관의 장의 의견을 들은 후 중앙도시계획위원회의 심의를 거쳐야 한다.","국토교통부장관이 광역계획권을 변경하려면 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 지방도시계획위원회의 심의를 거쳐야 한다.","중앙행정기관의 장, 시ㆍ도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다."],"a":[5],"L":"공1-1","o":"기출","x":{"한줄":"중앙행정기관의 장, 시ㆍ도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제1항·제2항","원문":"① 국토교통부장관 또는 도지사는 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 공간구조 및 기능을 상호 연계시키고 환경을 보전하며 광역시설을 체계적으로 정비하기 위하여 필요한 경우에는 다음 각 호의 구분에 따라 인접한 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 전부 또는 일부를 대통령령으로 정하는 바에 따라 광역계획권으로 지정할 수 있다.\n1. 광역계획권이 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 관할 구역에 걸쳐 있는 경우: 국토교통부장관이 지정\n2. 광역계획권이 도의 관할 구역에 속하여 있는 경우: 도지사가 지정\n② 중앙행정기관의 장, 시ㆍ도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제3항·제4항","원문":"③ 국토교통부장관은 광역계획권을 지정하거나 변경하려면 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 중앙도시계획위원회의 심의를 거쳐야 한다.\n④ 도지사가 광역계획권을 지정하거나 변경하려면 관계 중앙행정기관의 장, 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 지방도시계획위원회의 심의를 거쳐야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"둘 이상의 시·도에 걸친 광역계획권은 국토교통부장관이 지정한다. 도지사들의 공동 지정이 아니다(법 제10조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"하나의 도 안에 속한 광역계획권은 도지사가 지정한다. 국토교통부장관과 공동으로 지정하는 구조가 아니다(법 제10조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"도지사는 관계 중앙행정기관의 장, 관계 시·도지사, 시장 또는 군수의 의견을 들은 뒤 지방도시계획위원회의 심의를 거친다. 중앙도시계획위원회는 국토교통부장관 몫이다(법 제10조제4항)."},{"번호":4,"판정":"틀림","설명":"국토교통부장관은 관계 시·도지사, 시장 또는 군수의 의견을 들은 뒤 중앙도시계획위원회의 심의를 거친다. 지방도시계획위원회가 아니다(법 제10조제3항)."},{"번호":5,"판정":"옳음","설명":"중앙행정기관의 장, 시·도지사, 시장 또는 군수는 국토교통부장관이나 도지사에게 광역계획권의 지정 또는 변경을 요청할 수 있다(법 제10조제2항)."}],"개념":[{"종류":"표","제목":"광역계획권 지정과 광역도시계획 수립·승인","머리":["구분","같은 도 안","둘 이상 시·도에 걸침"],"행":[["광역계획권 지정","도지사(법 제10조①2호)","국토교통부장관(법 제10조①1호)"],["지정 전 의견·심의","관계 중앙행정기관의 장, 시·도지사, 시장·군수 의견 → 지방도시계획위원회 심의(제10조④)","관계 시·도지사, 시장·군수 의견 → 중앙도시계획위원회 심의(제10조③)"],["광역도시계획 수립","관할 시장·군수 공동. 지정일부터 3년 내 승인신청이 없으면 도지사(제11조①1·3호)","관할 시·도지사 공동. 지정일부터 3년 내 승인신청이 없으면 국토교통부장관(제11조①2·4호)"],["승인","시장·군수가 수립하면 도지사 승인(제16조⑤)","시·도지사가 수립하면 국토교통부장관 승인(제16조①)"],["협의가 안 될 때 조정","도지사에게 신청(제17조⑤)","국토교통부장관에게 신청(제17조①)"]]},{"종류":"흐름","제목":"광역도시계획 수립 절차","단계":[{"이름":"광역계획권 지정","설명":"국토교통부장관 또는 도지사가 지정(제10조)"},{"이름":"기초조사","설명":"인구·경제·토지이용 등 조사. 정보체계를 구축하면 5년마다 확인(제13조)"},{"이름":"공청회","설명":"수립·변경 전에 공청회를 열어 의견을 듣는다(제14조)"},{"이름":"의견 청취","설명":"관계 의회와 시장·군수 의견. 30일 이내 제시(제15조)"},{"이름":"승인","설명":"국토교통부장관 또는 도지사 승인. 관계 중앙행정기관 협의 의견은 30일 이내(제16조)"}]}],"함정":"선지 1·2는 지정권자를 바꿔 쓴 선지이다. 도지사가 지정하는 범위는 하나의 도 안이고, 두 개 이상의 시·도에 걸치면 국토교통부장관이 맡는다. 선지 3·4는 위원회 이름이 서로 바뀌어 있다."}},{"i":"S4-2-1-공법-02","r":"S4","g":2,"c":2,"n":42,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 광역도시계획에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["광역도시계획의 수립기준은 국토교통부장관이 정한다.","광역계획권이 같은 도의 관할 구역에 속하여 있는 경우 관할 도지사가 광역도시계획을 수립하여야 한다.","시ㆍ도지사, 시장 또는 군수는 광역도시계획을 수립하거나 변경하려면 미리 관계 시ㆍ도, 시 또는 군의 의회와 관계 시장 또는 군수의 의견을 들어야 한다.","시장 또는 군수가 기초조사정보체계를 구축한 경우에는 등록된 정보의 현황을 5년마다 확인하고 변동사항을 반영하여야 한다.","광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시장 또는 군수로부터 광역도시계획의 승인 신청이 없는 경우 관할 도지사가 광역도시계획을 수립하여야 한다."],"a":[2],"L":"공1-1","o":"기출","x":{"한줄":"광역계획권이 같은 도의 관할 구역에 속하면 관할 시장 또는 군수가 공동으로 광역도시계획을 수립한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제11조제1항","원문":"① 국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 구분에 따라 광역도시계획을 수립하여야 한다.\n1. 광역계획권이 같은 도의 관할 구역에 속하여 있는 경우: 관할 시장 또는 군수가 공동으로 수립\n2. 광역계획권이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우: 관할 시ㆍ도지사가 공동으로 수립\n3. 광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시장 또는 군수로부터 제16조제1항에 따른 광역도시계획의 승인 신청이 없는 경우: 관할 도지사가 수립\n4. 국가계획과 관련된 광역도시계획의 수립이 필요한 경우나 광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시ㆍ도지사로부터 제16조제1항에 따른 광역도시계획의 승인 신청이 없는 경우: 국토교통부장관이 수립"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제13조제5항","원문":"⑤ 국토교통부장관, 시ㆍ도지사, 시장 또는 군수가 제4항에 따라 기초조사정보체계를 구축한 경우에는 등록된 정보의 현황을 5년마다 확인하고 변동사항을 반영하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제15조제1항","원문":"① 시ㆍ도지사, 시장 또는 군수는 광역도시계획을 수립하거나 변경하려면 미리 관계 시ㆍ도, 시 또는 군의 의회와 관계 시장 또는 군수의 의견을 들어야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"광역도시계획의 수립기준은 대통령령으로 정하는 바에 따라 국토교통부장관이 정한다(법 제12조제2항)."},{"번호":2,"판정":"틀림","설명":"같은 도 안의 광역계획권은 관할 시장 또는 군수가 공동으로 수립한다. 도지사는 지정일부터 3년이 지나도 승인신청이 없을 때 수립한다(법 제11조제1항제1호·제3호)."},{"번호":3,"판정":"옳음","설명":"시·도지사, 시장 또는 군수는 수립·변경 전에 관계 시·도, 시 또는 군의 의회와 관계 시장·군수의 의견을 듣는다(법 제15조제1항)."},{"번호":4,"판정":"옳음","설명":"기초조사정보체계를 구축한 경우 등록된 정보의 현황을 5년마다 확인하고 변동사항을 반영한다(법 제13조제5항)."},{"번호":5,"판정":"옳음","설명":"광역계획권 지정일부터 3년이 지날 때까지 시장·군수의 승인 신청이 없으면 관할 도지사가 수립한다(법 제11조제1항제3호)."}],"개념":[{"종류":"표","제목":"광역도시계획 수립권자(법 제11조)","머리":["경우","수립권자"],"행":[["같은 도 안의 광역계획권","관할 시장 또는 군수 공동"],["둘 이상의 시·도에 걸친 광역계획권","관할 시·도지사 공동"],["지정일부터 3년 내 시장·군수의 승인신청 없음","관할 도지사"],["국가계획 관련, 또는 지정일부터 3년 내 시·도지사의 승인신청 없음","국토교통부장관"],["국토교통부장관이 시·도지사와 공동 수립","시·도지사가 요청하거나 필요하다고 인정할 때(제11조②)"]]},{"종류":"표","제목":"광역도시계획 기간·기준 모음","머리":["항목","내용"],"행":[["수립기준","국토교통부장관이 정한다(제12조②)"],["기초조사정보체계 확인","5년마다(제13조⑤)"],["의회·시장군수 의견 제시","특별한 사유가 없으면 30일 이내(제15조③)"],["관계 중앙행정기관 협의 의견","요청받은 날부터 30일 이내(제16조③)"]]}],"함정":"같은 도 안의 광역계획권이라서 도지사가 수립한다고 고르기 쉽다. 도지사는 시장·군수가 3년 안에 승인을 신청하지 않을 때 나서는 보충 수립권자이다."}},{"i":"S4-2-1-공법-03","r":"S4","g":2,"c":2,"n":43,"s":"공법","q":"「국토의 계획 및 이용에 관한 법률」상 도시ㆍ군관리계획의 결정에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["대도시의 시장은 도시ㆍ군관리계획을 직접 결정할 수 없고 시ㆍ도지사에게 그 결정을 신청하여야 한다.","수산자원보호구역의 지정에 관한 도시ㆍ군관리계획은 국토교통부장관이 결정한다.","시장 또는 군수가 입안한 지구단위계획구역의 지정에 관한 도시ㆍ군관리계획은 도지사가 결정한다.","국방상 기밀을 지켜야 할 필요가 있다고 인정되어 관계 중앙행정기관의 장이 요청하는 경우, 국토교통부장관은 중앙도시계획위원회의 심의를 거치지 아니하고 도시ㆍ군관리계획을 결정할 수 있다.","도시ㆍ군관리계획 결정의 효력은 그 결정을 고시한 날부터 발생한다."],"a":[4],"L":"공1-2","o":"변형","x":{"한줄":"국방상 또는 국가안전보장상 기밀을 지켜야 할 필요가 있고 관계 중앙행정기관의 장이 요청하면 국토교통부장관은 협의·심의 절차를 생략하고 결정할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제29조제1항·제2항","원문":"① 도시ㆍ군관리계획은 시ㆍ도지사가 직접 또는 시장ㆍ군수의 신청에 따라 결정한다. 다만, 「지방자치법」 제198조제1항에 따른 인구 50만 이상의 대도시(이하 \"대도시\"라 한다)의 경우에는 해당 시장(이하 \"대도시 시장\"이라 한다)이 직접 결정하고, 다음 각 호의 도시ㆍ군관리계획은 시장 또는 군수가 직접 결정한다.\n1. 시장 또는 군수가 입안한 지구단위계획구역의 지정ㆍ변경과 지구단위계획의 수립ㆍ변경에 관한 도시ㆍ군관리계획\n② 제1항에도 불구하고 다음 각 호의 도시ㆍ군관리계획은 국토교통부장관이 결정한다. 다만, 제4호의 도시ㆍ군관리계획은 해양수산부장관 또는 시ㆍ도지사가 결정한다.\n4. 제40조에 따른 수산자원보호구역의 지정 및 변경에 관한 도시ㆍ군관리계획(전체 구역 중 1제곱킬로미터 이상의 공유수면은 해양수산부장관이 결정하고, 공유수면에 인접한 토지 또는 1제곱킬로미터 미만의 공유수면은 시ㆍ도지사가 결정한다)"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제30조제3항·제4항","원문":"③ 국토교통부장관은 도시ㆍ군관리계획을 결정하려면 중앙도시계획위원회의 심의를 거쳐야 하며, 시ㆍ도지사가 도시ㆍ군관리계획을 결정하려면 시ㆍ도도시계획위원회의 심의를 거쳐야 한다. 다만, 시ㆍ도지사가 지구단위계획(지구단위계획과 지구단위계획구역을 동시에 결정할 때에는 지구단위계획구역의 지정 또는 변경에 관한 사항을 포함할 수 있다)이나 제52조제1항제1호의2에 따라 지구단위계획으로 대체하는 용도지구 폐지에 관한 사항을 결정하려면 대통령령으로 정하는 바에 따라 「건축법」 제4조에 따라 시ㆍ도에 두는 건축위원회와 도시계획위원회가 공동으로 하는 심의를 거쳐야 한다.\n④ 국토교통부장관이나 시ㆍ도지사는 국방상 또는 국가안전보장상 기밀을 지켜야 할 필요가 있다고 인정되면(관계 중앙행정기관의 장이 요청할 때만 해당된다) 그 도시ㆍ군관리계획의 전부 또는 일부에 대하여 제1항부터 제3항까지의 규정에 따른 절차를 생략할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제31조제1항","원문":"① 도시ㆍ군관리계획 결정의 효력은 제32조제4항에 따라 지형도면을 고시한 날부터 발생한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대도시 시장은 해당 도시의 도시·군관리계획을 직접 결정한다(법 제29조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"수산자원보호구역 지정은 해양수산부장관 또는 시·도지사가 결정한다. 1제곱킬로미터 이상의 공유수면은 해양수산부장관, 공유수면에 인접한 토지나 1제곱킬로미터 미만의 공유수면은 시·도지사 몫이다(법 제29조제2항제4호)."},{"번호":3,"판정":"틀림","설명":"시장 또는 군수가 입안한 지구단위계획구역의 지정·변경은 시장 또는 군수가 직접 결정한다(법 제29조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"국방상 또는 국가안전보장상 기밀을 지켜야 하고 관계 중앙행정기관의 장이 요청할 때만 협의·심의 절차를 생략할 수 있다(법 제30조제4항). 요청이 없으면 생략할 수 없다."},{"번호":5,"판정":"틀림","설명":"효력은 결정·고시일이 아니라 지형도면을 고시한 날부터 발생한다(법 제31조제1항)."}],"개념":[{"종류":"표","제목":"도시·군관리계획 결정권자(법 제29조)","머리":["구분","결정권자"],"행":[["원칙","시·도지사(직접 또는 시장·군수의 신청)"],["대도시","대도시 시장이 직접 결정"],["시장·군수가 입안한 지구단위계획구역 지정·변경과 지구단위계획 수립·변경","시장 또는 군수"],["국토교통부장관이 입안한 계획, 개발제한구역, 시가화조정구역(국가계획 연계)","국토교통부장관"],["수산자원보호구역","해양수산부장관 또는 시·도지사"]]},{"종류":"흐름","제목":"도시·군관리계획 결정부터 효력까지","단계":[{"이름":"입안","설명":"관할 지방자치단체장이 입안(제24조)"},{"이름":"협의","설명":"관계 행정기관의 장과 협의. 의견은 30일 이내(제30조①)"},{"이름":"심의","설명":"국토교통부장관은 중앙도시계획위원회, 시·도지사는 시·도도시계획위원회 심의(제30조③)"},{"이름":"결정·고시","설명":"결정하면 고시하고 관계 서류를 송부해 일반이 열람하게 한다(제30조⑥)"},{"이름":"지형도면 고시","설명":"지형도면을 작성하고 고시한다. 시장·군수는 도지사 승인이 필요하다(제32조)"},{"이름":"효력 발생","설명":"지형도면 고시일부터(제31조①)"}]}],"함정":"결정 고시일부터 효력이 생긴다고 쉽게 생각한다. 효력 발생 시점은 지형도면 고시일이다. 절차 생략도 관계 중앙행정기관의 장이 요청하는 경우에만 가능하다."}},{"i":"S4-2-1-공법-04","r":"S4","g":2,"c":2,"n":44,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 지방자치단체의 장이 다른 법률에 따른 토지 이용에 관한 구역을 지정하는 경우에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지정하려는 구역의 면적이 1제곱킬로미터 미만인 경우 승인을 받지 않아도 된다.","농림지역에서 ｢수도법｣에 따른 상수원보호구역을 지정하는 경우 국토교통부장관의 승인을 받아야 한다.","지정하려는 구역이 도시ㆍ군기본계획에 반영된 경우에는 승인 없이 구역을 지정할 수 있다.","승인을 받아 지정한 구역의 면적의 10퍼센트의 범위안에서 면적을 증감시키는 경우에는 따로 승인을 받지 않아도 된다.","지정된 구역을 변경하거나 해제하려면 도시ㆍ군관리계획의 입안권자의 의견을 들어야 한다."],"a":[2],"L":"공1-3","o":"기출","x":{"한줄":"농림지역에서 상수원보호구역을 지정하는 경우는 법이 국토교통부장관의 승인 대상에서 빼 두었다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제8조제2항","원문":"② 중앙행정기관의 장이나 지방자치단체의 장은 다른 법률에 따라 지정되는 구역등 중 대통령령으로 정하는 면적 이상의 구역등을 지정하거나 변경하려면 중앙행정기관의 장은 국토교통부장관과 협의하여야 하며 지방자치단체의 장은 국토교통부장관의 승인을 받아야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제8조제4항","원문":"④ 제2항 및 제3항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부장관과의 협의를 거치지 아니하거나 국토교통부장관 또는 시ㆍ도지사의 승인을 받지 아니한다.\n1. 다른 법률에 따라 지정하거나 변경하려는 구역등이 도시ㆍ군기본계획에 반영된 경우\n2. 제36조에 따른 보전관리지역ㆍ생산관리지역ㆍ농림지역 또는 자연환경보전지역에서 다음 각 목의 지역을 지정하려는 경우\n다. 「수도법」 제7조에 따른 상수원보호구역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"시행령 제5조제1항·제5항","원문":"①법 제8조제2항에서 \"대통령령으로 정하는 면적\"이란 1제곱킬로미터(「도시개발법」에 의한 도시개발구역의 경우에는 5제곱킬로미터)를 말한다.\n⑤법 제8조제4항제4호에서 \"대통령령으로 정하는 범위에서 변경하려는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n1. 협의 또는 승인을 얻은 지역ㆍ지구ㆍ구역 또는 구획 등(이하 \"구역등\"이라 한다)의 면적의 10퍼센트의 범위안에서 면적을 증감시키는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"국토교통부장관의 협의·승인 대상은 1제곱킬로미터(도시개발구역은 5제곱킬로미터) 이상이다. 1제곱킬로미터 미만이면 승인이 필요 없다(법 제8조제2항, 영 제5조제1항)."},{"번호":2,"판정":"틀림","설명":"보전관리지역·생산관리지역·농림지역·자연환경보전지역에서 「수도법」 상수원보호구역을 지정하는 경우는 승인을 받지 않는다(법 제8조제4항제2호다목)."},{"번호":3,"판정":"옳음","설명":"구역이 도시·군기본계획에 반영된 경우는 협의·승인 대상이 아니다(법 제8조제4항제1호)."},{"번호":4,"판정":"옳음","설명":"승인받은 구역 면적의 10퍼센트 범위에서 증감하는 변경은 다시 승인받지 않는다(법 제8조제4항제4호, 영 제5조제5항제1호)."},{"번호":5,"판정":"옳음","설명":"구역을 변경하거나 해제하려면 도시·군관리계획 입안권자의 의견을 듣는다(법 제8조제6항)."}],"개념":[{"종류":"표","제목":"다른 법률에 따른 구역 지정의 협의·승인(법 제8조)","머리":["구분","내용"],"행":[["대상 면적","1㎢ 이상(도시개발구역은 5㎢ 이상). 중앙행정기관은 국토교통부장관과 협의, 지방자치단체는 승인(제8조②, 영 제5조①)"],["승인권자","5㎢ 미만은 시·도지사가 시·도도시계획위원회 심의를 거쳐 지정하면 국토교통부장관 승인이 없고, 시장·군수·구청장은 시·도지사 승인(제8조③, 영 제5조③)"],["심의","국토교통부장관 또는 시·도지사가 협의·승인할 때 도시계획위원회 심의(제8조⑤)"],["변경·해제","도시·군관리계획 입안권자의 의견을 듣는다(제8조⑥)"]]},{"종류":"표","제목":"협의·승인이 필요 없는 경우(법 제8조제4항)","머리":["호","내용"],"행":[["1호","구역이 도시·군기본계획에 반영된 경우"],["2호","보전관리·생산관리·농림·자연환경보전지역에서 농업진흥지역, 수변구역, 상수원보호구역, 생태·경관보전지역, 야생생물 특별보호구역, 해양보호구역을 지정하는 경우"],["3호","군사상 기밀을 지켜야 할 구역"],["4호","협의·승인받은 구역을 영 제5조제5항 범위에서 변경(면적 10% 범위의 증감, 면적산정 착오 정정)"]]}],"함정":"1제곱킬로미터 기준과 농림지역의 상수원보호구역 예외가 같이 나온다. 상수원보호구역이라는 이름만 보고 승인 대상으로 생각하기 쉽다."}},{"i":"S4-2-1-공법-05","r":"S4","g":2,"c":2,"n":45,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 용도지역ㆍ용도지구ㆍ용도구역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도시자연공원구역의 지정 및 변경은 국토교통부장관이 도시ㆍ군관리계획으로 결정한다.","시가화조정구역의 지정에 관한 도시ㆍ군관리계획의 결정은 시가화 유보기간이 끝나는 날부터 그 효력을 잃는다.","시ㆍ도지사는 조례로도 법률에서 정하고 있는 용도지구 외의 새로운 용도지구를 지정할 수 없다.","보호취락지구란 녹지지역ㆍ관리지역ㆍ농림지역 또는 자연환경보전지역 안의 취락을 농촌의 주거환경 보호와 주거기능 강화를 목적으로 정비하기 위한 지구를 말한다.","개발제한구역의 지정 및 변경에 관한 도시ㆍ군관리계획은 시ㆍ도지사가 결정한다."],"a":[4],"L":"공1-3","o":"변형","x":{"한줄":"보호취락지구는 녹지지역·관리지역·농림지역·자연환경보전지역 안의 취락을 농촌의 주거환경 보호와 주거기능 강화를 목적으로 정비하는 지구이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제31조제2항제7호","원문":"7. 취락지구\n가. 자연취락지구 : 녹지지역ㆍ관리지역ㆍ농림지역 또는 자연환경보전지역안의 취락을 정비하기 위하여 필요한 지구\n나. 보호취락지구: 녹지지역ㆍ관리지역ㆍ농림지역 또는 자연환경보전지역 안의 취락을 농촌의 주거환경 보호와 주거기능 강화를 목적으로 정비하기 위한 지구\n다. 집단취락지구 : 개발제한구역안의 취락을 정비하기 위하여 필요한 지구"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제38조의2제1항","원문":"① 시ㆍ도지사 또는 대도시 시장은 도시의 자연환경 및 경관을 보호하고 도시민에게 건전한 여가ㆍ휴식공간을 제공하기 위하여 도시지역 안에서 식생(植生)이 양호한 산지(山地)의 개발을 제한할 필요가 있다고 인정하면 도시자연공원구역의 지정 또는 변경을 도시ㆍ군관리계획으로 결정할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제37조제3항","원문":"③ 시ㆍ도지사 또는 대도시 시장은 지역여건상 필요하면 대통령령으로 정하는 기준에 따라 그 시ㆍ도 또는 대도시의 조례로 용도지구의 명칭 및 지정목적, 건축이나 그 밖의 행위의 금지 및 제한에 관한 사항 등을 정하여 제1항 각 호의 용도지구 외의 용도지구의 지정 또는 변경을 도시ㆍ군관리계획으로 결정할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제39조제2항","원문":"② 시가화조정구역의 지정에 관한 도시ㆍ군관리계획의 결정은 제1항에 따른 시가화 유보기간이 끝난 날의 다음날부터 그 효력을 잃는다. 이 경우 국토교통부장관 또는 시ㆍ도지사는 대통령령으로 정하는 바에 따라 그 사실을 고시하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"도시자연공원구역의 지정·변경은 시·도지사 또는 대도시 시장이 결정한다(법 제38조의2제1항)."},{"번호":2,"판정":"틀림","설명":"시가화조정구역 지정 결정은 유보기간이 끝난 날의 다음날부터 효력을 잃는다(법 제39조제2항)."},{"번호":3,"판정":"틀림","설명":"시·도지사 또는 대도시 시장은 지역여건상 필요하면 조례로 법에 열거된 용도지구 외의 용도지구를 도시·군관리계획으로 결정할 수 있다(법 제37조제3항)."},{"번호":4,"판정":"옳음","설명":"영 제31조제2항제7호나목의 정의 그대로이다. 녹지지역·관리지역·농림지역·자연환경보전지역의 취락을 정비하는 지구는 자연취락지구와 보호취락지구이고 개발제한구역의 취락은 집단취락지구이다."},{"번호":5,"판정":"틀림","설명":"개발제한구역의 지정·변경은 국토교통부장관이 결정한다(법 제38조제1항, 제29조제2항제2호)."}],"개념":[{"종류":"표","제목":"용도지구 세분(영 제31조제2항)","머리":["용도지구","세분"],"행":[["경관지구","자연경관지구, 시가지경관지구, 특화경관지구"],["방재지구","시가지방재지구, 자연방재지구"],["보호지구","역사문화환경보호지구, 중요시설물보호지구, 생태계보호지구"],["취락지구","자연취락지구, 보호취락지구, 집단취락지구"],["개발진흥지구","주거개발진흥지구, 산업ㆍ유통개발진흥지구, 관광ㆍ휴양개발진흥지구, 복합개발진흥지구, 특정개발진흥지구"]]},{"종류":"표","제목":"용도구역 지정권자","머리":["용도구역","지정·변경 결정권자"],"행":[["개발제한구역","국토교통부장관(법 제38조①)"],["도시자연공원구역","시·도지사 또는 대도시 시장(법 제38조의2①)"],["시가화조정구역","시·도지사. 국가계획과 연계하면 국토교통부장관(법 제39조①)"],["수산자원보호구역","해양수산부장관 또는 시·도지사(법 제40조)"]]}],"함정":"선지 2는 효력 상실 시점을 유보기간이 끝나는 날로 적었고 선지 3은 조례로 용도지구를 신설할 수 없다고 적었다. 앞의 것은 끝난 날의 다음날이고(법 제39조제2항), 뒤의 것은 조례로 신설할 수 있다(법 제37조제3항).","개정":"2025.7.1 영 제78조제2항이 신설되어 보호취락지구 안에서 건축할 수 있는 건축물을 별표 23의2로 정한다(영 제78조제2항 <신설 2025.7.1>). 보호취락지구의 정의는 영 제31조제2항제7호나목이다."}},{"i":"S4-2-1-공법-06","r":"S4","g":2,"c":2,"n":46,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 제3종일반주거지역 안에서 도시ㆍ군계획조례가 정하는 바에 의하여 건축할 수 없는 건축물은? (단, 건축물의 종류는 「건축법 시행령」 별표 1에 규정된 용도별 건축물의 종류에 따름)","b":null,"bs":"없음","img":[],"ch":["문화 및 집회시설 중 공연장","의료시설 중 종합병원","업무시설로서 그 용도에 쓰이는 바닥면적의 합계가 3천제곱미터인 것","위험물저장 및 처리시설 중 주유소","제2종 근린생활시설 중 안마시술소"],"a":[5],"L":"공1-4","o":"변형","x":{"한줄":"제3종일반주거지역의 조례 허용 목록에서 제2종 근린생활시설은 단란주점과 안마시술소가 빠져 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제71조제1항제5호","원문":"5. 제3종일반주거지역안에서 건축할 수 있는 건축물 : 별표 6에 규정된 건축물"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 별표 6 제2호","원문":"2. 도시ㆍ군계획조례가 정하는 바에 의하여 건축할 수 있는 건축물 가. 「건축법 시행령」 별표 1 제4호의 제2종 근린생활시설(단란주점 및 안마시술소를 제외한다) 나. 「건축법 시행령」 별표 1 제5호의 문화 및 집회시설(관람장을 제외한다) 라. 「건축법 시행령」 별표 1 제9호의 의료시설(격리병원을 제외한다) 아. 「건축법 시행령」 별표 1 제14호의 업무시설로서 그 용도에 쓰이는 바닥면적의 합계가 3천제곱미터 이하인 것 카. 「건축법 시행령」 별표 1 제19호의 위험물저장 및 처리시설 중 주유소, 석유판매소, 액화가스 취급소ㆍ판매소, 도료류 판매소 …"}],"선지":[{"번호":1,"판정":"-","설명":"공연장은 문화 및 집회시설이고 관람장만 제외되므로 조례로 건축할 수 있다(영 별표 6 제2호나목)."},{"번호":2,"판정":"-","설명":"종합병원은 의료시설이다. 격리병원만 제외되므로 조례로 건축할 수 있다(영 별표 6 제2호라목)."},{"번호":3,"판정":"-","설명":"업무시설은 바닥면적 합계 3천제곱미터 이하이면 조례로 건축할 수 있다. 3천제곱미터는 한도에 들어간다(영 별표 6 제2호아목)."},{"번호":4,"판정":"-","설명":"위험물저장 및 처리시설 중 주유소는 조례로 건축할 수 있다(영 별표 6 제2호카목)."},{"번호":5,"판정":"-","설명":"안마시술소는 「건축법 시행령」 별표 1 제4호러목의 제2종 근린생활시설이며 별표 6 제2호가목이 단란주점과 함께 제외한다. 제3종일반주거지역에서는 조례로도 건축할 수 없다."}],"개념":[{"종류":"표","제목":"제3종일반주거지역 건축 가능 건축물(영 별표 6)","머리":["구분","건축물"],"행":[["바로 건축할 수 있는 건축물(1호)","단독주택, 공동주택, 제1종 근린생활시설, 종교시설, 유치원·초등학교·중학교·고등학교, 노유자시설"],["조례로 건축할 수 있는 건축물(2호) 일부","제2종 근린생활시설, 문화 및 집회시설, 판매시설(2천㎡ 미만 등), 의료시설, 교육연구시설(나머지), 수련시설, 운동시설, 업무시설(3천㎡ 이하), 창고시설, 위험물저장 및 처리시설 일부, 자동차관련시설 일부"],["조례 목록에서 빠진 것","단란주점·안마시술소, 관람장, 격리병원, 일반게임제공업 시설, 3천㎡를 넘는 업무시설"],["건축할 수 없는 건축물 예","숙박시설, 위락시설(1호·2호 어디에도 없음)"]]},{"종류":"표","제목":"조례 목록의 제외 항목 모음","머리":["용도","제외 또는 한도"],"행":[["제2종 근린생활시설","단란주점, 안마시술소 제외"],["문화 및 집회시설","관람장 제외"],["의료시설","격리병원 제외"],["업무시설","바닥면적 합계 3천㎡ 이하만"],["판매시설","일반게임제공업 시설 제외, 바닥면적 합계 2천㎡ 미만 등 조건"]]}],"함정":"조례 목록에 들어 있는 큰 용도 이름만 보고 안마시술소도 제2종 근린생활시설이니 가능하다고 고르기 쉽다. 괄호 안 제외 항목까지 읽어야 한다."}},{"i":"S4-2-1-공법-07","r":"S4","g":2,"c":2,"n":47,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 아파트를 건축할 수 있는 용도지역은?","b":null,"bs":"없음","img":[],"ch":["제1종일반주거지역","계획관리지역","유통상업지역","제2종일반주거지역","자연녹지지역"],"a":[4],"L":"공1-4","o":"변형","x":{"한줄":"제2종일반주거지역은 공동주택 전체가 건축 가능 목록에 들어 있어 아파트를 건축할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 별표 5 제1호나목(제2종일반주거지역)","원문":"1. 건축할 수 있는 건축물 가. 「건축법 시행령」 별표 1 제1호의 단독주택 나. 「건축법 시행령」 별표 1 제2호의 공동주택"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 별표 4 제1호나목(제1종일반주거지역)","원문":"나. 「건축법 시행령」 별표 1 제2호의 공동주택(아파트를 제외한다)"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 별표 20 제1호나목(계획관리지역)","원문":"1. 건축할 수 없는 건축물 나. 「건축법 시행령」 별표 1 제2호의 공동주택 중 아파트"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 별표 11 제1호나목(유통상업지역)","원문":"1. 건축할 수 없는 건축물 나. 「건축법 시행령」 별표 1 제2호의 공동주택"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 별표 17 제2호가목(자연녹지지역)","원문":"2. 도시ㆍ군계획조례가 정하는 바에 의하여 건축할 수 있는 건축물 가. 「건축법 시행령」 별표 1 제2호의 공동주택(아파트를 제외한다)"}],"선지":[{"번호":1,"판정":"-","설명":"제1종일반주거지역은 공동주택 중 아파트를 제외한다. 층수도 4층 이하로 묶인다(영 별표 4 제1호)."},{"번호":2,"판정":"-","설명":"계획관리지역은 공동주택 중 아파트를 건축할 수 없다(영 별표 20 제1호나목)."},{"번호":3,"판정":"-","설명":"유통상업지역은 단독주택과 공동주택을 모두 건축할 수 없다(영 별표 11 제1호가목·나목)."},{"번호":4,"판정":"-","설명":"제2종일반주거지역은 공동주택 전체가 건축 가능 목록에 있다. 아파트도 건축할 수 있다(영 별표 5 제1호나목)."},{"번호":5,"판정":"-","설명":"자연녹지지역은 조례가 허용하는 공동주택에서 아파트를 제외한다(영 별표 17 제2호가목)."}],"개념":[{"종류":"표","제목":"용도지역별 아파트 건축 여부","머리":["용도지역","아파트","근거"],"행":[["제1종전용주거지역","불가(연립·다세대만 조례로 가능)","영 별표 2"],["제2종전용주거지역","가능","영 별표 3 제1호나목"],["제1종일반주거지역","불가(아파트 제외, 4층 이하)","영 별표 4"],["제2종·제3종일반주거지역","가능","영 별표 5·6"],["유통상업지역","불가","영 별표 11"],["생산녹지·자연녹지·생산관리지역","불가(공동주택 중 아파트 제외)","영 별표 16·17·19"],["계획관리지역","불가","영 별표 20"]]},{"종류":"표","제목":"주거지역 세분(영 제30조제1항)","머리":["구분","성격"],"행":[["제1종전용주거지역","단독주택 중심의 양호한 주거환경 보호"],["제2종전용주거지역","공동주택 중심의 양호한 주거환경 보호"],["제1종일반주거지역","저층주택 중심"],["제2종일반주거지역","중층주택 중심"],["제3종일반주거지역","중고층주택 중심"],["준주거지역","주거기능 위주, 일부 상업·업무기능 보완"]]}],"함정":"제1종일반주거지역과 자연녹지지역은 공동주택을 허용하지만 목록에서 아파트를 뺀다. 공동주택이 가능하다는 말을 아파트 가능으로 읽으면 선지 1·5에 걸린다."}},{"i":"S4-2-1-공법-08","r":"S4","g":2,"c":2,"n":48,"s":"공법","q":"甲소유의 토지는 A광역시 B구에 소재한 지목이 대(垈)인 토지로서 도시ㆍ군계획시설 부지이다. 도시ㆍ군계획시설결정의 고시일부터 10년이 지나도록 그 시설사업이 시행되지 않았고 실시계획의 인가 절차도 진행되지 않았다. 甲의 토지에 대해 국토의 계획 및 이용에 관한 법령상 도시ㆍ군계획시설 부지의 매수청구권이 인정되는 경우, 이에 관한 설명으로 옳은 것은? (단, 도시ㆍ군계획시설의 설치의무자는 A광역시장이며, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲은 도시ㆍ군계획시설결정의 고시일부터 20년이 지난 때부터 매수를 청구할 수 있다.","甲이 매수를 청구할 수 있는 대상은 토지이며, 그 토지에 있는 건축물은 포함되지 않는다.","매수의무자는 매수대금을 반드시 도시ㆍ군계획시설채권으로 지급하여야 한다.","매수의무자가 매수하기로 결정한 토지는 매수 결정을 알린 날부터 1년 이내에 매수하여야 한다.","매수청구에 대해 매수의무자가 매수하지 아니하기로 결정한 경우 甲은 허가를 받아 자신의 토지에 3층의 제1종 근린생활시설을 건축할 수 있다."],"a":[5],"L":"공1-5","o":"변형","x":{"한줄":"매수하지 않기로 결정되면 토지 소유자는 허가를 받아 3층 이하의 단독주택·제1종 근린생활시설 등을 설치할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제47조제1항·제7항","원문":"① 도시ㆍ군계획시설에 대한 도시ㆍ군관리계획의 결정(이하 \"도시ㆍ군계획시설결정\"이라 한다)의 고시일부터 10년 이내에 그 도시ㆍ군계획시설의 설치에 관한 도시ㆍ군계획시설사업이 시행되지 아니하는 경우(제88조에 따른 실시계획의 인가나 그에 상당하는 절차가 진행된 경우는 제외한다. 이하 같다) 그 도시ㆍ군계획시설의 부지로 되어 있는 토지 중 지목(地目)이 대(垈)인 토지(그 토지에 있는 건축물 및 정착물을 포함한다. 이하 이 조에서 같다)의 소유자는 대통령령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 그 토지의 매수를 청구할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그에 해당하는 자(특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수를 포함한다. 이하 이 조에서 \"매수의무자\"라 한다)에게 그 토지의 매수를 청구할 수 있다.\n② 매수의무자는 제1항에 따라 매수 청구를 받은 토지를 매수할 때에는 현금으로 그 대금을 지급한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우로서 매수의무자가 지방자치단체인 경우에는 채권(이하 \"도시ㆍ군계획시설채권\"이라 한다)을 발행하여 지급할 수 있다.\n⑥ 매수의무자는 제1항에 따른 매수 청구를 받은 날부터 6개월 이내에 매수 여부를 결정하여 토지 소유자와 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수(매수의무자가 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수인 경우는 제외한다)에게 알려야 하며, 매수하기로 결정한 토지는 매수 결정을 알린 날부터 2년 이내에 매수하여야 한다.\n⑦ 제1항에 따라 매수 청구를 한 토지의 소유자는 다음 각 호의 어느 하나에 해당하는 경우 제56조에 따른 허가를 받아 대통령령으로 정하는 건축물 또는 공작물을 설치할 수 있다. 이 경우 제54조, 제58조와 제64조는 적용하지 아니한다.\n1. 제6항에 따라 매수하지 아니하기로 결정한 경우"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제41조제5항","원문":"⑤법 제47조제7항 각 호 외의 부분 전단에서 \"대통령령으로 정하는 건축물 또는 공작물\"이란 다음 각 호의 것을 말한다. 다만, 다음 각 호에 규정된 범위에서 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 도시ㆍ군계획조례로 따로 허용범위를 정하는 경우에는 그에 따른다.\n1. 「건축법 시행령」 별표 1 제1호 가목의 단독주택으로서 3층 이하인 것\n2. 「건축법 시행령」 별표 1 제3호의 제1종근린생활시설로서 3층 이하인 것\n3. 공작물"}],"선지":[{"번호":1,"판정":"틀림","설명":"매수청구는 시설결정 고시일부터 10년 이내에 사업이 시행되지 않을 때 가능하다. 20년은 시설결정이 실효되는 기간이다(법 제47조제1항, 제48조제1항)."},{"번호":2,"판정":"틀림","설명":"매수청구 대상은 지목이 대인 토지이며 그 토지에 있는 건축물과 정착물을 포함한다(법 제47조제1항)."},{"번호":3,"판정":"틀림","설명":"매수대금은 현금 지급이 원칙이다. 지방자치단체가 소유자의 요청이 있거나 부재부동산·비업무용 토지의 3천만원 초과분일 때 채권으로 지급할 수 있을 뿐이다(법 제47조제2항, 영 제41조제4항)."},{"번호":4,"판정":"틀림","설명":"매수하기로 결정한 토지는 결정을 알린 날부터 2년 이내에 매수한다(법 제47조제6항)."},{"번호":5,"판정":"옳음","설명":"매수하지 아니하기로 결정하면 법 제56조의 허가를 받아 3층 이하의 제1종 근린생활시설 등을 설치할 수 있다(법 제47조제7항제1호, 영 제41조제5항제2호)."}],"개념":[{"종류":"표","제목":"시설결정 고시 후 경과 기간별 제도","머리":["시점·단계","제도","내용"],"행":[["고시일부터 10년 이내 미시행","매수청구(법 제47조)","지목이 대인 토지(건축물·정착물 포함) 소유자가 청구. 실시계획 인가 절차가 진행된 경우 제외"],["청구를 받은 날부터 6개월","매수 여부 결정","소유자와 매수의무자가 아닌 시장·군수 등에게 통지(제47조⑥)"],["매수 결정을 알린 날부터 2년","매수","2년 안에 매수하지 않으면 건축·공작물 설치 허가 가능(제47조⑦2호)"],["고시일부터 20년","시설결정 실효","20년이 되는 날의 다음날 효력 상실(제48조①)"]]},{"종류":"흐름","제목":"매수청구 절차","단계":[{"이름":"매수청구","설명":"매수의무자에게 청구서와 등기사항증명서 제출(영 제41조①)"},{"이름":"매수 여부 결정","설명":"청구를 받은 날부터 6개월 이내 결정하여 통지(법 제47조⑥)"},{"이름":"매수 또는 불매수","설명":"매수하기로 하면 알린 날부터 2년 내 매수. 불매수 결정이면 허가받아 3층 이하 단독주택·제1종 근생 등 설치(법 제47조⑦, 영 제41조⑤)"},{"이름":"대금 지급","설명":"현금 원칙. 지방자치단체는 소유자 요청 등이면 채권으로, 상환기간은 10년 이내(법 제47조②③)"}]}],"함정":"10년(매수청구)과 20년(실효)을 바꿔 읽거나, 매수 결정 뒤 2년을 1년으로 줄여 놓은 선지에 속기 쉽다. 채권 지급은 예외 규정이라 반드시 채권으로 준다는 선지는 틀리다."}},{"i":"S4-2-1-공법-09","r":"S4","g":2,"c":2,"n":49,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 공동구가 설치 된 경우 공동구에 수용하기 위하여 공동구협의회의 심의를 거쳐야 하는 시설은?","b":"ㄱ. 열수송관\nㄴ. 하수도관\nㄷ. 가스관\nㄹ. 쓰레기수송관\nㅁ. 중수도관","bs":"글자","img":[],"ch":["ㄹ","ㄴ, ㄷ","ㄱ, ㄹ, ㅁ","ㄱ, ㄴ, ㄷ, ㅁ","ㄱ, ㄴ, ㄷ, ㄹ, ㅁ"],"a":[2],"L":"공1-5","o":"기출","x":{"한줄":"가스관과 하수도관은 공동구협의회의 심의를 거쳐 수용할 수 있는 시설이고, 나머지는 반드시 수용해야 하는 시설이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제35조의3","원문":"공동구가 설치된 경우에는 법 제44조제3항에 따라 제1호부터 제6호까지의 시설을 공동구에 수용하여야 하며, 제7호 및 제8호의 시설은 법 제44조의2제4항에 따른 공동구협의회의 심의를 거쳐 수용할 수 있다. 1. 전선로\n2. 통신선로\n3. 수도관\n4. 열수송관\n5. 중수도관\n6. 쓰레기수송관\n7. 가스관\n8. 하수도관, 그 밖의 시설"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제44조제3항","원문":"③ 공동구가 설치된 경우에는 대통령령으로 정하는 바에 따라 공동구에 수용하여야 할 시설이 모두 수용되도록 하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄹ(쓰레기수송관)은 반드시 수용해야 하는 시설이다. 협의회 심의 대상이 아니다."},{"번호":2,"판정":"-","설명":"ㄴ(하수도관)과 ㄷ(가스관)이 협의회 심의를 거쳐 수용하는 시설이다(영 제35조의3 제7호·제8호)."},{"번호":3,"판정":"-","설명":"ㄱ(열수송관), ㄹ(쓰레기수송관), ㅁ(중수도관)은 모두 의무 수용 시설이다."},{"번호":4,"판정":"-","설명":"ㄱ(열수송관)과 ㅁ(중수도관)은 의무 수용 시설이므로 심의 대상에 넣을 수 없다."},{"번호":5,"판정":"-","설명":"다섯 시설 가운데 심의 대상은 가스관과 하수도관 둘뿐이다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"열수송관은 의무 수용 시설이다(영 제35조의3 제4호)."},{"기호":"ㄴ","판정":"옳음","설명":"하수도관은 공동구협의회 심의를 거쳐 수용한다(영 제35조의3 제8호)."},{"기호":"ㄷ","판정":"옳음","설명":"가스관은 공동구협의회 심의를 거쳐 수용한다(영 제35조의3 제7호)."},{"기호":"ㄹ","판정":"틀림","설명":"쓰레기수송관은 의무 수용 시설이다(영 제35조의3 제6호)."},{"기호":"ㅁ","판정":"틀림","설명":"중수도관은 의무 수용 시설이다(영 제35조의3 제5호)."}],"개념":[{"종류":"표","제목":"공동구 수용 시설(영 제35조의3)","머리":["구분","시설"],"행":[["반드시 수용(제1호~제6호)","전선로, 통신선로, 수도관, 열수송관, 중수도관, 쓰레기수송관"],["공동구협의회 심의를 거쳐 수용(제7호·제8호)","가스관, 하수도관, 그 밖의 시설"],["수용 의무의 근거","공동구가 설치된 경우 수용할 시설이 모두 수용되도록 한다(법 제44조③)"]]},{"종류":"표","제목":"공동구 설치(법 제44조, 영 제35조의2)","머리":["항목","내용"],"행":[["설치 의무자","개발사업을 시행하는 사업시행자"],["대상 지역","도시개발구역, 택지개발지구, 경제자유구역, 정비구역, 공공주택지구, 도청이전신도시"],["규모","200만㎡ 초과(영 제35조의2①)"],["비용 부담","공동구 점용예정자와 사업시행자(법 제44조⑤)"],["점용예정자 부담액","해당 시설을 개별적으로 매설할 때 필요한 비용(영 제38조②)"]]}],"함정":"가스관을 전선·수도관 같은 기반 설비로 보고 의무 수용으로 고르기 쉽다. 의무 수용 목록은 전선로, 통신선로, 수도관, 열수송관, 중수도관, 쓰레기수송관이고, 가스관과 하수도관은 협의회 심의 대상이다."}},{"i":"S4-2-1-공법-10","r":"S4","g":2,"c":2,"n":50,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 성장관리계획구역에서 30퍼센트 이하의 범위에서 성장관리계획으로 정하는 바에 따라 건폐율을 완화하여 적용할 수 있는 지역이 아닌 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["생산관리지역","생산녹지지역","보전녹지지역","자연녹지지역","농림지역"],"a":[3],"L":"공1-7","o":"기출","x":{"한줄":"건폐율을 30퍼센트 이하까지 완화할 수 있는 지역은 생산관리지역, 농림지역, 생산녹지지역, 자연녹지지역이다. 보전녹지지역은 해당하지 않는다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제75조의3제2항·제3항","원문":"② 성장관리계획구역에서는 제77조제1항에도 불구하고 다음 각 호의 구분에 따른 범위에서 성장관리계획으로 정하는 바에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정하는 비율까지 건폐율을 완화하여 적용할 수 있다.\n1. 계획관리지역: 50퍼센트 이하\n2. 생산관리지역ㆍ농림지역 및 대통령령으로 정하는 녹지지역: 30퍼센트 이하\n③ 성장관리계획구역 내 계획관리지역에서는 제78조제1항에도 불구하고 125퍼센트 이하의 범위에서 성장관리계획으로 정하는 바에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정하는 비율까지 용적률을 완화하여 적용할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제70조의14제2항","원문":"② 법 제75조의3제2항제2호에서 \"대통령령으로 정하는 녹지지역\"이란 자연녹지지역과 생산녹지지역을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"생산관리지역은 30퍼센트 이하로 완화할 수 있는 지역이다(법 제75조의3제2항제2호)."},{"번호":2,"판정":"-","설명":"생산녹지지역은 영 제70조의14제2항이 정한 녹지지역이어서 30퍼센트 이하 완화가 가능하다."},{"번호":3,"판정":"-","설명":"보전녹지지역은 완화 대상 녹지지역(자연녹지·생산녹지)에 들지 않는다. 정답이다."},{"번호":4,"판정":"-","설명":"자연녹지지역은 영 제70조의14제2항의 대상 녹지지역이다."},{"번호":5,"판정":"-","설명":"농림지역은 30퍼센트 이하 완화 지역이다(법 제75조의3제2항제2호)."}],"개념":[{"종류":"표","제목":"성장관리계획구역의 건폐율·용적률 완화(법 제75조의3)","머리":["용도지역","건폐율 완화 한도","용적률"],"행":[["계획관리지역","50% 이하","125% 이하까지 완화 가능(제75조의3③)"],["생산관리지역","30% 이하","해당 없음"],["농림지역","30% 이하","해당 없음"],["자연녹지지역·생산녹지지역","30% 이하(영 제70조의14②)","해당 없음"],["보전녹지지역","완화 대상 아님","해당 없음"]]},{"종류":"흐름","제목":"성장관리계획구역 지정 절차","단계":[{"이름":"지정 대상","설명":"녹지지역, 관리지역, 농림지역, 자연환경보전지역 중 개발수요가 많은 지역 등(법 제75조의2①)"},{"이름":"주민·의회 의견","설명":"공고 후 14일 이상 열람, 지방의회 의견은 60일 이내(영 제70조의13, 법 제75조의2③)"},{"이름":"협의·심의","설명":"관계 행정기관 협의(30일 이내 의견) 및 지방도시계획위원회 심의(법 제75조의2②④)"},{"이름":"고시·열람","설명":"고시하고 관계 행정기관에 서류 송부(법 제75조의2⑤)"},{"이름":"재검토","설명":"수립된 성장관리계획을 5년마다 재검토(법 제75조의3⑤)"}]}],"함정":"녹지지역이면 모두 포함된다고 생각하기 쉽다. 대통령령이 자연녹지와 생산녹지만 지정했고 보전녹지는 빠져 있다."}},{"i":"S4-2-1-공법-11","r":"S4","g":2,"c":2,"n":51,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군계획시설사업 시행을 위한 타인의 토지에의 출입 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["타인의 토지에 출입하려는 행정청인 사업시행자는 출입하려는 날의 7일 전까지 그 토지의 소유자ㆍ점유자 또는 관리인에게 그 일시와 장소를 알려야 한다.","토지의 소유자ㆍ점유자 또는 관리인의 동의 없이 타인의 토지를 재료 적치장 또는 임시통로로 일시 사용한 사업시행자는 사용한 날부터 14일 이내에 시장 또는 군수의 허가를 받아야 한다.","토지 점유자가 승낙하지 않는 경우에도 사업시행자는 시장 또는 군수의 허가를 받아 일몰 후에 울타리로 둘러싸인 타인의 토지에 출입할 수 있다.","토지에의 출입에 따라 손실을 입은 자가 보상에 관하여 국토교통부장관에게 조정을 신청하지 아니하는 경우에는 관할 토지수용위원회에 재결을 신청할 수 없다.","사업시행자가 행정청인 경우라도 허가를 받지 아니하면 타인의 토지에 출입할 수 없다."],"a":[1],"L":"공1-8","o":"기출","x":{"한줄":"행정청인 시행자도 타인의 토지에 출입하려는 날의 7일 전까지 소유자·점유자·관리인에게 일시와 장소를 알려야 한다. 면제되는 것은 허가이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제130조제2항~제6항","원문":"② 제1항에 따라 타인의 토지에 출입하려는 자는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아야 하며, 출입하려는 날의 7일 전까지 그 토지의 소유자ㆍ점유자 또는 관리인에게 그 일시와 장소를 알려야 한다. 다만, 행정청인 도시ㆍ군계획시설사업의 시행자는 허가를 받지 아니하고 타인의 토지에 출입할 수 있다.\n③ 제1항에 따라 타인의 토지를 재료 적치장 또는 임시통로로 일시사용하거나 나무, 흙, 돌,  그 밖의 장애물을 변경 또는 제거하려는 자는 토지의 소유자 ㆍ점유자 또는 관리인의 동의를 받아야 한다.\n④ 제3항의 경우 토지나 장애물의 소유자ㆍ점유자 또는 관리인이 현장에 없거나 주소 또는 거소가 불분명하여 그 동의를 받을 수 없는 경우에는 행정청인 도시ㆍ군계획시설사업의 시행자는 관할 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 그 사실을 통지하여야 하며, 행정청이 아닌 도시ㆍ군계획시설사업의 시행자는 미리 관할 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아야 한다.\n⑤ 제3항과 제4항에 따라 토지를 일시 사용하거나 장애물을 변경 또는 제거하려는 자는 토지를 사용하려는 날이나 장애물을 변경 또는 제거하려는 날의 3일 전까지 그 토지나 장애물의 소유자ㆍ점유자 또는 관리인에게 알려야 한다.\n⑥ 일출 전이나 일몰 후에는 그 토지 점유자의 승낙 없이 택지나 담장 또는 울타리로 둘러싸인 타인의 토지에 출입할 수 없다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제131조제2항·제3항","원문":"② 제1항에 따른 손실 보상에 관하여는 그 손실을 보상할 자와 손실을 입은 자가 협의하여야 한다.\n③ 손실을 보상할 자나 손실을 입은 자는 제2항에 따른 협의가 성립되지 아니하거나 협의를 할 수 없는 경우에는 관할 토지수용위원회에 재결을 신청할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"행정청인 도시·군계획시설사업 시행자는 허가를 받지 않을 뿐 출입 7일 전 통지 의무는 그대로다(법 제130조제2항)."},{"번호":2,"판정":"틀림","설명":"동의 없이 일시 사용하는 경우 행정청이 아닌 시행자는 미리 허가를 받아야 하고, 행정청인 시행자는 시장·군수에게 통지한다. 사용한 날부터 14일 이내라는 기한은 없다(법 제130조제4항)."},{"번호":3,"판정":"틀림","설명":"일출 전이나 일몰 후에는 점유자의 승낙 없이 택지나 담장·울타리로 둘러싸인 타인의 토지에 출입할 수 없다. 허가가 있어도 같다(법 제130조제6항)."},{"번호":4,"판정":"틀림","설명":"손실보상 협의가 성립하지 않거나 협의할 수 없으면 관할 토지수용위원회에 재결을 신청할 수 있다. 국토교통부장관 조정을 먼저 거치는 규정은 없다(법 제131조제3항)."},{"번호":5,"판정":"틀림","설명":"행정청인 도시·군계획시설사업 시행자는 허가 없이 출입할 수 있다(법 제130조제2항 단서)."}],"개념":[{"종류":"표","제목":"타인 토지 출입·일시 사용(법 제130조)","머리":["항목","내용"],"행":[["허가","특별시장·광역시장·특별자치시장·특별자치도지사·시장 또는 군수의 허가. 행정청인 시행자는 불요(제130조②)"],["출입 통지","출입하려는 날의 7일 전까지 소유자·점유자·관리인에게 일시와 장소 통지(제130조②)"],["재료 적치장·임시통로 일시 사용, 장애물 변경·제거","소유자·점유자·관리인의 동의(제130조③)"],["동의를 받을 수 없을 때","행정청인 시행자는 시장·군수에게 통지, 행정청이 아닌 시행자는 미리 허가(제130조④)"],["일시 사용 통지","사용하려는 날 3일 전까지(제130조⑤)"],["시간 제한","일출 전·일몰 후 택지·울타리 안은 점유자 승낙 필요(제130조⑥)"]]},{"종류":"흐름","제목":"출입에 따른 손실보상(법 제131조)","단계":[{"이름":"손실 발생","설명":"출입·일시 사용·장애물 제거로 손실을 입은 자(제131조①)"},{"이름":"협의","설명":"보상할 자와 손실을 입은 자가 협의(제131조②)"},{"이름":"재결 신청","설명":"협의가 안 되거나 할 수 없으면 관할 토지수용위원회에 신청(제131조③)"},{"이름":"준용","설명":"재결에는 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제83조~제87조 준용(제131조④)"}]}],"함정":"행정청은 허가를 받지 않는다는 규정을 통지까지 면제된다고 넓혀 읽기 쉽다. 면제 대상은 허가뿐이다."}},{"i":"S4-2-1-공법-12","r":"S4","g":2,"c":2,"n":52,"s":"공법","q":"도시개발법령상 도시개발구역의 지정에 관한 설명으로 옳은 것은? (단, 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["인구 50만 미만인 시의 시장은 직접 도시개발구역을 지정할 수 있다.","도시지역 중 공업지역에서 도시개발구역을 지정하려면 면적이 1만 제곱미터 이상이어야 한다.","국토교통부장관은 관계 중앙행정기관의 장이 요청하는 경우 도시개발구역을 지정할 수 있다.","도시개발사업이 필요하다고 인정되는 지역이 둘 이상의 시ㆍ도에 걸치고 관계 시ㆍ도지사 간 협의가 성립되지 아니하면, 면적이 더 넓은 시ㆍ도의 시ㆍ도지사가 도시개발구역을 지정한다.","도시지역 외의 지역에서 도시개발구역의 면적은 30만 제곱미터 이상이어야 하고, 아파트 건설계획이 포함되더라도 이 기준은 완화되지 아니한다."],"a":[3],"L":"공2-1","o":"변형","x":{"한줄":"관계 중앙행정기관의 장이 요청하면 국토교통부장관은 시ㆍ도지사나 대도시 시장 대신 도시개발구역을 지정할 수 있다.","근거":[{"법령":"도시개발법","조문":"법 제3조제1항·제3항","원문":"① 다음 각 호의 어느 하나에 해당하는 자는 계획적인 도시개발이 필요하다고 인정되는 때에는 도시개발구역을 지정할 수 있다.\n1. 특별시장ㆍ통합특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)\n2. 「지방자치법」 제198조제1항에 따른 인구 50만 이상 대도시의 시장(이하 \"대도시 시장\"이라 한다)\n③ 국토교통부장관은 다음 각 호의 어느 하나에 해당하면 제1항과 제2항에도 불구하고 도시개발구역을 지정할 수 있다.\n2. 관계 중앙행정기관의 장이 요청하는 경우\n4. 제2항에 따른 협의가 성립되지 아니하는 경우\n④ 시장(대도시 시장은 제외한다)ㆍ군수 또는 구청장(자치구의 구청장을 말한다. 이하 같다)은 대통령령으로 정하는 바에 따라 시ㆍ도지사에게 도시개발구역의 지정을 요청할 수 있다."},{"법령":"도시개발법 시행령","조문":"영 제2조제1항","원문":"① 「도시개발법」(이하 \"법\"이라 한다) 제3조에 따라 도시개발구역으로 지정할 수 있는 대상 지역 및 규모는 다음과 같다.\n1. 도시지역\n나. 공업지역: 3만 제곱미터 이상\n2. 도시지역 외의 지역: 30만 제곱미터 이상. 다만, 「건축법 시행령」 별표 1 제2호의 공동주택 중 아파트 또는 연립주택의 건설계획이 포함되는 경우로서 다음 요건을 모두 갖춘 경우에는 10만제곱미터 이상으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대도시(인구 50만 이상)가 아닌 시의 시장·군수·구청장은 시·도지사에게 도시개발구역 지정을 요청한다(법 제3조제4항)."},{"번호":2,"판정":"틀림","설명":"공업지역은 3만 제곱미터 이상이다. 1만 제곱미터 이상은 주거지역·상업지역·자연녹지지역이다(영 제2조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"관계 중앙행정기관의 장이 요청하는 경우는 국토교통부장관의 지정 사유이다(법 제3조제3항제2호)."},{"번호":4,"판정":"틀림","설명":"협의가 성립되지 않으면 국토교통부장관이 지정할 수 있다. 면적이 더 넓은 쪽 시·도지사라는 규정은 없다(법 제3조제3항제4호)."},{"번호":5,"판정":"틀림","설명":"도시지역 외의 지역은 30만 제곱미터 이상이다. 다만 아파트 또는 연립주택 건설계획이 포함되고 초등학교용지 확보와 도로 요건을 갖추면 10만 제곱미터 이상으로 완화된다(영 제2조제1항제2호)."}],"개념":[{"종류":"표","제목":"도시개발구역 지정권자(법 제3조)","머리":["구분","지정권자"],"행":[["원칙","시·도지사, 대도시 시장(제3조①)"],["둘 이상의 시·도 또는 대도시에 걸침","관계 시·도지사·대도시 시장이 협의하여 지정할 자를 정함(제3조②)"],["국토교통부장관이 지정하는 경우","국가가 사업을 실시할 필요, 관계 중앙행정기관의 장 요청, 공공기관·정부출연기관의 제안, 협의 불성립, 천재지변 등 긴급 사유(제3조③, 영 제4조)"],["시장(대도시 제외)·군수·구청장","시·도지사에게 지정을 요청(제3조④)"]]},{"종류":"표","제목":"도시개발구역 지정 규모(영 제2조)","머리":["지역","규모"],"행":[["주거지역·상업지역","1만㎡ 이상"],["공업지역","3만㎡ 이상"],["자연녹지지역","1만㎡ 이상"],["생산녹지지역","1만㎡ 이상(생산녹지가 지정면적의 30% 이하일 때만)"],["도시지역 외의 지역","30만㎡ 이상. 아파트·연립주택 계획이 있고 초등학교용지와 도로 요건을 갖추면 10만㎡ 이상"]]}],"함정":"구역 지정 규모를 용도지역별로 섞어 외우다 공업지역을 1만㎡로 잘못 적기 쉽다. 협의가 안 되면 면적이 큰 쪽이 지정한다는 식의 규정은 없고 국토교통부장관 몫이다."}},{"i":"S4-2-1-공법-13","r":"S4","g":2,"c":2,"n":53,"s":"공법","q":"도시개발법령상 도시개발구역 지정권자가 시행자를 변경할 수 있는 경우가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["행정처분으로 시행자의 지정이 취소된 경우","시행자의 부도로 도시개발사업의 목적을 달성하기 어렵다고 인정되는 경우","도시개발구역 전부를 환지 방식으로 시행하여 토지 소유자가 시행자로 지정되었으나, 도시개발구역 지정의 고시일부터 1년(연장 없음) 이내에 실시계획의 인가를 신청하지 아니하는 경우","도시개발사업에 관한 실시계획의 인가를 받은 후 1년 6개월이 지나도록 사업에 착수하지 아니하는 경우","행정처분으로 실시계획의 인가가 취소된 경우"],"a":[4],"L":"공2-2","o":"변형","x":{"한줄":"법은 실시계획 인가 후 2년 이내에 착수하지 않는 경우를 시행자 변경 사유로 정하므로 1년 6개월 경과는 사유가 아니다.","근거":[{"법령":"도시개발법","조문":"법 제11조제8항","원문":"⑧ 지정권자는 다음 각 호의 어느 하나에 해당하는 경우에는 시행자를 변경할 수 있다.\n1. 도시개발사업에 관한 실시계획의 인가를 받은 후 2년 이내에 사업을 착수하지 아니하는 경우\n2. 행정처분으로 시행자의 지정이나 실시계획의 인가가 취소된 경우\n3. 시행자의 부도ㆍ파산, 그 밖에 이와 유사한 사유로 도시개발사업의 목적을 달성하기 어렵다고 인정되는 경우\n4. 제1항 단서에 따라 시행자로 지정된 자가 대통령령으로 정하는 기간에 도시개발사업에 관한 실시계획의 인가를 신청하지 아니하는 경우"},{"법령":"도시개발법 시행령","조문":"영 제24조","원문":"법 제11조제8항제4호에서 \"대통령령으로 정하는 기간\"이란 법 제9조제1항에 따른 도시개발구역 지정의 고시일부터 1년 이내를 말한다. 다만, 지정권자가 실시계획의 인가신청기간의 연장이 불가피하다고 인정하여 6개월의 범위에서 연장한 경우에는 그 연장된 기간을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"시행자 지정이나 실시계획 인가가 행정처분으로 취소되면 변경 사유이다(법 제11조제8항제2호)."},{"번호":2,"판정":"-","설명":"부도·파산 등으로 사업 목적 달성이 어려우면 변경 사유이다(법 제11조제8항제3호)."},{"번호":3,"판정":"-","설명":"제1항 단서에 따라 지정된 시행자가 지정 고시일부터 1년 안에 실시계획 인가를 신청하지 않으면 변경 사유이다(법 제11조제8항제4호, 영 제24조)."},{"번호":4,"판정":"-","설명":"착수 기한은 인가 후 2년이다. 1년 6개월 경과는 사유에 해당하지 않아 정답이다(법 제11조제8항제1호)."},{"번호":5,"판정":"-","설명":"행정처분으로 실시계획 인가가 취소된 경우는 변경 사유이다(법 제11조제8항제2호)."}],"개념":[{"종류":"표","제목":"시행자 변경 사유(법 제11조제8항)","머리":["호","사유","수치"],"행":[["1호","실시계획 인가를 받은 후 사업에 착수하지 않음","인가 후 2년 이내"],["2호","행정처분으로 시행자 지정 또는 실시계획 인가가 취소됨","-"],["3호","부도·파산 등으로 사업 목적 달성이 어려움","-"],["4호","제1항 단서로 지정된 시행자가 실시계획 인가를 신청하지 않음","구역 지정 고시일부터 1년(6개월 범위에서 연장 가능)"]]},{"종류":"표","제목":"시행자 지정 관련 기간(영)","머리":["구분","기간"],"행":[["토지 소유자·조합의 시행자 지정 신청(미신청 시 지방자치단체등을 시행자로 지정 가능)","개발계획 수립·고시일부터 1년(6개월 연장 가능, 영 제20조②)"],["환지방식 시행자의 실시계획 인가 신청","구역 지정 고시일부터 1년(6개월 연장 가능, 영 제24조)"],["공통","지정권자가 연장이 불가피하다고 인정하면 6개월 범위에서 연장"]]}],"함정":"착수 기한 2년과 인가 신청 기한 1년이 같이 나온다. 인가 뒤 착수 기한을 1년 6개월로 줄여 놓으면 사유에서 빠진다."}},{"i":"S4-2-1-공법-14","r":"S4","g":2,"c":2,"n":54,"s":"공법","q":"도시개발법령상 도시개발조합 총회의 의결사항 중 대의원회가 총회의 권한을 대행할 수 있는 사항은?","b":null,"bs":"없음","img":[],"ch":["개발계획의 수립","정관의 변경","환지계획의 작성","조합임원의 선임","자금의 차입과 그 방법ㆍ이율 및 상환방법"],"a":[5],"L":"공2-2","o":"변형","x":{"한줄":"대의원회는 정관 변경, 개발계획 수립, 환지계획 작성, 조합임원 선임, 합병·해산을 뺀 총회 권한을 대행하므로 자금 차입의 방법·이율·상환방법은 대행 대상이다.","근거":[{"법령":"도시개발법 시행령","조문":"영 제35조","원문":"1. 정관의 변경\n2. 개발계획 및 실시계획의 수립 및 변경\n3. 자금의 차입과 그 방법ㆍ이율 및 상환방법\n6. 환지계획의 작성\n9. 조합임원의 선임\n10. 조합의 합병 또는 해산에 관한 사항. 다만, 법 제46조에 따른 청산금의 징수ㆍ교부를 완료한 후에 조합을 해산하는 경우는 제외한다."},{"법령":"도시개발법 시행령","조문":"영 제36조제3항","원문":"③ 대의원회는 제35조에 따른 총회의 의결사항 중 같은 조 제1호ㆍ제2호(제7조에 따른 사항과 관련된 개발계획의 경미한 변경 및 법 제17조제1항에 따른 실시계획(이하 \"실시계획\"이라 한다)의 수립ㆍ변경은 제외한다)ㆍ제6호(제60조제1항 각 호에서 정하는 환지계획의 경미한 변경은 제외한다)ㆍ제9호 및 제10호의 사항을 제외한 총회의 권한을 대행할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"개발계획의 수립은 총회 의결사항(영 제35조제2호)이며 대의원회는 대행하지 못한다. 대행되는 것은 개발계획의 경미한 변경과 실시계획의 수립·변경이다(영 제36조제3항)."},{"번호":2,"판정":"-","설명":"정관의 변경(영 제35조제1호)은 대의원회가 대행할 수 없다."},{"번호":3,"판정":"-","설명":"환지계획의 작성(영 제35조제6호)은 경미한 변경만 대행할 수 있고 작성 자체는 총회가 한다."},{"번호":4,"판정":"-","설명":"조합임원의 선임(영 제35조제9호)은 대행할 수 없다."},{"번호":5,"판정":"-","설명":"자금의 차입과 그 방법·이율·상환방법(영 제35조제3호)은 제외 목록에 없으므로 대의원회가 대행할 수 있다."}],"개념":[{"종류":"표","제목":"대의원회의 총회 권한 대행(영 제36조제3항)","머리":["총회 의결사항(영 제35조)","대의원회 대행"],"행":[["1호 정관의 변경","불가"],["2호 개발계획·실시계획의 수립·변경","불가. 다만 개발계획의 경미한 변경과 실시계획의 수립·변경은 가능"],["3호 자금의 차입과 그 방법·이율·상환방법","가능"],["4호 수지예산, 5호 부과금의 금액·징수방법","가능"],["6호 환지계획의 작성","불가. 환지계획의 경미한 변경은 가능"],["7호 환지예정지의 지정, 8호 체비지 등의 처분방법","가능"],["9호 조합임원의 선임, 10호 조합의 합병 또는 해산","불가"]]},{"종류":"표","제목":"조합과 대의원회 수치","머리":["항목","내용"],"행":[["조합 설립인가 신청","토지 소유자 7명 이상이 정관을 작성(법 제13조①)"],["설립인가 동의","토지면적 3분의 2 이상 소유자 + 토지 소유자 총수 2분의 1 이상(법 제13조③)"],["대의원회를 둘 수 있는 조합","의결권을 가진 조합원 50인 이상(영 제36조①)"],["대의원 수","의결권을 가진 조합원 총수의 100분의 10 이상(영 제36조②)"]]}],"함정":"대행 불가 목록은 정관 변경, 개발계획, 환지계획 작성, 임원 선임, 합병·해산이다. 환지예정지 지정과 자금 차입은 대행 가능 쪽에 있다."}},{"i":"S4-2-1-공법-15","r":"S4","g":2,"c":2,"n":55,"s":"공법","q":"도시개발법령상 원형지의 공급과 개발에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["원형지를 공장 부지로 직접 사용하는 원형지개발자의 선정은 경쟁입찰의 방식으로 하며, 경쟁입찰이 2회 이상 유찰된 경우에는 수의계약의 방법으로 할 수 있다.","지정권자는 원형지의 공급을 승인할 때 용적률 등 개발밀도에 관한 이행조건을 붙일 수 없다.","원형지 공급가격은 원형지의 감정가격과 원형지에 설치한 기반시설 공사비의 합산 금액을 기준으로 시ㆍ도의 조례로 정한다.","원형지개발자인 지방자치단체는 10년의 범위에서 대통령령으로 정하는 기간 안에는 원형지를 매각할 수 없다.","원형지개발자가 공급받은 토지의 전부를 시행자의 동의 없이 제3자에게 매각하는 경우 시행자는 원형지개발자에 대한 시정요구 없이 원형지 공급계약을 해제할 수 있다."],"a":[1],"L":"공2-3","o":"기출","x":{"한줄":"원형지를 공장 부지로 직접 사용하는 자는 경쟁입찰로 선정하고, 2회 이상 유찰되면 수의계약을 할 수 있다.","근거":[{"법령":"도시개발법 시행령","조문":"영 제55조의2제6항","원문":"⑥ 법 제25조의2제9항에 따른 원형지개발자의 선정은 수의계약의 방법으로 한다. 다만, 법 제25조의2제1항제5호에 해당하는 원형지개발자의 선정은 경쟁입찰의 방식으로 하며, 경쟁입찰이 2회 이상 유찰된 경우에는 수의계약의 방법으로 할 수 있다."},{"법령":"도시개발법","조문":"법 제25조의2제1항·제5항·제6항","원문":"① 시행자는 도시를 자연친화적으로 개발하거나 복합적ㆍ입체적으로 개발하기 위하여 필요한 경우에는 대통령령으로 정하는 절차에 따라 미리 지정권자의 승인을 받아 다음 각 호의 어느 하나에 해당하는 자에게 원형지를 공급하여 개발하게 할 수 있다. 이 경우 공급될 수 있는 원형지의 면적은 도시개발구역 전체 토지 면적의 3분의 1 이내로 한정한다.\n5. 원형지를 학교나 공장 등의 부지로 직접 사용하는 자\n⑤ 지정권자는 제1항에 따라 승인을 할 때에는 용적률 등 개발밀도, 토지용도별 면적 및 배치, 교통처리계획 및 기반시설의 설치 등에 관한 이행조건을 붙일 수 있다.\n⑥ 원형지개발자(국가 및 지방자치단체는 제외한다)는 10년의 범위에서 대통령령으로 정하는 기간 안에는 원형지를 매각할 수 없다. 다만, 이주용 주택이나 공공ㆍ문화 시설 등 대통령령으로 정하는 경우로서 미리 지정권자의 승인을 받은 경우에는 예외로 한다."},{"법령":"도시개발법 시행령","조문":"영 제55조의2제3항·제5항·제7항","원문":"③ 법 제25조의2제6항 본문에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 기간 중 먼저 끝나는 기간을 말한다.\n1. 원형지에 대한 공사완료 공고일부터 5년\n2. 원형지 공급 계약일부터 10년\n⑤ 시행자는 법 제25조의2제8항 각 호의 어느 하나에 해당하는 사유가 발생한 경우에 원형지개발자에게 2회 이상 시정을 요구하여야 하고, 원형지개발자가 시정하지 아니한 경우에는 원형지 공급계약을 해제할 수 있다. 이 경우 원형지개발자는 시행자의 시정 요구에 대하여 의견을 제시할 수 있다.\n⑦ 법 제25조의2제9항에 따른 원형지 공급가격은 개발계획이 반영된 원형지의 감정가격에 시행자가 원형지에 설치한 기반시설 등의 공사비를 더한 금액을 기준으로 시행자와 원형지개발자가 협의하여 결정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제25조의2제1항제5호의 원형지개발자는 경쟁입찰로 선정하고, 경쟁입찰이 2회 이상 유찰되면 수의계약이 가능하다(영 제55조의2제6항)."},{"번호":2,"판정":"틀림","설명":"지정권자는 승인할 때 용적률 등 개발밀도, 토지용도별 면적·배치, 교통처리계획, 기반시설 설치 등에 관한 이행조건을 붙일 수 있다(법 제25조의2제5항)."},{"번호":3,"판정":"틀림","설명":"공급가격은 감정가격에 기반시설 등 공사비를 더한 금액을 기준으로 시행자와 원형지개발자가 협의하여 결정한다. 시·도 조례로 정하지 않는다(영 제55조의2제7항)."},{"번호":4,"판정":"틀림","설명":"국가와 지방자치단체는 매각 제한 대상에서 제외된다. 제한 기간도 공사완료 공고일부터 5년과 공급 계약일부터 10년 중 먼저 끝나는 기간이다(법 제25조의2제6항, 영 제55조의2제3항)."},{"번호":5,"판정":"틀림","설명":"시행자는 2회 이상 시정을 요구하고 이행하지 않을 때 공급계약을 해제할 수 있다(영 제55조의2제5항)."}],"개념":[{"종류":"표","제목":"원형지 공급·개발(법 제25조의2, 영 제55조의2)","머리":["항목","내용"],"행":[["공급 상한","도시개발구역 전체 토지면적의 3분의 1 이내"],["공급 대상","국가·지방자치단체, 공공기관, 지방공사, 공모에서 선정된 자, 학교·공장 부지로 직접 사용하는 자"],["승인","지정권자의 승인. 개발밀도 등 이행조건을 붙일 수 있음"],["원형지개발자 선정","원칙 수의계약. 학교·공장 부지 직접 사용자는 경쟁입찰(2회 이상 유찰 시 수의계약)"],["공급가격","감정가격 + 시행자가 설치한 기반시설 등 공사비를 기준으로 협의"],["매각 제한","원형지개발자(국가·지방자치단체 제외)는 공사완료 공고일부터 5년, 계약일부터 10년 중 먼저 끝나는 기간 동안 매각 불가"],["계약 해제","착수 지연, 사업 지연, 동의 없는 매각 등. 2회 이상 시정요구 후(영 제55조의2⑤)"]]},{"종류":"흐름","제목":"원형지 공급 절차","단계":[{"이름":"승인 신청","설명":"시행자가 원형지 공급 승인신청서와 개발계획 등 서류 제출(영 제55조의2①)"},{"이름":"개발계획 수립·승인","설명":"지정권자가 개발계획을 수립한 뒤 원형지 공급 승인(영 제55조의2②)"},{"이름":"공급계약 체결","설명":"승인내용과 공급 계획에 따라 원형지개발자와 계약(법 제25조의2④)"},{"이름":"세부계획 제출","설명":"원형지개발자가 세부계획 제출. 시행자가 실시계획에 반영(법 제25조의2④)"},{"이름":"감독·해제","설명":"이행조건 불이행 시 승인 취소·시정 요구, 시행자는 계약 해제(법 제25조의2⑦⑧)"}]}],"함정":"경쟁입찰은 학교·공장 부지로 직접 사용하는 원형지개발자에게만 적용되고 나머지는 수의계약이다. 매각 제한은 국가와 지방자치단체를 뺀 원형지개발자에게 적용되며, 계약 해제 전에는 시정요구가 2회 이상 필요하다."}},{"i":"S4-2-1-공법-16","r":"S4","g":2,"c":2,"n":56,"s":"공법","q":"도시개발법령상 도시개발사업의 일부를 환지방식으로 시행하기 위하여 개발계획을 변경할 때 토지 소유자의 동의가 필요한 경우는? (단, 시행자는 한국토지주택공사이며, 다른 조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["너비가 11미터인 도로를 신설하는 경우","제외되는 토지의 면적이 종전 환지방식이 적용되는 면적의 100분의 8이고 1만 제곱미터인 경우","공원의 면적이 종전보다 100분의 5 증가하는 경우","수용예정인구가 종전보다 100분의 15 증가하여 2천3백명이 되는 경우","기반시설을 제외한 도시개발구역의 용적률이 종전보다 100분의 4 증가하는 경우"],"a":[3],"L":"공2-4","o":"변형","x":{"한줄":"도로를 제외한 기반시설 중 공원·녹지는 면적이 100분의 5 이상 증감하면 경미한 변경이 아니어서 동의가 필요하다.","근거":[{"법령":"도시개발법","조문":"법 제4조제4항·제5항","원문":"④ 지정권자는 환지(換地) 방식의 도시개발사업에 대한 개발계획을 수립하려면 환지 방식이 적용되는 지역의 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 그 지역의 토지 소유자 총수의 2분의 1 이상의 동의를 받아야 한다. 환지 방식으로 시행하기 위하여 개발계획을 변경(대통령령으로 정하는 경미한 사항의 변경은 제외한다)하려는 경우에도 또한 같다.\n⑤ 지정권자는 도시개발사업을 환지 방식으로 시행하려고 개발계획을 수립하거나 변경할 때에 도시개발사업의 시행자가 제11조제1항제1호에 해당하는 자이면 제4항에도 불구하고 토지 소유자의 동의를 받을 필요가 없다."},{"법령":"도시개발법 시행령","조문":"영 제7조제1항","원문":"① 법 제4조제4항 후단에서 \"대통령령으로 정하는 경미한 사항의 변경\"이란 개발계획을 변경하는 경우로서 다음 각 호에 해당하는 경우를 제외한 경우를 말한다.\n1. 환지방식을 적용하는 지역의 면적 변경이 다음 각 목의 어느 하나에 해당하는 경우\n나. 제외되는 토지의 면적이 종전 환지방식이 적용되는 면적의 100분의 10 이상인 경우\n다. 편입 또는 제외되는 면적이 각각 3만 제곱미터 이상인 경우\n라. 토지의 편입이나 제외로 인하여 환지방식이 적용되는 면적이 종전보다 100분의 10 이상 증감하는 경우\n2. 너비가 12미터 이상인 도로를 신설 또는 폐지하는 경우\n4. 도로를 제외한 기반시설(「국토의 계획 및 이용에 관한 법률 시행령」 제2조제1항 각 호의 기반시설을 말한다)의 면적이 종전보다 100분의 10(공원 또는 녹지의 경우에는 100분의 5) 이상으로 증감하거나 신설되는 기반시설의 총면적이 종전 기반시설 면적의 100분의 5 이상인 경우\n5. 수용예정인구가 종전보다 100분의 10 이상 증감하는 경우(변경 이후 수용예정인구가 3천명 미만인 경우는 제외한다)\n6. 기반시설을 제외한 도시개발구역의 용적률이 종전보다 100분의 5 이상 증가하는 경우"}],"선지":[{"번호":1,"판정":"-","설명":"12미터 이상 도로의 신설·폐지만 동의 대상이다. 11미터는 경미한 변경이다(영 제7조제1항제2호)."},{"번호":2,"판정":"-","설명":"제외 면적이 10퍼센트 미만(8퍼센트)이고 3만 제곱미터 미만(1만 제곱미터)이며 전체 증감도 10퍼센트 미만이라 경미한 변경이다(영 제7조제1항제1호나목·다목·라목)."},{"번호":3,"판정":"-","설명":"공원 또는 녹지의 면적이 종전보다 100분의 5 이상 증감하면 경미하지 않다. 동의가 필요하다(영 제7조제1항제4호)."},{"번호":4,"판정":"-","설명":"수용예정인구가 100분의 10 이상 증감해도 변경 후 3천명 미만이면 제외된다. 2천3백명이므로 경미하다(영 제7조제1항제5호)."},{"번호":5,"판정":"-","설명":"용적률은 100분의 5 이상 증가해야 동의 대상이다. 4퍼센트는 경미하다(영 제7조제1항제6호)."}],"개념":[{"종류":"표","제목":"개발계획 변경 중 동의가 필요한 경우(영 제7조제1항)","머리":["구분","동의가 필요한 기준"],"행":[["환지방식 적용 면적","편입 5% 이상, 제외 10% 이상, 편입·제외가 각각 3만㎡ 이상, 전체 증감 10% 이상"],["도로 신설·폐지","너비 12m 이상"],["사업시행지구 분할·통합","있으면 필요"],["도로 제외 기반시설","면적 10% 이상 증감(공원·녹지는 5%), 신설 기반시설 총면적이 종전의 5% 이상"],["수용예정인구","10% 이상 증감. 변경 후 3천명 미만이면 제외"],["용적률","기반시설 제외 용적률 5% 이상 증가"]]},{"종류":"표","제목":"환지방식 개발계획의 동의 요건(법 제4조)","머리":["경우","동의"],"행":[["수립·변경(경미한 변경 제외)","환지방식 적용 지역 토지면적의 3분의 2 이상 + 토지 소유자 총수의 2분의 1 이상(제4조④)"],["시행자가 국가·지방자치단체(제11조제1항제1호)","동의 불필요(제4조⑤)"],["조합이 성립된 뒤 총회에서 3분의 2 이상 조합원 + 2분의 1 이상 찬성으로 의결","동의를 받은 것으로 봄(제4조⑥)"],["한국토지주택공사(제11조제1항제2호)","동의 필요"]]}],"함정":"시행자가 공공기관이면 동의가 필요 없다고 생각하기 쉽다. 동의 면제는 국가와 지방자치단체뿐이고 한국토지주택공사는 제외된다. 수용예정인구는 변경 후 3천명 미만이면 경미한 변경이다."}},{"i":"S4-2-1-공법-17","r":"S4","g":2,"c":2,"n":57,"s":"공법","q":"도시개발법령상 환지 방식의 도시개발사업에 대한 개발계획 수립에 필요한 동의자의 수를 산정하는 방법으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도시개발구역의 토지면적을 산정하는 경우: 국공유지를 제외하고 산정할 것","1인이 둘 이상 필지의 토지를 단독으로 소유한 경우: 필지의 수에 관계없이 토지 소유자를 1인으로 볼 것","둘 이상 필지의 토지를 소유한 공유자가 동일한 경우: 공유자 각각을 토지 소유자 1인으로 볼 것","1필지의 토지 소유권을 여럿이 공유하는 경우: ｢집합건물의 소유 및 관리에 관한 법률｣에 따른 구분소유자인지 여부와 관계없이 다른 공유자의 동의를 받은 대표공유자 1인을 해당 토지 소유자로 볼 것","도시개발구역의 지정이 제안된 후부터 개발계획이 수립되기 전까지의 사이에 토지 소유자가 변경된 경우: 변경된 토지 소유자의 동의서를 기준으로 할 것"],"a":[2],"L":"공2-4","o":"기출","x":{"한줄":"1인이 둘 이상 필지의 토지를 단독으로 소유한 경우에는 필지 수와 관계없이 토지 소유자를 1인으로 본다.","근거":[{"법령":"도시개발법 시행령","조문":"영 제6조제4항","원문":"④ 법 제4조제4항에 따른 동의자의 수를 산정하는 방법은 다음 각 호와 같다.\n1. 도시개발구역의 토지면적을 산정하는 경우: 국공유지를 포함하여 산정할 것\n2. 1필지의 토지 소유권을 여럿이 공유하는 경우: 다른 공유자의 동의를 받은 대표 공유자 1인을 해당 토지 소유자로 볼 것. 다만, 「집합건물의 소유 및 관리에 관한 법률」 제2조제2호에 따른 구분소유자는 각각을 토지 소유자 1인으로 본다.\n2의2. 1인이 둘 이상 필지의 토지를 단독으로 소유한 경우: 필지의 수에 관계없이 토지 소유자를 1인으로 볼 것\n2의3. 둘 이상 필지의 토지를 소유한 공유자가 동일한 경우: 공유자 여럿을 대표하는 1인을 토지 소유자로 볼 것\n5. 법 제11조제5항에 따라 도시개발구역의 지정이 제안된 후부터 법 제4조에 따라 개발계획이 수립되기 전까지의 사이에 토지 소유자가 변경된 경우 또는 법 제4조제2항에 따라 개발계획의 변경을 요청받은 후부터 개발계획이 변경되기 전까지의 사이에 토지 소유자가 변경된 경우: 기존 토지 소유자의 동의서를 기준으로 할 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지면적을 산정할 때 국공유지를 포함한다(영 제6조제4항제1호)."},{"번호":2,"판정":"옳음","설명":"1인이 둘 이상 필지를 단독 소유하면 필지 수와 관계없이 1인으로 본다(영 제6조제4항제2호의2)."},{"번호":3,"판정":"틀림","설명":"둘 이상 필지를 소유한 공유자가 동일하면 공유자 여럿을 대표하는 1인을 토지 소유자로 본다. 공유자 각각이 아니다(영 제6조제4항제2호의3)."},{"번호":4,"판정":"틀림","설명":"1필지를 여럿이 공유하면 다른 공유자의 동의를 받은 대표공유자 1인을 소유자로 보되, 「집합건물의 소유 및 관리에 관한 법률」상 구분소유자는 각각 1인으로 본다(영 제6조제4항제2호)."},{"번호":5,"판정":"틀림","설명":"지정 제안 후 개발계획 수립 전에 소유자가 바뀌면 기존 토지 소유자의 동의서를 기준으로 한다(영 제6조제4항제5호)."}],"개념":[{"종류":"표","제목":"동의자 수 산정 방법(영 제6조제4항)","머리":["경우","산정"],"행":[["도시개발구역 토지면적","국공유지를 포함하여 산정"],["1필지를 여럿이 공유","다른 공유자 동의를 받은 대표공유자 1인. 구분소유자는 각각 1인"],["1인이 둘 이상 필지 단독 소유","필지 수와 관계없이 1인"],["동일한 공유자가 둘 이상 필지 소유","공유자 여럿을 대표하는 1인"],["공람·공고일 뒤 구분소유권 분할로 소유자 증가","공람·공고일 전 소유자 수 기준, 증가분은 총수에 넣지 않음"],["제안 전 동의 철회","동의자 수에서 제외"],["제안 후 개발계획 수립 전 소유자 변경","기존 토지 소유자의 동의서 기준"]]},{"종류":"표","제목":"동의 비율 모음","머리":["대상","비율"],"행":[["환지방식 개발계획 수립(법 제4조④)","토지면적 3분의 2 이상 + 토지 소유자 총수 2분의 1 이상"],["조합 설립인가(법 제13조③)","토지면적 3분의 2 이상 + 토지 소유자 총수 2분의 1 이상"],["구역 지정 제안(법 제11조⑥)","대상 구역 토지면적의 3분의 2 이상 토지 소유자 동의"],["지방자치단체등을 시행자로 지정(법 제11조②3호)","국공유지 제외 토지면적 2분의 1 이상 + 소유자 총수 2분의 1 이상"]]}],"함정":"동의자 수 산정은 선지마다 규칙 하나씩을 뒤집는다. 국공유지는 포함, 동일 공유자와 구분소유자는 각각의 규칙이 다르다."}},{"i":"S4-2-1-공법-18","r":"S4","g":2,"c":2,"n":58,"s":"공법","q":"도시 및 주거환경정비법령상 정비기반시설에 해당하지 않는 것은? (단, 주거환경개선사업을 위하여 지정ㆍ고시된 정비구역이 아님)","b":null,"bs":"없음","img":[],"ch":["소방용수시설","광장","지역난방시설","마을회관","구거"],"a":[4],"L":"공3-1","o":"변형","x":{"한줄":"마을회관은 공동이용시설이고 정비기반시설이 아니다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"법 제2조제4호·제5호","원문":"4. \"정비기반시설\"이란 도로ㆍ상하수도ㆍ구거(溝渠: 도랑)ㆍ공원ㆍ공용주차장ㆍ공동구(「국토의 계획 및 이용에 관한 법률」 제2조제9호에 따른 공동구를 말한다. 이하 같다), 그 밖에 주민의 생활에 필요한 열ㆍ가스 등의 공급시설로서 대통령령으로 정하는 시설을 말한다.\n5. \"공동이용시설\"이란 주민이 공동으로 사용하는 놀이터ㆍ마을회관ㆍ공동작업장, 그 밖에 대통령령으로 정하는 시설을 말한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"영 제3조","원문":"법 제2조제4호에서 \"대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다.\n1. 녹지\n2. 하천\n3. 공공공지\n4. 광장\n5. 소방용수시설\n6. 비상대피시설\n7. 가스공급시설\n8. 지역난방시설\n9. 주거환경개선사업을 위하여 지정ㆍ고시된 정비구역에 설치하는 공동이용시설로서 법 제52조에 따른 사업시행계획서(이하 \"사업시행계획서\"라 한다)에 해당 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 자치구의 구청장(이하 \"시장ㆍ군수등\"이라 한다)이 관리하는 것으로 포함된 시설"}],"선지":[{"번호":1,"판정":"-","설명":"소방용수시설은 영 제3조제5호의 정비기반시설이다."},{"번호":2,"판정":"-","설명":"광장은 영 제3조제4호의 정비기반시설이다."},{"번호":3,"판정":"-","설명":"지역난방시설은 영 제3조제8호의 정비기반시설이다."},{"번호":4,"판정":"-","설명":"마을회관은 법 제2조제5호가 정한 공동이용시설이다. 주거환경개선사업 구역에서 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 공동이용시설만 정비기반시설로 보는데, 이 문제는 그 구역이 아니다."},{"번호":5,"판정":"-","설명":"구거는 법 제2조제4호에 직접 열거된 정비기반시설이다."}],"개념":[{"종류":"비교","제목":"정비기반시설과 공동이용시설","왼쪽":{"이름":"정비기반시설(법 제2조제4호, 영 제3조)","항목":["도로, 상하수도, 구거, 공원, 공용주차장, 공동구","녹지, 하천, 공공공지, 광장","소방용수시설, 비상대피시설","가스공급시설, 지역난방시설","주거환경개선사업 구역의 공동이용시설 중 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 시설"]},"오른쪽":{"이름":"공동이용시설(법 제2조제5호)","항목":["놀이터","마을회관","공동작업장","그 밖에 대통령령으로 정하는 시설"]}},{"종류":"표","제목":"정비사업 종류(법 제2조제2호)","머리":["사업","대상 지역"],"행":[["주거환경개선사업","도시저소득 주민이 집단거주하며 정비기반시설이 극히 열악하고 노후·불량건축물이 과도하게 밀집한 지역"],["재개발사업","정비기반시설이 열악하고 노후·불량건축물이 밀집한 지역 등"],["재건축사업","정비기반시설은 양호하나 노후·불량건축물에 해당하는 공동주택이 밀집한 지역"]]}],"함정":"마을회관·놀이터·공동작업장은 주민이 쓰는 시설이라 기반시설처럼 보인다. 법은 이 셋을 공동이용시설로 나누고, 정비기반시설은 도로·상하수도·공원 등 도시 기능 시설과 영 제3조 열거 시설로 한정한다."}},{"i":"S4-2-1-공법-19","r":"S4","g":2,"c":2,"n":59,"s":"공법","q":"도시 및 주거환경정비법령상 도시ㆍ주거환경정비기본계획(이하 \"기본계획\")에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["국토교통부장관은 기본계획에 대하여 5년마다 타당성을 검토하여 그 결과를 기본계획에 반영하여야 한다.","도지사가 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대하여는 기본계획을 수립하지 아니할 수 있다.","기본계획에는 건폐율ㆍ용적률 등에 관한 건축물의 밀도 계획이 포함되어야 한다.","기본계획의 내용 중 정비사업의 계획기간을 단축하는 경우에는 주민공람 절차를 거치지 아니할 수 있다.","기본계획의 내용 중 공동이용시설에 대한 설치계획을 변경하는 경우에는 지방의회의 의견청취 절차를 거치지 아니할 수 있다."],"a":[1],"L":"공3-1","o":"기출","x":{"한줄":"기본계획의 타당성을 5년마다 검토하는 사람은 국토교통부장관이 아니라 기본계획의 수립권자이다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"법 제4조제1항·제2항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장은 관할 구역에 대하여 도시ㆍ주거환경정비기본계획(이하 \"기본계획\"이라 한다)을 10년 단위로 수립하여야 한다. 다만, 도지사가 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대하여는 기본계획을 수립하지 아니할 수 있다.\n② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장(이하 \"기본계획의 수립권자\"라 한다)은 기본계획에 대하여 5년마다 타당성을 검토하여 그 결과를 기본계획에 반영하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"법 제5조제1항제11호","원문":"11. 건폐율ㆍ용적률 등에 관한 건축물의 밀도계획"},{"법령":"도시 및 주거환경정비법","조문":"법 제6조제3항","원문":"③ 제1항 및 제2항에도 불구하고 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 주민공람과 지방의회의 의견청취 절차를 거치지 아니할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"영 제6조제4항","원문":"④ 법 제6조제3항 및 제7조제1항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하는 경우\"란 각각 다음 각 호의 경우를 말한다.\n2. 정비사업의 계획기간을 단축하는 경우\n3. 공동이용시설에 대한 설치계획을 변경하는 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"5년마다 타당성을 검토하는 주체는 특별시장·광역시장·특별자치시장·특별자치도지사·시장(기본계획의 수립권자)이다(법 제4조제2항)."},{"번호":2,"판정":"옳음","설명":"도지사는 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대해 수립하지 않게 할 수 있다(법 제4조제1항 단서)."},{"번호":3,"판정":"옳음","설명":"기본계획에는 건폐율·용적률 등에 관한 건축물의 밀도계획이 포함된다(법 제5조제1항제11호)."},{"번호":4,"판정":"옳음","설명":"정비사업의 계획기간을 단축하는 변경은 경미한 사항이어서 주민공람과 지방의회 의견청취를 거치지 않을 수 있다(법 제6조제3항, 영 제6조제4항제2호)."},{"번호":5,"판정":"옳음","설명":"공동이용시설 설치계획의 변경도 경미한 사항이다(영 제6조제4항제3호)."}],"개념":[{"종류":"흐름","제목":"도시·주거환경정비기본계획 수립 절차","단계":[{"이름":"수립","설명":"특별시장·광역시장·특별자치시장·특별자치도지사·시장이 10년 단위로 수립(법 제4조①). 5년마다 타당성 검토(제4조②)"},{"이름":"주민공람·의견청취","설명":"14일 이상 주민공람, 지방의회 의견은 통지일부터 60일 이내(법 제6조)"},{"이름":"협의·심의","설명":"관계 행정기관 협의 후 지방도시계획위원회 심의(법 제7조①)"},{"이름":"도지사 승인","설명":"대도시가 아닌 시의 시장은 도지사 승인(법 제7조②)"},{"이름":"고시·보고","설명":"공보에 고시하고 일반이 열람. 국토교통부장관에게 보고(법 제7조③④)"}]},{"종류":"표","제목":"주민공람·의견청취를 생략하는 경미한 변경(영 제6조제4항)","머리":["호","내용"],"행":[["1호","정비기반시설 규모 확대, 또는 면적 10% 미만 축소"],["2호","정비사업의 계획기간 단축"],["3호","공동이용시설 설치계획 변경"],["4호","사회복지시설·주민문화시설 설치계획 변경"],["5호","정비예정구역 면적을 20% 미만 범위에서 변경"],["6호","단계별 정비사업 추진계획 변경"],["7호","건폐율·용적률을 각 20% 미만 범위에서 변경"]]}],"함정":"선지 1은 5년마다 타당성을 검토하는 주체를 국토교통부장관으로 적었다. 법에서 검토 주체는 기본계획의 수립권자이다. 경미한 변경 항목은 영 제6조제4항에 열거되어 있다."}},{"i":"S4-2-1-공법-20","r":"S4","g":2,"c":2,"n":60,"s":"공법","q":"도시 및 주거환경정비법령상 정비사업의 시행에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["조합설립인가 후 시장ㆍ군수등이 토지주택공사등을 사업시행자로 지정ㆍ고시한 때에는 그 고시일에 조합설립인가가 취소된 것으로 본다.","조합은 명칭에 “정비사업조합”이라는 문자를 사용하지 않아도 된다.","조합장이 자기를 위하여 조합과 소송을 할 때에는 감사가 조합을 대표한다.","재건축사업을 하는 정비구역에서 주택, 부대시설 및 복리시설을 제외한 건축물은 「국토의 계획 및 이용에 관한 법률」에 따른 준주거지역 및 상업지역 이외의 지역에서도 건설할 수 있다.","조합이 정관에 정한 정비구역의 위치 및 면적을 변경하려는 경우에는 조합원 과반수의 찬성으로 시장ㆍ군수등의 인가를 받으면 된다."],"a":[3],"L":"공3-2","o":"변형","x":{"한줄":"조합장이나 이사가 자기를 위하여 조합과 계약이나 소송을 할 때는 감사가 조합을 대표한다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"법 제42조제3항","원문":"③ 조합장 또는 이사가 자기를 위하여 조합과 계약이나 소송을 할 때에는 감사가 조합을 대표한다."},{"법령":"도시 및 주거환경정비법","조문":"법 제26조제3항","원문":"③ 제2항에 따라 시장ㆍ군수등이 직접 정비사업을 시행하거나 토지주택공사등을 사업시행자로 지정ㆍ고시한 때에는 그 고시일 다음 날에 추진위원회의 구성승인 또는 조합설립인가가 취소된 것으로 본다. 이 경우 시장ㆍ군수등은 해당 지방자치단체의 공보에 해당 내용을 고시하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"법 제38조제3항","원문":"③ 조합은 명칭에 \"정비사업조합\"이라는 문자를 사용하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"법 제23조제3항·제4항","원문":"③ 재건축사업은 정비구역에서 제74조에 따라 인가받은 관리처분계획에 따라 건축물을 건설하여 공급하는 방법으로 한다. 다만, 주택단지에 있지 아니하는 건축물의 경우에는 지형여건ㆍ주변의 환경으로 보아 사업 시행상 불가피한 경우로서 정비구역으로 보는 사업에 한정한다.\n④ 제3항에 따라 건축물을 건설하여 공급하는 경우 주택, 부대시설 및 복리시설을 제외한 건축물(이하 이 항에서 \"공동주택 외 건축물\"이라 한다)은 「국토의 계획 및 이용에 관한 법률」에 따른 준주거지역 및 상업지역에서만 건설할 수 있다. 이 경우 공동주택 외 건축물의 연면적은 전체 건축물 연면적의 100분의 30 이하이어야 한다."},{"법령":"도시 및 주거환경정비법","조문":"법 제40조제1항제4호·제3항","원문":"4. 정비구역의 위치 및 면적\n③ 조합이 정관을 변경하려는 경우에는 제35조제2항부터 제5항까지의 규정에도 불구하고 총회를 개최하여 조합원 과반수의 찬성으로 시장ㆍ군수등의 인가를 받아야 한다. 다만, 제1항제2호ㆍ제3호ㆍ제4호ㆍ제8호ㆍ제13호 또는 제16호의 경우에는 조합원 3분의 2 이상의 찬성으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취소된 것으로 보는 시점은 고시일 다음 날이다(법 제26조제3항)."},{"번호":2,"판정":"틀림","설명":"조합은 명칭에 “정비사업조합”이라는 문자를 사용하여야 한다(법 제38조제3항)."},{"번호":3,"판정":"옳음","설명":"조합장 또는 이사가 자기를 위하여 조합과 계약이나 소송을 할 때에는 감사가 조합을 대표한다(법 제42조제3항)."},{"번호":4,"판정":"틀림","설명":"공동주택 외 건축물은 준주거지역 및 상업지역에서만 건설할 수 있고, 연면적은 전체 건축물 연면적의 100분의 30 이하여야 한다(법 제23조제4항)."},{"번호":5,"판정":"틀림","설명":"정관의 정비구역 위치·면적 변경(제40조제1항제4호)은 조합원 3분의 2 이상의 찬성이 필요하다(법 제40조제3항 단서)."}],"개념":[{"종류":"표","제목":"정관 변경 의결 정족수(법 제40조제3항)","머리":["변경 대상","찬성"],"행":[["원칙","조합원 과반수 + 시장·군수등 인가"],["조합원의 자격, 제명·탈퇴 및 교체, 정비구역의 위치 및 면적, 조합의 비용부담 및 회계, 정비사업비의 부담 시기 및 절차, 시공자·설계자의 선정 및 계약서 내용","조합원 3분의 2 이상"],["경미한 사항","법 또는 정관 방법으로 변경하고 시장·군수등에게 신고(제40조④)"]]},{"종류":"표","제목":"조합과 임원(법 제38조·제42조)","머리":["항목","내용"],"행":[["조합의 성격","법인. 조합설립인가를 받은 날부터 30일 이내 등기하면 성립(제38조②)"],["명칭","“정비사업조합”이라는 문자 사용(제38조③)"],["조합장","조합을 대표하고 사무 총괄, 총회·대의원회 의장(제42조①)"],["자기 거래·소송","감사가 조합을 대표(제42조③)"],["겸직","같은 목적의 정비사업을 하는 다른 조합의 임원·직원 겸임 금지(제42조④)"]]}],"함정":"조합장 본인과의 소송에서 이사가 조합을 대표한다고 쓰면 틀리다. 감사가 대표한다. 취소 시점은 고시일이 아니라 그 다음 날이다."}},{"i":"S4-2-1-공법-21","r":"S4","g":2,"c":2,"n":61,"s":"공법","q":"도시 및 주거환경정비법령상 조합설립추진위원회가 운영에 필요한 사항 중 추진위원회 구성에 동의한 토지등소유자에게 등기우편으로 통지하여야 하는 사항에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["재건축사업의 재건축진단 결과","조합설립 동의서에 포함되는 사항으로서 정비사업비의 분담기준","토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서","정비사업전문관리업자의 선정에 관한 사항","추진위원회 위원의 선정에 관한 사항"],"a":[2],"L":"공3-2","o":"기출","x":{"한줄":"등기우편으로 통지하는 사항은 조합설립 동의철회 방법과 조합설립 동의서 포함사항뿐이고, 정비사업비의 분담기준은 동의서 포함사항이다.","근거":[{"법령":"도시 및 주거환경정비법 시행령","조문":"제29조제1항","원문":"① 추진위원회는 법 제34조제5항에 따라 다음 각 호의 사항을 토지등소유자가 쉽게 접할 수 있는 일정한 장소에 게시하거나 인터넷 등을 통하여 공개하고, 필요한 경우에는 토지등소유자에게 서면통지를 하는 등 토지등소유자가 그 내용을 충분히 알 수 있도록 하여야 한다. 다만, 제8호 및 제9호의 사항은 법 제35조에 따른 조합설립인가(이하 \"조합설립인가\"라 한다) 신청일 60일 전까지 추진위원회 구성에 동의한 토지등소유자에게 등기우편으로 통지하여야 한다.\n1. 법 제12조에 따른 재건축진단의 결과\n2. 정비사업전문관리업자의 선정에 관한 사항\n3. 토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서\n4. 추진위원회 위원의 선정에 관한 사항\n5. 토지등소유자의 비용부담을 수반하거나 권리ㆍ의무에 변동을 일으킬 수 있는 사항\n6. 법 제32조제1항에 따른 추진위원회의 업무에 관한 사항\n7. 창립총회 개최의 방법 및 절차\n8. 조합설립에 대한 동의철회(법 제31조제3항 단서에 따른 반대의 의사표시를 포함한다) 및 방법\n9. 제30조제2항에 따른 조합설립 동의서에 포함되는 사항"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제30조제2항","원문":"② 제1항에 따른 동의서에는 다음 각 호의 사항이 포함되어야 한다.\n1. 건설되는 건축물의 설계의 개요\n2. 공사비 등 정비사업비용에 드는 비용(이하 \"정비사업비\"라 한다)\n3. 정비사업비의 분담기준\n4. 사업 완료 후 소유권의 귀속에 관한 사항\n5. 조합 정관"},{"법령":"도시 및 주거환경정비법","조문":"제31조제1항","원문":"① 조합을 설립하려는 경우에는 다음 각 호의 사항에 대하여 토지등소유자 과반수의 동의를 받아 조합설립을 위한 추진위원회를 구성하여 국토교통부령으로 정하는 방법과 절차에 따라 시장ㆍ군수등의 승인을 받아야 한다. 이 경우 시장ㆍ군수등은 승인 이후 구역경계, 토지등소유자의 수 등 국토교통부령으로 정하는 사항을 해당 지방자치단체 공보에 고시하여야 한다.\n1. 추진위원회 위원장(이하 \"추진위원장\"이라 한다)을 포함한 5명 이상의 추진위원회 위원(이하 \"추진위원\"이라 한다)"},{"법령":"도시 및 주거환경정비법","조문":"제35조제10항","원문":"⑩ 추진위원회는 조합설립에 필요한 동의를 받기 전에 추정분담금 등 대통령령으로 정하는 정보를 토지등소유자에게 제공하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"재건축진단의 결과는 영 제29조제1항제1호 사항이라 게시·공개 대상이다. 등기우편은 제8호·제9호만 해당한다."},{"번호":2,"판정":"옳음","설명":"동의서에는 건설되는 건축물의 설계 개요, 정비사업비, 정비사업비의 분담기준, 사업 완료 후 소유권 귀속, 조합 정관이 들어간다(영 제30조제2항). 이 동의서 포함사항이 영 제29조제1항제9호로서 등기우편 통지 대상이다."},{"번호":3,"판정":"틀림","설명":"토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서는 제3호 사항이다. 게시·공개하고 필요하면 서면통지한다."},{"번호":4,"판정":"틀림","설명":"정비사업전문관리업자의 선정에 관한 사항은 제2호 사항이다. 등기우편 통지 대상이 아니다."},{"번호":5,"판정":"틀림","설명":"추진위원회 위원의 선정에 관한 사항은 제4호 사항이다. 등기우편 통지 대상이 아니다."}],"개념":[{"종류":"표","제목":"추진위원회의 공개·통지 사항(영 제29조제1항)","머리":["호","사항","공개·통지 방법"],"행":[["1","재건축진단의 결과","게시·공개, 필요하면 서면통지"],["2","정비사업전문관리업자의 선정에 관한 사항","게시·공개, 필요하면 서면통지"],["3","토지등소유자의 부담액 범위를 포함한 개략적인 사업시행계획서","게시·공개, 필요하면 서면통지"],["4","추진위원회 위원의 선정에 관한 사항","게시·공개, 필요하면 서면통지"],["5~7","비용부담·권리의무 변동 사항, 추진위원회 업무, 창립총회 개최 방법·절차","게시·공개, 필요하면 서면통지"],["8","조합설립 동의철회(반대의 의사표시 포함) 및 방법","조합설립인가 신청일 60일 전까지 동의한 토지등소유자에게 등기우편"],["9","조합설립 동의서에 포함되는 사항","조합설립인가 신청일 60일 전까지 동의한 토지등소유자에게 등기우편"]]},{"종류":"흐름","제목":"추진위원회 구성에서 조합설립인가까지","단계":[{"이름":"추진위원회 구성승인","설명":"토지등소유자 과반수 동의를 받아 위원장 포함 5명 이상의 추진위원과 운영규정으로 시장·군수등의 승인을 받는다(법 제31조제1항)."},{"이름":"정보 제공","설명":"조합설립 동의를 받기 전에 추정분담금 등 정보를 토지등소유자에게 제공한다(법 제35조제10항)."},{"이름":"등기우편 통지","설명":"동의철회 방법과 동의서 포함사항을 인가 신청일 60일 전까지 동의자에게 등기우편으로 통지한다(영 제29조제1항 단서)."},{"이름":"조합설립 동의","설명":"재개발은 토지등소유자 4분의 3 이상 및 토지면적 2분의 1 이상 토지소유자의 동의를 받는다(법 제35조제2항)."},{"이름":"조합설립인가","설명":"정비구역 지정·고시 후 정관 등을 첨부해 시장·군수등의 인가를 받는다(법 제35조제2항)."},{"이름":"업무 인계","설명":"추진위원회는 회계장부와 관계 서류를 인가일부터 30일 이내에 조합에 인계하고, 업무상 권리·의무는 조합이 포괄승계한다(법 제34조제3항·제4항)."}]}],"함정":"1번의 재건축진단 결과, 3번의 개략적인 사업시행계획서처럼 비용·권리에 크게 관련된 사항이 등기우편 대상일 것 같지만 게시·공개 사항이다. 등기우편은 동의철회 방법(제8호)과 동의서 포함사항(제9호) 둘이다.","개정":"법 제12조제1항이 2024.12.3 개정되어 안전진단이 재건축진단으로 바뀌었다. 영 제29조제1항제1호도 「재건축진단의 결과」로 표기하며, 재건축진단은 정비계획 수립시기가 도래한 때부터 사업시행계획인가 전까지 실시한다."}},{"i":"S4-2-1-공법-22","r":"S4","g":2,"c":2,"n":62,"s":"공법","q":"도시 및 주거환경정비법령상 사업시행계획의 통합심의에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["｢경관법｣에 따른 경관 심의는 통합심의 대상이 아니다.","시장ㆍ군수등은 특별한 사유가 없으면 통합심의 결과를 반영하여 사업시행계획을 인가하여야 한다.","통합심의를 거친 경우 해당 사항에 대한 조정 또는 재정을 거친 것으로 보지 아니한다.","통합심의위원회 위원장은 위원 중에서 호선한다.","사업시행자는 통합심의를 신청할 수 없다."],"a":[2],"L":"공3-2","o":"기출","x":{"한줄":"시장·군수등은 특별한 사유가 없으면 통합심의 결과를 반영해 사업시행계획을 인가해야 한다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제50조의2제4항","원문":"④ 시장ㆍ군수등은 특별한 사유가 없으면 통합심의 결과를 반영하여 사업시행계획을 인가하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제50조의2제5항","원문":"⑤ 통합심의를 거친 경우에는 제1항 각 호의 사항에 대한 검토ㆍ심의ㆍ조사ㆍ협의ㆍ조정 또는 재정을 거친 것으로 본다."},{"법령":"도시 및 주거환경정비법","조문":"제50조의2제1항","원문":"① 정비구역의 지정권자는 사업시행계획인가와 관련된 다음 각 호 중 둘 이상의 심의가 필요한 경우에는 이를 통합하여 검토 및 심의(이하 \"통합심의\"라 한다)하여야 한다.\n2. 「경관법」에 따른 경관 심의에 관한 사항"},{"법령":"도시 및 주거환경정비법","조문":"제50조의2제2항","원문":"② 사업시행자가 통합심의를 신청하는 경우에는 제1항 각 호와 관련된 서류를 첨부하여야 한다. 이 경우 정비구역의 지정권자는 통합심의를 효율적으로 처리하기 위하여 필요한 경우 제출기한을 정하여 제출하도록 할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제46조의2제3항","원문":"③ 통합심의위원회 위원장과 부위원장은 제2항에 따른 통합심의위원회의 위원(이하 \"위원\"이라 한다) 중에서 정비구역지정권자가 임명하거나 위촉한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경관법에 따른 경관 심의는 통합심의 대상 제2호에 들어간다(법 제50조의2제1항제2호)."},{"번호":2,"판정":"옳음","설명":"법 제50조의2제4항에 있는 내용이다."},{"번호":3,"판정":"틀림","설명":"통합심의를 거치면 제1항 각 호 사항의 검토·심의·조사·협의·조정 또는 재정을 거친 것으로 본다(법 제50조의2제5항)."},{"번호":4,"판정":"틀림","설명":"통합심의위원회의 위원장과 부위원장은 정비구역지정권자가 위원 중에서 임명하거나 위촉한다(영 제46조의2제3항)."},{"번호":5,"판정":"틀림","설명":"사업시행자가 통합심의를 신청하는 경우 제1항 각 호와 관련된 서류를 첨부하도록 되어 있어 신청할 수 있다(법 제50조의2제2항)."}],"개념":[{"종류":"표","제목":"통합심의 대상과 소집되는 위원회(법 제50조의2제1항·제3항)","머리":["호","심의 사항","위원회"],"행":[["1","건축법에 따른 건축물의 건축 및 특별건축구역의 지정 등","건축위원회"],["2","경관법에 따른 경관 심의","경관위원회"],["3","교육환경 보호에 관한 법률에 따른 교육환경평가","교육환경보호위원회"],["4","국토계획법에 따른 도시·군관리계획","지방도시계획위원회"],["5","도시교통정비 촉진법에 따른 교통영향평가","교통영향평가심의위원회"],["5의2","소방시설법에 따른 성능위주설계의 평가","성능위주설계평가단 또는 중앙소방기술심의위원회"],["5의3","자연재해대책법에 따른 재해영향평가","재해영향평가심의위원회"],["6","환경영향평가법에 따른 환경영향평가 등","환경영향평가협의회"],["7","그 밖에 국토교통부장관, 시·도지사 또는 시장·군수등이 통합심의에 부치는 사항","그 사항에 심의권한이 있는 위원회"]]},{"종류":"흐름","제목":"사업시행계획인가 절차(법 제50조)","단계":[{"이름":"총회 의결","설명":"시장·군수등과 토지주택공사등을 제외한 사업시행자는 인가 신청 전에 총회 의결을 거친다(제5항)."},{"이름":"인가 신청","설명":"사업시행계획서에 정관등과 국토교통부령 서류를 첨부해 시장·군수등에게 제출한다(제1항)."},{"이름":"통합심의","설명":"제1항 각 호 중 둘 이상의 심의가 필요하면 정비구역 지정권자가 통합심의한다(법 제50조의2)."},{"이름":"인가 여부 통보","설명":"특별한 사유가 없으면 제출일부터 60일 이내에 인가 여부를 결정해 통보한다(제4항)."},{"이름":"고시","설명":"인가하면 국토교통부령으로 정하는 방법과 절차로 지방자치단체 공보에 고시한다(제9항)."},{"이름":"경미한 변경","설명":"신고 대상이며 시장·군수등은 신고를 받은 날부터 20일 이내에 수리 여부를 통지한다(제1항 단서, 제2항)."}]}],"함정":"통합심의 결과의 반영은 시장·군수등의 의무(특별한 사유가 있으면 예외)이고, 통합심의를 거치면 개별 법률상 심의 등을 거친 것으로 본다. 위원장은 호선하지 않고 지정권자가 임명·위촉한다.","개정":"법 제50조의2제1항·제3항은 2025.1.31 개정된 조문이다. 현행 통합심의 대상에는 소방 성능위주설계의 평가(제5호의2)와 재해영향평가(제5호의3)가 포함되어 있다."}},{"i":"S4-2-1-공법-23","r":"S4","g":2,"c":2,"n":63,"s":"공법","q":"도시 및 주거환경정비법령상 사업시행자가 분양의 대상이 되는 대지 또는 건축물의 내역 등을 일간신문에 공고할 때 포함하여야 할 사항으로 명시되지 않은 것은? (단, 토지등소유자 1인이 시행하는 재개발사업은 제외하고, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["사업시행계획인가의 내용","정비사업의 종류ㆍ명칭 및 정비구역의 위치ㆍ면적","토지등소유자 외의 권리자의 권리신고방법","분양을 신청하지 아니한 자에 대한 조치","분양대상자별 종전의 토지 또는 건축물의 명세 및 가격"],"a":[5],"L":"공3-3","o":"변형","x":{"한줄":"분양대상자별 종전 토지·건축물의 명세와 가격은 토지등소유자에게 통지하는 사항이고, 일간신문 공고사항에는 없다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제72조제1항","원문":"① 사업시행자는 제50조제9항에 따른 사업시행계획인가의 고시가 있은 날(사업시행계획인가 이후 시공자를 선정한 경우에는 시공자와 계약을 체결한 날)부터 90일(대통령령으로 정하는 경우에는 1회에 한정하여 30일의 범위에서 연장할 수 있다) 이내에 다음 각 호의 사항을 토지등소유자에게 통지하고, 분양의 대상이 되는 대지 또는 건축물의 내역 등 대통령령으로 정하는 사항을 해당 지역에서 발간되는 일간신문에 공고하여야 한다. 다만, 토지등소유자 1인이 시행하는 재개발사업의 경우에는 그러하지 아니하다.\n1. 분양대상자별 종전의 토지 또는 건축물의 명세 및 사업시행계획인가의 고시가 있은 날을 기준으로 한 가격(사업시행계획인가 전에 제81조제3항에 따라 철거된 건축물은 시장ㆍ군수등에게 허가를 받은 날을 기준으로 한 가격)\n2. 분양대상자별 분담금의 추산액\n3. 분양신청기간\n4. 그 밖에 대통령령으로 정하는 사항"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제59조제2항","원문":"② 법 제72조제1항 각 호 외의 부분 본문에서 \"분양의 대상이 되는 대지 또는 건축물의 내역 등 대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n1. 사업시행인가의 내용\n2. 정비사업의 종류ㆍ명칭 및 정비구역의 위치ㆍ면적\n3. 분양신청기간 및 장소\n4. 분양대상 대지 또는 건축물의 내역\n5. 분양신청자격\n6. 분양신청방법\n7. 토지등소유자외의 권리자의 권리신고방법\n8. 분양을 신청하지 아니한 자에 대한 조치\n9. 그 밖에 시ㆍ도조례로 정하는 사항"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제59조제3항","원문":"③ 법 제72조제1항제4호에서 \"대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n1. 제2항제1호부터 제6호까지 및 제8호의 사항\n2. 분양신청서\n3. 그 밖에 시ㆍ도조례로 정하는 사항"},{"법령":"도시 및 주거환경정비법","조문":"제72조제2항","원문":"② 제1항제3호에 따른 분양신청기간은 통지한 날부터 30일 이상 60일 이내로 하여야 한다. 다만, 사업시행자는 제74조제1항에 따른 관리처분계획의 수립에 지장이 없다고 판단하는 경우에는 분양신청기간을 20일의 범위에서 한 차례만 연장할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"영 제59조제2항제1호 공고사항이다."},{"번호":2,"판정":"옳음","설명":"영 제59조제2항제2호 공고사항이다."},{"번호":3,"판정":"옳음","설명":"영 제59조제2항제7호 공고사항이다. 통지 사항(같은 조 제3항제1호)에는 이 호가 빠져 있다."},{"번호":4,"판정":"옳음","설명":"영 제59조제2항제8호 공고사항이다."},{"번호":5,"판정":"틀림","설명":"종전 토지·건축물의 명세와 가격은 법 제72조제1항제1호의 통지 사항이다. 영 제59조제2항의 공고사항에는 없다."}],"개념":[{"종류":"비교","제목":"분양신청 통지 사항과 일간신문 공고 사항","왼쪽":{"이름":"토지등소유자에게 통지(법 제72조제1항, 영 제59조제3항)","항목":["분양대상자별 종전 토지·건축물의 명세 및 사업시행계획인가 고시일 기준 가격","분양대상자별 분담금의 추산액","분양신청기간","사업시행인가의 내용, 정비사업의 종류·명칭·정비구역의 위치·면적","분양신청기간 및 장소, 분양대상 대지 또는 건축물의 내역","분양신청자격, 분양신청방법","분양을 신청하지 아니한 자에 대한 조치","분양신청서"]},"오른쪽":{"이름":"일간신문에 공고(영 제59조제2항)","항목":["사업시행인가의 내용","정비사업의 종류·명칭 및 정비구역의 위치·면적","분양신청기간 및 장소","분양대상 대지 또는 건축물의 내역","분양신청자격, 분양신청방법","토지등소유자 외의 권리자의 권리신고방법","분양을 신청하지 아니한 자에 대한 조치","그 밖에 시·도조례로 정하는 사항"]}},{"종류":"흐름","제목":"분양신청에서 현금청산까지","단계":[{"이름":"분양공고·통지","설명":"사업시행계획인가 고시일(인가 후 시공자를 선정했으면 계약 체결일)부터 90일 이내에 통지·공고한다. 재개발사업 중 시·도조례로 정하는 면적 이상의 정비구역은 1회 30일 범위에서 연장할 수 있다(법 제72조제1항, 영 제59조제1항)."},{"이름":"분양신청기간","설명":"통지한 날부터 30일 이상 60일 이내로 정하고, 관리처분계획 수립에 지장이 없으면 20일 범위에서 한 차례 연장한다(법 제72조제2항)."},{"이름":"분양신청","설명":"분양신청서에 소유권 내역을 적고 등기부등본 등을 첨부해 제출한다. 우편이면 기간 내 발송을 증명할 수 있어야 한다(영 제59조제4항)."},{"이름":"관리처분계획 인가","설명":"신청기간이 끝나면 분양신청 현황을 기초로 관리처분계획을 수립해 시장·군수등의 인가를 받는다(법 제74조제1항)."},{"이름":"현금청산 협의","설명":"관리처분계획 인가·고시 다음 날부터 90일 이내에 분양신청을 하지 않은 자 등과 손실보상을 협의한다(법 제73조제1항)."},{"이름":"수용재결·매도청구","설명":"협의가 안 되면 협의기간 만료일 다음 날부터 60일 이내에 수용재결 신청 또는 매도청구소송을 제기한다(법 제73조제2항)."}]}],"함정":"분담금의 추산액이나 종전 자산의 가격은 개인별 정보라 통지 사항이다. 공고는 신문에 싣는 일반 사항(사업 내용, 신청 자격·방법, 권리신고방법 등)만 담는다. 통지 사항과 공고 사항을 한 묶음으로 외우면 5번을 공고사항으로 읽게 된다.","개정":"법 제72조제1항이 2025.1.31 개정되고 영 제59조가 2025.4.29 신설·개정되었다. 분양공고·통지 기한은 90일이며 대통령령으로 정하는 경우(재개발사업 중 시·도조례로 정하는 면적 이상의 정비구역, 영 제59조제1항)에는 1회 30일 범위에서 연장할 수 있다."}},{"i":"S4-2-1-공법-24","r":"S4","g":2,"c":2,"n":64,"s":"공법","q":"도시 및 주거환경정비법령상 주택의 공급 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["정비사업의 시행으로 조성된 대지 및 건축물은 인가받은 사업시행계획에 따라 처분 또는 관리하여야 한다.","시장ㆍ군수는 조합이 요청하는 경우 재건축사업의 시행으로 건설된 임대주택을 인수하여야 한다.","사업시행자는 분양신청을 받은 후 잔여분이 있는 경우 그 잔여분을 조합원 또는 토지등소유자 이외의 자에게는 분양할 수 없다.","사업시행자가 토지주택공사등인 경우에는 분양대상자와 사업시행자가 공동 소유하는 방식으로 주택을 공급할 수 있다.","관리처분계획에서 종전 주택의 주거전용면적의 범위에서 2주택을 공급하는 경우 그 중 1주택은 주거전용면적을 60제곱미터 이하로 하되, 이를 공급받은 자는 이전고시일 다음 날부터 1년이 지나면 전매할 수 있다."],"a":[4],"L":"공3-3","o":"변형","x":{"한줄":"사업시행자가 토지주택공사등이면 분양대상자와 공동 소유하는 지분형주택을 공급할 수 있다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제80조제1항","원문":"① 사업시행자가 토지주택공사등인 경우에는 분양대상자와 사업시행자가 공동 소유하는 방식으로 주택(이하 \"지분형주택\"이라 한다)을 공급할 수 있다. 이 경우 공급되는 지분형주택의 규모, 공동 소유기간 및 분양대상자 등 필요한 사항은 대통령령으로 정한다."},{"법령":"도시 및 주거환경정비법","조문":"제79조제1항","원문":"① 정비사업의 시행으로 조성된 대지 및 건축물은 관리처분계획에 따라 처분 또는 관리하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제79조제4항","원문":"④ 사업시행자는 제72조에 따른 분양신청을 받은 후 잔여분이 있는 경우에는 정관등 또는 사업시행계획으로 정하는 목적을 위하여 그 잔여분을 보류지(건축물을 포함한다)로 정하거나 조합원 또는 토지등소유자 이외의 자에게 분양할 수 있다. 이 경우 분양공고와 분양신청절차 등에 필요한 사항은 대통령령으로 정한다."},{"법령":"도시 및 주거환경정비법","조문":"제79조제5항","원문":"⑤ 국토교통부장관, 시ㆍ도지사, 시장, 군수, 구청장 또는 토지주택공사등은 조합이 요청하는 경우 재개발사업의 시행으로 건설된 임대주택을 인수하여야 한다. 이 경우 재개발임대주택의 인수 절차 및 방법, 인수 가격 등에 필요한 사항은 대통령령으로 정한다."},{"법령":"도시 및 주거환경정비법","조문":"제76조제1항제7호라목","원문":"라. 제74조제1항제5호에 따른 가격의 범위 또는 종전 주택의 주거전용면적의 범위에서 2주택을 공급할 수 있고, 이 중 1주택은 주거전용면적을 60제곱미터 이하로 한다. 다만, 60제곱미터 이하로 공급받은 1주택은 제86조제2항에 따른 이전고시일 다음 날부터 3년이 지나기 전에는 주택을 전매(매매ㆍ증여나 그 밖에 권리의 변동을 수반하는 모든 행위를 포함하되 상속의 경우는 제외한다)하거나 전매를 알선할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정비사업으로 조성된 대지 및 건축물은 관리처분계획에 따라 처분 또는 관리한다(법 제79조제1항). 사업시행계획이 아니다."},{"번호":2,"판정":"틀림","설명":"조합 요청 시 인수하는 임대주택은 재개발사업의 시행으로 건설된 재개발임대주택이다(법 제79조제5항). 재건축은 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"분양신청 후 잔여분은 보류지로 정하거나 조합원 또는 토지등소유자 이외의 자에게 분양할 수 있다(법 제79조제4항)."},{"번호":4,"판정":"옳음","설명":"법 제80조제1항의 지분형주택이다. 규모, 공동 소유기간, 분양대상자는 대통령령으로 정한다."},{"번호":5,"판정":"틀림","설명":"60제곱미터 이하로 공급받은 1주택은 이전고시일 다음 날부터 3년이 지나기 전에는 전매하거나 전매를 알선할 수 없다. 상속은 제외한다(법 제76조제1항제7호라목)."}],"개념":[{"종류":"표","제목":"정비사업 주택의 처분·공급 규정","머리":["조문","내용"],"행":[["법 제79조제1항","조성된 대지·건축물은 관리처분계획에 따라 처분 또는 관리"],["법 제79조제2항","건설된 건축물은 인가받은 관리처분계획에 따라 토지등소유자에게 공급"],["법 제79조제3항","주택 건설 시 입주자 모집 조건·방법 등은 시장·군수등의 승인을 받아 주택법 제54조와 달리 정할 수 있음"],["법 제79조제4항","분양신청 후 잔여분은 보류지로 정하거나 조합원·토지등소유자 외의 자에게 분양 가능"],["법 제79조제5항","재개발임대주택은 조합 요청 시 국토교통부장관, 시·도지사, 시장, 군수, 구청장 또는 토지주택공사등이 인수"],["법 제79조제7항","공급대상자에게 공급하고 남은 주택은 공급대상자 외의 자에게 공급 가능"],["법 제80조제1항","사업시행자가 토지주택공사등이면 분양대상자와 공동 소유하는 지분형주택 공급 가능"],["법 제80조제2항","세입자와 소규모 토지·주택 소유자가 요청하면 인수한 임대주택의 일부를 토지임대부 분양주택으로 전환하여 공급해야 함"]]},{"종류":"표","제목":"1주택 공급 원칙과 예외(법 제76조제1항제6호·제7호)","머리":["구분","내용"],"행":[["원칙(제6호)","1세대 또는 1명이 하나 이상의 주택·토지를 소유하면 1주택 공급. 세대가 다른 2명 이상이 1주택·1토지를 공유하면 1주택만 공급"],["가목","2명 이상이 1토지를 공유한 경우 시·도조례로 정하면 그에 따라 공급"],["나목","소유 주택 수만큼 공급: 과밀억제권역 밖 재건축(투기과열지구·조정대상지역에서 최초 사업시행계획인가를 신청하는 재건축 제외), 근로자 숙소·기숙사, 국가·지방자치단체·토지주택공사등, 공공기관 이전 시책으로 이전하는 공공기관 소유 주택의 양수자"],["라목","종전 주택 가격 또는 주거전용면적의 범위에서 2주택 공급 가능. 1주택은 60㎡ 이하이며 이전고시일 다음 날부터 3년 전 전매·알선 금지(상속 제외)"],["마목","과밀억제권역 재건축은 소유 주택 수 범위에서 3주택까지 공급(투기과열지구·조정대상지역에서 최초 인가신청 재건축 제외)"]]}],"함정":"임대주택 인수 대상은 재개발임대주택뿐이라 재건축임대주택은 해당하지 않는다. 분양신청 후 잔여분은 조합원 외의 자에게 분양할 수 있다. 60제곱미터 이하로 공급받은 주택의 전매 제한기간은 이전고시일 다음 날부터 3년이다."}},{"i":"S4-2-1-공법-25","r":"S4","g":2,"c":2,"n":65,"s":"공법","q":"다음 건축물 중 ｢건축법｣의 적용을 받는 것은?","b":null,"bs":"없음","img":[],"ch":["공장이 아닌 상가 건축물의 대지에 설치하는, 이동이 쉬운 컨테이너를 이용한 간이창고","철도의 선로 위나 아래를 가로지르는 보행시설","｢자연유산의 보존 및 활용에 관한 법률｣에 따라 지정된 천연기념물등","철도의 선로 부지에 있는 플랫폼","｢하천법｣에 따른 하천구역 내의 수문조작실"],"a":[1],"L":"공4-1","o":"변형","x":{"한줄":"컨테이너를 이용한 간이창고가 건축법 적용에서 빠지려면 공장 용도 건축물의 대지에 설치하는 이동이 쉬운 것이어야 한다.","근거":[{"법령":"건축법","조문":"제3조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 건축물에는 이 법을 적용하지 아니한다.\n1. 「문화유산의 보존 및 활용에 관한 법률」에 따른 지정문화유산이나 임시지정문화유산 또는 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 천연기념물등이나 임시지정천연기념물, 임시지정명승, 임시지정시ㆍ도자연유산, 임시자연유산자료\n2. 철도나 궤도의 선로 부지(敷地)에 있는 다음 각 목의 시설\n가. 운전보안시설\n나. 철도 선로의 위나 아래를 가로지르는 보행시설\n다. 플랫폼\n라. 해당 철도 또는 궤도사업용 급수(給水)ㆍ급탄(給炭) 및 급유(給油) 시설\n3. 고속도로 통행료 징수시설\n4. 컨테이너를 이용한 간이창고(「산업집적활성화 및 공장설립에 관한 법률」 제2조제1호에 따른 공장의 용도로만 사용되는 건축물의 대지에 설치하는 것으로서 이동이 쉬운 것만 해당된다)\n5. 「하천법」에 따른 하천구역 내의 수문조작실"},{"법령":"건축법","조문":"제3조제2항","원문":"② 「국토의 계획 및 이용에 관한 법률」에 따른 도시지역 및 같은 법 제51조제3항에 따른 지구단위계획구역(이하 \"지구단위계획구역\"이라 한다) 외의 지역으로서 동이나 읍(동이나 읍에 속하는 섬의 경우에는 인구가 500명 이상인 경우만 해당된다)이 아닌 지역은 제44조부터 제47조까지, 제51조 및 제57조를 적용하지 아니한다."},{"법령":"건축법","조문":"제3조제3항","원문":"③ 「국토의 계획 및 이용에 관한 법률」 제47조제7항에 따른 건축물이나 공작물을 도시ㆍ군계획시설로 결정된 도로의 예정지에 건축하는 경우에는 제45조부터 제47조까지의 규정을 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제3조제1항제4호의 컨테이너 간이창고는 공장 용도로만 쓰는 건축물의 대지에 설치하는 이동이 쉬운 것만 제외된다. 상가 건축물의 대지에 설치하는 것은 제외 대상이 아니라 건축법이 적용된다."},{"번호":2,"판정":"틀림","설명":"철도 선로 위나 아래를 가로지르는 보행시설은 제3조제1항제2호나목으로 적용 제외다."},{"번호":3,"판정":"틀림","설명":"자연유산법에 따라 지정된 천연기념물등은 제3조제1항제1호로 적용 제외다."},{"번호":4,"판정":"틀림","설명":"플랫폼은 철도·궤도 선로 부지의 시설로 제3조제1항제2호다목에 따라 적용 제외다."},{"번호":5,"판정":"틀림","설명":"하천구역 내의 수문조작실은 제3조제1항제5호로 적용 제외다."}],"개념":[{"종류":"표","제목":"건축법 적용 제외 건축물(법 제3조제1항)","머리":["호","적용 제외 건축물"],"행":[["1","문화유산법의 지정문화유산·임시지정문화유산, 자연유산법의 천연기념물등·임시지정천연기념물·임시지정명승·임시지정시·도자연유산·임시자연유산자료"],["2","철도·궤도 선로 부지의 운전보안시설, 선로 위·아래를 가로지르는 보행시설, 플랫폼, 철도·궤도사업용 급수·급탄·급유 시설"],["3","고속도로 통행료 징수시설"],["4","컨테이너를 이용한 간이창고(공장 용도로만 쓰는 건축물의 대지에 설치하는 이동이 쉬운 것만)"],["5","하천법에 따른 하천구역 내의 수문조작실"]]},{"종류":"표","제목":"지역에 따른 일부 규정 적용 제외(법 제3조제2항·제3항)","머리":["대상","적용하지 않는 규정"],"행":[["도시지역·지구단위계획구역 밖으로서 동·읍(섬은 인구 500명 이상)이 아닌 지역","제44조(대지와 도로의 관계), 제45조(도로의 지정·폐지 또는 변경), 제46조(건축선의 지정), 제47조(건축선에 따른 건축제한), 제51조(방화지구 안의 건축물), 제57조(대지의 분할 제한)"],["국토계획법 제47조제7항에 따른 건축물·공작물을 도시·군계획시설 도로 예정지에 건축하는 경우","제45조부터 제47조까지"]]}],"함정":"컨테이너라는 이유만으로 건축법이 제외된다고 보기 쉽다. 제외되는 것은 공장 용도 건축물 대지의 이동이 쉬운 간이창고에 한정되고, 주택·상가 등에 쓰는 컨테이너 건축물은 적용 대상이다.","개정":"법 제3조제1항이 2023.8.8, 2024.2.6 개정되어 제1호가 「문화유산의 보존 및 활용에 관한 법률」의 지정문화유산·임시지정문화유산과 「자연유산의 보존 및 활용에 관한 법률」의 천연기념물등·임시지정천연기념물·임시지정명승·임시지정시·도자연유산·임시자연유산자료로 표기된다."}},{"i":"S4-2-1-공법-26","r":"S4","g":2,"c":2,"n":66,"s":"공법","q":"건축주 甲은 A도 B시에서 연면적이 100제곱미터이고 2층인 건축물을 대수선하고자 ｢건축법｣제14조에 따른 신고(이하 “건축신고”)를 하려고 한다. 건축법령상 이에 관한 설명으로 옳은 것은? (단, 건축법령상 특례 및 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲이 대수선을 하기 전에 B시장에게 건축신고를 하면 건축허가를 받은 것으로 본다.","건축신고를 한 甲이 공사시공자를 변경하려면 B시장에게 허가를 받아야 한다.","B시장은 건축신고의 수리 전에 건축물 안전영향평가를 실시하여야 한다.","건축신고를 한 甲이 신고일부터 6개월 이내에 공사에 착수하지 아니하면 그 신고의 효력은 없어진다.","건축신고를 한 甲은 건축물의 공사가 끝난 후 사용승인신청 없이 건축물을 사용할 수 있다."],"a":[1],"L":"공4-2","o":"기출","x":{"한줄":"연면적 200제곱미터 미만이고 3층 미만인 건축물의 대수선은 건축신고를 하면 건축허가를 받은 것으로 본다.","근거":[{"법령":"건축법","조문":"제14조제1항제3호","원문":"① 제11조에 해당하는 허가 대상 건축물이라 하더라도 다음 각 호의 어느 하나에 해당하는 경우에는 미리 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 국토교통부령으로 정하는 바에 따라 신고를 하면 건축허가를 받은 것으로 본다.\n3. 연면적이 200제곱미터 미만이고 3층 미만인 건축물의 대수선"},{"법령":"건축법","조문":"제14조제5항","원문":"⑤ 제1항에 따라 신고를 한 자가 신고일부터 1년 이내에 공사에 착수하지 아니하면 그 신고의 효력은 없어진다. 다만, 건축주의 요청에 따라 허가권자가 정당한 사유가 있다고 인정하면 1년의 범위에서 착수기한을 연장할 수 있다."},{"법령":"건축법 시행령","조문":"제12조제1항제3호","원문":"① 법 제16조제1항에 따라 허가를 받았거나 신고한 사항을 변경하려면 다음 각 호의 구분에 따라 허가권자의 허가를 받거나 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 신고하여야 한다.\n3. 건축주ㆍ설계자ㆍ공사시공자 또는 공사감리자(이하 \"건축관계자\"라 한다)를 변경하는 경우에는 신고할 것"},{"법령":"건축법","조문":"제13조의2제1항","원문":"① 허가권자는 초고층 건축물 등 대통령령으로 정하는 주요 건축물에 대하여 제11조에 따른 건축허가를 하기 전에 건축물의 구조, 지반 및 풍환경(風環境) 등이 건축물의 구조안전과 인접 대지의 안전에 미치는 영향 등을 평가하는 건축물 안전영향평가(이하 \"안전영향평가\"라 한다)를 안전영향평가기관에 의뢰하여 실시하여야 한다."},{"법령":"건축법","조문":"제22조제3항","원문":"③ 건축주는 제2항에 따라 사용승인을 받은 후가 아니면 건축물을 사용하거나 사용하게 할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.\n1. 허가권자가 제2항에 따른 기간 내에 사용승인서를 교부하지 아니한 경우\n2. 사용승인서를 교부받기 전에 공사가 완료된 부분이 건폐율, 용적률, 설비, 피난ㆍ방화 등 국토교통부령으로 정하는 기준에 적합한 경우로서 기간을 정하여 대통령령으로 정하는 바에 따라 임시로 사용의 승인을 한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"연면적 100제곱미터, 2층이면 제14조제1항제3호에 해당한다. 미리 신고하면 건축허가를 받은 것으로 본다."},{"번호":2,"판정":"틀림","설명":"공사시공자 등 건축관계자를 변경하는 경우는 허가가 아니라 신고한다(영 제12조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"안전영향평가는 초고층 건축물 등 대통령령으로 정하는 주요 건축물에 대해 건축허가를 하기 전에 실시한다(법 제13조의2제1항). 신고 수리의 절차가 아니다."},{"번호":4,"판정":"틀림","설명":"신고일부터 1년 이내에 공사에 착수하지 않으면 효력이 없어지고, 정당한 사유가 있으면 1년 범위에서 연장할 수 있다(법 제14조제5항). 6개월이 아니다."},{"번호":5,"판정":"틀림","설명":"신고한 건축물도 공사 완료 후 사용승인을 받은 후가 아니면 사용할 수 없다(법 제22조제1항·제3항)."}],"개념":[{"종류":"표","제목":"건축신고 대상(법 제14조제1항)","머리":["호","대상"],"행":[["1","바닥면적의 합계 85제곱미터 이내의 증축·개축·재축(3층 이상은 해당 부분 바닥면적 합계가 연면적의 10분의 1 이내)"],["2","관리지역·농림지역·자연환경보전지역에서 연면적 200제곱미터 미만이고 3층 미만인 건축(지구단위계획구역, 방재지구 등 제외)"],["3","연면적 200제곱미터 미만이고 3층 미만인 건축물의 대수선"],["4","주요구조부의 해체가 없는 등 대통령령으로 정하는 대수선"],["5","그 밖에 대통령령으로 정하는 소규모 건축물의 건축"]]},{"종류":"흐름","제목":"건축신고에서 사용승인까지","단계":[{"이름":"신고","설명":"허가 대상이어도 위 사유에 해당하면 미리 허가권자에게 신고하고, 신고하면 허가를 받은 것으로 본다(법 제14조제1항)."},{"이름":"수리 여부 통지","설명":"신고를 받은 날부터 5일 이내에 수리 여부 또는 처리기간 연장 여부를 통지한다. 심의·동의·협의 등이 필요하면 20일 이내에 통지한다(법 제14조제3항)."},{"이름":"착수 기한","설명":"신고일부터 1년 이내에 공사에 착수한다. 정당한 사유가 있으면 1년 범위에서 연장할 수 있다(법 제14조제5항)."},{"이름":"착공신고","설명":"공사에 착수하려는 건축주는 허가권자에게 공사계획을 신고하고, 허가권자는 3일 이내에 수리 여부를 통지한다(법 제21조제1항·제3항)."},{"이름":"사용승인","설명":"공사를 완료하면 사용승인을 신청해 사용승인서를 받은 후에 건축물을 사용한다(법 제22조)."}]}],"함정":"공사시공자 등 건축관계자의 변경은 신고 사항이고, 공사 착수 기한은 신고일부터 1년이다. 건축신고로 허가가 의제되어도 사용승인은 받아야 한다."}},{"i":"S4-2-1-공법-27","r":"S4","g":2,"c":2,"n":67,"s":"공법","q":"甲은 A도 B군에서 판매시설로 사용승인을 받은 바닥면적의 합계가 2천제곱미터인 건축물의 용도를 변경하려고 한다. 건축법령상 이에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["전체를 문화 및 집회시설로 용도를 변경하려는 경우에는 용도변경 허가를 받아야 한다.","전체를 업무시설로 용도를 변경하려는 경우에는 용도변경 신고를 하여야 한다.","甲이 바닥면적의 합계 1천제곱미터의 부분에 대해서만 교육연구시설로 용도를 변경하는 경우에는 사용승인을 받아야 한다.","전체를 제2종 근린생활시설(다중생활시설은 제외)로 용도를 변경하려는 경우에는 용도변경 허가를 받아야 한다.","A도지사는 도시ㆍ군계획에 특히 필요하다고 인정하면 B군수의 용도변경허가를 제한할 수 있다."],"a":[4],"L":"공4-2","o":"변형","x":{"한줄":"판매시설은 영업시설군이고 제2종 근린생활시설은 번호가 더 큰 근린생활시설군이어서 하위군으로의 변경이므로 허가가 아니라 신고 대상이다.","근거":[{"법령":"건축법","조문":"제19조제2항","원문":"② 제22조에 따라 사용승인을 받은 건축물의 용도를 변경하려는 자는 다음 각 호의 구분에 따라 국토교통부령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장의 허가를 받거나 신고를 하여야 한다.\n1. 허가 대상: 제4항 각 호의 어느 하나에 해당하는 시설군(施設群)에 속하는 건축물의 용도를 상위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 작은 시설군을 말한다)에 해당하는 용도로 변경하는 경우\n2. 신고 대상: 제4항 각 호의 어느 하나에 해당하는 시설군에 속하는 건축물의 용도를 하위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 큰 시설군을 말한다)에 해당하는 용도로 변경하는 경우"},{"법령":"건축법","조문":"제19조제4항","원문":"④ 시설군은 다음 각 호와 같고 각 시설군에 속하는 건축물의 세부 용도는 대통령령으로 정한다.\n1. 자동차 관련 시설군\n2. 산업 등의 시설군\n3. 전기통신시설군\n4. 문화 및 집회시설군\n5. 영업시설군\n6. 교육 및 복지시설군\n7. 근린생활시설군\n8. 주거업무시설군\n9. 그 밖의 시설군"},{"법령":"건축법 시행령","조문":"제14조제5항","원문":"⑤ 법 제19조제4항 각 호의 시설군에 속하는 건축물의 용도는 다음 각 호와 같다.\n1. 자동차 관련 시설군\n자동차 관련 시설\n2. 산업 등 시설군\n가. 운수시설\n나. 창고시설\n다. 공장\n라. 위험물저장 및 처리시설\n마. 자원순환 관련 시설\n바. 묘지 관련 시설\n사. 장례시설\n3. 전기통신시설군\n가. 방송통신시설\n나. 발전시설\n4. 문화집회시설군\n가. 문화 및 집회시설\n나. 종교시설\n다. 위락시설\n라. 관광휴게시설\n5. 영업시설군\n가. 판매시설\n나. 운동시설\n다. 숙박시설\n라. 제2종 근린생활시설 중 다중생활시설\n6. 교육 및 복지시설군\n가. 의료시설\n나. 교육연구시설\n다. 노유자시설(老幼者施設)\n라. 수련시설\n마. 야영장 시설\n7. 근린생활시설군\n가. 제1종 근린생활시설\n나. 제2종 근린생활시설(다중생활시설은 제외한다)\n8. 주거업무시설군\n가. 단독주택\n나. 공동주택\n다. 업무시설\n라. 교정시설\n마. 국방ㆍ군사시설\n9. 그 밖의 시설군\n가. 동물 및 식물 관련 시설\n나. 삭제"},{"법령":"건축법","조문":"제19조제5항","원문":"⑤ 제2항에 따른 허가나 신고 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 100제곱미터 이상인 경우의 사용승인에 관하여는 제22조를 준용한다. 다만, 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 미만으로서 대수선에 해당되는 공사를 수반하지 아니하는 경우에는 그러하지 아니하다."},{"법령":"건축법","조문":"제18조제2항","원문":"② 특별시장ㆍ광역시장ㆍ도지사는 지역계획이나 도시ㆍ군계획에 특히 필요하다고 인정하면 시장ㆍ군수ㆍ구청장의 건축허가나 허가를 받은 건축물의 착공을 제한할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"판매시설(영업시설군, 5)에서 문화 및 집회시설(문화집회시설군, 4)로 바꾸는 것은 번호가 작은 상위군으로의 변경이라 허가 대상이다(법 제19조제2항제1호)."},{"번호":2,"판정":"옳음","설명":"업무시설은 주거업무시설군(8)이다. 번호가 큰 하위군으로의 변경이라 신고 대상이다(법 제19조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"교육연구시설(6)로의 변경은 신고 대상이다. 변경 부분이 100제곱미터 이상이면 사용승인 규정을 준용하고, 500제곱미터 미만이면서 대수선을 수반하지 않는 경우만 제외된다. 1천제곱미터이므로 사용승인을 받는다(법 제19조제5항)."},{"번호":4,"판정":"틀림","설명":"제2종 근린생활시설(다중생활시설 제외)은 근린생활시설군(7)이다. 영업시설군(5)에서 하위군으로의 변경이므로 신고 대상이다(법 제19조제2항제2호)."},{"번호":5,"판정":"옳음","설명":"용도변경에는 법 제18조가 준용된다(법 제19조제7항). 시·도지사는 지역계획이나 도시·군계획에 특히 필요하면 시장·군수·구청장의 허가를 제한할 수 있다(법 제18조제2항)."}],"개념":[{"종류":"표","제목":"건축물 용도 시설군(영 제14조제5항)","머리":["번호","시설군","용도"],"행":[["1","자동차 관련 시설군","자동차 관련 시설"],["2","산업 등 시설군","운수시설, 창고시설, 공장, 위험물저장 및 처리시설, 자원순환 관련 시설, 묘지 관련 시설, 장례시설"],["3","전기통신시설군","방송통신시설, 발전시설"],["4","문화집회시설군","문화 및 집회시설, 종교시설, 위락시설, 관광휴게시설"],["5","영업시설군","판매시설, 운동시설, 숙박시설, 제2종 근린생활시설 중 다중생활시설"],["6","교육 및 복지시설군","의료시설, 교육연구시설, 노유자시설, 수련시설, 야영장 시설"],["7","근린생활시설군","제1종 근린생활시설, 제2종 근린생활시설(다중생활시설 제외)"],["8","주거업무시설군","단독주택, 공동주택, 업무시설, 교정시설, 국방·군사시설"],["9","그 밖의 시설군","동물 및 식물 관련 시설"]]},{"종류":"흐름","제목":"용도변경 절차 판단","단계":[{"이름":"시설군 확인","설명":"변경 전후 용도가 속한 시설군을 확인한다(법 제19조제4항, 영 제14조제5항)."},{"이름":"같은 시설군","설명":"건축물대장 기재내용의 변경을 신청한다. 대통령령으로 정하는 변경은 신청도 필요 없다(법 제19조제3항)."},{"이름":"상위군으로 변경","설명":"번호가 작은 시설군으로 바꾸면 허가를 받는다(법 제19조제2항제1호)."},{"이름":"하위군으로 변경","설명":"번호가 큰 시설군으로 바꾸면 신고한다(법 제19조제2항제2호)."},{"이름":"사용승인","설명":"변경 부분이 100제곱미터 이상이면 사용승인 규정을 준용한다. 500제곱미터 미만이고 대수선을 수반하지 않으면 제외한다(법 제19조제5항)."},{"이름":"설계","설명":"허가 대상으로 변경 부분이 500제곱미터 이상이면 건축물의 설계에 관한 제23조를 준용한다(법 제19조제6항)."}]}],"함정":"허가와 신고는 변경 전 시설군 번호보다 작은 군으로 가는지, 큰 군으로 가는지로 갈린다. 판매시설(5군)에서 문화집회시설군(4군)으로는 허가, 교육 및 복지(6군)·근린생활(7군)·주거업무(8군)로는 신고다."}},{"i":"S4-2-1-공법-28","r":"S4","g":2,"c":2,"n":68,"s":"공법","q":"건축법령상 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 신고하고 축조하여야 하는 공작물에 해당하는 것은? (단, 건축물과 분리하여 축조하는 경우이며, 공용건축물에 대한 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["높이 5미터의 굴뚝","높이 7미터의 고가수조(高架水槽)","높이 2미터의 담장","높이 5미터의 ｢재생에너지 개발ㆍ이용ㆍ보급 촉진법｣ 제2조제2호가목에 따른 태양에너지를 이용하는 발전설비","높이 5미터의 광고탑"],"a":[5],"L":"공4-2","o":"변형","x":{"한줄":"장식탑·기념탑·첨탑·광고탑·광고판은 높이 4미터를 넘으면 신고 대상이므로 높이 5미터의 광고탑이 해당한다.","근거":[{"법령":"건축법","조문":"제83조제1항","원문":"① 대지를 조성하기 위한 옹벽, 굴뚝, 광고탑, 고가수조(高架水槽), 지하 대피호, 그 밖에 이와 유사한 것으로서 대통령령으로 정하는 공작물을 축조하려는 자는 대통령령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 신고하여야 한다."},{"법령":"건축법 시행령","조문":"제118조제1항","원문":"① 법 제83조제1항에 따라 공작물을 축조(건축물과 분리하여 축조하는 것을 말한다. 이하 이 조에서 같다)할 때 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 신고를 해야 하는 공작물은 다음 각 호와 같다.\n1. 높이 6미터를 넘는 굴뚝\n2. 삭제\n3. 높이 4미터를 넘는 장식탑, 기념탑, 첨탑, 광고탑, 광고판, 그 밖에 이와 비슷한 것\n4. 높이 8미터를 넘는 고가수조나 그 밖에 이와 비슷한 것\n5. 높이 2미터를 넘는 옹벽 또는 담장\n6. 바닥면적 30제곱미터를 넘는 지하대피호\n7. 높이 6미터를 넘는 골프연습장 등의 운동시설을 위한 철탑, 주거지역ㆍ상업지역에 설치하는 통신용 철탑, 그 밖에 이와 비슷한 것\n8. 높이 8미터(위험을 방지하기 위한 난간의 높이는 제외한다) 이하의 기계식 주차장 및 철골 조립식 주차장(바닥면이 조립식이 아닌 것을 포함한다)으로서 외벽이 없는 것\n9. 건축조례로 정하는 제조시설, 저장시설(시멘트사일로를 포함한다), 유희시설, 그 밖에 이와 비슷한 것\n10. 건축물의 구조에 심대한 영향을 줄 수 있는 중량물로서 건축조례로 정하는 것\n11. 높이 5미터를 넘는 「재생에너지 개발ㆍ이용ㆍ보급 촉진법」 제2조제2호가목에 따른 태양에너지를 이용하는 발전설비와 그 밖에 이와 비슷한 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"굴뚝은 높이 6미터를 넘어야 신고 대상이다(영 제118조제1항제1호). 5미터는 해당하지 않는다."},{"번호":2,"판정":"틀림","설명":"고가수조는 높이 8미터를 넘어야 한다(영 제118조제1항제4호). 7미터는 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"옹벽 또는 담장은 높이 2미터를 넘어야 한다(영 제118조제1항제5호). 2미터는 넘지 않는다."},{"번호":4,"판정":"틀림","설명":"태양에너지 발전설비는 높이 5미터를 넘어야 한다(영 제118조제1항제11호). 5미터는 넘지 않는다."},{"번호":5,"판정":"옳음","설명":"광고탑은 영 제118조제1항제3호에 따라 높이 4미터를 넘으면 신고 대상이다."}],"개념":[{"종류":"표","제목":"신고 대상 공작물(영 제118조제1항)","머리":["호","공작물","기준"],"행":[["1","굴뚝","높이 6미터 초과"],["3","장식탑, 기념탑, 첨탑, 광고탑, 광고판 등","높이 4미터 초과"],["4","고가수조 등","높이 8미터 초과"],["5","옹벽 또는 담장","높이 2미터 초과"],["6","지하대피호","바닥면적 30제곱미터 초과"],["7","골프연습장 등 운동시설용 철탑, 주거지역·상업지역의 통신용 철탑 등","높이 6미터 초과"],["8","기계식 주차장 및 철골 조립식 주차장으로서 외벽이 없는 것","높이 8미터 이하(위험 방지용 난간 높이 제외)"],["9~10","건축조례로 정하는 제조시설·저장시설·유희시설, 구조에 심대한 영향을 주는 중량물","건축조례로 정하는 것"],["11","태양에너지 발전설비 등","높이 5미터 초과"]]},{"종류":"흐름","제목":"공작물 축조신고 절차","단계":[{"이름":"신고서 제출","설명":"공작물 축조신고서와 국토교통부령으로 정하는 설계도서를 시장·군수·구청장 등에게 제출한다(영 제118조제2항)."},{"이름":"건축법 규정 준용","설명":"법 제14조, 제21조제5항, 제29조, 제40조제4항 등을 준용한다. 옥외광고물법에 따라 허가·신고한 제3호 공작물은 법 제14조를 준용하지 않는다(영 제118조제3항)."},{"이름":"관리대장","설명":"신고를 받으면 공작물 관리대장에 내용을 작성·관리하며, 특별한 사유가 없으면 전자적 방법으로 한다(영 제118조제5항·제6항)."}]}],"함정":"신고 기준은 6미터·4미터·8미터·2미터·5미터 모두 「넘는」 높이다. 경계값과 같은 5미터 굴뚝(6미터 기준)이나 2미터 담장은 신고 대상이 아니다. 기념탑 등은 4미터, 태양에너지 발전설비는 5미터로 기준이 다르다.","개정":"영 제118조제1항 제2호는 2020.12.15 삭제되어, 기념탑·장식탑·첨탑·광고탑·광고판은 현행 제3호에서 높이 4미터를 넘는 것이 신고 대상이다. 이 항은 2026.8.18에도 개정 표시가 있다."}},{"i":"S4-2-1-공법-29","r":"S4","g":2,"c":2,"n":69,"s":"공법","q":"건축법령상 공개공지등에 관한 설명으로 옳은 것은? (단, 건축법령상 특례, 기타 강화ㆍ완화조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["노후 산업단지의 정비가 필요하다고 인정되어 지정ㆍ공고된 지역에는 공개공지등을 설치할 수 없다.","공개 공지는 필로티의 구조로 설치할 수 없다.","공개공지등을 설치할 때에는 모든 사람들이 환경친화적으로 편리하게 이용할 수 있도록 긴 의자 또는 조경시설 등 건축조례로 정하는 시설을 설치해야 한다.","공개공지등에는 건축조례로 정하는 바에 따라 연간 최장 90일의 기간 동안 주민들을 위한 문화행사를 열거나 판촉활동을 할 수 있다.","울타리나 담장 등 시설의 설치 또는 출입구의 폐쇄 등을 통하여 공개공지등의 출입을 제한한 경우 지체 없이 관할 시장ㆍ군수ㆍ구청장에게 신고하여야 한다."],"a":[3],"L":"공4-3","o":"기출","x":{"한줄":"공개공지등을 설치할 때는 긴 의자 또는 조경시설 등 건축조례로 정하는 시설을 설치해야 한다.","근거":[{"법령":"건축법 시행령","조문":"제27조의2제3항","원문":"③ 제1항에 따라 공개공지등을 설치할 때에는 모든 사람들이 환경친화적으로 편리하게 이용할 수 있도록 긴 의자 또는 조경시설 등 건축조례로 정하는 시설을 설치해야 한다."},{"법령":"건축법","조문":"제43조제1항제4호","원문":"① 다음 각 호의 어느 하나에 해당하는 지역의 환경을 쾌적하게 조성하기 위하여 대통령령으로 정하는 용도와 규모의 건축물은 일반이 사용할 수 있도록 대통령령으로 정하는 기준에 따라 소규모 휴식시설 등의 공개 공지(空地: 공터) 또는 공개 공간(이하 \"공개공지등\"이라 한다)을 설치하여야 한다.\n4. 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 도시화의 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정하여 지정ㆍ공고하는 지역"},{"법령":"건축법 시행령","조문":"제27조의2제1항","원문":"① 법 제43조제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물의 대지에는 공개 공지 또는 공개 공간(이하 이 조에서 \"공개공지등\"이라 한다)을 설치해야 한다. 이 경우 공개 공지는 필로티의 구조로 설치할 수 있다."},{"법령":"건축법 시행령","조문":"제27조의2제6항","원문":"⑥ 공개공지등에는 연간 60일 이내의 기간 동안 건축조례로 정하는 바에 따라 주민들을 위한 문화행사를 열거나 판촉활동을 할 수 있다. 다만, 울타리를 설치하는 등 공중이 해당 공개공지등을 이용하는데 지장을 주는 행위를 해서는 아니 된다."},{"법령":"건축법","조문":"제43조제4항","원문":"④ 누구든지 공개공지등에 물건을 쌓아놓거나 출입을 차단하는 시설을 설치하는 등 공개공지등의 활용을 저해하는 행위를 하여서는 아니 된다."},{"법령":"건축법 시행령","조문":"제27조의2제7항","원문":"⑦ 법 제43조제4항에 따라 제한되는 행위는 다음 각 호와 같다.\n3. 울타리나 담장 등의 시설을 설치하거나 출입구를 폐쇄하는 등 공개공지등의 출입을 차단하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"특별자치시장·시장·군수·구청장이 도시화 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정해 지정·공고한 지역도 설치 대상 지역이다(법 제43조제1항제4호)."},{"번호":2,"판정":"틀림","설명":"공개 공지는 필로티의 구조로 설치할 수 있다(영 제27조의2제1항 후단)."},{"번호":3,"판정":"옳음","설명":"영 제27조의2제3항에 있는 내용이다."},{"번호":4,"판정":"틀림","설명":"문화행사나 판촉활동은 연간 60일 이내의 기간 동안 할 수 있다(영 제27조의2제6항). 90일이 아니다."},{"번호":5,"판정":"틀림","설명":"울타리나 담장을 설치하거나 출입구를 폐쇄해 출입을 차단하는 행위는 신고 대상이 아니라 제한되는 행위다(법 제43조제4항, 영 제27조의2제7항제3호)."}],"개념":[{"종류":"표","제목":"공개공지등 설치 대상(법 제43조제1항, 영 제27조의2제1항·제2항)","머리":["구분","내용"],"행":[["대상 지역","일반주거지역·준주거지역, 상업지역, 준공업지역, 시장·군수·구청장이 도시화 가능성이 크거나 노후 산업단지 정비가 필요하다고 인정해 지정·공고하는 지역"],["대상 건축물","문화 및 집회시설, 종교시설, 판매시설(농수산물유통시설 제외), 운수시설(여객용 시설만), 업무시설, 숙박시설로서 해당 용도 바닥면적 합계 5천제곱미터 이상"],["그 밖의 건축물","그 밖에 다중이 이용하는 시설로서 건축조례로 정하는 건축물"],["면적","대지면적의 100분의 10 이하의 범위에서 건축조례로 정함"],["설치 방식","공개 공지는 필로티 구조로 설치 가능"]]},{"종류":"표","제목":"공개공지등의 이용·완화·제한(영 제27조의2제3항·제4항·제6항·제7항)","머리":["구분","내용"],"행":[["설치 시설","긴 의자 또는 조경시설 등 건축조례로 정하는 시설"],["건축기준 완화","용적률은 해당 지역 용적률의 1.2배 이하, 높이 제한은 해당 건축물 높이기준의 1.2배 이하"],["문화행사·판촉활동","연간 60일 이내, 건축조례로 정하는 바에 따름. 울타리 설치 등 공중의 이용에 지장을 주는 행위 금지"],["제한되는 행위","일정 공간을 점유한 영업, 시설 외 물건·시설물 설치, 물건 적치, 울타리·담장 설치나 출입구 폐쇄로 출입 차단, 시설 훼손 등"]]}],"함정":"문화행사·판촉활동은 연간 60일 이내다. 출입 차단은 신고하면 되는 행위가 아니라 금지되는 행위다. 필로티 설치는 허용되고, 노후 산업단지 정비가 필요해 지정·공고한 지역도 설치 대상 지역이다."}},{"i":"S4-2-1-공법-30","r":"S4","g":2,"c":2,"n":70,"s":"공법","q":"건축법령상 건축허가 대상 건축물로서 내진능력을 공개하여야 하는 건축물에 해당하지 않는 것은? (단, 소규모건축구조기준을 적용한 건축물이 아님)","b":null,"bs":"없음","img":[],"ch":["높이가 13미터인 건축물","처마높이가 9미터인 건축물","기둥과 기둥 사이의 거리가 10미터인 건축물","건축물의 용도 및 규모를 고려한 중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물","국가적 문화유산으로 보존할 가치가 있는 것으로 문화체육관광부령으로 정하는 건축물"],"a":[5],"L":"공4-3","o":"기출","x":{"한줄":"국가적 문화유산 건축물은 국토교통부령으로 정하는 것이 대상이어서 문화체육관광부령으로 정한다는 5번은 해당하지 않는다.","근거":[{"법령":"건축법","조문":"제48조의3제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 건축물을 건축하고자 하는 자는 제22조에 따른 사용승인을 받는 즉시 건축물이 지진 발생 시에 견딜 수 있는 능력(이하 \"내진능력\"이라 한다)을 공개하여야 한다. 다만, 제48조제2항에 따른 구조안전 확인 대상 건축물이 아니거나 내진능력 산정이 곤란한 건축물로서 대통령령으로 정하는 건축물은 공개하지 아니한다.\n1. 층수가 2층[주요구조부인 기둥과 보를 설치하는 건축물로서 그 기둥과 보가 목재인 목구조 건축물(이하 \"목구조 건축물\"이라 한다)의 경우에는 3층] 이상인 건축물\n2. 연면적이 200제곱미터(목구조 건축물의 경우에는 500제곱미터) 이상인 건축물\n3. 그 밖에 건축물의 규모와 중요도를 고려하여 대통령령으로 정하는 건축물"},{"법령":"건축법 시행령","조문":"제32조의2","원문":"제32조의2(건축물의 내진능력 공개)\n① 법 제48조의3제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 건축물\"이란 다음 각 호의 어느 하나에 해당하는 건축물을 말한다.\n1. 창고, 축사, 작물 재배사 및 표준설계도서에 따라 건축하는 건축물로서 제32조제2항제1호 및 제3호부터 제9호까지의 어느 하나에도 해당하지 아니하는 건축물\n2. 제32조제1항에 따른 구조기준 중 국토교통부령으로 정하는 소규모건축구조기준을 적용한 건축물\n② 법 제48조의3제1항제3호에서 \"대통령령으로 정하는 건축물\"이란 제32조제2항제3호부터 제9호까지의 어느 하나에 해당하는 건축물을 말한다."},{"법령":"건축법 시행령","조문":"제32조제2항","원문":"② 제1항에 따라 구조 안전을 확인한 건축물 중 다음 각 호의 어느 하나에 해당하는 건축물의 건축주는 해당 건축물의 설계자로부터 구조 안전의 확인 서류를 받아 법 제21조에 따른 착공신고를 하는 때에 그 확인 서류를 허가권자에게 제출하여야 한다. 다만, 표준설계도서에 따라 건축하는 건축물은 제외한다.\n1. 층수가 2층[주요구조부인 기둥과 보를 설치하는 건축물로서 그 기둥과 보가 목재인 목구조 건축물(이하 \"목구조 건축물\"이라 한다)의 경우에는 3층] 이상인 건축물\n2. 연면적이 200제곱미터(목구조 건축물의 경우에는 500제곱미터) 이상인 건축물. 다만, 창고, 축사, 작물 재배사는 제외한다.\n3. 높이가 13미터 이상인 건축물\n4. 처마높이가 9미터 이상인 건축물\n5. 기둥과 기둥 사이의 거리가 10미터 이상인 건축물\n6. 건축물의 용도 및 규모를 고려한 중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물\n7. 국가적 문화유산으로 보존할 가치가 있는 건축물로서 국토교통부령으로 정하는 것\n8. 제2조제18호가목, 다목 및 라목의 건축물\n9. 별표 1 제1호의 단독주택 및 같은 표 제2호의 공동주택"}],"선지":[{"번호":1,"판정":"옳음","설명":"높이 13미터 이상은 영 제32조제2항제3호로 내진능력 공개 대상이다(영 제32조의2제2항)."},{"번호":2,"판정":"옳음","설명":"처마높이 9미터 이상은 제4호로 공개 대상이다."},{"번호":3,"판정":"옳음","설명":"기둥과 기둥 사이의 거리 10미터 이상은 제5호로 공개 대상이다."},{"번호":4,"판정":"옳음","설명":"중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물은 제6호로 공개 대상이다."},{"번호":5,"판정":"틀림","설명":"제7호의 국가적 문화유산 건축물은 국토교통부령으로 정하는 것이다. 문화체육관광부령으로 정하는 건축물은 대상이 아니다."}],"개념":[{"종류":"표","제목":"구조 안전 확인 서류 제출 대상(영 제32조제2항)","머리":["호","건축물"],"행":[["1","층수 2층(목구조 건축물은 3층) 이상"],["2","연면적 200제곱미터(목구조 500제곱미터) 이상. 창고, 축사, 작물 재배사 제외"],["3","높이 13미터 이상"],["4","처마높이 9미터 이상"],["5","기둥과 기둥 사이의 거리 10미터 이상"],["6","중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물"],["7","국가적 문화유산으로 보존할 가치가 있는 건축물로서 국토교통부령으로 정하는 것"],["8","영 제2조제18호가목·다목·라목의 건축물"],["9","단독주택, 공동주택"]]},{"종류":"표","제목":"내진능력 공개(법 제48조의3, 영 제32조의2)","머리":["구분","내용"],"행":[["공개 시기","사용승인을 받는 즉시"],["법에서 정한 대상","층수 2층(목구조 3층) 이상, 연면적 200제곱미터(목구조 500제곱미터) 이상"],["영으로 정한 대상(법 제48조의3제1항제3호)","영 제32조제2항제3호부터 제9호까지의 건축물"],["공개하지 않는 건축물","구조안전 확인 대상이 아닌 건축물, 내진능력 산정이 곤란한 건축물로서 영 제32조의2제1항에서 정한 것(창고·축사·작물 재배사·표준설계도서 건축물 중 제32조제2항 해당 호가 없는 것, 소규모건축구조기준 적용 건축물)"],["산정 기준·공개 방법","국토교통부령"]]}],"함정":"공개 대상은 법의 층수·연면적 기준에 영 제32조제2항제3호~제9호가 더해진다. 선지 문장의 수치(13미터, 9미터, 10미터)는 모두 맞고 5번만 위임 주체가 국토교통부령에서 문화체육관광부령으로 바뀌어 있다."}},{"i":"S4-2-1-공법-31","r":"S4","g":2,"c":2,"n":71,"s":"공법","q":"건축법령상 특별건축구역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국토교통부장관은 지방자치단체가 국제행사 등을 개최하는 지역의 사업구역을 특별건축구역으로 지정할 수 있다.","｢도로법｣에 따른 접도구역은 특별건축구역으로 지정될 수 없다.","특별건축구역에서의 건축기준의 특례사항은 지방자치단체가 건축하는 건축물에는 적용되지 않는다.","특별건축구역에서 ｢주차장법｣에 따른 부설주차장의 설치에 관한 규정은 개별 건축물마다 적용하여야 한다.","특별건축구역을 지정한 경우에는 ｢국토의 계획 및 이용에 관한 법률｣에 따른 용도지역ㆍ지구ㆍ구역의 지정이 있는 것으로 본다."],"a":[2],"L":"공4-4","o":"기출","x":{"한줄":"도로법에 따른 접도구역은 특별건축구역으로 지정할 수 없다.","근거":[{"법령":"건축법","조문":"제69조제2항","원문":"② 다음 각 호의 어느 하나에 해당하는 지역ㆍ구역 등에 대하여는 제1항에도 불구하고 특별건축구역으로 지정할 수 없다.\n1. 「개발제한구역의 지정 및 관리에 관한 특별조치법」에 따른 개발제한구역\n2. 「자연공원법」에 따른 자연공원\n3. 「도로법」에 따른 접도구역\n4. 「산지관리법」에 따른 보전산지\n5. 삭제"},{"법령":"건축법","조문":"제69조제1항","원문":"① 국토교통부장관 또는 시ㆍ도지사는 다음 각 호의 구분에 따라 도시나 지역의 일부가 특별건축구역으로 특례 적용이 필요하다고 인정하는 경우에는 특별건축구역을 지정할 수 있다.\n1. 국토교통부장관이 지정하는 경우\n가. 국가가 국제행사 등을 개최하는 도시 또는 지역의 사업구역\n나. 관계법령에 따른 국가정책사업으로서 대통령령으로 정하는 사업구역\n2. 시ㆍ도지사가 지정하는 경우\n가. 지방자치단체가 국제행사 등을 개최하는 도시 또는 지역의 사업구역\n나. 관계법령에 따른 도시개발ㆍ도시재정비 및 건축문화 진흥사업으로서 건축물 또는 공간환경을 조성하기 위하여 대통령령으로 정하는 사업구역\n다. 그 밖에 대통령령으로 정하는 도시 또는 지역의 사업구역"},{"법령":"건축법","조문":"제70조","원문":"제70조(특별건축구역의 건축물) 특별건축구역에서 제73조에 따라 건축기준 등의 특례사항을 적용하여 건축할 수 있는 건축물은 다음 각 호의 어느 하나에 해당되어야 한다.\n1. 국가 또는 지방자치단체가 건축하는 건축물\n2. 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관 중 대통령령으로 정하는 공공기관이 건축하는 건축물\n3. 그 밖에 대통령령으로 정하는 용도ㆍ규모의 건축물로서 도시경관의 창출, 건설기술 수준향상 및 건축 관련 제도개선을 위하여 특례 적용이 필요하다고 허가권자가 인정하는 건축물"},{"법령":"건축법","조문":"제74조제1항","원문":"① 특별건축구역에서는 다음 각 호의 관계 법령의 규정에 대하여는 개별 건축물마다 적용하지 아니하고 특별건축구역 전부 또는 일부를 대상으로 통합하여 적용할 수 있다.\n1. 「문화예술진흥법」 제9조에 따른 건축물에 대한 미술작품의 설치\n2. 「주차장법」 제19조에 따른 부설주차장의 설치\n3. 「도시공원 및 녹지 등에 관한 법률」에 따른 공원의 설치"},{"법령":"건축법","조문":"제71조제11항","원문":"⑪ 특별건축구역을 지정하거나 변경한 경우에는 「국토의 계획 및 이용에 관한 법률」 제30조에 따른 도시ㆍ군관리계획의 결정(용도지역ㆍ지구ㆍ구역의 지정 및 변경은 제외한다)이 있는 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지방자치단체가 국제행사 등을 개최하는 사업구역은 시·도지사가 지정한다(법 제69조제1항제2호가목). 국토교통부장관은 국가가 개최하는 경우다."},{"번호":2,"판정":"옳음","설명":"법 제69조제2항제3호에 접도구역이 지정 제외 지역으로 열거된다."},{"번호":3,"판정":"틀림","설명":"국가 또는 지방자치단체가 건축하는 건축물은 특례를 적용할 수 있는 건축물이다(법 제70조제1호)."},{"번호":4,"판정":"틀림","설명":"부설주차장 설치 규정은 개별 건축물마다 적용하지 않고 특별건축구역 전부 또는 일부를 대상으로 통합하여 적용할 수 있다(법 제74조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"지정하면 도시·군관리계획의 결정이 있는 것으로 보지만, 용도지역·지구·구역의 지정 및 변경은 제외한다(법 제71조제11항)."}],"개념":[{"종류":"표","제목":"특별건축구역 지정권자와 지정 제외 지역(법 제69조)","머리":["구분","내용"],"행":[["국토교통부장관 지정","국가가 국제행사 등을 개최하는 도시·지역의 사업구역, 국가정책사업으로서 대통령령으로 정하는 사업구역"],["시·도지사 지정","지방자치단체가 국제행사 등을 개최하는 사업구역, 도시개발·도시재정비 및 건축문화 진흥사업으로서 대통령령으로 정하는 사업구역, 그 밖에 대통령령으로 정하는 사업구역"],["지정 불가","개발제한구역, 자연공원, 접도구역, 보전산지"],["군사시설보호구역","지정하려는 지역이 군사기지 및 군사시설 보호구역이면 국방부장관과 사전 협의"],["특례 적용 건축물(법 제70조)","국가·지방자치단체가 건축하는 건축물, 대통령령으로 정하는 공공기관이 건축하는 건축물, 대통령령으로 정하는 용도·규모로서 허가권자가 특례 필요를 인정하는 건축물"]]},{"종류":"흐름","제목":"특별건축구역 지정 절차(법 제71조)","단계":[{"이름":"지정 신청","설명":"중앙행정기관의 장·시·도지사는 국토교통부장관에게, 시장·군수·구청장은 특별시장·광역시장·도지사에게 자료를 갖춰 신청한다(제1항)."},{"이름":"지정 제안","설명":"신청기관 외의 자는 시·도지사가 지정하는 사업구역에 대해 시·도지사에게 제안할 수 있다(제2항)."},{"이름":"건축위원회 심의","설명":"지정신청을 받은 날부터 30일 이내에 건축위원회 심의를 거친다(제4항)."},{"이름":"고시","설명":"지정·변경·해제 시 관보(시·도지사는 공보)에 고시한다(제7항)."},{"이름":"지정 효과","설명":"도시·군관리계획 결정이 있는 것으로 본다. 용도지역·지구·구역의 지정과 변경은 제외한다(제11항)."},{"이름":"해제","설명":"지정일부터 5년 이내에 목적에 부합하는 건축물의 착공이 없으면 해제할 수 있다(제10항제3호)."}]}],"함정":"지방자치단체가 개최하는 국제행사 구역은 시·도지사 지정이다. 5번은 용도지역·지구·구역 지정까지 의제되는 것처럼 바꾼 문장인데 법은 이를 제외한다. 부설주차장·미술작품·공원 규정은 통합 적용이 가능하다."}},{"i":"S4-2-1-공법-32","r":"S4","g":2,"c":2,"n":72,"s":"공법","q":"주택법령상 세대구분형 공동주택에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["사업계획의 승인을 받아 건설하는 세대구분형 공동주택의 세대수는 해당 주택단지 안의 공동주택 전체 세대수의 2분의 1을 넘지 않아야 한다.","｢공동주택관리법｣에 따른 행위허가를 받거나 신고하고 설치하는 세대구분형 공동주택의 구분된 공간의 세대수는 기존 세대를 포함하여 2세대 이하여야 한다.","사업계획의 승인을 받아 건설하는 세대구분형 공동주택은 하나의 세대가 통합하여 사용할 수 있도록 세대 간에 연결문 또는 경량구조의 경계벽 등을 설치하여야 한다.","｢공동주택관리법｣에 따른 행위허가를 받거나 신고하고 설치하는 세대구분형 공동주택은 세대별로 구분된 각각의 공간마다 별도의 욕실, 부엌과 구분 출입문을 설치하여야 한다.","주택건설기준 등을 적용하는 경우 세대구분형 공동주택의 세대수는 그 구분된 공간의 세대수에 관계없이 하나의 세대로 산정한다."],"a":[1],"L":"공5-1","o":"변형","x":{"한줄":"사업계획승인형 세대구분형 공동주택은 세대수가 주택단지 안 공동주택 전체 세대수의 3분의 1을 넘지 않아야 하며 2분의 1이 아니다.","근거":[{"법령":"주택법 시행령","조문":"제9조제1항","원문":"① 법 제2조제19호에서 \"대통령령으로 정하는 건설기준, 설치기준, 면적기준 등에 적합한 주택\"이란 다음 각 호의 구분에 따른 요건을 충족하는 공동주택을 말한다.\n1. 법 제15조에 따른 사업계획의 승인을 받아 건설하는 공동주택의 경우: 다음 각 목의 요건을 모두 충족할 것\n가. 세대별로 구분된 각각의 공간마다 별도의 욕실, 부엌과 현관을 설치할 것\n나. 하나의 세대가 통합하여 사용할 수 있도록 세대 간에 연결문 또는 경량구조의 경계벽 등을 설치할 것\n다. 세대구분형 공동주택의 세대수가 해당 주택단지 안의 공동주택 전체 세대수의 3분의 1을 넘지 않을 것\n라. 세대별로 구분된 각각의 공간의 주거전용면적(주거의 용도로만 쓰이는 면적으로서 법 제2조제6호 후단에 따른 방법으로 산정된 것을 말한다. 이하 같다) 합계가 해당 주택단지 전체 주거전용면적 합계의 3분의 1을 넘지 않는 등 국토교통부장관이 정하여 고시하는 주거전용면적의 비율에 관한 기준을 충족할 것\n2. 「공동주택관리법」 제35조에 따른 행위의 허가를 받거나 신고를 하고 설치하는 공동주택의 경우: 다음 각 목의 요건을 모두 충족할 것\n가. 구분된 공간의 세대수는 기존 세대를 포함하여 2세대 이하일 것\n나. 세대별로 구분된 각각의 공간마다 별도의 욕실, 부엌과 구분 출입문을 설치할 것\n다. 세대구분형 공동주택의 세대수가 해당 주택단지 안의 공동주택 전체 세대수의 10분의 1과 해당 동의 전체 세대수의 3분의 1을 각각 넘지 않을 것. 다만, 특별자치시장, 특별자치도지사, 시장, 군수 또는 구청장(구청장은 자치구의 구청장을 말하며, 이하 \"시장ㆍ군수ㆍ구청장\"이라 한다)이 부대시설의 규모 등 해당 주택단지의 여건을 고려하여 인정하는 범위에서 세대수의 기준을 넘을 수 있다.\n라. 구조, 화재, 소방 및 피난안전 등 관계 법령에서 정하는 안전 기준을 충족할 것"},{"법령":"주택법 시행령","조문":"제9조제2항","원문":"② 제1항에 따라 건설 또는 설치되는 주택과 관련하여 법 제35조에 따른 주택건설기준 등을 적용하는 경우 세대구분형 공동주택의 세대수는 그 구분된 공간의 세대수에 관계없이 하나의 세대로 산정한다."},{"법령":"주택법","조문":"제2조제19호","원문":"19. \"세대구분형 공동주택\"이란 공동주택의 주택 내부 공간의 일부를 세대별로 구분하여 생활이 가능한 구조로 하되, 그 구분된 공간의 일부를 구분소유 할 수 없는 주택으로서 대통령령으로 정하는 건설기준, 설치기준, 면적기준 등에 적합한 주택을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"세대수가 해당 주택단지 안 공동주택 전체 세대수의 3분의 1을 넘지 않아야 한다(영 제9조제1항제1호다목)."},{"번호":2,"판정":"옳음","설명":"행위허가·신고형은 구분된 공간의 세대수가 기존 세대를 포함하여 2세대 이하여야 한다(영 제9조제1항제2호가목)."},{"번호":3,"판정":"옳음","설명":"영 제9조제1항제1호나목이다."},{"번호":4,"판정":"옳음","설명":"영 제9조제1항제2호나목이다. 사업계획승인형은 별도의 욕실, 부엌과 현관을 설치한다(제1호가목)."},{"번호":5,"판정":"옳음","설명":"영 제9조제2항이다."}],"개념":[{"종류":"비교","제목":"세대구분형 공동주택의 요건","왼쪽":{"이름":"사업계획승인형(영 제9조제1항제1호)","항목":["세대별 공간마다 별도의 욕실, 부엌과 현관","세대 간에 연결문 또는 경량구조의 경계벽 등 설치","세대수가 단지 안 공동주택 전체 세대수의 3분의 1 이하","구분된 공간의 주거전용면적 합계가 단지 전체 주거전용면적 합계의 3분의 1 이하 등 국토교통부장관 고시 기준 충족"]},"오른쪽":{"이름":"행위허가·신고형(영 제9조제1항제2호)","항목":["공동주택관리법 제35조에 따른 행위허가를 받거나 신고하고 설치","구분된 공간의 세대수는 기존 세대를 포함하여 2세대 이하","세대별 공간마다 별도의 욕실, 부엌과 구분 출입문","세대수가 단지 공동주택 전체 세대수의 10분의 1, 해당 동 전체 세대수의 3분의 1을 각각 넘지 않을 것(시장·군수·구청장이 인정하는 범위에서 초과 가능)","구조·화재·소방·피난안전 등 관계 법령의 안전 기준 충족"]}},{"종류":"표","제목":"세대구분형 공동주택의 정의와 산정","머리":["구분","내용"],"행":[["정의","공동주택의 주택 내부 공간의 일부를 세대별로 구분하여 생활이 가능한 구조로 하되, 구분된 공간의 일부를 구분소유 할 수 없는 주택(법 제2조제19호)"],["구분소유","불가"],["건설기준 위임","건설기준·설치기준·면적기준은 대통령령(영 제9조)"],["세대 산정","주택건설기준 등 적용 시 구분된 공간의 세대수와 관계없이 하나의 세대(영 제9조제2항)"]]}],"함정":"사업계획승인형은 단지 전체 세대수의 3분의 1, 행위허가·신고형은 단지 전체의 10분의 1과 해당 동의 3분의 1이다. 두 유형의 기준이 다르다.","개정":"영 제9조제1항이 2019.2.12, 2020.7.24 개정되어 사업계획승인형(제1호)과 공동주택관리법에 따른 행위허가·신고형(제2호)으로 나뉘어 규정된다."}},{"i":"S4-2-1-공법-33","r":"S4","g":2,"c":2,"n":73,"s":"공법","q":"주택법령상 주택단지가 일정한 시설로 분리된 토지는 각각 별개의 주택단지로 본다. 그 시설에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["철도","폭 20 미터의 고속도로","폭 10 미터의 일반도로","폭 20 미터의 자동차전용도로","폭 10 미터의 도시계획예정도로"],"a":[3],"L":"공5-1","o":"기출","x":{"한줄":"일반도로는 폭 20미터 이상이어야 주택단지를 나누는 시설이므로 폭 10미터의 일반도로는 해당하지 않는다.","근거":[{"법령":"주택법","조문":"제2조제12호","원문":"12. \"주택단지\"란 제15조에 따른 주택건설사업계획 또는 대지조성사업계획의 승인을 받아 주택과 그 부대시설 및 복리시설을 건설하거나 대지를 조성하는 데 사용되는 일단(一團)의 토지를 말한다. 다만, 다음 각 목의 시설로 분리된 토지는 각각 별개의 주택단지로 본다.\n가. 철도ㆍ고속도로ㆍ자동차전용도로\n나. 폭 20미터 이상인 일반도로\n다. 폭 8미터 이상인 도시계획예정도로\n라. 가목부터 다목까지의 시설에 준하는 것으로서 대통령령으로 정하는 시설"},{"법령":"주택법 시행령","조문":"제5조","원문":"제5조(주택단지의 구분기준이 되는 도로)\n① 법 제2조제12호라목에서 \"대통령령으로 정하는 시설\"이란 보행자 및 자동차의 통행이 가능한 도로로서 다음 각 호의 어느 하나에 해당하는 도로를 말한다.\n1. 「국토의 계획 및 이용에 관한 법률」 제2조제7호에 따른 도시ㆍ군계획시설(이하 \"도시ㆍ군계획시설\"이라 한다)인 도로로서 국토교통부령으로 정하는 도로\n2. 「도로법」 제10조에 따른 일반국도ㆍ특별시도ㆍ광역시도 또는 지방도\n3. 그 밖에 관계 법령에 따라 설치된 도로로서 제1호 및 제2호에 준하는 도로\n② 제1항에도 불구하고 법 제15조에 따른 사업계획승인권자(이하 \"사업계획승인권자\"라 한다)가 다음 각 호의 요건을 모두 충족한다고 인정하여 사업계획을 승인한 도로는 주택단지의 구분기준이 되는 도로에서 제외한다.\n1. 인근 주민의 통행권 확보 및 교통편의 제고 등을 위해 기존의 도로를 국토교통부령으로 정하는 기준에 적합하게 유지ㆍ변경할 것\n2. 보행자 통행의 편리성 및 안전성을 확보하기 위한 시설을 국토교통부령으로 정하는 바에 따라 설치할 것"}],"선지":[{"번호":1,"판정":"옳음","설명":"철도는 폭과 관계없이 제2조제12호가목 시설이다."},{"번호":2,"판정":"옳음","설명":"고속도로는 폭과 관계없이 가목 시설이다."},{"번호":3,"판정":"틀림","설명":"일반도로는 폭 20미터 이상이어야 나목 시설이다. 폭 10미터는 기준에 못 미친다."},{"번호":4,"판정":"옳음","설명":"자동차전용도로는 폭과 관계없이 가목 시설이다."},{"번호":5,"판정":"옳음","설명":"도시계획예정도로는 폭 8미터 이상이면 다목 시설이다. 10미터는 기준을 넘는다."}],"개념":[{"종류":"표","제목":"별개의 주택단지로 보는 분리 시설(법 제2조제12호)","머리":["목","시설","폭 기준"],"행":[["가","철도·고속도로·자동차전용도로","폭 무관"],["나","일반도로","폭 20미터 이상"],["다","도시계획예정도로","폭 8미터 이상"],["라","가목부터 다목까지에 준하는 시설로서 대통령령으로 정하는 시설","영 제5조: 도시·군계획시설인 도로로서 국토교통부령으로 정하는 도로, 일반국도·특별시도·광역시도·지방도, 그에 준하는 도로"]]},{"종류":"표","제목":"주택단지와 관련 시설의 정의(법 제2조제12호~제14호)","머리":["용어","내용"],"행":[["주택단지","사업계획승인을 받아 주택과 부대시설·복리시설을 건설하거나 대지를 조성하는 데 사용되는 일단의 토지"],["부대시설","주차장, 관리사무소, 담장 및 주택단지 안의 도로, 건축설비 등"],["복리시설","어린이놀이터, 근린생활시설, 유치원, 주민운동시설 및 경로당 등"],["제외 도로(영 제5조제2항)","사업계획승인권자가 기존 도로를 부령 기준에 맞게 유지·변경하고 보행자 안전시설을 설치한다고 인정해 사업계획을 승인한 도로"]]}],"함정":"20미터와 8미터 기준이 일반도로와 도시계획예정도로에 각각 붙는다. 일반도로 20미터를 도시계획예정도로에 적용하면 5번을 고르게 된다. 철도·고속도로·자동차전용도로는 폭을 따지지 않는다.","개정":"영 제5조제2항은 2019.7.2 신설되었다. 사업계획승인권자가 요건을 충족한다고 인정해 사업계획을 승인한 도로는 주택단지 구분기준이 되는 도로에서 제외한다."}},{"i":"S4-2-1-공법-34","r":"S4","g":2,"c":2,"n":74,"s":"공법","q":"주택법령상 사용검사에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["한국토지주택공사가 사업주체인 경우 시장ㆍ군수ㆍ구청장의 사용검사를 받아야 한다.","사업주체가 파산 등으로 사용검사를 받을 수 없는 경우에는 해당 주택의 시공을 보증한 자 또는 입주예정자는 대통령령으로 정하는 바에 따라 사용검사를 받을 수 있다.","사용검사는 그 신청일부터 15일 이내에 하여야 한다","사업주체는 구획별로 공사가 완료된 대지조성사업의 경우로서 사용검사권자의 임시 사용승인을 받은 경우에는 사용검사를 받기 전에 대지를 사용하게 할 수 있다.","사용검사권자가 임시사용을 승인하는 경우 임시 사용승인의 대상이 공동주택인 경우에는 세대별로 임시 사용승인을 할 수 있다."],"a":[1],"L":"공5-2","o":"기출","x":{"한줄":"국가 또는 한국토지주택공사가 사업주체인 경우에는 국토교통부장관의 사용검사를 받는다.","근거":[{"법령":"주택법","조문":"제49조제1항","원문":"① 사업주체는 제15조에 따른 사업계획승인을 받아 시행하는 주택건설사업 또는 대지조성사업을 완료한 경우에는 주택 또는 대지에 대하여 국토교통부령으로 정하는 바에 따라 시장ㆍ군수ㆍ구청장(국가 또는 한국토지주택공사가 사업주체인 경우와 대통령령으로 정하는 경우에는 국토교통부장관을 말한다. 이하 이 조에서 같다)의 사용검사를 받아야 한다. 다만, 제15조제3항에 따라 사업계획을 승인받은 경우에는 완공된 주택에 대하여 공구별로 사용검사(이하 \"분할 사용검사\"라 한다)를 받을 수 있고, 사업계획승인 조건의 미이행 등 대통령령으로 정하는 사유가 있는 경우에는 공사가 완료된 주택에 대하여 동별로 사용검사(이하 \"동별 사용검사\"라 한다)를 받을 수 있다."},{"법령":"주택법","조문":"제49조제3항","원문":"③ 제1항에도 불구하고 다음 각 호의 구분에 따라 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자는 대통령령으로 정하는 바에 따라 사용검사를 받을 수 있다.\n1. 사업주체가 파산 등으로 사용검사를 받을 수 없는 경우에는 해당 주택의 시공을 보증한 자 또는 입주예정자\n2. 사업주체가 정당한 이유 없이 사용검사를 위한 절차를 이행하지 아니하는 경우에는 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자. 이 경우 사용검사권자는 사업주체가 사용검사를 받지 아니하는 정당한 이유를 밝히지 못하면 사용검사를 거부하거나 지연할 수 없다."},{"법령":"주택법","조문":"제49조제4항","원문":"④ 사업주체 또는 입주예정자는 제1항에 따른 사용검사를 받은 후가 아니면 주택 또는 대지를 사용하게 하거나 이를 사용할 수 없다. 다만, 대통령령으로 정하는 경우로서 사용검사권자의 임시 사용승인을 받은 경우에는 그러하지 아니하다."},{"법령":"주택법 시행령","조문":"제54조제4항","원문":"④ 제3항에 따른 사용검사는 신청일부터 15일 이내에 하여야 한다."},{"법령":"주택법 시행령","조문":"제56조","원문":"제56조(임시 사용승인)\n① 법 제49조제4항 단서에서 \"대통령령으로 정하는 경우\"란 다음 각 호의 구분에 따른 경우를 말한다.\n1. 주택건설사업의 경우: 건축물의 동별로 공사가 완료된 경우\n2. 대지조성사업의 경우: 구획별로 공사가 완료된 경우\n② 법 제49조제4항 단서에 따른 임시 사용승인을 받으려는 자는 국토교통부령으로 정하는 바에 따라 사용검사권자에게 임시 사용승인을 신청하여야 한다.\n③ 사용검사권자는 제2항에 따른 신청을 받은 때에는 임시 사용승인대상인 주택 또는 대지가 사업계획의 내용에 적합하고 사용에 지장이 없는 경우에만 임시사용을 승인할 수 있다. 이 경우 임시 사용승인의 대상이 공동주택인 경우에는 세대별로 임시 사용승인을 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가 또는 한국토지주택공사가 사업주체인 경우의 사용검사권자는 국토교통부장관이다(법 제49조제1항)."},{"번호":2,"판정":"옳음","설명":"사업주체가 파산 등으로 사용검사를 받을 수 없으면 시공보증자 또는 입주예정자가 받을 수 있다(법 제49조제3항제1호)."},{"번호":3,"판정":"옳음","설명":"사용검사는 신청일부터 15일 이내에 한다(영 제54조제4항)."},{"번호":4,"판정":"옳음","설명":"대지조성사업은 구획별로 공사가 완료된 경우 임시 사용승인을 받아 사용검사 전에 사용할 수 있다(법 제49조제4항 단서, 영 제56조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"임시 사용승인 대상이 공동주택이면 세대별로 승인할 수 있다(영 제56조제3항 후단)."}],"개념":[{"종류":"흐름","제목":"사용검사 절차","단계":[{"이름":"사용검사 신청","설명":"사업계획승인을 받아 시행한 주택건설·대지조성사업을 완료하면 시장·군수·구청장에게 사용검사를 받는다. 국가·한국토지주택공사가 사업주체인 경우 등은 국토교통부장관이다(법 제49조제1항)."},{"이름":"분할·동별 사용검사","설명":"공구별로 사업계획을 승인받은 경우 공구별로, 승인 조건 미이행 등 영 제54조제2항 사유가 있으면 동별로 받을 수 있다(법 제49조제1항 단서)."},{"이름":"검사","설명":"신청일부터 15일 이내에 사업계획 적합 여부와 사용검사 전 조치해야 하는 하자의 조치 완료 여부를 확인한다(영 제54조제3항·제4항)."},{"이름":"관계 기관 협의","설명":"의제된 인허가의 사용승인·준공검사를 위해 관계 행정기관의 장과 협의하며, 협의 요청을 받은 기관은 10일 이내에 의견을 제시한다(법 제49조제2항, 영 제54조제5항)."},{"이름":"사용","설명":"사용검사를 받은 후에야 주택·대지를 사용하게 하거나 사용할 수 있다. 임시 사용승인을 받으면 예외다(법 제49조제4항)."}]},{"종류":"표","제목":"임시 사용승인과 대행 사용검사","머리":["구분","내용"],"행":[["임시 사용승인(주택건설)","건축물의 동별로 공사가 완료된 경우(영 제56조제1항제1호)"],["임시 사용승인(대지조성)","구획별로 공사가 완료된 경우(영 제56조제1항제2호)"],["임시 사용승인 요건","사업계획 내용에 적합하고 사용에 지장이 없는 경우에만 가능, 공동주택은 세대별 승인 가능(영 제56조제3항)"],["대행 사용검사(제3항제1호)","사업주체가 파산 등으로 받을 수 없으면 시공보증자 또는 입주예정자"],["대행 사용검사(제3항제2호)","사업주체가 정당한 이유 없이 절차를 이행하지 않으면 시공보증자, 시공자 또는 입주예정자"],["시공보증자의 사용검사(영 제55조제1항)","시공보증자가 잔여공사를 시공하고 사용검사를 받음. 시공보증자가 없거나 시공이 불가능하면 입주예정자대표회의가 시공자를 정함"]]}],"함정":"사용검사권자는 시장·군수·구청장이 원칙이고, 국가와 한국토지주택공사가 사업주체이면 국토교통부장관이다. 지방공사나 지방자치단체는 이 예외에 들지 않는다.","개정":"법 제49조제5항(입주예정자 과반수가 요청하면 사용검사 전에 현장점검)은 2026.2.3 신설되었다. 요청에 따르지 않은 사업주체는 1천만원 이하의 과태료 대상이다(법 제106조제2항제5호의2)."}},{"i":"S4-2-1-공법-35","r":"S4","g":2,"c":2,"n":75,"s":"공법","q":"주택법령상 징역 또는 벌금의 부과 대상자는?","b":null,"bs":"없음","img":[],"ch":["지방자치단체의 장이 관계 공무원으로 하여금 사업장에 출입하여 필요한 검사를 하게 한 경우 그 검사를 방해한 자","공동주택 품질점검단의 점검에 따르지 아니한 사업주체","주택조합의 임원으로서 다른 주택조합의 발기인을 겸직한 자","국토교통부장관이 거주의무자의 실제 거주 여부를 확인하기 위하여 소속 공무원으로 하여금 분양가상한제 적용주택에 출입하여 조사하게 한 경우 그 조사를 기피한 자","공동주택 품질점검단의 점검결과에 따라 사용검사권자로부터 보수ㆍ보강 등의 조치 명령을 받았으나 이를 이행하지 아니한 사업주체"],"a":[1],"L":"공5-2","o":"기출","x":{"한줄":"제93조제1항에 따른 출입·검사를 방해한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.","근거":[{"법령":"주택법","조문":"제104조제13호","원문":"13. 제93조제1항에 따른 검사 등을 거부ㆍ방해 또는 기피한 자"},{"법령":"주택법","조문":"제93조제1항","원문":"① 국토교통부장관 또는 지방자치단체의 장은 필요하다고 인정할 때에는 다음 각 호의 어느 하나에 해당하는 자에게 필요한 보고를 하게 하거나, 관계 공무원으로 하여금 사업장에 출입하여 필요한 검사를 하게 할 수 있다."},{"법령":"주택법","조문":"제106조제1항제2호","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 2천만원 이하의 과태료를 부과한다.\n2. 제48조의3제3항을 위반하여 점검에 따르지 아니하거나 기피 또는 방해한 자"},{"법령":"주택법","조문":"제106조제2항제4호","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 1천만원 이하의 과태료를 부과한다.\n4. 제13조제4항을 위반하여 겸직한 자"},{"법령":"주택법","조문":"제106조제3항제4호의5","원문":"③ 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n4의5. 제48조의3제7항을 위반하여 조치명령을 이행하지 아니한 자"},{"법령":"주택법","조문":"제106조제4항제2호","원문":"④ 다음 각 호의 어느 하나에 해당하는 자에게는 300만원 이하의 과태료를 부과한다.\n2. 제57조의3제1항에 따른 서류 등의 제출을 거부하거나 해당 주택의 출입ㆍ조사 또는 질문을 방해하거나 기피한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"검사 거부·방해·기피는 법 제104조제13호로 1년 이하의 징역 또는 1천만원 이하의 벌금이다."},{"번호":2,"판정":"틀림","설명":"품질점검단의 점검에 따르지 않거나 기피·방해하면 2천만원 이하의 과태료다(법 제48조의3제3항, 제106조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"주택조합 임원이 다른 주택조합의 임원, 직원 또는 발기인을 겸하면 1천만원 이하의 과태료다(법 제13조제4항, 제106조제2항제4호)."},{"번호":4,"판정":"틀림","설명":"거주실태 조사의 출입·조사·질문을 방해하거나 기피하면 300만원 이하의 과태료다(법 제57조의3제1항, 제106조제4항제2호)."},{"번호":5,"판정":"틀림","설명":"품질점검단 점검결과에 따른 조치명령을 이행하지 않으면 500만원 이하의 과태료다(법 제48조의3제7항, 제106조제3항제4호의5)."}],"개념":[{"종류":"표","제목":"주택법 벌칙과 과태료 구분","머리":["조문","수준","주요 위반행위"],"행":[["제98조","10년 이하 징역","설계·시공·감리 위반으로 담보책임기간에 공동주택 내력구조부에 중대한 하자를 발생시켜 일반인을 위험에 처하게 함"],["제101조","3년 이하 징역 또는 3천만원 이하 벌금","조합업무를 대행하게 한 주택조합·발기인, 주택 전매·전매 알선(제64조제1항), 제65조제1항 위반"],["제102조","2년 이하 징역 또는 2천만원 이하 벌금","등록 없이 사업, 사업계획승인 없이 사업 시행, 사용검사 전 주택·대지 사용, 주택 공급 방법 위반"],["제104조","1년 이하 징역 또는 1천만원 이하 벌금","영업정지기간 영업, 제93조제1항 검사 거부·방해·기피, 공사 중지 명령 위반"],["제106조제1항","2천만원 이하 과태료","사전방문 미실시, 품질점검단 점검 불응·기피·방해, 표준임대차계약서 미사용"],["제106조제2항","1천만원 이하 과태료","주택조합 임원 겸직, 가입 설명의무 위반, 건축구조기술사 협력 미이행, 현장점검 요청 불응"],["제106조제3항","500만원 이하 과태료","제16조제2항 착공신고 미이행, 품질점검단 점검결과 조치명령 불이행, 제93조제1항 보고·검사 명령 위반"],["제106조제4항","300만원 이하 과태료","거주의무자의 한국토지주택공사 매입 신청 불이행, 거주실태 조사 방해·기피"]]},{"종류":"표","제목":"출입·검사·조사 방해 관련 제재 비교","머리":["위반행위","근거","제재"],"행":[["제93조제1항에 따른 출입·검사 거부·방해·기피","제104조제13호","1년 이하 징역 또는 1천만원 이하 벌금"],["제93조제1항에 따른 보고 또는 검사 명령 위반","제106조제3항제7호","500만원 이하 과태료"],["품질점검단 점검 불응·기피·방해(제48조의3제3항)","제106조제1항제2호","2천만원 이하 과태료"],["거주실태 조사 서류 제출 거부·출입 방해(제57조의3제1항)","제106조제4항제2호","300만원 이하 과태료"]]}],"함정":"같은 「방해」라도 사업장에 대한 출입·검사(제93조제1항)는 형벌이고, 품질점검단 점검과 거주실태 조사 방해는 과태료다. 품질점검단 관련 위반(2번, 5번)과 분양가상한제 주택 거주실태 조사(4번)는 모두 과태료이며 금액만 다르다."}},{"i":"S4-2-1-공법-36","r":"S4","g":2,"c":2,"n":76,"s":"공법","q":"주택법령상 사업계획승인 등에 관한 설명으로 틀린 것은? (단, 다른 법률에 따른 사업은 제외함)","b":null,"bs":"없음","img":[],"ch":["주택건설사업을 시행하려는 자는 전체 세대수가 600세대 이상의 주택단지를 공구별로 분할하여 주택을 건설ㆍ공급할 수 있다.","사업계획승인권자는 착공신고를 받은 날부터 20일 이내에 신고수리 여부를 신고인에게 통지하여야 한다.","사업계획승인권자는 사업계획승인의 신청을 받았을 때에는 정당한 사유가 없으면 신청받은 날부터 60일 이내에 사업주체에게 승인 여부를 통보하여야 한다.","사업주체는 사업계획승인을 받은 날부터 1년 이내에 공사를 착수하여야 한다.","사업계획에는 부대시설 및 복리시설의 설치에 관한 계획 등이 포함되어야 한다."],"a":[4],"L":"공5-2","o":"기출","x":{"한줄":"사업계획승인을 받은 사업주체는 승인받은 날부터 5년 이내에 공사를 시작해야 하므로 1년 이내라는 4번이 틀린 선지다.","근거":[{"법령":"주택법","조문":"제16조제1항","원문":"① 사업주체는 제15조제1항 또는 제3항에 따라 승인받은 사업계획대로 사업을 시행하여야 하고, 다음 각 호의 구분에 따라 공사를 시작하여야 한다. 다만, 사업계획승인권자는 대통령령으로 정하는 정당한 사유가 있다고 인정하는 경우에는 사업주체의 신청을 받아 그 사유가 없어진 날부터 1년의 범위에서 제1호 또는 제2호가목에 따른 공사의 착수기간을 연장할 수 있다.\n1. 제15조제1항에 따라 승인을 받은 경우: 승인받은 날부터 5년 이내"},{"법령":"주택법","조문":"제16조제3항","원문":"③ 사업계획승인권자는 제2항에 따른 신고를 받은 날부터 20일 이내에 신고수리 여부를 신고인에게 통지하여야 한다."},{"법령":"주택법","조문":"제15조제5항","원문":"⑤ 제1항 또는 제3항의 사업계획은 쾌적하고 문화적인 주거생활을 하는 데에 적합하도록 수립되어야 하며, 그 사업계획에는 부대시설 및 복리시설의 설치에 관한 계획 등이 포함되어야 한다."},{"법령":"주택법 시행령","조문":"제28조제1항","원문":"① 법 제15조제3항 각 호 외의 부분 전단에서 \"대통령령으로 정하는 호수 이상의 주택단지\"란 전체 세대수가 600세대 이상인 주택단지를 말한다."},{"법령":"주택법 시행령","조문":"제30조제1항","원문":"① 사업계획승인권자는 법 제15조에 따른 사업계획승인의 신청을 받았을 때에는 정당한 사유가 없으면 신청받은 날부터 60일 이내에 사업주체에게 승인 여부를 통보하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"영 제28조제1항에서 공구별 분할 대상 주택단지를 전체 세대수 600세대 이상으로 정한다."},{"번호":2,"판정":"옳음","설명":"착공신고를 받은 날부터 20일 이내에 수리 여부를 통지한다(법 제16조제3항)."},{"번호":3,"판정":"옳음","설명":"승인 신청을 받은 날부터 60일 이내에 승인 여부를 통보한다(영 제30조제1항)."},{"번호":4,"판정":"틀림","설명":"제15조제1항에 따라 승인받은 경우 승인받은 날부터 5년 이내에 공사를 시작한다(법 제16조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"사업계획에는 부대시설 및 복리시설의 설치에 관한 계획 등이 포함되어야 한다(법 제15조제5항)."}],"개념":[{"종류":"표","제목":"사업계획승인 이후 기한","머리":["단계","기한","근거"],"행":[["승인 신청 후 승인 여부 통보","신청받은 날부터 60일 이내(정당한 사유가 없는 한)","영 제30조제1항"],["공사 착수(제15조제1항 승인)","승인받은 날부터 5년 이내","법 제16조제1항제1호"],["공사 착수(공구별 분할, 최초 공구)","승인받은 날부터 5년 이내","법 제16조제1항제2호가목"],["공사 착수(공구별 분할, 그 외 공구)","해당 주택단지에 대한 최초 착공신고일부터 2년 이내","법 제16조제1항제2호나목"],["착수기간 연장","정당한 사유가 있으면 신청을 받아 그 사유가 없어진 날부터 1년의 범위(제1호·제2호가목에 한정)","법 제16조제1항 단서"],["착공신고 수리 여부 통지","신고를 받은 날부터 20일 이내","법 제16조제3항"],["승인 취소 사유","착수기간 위반, 경매·공매로 대지소유권 상실, 부도·파산 등으로 공사 완료 불가능","법 제16조제4항"]]},{"종류":"표","제목":"공구별 분할 건설과 착수기간 연장 사유","머리":["구분","내용"],"행":[["분할 대상(영 제28조제1항)","전체 세대수 600세대 이상의 주택단지"],["추가 제출서류(법 제15조제3항)","공구별 공사계획서, 입주자모집계획서, 사용검사계획서"],["연장 사유 1(영 제31조)","매장유산 발굴허가를 받은 경우, 소유권 분쟁(소송 진행 중)으로 착수가 지연되는 경우"],["연장 사유 2(영 제31조)","사업계획승인 조건을 이행하느라 지연되는 경우, 천재지변 등 사업주체에게 책임이 없는 불가항력적 사유"],["연장 사유 3(영 제31조)","공공택지 기반시설 설치 지연, 미분양주택 증가 등으로 사업성이 악화되는 등 승인권자가 부득이하다고 인정하는 경우"]]}],"함정":"공사 착수기한은 1년이 아니라 5년이다. 공구별 분할에서 최초 공구 외의 공구만 최초 착공신고일부터 2년 이내이며, 수치가 여러 개 나오므로 단계별로 구분해 둔다.","개정":"법 제16조제3항(착공신고를 받은 날부터 20일 이내에 수리 여부 통지)은 2021.1.5 신설되었다."}},{"i":"S4-2-1-공법-37","r":"S4","g":2,"c":2,"n":77,"s":"공법","q":"주택법령상 토지임대부 분양주택에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지임대부 분양주택의 토지에 대한 임대차기간은 50년 이내로 한다.","토지임대부 분양주택의 토지에 대한 임대차기간을 갱신하기 위해서는 토지임대부 분양주택 소유자의 3분의 2 이상이 계약갱신을 청구하여야 한다.","토지임대료를 보증금으로 전환하여 납부하는 경우, 그 보증금을 산정할 때 적용되는 이자율은 ｢은행법｣에 따른 은행의 3년 만기 정기예금 평균이자율 이상이어야 한다.","토지임대부 분양주택을 공급받은 자가 토지임대부 분양주택을 양도하려는 경우에는 시ㆍ도지사에게 해당 주택의 매입을 신청하여야 한다.","토지임대료는 분기별 임대료를 원칙으로 한다."],"a":[3],"L":"공5-3","o":"기출","x":{"한줄":"토지임대료를 보증금으로 전환할 때 적용하는 이자율은 은행의 3년 만기 정기예금 평균이자율 이상이어야 한다.","근거":[{"법령":"주택법 시행령","조문":"제82조","원문":"제82조(토지임대료의 선납 및 보증금 전환) 법 제78조제6항에 따라 토지임대료를 선납하거나 보증금으로 전환하려는 경우 그 선납 토지임대료 또는 보증금을 산정할 때 적용되는 이자율은 「은행법」에 따른 은행의 3년 만기 정기예금 평균이자율 이상이어야 한다."},{"법령":"주택법","조문":"제78조제1항","원문":"① 토지임대부 분양주택의 토지에 대한 임대차기간은 40년 이내로 한다. 이 경우 토지임대부 분양주택 소유자의 75퍼센트 이상이 계약갱신을 청구하는 경우 40년의 범위에서 이를 갱신할 수 있다."},{"법령":"주택법","조문":"제78조제6항","원문":"⑥ 제5항의 토지임대료는 월별 임대료를 원칙으로 하되, 토지소유자와 주택을 공급받은 자가 합의한 경우 대통령령으로 정하는 바에 따라 임대료를 선납하거나 보증금으로 전환하여 납부할 수 있다."},{"법령":"주택법","조문":"제78조의2제1항","원문":"① 토지임대부 분양주택을 공급받은 자는 제64조제1항에도 불구하고 전매제한기간이 지나기 전에 대통령령으로 정하는 바에 따라 한국토지주택공사에 해당 주택의 매입을 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"임대차기간은 40년 이내다(법 제78조제1항)."},{"번호":2,"판정":"틀림","설명":"소유자의 75퍼센트 이상이 계약갱신을 청구하면 40년의 범위에서 갱신할 수 있다(법 제78조제1항)."},{"번호":3,"판정":"옳음","설명":"영 제82조에 있는 내용이다. 선납 토지임대료를 산정할 때도 같은 기준이다."},{"번호":4,"판정":"틀림","설명":"전매제한기간이 지나기 전에 매입을 신청하는 상대방은 한국토지주택공사이며, 신청은 의무가 아니라 할 수 있는 것이다(법 제78조의2제1항)."},{"번호":5,"판정":"틀림","설명":"토지임대료는 월별 임대료가 원칙이며, 합의가 있으면 선납하거나 보증금으로 전환할 수 있다(법 제78조제6항)."}],"개념":[{"종류":"표","제목":"토지임대부 분양주택의 토지 임대차(법 제78조)","머리":["구분","내용"],"행":[["임대차기간","40년 이내"],["갱신","소유자의 75퍼센트 이상이 계약갱신을 청구하면 40년의 범위에서 갱신"],["지상권","임대차계약을 체결하면 임대차기간 동안 구분소유권을 목적으로 지상권이 설정된 것으로 봄"],["표준임대차계약서","국토교통부령으로 정하는 표준임대차계약서 사용"],["승계","양수인 또는 상속인이 임대차계약을 승계"],["토지임대료","월별 임대료가 원칙. 합의하면 선납 또는 보증금 전환 가능"],["법 적용 순서","주택법에서 정하지 않은 사항은 집합건물법, 민법 순으로 적용"]]},{"종류":"표","제목":"토지임대료 산정과 증액(영 제81조·제82조)","머리":["구분","내용"],"행":[["공공택지","조성원가에 입주자모집공고일이 속하는 달의 전전달 은행 3년 만기 정기예금 평균이자율을 적용한 금액을 12개월로 분할한 금액 이하"],["공공택지 외","감정평가한 가액에 같은 평균이자율을 적용한 금액을 12개월로 분할한 금액 이하"],["선납·보증금 전환 이자율","은행 3년 만기 정기예금 평균이자율 이상(영 제82조)"],["증액 청구 제한","토지임대료약정 체결 후 2년이 지나기 전에는 증액 청구 불가"],["증액 한도","시·군·구 평균지가상승률을 고려하되 주택임대차보호법 시행령 제8조제1항의 차임 증액 한도 비율 초과 불가"],["공공매입(법 제78조의2)","전매제한기간이 지나기 전에 한국토지주택공사에 매입 신청 가능"]]}],"함정":"임대차기간 40년, 갱신 청구 75퍼센트, 월별 임대료 원칙, 3년 만기 정기예금 이자율 이상이라는 네 가지 수치·용어가 한 묶음으로 출제된다. 매입 신청 상대방은 시·도지사가 아니라 한국토지주택공사다.","개정":"영 제82조는 2024.6.18 개정되어, 토지임대료를 선납하거나 보증금으로 전환할 때 적용하는 이자율을 은행의 3년 만기 정기예금 평균이자율 이상으로 정한다. 법 제78조제6항은 2023.12.26 개정 조문이다."}},{"i":"S4-2-1-공법-38","r":"S4","g":2,"c":2,"n":78,"s":"공법","q":"주택법령상 리모델링에 관한 설명으로 옳은 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["대수선은 리모델링에 포함되지 않는다.","공동주택의 리모델링은 동별로 할 수 있다.","주택단지 전체를 리모델링하고자 주택조합을 설립하기 위해서는 주택단지 전체의 구분소유자와 의결권의 각 과반수의 결의가 필요하다.","공동주택 리모델링의 허가는 시ㆍ도지사가 한다.","리모델링주택조합 설립에 동의한 자로부터 건축물을 취득하였더라도 리모델링주택조합 설립에 동의한 것으로 보지 않는다."],"a":[2],"L":"공5-3","o":"기출","x":{"한줄":"공동주택의 리모델링은 동을 단위로 할 수 있고, 동 리모델링은 그 동 구분소유자와 의결권의 각 3분의 2 이상 결의로 조합을 설립한다.","근거":[{"법령":"주택법","조문":"제11조제3항","원문":"③ 제1항에 따라 주택을 리모델링하기 위하여 주택조합을 설립하려는 경우에는 다음 각 호의 구분에 따른 구분소유자(「집합건물의 소유 및 관리에 관한 법률」 제2조제2호에 따른 구분소유자를 말한다. 이하 같다)와 의결권(「집합건물의 소유 및 관리에 관한 법률」 제37조에 따른 의결권을 말한다. 이하 같다)의 결의를 증명하는 서류를 첨부하여 관할 시장ㆍ군수ㆍ구청장의 인가를 받아야 한다.\n1. 주택단지 전체를 리모델링하고자 하는 경우에는 주택단지 전체의 구분소유자와 의결권의 각 3분의 2 이상의 결의 및 각 동의 구분소유자와 의결권의 각 과반수의 결의\n2. 동을 리모델링하고자 하는 경우에는 그 동의 구분소유자 및 의결권의 각 3분의 2 이상의 결의"},{"법령":"주택법","조문":"제2조제25호","원문":"25. \"리모델링\"이란 제66조제1항 및 제2항에 따라 건축물의 노후화 억제 또는 기능 향상 등을 위한 다음 각 목의 어느 하나에 해당하는 행위를 말한다.\n가. 대수선(大修繕)"},{"법령":"주택법","조문":"제66조제1항","원문":"① 공동주택(부대시설과 복리시설을 포함한다)의 입주자ㆍ사용자 또는 관리주체가 공동주택을 리모델링하려고 하는 경우에는 허가와 관련된 면적, 세대수 또는 입주자 등의 동의 비율에 관하여 대통령령으로 정하는 기준 및 절차 등에 따라 시장ㆍ군수ㆍ구청장의 허가를 받아야 한다."},{"법령":"주택법 시행령","조문":"제20조제8항","원문":"⑧ 리모델링주택조합 설립에 동의한 자로부터 건축물을 취득한 자는 리모델링주택조합 설립에 동의한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대수선은 리모델링에 포함된다(법 제2조제25호가목)."},{"번호":2,"판정":"옳음","설명":"동을 리모델링하려는 경우의 설립 결의 요건이 따로 있다(법 제11조제3항제2호)."},{"번호":3,"판정":"틀림","설명":"주택단지 전체를 리모델링하려면 전체 구분소유자와 의결권의 각 3분의 2 이상 결의 및 각 동의 구분소유자와 의결권의 각 과반수 결의가 필요하다(법 제11조제3항제1호)."},{"번호":4,"판정":"틀림","설명":"리모델링 허가권자는 시장·군수·구청장이다(법 제66조제1항)."},{"번호":5,"판정":"틀림","설명":"설립에 동의한 자로부터 건축물을 취득한 자는 동의한 것으로 본다(영 제20조제8항)."}],"개념":[{"종류":"표","제목":"리모델링주택조합 설립 결의와 동의(법 제11조제3항, 영 제20조제8항, 영 제75조제3항)","머리":["구분","내용"],"행":[["주택단지 전체 리모델링","주택단지 전체의 구분소유자와 의결권 각 3분의 2 이상 + 각 동의 구분소유자와 의결권 각 과반수"],["동 리모델링","그 동의 구분소유자 및 의결권 각 3분의 2 이상"],["인가","결의를 증명하는 서류를 첨부해 시장·군수·구청장의 인가"],["동의자의 승계","동의한 자로부터 건축물을 취득한 자는 동의한 것으로 봄"],["동의 철회","리모델링주택조합 또는 입주자대표회의가 허가신청서를 제출하기 전까지 서면으로 철회 가능"]]},{"종류":"표","제목":"리모델링의 종류와 허가(법 제2조제25호, 제66조)","머리":["구분","내용"],"행":[["대수선","리모델링에 포함"],["증축","사용검사일 또는 사용승인일부터 15년(15년 이상 20년 미만의 연수 중 시·도조례로 정한 연수)이 지난 공동주택을 각 세대 주거전용면적의 30퍼센트 이내(85제곱미터 미만은 40퍼센트 이내)에서 증축"],["세대수 증가형","각 세대의 증축 가능 면적을 합산한 범위에서 기존 세대수의 15퍼센트 이내로 세대수를 증가. 수직증축은 최대 3개층 이하 등 요건 충족 필요"],["허가권자","시장·군수·구청장"],["세대수 증가형 허가","대통령령으로 정하는 세대수 이상 증가하면 시·군·구도시계획위원회 심의"],["시공자 선정","리모델링주택조합 총회 또는 소유자 전원이 동의한 입주자대표회의가 경쟁입찰로 선정"],["사용검사","허가받은 리모델링 공사를 완료하면 시장·군수·구청장의 사용검사"]]}],"함정":"주택단지 전체 리모델링의 결의는 3분의 2 이상과 각 동 과반수가 합쳐진 이중 요건이다. 3번은 이 중 과반수만 적었고 3분의 2 요건이 빠져 있다. 허가권자는 시·도지사가 아니라 시장·군수·구청장이다."}},{"i":"S4-2-1-공법-39","r":"S4","g":2,"c":2,"n":79,"s":"공법","q":"농지법령상 농업경영을 하려는 자에게 농지를 임대하는 경우에 관한 설명으로 옳은 것은? (단, 농지법에서 임대차가 허용되는 경우이며, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["임대차계약은 등기가 없으면 임차인이 농지를 인도받았더라도 제삼자에 대하여 효력이 생기지 않는다.","임대인이 질병을 이유로 농지를 임대하는 경우에도 임대차 기간은 3년 이상으로 하여야 한다.","임차인이 농작물의 재배시설로서 고정식온실을 설치한 농지의 임대차 기간은 5년 이상으로 하여야 한다.","임대인이 임대차 기간이 끝나기 6개월 전까지 갱신하지 아니한다는 뜻을 통지하지 아니하면 그 임대차 기간이 끝난 때에 이전의 임대차계약과 같은 조건으로 다시 임대차계약을 한 것으로 본다.","임차인이 임대받은 농지를 정당한 사유 없이 농업경영에 사용하지 아니할 때에는 시ㆍ도지사가 임대차의 종료를 명할 수 있다."],"a":[3],"L":"공6-1","o":"변형","x":{"한줄":"임차인이 고정식온실이나 비닐하우스를 설치한 농지와 다년생식물 재배지는 임대차 기간을 5년 이상으로 해야 한다.","근거":[{"법령":"농지법","조문":"제24조의2제1항","원문":"① 제23조제1항 각 호(제8호는 제외한다)의 임대차 기간은 3년 이상으로 하여야 한다. 다만, 다년생식물 재배지 등 대통령령으로 정하는 농지의 경우에는 5년 이상으로 하여야 한다."},{"법령":"농지법 시행령","조문":"제24조의2제1항","원문":"① 법 제24조의2제1항 단서에서 \"다년생식물 재배지 등 대통령령으로 정하는 농지\"란 다음 각 호의 어느 하나에 해당하는 농지를 말한다.\n1. 농지의 임차인이 제2조제1항 각 호의 어느 하나에 해당하는 다년생식물의 재배지로 이용하는 농지\n2. 농지의 임차인이 농작물의 재배시설로서 고정식온실 또는 비닐하우스를 설치한 농지"},{"법령":"농지법","조문":"제24조의2제3항","원문":"③ 임대인은 제1항 및 제2항에도 불구하고 질병, 징집 등 대통령령으로 정하는 불가피한 사유가 있는 경우에는 임대차 기간을 제1항에 따른 기간 미만으로 정할 수 있다."},{"법령":"농지법","조문":"제24조제2항","원문":"② 제1항에 따른 임대차계약은 그 등기가 없는 경우에도 임차인이 농지소재지를 관할하는 시ㆍ구ㆍ읍ㆍ면의 장의 확인을 받고, 해당 농지를 인도(引渡)받은 경우에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다."},{"법령":"농지법","조문":"제25조","원문":"제25조(묵시의 갱신) 임대인이 임대차 기간이 끝나기 3개월 전까지 임차인에게 임대차계약을 갱신하지 아니한다는 뜻이나 임대차계약 조건을 변경한다는 뜻을 통지하지 아니하면 그 임대차 기간이 끝난 때에 이전의 임대차계약과 같은 조건으로 다시 임대차계약을 한 것으로 본다."},{"법령":"농지법","조문":"제23조제2항","원문":"② 제1항에도 불구하고 농지를 임차하거나 사용대차한 임차인 또는 사용대차인이 그 농지를 정당한 사유 없이 농업경영에 사용하지 아니할 때에는 시장ㆍ군수ㆍ구청장이 농림축산식품부령으로 정하는 바에 따라 임대차 또는 사용대차의 종료를 명할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"등기가 없어도 임차인이 시·구·읍·면의 장의 확인을 받고 농지를 인도받으면 다음 날부터 제삼자에 대하여 효력이 생긴다(법 제24조제2항)."},{"번호":2,"판정":"틀림","설명":"질병, 징집, 취학 등 불가피한 사유가 있으면 임대차 기간을 3년 미만으로 정할 수 있다(법 제24조의2제3항, 영 제24조의2제2항제1호)."},{"번호":3,"판정":"옳음","설명":"고정식온실 또는 비닐하우스를 설치한 농지는 5년 이상이다(법 제24조의2제1항 단서, 영 제24조의2제1항제2호)."},{"번호":4,"판정":"틀림","설명":"갱신하지 않는다는 통지 시한은 임대차 기간이 끝나기 3개월 전까지다(법 제25조). 6개월이 아니다."},{"번호":5,"판정":"틀림","설명":"임대차 종료를 명할 수 있는 자는 시장·군수·구청장이다(법 제23조제2항)."}],"개념":[{"종류":"표","제목":"농지 임대차 기간(법 제24조의2, 영 제24조의2)","머리":["구분","내용"],"행":[["원칙","제23조제1항 각 호(제8호 제외)의 임대차 기간은 3년 이상"],["5년 이상","다년생식물 재배지, 임차인이 고정식온실·비닐하우스를 설치한 농지"],["기간 미정·미달","3년(5년)으로 약정된 것으로 보되, 임차인은 미달 기간이 유효함을 주장 가능"],["3년 미만 가능한 사유","질병, 징집, 취학, 선거에 의한 공직 취임, 3개월 이상 치료가 필요한 부상, 교도소·구치소 등 수용 중, 농업법인 청산 중, 농지전용허가 후 목적사업 미착수"],["연장·갱신","연장, 갱신, 재계약에도 같은 기간 기준 적용"]]},{"종류":"표","제목":"임대차 계약의 방법과 효력(법 제23조~제26조의2)","머리":["구분","내용"],"행":[["계약 방법","서면계약 원칙(제24조제1항)"],["제삼자에 대한 효력","시·구·읍·면의 장의 확인을 받고 농지를 인도받으면 다음 날부터(제24조제2항)"],["묵시의 갱신","임대차 기간이 끝나기 3개월 전까지 갱신 거절이나 조건 변경 통지가 없으면 같은 조건으로 갱신(제25조)"],["임대인 지위 승계","양수인이 승계(제26조)"],["강행규정","임차인에게 불리한 약정은 무효(제26조의2)"],["임대차 종료 명령","정당한 사유 없이 농업경영에 사용하지 않으면 시장·군수·구청장이 명령(제23조제2항)"]]}],"함정":"임대차의 제삼자 효력은 시·구·읍·면의 장의 확인과 인도로 생기며 등기는 필요 없다. 갱신 거절 통지는 3개월 전까지이고, 3년 미만으로 정할 수 있는 사유는 질병·징집·취학 등이다. 종료 명령권자는 시장·군수·구청장이다.","개정":"법 제24조의2제1항은 제23조제1항 각 호(제8호 제외)의 임대차 기간을 3년 이상으로 정하며(개정 2015.1.20, 2015.7.20, 2020.2.11), 제23조제1항제1호에 국가나 지방자치단체 소유 농지(제6조제2항제1호)의 임대차도 포함된다. 국유 농지 임대차를 3년 미만으로 할 수 있다고 보던 27회 기출 지문은 현행 조문으로는 맞지 않다."}},{"i":"S4-2-1-공법-40","r":"S4","g":2,"c":2,"n":80,"s":"공법","q":"농지법령상 농지의 타용도 일시사용신고를 할 수 있는 용도에 해당하지 않는 것은? (단, 일시사용기간은 6개월 이내이며, 신고의 다른 요건은 충족한 것으로 봄)","b":null,"bs":"없음","img":[],"ch":["썰매장으로 사용하는 경우","지역축제장으로 사용하는 경우","해당 농지에서 허용되는 주목적사업을 위하여 물건을 매설하는 경우","해당 농지에서 허용되는 주목적사업을 위하여 현장 사무소를 설치하는 경우","｢전기사업법｣상 전기사업을 영위하기 위한 목적으로 ｢재생에너지 개발ㆍ이용ㆍ보급 촉진법｣에 따른 태양에너지 발전설비를 설치하는 경우"],"a":[5],"L":"공6-1","o":"기출","x":{"한줄":"태양에너지 발전설비를 설치하는 용도는 일시사용허가 대상이어서 신고할 수 있는 용도에 해당하지 않는다.","근거":[{"법령":"농지법","조문":"제36조의2제1항","원문":"① 농지를 다음 각 호의 어느 하나에 해당하는 용도로 일시사용하려는 자는 대통령령으로 정하는 바에 따라 지력을 훼손하지 아니하는 범위에서 일정 기간 사용한 후 농지로 원상복구한다는 조건으로 시장ㆍ군수 또는 자치구구청장에게 신고하여야 한다. 신고한 사항을 변경하려는 경우에도 또한 같다. 다만, 국가나 지방자치단체의 경우에는 시장ㆍ군수 또는 자치구구청장과 협의하여야 한다.\n1. 썰매장, 지역축제장 등으로 일시적으로 사용하는 경우\n2. 제36조제1항제1호 또는 제2호에 해당하는 시설을 일시적으로 설치하는 경우"},{"법령":"농지법","조문":"제36조제1항제2호","원문":"2. 주(主)목적사업(해당 농지에서 허용되는 사업만 해당한다)을 위하여 현장 사무소나 부대시설, 그 밖에 이에 준하는 시설을 설치하거나 물건을 적치(積置)하거나 매설(埋設)하는 경우"},{"법령":"농지법","조문":"제36조제1항제4호","원문":"①농지를 다음 각 호의 어느 하나에 해당하는 용도로 일시 사용하려는 자는 대통령령으로 정하는 바에 따라 일정 기간 사용한 후 농지로 복구한다는 조건으로 시장ㆍ군수 또는 자치구구청장의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다. 다만, 국가나 지방자치단체의 경우에는 시장ㆍ군수 또는 자치구구청장과 협의하여야 한다.\n4. 「전기사업법」 제2조제1호의 전기사업을 영위하기 위한 목적으로 설치하는 「재생에너지 개발ㆍ이용ㆍ보급 촉진법」 제2조제2호가목에 따른 태양에너지 발전설비(이하 \"태양에너지 발전설비\"라 한다)로서 다음 각 목의 요건을 모두 갖춘 경우"},{"법령":"농지법 시행령","조문":"제38조제1항제3호","원문":"① 법 제36조제1항에 따른 허가ㆍ협의, 같은 조 제2항에 따른 협의, 법 제36조의2제1항에 따른 신고ㆍ협의 및 같은 조 제2항에 따른 협의의 경우 농지의 타용도 일시사용기간은 다음 각 호와 같다.\n3. 법 제36조의2제1항에 따른 신고ㆍ협의 및 같은 조 제2항에 따른 협의: 6개월 이내"}],"선지":[{"번호":1,"판정":"옳음","설명":"썰매장은 법 제36조의2제1항제1호의 신고 용도다."},{"번호":2,"판정":"옳음","설명":"지역축제장도 같은 호의 신고 용도다."},{"번호":3,"판정":"옳음","설명":"주목적사업을 위해 물건을 적치하거나 매설하는 경우는 제36조제1항제2호 시설로서 제36조의2제1항제2호에 따라 신고할 수 있다."},{"번호":4,"판정":"옳음","설명":"주목적사업을 위한 현장 사무소 설치도 제36조제1항제2호이므로 신고할 수 있다."},{"번호":5,"판정":"틀림","설명":"태양에너지 발전설비는 제36조제1항제4호의 허가 대상이다. 제36조의2제1항의 신고 용도에 들어 있지 않다."}],"개념":[{"종류":"비교","제목":"농지 타용도 일시사용 허가와 신고","왼쪽":{"이름":"허가(법 제36조제1항)","항목":["간이 농수축산업용 시설, 농수산물의 간이 처리 시설 설치","주목적사업을 위한 현장 사무소·부대시설 설치, 물건 적치·매설","대통령령으로 정하는 토석·광물 채굴","전기사업을 위한 태양에너지 발전설비(간척지 등 요건 충족 시)","정보통신기술을 결합한 작물재배사 설치","기간: 제1호 용도 5년 이내, 제2호 용도 주목적사업 시행에 필요한 기간, 제5호 용도 7년 이내, 그 밖 5년 이내(영 제38조제1항제1호)"]},"오른쪽":{"이름":"신고(법 제36조의2제1항)","항목":["썰매장, 지역축제장 등 일시적 사용","제36조제1항제1호·제2호 시설을 일시적으로 설치","지력을 훼손하지 않는 범위에서 일정 기간 사용 후 원상복구","수리 여부는 신고를 받은 날부터 10일 이내 통지","기간 내 통지가 없으면 그 기간이 끝난 날의 다음 날 수리한 것으로 봄","기간: 6개월 이내(영 제38조제1항제3호)"]}},{"종류":"흐름","제목":"일시사용신고 절차(법 제36조의2)","단계":[{"이름":"신고","설명":"지력을 훼손하지 않는 범위에서 일정 기간 사용한 후 농지로 원상복구한다는 조건으로 시장·군수·자치구구청장에게 신고한다. 국가나 지방자치단체는 협의한다(제1항)."},{"이름":"복구계획·비용","설명":"수리하거나 협의할 때 농지로의 복구계획을 제출하게 하고 복구비용을 예치하게 할 수 있다(제3항)."},{"이름":"수리 통지","설명":"신고를 받은 날부터 10일 이내에 수리 여부를 통지한다(제4항)."},{"이름":"수리 간주","설명":"기간 내 통지하지 않으면 기간이 끝난 날의 다음 날 수리한 것으로 본다(제5항)."},{"이름":"사용기간","설명":"신고·협의의 일시사용기간은 6개월 이내이며, 영 제38조제2항의 기간 연장 규정에서 제외된다(영 제38조제1항제3호, 제2항)."}]}],"함정":"신고 용도는 썰매장·지역축제장 등과 제36조제1항 제1호·제2호 시설로 한정된다. 같은 제36조제1항이라도 토석 채굴(제3호), 태양에너지 발전설비(제4호), 작물재배사(제5호)는 허가 대상이다.","개정":"법 제36조제1항은 2026.3.17 개정되었고, 제4호는 「전기사업법」 제2조제1호의 전기사업을 위한 「재생에너지 개발ㆍ이용ㆍ보급 촉진법」 제2조제2호가목의 태양에너지 발전설비로서 간척지 등 요건을 갖춘 경우를 허가 대상으로 정한다."}},{"i":"S4-2-2-공시법-01","r":"S4","g":3,"c":2,"n":1,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 영구적 건축물 중 박물관, 미술관 등 문화시설과 이에 접속된 정원의 부지에 관한 지목의 구분으로 옳은 것은? (단, 다른 조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["대","공원","사적지","유원지","학교용지"],"a":[1],"L":"시1-1","o":"기출","x":{"한줄":"박물관·미술관 같은 문화시설과 그에 접속된 정원·부속시설물의 부지는 지목이 대(垈)다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제8호","원문":"대: 가. 영구적 건축물 중 주거ㆍ사무실ㆍ점포와 박물관ㆍ극장ㆍ미술관 등 문화시설과 이에 접속된 정원 및 부속시설물의 부지 / 나. 「국토의 계획 및 이용에 관한 법률」 등 관계 법령에 따른 택지조성공사가 준공된 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제22호","원문":"공원: 일반 공중의 보건ㆍ휴양 및 정서생활에 이용하기 위한 시설을 갖춘 토지로서 「국토의 계획 및 이용에 관한 법률」에 따라 공원 또는 녹지로 결정ㆍ고시된 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제26호","원문":"사적지: 국가유산으로 지정된 역사적인 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지. 다만, 학교용지ㆍ공원ㆍ종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 등을 보호하기 위하여 구획된 토지는 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"문화시설과 접속된 정원·부속시설물 부지는 대에 속한다(영 제58조제8호가목)."},{"번호":2,"판정":"틀림","설명":"공원은 보건·휴양·정서생활 시설을 갖춘 토지 중 국토계획법상 공원 또는 녹지로 결정·고시된 것이다(영 제58조제22호). 문화시설 부지는 이에 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"사적지는 국가유산으로 지정된 유적·고적·기념물을 보존하려고 구획한 토지다(영 제58조제26호). 박물관·미술관 부지와 관계없다."},{"번호":4,"판정":"틀림","설명":"유원지는 수영장·유선장·낚시터·어린이놀이터·동물원·식물원·민속촌·경마장·야영장 같은 위락·휴양 시설의 토지다(영 제58조제24호)."},{"번호":5,"판정":"틀림","설명":"학교용지는 학교의 교사와 이에 접속된 체육장 등 부속시설물의 부지다(영 제58조제10호)."}],"개념":[{"종류":"표","제목":"건축물 부지를 가르는 지목","머리":["지목","해당 부지","주의"],"행":[["대","주거ㆍ사무실ㆍ점포, 박물관ㆍ극장ㆍ미술관 등 문화시설과 접속 정원ㆍ부속시설물, 택지조성공사 준공 토지","과수원ㆍ목장용지ㆍ묘지 안의 주거용(관리용) 건축물 부지도 대"],["공장용지","제조업 공장시설물, 공장부지 조성공사 준공 토지, 같은 구역의 의료시설 등 부속시설물","공장 안 급유ㆍ송유시설은 주유소용지에서 제외"],["학교용지","학교 교사와 접속 체육장 등 부속시설물","-"],["종교용지","교회ㆍ사찰ㆍ향교 등 건축물과 접속 부속시설물","-"],["창고용지","독립 설치된 보관시설물과 접속 부속시설물","-"],["사적지","국가유산으로 지정된 유적ㆍ고적ㆍ기념물 보존 구획 토지","학교용지ㆍ공원ㆍ종교용지 안의 유적 구획 토지는 제외"]]},{"종류":"표","제목":"지목 부호: 첫 글자와 다른 네 가지","머리":["지목","부호","비고"],"행":[["공장용지","장","공원(공)과 구별"],["주차장","차","주유소용지(주)와 구별"],["하천","천","-"],["유원지","원","유지(유)와 구별"],["그 밖의 지목","첫 글자","학교용지 학, 창고용지 창, 주유소용지 주 등"]]}],"함정":"정원이 딸려 있다는 이유로 2번 공원을 고르기 쉽다. 공원은 국토계획법에 따라 공원·녹지로 결정·고시된 토지여야 하고, 문화시설의 부속 정원은 대의 일부다."}},{"i":"S4-2-2-공시법-02","r":"S4","g":3,"c":2,"n":2,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지목의 구분으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 “광천지”로 한다.","일반 공중의 종교의식을 위하여 예배ㆍ법요ㆍ설교ㆍ제사 등을 하기 위한 교회ㆍ사찰ㆍ향교 등 건축물의 부지와 이에 접속된 부속시설물의 부지는 “사적지”로 한다.","자연의 유수(流水)가 있거나 있을 것으로 예상되는 토지는 “구거”로 한다.","제조업을 하고 있는 공장시설물의 부지와 같은 구역에 있는 의료시설 등 부속시설물의 부지는 “공장용지”로 한다.","일반 공중의 보건ㆍ휴양 및 정서생활에 이용하기 위한 시설을 갖춘 토지로서 「국토의 계획 및 이용에 관한 법률」에 따라 공원 또는 녹지로 결정ㆍ고시된 토지는 “체육용지”로 한다."],"a":[4],"L":"시1-1","o":"기출","x":{"한줄":"공장시설물 부지와 같은 구역 안의 의료시설 등 부속시설물 부지는 공장용지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제9호","원문":"공장용지: 가. 제조업을 하고 있는 공장시설물의 부지 / 나. 「산업집적활성화 및 공장설립에 관한 법률」 등 관계 법령에 따른 공장부지 조성공사가 준공된 토지 / 다. 가목 및 나목의 토지와 같은 구역에 있는 의료시설 등 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제6호","원문":"광천지: 지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제17호","원문":"하천: 자연의 유수(流水)가 있거나 있을 것으로 예상되는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제25호","원문":"종교용지: 일반 공중의 종교의식을 위하여 예배ㆍ법요ㆍ설교ㆍ제사 등을 하기 위한 교회ㆍ사찰ㆍ향교 등 건축물의 부지와 이에 접속된 부속시설물의 부지"}],"선지":[{"번호":1,"판정":"틀림","설명":"송수관·송유관·저장시설 부지는 광천지에서 빠진다. 광천지는 용출구와 그 유지에 쓰는 부지만이다(영 제58조제6호 단서)."},{"번호":2,"판정":"틀림","설명":"교회·사찰·향교 건축물 부지는 종교용지다(영 제58조제25호). 사적지는 국가유산으로 지정된 유적·고적·기념물 보존 구획 토지다."},{"번호":3,"판정":"틀림","설명":"자연의 유수가 있거나 있을 것으로 예상되는 토지는 하천이다(영 제58조제17호). 구거는 인공 수로·둑과 그 부속시설물 부지, 소규모 수로부지다."},{"번호":4,"판정":"옳음","설명":"공장용지에는 공장시설물 부지와 같은 구역의 의료시설 등 부속시설물 부지가 들어간다(영 제58조제9호다목)."},{"번호":5,"판정":"틀림","설명":"국토계획법에 따라 공원·녹지로 결정·고시된 토지는 공원이다(영 제58조제22호). 체육용지는 종합운동장·실내체육관·야구장·골프장 같은 체육시설의 토지다."}],"개념":[{"종류":"표","제목":"물과 관련된 지목","머리":["지목","정의","구별 포인트"],"행":[["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","자연 상태의 흐름"],["구거","용수ㆍ배수를 위한 인공 수로ㆍ둑ㆍ부속시설물 부지, 자연 유수가 있는 소규모 수로부지","인공 수로 중심"],["유지","물이 고이거나 상시 저장하는 댐ㆍ저수지ㆍ소류지ㆍ호수ㆍ연못, 연ㆍ왕골 자생 배수불량 토지","저장하는 물"],["제방","조수ㆍ자연유수ㆍ모래ㆍ바람을 막는 방조제ㆍ방수제ㆍ방사제ㆍ방파제 부지","막는 시설"],["양어장","육상에 인공으로 조성된 수산생물 번식ㆍ양식 시설 부지와 접속 부속시설물","육상 인공 시설"],["수도용지","취수ㆍ저수ㆍ도수ㆍ정수ㆍ송수ㆍ배수 시설 부지와 접속 부속시설물","물 공급 시설"],["광천지","온수ㆍ약수ㆍ석유류 용출구와 그 유지에 쓰는 부지","송수관ㆍ송유관ㆍ저장시설 부지 제외"]]},{"종류":"표","제목":"공원ㆍ체육용지ㆍ유원지","머리":["지목","해당","제외"],"행":[["공원","보건ㆍ휴양ㆍ정서생활 시설을 갖추고 국토계획법에 따라 공원 또는 녹지로 결정ㆍ고시된 토지","-"],["체육용지","종합운동장ㆍ실내체육관ㆍ야구장ㆍ골프장ㆍ스키장ㆍ승마장ㆍ경륜장 등 체육시설 토지와 접속 부속시설물","영속성ㆍ독립성이 약한 정구장ㆍ골프연습장ㆍ실내수영장ㆍ체육도장, 유수를 이용한 요트장ㆍ카누장"],["유원지","수영장ㆍ유선장ㆍ낚시터ㆍ어린이놀이터ㆍ동물원ㆍ식물원ㆍ민속촌ㆍ경마장ㆍ야영장 등 위락ㆍ휴양 시설 토지와 접속 부속시설물","독립적 숙식시설ㆍ유기장 부지, 하천ㆍ구거ㆍ공유 유지로 분류되는 것"]]}],"함정":"3번은 하천의 정의를 구거에 붙인 문장이고, 5번은 공원의 정의를 체육용지에 붙인 문장이다. 정의 문구는 맞고 지목 이름만 바뀌어 있어 정의 쪽을 먼저 읽으면 걸러진다."}},{"i":"S4-2-2-공시법-03","r":"S4","g":3,"c":2,"n":3,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지상경계점등록부의 등록사항으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지적도면의 번호","토지의 소재","공부상 지목과 실제 토지이용 지목","경계점의 사진 파일","경계점표지의 종류 및 경계점 위치"],"a":[1],"L":"시1-2","o":"기출","x":{"한줄":"지상경계점등록부의 등록사항에 지적도면의 번호는 없다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제65조제2항","원문":"지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제60조제2항","원문":"법 제65조제2항제5호에서 “그 밖에 국토교통부령으로 정하는 사항”이란 다음 각 호의 사항을 말한다. 1. 공부상 지목과 실제 토지이용 지목 2. 경계점의 사진 파일 3. 경계점표지의 종류 및 경계점 위치"}],"선지":[{"번호":1,"판정":"틀림","설명":"법 제65조제2항 각 호와 규칙 제60조제2항 어디에도 지적도면의 번호는 없다."},{"번호":2,"판정":"옳음","설명":"토지의 소재는 법 제65조제2항제1호의 등록사항이다."},{"번호":3,"판정":"옳음","설명":"공부상 지목과 실제 토지이용 지목은 규칙 제60조제2항제1호의 등록사항이다."},{"번호":4,"판정":"옳음","설명":"경계점의 사진 파일은 규칙 제60조제2항제2호의 등록사항이다."},{"번호":5,"판정":"옳음","설명":"경계점표지의 종류 및 경계점 위치는 규칙 제60조제2항제3호의 등록사항이다."}],"개념":[{"종류":"표","제목":"지상경계점등록부 등록사항","머리":["구분","등록사항","근거"],"행":[["법에서 직접","토지의 소재","법 제65조제2항제1호"],["법에서 직접","지번","법 제65조제2항제2호"],["법에서 직접","경계점 좌표(경계점좌표등록부 시행지역에 한정)","법 제65조제2항제3호"],["법에서 직접","경계점 위치 설명도","법 제65조제2항제4호"],["규칙에서","공부상 지목과 실제 토지이용 지목","규칙 제60조제2항제1호"],["규칙에서","경계점의 사진 파일","규칙 제60조제2항제2호"],["규칙에서","경계점표지의 종류 및 경계점 위치","규칙 제60조제2항제3호"]]},{"종류":"표","제목":"지상경계의 결정기준","머리":["상황","경계 위치"],"행":[["연접 토지 간 높낮이 차이가 없는 경우","구조물 등의 중앙"],["연접 토지 간 높낮이 차이가 있는 경우","구조물 등의 하단부"],["도로ㆍ구거 등에 절토(땅깎기)된 부분이 있는 경우","경사면의 상단부"],["토지가 해면 또는 수면에 접하는 경우","최대만조위 또는 최대만수위가 되는 선"],["공유수면매립지에서 제방 등을 토지에 편입하여 등록하는 경우","바깥쪽 어깨부분"]]}],"함정":"5번의 「경계점 위치」는 법에 있는 「경계점 위치 설명도」와 이름이 비슷하다. 규칙 제60조제2항제3호는 경계점표지의 종류와 경계점 위치를 함께 정한 항목이라 등록사항이 맞다. 경계점 좌표는 경계점좌표등록부 시행지역에서만 등록한다."}},{"i":"S4-2-2-공시법-04","r":"S4","g":3,"c":2,"n":4,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적도의 축척이 1200분의 1인 지역(경계점좌표등록부 시행지역은 아님)에서 신규등록할 1필지의 면적을 계산한 값이 0.5㎡이었다. 토지대장에 등록하는 면적의 결정으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["0㎡","0.05㎡","0.1㎡","0.5㎡","1㎡"],"a":[5],"L":"시1-2","o":"변형","x":{"한줄":"1200분의 1 지역은 1㎡ 단위로 정한다. 끝수 0.5㎡는 끝자리가 0(짝수)이라 버리지만, 1필지가 1㎡ 미만이면 1㎡로 하므로 1㎡다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제1호","원문":"토지의 면적에 1제곱미터 미만의 끝수가 있는 경우 0.5제곱미터 미만일 때에는 버리고 0.5제곱미터를 초과하는 때에는 올리며, 0.5제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 1제곱미터 미만일 때에는 1제곱미터로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제2호","원문":"지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 제1호에도 불구하고 제곱미터 이하 한 자리 단위로 하되, 0.1제곱미터 미만의 끝수가 있는 경우 0.05제곱미터 미만일 때에는 버리고 0.05제곱미터를 초과할 때에는 올리며, 0.05제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."}],"선지":[{"번호":1,"판정":"-","설명":"끝수 처리만 하면 0㎡가 되지만, 제1호 단서가 1필지 면적 1㎡ 미만을 1㎡로 끌어올린다."},{"번호":2,"판정":"-","설명":"0.05㎡는 600분의 1 지역·경계점좌표등록부 지역의 끝수 기준값이다(제2호). 이 사례는 1㎡ 단위 지역이다."},{"번호":3,"판정":"-","설명":"0.1㎡는 600분의 1 지역·경계점좌표등록부 지역에서 1필지의 최소 면적이다(제2호 단서). 1200분의 1 지역에는 적용되지 않는다."},{"번호":4,"판정":"-","설명":"1㎡ 단위 지역에서 0.5㎡를 그대로 등록하는 규정은 없다."},{"번호":5,"판정":"-","설명":"제1호 단서에 따라 1필지 면적이 1㎡ 미만이면 1㎡로 한다."}],"개념":[{"종류":"계산","제목":"1200분의 1 지역 면적 결정 (계산값 0.5㎡)","단계":[{"설명":"적용 규정 찾기: 축척 1200분의 1, 경계점좌표등록부 아님","식":"600분의 1도 좌표등록부도 아님 → 제1호 적용","값":"1㎡ 단위"},{"설명":"1㎡ 미만 끝수 처리","식":"끝수 = 0.5㎡, 구하려는 끝자리(1㎡ 자리) = 0 (짝수)","값":"버림 → 0㎡"},{"설명":"1필지 최소 면적 단서 적용","식":"0㎡ < 1㎡ → 1㎡로 한다","값":"1㎡"}]},{"종류":"표","제목":"면적 결정 단위 비교","머리":["구분","1㎡ 단위 (제1호)","0.1㎡ 단위 (제2호)"],"행":[["적용 지역","그 밖의 지역","지적도 축척 600분의 1 지역, 경계점좌표등록부 등록 지역"],["끝수 처리 단위","1㎡ 미만 끝수","0.1㎡ 미만 끝수"],["버리는 경우","0.5㎡ 미만","0.05㎡ 미만"],["올리는 경우","0.5㎡ 초과","0.05㎡ 초과"],["기준값과 같을 때","끝자리 0 또는 짝수면 버림, 홀수면 올림","끝자리 0 또는 짝수면 버림, 홀수면 올림"],["1필지 최소 면적","1㎡","0.1㎡"]]}],"함정":"끝수 처리 결과인 0㎡를 그대로 고르기 쉽다. 면적이 0인 필지는 없으므로 단서가 1㎡로 끌어올린다. 같은 값이라도 600분의 1 지역이면 0.5㎡ 그대로 등록한다."}},{"i":"S4-2-2-공시법-05","r":"S4","g":3,"c":2,"n":5,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적공부의 복구 절차에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지적소관청은 복구하려는 토지의 표시 등을 시ㆍ군ㆍ구 게시판 및 인터넷 홈페이지에 15일 이상 게시하여야 한다.","복구하려는 토지의 표시 등에 이의가 있는 자는 게시기간 내에 지적소관청에 이의신청을 할 수 있다.","측량 결과도와 토지이동정리 결의서는 지적공부의 복구자료이다.","토지대장ㆍ임야대장 또는 공유지연명부는 복구되고 지적도면이 복구되지 아니한 토지가 축척변경 시행지역이나 도시개발사업 등의 시행지역에 편입된 때에는 지적도면을 복구하지 아니할 수 있다.","지적복구자료 조사서의 조사된 면적이 오차의 허용범위 이내인 경우에도 복구측량을 하여 면적을 새로 결정하여야 한다."],"a":[5],"L":"시1-3","o":"변형","x":{"한줄":"조사서의 면적이 허용범위 이내이면 복구측량 없이 그 면적을 복구면적으로 결정한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제73조제4항","원문":"지적소관청은 제2항에 따라 작성된 지적복구자료 조사서의 조사된 면적이 영 제19조제1항제2호가목의 계산식에 따른 허용범위 이내인 경우에는 그 면적을 복구면적으로 결정하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제73조제3항","원문":"제2항에 따라 작성된 복구자료도에 따라 측정한 면적과 지적복구자료 조사서의 조사된 면적의 증감이 영 제19조제1항제2호가목의 계산식에 따른 허용범위를 초과하거나 복구자료도를 작성할 복구자료가 없는 경우에는 복구측량을 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제73조제6항·제7항","원문":"지적소관청은 제1항부터 제5항까지의 규정에 따른 복구자료의 조사 또는 복구측량 등이 완료되어 지적공부를 복구하려는 경우에는 복구하려는 토지의 표시 등을 시ㆍ군ㆍ구 게시판 및 인터넷 홈페이지에 15일 이상 게시하여야 한다. / 복구하려는 토지의 표시 등에 이의가 있는 자는 제6항의 게시기간 내에 지적소관청에 이의신청을 할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제73조제9항","원문":"토지대장ㆍ임야대장 또는 공유지연명부는 복구되고 지적도면이 복구되지 아니한 토지가 법 제83조에 따른 축척변경 시행지역이나 법 제86조에 따른 도시개발사업 등의 시행지역에 편입된 때에는 지적도면을 복구하지 아니할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제72조","원문":"영 제61조제1항에 따른 지적공부의 복구에 관한 관계 자료는 다음 각 호와 같다. 1. 지적공부의 등본 2. 측량 결과도 3. 토지이동정리 결의서 4. 토지(건물)등기사항증명서 등 등기사실을 증명하는 서류 5. 지적소관청이 작성하거나 발행한 지적공부의 등록내용을 증명하는 서류 6. 법 제69조제3항에 따라 복제된 지적공부 7. 법원의 확정판결서 정본 또는 사본"}],"선지":[{"번호":1,"판정":"옳음","설명":"복구하려는 토지의 표시 등은 시·군·구 게시판과 인터넷 홈페이지에 15일 이상 게시한다(규칙 제73조제6항)."},{"번호":2,"판정":"옳음","설명":"이의는 게시기간 내에 지적소관청에 신청하고, 이유가 있으면 지적소관청이 시정 조치를 한다(규칙 제73조제7항)."},{"번호":3,"판정":"옳음","설명":"측량 결과도(제2호)와 토지이동정리 결의서(제3호)는 규칙 제72조의 복구자료다."},{"번호":4,"판정":"옳음","설명":"대장은 복구되고 도면은 복구되지 않은 토지가 축척변경·도시개발사업 등의 시행지역에 편입되면 도면을 복구하지 않을 수 있다(규칙 제73조제9항)."},{"번호":5,"판정":"틀림","설명":"허용범위 이내이면 조사서의 면적이 곧 복구면적이다(규칙 제73조제4항). 복구측량은 허용범위를 초과하거나 복구자료도를 만들 자료가 없을 때 한다(제3항)."}],"개념":[{"종류":"흐름","제목":"지적공부 복구 절차","단계":[{"이름":"복구자료 조사","설명":"멸실ㆍ훼손 즉시 복구(법 제74조). 규칙 제72조의 7종 자료를 조사한다."},{"이름":"조사서ㆍ복구자료도 작성","설명":"대장ㆍ공유지연명부는 지적복구자료 조사서, 도면은 복구자료도를 만든다."},{"이름":"면적 비교","설명":"복구자료도 측정면적과 조사서 면적의 차이가 허용범위 이내면 조사서 면적으로 결정. 초과하거나 복구자료도를 만들 자료가 없으면 복구측량."},{"이름":"복구측량 결과 조정","설명":"복구자료와 부합하지 않으면 토지소유자ㆍ이해관계인 동의를 받아 경계ㆍ면적 조정. 경계를 조정하면 경계점표지 설치."},{"이름":"게시","설명":"시ㆍ군ㆍ구 게시판과 인터넷 홈페이지에 15일 이상."},{"이름":"이의신청","설명":"게시기간 내 지적소관청에 신청. 이유가 있으면 시정."},{"이름":"복구","설명":"조사서ㆍ복구자료도ㆍ복구측량 결과도에 따라 대장ㆍ공유지연명부ㆍ도면 복구."}]},{"종류":"표","제목":"복구 원칙과 복구자료","머리":["항목","내용","근거"],"행":[["복구 시기","멸실ㆍ훼손 시 지체 없이","법 제74조"],["토지의 표시","멸실ㆍ훼손 당시의 지적공부와 가장 부합된다고 인정되는 관계 자료","영 제61조제1항 본문"],["소유자","부동산등기부나 법원의 확정판결","영 제61조제1항 단서"],["복구자료","지적공부 등본, 측량 결과도, 토지이동정리 결의서, 등기사실 증명서류, 지적소관청 발행 등록내용 증명서류, 복제된 지적공부, 법원 확정판결서 정본 또는 사본","규칙 제72조"],["정보처리시스템 기록 공부의 복구권자","시ㆍ도지사, 시장ㆍ군수 또는 구청장","법 제74조"]]}],"함정":"4번의 도면 미복구 예외가 낯설어 틀린 문장으로 보기 쉽다. 규칙 제73조제9항에 그대로 있다. 5번은 복구측량을 언제 하는지가 핵심이고, 허용범위 이내라는 조건이면 측량을 거치지 않는다.","개정":"규칙 제72조는 <개정 2023.6.9> 표시가 있고 현행 복구자료는 7종이다. 예전 기출에서 복구자료로 제시된 개별공시지가 자료, 측량신청서와 측량 준비도는 현행 열거에 없다."}},{"i":"S4-2-2-공시법-06","r":"S4","g":3,"c":2,"n":6,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 부동산종합공부의 관리 및 운영 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지적소관청은 부동산종합공부에 토지적성평가 확인서의 내용을 등록하여야 한다.","지적소관청은 부동산종합공부의 멸실 또는 훼손에 대비하여 이를 별도로 복제하여 관리하는 정보관리체계를 구축하여야 한다.","부동산종합공부의 등록사항을 관리하는 기관의 장은 지적소관청에 상시적으로 관련 정보를 제공하여야 한다.","지적소관청은 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 부동산종합공부를 관리ㆍ운영한다.","부동산종합공부 기록사항의 전부 또는 일부에 관한 증명서를 발급받으려는 자는 지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청할 수 있다."],"a":[1],"L":"시1-3","o":"기출","x":{"한줄":"부동산종합공부의 등록사항은 법이 다섯 가지로 정해 두었고 토지적성평가 확인서는 그 안에 없다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의3","원문":"지적소관청은 부동산종합공부에 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 표시와 소유자에 관한 사항: 이 법에 따른 지적공부의 내용 2. 건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만 해당한다): 「건축법」 제38조에 따른 건축물대장의 내용 3. 토지의 이용 및 규제에 관한 사항: 「토지이용규제 기본법」 제10조에 따른 토지이용계획확인서의 내용 4. 부동산의 가격에 관한 사항: 「부동산 가격공시에 관한 법률」 제10조에 따른 개별공시지가, 같은 법 제16조, 제17조 및 제18조에 따른 개별주택가격 및 공동주택가격 공시내용 5. 그 밖에 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 필요한 사항으로서 대통령령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제62조의2","원문":"법 제76조의3제5호에서 “대통령령으로 정하는 사항”이란 「부동산등기법」 제48조에 따른 부동산의 권리에 관한 사항을 말한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의2제2항·제3항","원문":"지적소관청은 부동산종합공부를 영구히 보존하여야 하며, 부동산종합공부의 멸실 또는 훼손에 대비하여 이를 별도로 복제하여 관리하는 정보관리체계를 구축하여야 한다. / 제76조의3 각 호의 등록사항을 관리하는 기관의 장은 지적소관청에 상시적으로 관련 정보를 제공하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의4제1항","원문":"부동산종합공부를 열람하거나 부동산종합공부 기록사항의 전부 또는 일부에 관한 증명서(이하 “부동산종합증명서”라 한다)를 발급받으려는 자는 지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"등록사항은 지적공부, 건축물대장, 토지이용계획확인서, 개별공시지가ㆍ개별주택가격ㆍ공동주택가격, 부동산등기법 제48조의 권리 사항이다(법 제76조의3, 영 제62조의2). 토지적성평가 확인서는 없다."},{"번호":2,"판정":"옳음","설명":"영구 보존과 별도 복제 관리 정보관리체계 구축은 지적소관청의 의무다(법 제76조의2제2항)."},{"번호":3,"판정":"옳음","설명":"등록사항 관리기관의 장은 지적소관청에 상시적으로 정보를 제공한다(법 제76조의2제3항)."},{"번호":4,"판정":"옳음","설명":"지적소관청이 부동산의 효율적 이용과 정보의 종합적 관리ㆍ운영을 위해 관리ㆍ운영한다(법 제76조의2제1항)."},{"번호":5,"판정":"옳음","설명":"열람과 증명서 발급은 지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청한다(법 제76조의4제1항)."}],"개념":[{"종류":"표","제목":"부동산종합공부 등록사항","머리":["구분","등록 내용","근거"],"행":[["토지의 표시와 소유자","지적공부의 내용","법 제76조의3제1호"],["건축물의 표시와 소유자(건축물이 있는 경우만)","건축물대장의 내용","법 제76조의3제2호"],["토지의 이용 및 규제","토지이용계획확인서의 내용","법 제76조의3제3호"],["부동산의 가격","개별공시지가, 개별주택가격, 공동주택가격 공시내용","법 제76조의3제4호"],["부동산의 권리","부동산등기법 제48조에 따른 권리에 관한 사항","법 제76조의3제5호, 영 제62조의2"]]},{"종류":"표","제목":"부동산종합공부 관리 규정","머리":["항목","내용","근거"],"행":[["관리자","지적소관청이 관리ㆍ운영","법 제76조의2제1항"],["보존","영구 보존, 멸실ㆍ훼손에 대비한 별도 복제 관리 정보관리체계 구축","법 제76조의2제2항"],["정보 제공","등록사항 관리기관의 장은 상시적으로 제공","법 제76조의2제3항"],["자료 제출 요구","정확한 등록ㆍ관리를 위해 필요하면 관리기관의 장에게 요구, 요구받은 기관은 특별한 사유가 없으면 제공","법 제76조의2제4항"],["열람ㆍ증명서 발급","지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청","법 제76조의4제1항"],["등록사항 정정","법 제84조(등록사항의 정정) 준용","법 제76조의5"],["불일치 등록사항","지적소관청이 확인ㆍ관리, 관리기관에 통지해 정정 요청 가능","영 제62조의3"]]}],"함정":"3번의 「제공하여야」와 4항의 「요구할 수 있다」는 서로 다른 조항이다. 관리기관은 상시 제공이 의무이고, 지적소관청의 자료 제출 요구는 필요할 때 하는 재량이다. 5번은 시장ㆍ군수가 아닌 읍ㆍ면ㆍ동의 장도 발급처에 들어간다."}},{"i":"S4-2-2-공시법-07","r":"S4","g":3,"c":2,"n":7,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 축척변경에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["축척변경위원회는 5명 이상 10명 이하의 위원으로 구성하며, 위원의 3분의 1 이상을 토지소유자로 하여야 한다.","축척변경 시행지역의 토지소유자 또는 점유자는 시행공고일부터 60일 이내에 시행공고일 현재 점유하고 있는 경계에 경계점표지를 설치하여야 한다.","청산금 납부고지를 받은 자는 그 고지를 받은 날부터 6개월 이내에 청산금을 지적소관청에 내야 한다.","청산금에 이의가 있는 자는 납부고지 또는 수령통지를 받은 날부터 3개월 이내에 지적소관청에 이의신청을 할 수 있다.","지적소관청은 축척변경 시행기간 중에도 시행지역의 지적공부정리를 계속하여야 한다."],"a":[3],"L":"시1-4","o":"변형","x":{"한줄":"청산금 납부고지를 받은 자는 고지받은 날부터 6개월 이내에 청산금을 낸다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제76조제2항","원문":"제1항에 따른 납부고지를 받은 자는 그 고지를 받은 날부터 6개월 이내에 청산금을 지적소관청에 내야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제79조제1항","원문":"축척변경위원회는 5명 이상 10명 이하의 위원으로 구성하되, 위원의 2분의 1 이상을 토지소유자로 하여야 한다. 이 경우 그 축척변경 시행지역의 토지소유자가 5명 이하일 때에는 토지소유자 전원을 위원으로 위촉하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제71조제3항","원문":"축척변경 시행지역의 토지소유자 또는 점유자는 시행공고가 된 날(이하 “시행공고일”이라 한다)부터 30일 이내에 시행공고일 현재 점유하고 있는 경계에 국토교통부령으로 정하는 경계점표지를 설치하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제77조제1항","원문":"제76조제1항에 따라 납부고지되거나 수령통지된 청산금에 관하여 이의가 있는 자는 납부고지 또는 수령통지를 받은 날부터 1개월 이내에 지적소관청에 이의신청을 할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제74조","원문":"지적소관청은 축척변경 시행기간 중에는 축척변경 시행지역의 지적공부정리와 경계복원측량(제71조제3항에 따른 경계점표지의 설치를 위한 경계복원측량은 제외한다)을 제78조에 따른 축척변경 확정공고일까지 정지하여야 한다. 다만, 축척변경위원회의 의결이 있는 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"위원의 2분의 1 이상이 토지소유자여야 한다(영 제79조제1항). 소유자가 5명 이하이면 소유자 전원을 위촉한다."},{"번호":2,"판정":"틀림","설명":"경계점표지는 시행공고일부터 30일 이내에 설치한다(영 제71조제3항)."},{"번호":3,"판정":"옳음","설명":"납부고지를 받은 날부터 6개월 이내에 낸다(영 제76조제2항). 수령통지를 한 때도 지적소관청이 6개월 이내에 지급한다(제3항)."},{"번호":4,"판정":"틀림","설명":"이의신청 기간은 납부고지 또는 수령통지를 받은 날부터 1개월이다(영 제77조제1항)."},{"번호":5,"판정":"틀림","설명":"시행기간 중에는 지적공부정리와 경계복원측량을 확정공고일까지 정지한다(영 제74조). 위원회 의결이 있으면 예외다."}],"개념":[{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"신청ㆍ직권","설명":"토지소유자 신청 또는 지적소관청 직권. 소규모 필지 다수, 한 지번부여지역 내 다른 축척 지적도, 그 밖의 관리상 필요 (법 제83조제2항)."},{"이름":"동의ㆍ의결ㆍ승인","설명":"시행지역 토지소유자 3분의 2 이상 동의 → 축척변경위원회 의결 → 시ㆍ도지사 또는 대도시 시장 승인. 합병 대상 토지가 다른 축척 도면에 있는 경우와 도시개발사업 등에서 제외된 토지는 의결ㆍ승인 없이 가능 (법 제83조제3항)."},{"이름":"시행공고","설명":"승인 후 지체 없이 20일 이상 공고. 시ㆍ군ㆍ구와 시행지역 동ㆍ리 게시판에 게시 (영 제71조제1항ㆍ제2항)."},{"이름":"경계점표지 설치","설명":"소유자 또는 점유자가 공고일부터 30일 이내. 이 기간 동안 지적공부정리 정지 (영 제71조제3항, 제74조)."},{"이름":"측량ㆍ조서","설명":"각 필지의 지번ㆍ지목ㆍ면적ㆍ경계 또는 좌표를 새로 정하고 축척변경 지번별 조서 작성 (영 제72조, 제73조)."},{"이름":"청산금 산정ㆍ공고","설명":"위원회 의결로 지번별 제곱미터당 금액 결정, 청산금 조서 작성 후 15일 이상 공고 (영 제75조)."},{"이름":"납부고지ㆍ이의","설명":"공고일부터 20일 이내 납부고지ㆍ수령통지. 납부ㆍ지급 6개월, 이의신청 1개월 (영 제76조, 제77조)."},{"이름":"확정공고","설명":"청산금 납부ㆍ지급 완료 후 지체 없이 공고, 지적공부에 등록. 확정공고일에 토지의 이동이 있는 것으로 본다 (영 제78조)."}]},{"종류":"표","제목":"축척변경 기간ㆍ수치 모음","머리":["항목","기간ㆍ수치","근거"],"행":[["소유자 동의","시행지역 토지소유자 3분의 2 이상","법 제83조제3항"],["시행공고","20일 이상","영 제71조제1항"],["경계점표지 설치","시행공고일부터 30일 이내","영 제71조제3항"],["청산금 조서 공고","15일 이상","영 제75조제4항"],["납부고지ㆍ수령통지","청산금 결정 공고일부터 20일 이내","영 제76조제1항"],["청산금 납부ㆍ지급","고지(통지)받은 날부터 6개월 이내","영 제76조제2항ㆍ제3항"],["청산금 이의신청","고지(통지)받은 날부터 1개월 이내, 접수 후 1개월 이내 위원회 의결로 결정","영 제77조"],["위원회 구성","5명 이상 10명 이하, 2분의 1 이상 토지소유자","영 제79조제1항"],["위원회 회의 통지","개최 5일 전까지 서면 통지","영 제81조제3항"]]}],"함정":"1번의 「3분의 1」은 위원회 구성 비율을 2분의 1에서 바꾼 것이고, 2번의 「60일」은 30일을 바꾼 것이다. 숫자 선지는 기간이 비슷한 항목끼리 섞이므로 위 표의 기간을 짝지어 외워야 한다. 5번은 정리가 정지되는 기간이 확정공고일까지임을 안다."}},{"i":"S4-2-2-공시법-08","r":"S4","g":3,"c":2,"n":8,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 토지의 등록 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지적소관청은 토지이동현황을 직권으로 조사ㆍ측량하여 결정하려면 읍ㆍ면ㆍ동별로 토지이동현황 조사계획을 수립하는 것이 원칙이며, 부득이한 사유가 있는 때에 한하여 시ㆍ군ㆍ구별로 수립할 수 있다.","지적소관청은 지적공부에 등록된 지번을 변경할 필요가 있으면 토지소유자의 동의를 받아 지번부여지역의 전부 또는 일부에 대하여 새로 지번을 부여할 수 있다.","토지가 일시적 또는 임시적인 용도로 사용되는 경우에도 토지소유자가 신청하면 지적소관청은 지목을 변경하여야 한다.","1필지가 둘 이상의 용도로 활용되는 경우에는 용도별로 둘 이상의 지목을 설정하여야 한다.","지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 1필지 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."],"a":[5],"L":"시1-4","o":"변형","x":{"한줄":"600분의 1 지역과 경계점좌표등록부 지역은 1필지 면적이 0.1㎡ 미만이면 0.1㎡로 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제2호 단서","원문":"지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 … 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제59조제1항","원문":"지적소관청은 법 제64조제2항 단서에 따라 토지의 이동현황을 직권으로 조사ㆍ측량하여 토지의 지번ㆍ지목ㆍ면적ㆍ경계 또는 좌표를 결정하려는 때에는 토지이동현황 조사계획을 수립하여야 한다. 이 경우 토지이동현황 조사계획은 시ㆍ군ㆍ구별로 수립하되, 부득이한 사유가 있는 때에는 읍ㆍ면ㆍ동별로 수립할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제66조제2항","원문":"지적소관청은 지적공부에 등록된 지번을 변경할 필요가 있다고 인정하면 시ㆍ도지사나 대도시 시장의 승인을 받아 지번부여지역의 전부 또는 일부에 대하여 지번을 새로 부여할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제59조","원문":"법 제67조제1항에 따른 지목의 설정은 다음 각 호의 방법에 따른다. 1. 필지마다 하나의 지목을 설정할 것 2. 1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정할 것 / ② 토지가 일시적 또는 임시적인 용도로 사용될 때에는 지목을 변경하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"조사계획은 시ㆍ군ㆍ구별로 수립하는 것이 원칙이고, 부득이한 사유가 있을 때 읍ㆍ면ㆍ동별로 수립할 수 있다(규칙 제59조제1항). 원칙과 예외가 뒤바뀌었다."},{"번호":2,"판정":"틀림","설명":"지번 변경은 시ㆍ도지사 또는 대도시 시장의 승인을 받아야 한다(법 제66조제2항). 소유자 동의가 요건이 아니다."},{"번호":3,"판정":"틀림","설명":"일시적 또는 임시적 용도로 쓰이는 토지는 지목을 변경하지 않는다(영 제59조제2항)."},{"번호":4,"판정":"틀림","설명":"지목은 필지마다 하나를 설정하고, 둘 이상의 용도로 쓰이면 주된 용도에 따른다(영 제59조제1항)."},{"번호":5,"판정":"옳음","설명":"영 제60조제1항제2호 단서의 내용이다. 1㎡ 단위 지역은 1㎡ 미만을 1㎡로 한다는 제1호 단서와 구별한다."}],"개념":[{"종류":"표","제목":"토지의 등록 기본 규정","머리":["항목","내용","근거"],"행":[["등록 주체","국토교통부장관이 모든 토지를 필지별로 조사ㆍ측량해 지적공부에 등록","법 제64조제1항"],["결정 방식","토지의 이동이 있을 때 소유자 신청을 받아 지적소관청이 결정, 신청이 없으면 직권으로 조사ㆍ측량해 결정 가능","법 제64조제2항"],["지번 부여","지적소관청이 지번부여지역별로 차례대로 부여","법 제66조제1항"],["지번 변경","시ㆍ도지사나 대도시 시장의 승인","법 제66조제2항"],["지목 설정","필지마다 하나, 둘 이상 용도면 주된 용도, 일시적 용도는 변경하지 않음","영 제59조"],["면적 결정","1㎡ 단위(최소 1㎡) / 600분의 1ㆍ좌표등록부 지역은 0.1㎡ 단위(최소 0.1㎡)","영 제60조제1항"]]},{"종류":"흐름","제목":"직권 조사ㆍ측량에 의한 토지이동 정리","단계":[{"이름":"조사계획 수립","설명":"토지이동현황 조사계획. 시ㆍ군ㆍ구별로 수립, 부득이하면 읍ㆍ면ㆍ동별 (규칙 제59조제1항)."},{"이름":"현황 조사","설명":"조사한 현황을 토지이동 조사부에 적는다 (규칙 제59조제2항)."},{"이름":"결정","설명":"지번ㆍ지목ㆍ면적ㆍ경계 또는 좌표를 결정 (규칙 제59조제3항)."},{"이름":"지적공부 정리","설명":"토지이동 조사부를 근거로 토지이동 조서를 작성해 토지이동정리 결의서에 첨부 (규칙 제59조제4항)."}]}],"함정":"1번은 원칙과 예외를 맞바꾼 문장이다. 5번과 비슷한 문장인 「1필지가 1제곱미터 미만이면 1제곱미터」는 1㎡ 단위 지역의 규정이고, 600분의 1 지역과 좌표등록부 지역에서는 0.1㎡다."}},{"i":"S4-2-2-공시법-09","r":"S4","g":3,"c":2,"n":9,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적소관청이 토지의 이동 등으로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우 관할 등기관서에 그 등기를 촉탁하여야 하는 사유가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["행정구역의 개편으로 지번부여지역의 일부가 다른 지번부여지역에 속하게 되어 새로 지번을 부여한 경우","지적소관청이 지형의 변화로 바다가 된 토지의 등록을 직권으로 말소한 경우","멸실ㆍ훼손된 지적공부를 복구한 경우","잦은 토지의 이동으로 1필지의 규모가 작아 소축척으로는 정리가 곤란하여 축척을 변경한 경우","지적소관청이 지적공부의 등록사항에 잘못이 있음을 발견하고 직권으로 조사ㆍ측량하여 정정한 경우"],"a":[3],"L":"시1-4","o":"변형","x":{"한줄":"등기촉탁 사유는 법 제89조제1항이 열거한 조문으로 한정되고, 지적공부 복구(법 제74조)는 그 안에 없다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제89조제1항","원문":"지적소관청은 제64조제2항(신규등록은 제외한다), 제66조제2항, 제82조, 제83조제2항, 제84조제2항 또는 제85조제2항에 따른 사유로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁은 국가가 국가를 위하여 하는 등기로 본다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제85조제2항","원문":"지번부여지역의 일부가 행정구역의 개편으로 다른 지번부여지역에 속하게 되었으면 지적소관청은 새로 속하게 된 지번부여지역의 지번을 부여하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제74조","원문":"지적소관청(제69조제2항에 따른 지적공부의 경우에는 시ㆍ도지사, 시장ㆍ군수 또는 구청장)은 지적공부의 전부 또는 일부가 멸실되거나 훼손된 경우에는 대통령령으로 정하는 바에 따라 지체 없이 이를 복구하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"법 제85조제2항의 사유이고, 제89조제1항에 열거되어 촉탁 대상이다."},{"번호":2,"판정":"-","설명":"법 제82조의 사유(바다로 된 토지의 등록말소)이며 제89조제1항에 열거되어 촉탁 대상이다."},{"번호":3,"판정":"-","설명":"복구는 법 제74조의 사유로, 제89조제1항 열거에 없어 촉탁 대상이 아니다."},{"번호":4,"판정":"-","설명":"법 제83조제2항의 사유(축척변경)이며 제89조제1항에 열거되어 촉탁 대상이다."},{"번호":5,"판정":"-","설명":"법 제84조제2항의 사유(직권 등록사항 정정)이며 제89조제1항에 열거되어 촉탁 대상이다."}],"개념":[{"종류":"표","제목":"지적소관청의 등기촉탁 사유 (법 제89조제1항)","머리":["근거","사유","비고"],"행":[["법 제64조제2항","토지의 이동에 따른 지번ㆍ지목ㆍ면적ㆍ경계 또는 좌표의 결정","신규등록은 제외"],["법 제66조제2항","지번부여지역의 지번 변경","시ㆍ도지사 또는 대도시 시장 승인 후"],["법 제82조","바다로 된 토지의 등록말소","-"],["법 제83조제2항","축척변경","-"],["법 제84조제2항","지적소관청의 직권 등록사항 정정","-"],["법 제85조제2항","행정구역 개편에 따른 새 지번 부여","-"]]},{"종류":"표","제목":"촉탁ㆍ통지가 아닌 정리와 사후 통지","머리":["상황","처리","근거"],"행":[["신규등록 토지의 소유자","지적소관청이 직접 조사해 등록","법 제88조제1항 단서"],["소유자 변경","등기필증, 등기완료통지서, 등기사항증명서, 등기전산정보자료에 따라 정리","법 제88조제1항"],["등기부 표시와 지적공부가 다름","소유자를 정리하지 못하고 불일치 사실을 관할 등기관서에 통지","법 제88조제3항"],["지적공부 복구","복구자료 조사와 복구 절차 (등기촉탁 사유 아님)","법 제74조, 규칙 제73조"],["촉탁 후 토지소유자 통지 기한","변경등기가 필요하면 등기완료통지서 접수일부터 15일 이내, 불필요하면 지적공부 등록일부터 7일 이내","영 제85조"]]}],"함정":"복구도 지적공부를 고치는 지적정리지만 법 제89조제1항에 오르지 않았다. 지적소관청의 촉탁은 토지의 표시 변경등기가 필요한 법정 사유에 한정된다. 신규등록은 법 제64조제2항에 해당하지만 괄호로 제외되어 있다."}},{"i":"S4-2-2-공시법-10","r":"S4","g":3,"c":2,"n":10,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적측량 수행자가 지적측량 의뢰를 받은 때 그 다음 날까지 지적소관청에 제출하여야 하는 것으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지적측량 수행계획서","지적측량 의뢰서","토지이동현황 조사계획서","토지이동 정리결의서","지적측량 결과서"],"a":[1],"L":"시1-5","o":"기출","x":{"한줄":"지적측량수행자는 의뢰를 받은 때 측량기간ㆍ측량일자ㆍ수수료 등을 적은 수행계획서를 그 다음 날까지 지적소관청에 낸다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제25조제1항","원문":"법 제24조제1항에 따라 지적측량을 의뢰하려는 자는 별지 제15호서식의 지적측량 의뢰서(전자문서로 된 의뢰서를 포함한다)에 의뢰 사유를 증명하는 서류(전자문서를 포함한다)를 첨부하여 지적측량수행자에게 제출하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제25조제2항","원문":"지적측량수행자는 제1항에 따른 지적측량 의뢰를 받은 때에는 측량기간, 측량일자 및 측량 수수료 등을 적은 별지 제16호서식의 지적측량 수행계획서를 그 다음 날까지 지적소관청에 제출하여야 한다. 제출한 지적측량 수행계획서를 변경한 경우에도 같다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수행계획서가 규칙 제25조제2항에 따라 다음 날까지 지적소관청에 내는 서류이고, 계획을 변경한 때도 같다."},{"번호":2,"판정":"틀림","설명":"의뢰서는 의뢰인이 지적측량수행자에게 내는 서류다(규칙 제25조제1항)."},{"번호":3,"판정":"틀림","설명":"토지이동현황 조사계획은 지적소관청이 직권으로 토지이동을 조사ㆍ측량하려 할 때 스스로 세우는 계획이다(규칙 제59조제1항)."},{"번호":4,"판정":"틀림","설명":"토지이동정리 결의서는 지적소관청이 지적공부를 정리하면서 작성한다(영 제84조제2항)."},{"번호":5,"판정":"틀림","설명":"규칙 제25조제2항이 다음 날까지 내도록 정한 서류는 수행계획서뿐이다. 측량성과는 별도로 시ㆍ도지사, 대도시 시장 또는 지적소관청의 검사를 받는다(법 제25조제1항)."}],"개념":[{"종류":"표","제목":"지적측량 기간 (규칙 제25조제3항ㆍ제4항)","머리":["구분","기간"],"행":[["측량기간","5일"],["측량검사기간","4일"],["지적기준점을 설치하는 경우 (15점 이하)","측량ㆍ검사기간 각 4일"],["지적기준점을 설치하는 경우 (15점 초과)","4일에 15점을 초과하는 4점마다 1일 가산"],["의뢰인과 수행자가 합의한 기간","합의 기간 적용, 전체의 4분의 3은 측량기간, 4분의 1은 검사기간으로 봄"]]},{"종류":"흐름","제목":"지적측량 의뢰에서 적부심사까지","단계":[{"이름":"의뢰","설명":"의뢰서에 사유 증명서류를 붙여 지적측량수행자(지적측량업 등록자 또는 한국국토정보공사)에 제출 (법 제24조제1항, 규칙 제25조제1항)."},{"이름":"수행계획서 제출","설명":"의뢰받은 다음 날까지 지적소관청에 제출, 변경해도 같음 (규칙 제25조제2항)."},{"이름":"측량ㆍ성과 결정","설명":"측량기간 5일 (규칙 제25조제3항)."},{"이름":"성과검사","설명":"시ㆍ도지사, 대도시 시장 또는 지적소관청의 검사. 지적공부를 정리하지 않는 측량은 예외 (법 제25조제1항). 검사기간 4일."},{"이름":"적부심사","설명":"다툼이 있으면 시ㆍ도지사를 거쳐 지방지적위원회에 청구. 시ㆍ도지사 30일 내 조사 회부 → 위원회 60일 내 의결(30일 한 번 연장) → 시ㆍ도지사 7일 내 통지 → 불복 시 90일 내 중앙지적위원회 재심사 (법 제29조)."}]}],"함정":"서류 이름만 보면 2번 의뢰서를 고르기 쉽다. 의뢰서는 수행자에게 내는 서류이고, 지적소관청에 다음 날까지 내는 서류는 수행계획서다. 서류별 제출처를 따로 외워 둔다."}},{"i":"S4-2-2-공시법-11","r":"S4","g":3,"c":2,"n":11,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적기준점성과의 열람 및 등본 발급 신청에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지적삼각점성과는 지적소관청에만 신청하여야 한다.","지적삼각보조점성과는 지적소관청에 신청하여야 한다.","지적도근점성과는 시ㆍ도지사에게 신청하여야 한다.","지적삼각보조점성과는 한국국토정보공사에 신청하여야 한다.","지적삼각점성과와 지적도근점성과는 모두 시ㆍ도지사 또는 지적소관청에 신청할 수 있다."],"a":[2],"L":"시1-5","o":"변형","x":{"한줄":"지적삼각점성과는 시ㆍ도지사 또는 지적소관청에, 지적삼각보조점성과와 지적도근점성과는 지적소관청에 신청한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제26조제1항","원문":"법 제27조에 따라 지적측량기준점성과 또는 그 측량부를 열람하거나 등본을 발급받으려는 자는 지적삼각점성과에 대해서는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 “시ㆍ도지사”라 한다) 또는 지적소관청에 신청하고, 지적삼각보조점성과 및 지적도근점성과에 대해서는 지적소관청에 신청하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제27조","원문":"시ㆍ도지사나 지적소관청은 지적기준점성과(지적기준점에 의한 측량성과를 말한다. 이하 같다)와 그 측량기록을 보관하고 일반인이 열람할 수 있도록 하여야 한다. / 지적기준점성과의 등본이나 그 측량기록의 사본을 발급받으려는 자는 국토교통부령으로 정하는 바에 따라 시ㆍ도지사나 지적소관청에 그 발급을 신청하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"삼각점성과는 시ㆍ도지사 또는 지적소관청 둘 중 어느 곳에든 신청한다(규칙 제26조제1항)."},{"번호":2,"판정":"옳음","설명":"삼각보조점성과는 지적소관청에 신청한다(규칙 제26조제1항)."},{"번호":3,"판정":"틀림","설명":"도근점성과는 지적소관청에만 신청한다. 시ㆍ도지사는 신청처가 아니다."},{"번호":4,"판정":"틀림","설명":"한국국토정보공사는 지적측량수행자이지 성과의 열람ㆍ등본 신청처가 아니다(법 제27조, 규칙 제26조제1항)."},{"번호":5,"판정":"틀림","설명":"도근점성과는 지적소관청에만 신청하므로 도근점성과까지 시ㆍ도지사에게 신청할 수 있다는 부분이 틀리다."}],"개념":[{"종류":"표","제목":"지적기준점성과 열람ㆍ등본 신청처","머리":["성과","신청처","근거"],"행":[["지적삼각점성과","시ㆍ도지사 또는 지적소관청","규칙 제26조제1항"],["지적삼각보조점성과","지적소관청","규칙 제26조제1항"],["지적도근점성과","지적소관청","규칙 제26조제1항"],["보관ㆍ열람 의무","시ㆍ도지사나 지적소관청이 성과와 측량기록을 보관하고 일반인이 열람하게 함","법 제27조제1항"],["신청 서식","열람ㆍ등본 발급 신청서는 별지 제17호서식, 등본은 별지 제18호서식","규칙 제26조제2항ㆍ제3항"]]}],"함정":"지적삼각점만 시ㆍ도지사에게도 신청할 수 있다. 4번의 한국국토정보공사처럼 측량을 대행하는 기관은 신청처로 나오지 않는다."}},{"i":"S4-2-2-공시법-12","r":"S4","g":3,"c":2,"n":12,"s":"공시법","q":"부동산등기법상 등기소와 등기부에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기부는 영구히 보존하여야 하며, 등기사항을 새로운 등기기록에 옮겨 기록하여 폐쇄한 종전 등기기록도 영구히 보존하여야 한다.","누구든지 수수료를 내고 등기기록의 열람과 등기사항증명서의 발급을 청구할 수 있으나, 등기기록의 부속서류는 이해관계 있는 부분만 열람을 청구할 수 있다.","등기관이 등기를 마친 경우 그 등기는 접수한 때부터 효력을 발생한다.","관할 등기소가 다른 여러 개의 부동산과 관련하여 등기목적과 등기원인이 동일한 경우에는 그 중 하나의 관할 등기소에서 해당 신청에 따른 등기사무를 담당할 수 있다.","부동산이 여러 등기소의 관할구역에 걸쳐 있을 때에는 신청인이 그 중 어느 하나를 선택하여 등기를 신청한 등기소가 관할 등기소가 된다."],"a":[5],"L":"시2-1","o":"변형","x":{"한줄":"여러 등기소 관할에 걸친 부동산은 선택이 아니라 상급법원의 장이 관할 등기소를 지정한다.","근거":[{"법령":"부동산등기법","조문":"제7조제2항","원문":"부동산이 여러 등기소의 관할구역에 걸쳐 있을 때에는 대법원규칙으로 정하는 바에 따라 각 등기소를 관할하는 상급법원의 장이 관할 등기소를 지정한다."},{"법령":"부동산등기규칙","조문":"제5조제1항","원문":"부동산이 여러 등기소의 관할구역에 걸쳐 있는 경우 그 부동산에 대한 최초의 등기신청을 하고자 하는 자는 각 등기소를 관할하는 상급법원의 장에게 관할등기소의 지정을 신청하여야 한다."},{"법령":"부동산등기법","조문":"제7조의2제1항","원문":"제7조에도 불구하고 관할 등기소가 다른 여러 개의 부동산과 관련하여 등기목적과 등기원인이 동일하거나 그 밖에 대법원규칙으로 정하는 등기신청이 있는 경우에는 그 중 하나의 관할 등기소에서 해당 신청에 따른 등기사무를 담당할 수 있다."},{"법령":"부동산등기법","조문":"제6조제2항","원문":"제11조제1항에 따른 등기관이 등기를 마친 경우 그 등기는 접수한 때부터 효력을 발생한다."},{"법령":"부동산등기법","조문":"제19조제1항","원문":"누구든지 수수료를 내고 대법원규칙으로 정하는 바에 따라 등기기록에 기록되어 있는 사항의 전부 또는 일부의 열람(閱覽)과 이를 증명하는 등기사항증명서의 발급을 청구할 수 있다. 다만, 등기기록의 부속서류에 대하여는 이해관계 있는 부분만 열람을 청구할 수 있다."},{"법령":"부동산등기법","조문":"제20조제2항ㆍ제3항","원문":"폐쇄한 등기기록은 영구히 보존하여야 한다. / 폐쇄한 등기기록에 관하여는 제19조를 준용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"등기부는 영구 보존(법 제14조제2항), 폐쇄한 등기기록도 영구 보존(법 제20조제2항)이다."},{"번호":2,"판정":"옳음","설명":"열람ㆍ증명서 발급은 이해관계를 따지지 않고 청구할 수 있고, 부속서류만 이해관계 있는 부분으로 제한된다(법 제19조제1항)."},{"번호":3,"판정":"옳음","설명":"효력은 마친 때가 아니라 접수한 때로 거슬러 올라간다(법 제6조제2항)."},{"번호":4,"판정":"옳음","설명":"동일한 목적ㆍ원인의 여러 부동산 등기는 그 중 한 등기소에서 처리할 수 있다(법 제7조의2제1항)."},{"번호":5,"판정":"틀림","설명":"관할 등기소는 상급법원의 장이 지정한다(법 제7조제2항). 신청인은 지정을 신청할 뿐 관할 등기소를 선택하지 못한다(규칙 제5조제1항)."}],"개념":[{"종류":"표","제목":"관할 등기소 정하기","머리":["상황","관할","근거"],"행":[["원칙","부동산 소재지 관할 지방법원, 지원 또는 등기소","법 제7조제1항"],["여러 등기소 관할에 걸침","각 등기소를 관할하는 상급법원의 장이 지정","법 제7조제2항"],["관할이 다른 여러 부동산, 목적과 원인이 동일","그 중 하나의 관할 등기소에서 처리 가능","법 제7조의2제1항"],["상속ㆍ유증으로 인한 등기","부동산 관할이 아닌 등기소도 처리 가능","법 제7조의3제1항"],["관할의 위임","대법원장이 다른 등기소에 위임하게 할 수 있음","법 제8조"],["관할 변경","종전 등기소가 등기기록 처리권한을 넘겨줌","법 제9조"]]},{"종류":"표","제목":"등기기록의 구성","머리":["구분","기록 내용","근거"],"행":[["표제부","부동산의 표시에 관한 사항 (토지: 표시번호ㆍ접수연월일ㆍ소재와 지번ㆍ지목ㆍ면적ㆍ등기원인)","법 제15조제2항, 제34조"],["갑구","소유권에 관한 사항","법 제15조제2항"],["을구","소유권 외의 권리에 관한 사항","법 제15조제2항"],["편성 원칙","1필의 토지 또는 1개의 건물마다 1개의 등기기록 (구분건물은 1동 전부에 1개)","법 제15조제1항"],["갑구ㆍ을구 기록사항","순위번호, 등기목적, 접수연월일ㆍ접수번호, 등기원인과 연월일, 권리자 (표시번호는 표제부 사항)","법 제48조제1항"]]}],"함정":"5번은 신청인에게 선택권이 있는 것처럼 쓴 문장이다. 신청인이 하는 일은 어느 등기소에든 지정 신청서를 내는 것까지이고, 지정은 상급법원의 장이 한다. 3번의 「접수한 때」를 「마친 때」로 바꾼 선지가 자주 나온다."}},{"i":"S4-2-2-공시법-13","r":"S4","g":3,"c":2,"n":13,"s":"공시법","q":"등기의 신청에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공동상속인 중 일부는 자신의 상속지분만에 대한 상속 등기를 신청할 수 없다.","「민법」상 조합재산에 속하는 부동산의 등기는 그 조합의 명의로 조합원이 신청할 수 있다.","등기원인이 발생한 후에 등기권리자에 대하여 상속이 있는 경우, 상속인이 그 등기를 신청할 수 있다.","건물 또는 토지의 소유권을 포기한 경우, 그 소유권을 포기한 자는 단독으로 그에 따른 등기를 신청할 수 없다.","전세권의 범위를 10층 북쪽 201m²에서 3층 동쪽 485m²로 변경하는 경우, 전세권변경등기가 아니라 별개의 전세권 설정등기를 신청해야 한다."],"a":[2],"L":"시2-2","o":"기출","x":{"한줄":"민법상 조합은 등기 명의인이 될 수 없어 조합원 전원 명의의 합유등기로 한다.","근거":[{"법령":"부동산등기법","조문":"제26조제1항","원문":"종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다."},{"법령":"부동산등기법","조문":"제48조제4항","원문":"제1항제5호의 권리자가 2인 이상인 경우에는 권리자별 지분을 기록하여야 하고 등기할 권리가 합유(合有)인 때에는 그 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제27조","원문":"등기원인이 발생한 후에 등기권리자 또는 등기의무자에 대하여 상속이나 그 밖의 포괄승계가 있는 경우에는 상속인이나 그 밖의 포괄승계인이 그 등기를 신청할 수 있다."},{"법령":"부동산등기규칙","조문":"제52조제7호","원문":"법 제29조제2호에서 “사건이 등기할 것이 아닌 경우”란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. … 7. 공동상속인 중 일부가 자신의 상속지분만에 대한 상속등기를 신청한 경우"},{"법령":"부동산등기법","조문":"제23조제1항","원문":"등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속지분 일부만의 상속등기 신청은 각하 사유다(규칙 제52조제7호)."},{"번호":2,"판정":"틀림","설명":"단체 명의로 등기할 수 있는 것은 대표자나 관리인이 있는 법인 아닌 사단ㆍ재단이다(법 제26조). 조합은 이에 해당하지 않아 조합원 전원 명의로 합유라는 뜻을 함께 신청ㆍ기록한다(법 제48조제4항, 규칙 제105조제2항)."},{"번호":3,"판정":"옳음","설명":"등기원인 발생 후 권리자에게 상속이 있으면 상속인이 그 등기를 신청한다(법 제27조)."},{"번호":4,"판정":"옳음","설명":"단독신청을 허용하는 규정에 소유권 포기가 없다. 포기에 따른 이전등기는 공동신청 원칙(법 제23조제1항)이 적용된다."},{"번호":5,"판정":"옳음","설명":"변경등기는 권리의 동일성이 유지되는 범위에서만 한다. 층ㆍ방위ㆍ면적이 모두 달라지면 동일한 전세권으로 볼 수 없어 새 설정등기를 한다는 것이 등기실무의 태도다."}],"개념":[{"종류":"표","제목":"단독신청 사유 정리","머리":["사유","단독 신청인","근거"],"행":[["소유권보존등기와 그 말소등기","등기명의인으로 될 자 또는 등기명의인","법 제23조제2항"],["상속, 법인합병 등 포괄승계","등기권리자","법 제23조제3항"],["이행ㆍ인수를 명하는 판결","승소한 등기권리자 또는 등기의무자","법 제23조제4항"],["공유물분할 판결","등기권리자 또는 등기의무자","법 제23조제4항"],["부동산표시의 변경ㆍ경정","소유권의 등기명의인","법 제23조제5항"],["등기명의인표시의 변경ㆍ경정","해당 권리의 등기명의인","법 제23조제6항"],["신탁등기","수탁자","법 제23조제7항"],["수용으로 인한 소유권이전","등기권리자","법 제99조제1항"],["가등기","가등기권리자 (의무자 승낙 또는 가처분명령이 있을 때)","법 제89조"],["가등기 말소","가등기명의인","법 제93조제1항"]]},{"종류":"표","제목":"사건이 등기할 것이 아닌 경우 (각하 사유)","머리":["유형","예"],"행":[["등기능력 없는 물건ㆍ권리","등기할 수 없는 대상에 대한 신청"],["법령 근거 없는 특약","법령에 근거가 없는 특약사항의 등기"],["분리처분 금지 위반","구분건물의 전유부분과 대지사용권을 분리해 처분하는 등기"],["농지의 전세권 설정","농지를 전세권 목적으로 하는 등기"],["저당권의 분리 양도","피담보채권과 분리한 양도, 다른 채권의 담보"],["일부지분 보존등기","일부지분에 대한 소유권보존등기"],["일부 상속인의 자기 지분 상속등기","공동상속인 중 일부가 자기 지분만 신청"],["촉탁 대상 등기를 신청","관공서 또는 법원의 촉탁으로 해야 할 등기를 신청"],["이중 보존","이미 보존등기된 부동산에 다시 보존등기 신청"]]}],"함정":"3번의 「상속인이 등기를 신청」과 1번의 「일부 상속인이 자기 지분만 신청」은 서로 다른 장면이다. 포괄승계인은 피상속인의 지위를 이어 신청하는 것이고, 지분 일부만 상속등기를 하는 것은 규칙 제52조제7호가 각하한다. 2번은 법인 아닌 사단ㆍ재단 규정(법 제26조)을 조합에 잘못 끌어다 쓴 선지다."}},{"i":"S4-2-2-공시법-14","r":"S4","g":3,"c":2,"n":14,"s":"공시법","q":"등기신청에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["등기신청은 1건당 1개의 부동산에 관한 신청정보를 제공해야 하므로, 같은 채권의 담보를 위하여 소유자가 다른 여러 개의 부동산에 저당권설정등기를 신청하는 경우에도 부동산마다 따로 신청해야 한다.","소유권이전등기를 신청하는 경우 등기권리자의 주소증명정보만 제공하면 되고 등기의무자의 주소증명정보는 제공하지 않는다.","등기신청의 취하는 신청인이 등기소에 출석하여 취하서를 제출하는 방법으로만 할 수 있고, 전자신청의 취하는 허용되지 않는다.","승소한 등기의무자가 단독으로 권리에 관한 등기를 신청하는 경우에도 신청정보와 함께 등기의무자의 등기필정보를 등기소에 제공하여야 한다.","법인 아닌 사단이 등기의무자로서 등기를 신청하는 경우에는 「민법」 제276조제1항의 결의가 있음을 증명하는 정보를 제공할 필요가 없다."],"a":[4],"L":"시2-2","o":"변형","x":{"한줄":"승소한 등기의무자의 단독신청에도 등기의무자의 등기필정보를 제공해야 한다.","근거":[{"법령":"부동산등기법","조문":"제50조제2항","원문":"등기권리자와 등기의무자가 공동으로 권리에 관한 등기를 신청하는 경우에 신청인은 그 신청정보와 함께 제1항에 따라 통지받은 등기의무자의 등기필정보를 등기소에 제공하여야 한다. 승소한 등기의무자가 단독으로 권리에 관한 등기를 신청하는 경우에도 또한 같다."},{"법령":"부동산등기규칙","조문":"제43조제1항제7호","원문":"등기필정보. 다만, 공동신청 또는 승소한 등기의무자의 단독신청에 의하여 권리에 관한 등기를 신청하는 경우로 한정한다."},{"법령":"부동산등기법","조문":"제25조","원문":"등기의 신청은 1건당 1개의 부동산에 관한 신청정보를 제공하는 방법으로 하여야 한다. 다만, 등기목적과 등기원인이 동일하거나 그 밖에 대법원규칙으로 정하는 경우에는 여러 개의 부동산에 관한 신청정보를 일괄하여 제공하는 방법으로 할 수 있다."},{"법령":"부동산등기규칙","조문":"제47조제1항제1호","원문":"법 제25조 단서에 따라 다음 각 호의 경우에는 1건의 신청정보로 일괄하여 신청하거나 촉탁할 수 있다. 1. 같은 채권의 담보를 위하여 소유자가 다른 여러 개의 부동산에 대한 저당권설정등기를 신청하는 경우"},{"법령":"부동산등기규칙","조문":"제46조제1항제6호","원문":"등기권리자(새로 등기명의인이 되는 경우로 한정한다)의 주소(또는 사무소 소재지) 및 주민등록번호(또는 부동산등기용등록번호)를 증명하는 정보. 다만, 소유권이전등기를 신청하는 경우 또는 제52조의2제1항에 따라 등기의무자의 동일성 확인이 필요한 경우에는 등기의무자의 주소(또는 사무소 소재지)를 증명하는 정보도 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제51조제2항","원문":"제1항의 취하는 다음 각 호의 구분에 따른 방법으로 하여야 한다. 1. 방문신청: 신청인 또는 그 대리인이 등기신청을 한 등기소에 출석하여 취하서를 제출하는 방법 2. 전자신청: 전산정보처리조직을 이용하여 취하정보를 전자문서로 등기신청을 한 등기소에 송신하는 방법"},{"법령":"부동산등기규칙","조문":"제48조제3호","원문":"「민법」 제276조제1항의 결의가 있음을 증명하는 정보(법인 아닌 사단이 등기의무자인 경우로 한정한다)"}],"선지":[{"번호":1,"판정":"틀림","설명":"같은 채권을 담보하는 저당권설정등기는 소유자가 달라도 1건의 신청정보로 일괄 신청할 수 있다(규칙 제47조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"소유권이전등기에서는 등기권리자뿐 아니라 등기의무자의 주소증명정보도 제공한다(규칙 제46조제1항제6호 단서)."},{"번호":3,"판정":"틀림","설명":"방문신청은 출석해 취하서를 제출하고, 전자신청은 취하정보를 전자문서로 송신한다(규칙 제51조제2항)."},{"번호":4,"판정":"옳음","설명":"승소한 등기의무자의 단독신청도 등기필정보 제공 대상이다(법 제50조제2항 후단, 규칙 제43조제1항제7호)."},{"번호":5,"판정":"틀림","설명":"법인 아닌 사단이 등기의무자이면 사원총회 결의(민법 제276조제1항)를 증명하는 정보를 제공해야 한다(규칙 제48조제3호)."}],"개념":[{"종류":"표","제목":"신청정보와 첨부정보 주요 항목","머리":["구분","항목","근거"],"행":[["신청정보","부동산 표시, 신청인 성명ㆍ주소ㆍ주민등록번호, 대리인, 등기원인과 연월일, 등기목적, 등기필정보, 등기소 표시, 신청연월일","규칙 제43조제1항"],["신청정보","취득세ㆍ등록면허세 등 납부 세액과 과세표준액","규칙 제44조제1항"],["첨부정보","등기원인증명정보, 제3자의 허가ㆍ동의ㆍ승낙 증명, 이해관계 있는 제3자의 승낙 증명","규칙 제46조제1항제1호~제3호"],["첨부정보","법인 대표자 자격, 대리인 권한을 증명하는 정보","규칙 제46조제1항제4호ㆍ제5호"],["첨부정보","등기권리자의 주소ㆍ등록번호 증명 (소유권이전이면 등기의무자 주소 증명도)","규칙 제46조제1항제6호"],["첨부정보","소유권이전등기이면 토지대장ㆍ임야대장ㆍ건축물대장 정보","규칙 제46조제1항제7호"],["첨부정보","법인 아닌 사단ㆍ재단: 정관, 대표자 증명, 사원총회 결의(의무자인 경우), 대표자 주소ㆍ주민등록번호 증명","규칙 제48조"]]},{"종류":"표","제목":"등기필정보 작성ㆍ통지를 하지 않는 경우","머리":["경우","근거"],"행":[["등기권리자가 통지를 원하지 않는 경우","법 제50조제1항제1호"],["국가 또는 지방자치단체가 등기권리자인 경우","법 제50조제1항제2호"],["전자 통지를 받을 수 있는 때부터 3개월 내 수신하지 않은 경우","규칙 제109조제2항제1호"],["등기필정보통지서를 등기 후 3개월 내 수령하지 않은 경우","규칙 제109조제2항제2호"],["승소한 등기의무자가 신청한 경우","규칙 제109조제2항제3호"],["채권자대위로 등기권리자를 대위해 신청한 경우","규칙 제109조제2항제4호"],["등기관이 직권으로 소유권보존등기를 한 경우","규칙 제109조제2항제5호"],["공유물 보존행위로 공유자 전원을 권리자로 신청한 경우(나머지 공유자가 권리자인 경우)","규칙 제109조제2항제6호"]]}],"함정":"3번처럼 방문신청 방식만 쓴 선지는 취하 규정의 절반만 담았다. 5번은 법인 아닌 사단이 등기권리자일 때와 등기의무자일 때의 첨부정보를 섞은 선지로, 결의 증명은 의무자일 때만 낸다. 4번에서 제공하는 등기필정보는 새 권리자가 받는 것이 아니라 종전에 통지받아 둔 등기의무자의 등기필정보다."}},{"i":"S4-2-2-공시법-15","r":"S4","g":3,"c":2,"n":15,"s":"공시법","q":"등기관의 처분에 대한 이의신청에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기신청인이 아닌 제3자는 등기신청의 각하결정에 대하여 이의신청을 할 수 없다.","이의신청은 대법원규칙으로 정하는 바에 따라 관할 지방법원에 이의신청서를 제출하는 방법으로 한다.","이의신청기간에는 제한이 없으므로 이의의 이익이 있는 한 언제라도 이의신청을 할 수 있다.","등기관의 처분시에 주장하거나 제출하지 아니한 새로운 사실을 근거로 이의신청을 할 수 없다.","등기관의 처분에 대한 이의신청이 있더라도 그 부동산에 대한 다른 등기신청은 수리된다."],"a":[2],"L":"시2-2","o":"기출","x":{"한줄":"이의신청서는 관할 지방법원이 아니라 결정ㆍ처분을 한 등기관이 속한 등기소에 제출한다.","근거":[{"법령":"부동산등기법","조문":"제100조","원문":"등기관의 결정 또는 처분에 이의가 있는 자는 그 결정 또는 처분을 한 등기관이 속한 지방법원(이하 이 장에서 “관할 지방법원”이라 한다)에 이의신청을 할 수 있다."},{"법령":"부동산등기법","조문":"제101조","원문":"제100조에 따른 이의신청(이하 이 장에서 “이의신청”이라 한다)은 대법원규칙으로 정하는 바에 따라 결정 또는 처분을 한 등기관이 속한 등기소에 이의신청서를 제출하거나 전산정보처리조직을 이용하여 이의신청정보를 보내는 방법으로 한다."},{"법령":"부동산등기법","조문":"제102조","원문":"새로운 사실이나 새로운 증거방법을 근거로 이의신청을 할 수는 없다."},{"법령":"부동산등기법","조문":"제103조제2항","원문":"등기관은 이의가 이유 없다고 인정하면 이의신청일부터 3일 이내에 의견을 붙여 이의신청서 또는 이의신청정보를 관할 지방법원에 보내야 한다."},{"법령":"부동산등기법","조문":"제104조","원문":"이의에는 집행정지(執行停止)의 효력이 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"각하결정은 신청인에게만 불이익을 주므로 신청인이 아닌 제3자에게는 이의의 이익이 없다. 법 제100조의 「이의가 있는 자」는 이 범위로 읽는다."},{"번호":2,"판정":"틀림","설명":"관할 지방법원은 이의에 대해 결정하는 법원이고, 이의신청서는 등기관이 속한 등기소에 낸다(법 제101조). 등기소가 이의신청서를 관할 지방법원에 보낸다(법 제103조제2항)."},{"번호":3,"판정":"옳음","설명":"법 제100조~제108조에 이의신청 기간 제한 규정이 없다."},{"번호":4,"판정":"옳음","설명":"새로운 사실이나 새로운 증거방법을 근거로 한 이의는 허용되지 않는다(법 제102조)."},{"번호":5,"판정":"옳음","설명":"이의에는 집행정지 효력이 없어(법 제104조) 다른 등기신청은 계속 처리된다."}],"개념":[{"종류":"흐름","제목":"등기관의 처분에 대한 이의 절차","단계":[{"이름":"이의신청","설명":"결정ㆍ처분을 한 등기관이 속한 등기소에 이의신청서 제출 또는 이의신청정보 전송 (법 제101조). 기간 제한 없음, 새로운 사실ㆍ증거방법 불가 (법 제102조)."},{"이름":"등기관의 판단","설명":"이유 있으면 그에 해당하는 처분 (법 제103조제1항)."},{"이름":"관할 지방법원 송부","설명":"이유 없으면 이의신청일부터 3일 이내 의견을 붙여 송부. 등기를 마친 후의 이의는 이해관계인에게 이의 사실도 통지 (법 제103조제2항ㆍ제3항)."},{"이름":"지방법원의 조치","설명":"결정 전에 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있음 (법 제106조)."},{"이름":"결정","설명":"이유를 붙여 결정. 이유 있으면 등기관에게 처분 명령 (법 제105조제1항)."},{"이름":"항고","설명":"비송사건절차법에 따라 항고 (법 제105조제2항)."}]},{"종류":"표","제목":"이의신청 규정 요약","머리":["항목","내용","근거"],"행":[["관할","처분한 등기관이 속한 지방법원","법 제100조"],["제출처","처분한 등기관이 속한 등기소","법 제101조"],["새로운 사실","근거로 삼을 수 없음","법 제102조"],["집행정지","효력 없음","법 제104조"],["법원 명령에 따른 등기","명령한 법원, 명령 연월일, 명령에 따라 등기한다는 뜻 기록","법 제107조"]]}],"함정":"2번은 이의 「관할」과 이의신청서 「제출처」를 섞은 선지다. 이의에 대한 판단은 관할 지방법원이 하지만 서류는 등기소에 낸다. 5번은 이의신청 중에도 같은 부동산의 다른 등기신청이 접수ㆍ처리된다는 뜻이며 집행 부정지에서 나온다.","개정":"법 제100조ㆍ제103조는 <개정 2024.9.20> 표시가 있다. 현행 제101조는 이의신청서를 등기소에 제출하거나 전산정보처리조직으로 이의신청정보를 보내는 두 방식이다. 정답은 달라지지 않는다."}},{"i":"S4-2-2-공시법-16","r":"S4","g":3,"c":2,"n":16,"s":"공시법","q":"부동산등기의 신청에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인 아닌 사단이나 재단은 전자신청을 할 수 없다.","공유자 중 1인은 자기 지분만의 소유권이전등기를 신청할 수 없다.","공유지분을 목적으로 하는 지상권설정등기를 공동으로 신청할 수 없다.","외국인은 외국인등록을 하였거나 국내거소신고를 한 경우에 전자신청을 할 수 있다.","소유권의 등기명의인인 지방자치단체가 등기의무자로서 등기를 방문신청하는 경우, 인감증명을 제출할 필요가 없다."],"a":[2],"L":"시2-2","o":"기출","x":{"한줄":"공유자는 자기 지분만 소유권이전등기를 신청할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제67조제1항","원문":"등기관이 소유권의 일부에 관한 이전등기를 할 때에는 이전되는 지분을 기록하여야 한다. 이 경우 등기원인에 「민법」 제268조제1항 단서의 약정이 있을 때에는 그 약정에 관한 사항도 기록하여야 한다."},{"법령":"부동산등기규칙","조문":"제123조","원문":"소유권의 일부에 대한 이전등기를 신청하는 경우에는 이전되는 지분을 신청정보의 내용으로 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제67조제1항","원문":"전자신청은 당사자가 직접 하거나 자격자대리인이 당사자를 대리하여 한다. 다만, 법인 아닌 사단이나 재단은 전자신청을 할 수 없으며, 외국인의 경우에는 다음 각 호의 어느 하나에 해당하는 요건을 갖추어야 한다. 1. 「출입국관리법」 제31조에 따른 외국인등록 2. 「재외동포의 출입국과 법적 지위에 관한 법률」 제6조, 제7조에 따른 국내거소신고"},{"법령":"부동산등기규칙","조문":"제60조제3항","원문":"제1항에 따라 인감증명을 제출하여야 하는 자가 국가 또는 지방자치단체인 경우에는 인감증명을 제출할 필요가 없다."},{"법령":"부동산등기규칙","조문":"제52조제10호","원문":"그 밖에 신청취지 자체에 의하여 법률상 허용될 수 없음이 명백한 등기를 신청한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인 아닌 사단ㆍ재단은 전자신청을 할 수 없다(규칙 제67조제1항 본문 단서)."},{"번호":2,"판정":"틀림","설명":"소유권 일부(지분)의 이전등기는 이전되는 지분을 신청정보로 제공해 신청한다(법 제67조제1항, 규칙 제123조). 자기 지분만 이전하는 신청이 가능하다."},{"번호":3,"판정":"옳음","설명":"지상권은 토지 전부를 사용하는 권리라 공유지분만을 목적으로 하는 설정등기는 법률상 허용될 수 없음이 명백한 신청이다(규칙 제52조제10호)."},{"번호":4,"판정":"옳음","설명":"외국인은 외국인등록이나 국내거소신고를 갖추어야 전자신청을 할 수 있다(규칙 제67조제1항제1호ㆍ제2호)."},{"번호":5,"판정":"옳음","설명":"국가 또는 지방자치단체는 인감증명을 제출하지 않는다(규칙 제60조제3항)."}],"개념":[{"종류":"비교","제목":"방문신청과 전자신청","왼쪽":{"이름":"방문신청","항목":["신청인 또는 대리인이 등기소에 출석해 서면 제출 (법 제24조제1항제1호)","대리인이 변호사ㆍ법무사이면 사무원을 출석시켜 제출 가능","인감증명 제출 (규칙 제60조)","출석하지 않으면 각하 (법 제29조제4호)","도면은 전자문서로 작성해 송신이 원칙 (규칙 제63조)"]},"오른쪽":{"이름":"전자신청","항목":["전산정보처리조직(애플리케이션 포함)으로 신청정보와 첨부정보 송신 (법 제24조제1항제2호)","당사자가 직접 하거나 자격자대리인이 대리 (규칙 제67조제1항)","법인 아닌 사단ㆍ재단은 불가, 외국인은 외국인등록 또는 국내거소신고 필요","사용자등록 선행, 유효기간 3년 (규칙 제68조, 제69조)","사용자등록번호ㆍ등기필정보를 제공하지 않으면 송신 불가 (규칙 제67조제2항)"]}},{"종류":"표","제목":"인감증명을 제출하는 경우 (방문신청)","머리":["제출 사유","제출자","근거"],"행":[["소유권 등기명의인이 등기의무자로 신청","등기의무자","규칙 제60조제1항제1호"],["소유권 가등기명의인이 가등기 말소 신청","가등기명의인","규칙 제60조제1항제2호"],["소유권 외 권리 명의인이 등기필정보 없이 신청(법 제51조)","등기의무자","규칙 제60조제1항제3호"],["토지합필등기 확인서 첨부","토지소유자들","규칙 제60조제1항제4호"],["토지분필등기 권리자 확인서 첨부","권리자","규칙 제60조제1항제5호"],["협의분할 상속등기","상속인 전원","규칙 제60조제1항제6호"],["제3자의 동의 또는 승낙서 첨부","제3자","규칙 제60조제1항제7호"],["예외","국가ㆍ지방자치단체는 제출하지 않음","규칙 제60조제3항"],["유효기간","발행일부터 3개월 이내","규칙 제62조"]]}],"함정":"1번과 4번은 전자신청 자격을 묻는 선지로 규칙 제67조제1항 하나에서 나온다. 3번의 지분 위 지상권은 소유권 지분 이전과 다르게 설정이 막힌다. 소유권은 지분 단위로 이전할 수 있지만, 지상권 같은 용익권은 지분만을 목적으로 설정할 수 없다."}},{"i":"S4-2-2-공시법-17","r":"S4","g":3,"c":2,"n":17,"s":"공시법","q":"대장은 편성되어 있으나 미등기인 부동산의 소유권보존등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기관이 보존등기를 할 때에는 등기원인과 그 연월일을 기록해야 한다.","대장에 최초 소유자로 등록된 자의 상속인은 보존등기를 신청할 수 있다.","수용으로 인하여 소유권을 취득하였음을 증명하는 자는 미등기토지에 대한 보존등기를 신청할 수 있다.","군수의 확인에 의해 미등기건물에 대한 자기의 소유권을 증명하는 자는 보존등기를 신청할 수 있다.","등기관이 법원의 촉탁에 따라 소유권의 처분제한의 등기를 할 때는 직권으로 보존등기를 한다."],"a":[1],"L":"시2-3","o":"기출","x":{"한줄":"소유권보존등기에는 등기원인과 그 연월일을 기록하지 않는다.","근거":[{"법령":"부동산등기법","조문":"제64조","원문":"등기관이 소유권보존등기를 할 때에는 제48조제1항제4호에도 불구하고 등기원인과 그 연월일을 기록하지 아니한다."},{"법령":"부동산등기법","조문":"제65조","원문":"미등기의 토지 또는 건물에 관한 소유권보존등기는 다음 각 호의 어느 하나에 해당하는 자가 신청할 수 있다. 1. 토지대장, 임야대장 또는 건축물대장에 최초의 소유자로 등록되어 있는 자 또는 그 상속인, 그 밖의 포괄승계인 2. 확정판결에 의하여 자기의 소유권을 증명하는 자 3. 수용(收用)으로 인하여 소유권을 취득하였음을 증명하는 자 4. 특별자치도지사, 시장, 군수 또는 구청장(자치구의 구청장을 말한다)의 확인에 의하여 자기의 소유권을 증명하는 자(건물의 경우로 한정한다)"},{"법령":"부동산등기법","조문":"제66조제1항","원문":"등기관이 미등기부동산에 대하여 법원의 촉탁에 따라 소유권의 처분제한의 등기를 할 때에는 직권으로 소유권보존등기를 하고, 처분제한의 등기를 명하는 법원의 재판에 따라 소유권의 등기를 한다는 뜻을 기록하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"보존등기는 최초의 등기라 등기원인이 없다. 등기원인과 연월일을 기록하지 않는다(법 제64조, 규칙 제121조제1항)."},{"번호":2,"판정":"옳음","설명":"대장상 최초 소유자의 상속인, 그 밖의 포괄승계인이 신청할 수 있다(법 제65조제1호)."},{"번호":3,"판정":"옳음","설명":"수용으로 소유권을 취득했음을 증명하는 자는 신청할 수 있다(법 제65조제3호)."},{"번호":4,"판정":"옳음","설명":"시장ㆍ군수ㆍ구청장의 확인으로 소유권을 증명하는 자는 신청할 수 있고, 건물에 한정된다(법 제65조제4호)."},{"번호":5,"판정":"옳음","설명":"법원의 촉탁으로 처분제한등기를 하면 등기관이 직권으로 보존등기를 한다(법 제66조제1항)."}],"개념":[{"종류":"표","제목":"소유권보존등기 신청인 (법 제65조)","머리":["유형","신청할 수 있는 자","대상"],"행":[["대장등록형","토지대장ㆍ임야대장ㆍ건축물대장에 최초 소유자로 등록된 자, 그 상속인ㆍ포괄승계인","토지ㆍ건물"],["판결형","확정판결로 자기 소유권을 증명하는 자","토지ㆍ건물"],["수용형","수용으로 소유권을 취득했음을 증명하는 자","토지ㆍ건물"],["확인형","특별자치도지사ㆍ시장ㆍ군수ㆍ구청장 확인으로 소유권을 증명하는 자","건물에 한정"]]},{"종류":"흐름","제목":"미등기부동산의 처분제한등기와 직권 보존","단계":[{"이름":"법원의 촉탁","설명":"미등기부동산에 소유권의 처분제한(가압류 등) 등기를 촉탁 (법 제66조제1항)."},{"이름":"직권 소유권보존","설명":"등기관이 직권으로 소유권보존등기를 하고, 재판에 따라 소유권의 등기를 한다는 뜻 기록."},{"이름":"건물의 특례","설명":"신청인 자격 제한(법 제65조)을 적용하지 않는다. 사용승인 대상인데 사용승인 전이면 그 사실을 표제부에 기록 (법 제66조제2항)."},{"이름":"사용승인 후 말소","설명":"사용승인이 나면 소유권 등기명의인이 1개월 이내 그 기록의 말소등기 신청 (법 제66조제3항)."}]}],"함정":"보존등기의 신청인 4유형 가운데 4호만 건물에 한정된다. 군수 확인으로 토지를 보존등기하는 길은 없다. 5번은 신청이 아니라 직권으로 하는 보존등기라는 점이 다르다."}},{"i":"S4-2-2-공시법-18","r":"S4","g":3,"c":2,"n":18,"s":"공시법","q":"소유권등기에서 공유와 합유에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기할 권리자가 2인 이상인 경우에는 권리자별 지분을 기록하고, 등기할 권리가 합유인 때에는 그 뜻을 기록한다.","수탁자가 여러 명인 경우 등기관은 신탁재산이 합유인 뜻을 기록하여야 한다.","소유권의 일부이전등기를 하면서 등기원인에 공유물 분할금지의 약정이 있는 경우, 그 약정의 변경등기는 공유자 중 1인이 단독으로 신청할 수 있다.","소유권의 일부에 대한 이전등기를 신청하는 경우에는 이전되는 지분을 신청정보의 내용으로 등기소에 제공하여야 한다.","신탁재산이 합유인 경우 여러 명의 수탁자 중 1인의 임무가 종료되었을 때 남은 수탁자가 여러 명이면 그 전원이 공동으로 권리변경등기를 신청하여야 한다."],"a":[3],"L":"시2-3","o":"변형","x":{"한줄":"공유물 분할금지 약정의 변경등기는 공유자 전원이 공동으로 신청한다.","근거":[{"법령":"부동산등기법","조문":"제67조","원문":"① 등기관이 소유권의 일부에 관한 이전등기를 할 때에는 이전되는 지분을 기록하여야 한다. 이 경우 등기원인에 「민법」 제268조제1항 단서의 약정이 있을 때에는 그 약정에 관한 사항도 기록하여야 한다. ② 제1항 후단의 약정의 변경등기는 공유자 전원이 공동으로 신청하여야 한다."},{"법령":"부동산등기법","조문":"제48조제4항","원문":"제1항제5호의 권리자가 2인 이상인 경우에는 권리자별 지분을 기록하여야 하고 등기할 권리가 합유(合有)인 때에는 그 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제84조","원문":"① 수탁자가 여러 명인 경우 등기관은 신탁재산이 합유인 뜻을 기록하여야 한다. ② 여러 명의 수탁자 중 1인이 제83조 각 호의 어느 하나의 사유로 그 임무가 종료된 경우 다른 수탁자는 단독으로 권리변경등기를 신청할 수 있다. 이 경우 다른 수탁자가 여러 명일 때에는 그 전원이 공동으로 신청하여야 한다."},{"법령":"부동산등기규칙","조문":"제123조","원문":"소유권의 일부에 대한 이전등기를 신청하는 경우에는 이전되는 지분을 신청정보의 내용으로 등기소에 제공하여야 한다. 이 경우 등기원인에 「민법」 제268조제1항 단서의 약정이 있을 때에는 그 약정에 관한 사항도 신청정보의 내용으로 등기소에 제공하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제48조제4항 그대로다. 권리자가 여럿이면 지분, 합유이면 합유라는 뜻을 기록한다."},{"번호":2,"판정":"옳음","설명":"수탁자가 여러 명이면 신탁재산이 합유인 뜻을 기록한다(법 제84조제1항)."},{"번호":3,"판정":"틀림","설명":"분할금지 약정의 변경등기는 공유자 전원이 공동으로 신청한다(법 제67조제2항). 1인이 단독으로 신청할 수 없다."},{"번호":4,"판정":"옳음","설명":"일부이전등기의 신청정보에는 이전되는 지분을 제공한다(규칙 제123조)."},{"번호":5,"판정":"옳음","설명":"남은 수탁자가 여럿이면 전원이 공동으로 권리변경등기를 신청한다(법 제84조제2항 후단)."}],"개념":[{"종류":"비교","제목":"공유와 합유의 등기","왼쪽":{"이름":"공유","항목":["권리자별 지분을 신청정보에 제공하고 기록 (규칙 제105조제1항, 법 제48조제4항)","소유권 일부(지분)이전등기는 이전되는 지분을 제공 (규칙 제123조)","공유물 분할금지 약정은 이전등기 때 함께 기록 (법 제67조제1항 후단)","분할금지 약정의 변경등기는 공유자 전원 공동신청 (법 제67조제2항)"]},"오른쪽":{"이름":"합유","항목":["합유라는 뜻을 신청정보에 제공하고 기록 (규칙 제105조제2항, 법 제48조제4항)","수탁자가 여러 명이면 신탁재산이 합유인 뜻 기록 (법 제84조제1항)","수탁자 1인의 임무 종료 시 나머지 수탁자가 변경등기 신청, 여러 명이면 전원 공동 (법 제84조제2항)","조합은 조합 명의가 아니라 조합원 전원 명의로 합유등기"]}},{"종류":"표","제목":"단체의 등기 명의","머리":["주체","등기 명의","신청"],"행":[["종중ㆍ문중 등 대표자나 관리인이 있는 법인 아닌 사단ㆍ재단","그 사단 또는 재단","대표자나 관리인이 사단ㆍ재단 명의로 신청 (법 제26조)"],["법인 아닌 사단ㆍ재단 명의 등기의 기록","대표자나 관리인의 성명ㆍ주소ㆍ주민등록번호를 함께 기록","법 제48조제3항"],["법인 아닌 사단ㆍ재단의 등록번호","시장ㆍ군수ㆍ구청장이 부여","법 제49조제1항제3호"],["민법상 조합","조합원 전원 명의 합유","법 제48조제4항, 규칙 제105조제2항"]]}],"함정":"권리자가 2인 이상이면 지분을 기록한다는 법 제48조제4항 앞부분과 합유의 뜻을 기록한다는 뒷부분을 한 문장에 쓴 1번은 법 문언 그대로라 옳다. 분할금지 약정은 설정 때는 이전등기와 함께 기록하지만 변경은 전원 공동신청이다."}},{"i":"S4-2-2-공시법-19","r":"S4","g":3,"c":2,"n":19,"s":"공시법","q":"소유권등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["민법상 조합이 소유하는 부동산은 조합 명의가 아니라 조합원 전원의 명의로 합유등기를 한다.","수용으로 인한 소유권이전등기는 등기권리자가 단독으로 신청할 수 있다.","수용으로 인한 소유권이전등기를 할 때 그 부동산의 등기기록에 소유권 외의 권리나 처분제한에 관한 등기가 있으면 등기관은 직권으로 말소하되, 그 부동산을 위하여 존재하는 지역권의 등기는 말소하지 않는다.","등기관이 미등기부동산에 대하여 법원의 촉탁에 따라 소유권의 처분제한의 등기를 할 때에는 직권으로 소유권보존등기를 한다.","공용부분이라는 뜻을 정한 규약을 폐지한 경우 공용부분의 취득자는 규약을 폐지한 날부터 1개월 이내에 소유권보존등기를 신청하여야 한다."],"a":[5],"L":"시2-3","o":"변형","x":{"한줄":"규약 폐지에 따른 소유권보존등기는 1개월이라는 기간 없이 지체 없이 신청한다.","근거":[{"법령":"부동산등기법","조문":"제47조제2항","원문":"공용부분이라는 뜻을 정한 규약을 폐지한 경우에 공용부분의 취득자는 지체 없이 소유권보존등기를 신청하여야 한다."},{"법령":"부동산등기법","조문":"제99조제1항ㆍ제4항","원문":"수용으로 인한 소유권이전등기는 제23조제1항에도 불구하고 등기권리자가 단독으로 신청할 수 있다. / 등기관이 제1항과 제3항에 따라 수용으로 인한 소유권이전등기를 하는 경우 그 부동산의 등기기록 중 소유권, 소유권 외의 권리, 그 밖의 처분제한에 관한 등기가 있으면 그 등기를 직권으로 말소하여야 한다. 다만, 그 부동산을 위하여 존재하는 지역권의 등기 또는 토지수용위원회의 재결(裁決)로써 존속(存續)이 인정된 권리의 등기는 그러하지 아니하다."},{"법령":"부동산등기법","조문":"제66조제1항","원문":"등기관이 미등기부동산에 대하여 법원의 촉탁에 따라 소유권의 처분제한의 등기를 할 때에는 직권으로 소유권보존등기를 하고, 처분제한의 등기를 명하는 법원의 재판에 따라 소유권의 등기를 한다는 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제48조제4항","원문":"제1항제5호의 권리자가 2인 이상인 경우에는 권리자별 지분을 기록하여야 하고 등기할 권리가 합유(合有)인 때에는 그 뜻을 기록하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"조합은 법 제26조의 법인 아닌 사단ㆍ재단이 아니므로 조합원 전원의 합유로 등기한다(법 제48조제4항, 규칙 제105조제2항)."},{"번호":2,"판정":"옳음","설명":"수용으로 인한 소유권이전등기는 등기권리자 단독신청이다(법 제99조제1항)."},{"번호":3,"판정":"옳음","설명":"직권말소 대상은 소유권, 소유권 외의 권리, 처분제한 등기이고, 요역지를 위한 지역권 등기와 재결로 존속이 인정된 권리 등기는 제외된다(법 제99조제4항)."},{"번호":4,"판정":"옳음","설명":"미등기부동산에 법원이 처분제한을 촉탁하면 등기관이 직권으로 보존등기를 한다(법 제66조제1항)."},{"번호":5,"판정":"틀림","설명":"취득자는 지체 없이 신청한다(법 제47조제2항). 1개월 기간을 두는 것은 토지ㆍ건물의 표시변경ㆍ멸실등기(법 제35조, 제39조, 제41조, 제43조)다."}],"개념":[{"종류":"표","제목":"신청 기한: 1개월과 지체 없이","머리":["등기","기한","신청인","근거"],"행":[["토지 분할ㆍ합병, 표시 변경","그 사실이 있는 때부터 1개월 이내","토지 소유권 등기명의인","법 제35조"],["토지 멸실","그 사실이 있는 때부터 1개월 이내","토지 소유권 등기명의인","법 제39조"],["건물 분할ㆍ구분ㆍ합병, 표시 변경","그 사실이 있는 때부터 1개월 이내","건물 소유권 등기명의인","법 제41조제1항"],["건물 멸실","그 사실이 있는 때부터 1개월 이내 (이내에 신청 안 하면 대지 소유자가 대위 가능)","건물 소유권 등기명의인","법 제43조"],["존재하지 않는 건물의 등기","지체 없이","소유권 등기명의인","법 제44조제1항"],["규약 폐지에 따른 소유권보존","지체 없이","공용부분의 취득자","법 제47조제2항"],["사용승인 후 기록 말소","1개월 이내","건물 소유권 등기명의인","법 제66조제3항"]]},{"종류":"표","제목":"수용으로 인한 등기 (법 제99조)","머리":["항목","내용"],"행":[["신청","등기권리자 단독 (제1항)"],["대위 신청","등기명의인 등을 갈음해 표시ㆍ명의인표시의 변경ㆍ경정, 상속 등 포괄승계로 인한 이전등기 신청 가능 (제2항)"],["국가ㆍ지방자치단체가 권리자","지체 없이 촉탁 (제3항)"],["직권 말소","소유권, 소유권 외 권리, 처분제한 등기. 다만 해당 부동산을 위한 지역권 등기와 재결로 존속이 인정된 권리 등기는 제외 (제4항)"],["소유권 외 권리의 수용","제1항~제4항 준용 (제5항)"]]}],"함정":"표시변경ㆍ멸실등기의 「1개월」 기간이 인상에 남아 5번을 옳다고 보기 쉽다. 규약 폐지의 보존등기는 법 문언이 「지체 없이」다. 3번은 지역권 등기가 직권말소에서 빠지는 예외를 묻는 문장이다."}},{"i":"S4-2-2-공시법-20","r":"S4","g":3,"c":2,"n":20,"s":"공시법","q":"용익권에 관한 등기에 대한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기관이 승역지에 지역권설정의 등기를 하였을 때에는 직권으로 요역지의 등기기록에 승역지 등을 기록하여야 한다.","임차권설정등기를 할 때 임차보증금은 등기원인에 그 약정이 없더라도 반드시 기록하여야 한다.","지상권설정의 범위가 토지의 일부인 경우에는 그 부분을 표시한 지적도를 첨부정보로서 등기소에 제공하여야 한다.","전세권설정의 범위가 건물의 일부인 경우에는 그 부분을 표시한 건물도면을 첨부정보로서 등기소에 제공하여야 한다.","근저당권설정등기의 존속기간은 등기원인에 그 약정이 있는 경우에만 기록한다."],"a":[2],"L":"시2-4","o":"변형","x":{"한줄":"임차보증금은 등기원인에 약정이 있는 경우에만 기록하는 사항이다.","근거":[{"법령":"부동산등기법","조문":"제74조","원문":"등기관이 임차권 설정 또는 임차물 전대(轉貸)의 등기를 할 때에는 제48조에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호부터 제6호까지는 등기원인에 그 사항이 있는 경우에만 기록한다. 1. 차임(借賃) 2. 범위 3. 차임지급시기 4. 존속기간. 다만, 처분능력 또는 처분권한 없는 임대인에 의한 「민법」 제619조의 단기임대차인 경우에는 그 뜻도 기록한다. 5. 임차보증금 6. 임차권의 양도 또는 임차물의 전대에 대한 임대인의 동의 7. 임차권설정 또는 임차물전대의 범위가 부동산의 일부인 때에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제71조제1항","원문":"등기관이 승역지에 지역권설정의 등기를 하였을 때에는 직권으로 요역지의 등기기록에 다음 각 호의 사항을 기록하여야 한다. 1. 순위번호 2. 등기목적 3. 승역지 4. 지역권설정의 목적 5. 범위 6. 등기연월일"},{"법령":"부동산등기규칙","조문":"제126조제2항","원문":"지상권설정의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 지적도를 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제128조제2항","원문":"전세권설정 또는 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 지적도나 건물도면을 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기법","조문":"제75조제2항","원문":"등기관은 제1항의 저당권의 내용이 근저당권(根抵當權)인 경우에는 제48조에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호 및 제4호는 등기원인에 그 약정이 있는 경우에만 기록한다. 1. 채권의 최고액 2. 채무자의 성명 또는 명칭과 주소 또는 사무소 소재지 3. 「민법」 제358조 단서의 약정 4. 존속기간"}],"선지":[{"번호":1,"판정":"옳음","설명":"승역지에 설정등기를 하면 등기관이 직권으로 요역지 등기기록에 승역지 등을 기록한다(법 제71조제1항)."},{"번호":2,"판정":"틀림","설명":"임차권 등기사항 중 제3호~제6호(차임지급시기, 존속기간, 임차보증금, 양도ㆍ전대 동의)는 약정이 있을 때만 기록한다(법 제74조 단서). 임차보증금은 제5호다."},{"번호":3,"판정":"옳음","설명":"지상권의 범위가 일부이면 그 부분을 표시한 지적도를 제공한다(규칙 제126조제2항)."},{"번호":4,"판정":"옳음","설명":"전세권의 범위가 부동산 일부이면 지적도나 건물도면을 제공한다(규칙 제128조제2항). 건물 일부이면 건물도면이다."},{"번호":5,"판정":"옳음","설명":"근저당권의 존속기간은 제75조제2항제4호로, 약정이 있는 경우에만 기록한다."}],"개념":[{"종류":"표","제목":"용익권 등기사항: 반드시 기록하는 것과 약정이 있을 때만 기록하는 것","머리":["권리","필수 기록사항","약정이 있을 때만 기록","근거"],"행":[["지상권","설정목적, 범위","존속기간, 지료와 지급시기, 민법 제289조의2제1항 후단의 약정","법 제69조"],["지역권(승역지)","설정목적, 범위, 요역지","민법 제292조제1항 단서ㆍ제297조제1항 단서ㆍ제298조의 약정","법 제70조"],["전세권","전세금, 범위","존속기간, 위약금 또는 배상금, 민법 제306조 단서의 약정","법 제72조"],["임차권","차임, 범위","차임지급시기, 존속기간, 임차보증금, 양도ㆍ전대 동의","법 제74조"],["공통","범위가 부동산 일부이면 그 부분을 표시한 도면의 번호","-","법 제69조~제74조"]]},{"종류":"표","제목":"범위가 일부인 경우 첨부 도면과 전세권 일부이전","머리":["권리","첨부정보","근거"],"행":[["지상권","그 부분을 표시한 지적도","규칙 제126조제2항"],["지역권(승역지의 일부)","지상권 규정 준용: 지적도","규칙 제127조제2항"],["전세권ㆍ전전세","지적도 또는 건물도면","규칙 제128조제2항"],["임차권ㆍ임차물 전대","전세권 규정 준용: 지적도 또는 건물도면","규칙 제130조제2항"],["전세금반환채권 일부양도에 따른 전세권 일부이전","존속기간 만료 전에는 전세권 소멸 증명정보를 첨부해야 신청 가능","법 제73조제2항, 규칙 제129조제2항"]]}],"함정":"임차권에서 차임과 범위는 약정 여부와 관계없이 기록하고, 3호부터 6호는 약정이 있을 때만 기록한다. 임차보증금이 3호~6호 중 하나라는 점을 놓치기 쉽다. 5번도 근저당권은 존속기간이 약정 기록사항이다."}},{"i":"S4-2-2-공시법-21","r":"S4","g":3,"c":2,"n":21,"s":"공시법","q":"甲은 乙과 乙소유 A건물 전부에 대해 전세금 5억원, 기간 2년으로 하는 전세권설정계약을 체결하고 공동으로 전세권설정등기를 신청하였다. 이에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기관은 전세금을 기록하여야 한다.","등기관은 존속기간을 기록하여야 한다.","전세권설정등기가 된 후, 전세금반환채권의 일부 양도를 원인으로 한 전세권 일부이전등기를 할 때에 등기관은 양도액을 기록한다.","전세권설정등기가 된 후에 건물전세권의 존속기간이 만료되어 법정갱신이 된 경우, 甲은 존속기간 연장을 위한 변경등기를 하지 않아도 그 전세권에 대한 저당권설정등기를 할 수 있다.","전세권설정등기가 된 후에 甲과 丙이 A건물의 일부에 대한 전전세계약에 따라 전전세등기를 신청하는 경우, 그 부분을 표시한 건물도면을 첨부정보로 등기소에 제공하여야 한다."],"a":[4],"L":"시2-4","o":"기출","x":{"한줄":"법정갱신으로 전세권을 다시 설정한 것으로 보더라도 등기 없이는 처분할 수 없어, 존속기간 변경등기를 먼저 해야 그 전세권에 저당권을 설정할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제72조제1항","원문":"등기관이 전세권설정이나 전전세(轉傳貰)의 등기를 할 때에는 제48조에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호부터 제5호까지는 등기원인에 그 약정이 있는 경우에만 기록한다.\n1. 전세금 또는 전전세금\n2. 범위\n3. 존속기간\n4. 위약금 또는 배상금\n5. 「민법」 제306조 단서의 약정\n6. 전세권설정이나 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제73조제1항","원문":"등기관이 전세금반환채권의 일부 양도를 원인으로 한 전세권 일부이전등기를 할 때에는 양도액을 기록한다."},{"법령":"부동산등기규칙","조문":"제128조제2항","원문":"전세권설정 또는 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 지적도나 건물도면을 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"민법","조문":"제312조제4항","원문":"건물의 전세권설정자가 전세권의 존속기간 만료전 6월부터 1월까지 사이에 전세권자에 대하여 갱신거절의 통지 또는 조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 전세권의 존속기간은 그 정함이 없는 것으로 본다."},{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전세금은 전세권설정등기의 필요적 기록사항이다(법 제72조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"존속기간은 약정이 있을 때만 적는다(제3호). 사안은 기간 2년으로 계약했으므로 기록한다."},{"번호":3,"판정":"옳음","설명":"일부이전등기에는 양도액을 기록한다(법 제73조제1항). 신청은 존속기간 만료 전에는 못 하고, 전세권 소멸을 증명하면 만료 전에도 가능하다(같은 조 제2항)."},{"번호":4,"판정":"틀림","설명":"법정갱신은 법률 규정에 의한 물권 변동이라 등기 없이도 효력이 생기지만, 등기하지 않으면 처분하지 못한다(민법 제187조, 제312조제4항). 갱신된 전세권은 존속기간 정함이 없는 것으로 보므로, 그 기간을 반영한 변경등기를 한 뒤에 저당권을 설정한다."},{"번호":5,"판정":"옳음","설명":"전전세의 범위가 건물의 일부이면 그 부분을 표시한 건물도면을 첨부정보로 제공한다(규칙 제128조제2항)."}],"개념":[{"종류":"표","제목":"전세권설정·전전세 등기 기록사항","머리":["구분","기록 여부","내용"],"행":[["전세금·전전세금","반드시","금액"],["범위","반드시","목적물 전부 또는 일부"],["존속기간","약정이 있을 때만","기간(민법상 최장 10년)"],["위약금·배상금","약정이 있을 때만","금액"],["민법 제306조 단서 약정","약정이 있을 때만","양도·담보제공 금지 등"],["일부에 설정","도면번호 기록","지적도 또는 건물도면 첨부(규칙 제128조제2항)"]]},{"종류":"흐름","제목":"전세금반환채권 일부양도에 따른 전세권 일부이전등기","단계":[{"이름":"채권의 일부 양도","설명":"전세금반환채권 중 일부를 양도"},{"이름":"소멸 시점 확인","설명":"존속기간 만료 전에는 신청 불가, 전세권 소멸을 증명하면 만료 전에도 신청 가능(법 제73조제2항)"},{"이름":"신청","설명":"신청정보에 양도액을 제공하고, 만료 전이면 소멸 증명 정보 첨부(규칙 제129조)"},{"이름":"등기","설명":"등기관이 전세권 일부이전등기를 하면서 양도액 기록(법 제73조제1항)"}]}],"함정":"선지 2에서 존속기간은 약정이 있을 때만 적는다는 점을 떠올려 틀렸다고 고르기 쉽다. 사안에 기간 2년이 명시돼 있어 기록 대상이다. 선지 4는 법정갱신이 등기 없이 효력이 생긴다는 점에 끌려 변경등기가 필요 없다고 오해하기 쉽다. 효력과 처분 가능성은 별개다."}},{"i":"S4-2-2-공시법-22","r":"S4","g":3,"c":2,"n":22,"s":"공시법","q":"부동산등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["건물소유권의 공유지분 일부에 대하여는 전세권설정등기를 할 수 없다.","구분건물에 대하여는 전유부분마다 부동산고유번호를 부여한다.","폐쇄한 등기기록에 대해서는 등기사항의 열람은 가능하지만 등기사항증명서의 발급은 청구할 수 없다.","전세금을 증액하는 전세권변경등기는 등기상 이해관계 있는 제3자의 승낙 또는 이에 대항할 수 있는 재판의 등본이 없으면 부기등기가 아닌 주등기로 해야 한다.","등기관이 부기등기를 할 때에는 주등기 또는 부기등기의 순위번호에 가지번호를 붙여서 하여야 한다."],"a":[3],"L":"시2-5","o":"기출","x":{"한줄":"폐쇄한 등기기록도 등기사항증명서를 발급받을 수 있고, 다만 종류가 등기사항전부증명서(말소사항 포함)로 한정된다.","근거":[{"법령":"부동산등기법","조문":"제19조제1항","원문":"누구든지 수수료를 내고 대법원규칙으로 정하는 바에 따라 등기기록에 기록되어 있는 사항의 전부 또는 일부의 열람(閱覽)과 이를 증명하는 등기사항증명서의 발급을 청구할 수 있다. 다만, 등기기록의 부속서류에 대하여는 이해관계 있는 부분만 열람을 청구할 수 있다."},{"법령":"부동산등기규칙","조문":"제29조","원문":"등기사항증명서의 종류는 다음 각 호로 한다. 다만, 폐쇄한 등기기록 및 대법원예규로 정하는 등기기록에 대하여는 제1호로 한정한다.\n1. 등기사항전부증명서(말소사항 포함)"},{"법령":"부동산등기규칙","조문":"제12조제2항","원문":"구분건물에 대하여는 전유부분마다 부동산고유번호를 부여한다."},{"법령":"부동산등기법","조문":"제52조","원문":"등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다.\n5. 권리의 변경이나 경정의 등기"},{"법령":"부동산등기규칙","조문":"제2조","원문":"등기관이 부기등기를 할 때에는 그 부기등기가 어느 등기에 기초한 것인지 알 수 있도록 주등기 또는 부기등기의 순위번호에 가지번호를 붙여서 하여야 한다."},{"법령":"민법","조문":"제303조제1항","원문":"전세권자는 전세금을 지급하고 타인의 부동산을 점유하여 그 부동산의 용도에 좇아 사용ㆍ수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전세권은 부동산 전부를 점유해 사용·수익하는 물권이라 건물소유권의 공유지분만을 목적으로 설정할 수 없다(민법 제303조제1항, 등기선례 취지). 등기관은 이런 신청을 각하한다(법 제29조제2호, 규칙 제52조제1호)."},{"번호":2,"판정":"옳음","설명":"1필의 토지나 1개의 건물마다 부동산고유번호를 부여하고, 구분건물은 전유부분마다 부여한다(규칙 제12조제1항·제2항)."},{"번호":3,"판정":"틀림","설명":"폐쇄한 등기기록에 대해서도 열람과 증명서 발급을 청구할 수 있고, 발급되는 증명서는 등기사항전부증명서(말소사항 포함)로 한정된다(법 제19조제1항, 규칙 제29조 단서)."},{"번호":4,"판정":"옳음","설명":"전세금 증액은 권리의 변경등기이고, 이해관계 있는 제3자의 승낙이 없으면 부기가 아닌 주등기로 한다(법 제52조제5호 단서, 규칙 제112조제1항 단서)."},{"번호":5,"판정":"옳음","설명":"부기등기는 주등기 또는 부기등기의 순위번호에 가지번호를 붙여 한다(규칙 제2조). 같은 주등기에 딸린 부기등기끼리는 등기한 순서에 따른다(법 제5조)."}],"개념":[{"종류":"표","제목":"등기기록 열람·증명서 발급","머리":["대상","열람","증명서 발급","비고"],"행":[["현행 등기기록","가능","가능","누구든지 청구(법 제19조제1항)"],["폐쇄한 등기기록","가능","가능","종류는 등기사항전부증명서(말소사항 포함)로 한정(규칙 제29조)"],["관할 아닌 등기소","가능","가능","법 제19조제2항"],["등기기록의 부속서류","이해관계 있는 부분만","-","법 제19조제1항 단서"],["접수되어 처리 중인 부동산","-","원칙적 불가","처리 중이라는 뜻을 표시해 발급 가능(규칙 제30조제4항)"]]},{"종류":"표","제목":"주등기와 부기등기 구분","머리":["구분","등기","방식"],"행":[["등기명의인표시 변경·경정","부기","법 제52조제1호"],["소유권 외 권리의 이전","부기","법 제52조제2호"],["소유권 외 권리를 목적으로 하는 권리","부기","법 제52조제3호"],["권리 변경·경정(제3자 승낙 있음)","부기","법 제52조제5호"],["권리 변경·경정(제3자 승낙 없음)","주등기","법 제52조 단서"],["환매특약·권리소멸약정","부기","법 제52조제6호·제7호"]]}],"함정":"폐쇄한 등기기록은 효력이 없어졌으니 증명서도 못 받는다고 생각하기 쉽다. 발급은 되고 종류만 전부증명서로 제한된다. 선지 4는 전세금 증액이 부기등기라는 일반 원칙만 기억하면 틀려 보이지만, 제3자 승낙이 없으면 주등기다."}},{"i":"S4-2-2-공시법-23","r":"S4","g":3,"c":2,"n":23,"s":"공시법","q":"가등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["가등기명의인은 그 가등기의 말소를 단독으로 신청할 수 없다.","가등기의무자는 가등기명의인의 승낙을 받더라도 가등기의 말소를 단독으로 신청할 수 없다.","가등기권리자는 가등기를 명하는 법원의 가처분명령이 있더라도 단독으로 가등기를 신청할 수 없다.","하나의 가등기에 관하여 여러 사람의 가등기권자가 있는 경우, 그 중 일부의 가등기권자는 공유물보존행위에 준하여 가등기 전부에 관한 본등기를 신청할 수 없다.","가등기목적물의 소유권이 가등기 후에 제3자에게 이전된 경우, 가등기에 의한 본등기신청의 등기의무자는 그 제3자이다."],"a":[4],"L":"시2-5","o":"기출","x":{"한줄":"가등기권자가 여럿이면 각자 자기 지분에 관한 본등기만 신청할 수 있고, 공유물 보존행위에 준해 전부의 본등기를 신청할 수는 없다.","근거":[{"법령":"부동산등기법","조문":"제89조","원문":"가등기권리자는 제23조제1항에도 불구하고 가등기의무자의 승낙이 있거나 가등기를 명하는 법원의 가처분명령(假處分命令)이 있을 때에는 단독으로 가등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제93조","원문":"① 가등기명의인은 제23조제1항에도 불구하고 단독으로 가등기의 말소를 신청할 수 있다.\n② 가등기의무자 또는 가등기에 관하여 등기상 이해관계 있는 자는 제23조제1항에도 불구하고 가등기명의인의 승낙을 받아 단독으로 가등기의 말소를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제92조제1항","원문":"등기관은 가등기에 의한 본등기를 하였을 때에는 대법원규칙으로 정하는 바에 따라 가등기 이후에 된 등기로서 가등기에 의하여 보전되는 권리를 침해하는 등기를 직권으로 말소하여야 한다."},{"이론":"공동 가등기권자의 본등기","내용":"가등기 권리자가 여럿이면 각자 자기 지분에 관해서만 본등기를 신청한다. 공유물 보존행위에 준해 1인이 전부의 본등기를 신청하는 것은 허용되지 않는다(등기선례·예규 취지)."}],"선지":[{"번호":1,"판정":"틀림","설명":"가등기명의인은 단독으로 말소를 신청할 수 있다(법 제93조제1항)."},{"번호":2,"판정":"틀림","설명":"가등기의무자는 가등기명의인의 승낙을 받아 단독으로 말소를 신청할 수 있다(법 제93조제2항, 규칙 제150조)."},{"번호":3,"판정":"틀림","설명":"가등기의무자의 승낙이 있거나 가등기를 명하는 법원의 가처분명령이 있으면 가등기권리자가 단독으로 신청할 수 있다(법 제89조, 제90조)."},{"번호":4,"판정":"옳음","설명":"가등기권자가 여럿이면 각자 자기 지분의 본등기만 신청한다. 일부 권리자가 보존행위를 이유로 전부를 신청할 수 없다."},{"번호":5,"판정":"틀림","설명":"가등기 후 소유권이 제3자에게 넘어갔더라도 본등기의 등기의무자는 제3자가 아니라 가등기 당시의 소유자(가등기의무자)다. 본등기를 하면 제3자 명의의 소유권이전등기는 가등기로 보전되는 권리를 침해하는 등기로서 등기관이 직권으로 말소한다(법 제92조제1항)."}],"개념":[{"종류":"표","제목":"가등기 신청·말소 주체","머리":["구분","단독 신청","요건","조문"],"행":[["가등기 신청","가등기권리자","가등기의무자의 승낙 또는 법원의 가처분명령","법 제89조"],["가등기 말소","가등기명의인","없음","법 제93조제1항"],["가등기 말소","가등기의무자·이해관계인","가등기명의인의 승낙 또는 대항 재판","법 제93조제2항, 규칙 제150조"],["가처분명령 관할","부동산 소재지 지방법원","원인사실 소명","법 제90조제1항"]]},{"종류":"흐름","제목":"가등기에 의한 본등기","단계":[{"이름":"가등기","설명":"소유권이전청구권 등 청구권 보전을 위해 가등기(법 제88조)"},{"이름":"본등기 신청","설명":"가등기권리자와 의무자가 공동으로 신청, 가등기 지분별로 신청"},{"이름":"본등기 실행","설명":"가등기의 순위번호를 사용해 본등기(규칙 제146조), 순위는 가등기 순위에 따름(법 제91조)"},{"이름":"직권말소","설명":"가등기 후에 된 등기 중 가등기 권리를 침해하는 등기 직권말소, 명의인에게 통지(법 제92조)"}]}],"함정":"선지 1·2·3은 단독신청 규정(법 제89조, 제93조)의 요건을 뒤집은 문장이다. 선지 5는 제3자 명의 등기를 보호해야 한다고 오해하기 쉽지만 가등기 이후의 침해 등기는 직권말소 대상이다."}},{"i":"S4-2-2-공시법-24","r":"S4","g":3,"c":2,"n":24,"s":"공시법","q":"다음 중 부기등기로 하는 경우만을 모두 고른 것은?","b":"ㄱ. 저당권의 이전등기\nㄴ. 소유권이전청구권을 보전하기 위한 가등기\nㄷ. 지상권을 목적으로 하는 저당권설정등기\nㄹ. 이해관계 있는 제3자의 승낙 없이 하는 전세금 증액의 변경등기\nㅁ. 전세권에 대한 가압류등기","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄴ, ㄹ","ㄱ, ㄷ, ㅁ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㅁ"],"a":[3],"L":"시2-5","o":"변형","x":{"한줄":"소유권 외 권리의 이전(ㄱ), 소유권 외 권리를 목적으로 하는 권리(ㄷ), 소유권 외 권리에 대한 처분제한(ㅁ)은 부기로 하므로 ㄱ, ㄷ, ㅁ 이다.","근거":[{"법령":"부동산등기법","조문":"제52조","원문":"등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다.\n1. 등기명의인표시의 변경이나 경정의 등기\n2. 소유권 외의 권리의 이전등기\n3. 소유권 외의 권리를 목적으로 하는 권리에 관한 등기\n4. 소유권 외의 권리에 대한 처분제한 등기\n5. 권리의 변경이나 경정의 등기\n6. 제53조의 환매특약등기\n7. 제54조의 권리소멸약정등기\n8. 제67조제1항 후단의 공유물 분할금지의 약정등기\n9. 그 밖에 대법원규칙으로 정하는 등기"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 부기, ㄴ은 주등기이므로 ㄴ이 섞인 조합은 틀리다."},{"번호":2,"판정":"-","설명":"ㄴ, ㄹ 모두 주등기다."},{"번호":3,"판정":"-","설명":"ㄱ(제2호), ㄷ(제3호), ㅁ(제4호) 모두 부기다."},{"번호":4,"판정":"-","설명":"ㄹ이 주등기라서 섞이면 틀리다."},{"번호":5,"판정":"-","설명":"ㄴ이 주등기라서 섞이면 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"저당권은 소유권 외의 권리이고 그 이전등기는 부기로 한다(법 제52조제2호)."},{"기호":"ㄴ","판정":"틀림","설명":"소유권이전청구권 가등기는 소유권을 대상으로 하므로 부기 사유(제52조 각 호)에 없어 주등기로 한다. 소유권 외의 권리에 대한 가등기라면 제3호로 부기다."},{"기호":"ㄷ","판정":"옳음","설명":"지상권은 소유권 외의 권리이고 저당권은 그 권리를 목적으로 하는 권리라서 부기다(법 제52조제3호)."},{"기호":"ㄹ","판정":"틀림","설명":"권리의 변경등기는 제3자의 승낙이 없으면 부기가 아닌 주등기로 한다(법 제52조제5호 단서, 규칙 제112조제1항 단서)."},{"기호":"ㅁ","판정":"옳음","설명":"전세권은 소유권 외의 권리이고 그에 대한 가압류는 처분제한등기라서 부기다(법 제52조제4호)."}],"개념":[{"종류":"표","제목":"부기등기와 주등기 분류","머리":["등기","방식","근거"],"행":[["소유권이전등기","주등기","제52조 각 호에 없음"],["소유권에 대한 가압류·가처분·경매개시결정","주등기","소유권 처분제한은 제4호의 대상 아님"],["소유권이전청구권 가등기","주등기","제52조 각 호에 없음"],["소유권 외 권리의 이전","부기","제52조제2호"],["소유권 외 권리 위의 저당권 등","부기","제52조제3호"],["소유권 외 권리의 가압류 등 처분제한","부기","제52조제4호"],["환매특약·권리소멸약정·공유물 분할금지 약정","부기","제52조제6호~제8호"]]}],"함정":"가등기는 부기가 많다고 알고 ㄴ을 부기로 고르기 쉽다. 소유권이전청구권 가등기는 주등기다. ㄹ은 전세금 증액이 권리 변경이라 부기라고 보는 오류를 노린다. 제3자 승낙이 없으면 주등기다."}},{"i":"S4-2-2-세법-01","r":"S4","g":3,"c":2,"n":25,"s":"세법","q":"지방세기본법 및 지방세법상 용어의 정의에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["\"납세의무자\"란 「지방세법」에 따라 지방세를 납부할 의무(지방세를 특별징수하여 납부할 의무는 제외한다)가 있는 자를 말한다.","\"납세자\"란 납세의무자(연대납세의무자와 제2차 납세의무자를 포함하며 보증인은 제외한다)와 특별징수의무자를 말한다.","\"체납액\"이란 체납된 지방세와 가산세를 말한다.","\"표준세율\"이란 지방자치단체가 지방세를 부과할 경우에 특별한 사유가 있더라도 반드시 적용하여야 하는 세율을 말한다.","취득세에서 \"토지\"란 「공간정보의 구축 및 관리 등에 관한 법률」에 따라 지적공부에 등록된 토지만을 말한다."],"a":[1],"L":"세1-1","o":"변형","x":{"한줄":"납세의무자 정의에서는 특별징수하여 납부할 의무가 빠지고, 그 의무를 지는 자는 특별징수의무자로 따로 부른다.","근거":[{"법령":"지방세기본법","조문":"제2조제1항제6호·제11호·제12호·제33호","원문":"① 이 법에서 사용하는 용어의 뜻은 다음과 같다.\n  6. \"표준세율\"이란 지방자치단체가 지방세를 부과할 경우에 통상 적용하여야 할 세율로서 재정상의 사유 또는 그 밖의 특별한 사유가 있는 경우에는 이에 따르지 아니할 수 있는 세율을 말한다.\n  11. \"납세의무자\"란 「지방세법」에 따라 지방세를 납부할 의무(지방세를 특별징수하여 납부할 의무는 제외한다)가 있는 자를 말한다.\n  12. \"납세자\"란 납세의무자(연대납세의무자와 제2차 납세의무자 및 보증인을 포함한다)와 특별징수의무자를 말한다.\n  33. \"체납액\"이란 체납된 지방세와 체납처분비를 말한다."},{"법령":"지방세법","조문":"제6조제3호","원문":"취득세에서 사용하는 용어의 뜻은 다음 각 호와 같다.\n  3. \"토지\"란 「공간정보의 구축 및 관리 등에 관한 법률」에 따라 지적공부(地籍公簿)의 등록대상이 되는 토지와 그 밖에 사용되고 있는 사실상의 토지를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"납세의무자는 지방세를 납부할 의무가 있는 자이고, 특별징수하여 납부할 의무는 이 정의에서 뺀다. 그 의무를 지는 자는 특별징수의무자다(지방세기본법 제2조제1항제11호·제21호)."},{"번호":2,"판정":"틀림","설명":"납세자에는 보증인이 들어간다. 납세의무자(연대납세의무자·제2차 납세의무자·보증인 포함)와 특별징수의무자를 합쳐 납세자라 한다(같은 항 제12호)."},{"번호":3,"판정":"틀림","설명":"체납액은 체납된 지방세와 체납처분비다(같은 항 제33호). 가산세는 이 정의에 들어 있지 않다."},{"번호":4,"판정":"틀림","설명":"표준세율은 통상 적용할 세율이다. 재정상 사유나 그 밖의 특별한 사유가 있으면 따르지 않을 수 있다(같은 항 제6호)."},{"번호":5,"판정":"틀림","설명":"취득세의 토지에는 지적공부 등록 토지 외에 사실상 사용되고 있는 토지도 들어간다(지방세법 제6조제3호)."}],"개념":[{"종류":"표","제목":"지방세기본법 제2조 주요 용어","머리":["용어","뜻"],"행":[["납세의무자","지방세법에 따라 지방세를 납부할 의무가 있는 자(특별징수 납부의무 제외)"],["납세자","납세의무자(연대납세의무자·제2차 납세의무자·보증인 포함) + 특별징수의무자"],["제2차 납세의무자","납세자가 납세의무를 이행할 수 없을 때 납세자를 갈음하여 납세의무를 지는 자"],["보증인","납세자의 지방세 또는 체납처분비의 납부를 보증한 자"],["지방자치단체의 징수금","지방세 및 체납처분비"],["체납액","체납된 지방세와 체납처분비"],["표준세율","통상 적용할 세율. 재정상 사유 등 특별한 사유가 있으면 따르지 않을 수 있음"],["세무공무원","지방자치단체의 장 또는 지방세의 부과·징수 등에 관한 사무를 위임받은 공무원"]]},{"종류":"비교","제목":"보통징수와 특별징수","왼쪽":{"이름":"보통징수","항목":["세무공무원이 납세고지서를 납세자에게 발급하여 징수(제2조제1항제19호)","재산세는 지방자치단체의 장이 세액을 산정하여 보통징수로 부과·징수(지방세법 제116조제1항)"]},"오른쪽":{"이름":"특별징수","항목":["징수할 여건이 좋은 자로 하여금 징수하게 하고 그 징수한 세금을 납부하게 함(제2조제1항제20호)","그 의무를 지는 자는 특별징수의무자이며 납세자에 포함(제2조제1항제12호·제21호)"]}}],"함정":"납세의무자 정의에서는 특별징수 납부의무를 빼는데, 납세자 정의에서는 보증인과 특별징수의무자를 넣는다. 체납액에는 체납처분비가 들어가고 가산세는 들어가지 않는다. 표준세율은 '반드시' 적용하는 세율이 아니다.","개정":"지방세기본법 제2조제1항제24호(가산금 정의)는 삭제 <2020.12.29>이고, 현행 제22호의 지방자치단체의 징수금은 지방세 및 체납처분비다."}},{"i":"S4-2-2-세법-02","r":"S4","g":3,"c":2,"n":26,"s":"세법","q":"국세기본법령 및 지방세기본법령상 국세 또는 지방세 징수권의 소멸시효에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["가산세를 제외한 국세가 10억원인 경우 국세징수권은 5년 동안 행사하지 아니하면 소멸시효가 완성된다.","가산세를 제외한 지방세가 1억원인 경우 지방세징수권은 7년 동안 행사하지 아니하면 소멸시효가 완성된다.","가산세를 제외한 지방세가 5천만원인 경우 지방세징수권은 5년 동안 행사하지 아니하면 소멸시효가 완성된다.","납세의무자가 양도소득세를 확정신고하였으나 정부가 경정하는 경우, 국세징수권을 행사할 수 있는 때는 납세의무자가 확정신고한 법정 신고납부기한의 다음 날이다.","납세의무자가 취득세를 신고하였으나 지방자치단체의장이 경정하는 경우, 납세고지한 세액에 대한 지방세징수권을 행사할 수 있는 때는 그 납세고지서에 따른 납부기한의 다음 날이다."],"a":[5],"L":"세1-1","o":"기출","x":{"한줄":"경정해서 납세고지한 세액은 그 납세고지서에 따른 납부기한의 다음 날부터 징수권을 행사할 수 있으므로 시효도 그날부터 진행한다.","근거":[{"법령":"국세기본법","조문":"제27조제1항","원문":"① 국세의 징수를 목적으로 하는 국가의 권리(이하 이 조에서 \"국세징수권\"이라 한다)는 이를 행사할 수 있는 때부터 다음 각 호의 구분에 따른 기간 동안 행사하지 아니하면 소멸시효가 완성된다. 이 경우 다음 각 호의 국세의 금액은 가산세를 제외한 금액으로 한다.\n  1. 5억원 이상의 국세: 10년\n  2. 제1호 외의 국세: 5년"},{"법령":"국세기본법","조문":"제27조제3항","원문":"③ 제1항에 따른 국세징수권을 행사할 수 있는 때는 다음 각 호의 날을 말한다.\n  1. 과세표준과 세액의 신고에 의하여 납세의무가 확정되는 국세의 경우 신고한 세액에 대해서는 그 법정 신고납부기한의 다음 날\n  2. 과세표준과 세액을 정부가 결정, 경정 또는 수시부과결정하는 경우 납부고지한 세액에 대해서는 그 고지에 따른 납부기한의 다음 날"},{"법령":"지방세기본법","조문":"제39조제1항","원문":"① 지방자치단체의 징수금의 징수를 목적으로 하는 지방자치단체의 권리(이하 \"지방세징수권\"이라 한다)는 이를 행사할 수 있는 때부터 다음 각 호의 구분에 따른 기간 동안 행사하지 아니하면 소멸시효가 완성된다.\n  1. 가산세를 제외한 지방세의 금액이 5천만원 이상인 경우: 10년\n  2. 가산세를 제외한 지방세의 금액이 5천만원 미만인 경우: 5년"},{"법령":"지방세기본법","조문":"제39조제3항","원문":"③ 지방세징수권을 행사할 수 있는 때는 다음 각 호의 날로 한다.\n  1. 과세표준과 세액의 신고로 납세의무가 확정되는 지방세의 경우 신고한 세액에 대해서는 그 법정납부기한의 다음 날\n  2. 과세표준과 세액을 지방자치단체의 장이 결정 또는 경정하는 경우 납세고지한 세액에 대해서는 그 납세고지서에 따른 납부기한의 다음 날"}],"선지":[{"번호":1,"판정":"틀림","설명":"국세는 가산세를 뺀 금액이 5억원 이상이면 10년이다. 10억원이면 10년이다(국세기본법 제27조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"지방세는 5천만원 이상이면 10년이다. 1억원이면 10년이고, 7년이라는 시효 기간은 없다(지방세기본법 제39조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"5천만원은 '5천만원 이상'에 해당해 10년이다. 5년은 5천만원 미만일 때다(같은 항 제1호·제2호)."},{"번호":4,"판정":"틀림","설명":"확정신고한 세액 부분만 법정 신고납부기한의 다음 날이다. 정부가 경정하여 납부고지한 세액은 그 고지에 따른 납부기한의 다음 날이다(국세기본법 제27조제3항제1호·제2호)."},{"번호":5,"판정":"옳음","설명":"경정으로 납세고지한 세액은 납세고지서에 따른 납부기한의 다음 날이 징수권을 행사할 수 있는 때다(지방세기본법 제39조제3항제2호)."}],"개념":[{"종류":"표","제목":"징수권 소멸시효 기간과 기산일","머리":["구분","10년","5년","신고 세액의 기산일","경정·결정 고지 세액의 기산일"],"행":[["국세","5억원 이상","5억원 미만","법정 신고납부기한의 다음 날","납부고지에 따른 납부기한의 다음 날"],["지방세","5천만원 이상","5천만원 미만","법정납부기한의 다음 날","납세고지서에 따른 납부기한의 다음 날"],["근거 조문","국세기본법 제27조제1항","지방세기본법 제39조제1항","국세기본법 제27조제3항제1호 / 지방세기본법 제39조제3항제1호","국세기본법 제27조제3항제2호 / 지방세기본법 제39조제3항제2호"],["기산일 예외","-","-","법정 신고납부기한이 연장되면 연장된 기한의 다음 날(국세기본법 제27조제4항제3호, 지방세기본법 제39조제4항제2호)","원천징수·특별징수세액을 납부고지한 경우는 그 고지에 따른 납부기한의 다음 날(국세기본법 제27조제4항제1호, 지방세기본법 제39조제4항제1호)"]]},{"종류":"표","제목":"지방세징수권 시효의 중단과 정지(지방세기본법 제40조)","머리":["구분","사유"],"행":[["중단","납세고지, 독촉 또는 납부최고, 교부청구, 압류"],["다시 진행하는 때","고지한 납부기간·독촉 납부기간·교부청구 중의 기간·압류해제까지의 기간이 지난 때부터"],["정지","지방세법에 따른 분할납부기간·연부기간, 지방세징수법에 따른 징수유예기간·체납처분유예기간"],["정지(소송)","사해행위 취소의 소 또는 채권자대위 소송이 진행 중인 기간(각하·기각·취하되면 효력 없음)"],["정지(국외)","체납자가 국외에 6개월 이상 계속 체류하는 경우 그 체류기간"]]}],"함정":"신고한 세액과 경정으로 고지한 세액은 기산일이 다르다. ④는 두 경우를 섞었다. 금액 구간은 국세 5억원, 지방세 5천만원이고 '이상'이 10년이다."}},{"i":"S4-2-2-세법-03","r":"S4","g":3,"c":2,"n":27,"s":"세법","q":"지방세법상 취득세 납세의무에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 보지 아니한다.","상속회복청구의 소에 의한 법원의 확정판결에 의하여 특정 상속인이 당초 상속분을 초과하여 취득하게 되는 재산가액은 상속분이 감소한 상속인으로부터 증여받아 취득한 것으로 본다.","권리의 이전이나 행사에 등기 또는 등록이 필요한 부동산을 직계존속과 서로 교환한 경우에는 무상으로 취득한 것으로 본다.","증여로 인한 승계취득의 경우 해당 취득물건을 등기ㆍ등록하더라도 취득일부터 60일 이내에 공증받은 공정증서에 의하여 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 아니한다.","증여자가 배우자 또는 직계존비속이 아닌 경우 증여자의 채무를 인수하는 부담부 증여의 경우에는 그 채무액에 상당하는 부분은 부동산등을 유상으로 취득하는 것으로 본다."],"a":[5],"L":"세2-1","o":"기출","x":{"한줄":"배우자·직계존비속이 아닌 증여자의 채무를 떠안는 부담부증여는 채무액 부분을 유상취득으로 본다.","근거":[{"법령":"지방세법","조문":"제7조제4항","원문":"④ 선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다. 이 경우 「도시개발법」에 따른 도시개발사업(환지방식만 해당한다)의 시행으로 토지의 지목이 사실상 변경된 때에는 그 환지계획에 따라 공급되는 환지는 조합원이, 체비지 또는 보류지는 사업시행자가 각각 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제11항","원문":"⑪ 배우자 또는 직계존비속의 부동산등을 취득하는 경우에는 증여로 취득한 것으로 본다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그 취득한 부동산등 전체를 유상으로 취득한 것으로 본다.\n  3. 권리의 이전이나 행사에 등기 또는 등록이 필요한 부동산등을 서로 교환한 경우"},{"법령":"지방세법","조문":"제7조제12항","원문":"⑫ 증여자의 채무를 인수하는 부담부(負擔附) 증여의 경우에는 그 채무액에 상당하는 부분은 부동산등을 유상으로 취득하는 것으로 본다. 다만, 배우자 또는 직계존비속으로부터의 부동산등의 부담부 증여의 경우에는 제11항을 적용한다."},{"법령":"지방세법","조문":"제7조제13항","원문":"⑬ 상속개시 후 상속재산에 대하여 등기ㆍ등록ㆍ명의개서(名義改書) 등(이하 \"등기등\"이라 한다)에 의하여 각 상속인의 상속분이 확정되어 등기등이 된 후, 그 상속재산에 대하여 공동상속인이 협의하여 재분할한 결과 특정 상속인이 당초 상속분을 초과하여 취득하게 되는 재산가액은 그 재분할에 의하여 상속분이 감소한 상속인으로부터 증여받아 취득한 것으로 본다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.\n  2. 상속회복청구의 소에 의한 법원의 확정판결에 의하여 상속인 및 상속재산에 변동이 있는 경우"},{"법령":"지방세법 시행령","조문":"제20조제1항","원문":"① 무상취득의 경우에는 그 계약일(상속 또는 유증으로 인한 취득의 경우에는 상속 또는 유증 개시일을 말한다)에 취득한 것으로 본다. 다만, 해당 취득물건을 등기ㆍ등록하지 않고 다음 각 호의 어느 하나에 해당하는 서류로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.\n  2. 공정증서(공증인이 인증한 사서증서를 포함하되, 취득일부터 취득일이 속하는 달의 말일부터 3개월 이내에 공증받은 것만 해당한다)"}],"선지":[{"번호":1,"판정":"틀림","설명":"지목을 사실상 변경하여 가액이 증가하면 취득으로 본다(지방세법 제7조제4항). 가액이 늘지 않으면 취득이 아니다."},{"번호":2,"판정":"틀림","설명":"상속회복청구의 소에 의한 확정판결로 상속인·상속재산에 변동이 있으면 재분할에 따른 증여취득으로 보지 않는다(같은 법 제7조제13항제2호)."},{"번호":3,"판정":"틀림","설명":"배우자·직계존비속의 부동산을 취득하면 증여가 원칙이다. 다만 등기·등록이 필요한 부동산을 서로 교환한 경우는 전체를 유상취득으로 본다(같은 법 제7조제11항제3호)."},{"번호":4,"판정":"틀림","설명":"증여 취득물건을 등기·등록하면 나중에 계약이 해제돼도 취득한 것으로 본다. 해제로 취득하지 않은 것으로 보려면 등기·등록하지 않고 취득일이 속하는 달의 말일부터 3개월 이내에 공증받은 공정증서 등으로 입증해야 한다(시행령 제20조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"증여자의 채무를 인수하는 부담부증여는 채무액에 해당하는 부분이 유상취득이다. 배우자·직계존비속으로부터의 부담부증여는 제11항에 따라 따로 판단한다(같은 법 제7조제12항)."}],"개념":[{"종류":"표","제목":"취득세에서 '취득한 것으로 보는' 경우(지방세법 제7조)","머리":["유형","취득으로 보는 내용","조문"],"행":[["사실상 취득","등기·등록이 없어도 사실상 취득하면 소유자·양수인이 취득자","제2항"],["지목변경 등","토지 지목을 사실상 변경하거나 선박·차량·기계장비 종류를 변경해 가액이 증가한 경우","제4항"],["과점주주","주식 취득으로 과점주주가 되면 법인의 부동산등을 취득한 것으로 봄(설립 시 취득은 제외)","제5항"],["상속","상속인 각자가 상속받는 취득물건(지분)을 취득","제7항"],["주택조합 등","조합원용 조합주택용 부동산은 조합원이 취득(비조합원용은 제외)","제8항"],["배우자·직계존비속 취득","증여로 취득한 것으로 봄(공매·파산·등기필 부동산 교환·대가 지급 입증 등은 유상)","제11항"],["부담부증여","배우자·직계존비속이 아닌 증여자의 채무 인수분은 유상","제12항"],["상속 재분할","등기 후 협의 재분할로 늘어난 몫은 감소한 상속인으로부터 증여받은 것으로 봄","제13항"]]},{"종류":"비교","제목":"배우자·직계존비속의 부동산 취득(제7조제11항)","왼쪽":{"이름":"증여로 취득한 것으로 봄(원칙)","항목":["배우자 또는 직계존비속의 부동산등을 취득하는 경우","배우자·직계존비속으로부터의 부담부증여도 이 항을 적용"]},"오른쪽":{"이름":"전체를 유상취득으로 봄(예외)","항목":["공매(경매 포함)로 취득","파산선고로 처분되는 부동산등 취득","등기·등록이 필요한 부동산등을 서로 교환","대가 지급 사실이 소득·재산처분·상속세 또는 증여세 과세 등으로 증명되는 경우(대가가 시가인정액보다 낮아 차액이 3억원 이상이거나 시가인정액의 100분의 30 이상인 범위로 대통령령이 정하는 경우는 제외)"]}}],"함정":"④는 '등기하더라도'가 틀렸다. 등기·등록을 하지 않아야 해제로 취득을 부인할 수 있다. ③은 직계존속과의 교환이어서 증여로 보일 듯하지만 교환은 유상이다."}},{"i":"S4-2-2-세법-04","r":"S4","g":3,"c":2,"n":28,"s":"세법","q":"지방세기본법령 및 지방세법령상 취득세 납세의무의 성립에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["상속으로 인한 취득의 경우에는 상속개시일이 납세의무의 성립시기이다.","부동산의 증여계약으로 인한 취득에 있어서 소유권이전등기를 하지 않고 계약일부터 60일 이내에 공증받은 공정증서로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.","유상승계취득의 경우 사실상의 잔금지급일을 확인할 수 있는 때에는 사실상의 잔금지급일(그 전에 등기한 경우에는 등기일)이 납세의무의 성립시기이다.","「민법」에 따른 이혼시 재산분할로 인한 부동산 취득의 경우에는 취득물건의 등기일이 납세의무의 성립시기이다.","「도시 및 주거환경정비법」에 따른 재건축조합이 재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 같은 법에 따른 준공인가 고시일의 다음 날이 납세의무의 성립시기이다."],"a":[5],"L":"세2-1","o":"기출","x":{"한줄":"재건축조합이 조합원에게 귀속되지 않는 토지를 취득하는 때는 소유권이전 고시일의 다음 날이고, 준공인가 고시일은 기준이 아니다.","근거":[{"법령":"지방세기본법","조문":"제34조제1항제1호","원문":"① 지방세를 납부할 의무는 다음 각 호의 구분에 따른 시기에 성립한다.\n  1. 취득세: 과세물건을 취득하는 때"},{"법령":"지방세법 시행령","조문":"제20조제1항·제2항","원문":"① 무상취득의 경우에는 그 계약일(상속 또는 유증으로 인한 취득의 경우에는 상속 또는 유증 개시일을 말한다)에 취득한 것으로 본다. 다만, 해당 취득물건을 등기ㆍ등록하지 않고 다음 각 호의 어느 하나에 해당하는 서류로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.\n  2. 공정증서(공증인이 인증한 사서증서를 포함하되, 취득일부터 취득일이 속하는 달의 말일부터 3개월 이내에 공증받은 것만 해당한다)\n② 유상승계취득의 경우에는 사실상의 잔금지급일(신고인이 제출한 자료로 사실상의 잔금지급일을 확인할 수 없는 경우에는 계약상의 잔금지급일을 말하고, 계약상 잔금 지급일이 명시되지 않은 경우에는 계약일부터 60일이 경과한 날을 말한다)에 취득한 것으로 본다. 다만, 해당 취득물건을 등기ㆍ등록하지 않고 다음 각 호의 어느 하나에 해당하는 서류로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.\n  1. 화해조서ㆍ인낙조서(해당 조서에서 취득일부터 60일 이내에 계약이 해제된 사실이 입증되는 경우만 해당한다)\n  2. 공정증서(공증인이 인증한 사서증서를 포함하되, 취득일부터 60일 이내에 공증받은 것만 해당한다)\n  3. 행정안전부령으로 정하는 계약해제신고서(취득일부터 60일 이내에 제출된 것만 해당한다)\n  4. 부동산 거래신고 관련 법령에 따른 부동산거래계약 해제등 신고서(취득일부터 60일 이내에 등록관청에 제출한 경우만 해당한다)"},{"법령":"지방세법 시행령","조문":"제20조제7항","원문":"⑦ 「주택법」 제11조에 따른 주택조합이 주택건설사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「주택법」 제49조에 따른 사용검사를 받은 날에 그 토지를 취득한 것으로 보고, 「도시 및 주거환경정비법」 제35조제3항에 따른 재건축조합이 재건축사업을 하거나 「빈집 및 소규모주택 정비에 관한 특례법」 제23조제2항에 따른 소규모재건축조합이 소규모재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「도시 및 주거환경정비법」 제86조제2항 또는 「빈집 및 소규모주택 정비에 관한 특례법」 제40조제2항에 따른 소유권이전 고시일의 다음 날에 그 토지를 취득한 것으로 본다."},{"법령":"지방세법 시행령","조문":"제20조제13항·제14항","원문":"⑬ 「민법」 제839조의2 및 제843조에 따른 재산분할로 인한 취득의 경우에는 취득물건의 등기일 또는 등록일을 취득일로 본다.\n⑭ 제1항, 제2항 및 제5항에 따른 취득일 전에 등기 또는 등록을 한 경우에는 그 등기일 또는 등록일에 취득한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속·유증은 개시일에 취득한 것으로 본다(지방세법 시행령 제20조제1항). 취득세는 과세물건을 취득하는 때 납세의무가 성립한다(지방세기본법 제34조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"증여는 계약일 취득이 원칙이다. 등기·등록하지 않고 취득일이 속하는 달의 말일부터 3개월 이내에 공증받은 공정증서로 해제가 입증되면 취득하지 않은 것으로 본다. 60일 이내 공증이면 이 기한 안이다(시행령 제20조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"유상승계는 사실상 잔금지급일이 취득일이고, 그 전에 등기·등록하면 등기일·등록일이 취득일이다(시행령 제20조제2항·제14항)."},{"번호":4,"판정":"옳음","설명":"이혼 재산분할로 인한 취득은 취득물건의 등기일 또는 등록일이 취득일이다(시행령 제20조제13항)."},{"번호":5,"판정":"틀림","설명":"재건축조합이 비조합원용 토지를 취득하는 때는 소유권이전 고시일의 다음 날이다. 주택법상 주택조합이 취득하는 비조합원용 토지는 사용검사를 받은 날이다(시행령 제20조제7항)."}],"개념":[{"종류":"표","제목":"취득세 취득일(지방세법 시행령 제20조)","머리":["취득 유형","취득일"],"행":[["무상취득(증여 등)","계약일. 상속·유증은 개시일"],["유상승계취득","사실상 잔금지급일(확인 불가 시 계약상 잔금지급일, 명시가 없으면 계약일부터 60일이 지난 날)"],["연부취득","사실상의 연부금 지급일"],["건축·개수","사용승인서 교부일(임시사용승인 시 그날)과 사실상 사용일 중 빠른 날"],["주택조합의 비조합원용 토지","주택법에 따른 사용검사를 받은 날"],["재건축조합의 비조합원용 토지","소유권이전 고시일의 다음 날"],["매립·간척 원시취득","공사준공인가일. 그 전 사용승낙·허가·사실상 사용이 있으면 가장 빠른 날"],["지목변경","사실상 변경일과 공부상 변경일 중 빠른 날"],["점유취득·재산분할","취득물건의 등기일 또는 등록일"],["취득일 전 등기·등록(무상·유상·연부)","그 등기일 또는 등록일"]]},{"종류":"표","제목":"취득세 신고·납부 기한(지방세법 제20조제1항)","머리":["취득 원인","신고·납부 기한"],"행":[["일반(유상취득 등)","취득일부터 60일 이내"],["무상취득(상속 제외)·부담부증여","취득일이 속하는 달의 말일부터 3개월 이내"],["상속","상속개시일이 속하는 달의 말일부터 6개월 이내(외국에 주소를 둔 상속인이 있으면 9개월)"],["실종","실종선고일이 속하는 달의 말일부터 6개월 이내(외국에 주소를 둔 상속인이 있으면 9개월)"]]}],"함정":"⑤에서 '준공인가 고시일'을 '소유권이전 고시일'로 바꿔 놓았다. 주택조합은 사용검사일, 재건축조합은 소유권이전 고시일의 다음 날로 갈린다.","개정":"선지 ③에 '(그 전에 등기한 경우에는 등기일)'을 더했다. 시행령 제20조제14항에 따라 잔금지급일 전에 등기하면 등기일이 취득일이어서, 괄호가 없으면 ③도 틀린 선지가 되어 정답이 둘이 되기 때문이다. 증여 등 무상취득의 해제 입증 기한은 시행령 제20조제1항 각 호에 '취득일이 속하는 달의 말일부터 3개월'로 되어 있다(<개정 2023.12.29> 표시)."}},{"i":"S4-2-2-세법-05","r":"S4","g":3,"c":2,"n":29,"s":"세법","q":"지방세법상 등록면허세가 과세되는 등록 또는 등기에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["양식업권의 취득에 따른 등록","취득세 부과제척기간이 경과한 토지의 소유권이전등기","증여를 원인으로 하는 건물 소유권이전등기(취득가액 1억원)","취득가액이 50만원 이하인 토지의 소유권이전등기","부동산에 대한 저당권 설정등기"],"a":[3],"L":"세2-2","o":"변형","x":{"한줄":"증여를 원인으로 하는 소유권이전등기는 취득을 원인으로 한 등기여서 취득세를 내고, 등록면허세 과세대상에서 빠진다.","근거":[{"법령":"지방세법","조문":"제23조제1호","원문":"등록면허세에서 사용하는 용어의 뜻은 다음과 같다.\n  1. \"등록\"이란 재산권과 그 밖의 권리의 설정ㆍ변경 또는 소멸에 관한 사항을 공부에 등기하거나 등록하는 것을 말한다. 다만, 제2장에 따른 취득을 원인으로 이루어지는 등기 또는 등록은 제외하되, 다음 각 목의 어느 하나에 해당하는 등기나 등록은 포함한다.\n    가. 광업권ㆍ어업권 및 양식업권의 취득에 따른 등록\n    나. 제15조제2항제4호에 따른 외국인 소유의 취득세 과세대상 물건(차량, 기계장비, 항공기 및 선박만 해당한다)의 연부 취득에 따른 등기 또는 등록\n    다. 「지방세기본법」 제38조에 따른 취득세 부과제척기간이 경과한 물건의 등기 또는 등록\n    라. 제17조에 해당하는 물건의 등기 또는 등록"},{"법령":"지방세법","조문":"제17조제1항","원문":"① 취득가액이 50만원 이하일 때에는 취득세를 부과하지 아니한다."},{"법령":"지방세법","조문":"제28조제1항제1호다목","원문":"① 등록면허세는 등록에 대하여 제27조의 과세표준에 다음 각 호에서 정하는 세율을 적용하여 계산한 금액을 그 세액으로 한다. 다만, 제1호부터 제5호까지 및 제5호의2의 규정에 따라 산출한 세액이 해당 각 호의 그 밖의 등기 또는 등록 세율보다 적을 때에는 그 밖의 등기 또는 등록 세율을 적용한다.\n  1. 부동산 등기\n    다. 소유권 외의 물권과 임차권의 설정 및 이전\n      1) 지상권: 부동산 가액의 1천분의 2. 다만, 구분지상권의 경우에는 해당 토지의 지하 또는 지상 공간의 사용에 따른 건축물의 이용저해율(利用沮害率), 지하 부분의 이용저해율 및 그 밖의 이용저해율 등을 고려하여 행정안전부장관이 정하는 기준에 따라 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 구청장이 산정한 해당 토지 가액의 1천분의 2로 한다.\n      2) 저당권(지상권ㆍ전세권을 목적으로 등기하는 경우를 포함한다): 채권금액의 1천분의 2\n      3) 지역권: 요역지(要役地) 가액의 1천분의 2\n      4) 전세권: 전세금액의 1천분의 2\n      5) 임차권: 월 임대차금액의 1천분의 2."}],"선지":[{"번호":1,"판정":"옳음","설명":"양식업권·어업권·광업권의 취득에 따른 등록은 취득이 원인이어도 등록면허세 대상이다(지방세법 제23조제1호가목)."},{"번호":2,"판정":"옳음","설명":"취득세 부과제척기간이 지난 물건의 등기·등록은 등록면허세 대상이다(같은 호 다목). 과세표준은 등록 당시 가액과 취득당시가액 중 높은 가액이다(제27조제3항제2호)."},{"번호":3,"판정":"틀림","설명":"증여는 취득을 원인으로 한 등기여서 등록면허세 대상이 아니라 취득세 과세대상이다(제23조제1호 본문)."},{"번호":4,"판정":"옳음","설명":"취득가액이 50만원 이하이면 취득세를 부과하지 않는다(제17조제1항). 그 물건의 등기·등록은 등록면허세 대상에 포함된다(제23조제1호라목)."},{"번호":5,"판정":"옳음","설명":"저당권 설정은 소유권 외의 물권 설정이어서 취득이 아니다. 채권금액의 1천분의 2를 등록면허세로 낸다(제28조제1항제1호다목, 저당권)."}],"개념":[{"종류":"표","제목":"취득세와 등록면허세의 구분(지방세법 제23조제1호)","머리":["등기·등록의 내용","과세 세목","근거"],"행":[["매매·증여·상속 등 취득을 원인으로 하는 소유권 이전·보존 등기","취득세","제23조제1호 본문"],["지상권·저당권·전세권·지역권·임차권 등 소유권 외 권리의 설정·이전 등기","등록면허세","제28조제1항제1호다목"],["경매신청·가압류·가처분·가등기","등록면허세","제28조제1항제1호라목"],["광업권·어업권·양식업권의 취득에 따른 등록","등록면허세","제23조제1호가목"],["외국인 소유 차량·기계장비·항공기·선박을 소유권 이전 조건으로 임차해 수입하는 연부 취득의 등기·등록","등록면허세","제23조제1호나목"],["취득세 부과제척기간이 경과한 물건의 등기·등록","등록면허세","제23조제1호다목"],["취득가액 50만원 이하 물건의 등기·등록","등록면허세","제17조제1항, 제23조제1호라목"]]},{"종류":"표","제목":"부동산 등기의 등록면허세 세율(지방세법 제28조제1항제1호)","머리":["등기","과세표준","세율"],"행":[["소유권 보존","부동산 가액","1천분의 8"],["소유권 이전(유상)","부동산 가액","1천분의 20(유상 주택은 주택 취득세율의 100분의 50)"],["소유권 이전(무상)","부동산 가액","1천분의 15(상속은 1천분의 8)"],["지상권","부동산 가액","1천분의 2"],["저당권","채권금액","1천분의 2"],["지역권","요역지 가액","1천분의 2"],["전세권","전세금액","1천분의 2"],["임차권","월 임대차금액","1천분의 2"],["경매신청·가압류·가처분","채권금액","1천분의 2"],["가등기","부동산 가액 또는 채권금액","1천분의 2"],["그 밖의 등기","건수","건당 6천원"]]}],"함정":"③은 이전등기여서 등록면허세 대상으로 보이기 쉽다. 이전등기라도 증여·매매·상속처럼 취득이 원인이면 취득세다. 반대로 ④처럼 취득세가 면제되는 50만원 이하 물건은 등기할 때 등록면허세를 낸다."}},{"i":"S4-2-2-세법-06","r":"S4","g":3,"c":2,"n":30,"s":"세법","q":"지방세법령상 재산세의 부과ㆍ징수에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["주택에 대한 재산세의 경우 해당 연도에 부과ㆍ징수할 세액의 2분의 1은 매년 7월 16일부터 7월 31일까지, 나머지 2분의 1은 9월 16일부터 9월 30일까지를 납기로 한다. 다만, 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 9월 16일부터 9월 30일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다.","재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.","재산세를 징수하려면 토지, 건축물, 주택, 선박 및 항공기로 구분한 납세고지서에 과세표준과 세액을 적어 늦어도 납기개시 5일 전까지 발급하여야 한다.","재산세의 과세기준일은 매년 6월 1일로 한다.","고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다."],"a":[1],"L":"세2-3","o":"기출","x":{"한줄":"주택 재산세 세액이 20만원 이하이면 조례로 7월 16일부터 7월 31일까지 한꺼번에 걷을 수 있고, 9월에 한꺼번에 걷는 규정은 없다.","근거":[{"법령":"지방세법","조문":"제115조제1항제3호","원문":"① 재산세의 납기는 다음 각 호와 같다.\n  3. 주택: 해당 연도에 부과ㆍ징수할 세액의 2분의 1은 매년 7월 16일부터 7월 31일까지, 나머지 2분의 1은 9월 16일부터 9월 30일까지. 다만, 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다."},{"법령":"지방세법","조문":"제116조제1항·제2항","원문":"① 재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.\n② 재산세를 징수하려면 토지, 건축물, 주택, 선박 및 항공기로 구분한 납세고지서에 과세표준과 세액을 적어 늦어도 납기개시 5일 전까지 발급하여야 한다."},{"법령":"지방세법","조문":"제114조","원문":"재산세의 과세기준일은 매년 6월 1일로 한다."},{"법령":"지방세법","조문":"제119조","원문":"고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"20만원 이하 주택분은 조례로 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 걷는다(지방세법 제115조제1항제3호 단서). 9월 일괄 납기는 없다."},{"번호":2,"판정":"옳음","설명":"재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수로 부과·징수한다(제116조제1항)."},{"번호":3,"판정":"옳음","설명":"토지·건축물·주택·선박·항공기로 구분한 납세고지서를 늦어도 납기개시 5일 전까지 발급한다(제116조제2항)."},{"번호":4,"판정":"옳음","설명":"과세기준일은 매년 6월 1일이다(제114조)."},{"번호":5,"판정":"옳음","설명":"고지서 1장당 재산세 징수세액이 2천원 미만이면 징수하지 않는다(제119조)."}],"개념":[{"종류":"표","제목":"재산세 납기(지방세법 제115조제1항)","머리":["과세대상","납기"],"행":[["토지","9월 16일 ~ 9월 30일"],["건축물","7월 16일 ~ 7월 31일"],["주택","세액의 2분의 1은 7월 16일 ~ 7월 31일, 나머지 2분의 1은 9월 16일 ~ 9월 30일"],["주택(부과할 세액 20만원 이하)","조례로 7월 16일 ~ 7월 31일에 한꺼번에 부과·징수 가능"],["선박","7월 16일 ~ 7월 31일"],["항공기","7월 16일 ~ 7월 31일"]]},{"종류":"흐름","제목":"재산세 부과·징수 절차","단계":[{"이름":"과세기준일","설명":"매년 6월 1일 현재 사실상 소유자가 납세의무자(제114조, 제107조)"},{"이름":"세액 산정·고지서 발급","설명":"지방자치단체의 장이 세액을 산정해 보통징수. 토지·건축물·주택·선박·항공기로 구분한 납세고지서를 납기개시 5일 전까지 발급(제116조)"},{"이름":"납기 내 납부","설명":"토지 9월, 건축물·선박·항공기 7월, 주택은 7월·9월 반씩(제115조)"},{"이름":"물납·분할납부","설명":"납부세액 1천만원 초과 시 관할구역 안 부동산 물납 허가(제117조). 250만원 초과 시 납부기한이 지난 날부터 3개월 이내 분할납부(제118조)"},{"이름":"수시부과","설명":"과세대상 누락·위법·착오가 있으면 수시로 부과·징수(제115조제2항)"},{"이름":"소액 징수면제","설명":"고지서 1장당 징수할 세액이 2천원 미만이면 징수하지 않음(제119조)"}]}],"함정":"20만원 이하 일괄 납기를 9월로 적은 ①이 오답이다. 7월 16일부터 7월 31일이다. 토지에는 이 일괄 납기 특례가 없다."}},{"i":"S4-2-2-세법-07","r":"S4","g":3,"c":2,"n":31,"s":"세법","q":"지방세법령상 재산세 분리과세대상 토지에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["서울특별시 일반주거지역에 있는 개인 소유 농지로서 과세기준일 현재 실제 영농에 사용되고 있는 농지","건축물의 시가표준액이 그 부속토지의 시가표준액의 100분의 2에 미달하는 건축물의 부속토지 중 건축물의 바닥면적을 제외한 부분","건축물이 없는 지목 대지로서 차고용·물류단지시설용 등 별도합산 용도에 사용되지 않는 토지","「수도법」에 따른 상수원보호구역의 임야","「자동차관리법」에 따라 자동차관리사업의 등록을 한 자가 시설기준에 따라 사용하는 자동차정비사업장용 토지로서 그 시설의 최저면적기준의 1.5배에 해당하는 면적 이내의 토지"],"a":[4],"L":"세2-3","o":"변형","x":{"한줄":"상수원보호구역의 임야는 시행령이 정한 분리과세대상 임야다.","근거":[{"법령":"지방세법 시행령","조문":"제102조제2항제6호","원문":"② 법 제106조제1항제3호나목에서 \"대통령령으로 정하는 임야\"란 다음 각 호에서 정하는 임야를 말한다.\n  6. 「수도법」에 따른 상수원보호구역의 임야"},{"법령":"지방세법 시행령","조문":"제102조제1항제2호가목","원문":"① 법 제106조제1항제3호가목에서 \"대통령령으로 정하는 토지\"란 다음 각 호에서 정하는 것을 말한다.\n  2. 전ㆍ답ㆍ과수원\n    가. 전ㆍ답ㆍ과수원(이하 이 조에서 \"농지\"라 한다)으로서 과세기준일 현재 실제 영농에 사용되고 있는 개인이 소유하는 농지. 다만, 특별시ㆍ광역시(군 지역은 제외한다)ㆍ특별자치시ㆍ특별자치도 및 시지역(읍ㆍ면 지역은 제외한다)의 도시지역의 농지는 개발제한구역과 녹지지역(「국토의 계획 및 이용에 관한 법률」 제6조제1호에 따른 도시지역 중 같은 법 제36조제1항제1호 각 목의 구분에 따른 세부 용도지역이 지정되지 않은 지역을 포함한다. 이하 이 항에서 같다)에 있는 것으로 한정한다."},{"법령":"지방세법 시행령","조문":"제101조제1항제2호","원문":"① 법 제106조제1항제2호가목에서 \"공장용 건축물의 부속토지 등 대통령령으로 정하는 건축물의 부속토지\"란 다음 각 호의 어느 하나에 해당하는 건축물의 부속토지를 말한다. 다만, 「건축법」 등 관계 법령에 따라 허가 등을 받아야 할 건축물로서 허가 등을 받지 아니한 건축물 또는 사용승인을 받아야 할 건축물로서 사용승인(임시사용승인을 포함한다)을 받지 아니하고 사용 중인 건축물의 부속토지는 제외한다.\n  2. 건축물(제1호에 따른 공장용 건축물은 제외한다)의 부속토지 중 다음 각 목의 어느 하나에 해당하는 건축물의 부속토지를 제외한 건축물의 부속토지로서 건축물의 바닥면적(건축물 외의 시설의 경우에는 그 수평투영면적을 말한다)에 제2항에 따른 용도지역별 적용배율을 곱하여 산정한 면적 범위의 토지\n    가. 법 제106조제1항제3호다목에 따른 토지 안의 건축물의 부속토지\n    나. 건축물의 시가표준액이 해당 부속토지의 시가표준액의 100분의 2에 미달하는 건축물의 부속토지 중 그 건축물의 바닥면적을 제외한 부속토지"},{"법령":"지방세법 시행령","조문":"제101조제3항제5호","원문":"③ 법 제106조제1항제2호나목에서 \"대통령령으로 정하는 토지\"란 다음 각 호의 어느 하나에 해당하는 토지를 말한다.\n  5. 「자동차관리법」에 따라 자동차관리사업의 등록을 한 자가 그 시설기준에 따라 사용하는 자동차관리사업용 토지(자동차정비사업장용, 자동차해체재활용사업장용, 자동차매매사업장용 또는 자동차경매장용 토지만 해당한다)로서 그 시설의 최저면적기준의 1.5배에 해당하는 면적 이내의 토지"}],"선지":[{"번호":1,"판정":"틀림","설명":"특별시·광역시·시 지역 도시지역의 농지는 개발제한구역과 녹지지역에 있는 것만 분리과세다. 일반주거지역 농지는 해당하지 않아 종합합산이 된다(시행령 제102조제1항제2호가목)."},{"번호":2,"판정":"틀림","설명":"건축물 시가표준액이 부속토지 시가표준액의 100분의 2에 미달하면 그 부속토지 중 바닥면적을 뺀 부분은 별도합산에서 빠진다(시행령 제101조제1항제2호나목). 분리과세대상도 아니어서 종합합산이다."},{"번호":3,"판정":"틀림","설명":"별도합산도 분리과세도 아닌 토지는 종합합산이다(지방세법 제106조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"「수도법」상 상수원보호구역의 임야는 분리과세대상이다(시행령 제102조제2항제6호)."},{"번호":5,"판정":"틀림","설명":"자동차관리사업용 토지는 최저면적기준 1.5배 이내가 별도합산과세대상이다(시행령 제101조제3항제5호)."}],"개념":[{"종류":"표","제목":"토지 재산세 과세대상 3구분(지방세법 제106조·제113조)","머리":["구분","대상","세율 적용 방식"],"행":[["종합합산","별도합산·분리과세대상이 아닌 토지(나대지, 도시지역 일반 농지 등)","관할구역 안 토지 가액을 모두 합한 과세표준에 누진세율"],["별도합산","공장용 건축물 부속토지, 일반 건축물 부속토지(기준면적 이내), 차고용·보세창고용·물류단지시설용·부설주차장 등 시행령 열거 토지","관할구역 안 토지 가액을 모두 합한 과세표준에 누진세율"],["분리과세","일정 농지·목장용지, 산림 보호·육성 임야와 종중 임야, 골프장·고급오락장 토지, 공장용지 입지기준면적 범위 토지 등","해당 토지별 과세표준에 비례세율"],["별도합산 기준면적","건축물 바닥면적 × 용도지역별 배율: 전용주거 5배, 준주거·상업 3배, 일반주거·공업 4배, 녹지 7배, 미계획 4배, 도시지역 밖 7배","시행령 제101조제2항"],["허가·사용승인 없는 건축물","허가 등을 받아야 하는데 받지 않은 건축물, 사용승인 없이 사용 중인 건축물의 부속토지는 별도합산에서 제외(공장용 건축물은 공장용지 분리과세에서도 제외) → 종합합산","시행령 제101조제1항 단서, 제102조제1항제1호 단서"]]},{"종류":"표","제목":"분리과세 임야(지방세법 시행령 제102조제2항)","머리":["호","임야"],"행":[["제1호","특수산림사업지구 임야, 보전산지 임야로서 산림경영계획 인가를 받아 실행 중인 임야(도시지역은 원칙적 제외)"],["제2호","지정문화유산·보호구역·천연기념물등·그 보호구역 안의 임야"],["제3호","자연공원법에 따라 지정된 공원자연환경지구의 임야"],["제4호","종중이 소유하고 있는 임야"],["제5호","개발제한구역, 군사시설 제한보호구역, 접도구역, 철도보호지구, 도시공원, 도시자연공원구역, 하천 홍수관리구역의 임야"],["제6호","수도법에 따른 상수원보호구역의 임야"]]}],"함정":"①~③은 모두 종합합산이다. 도시지역 농지는 개발제한구역·녹지지역에 있어야 분리과세이고, 별도합산 기준에서 빠진 건축물 부속토지와 나대지는 분리과세가 되지 않는다. ⑤는 분리과세가 아니라 별도합산이다."}},{"i":"S4-2-2-세법-08","r":"S4","g":3,"c":2,"n":32,"s":"세법","q":"지방세법상 재산세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["선박에 대한 재산세의 납기는 매년 9월 16일부터 9월 30일까지이다.","재산세 납부세액이 250만원을 초과하는 경우 납부기한이 지난 날부터 6개월 이내에 분할납부하게 할 수 있다.","재산세의 세부담 상한은 주택에도 적용되어, 직전 연도 세액 상당액의 100분의 150을 초과하는 부분은 징수하지 아니한다.","토지와 건물의 소유자가 다른 주택에 대한 재산세는 토지와 건물의 가액을 합산한 과세표준에 주택 세율을 적용하고, 산출세액을 시가표준액 비율로 안분하여 각 소유자가 납부한다.","주택 부속토지의 경계가 명백하지 아니한 경우 그 주택의 바닥면적의 20배에 해당하는 토지를 주택의 부속토지로 한다."],"a":[4],"L":"세2-3","o":"변형","x":{"한줄":"토지와 건물의 소유자가 달라도 주택 세율은 두 가액을 합산한 과세표준에 적용하고, 세액은 소유자별로 안분해 낸다.","근거":[{"법령":"지방세법","조문":"제113조제3항","원문":"③ 주택을 2명 이상이 공동으로 소유하거나 토지와 건물의 소유자가 다를 경우 해당 주택에 대한 세율을 적용할 때 해당 주택의 토지와 건물의 가액을 합산한 과세표준에 제111조제1항제3호의 세율 또는 제111조의2제1항의 세율을 적용한다."},{"법령":"지방세법","조문":"제107조제1항제2호","원문":"① 재산세 과세기준일 현재 재산을 사실상 소유하고 있는 자는 재산세를 납부할 의무가 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 해당 각 호의 자를 납세의무자로 본다.\n  2. 주택의 건물과 부속토지의 소유자가 다를 경우: 그 주택에 대한 산출세액을 제4조제1항 및 제2항에 따른 건축물과 그 부속토지의 시가표준액 비율로 안분계산(按分計算)한 부분에 대해서는 그 소유자"},{"법령":"지방세법","조문":"제118조","원문":"지방자치단체의 장은 재산세의 납부세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다."},{"법령":"지방세법","조문":"제122조","원문":"해당 재산에 대한 재산세의 산출세액(제112조제1항 각 호 및 같은 조 제2항에 따른 각각의 세액을 말한다)이 대통령령으로 정하는 방법에 따라 계산한 직전 연도의 해당 재산에 대한 재산세액 상당액의 100분의 150을 초과하는 경우에는 100분의 150에 해당하는 금액을 해당 연도에 징수할 세액으로 한다. 다만, 주택의 경우에는 적용하지 아니한다.\n  1. 삭제<2023.3.14>\n  2. 삭제<2023.3.14>\n  3. 삭제<2023.3.14>"},{"법령":"지방세법 시행령","조문":"제105조","원문":"법 제106조제2항제3호에 따라 주택의 부속토지의 경계가 명백하지 아니한 경우에는 그 주택의 바닥면적의 10배에 해당하는 토지를 주택의 부속토지로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"선박의 납기는 7월 16일부터 7월 31일까지다(지방세법 제115조제1항제4호)."},{"번호":2,"판정":"틀림","설명":"분할납부 기간은 납부기한이 지난 날부터 3개월 이내다(제118조)."},{"번호":3,"판정":"틀림","설명":"세부담 상한 150%는 주택에 적용하지 않는다(제122조 단서). 주택은 과세표준상한액으로 조정한다(제110조제3항)."},{"번호":4,"판정":"옳음","설명":"주택의 토지·건물 소유자가 다르면 합산한 가액에 주택 세율을 적용하고(제113조제3항), 그 산출세액을 건축물과 부속토지의 시가표준액 비율로 안분한 부분에 대해 각 소유자가 납세의무를 진다(제107조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"경계가 명백하지 않으면 주택 바닥면적의 10배에 해당하는 토지를 부속토지로 본다(시행령 제105조)."}],"개념":[{"종류":"표","제목":"재산세 과세표준(지방세법 제110조, 시행령 제109조)","머리":["대상","과세표준","법률상 범위"],"행":[["토지·건축물","시가표준액 × 100분의 70","100분의 50 ~ 100분의 90"],["주택","시가표준액 × 100분의 60","100분의 40 ~ 100분의 80"],["1세대 1주택(2026년 납세의무 성립분, 시가표준액 3억원 이하)","시가표준액 × 100분의 43","100분의 30 ~ 100분의 70"],["1세대 1주택(2026년, 3억원 초과 6억원 이하)","시가표준액 × 100분의 44","100분의 30 ~ 100분의 70"],["1세대 1주택(2026년, 6억원 초과)","시가표준액 × 100분의 45","100분의 30 ~ 100분의 70"],["선박·항공기","시가표준액","-"]]},{"종류":"비교","제목":"세 부담 조정 방식","왼쪽":{"이름":"토지·건축물 등(주택 제외)","항목":["산출세액이 직전 연도 세액 상당액의 100분의 150을 넘으면 150%만 징수(제122조)","주택에는 적용하지 않음"]},"오른쪽":{"이름":"주택","항목":["산정한 과세표준이 과세표준상한액보다 크면 상한액이 과세표준(제110조제3항)","과세표준상한액 = 직전 연도 과세표준 상당액 + (시가표준액 과세표준 × 과세표준상한율)","과세표준상한율은 0에서 100분의 5 범위에서 시행령이 정함"]}}],"함정":"세부담 상한 150%를 주택에도 적용한다고 쓴 ③이 오답이다. 분할납부는 3개월, 물납은 1천만원 초과 + 관할구역 부동산으로 숫자를 섞기 쉽다. 부속토지 경계 불명이면 10배다.","개정":"주택에 대한 세부담 상한 적용 제외(제122조 단서)와 과세표준상한액(제110조제3항)은 <개정 2023.3.14> 표시가 붙어 있다. 2026년 납세의무가 성립하는 1세대 1주택의 공정시장가액비율 43·44·45%는 시행령 제109조제1항제2호 단서(<개정 2026.5.29>)에 있다."}},{"i":"S4-2-2-세법-09","r":"S4","g":3,"c":2,"n":33,"s":"세법","q":"2021년 귀속 토지분 종합부동산세에 관한 설명으로 옳은 것은? (단, 감면과 비과세와 지방세특례제한법 또는 조세특례제한법은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["재산세 과세대상 중 분리과세대상 토지는 종합부동산세 과세대상이다.","종합부동산세의 분납은 허용되지 않는다.","종합부동산세의 물납은 허용되지 않는다.","납세자에게 부정행위가 없으며 특례제척기간에 해당하지 않는 경우 원칙적으로 납세의무 성립일부터 3년이 지나면 종합부동산세를 부과할 수 없다.","별도합산과세대상인 토지의 재산세로 부과된 세액이 세부담 상한을 적용받는 경우 그 상한을 적용받기 전의 세액을 별도합산과세대상 토지분 종합부동산세액에서 공제한다."],"a":[3],"L":"세3-1","o":"기출","x":{"한줄":"종합부동산세법에는 분납 규정(제20조)만 있고 물납 규정이 없으므로 물납은 허용되지 않는다.","근거":[{"법령":"종합부동산세법","조문":"제11조","원문":"토지에 대한 종합부동산세는 국내에 소재하는 토지에 대하여 「지방세법」 제106조제1항제1호에 따른 종합합산과세대상(이하 \"종합합산과세대상\"이라 한다)과 같은 법 제106조제1항제2호에 따른 별도합산과세대상(이하 \"별도합산과세대상\"이라 한다)으로 구분하여 과세한다."},{"법령":"종합부동산세법","조문":"제14조제6항","원문":"⑥별도합산과세대상인 토지의 과세표준 금액에 대하여 해당 과세대상 토지의 토지분 재산세로 부과된 세액(「지방세법」 제111조제3항에 따라 가감조정된 세율이 적용된 경우에는 그 세율이 적용된 세액, 같은 법 제122조에 따라 세부담 상한을 적용받은 경우에는 그 상한을 적용받은 세액을 말한다)은 토지분 별도합산세액에서 이를 공제한다."},{"법령":"종합부동산세법","조문":"제20조","원문":"관할세무서장은 종합부동산세로 납부하여야 할 세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 그 세액의 일부를 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다."},{"법령":"국세기본법","조문":"제26조의2제1항","원문":"① 국세를 부과할 수 있는 기간(이하 \"부과제척기간\"이라 한다)은 국세를 부과할 수 있는 날부터 5년으로 한다. 다만, 역외거래[「국제조세조정에 관한 법률」 제2조제1항제1호에 따른 국제거래(이하 \"국제거래\"라 한다) 및 거래 당사자 양쪽이 거주자(내국법인과 외국법인의 국내사업장을 포함한다)인 거래로서 국외에 있는 자산의 매매ㆍ임대차, 국외에서 제공하는 용역과 관련된 거래를 말한다. 이하 같다]의 경우에는 국세를 부과할 수 있는 날부터 7년으로 한다."},{"법령":"국세기본법 시행령","조문":"제12조의3제1항제2호","원문":"① 법 제26조의2제9항에 따른 국세를 부과할 수 있는 날은 다음 각 호의 날로 한다.\n  2. 종합부동산세 및 인지세의 경우 해당 국세의 납세의무가 성립한 날"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지분 종합부동산세는 종합합산과세대상과 별도합산과세대상으로 구분해 과세한다. 분리과세대상 토지는 과세대상이 아니다(종합부동산세법 제11조)."},{"번호":2,"판정":"틀림","설명":"납부할 세액이 250만원을 초과하면 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다(제20조)."},{"번호":3,"판정":"옳음","설명":"종합부동산세법에는 물납 규정이 없고, 분납(제20조)과 납부유예(제20조의2)가 있다."},{"번호":4,"판정":"틀림","설명":"부과제척기간은 원칙적으로 5년이고, 종합부동산세는 납세의무가 성립한 날부터 센다(국세기본법 제26조의2제1항, 시행령 제12조의3제1항제2호)."},{"번호":5,"판정":"틀림","설명":"공제하는 재산세액은 세부담 상한을 적용받은 경우 그 상한을 적용받은 세액이다. 적용받기 전의 세액이 아니다(종합부동산세법 제14조제6항)."}],"개념":[{"종류":"표","제목":"토지분 종합부동산세: 종합합산과 별도합산","머리":["구분","종합합산과세대상","별도합산과세대상"],"행":[["납세의무자(제12조)","토지분 재산세 납세의무자로서 공시가격 합계 5억원 초과","토지분 재산세 납세의무자로서 공시가격 합계 80억원 초과"],["과세표준 공제(제13조)","공시가격 합계 − 5억원","공시가격 합계 − 80억원"],["공정시장가액비율(시행령 제2조의4제2항)","100분의 100(2019~2021년 성립분은 85·90·95)","100분의 100(2019~2021년 성립분은 85·90·95)"],["세율(제14조)","15억원 이하 1천분의 10 / 15억~45억원 1천500만원 + 초과분 1천분의 20 / 45억원 초과 7천500만원 + 초과분 1천분의 30","200억원 이하 1천분의 5 / 200억~400억원 1억원 + 초과분 1천분의 6 / 400억원 초과 2억2천만원 + 초과분 1천분의 7"],["재산세액 공제(제14조제3항·제6항)","조례로 가감한 세율이 적용된 세액, 세부담 상한을 적용받은 세액을 공제","조례로 가감한 세율이 적용된 세액, 세부담 상한을 적용받은 세액을 공제"],["세부담 상한(제15조)","직전 연도 총세액상당액의 100분의 150 초과분은 없는 것으로 봄","직전 연도 총세액상당액의 100분의 150 초과분은 없는 것으로 봄"],["분리과세대상 토지","과세대상 아님(제11조)","과세대상 아님(제11조)"]]},{"종류":"흐름","제목":"종합부동산세 부과·납부","단계":[{"이름":"과세기준일","설명":"재산세와 같은 매년 6월 1일(제3조)"},{"이름":"부과·징수","설명":"관할세무서장이 세액을 결정해 12월 1일~12월 15일에 부과·징수. 납부고지서에 주택 및 토지로 구분한 과세표준과 세액을 적어 납부기간 개시 5일 전까지 발급(제16조제1항·제2항)"},{"이름":"신고납부 선택","설명":"신고납부방식을 택하면 12월 1일~12월 15일에 신고·납부. 이 경우 정부의 결정은 없었던 것으로 봄(제16조제3항·제4항)"},{"이름":"분납","설명":"납부할 세액 250만원 초과 시 납부기한이 지난 날부터 6개월 이내(제20조). 물납은 없음"},{"이름":"경정","설명":"과세대상 누락·위법·착오가 있으면 다시 부과·징수 또는 경정(제17조)"},{"이름":"부과제척기간","설명":"5년. 종합부동산세는 납세의무 성립일부터 계산(국세기본법 제26조의2, 시행령 제12조의3)"}]}],"함정":"물납은 재산세에만 있다(지방세법 제117조). 종합부동산세는 분납만 된다. ⑤처럼 재산세 공제액을 '상한 적용 전' 세액으로 쓰면 틀리다. 제척기간은 5년이다."}},{"i":"S4-2-2-세법-10","r":"S4","g":3,"c":2,"n":34,"s":"세법","q":"종합부동산세법상 종합부동산세에 관한 설명으로 틀린 것은? (단, 감면 및 비과세와 지방세특례제한법 또는 조세특례제한법은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["종합합산과세대상인 토지에 대한 종합부동산세의 과세표준은 납세의무자별로 해당 토지의 공시가격을 합산한 금액에서 5억원을 공제한 금액에 공정시장가액비율을 곱한 금액으로 한다.","1세대 1주택자의 주택분 종합부동산세 과세표준은 주택의 공시가격을 합산한 금액에서 12억원을 공제한 금액에 공정시장가액비율을 곱한 금액으로 한다.","종합부동산세를 신고납부방식으로 납부하려는 납세의무자는 해당 연도 11월 16일부터 11월 30일까지 과세표준과 세액을 관할세무서장에게 신고하여야 한다.","납세의무자가 법인 또는 법인으로 보는 단체인 경우(공익법인등과 대통령령으로 정하는 공공주택사업자 등은 제외) 주택분 종합부동산세의 세율은 2주택 이하를 소유하면 1천분의 27, 3주택 이상을 소유하면 1천분의 50이다.","수탁자 명의로 등기된 신탁주택의 경우 위탁자가 종합부동산세를 납부할 의무가 있다."],"a":[3],"L":"세3-1","o":"변형","x":{"한줄":"신고납부방식을 택한 납세의무자의 신고·납부 기간은 12월 1일부터 12월 15일까지이고 11월이 아니다.","근거":[{"법령":"종합부동산세법","조문":"제16조제3항","원문":"③제1항 및 제2항에도 불구하고 종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 대통령령으로 정하는 바에 따라 관할세무서장에게 신고하여야 한다. 이 경우 제1항의 규정에 따른 결정은 없었던 것으로 본다."},{"법령":"종합부동산세법","조문":"제13조제1항","원문":"① 종합합산과세대상인 토지에 대한 종합부동산세의 과세표준은 납세의무자별로 해당 과세대상토지의 공시가격을 합산한 금액에서 5억원을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다."},{"법령":"종합부동산세법","조문":"제8조제1항","원문":"① 주택에 대한 종합부동산세의 과세표준은 납세의무자별로 주택의 공시가격을 합산한 금액에서 다음 각 호의 금액을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다. 다만, 그 금액이 영보다 작은 경우에는 영으로 본다.\n  1. 대통령령으로 정하는 1세대 1주택자(이하 \"1세대 1주택자\"라 한다): 12억원\n  2. 제9조제2항제3호 각 목의 세율이 적용되는 법인 또는 법인으로 보는 단체: 0원\n  3. 제1호 및 제2호에 해당하지 아니하는 자: 9억원"},{"법령":"종합부동산세법","조문":"제9조제2항","원문":"② 납세의무자가 법인 또는 법인으로 보는 단체인 경우 제1항에도 불구하고 과세표준에 다음 각 호에 따른 세율을 적용하여 계산한 금액을 주택분 종합부동산세액으로 한다.\n  1. 「상속세 및 증여세법」 제16조에 따른 공익법인등(이하 이 조에서 \"공익법인등\"이라 한다)이 직접 공익목적사업에 사용하는 주택만을 보유한 경우와 「공공주택 특별법」 제4조에 따른 공공주택사업자 등 사업의 특성을 고려하여 대통령령으로 정하는 경우: 제1항제1호에 따른 세율\n  2. 공익법인등으로서 제1호에 해당하지 아니하는 경우: 제1항 각 호에 따른 세율\n  3. 제1호 및 제2호 외의 경우: 다음 각 목에 따른 세율\n    가. 2주택 이하를 소유한 경우: 1천분의 27\n    나. 3주택 이상을 소유한 경우: 1천분의 50"},{"법령":"종합부동산세법","조문":"제7조제2항","원문":"② 「신탁법」 제2조에 따른 수탁자(이하 \"수탁자\"라 한다)의 명의로 등기 또는 등록된 신탁재산으로서 주택(이하 \"신탁주택\"이라 한다)의 경우에는 제1항에도 불구하고 같은 조에 따른 위탁자[「주택법」 제2조제11호가목에 따른 지역주택조합, 같은 호 나목에 따른 직장주택조합 등 위탁자별로 구분 과세가 곤란한 조합으로서 대통령령으로 정하는 조합(이하 \"지역주택조합등\"이라 한다)이 조합원이 납부한 금전으로 매수하여 소유하고 있는 신탁주택의 경우에는 해당 지역주택조합등을 말한다. 이하 \"위탁자\"라 한다]가 종합부동산세를 납부할 의무가 있다. 이 경우 위탁자가 신탁주택을 소유한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"종합합산 토지의 과세표준은 공시가격 합산액에서 5억원을 공제하고 공정시장가액비율을 곱한 금액이다(종합부동산세법 제13조제1항). 비율은 100분의 100이다(시행령 제2조의4제2항)."},{"번호":2,"판정":"옳음","설명":"1세대 1주택자는 12억원, 법인 등 제9조제2항제3호 세율 적용 대상은 0원, 그 밖의 자는 9억원을 공제한다(제8조제1항). 비율은 100분의 60이다(시행령 제2조의4제1항)."},{"번호":3,"판정":"틀림","설명":"신고납부방식은 12월 1일부터 12월 15일까지 신고한다. 신고하면 정부의 결정은 없었던 것으로 본다(제16조제3항)."},{"번호":4,"판정":"옳음","설명":"공익법인등이 아닌 법인은 2주택 이하 1천분의 27, 3주택 이상 1천분의 50의 단일세율이다(제9조제2항제3호)."},{"번호":5,"판정":"옳음","설명":"수탁자 명의로 등기된 신탁주택은 위탁자가 납세의무자이고 위탁자가 소유한 것으로 본다(제7조제2항). 위탁자의 다른 재산으로 체납액을 못 채우면 수탁자가 그 신탁주택으로 납부한다(제7조의2)."}],"개념":[{"종류":"표","제목":"주택분 종합부동산세: 공제금액과 세율","머리":["납세의무자","공제금액(제8조제1항)","세율(제9조)"],"행":[["1세대 1주택자(공동명의 1주택자 특례 포함)","12억원","제9조제1항 세율. 산출세액에서 연령(20·30·40%)과 보유기간(20·40·50%) 공제를 합계 100분의 80 한도로 중복 적용"],["법인·법인으로 보는 단체(제9조제2항제3호 세율 적용)","0원","2주택 이하 1천분의 27, 3주택 이상 1천분의 50"],["공익법인등이 직접 공익목적사업에 쓰는 주택만 보유한 경우 등(제9조제2항제1호)","9억원","제9조제1항제1호(2주택 이하) 세율"],["그 밖의 자(개인 등)","9억원","제9조제1항 세율"],["개인 2주택 이하 세율","-","3억원 이하 1천분의 5 / 3억~6억원 150만원 + 초과분 1천분의 7 / 6억~12억원 360만원 + 초과분 1천분의 10 / 12억~25억원 960만원 + 초과분 1천분의 13 / 25억~50억원 2천650만원 + 초과분 1천분의 15 / 50억~94억원 6천400만원 + 초과분 1천분의 20 / 94억원 초과 1억5천200만원 + 초과분 1천분의 27"],["개인 3주택 이상 세율","-","12억원까지는 위와 같고, 12억~25억원 960만원 + 초과분 1천분의 20 / 25억~50억원 3천560만원 + 초과분 1천분의 30 / 50억~94억원 1억1천60만원 + 초과분 1천분의 40 / 94억원 초과 2억8천660만원 + 초과분 1천분의 50"]]},{"종류":"표","제목":"종합부동산세 연간 일정","머리":["시기","내용","근거"],"행":[["6월 1일","과세기준일","제3조"],["9월 16일 ~ 9월 30일","합산배제 주택 보유현황 신고","제8조제3항"],["9월 16일 ~ 9월 30일","일시적 2주택·상속주택·지방 저가주택 보유자의 1세대 1주택자 특례 신청","제8조제5항"],["9월 16일 ~ 9월 30일","공동명의 1주택자 신청","제10조의2제2항"],["12월 1일 ~ 12월 15일","부과·징수, 신고납부 선택 시 신고·납부","제16조제1항·제3항"],["납부기간 개시 5일 전","납부고지서 발급(주택 및 토지 구분)","제16조제2항"],["납부기한 만료 3일 전","1세대 1주택자의 주택분 납부유예 신청","제20조의2제1항"],["납부기한이 지난 날부터 6개월 이내","250만원 초과 세액 분납","제20조"]]}],"함정":"신고납부 기간을 11월로 적은 ③이 오답이다. 9월 16일~30일은 합산배제 신고와 특례 신청 시기이고, 부과·신고납부는 12월 1일~15일이다. 법인의 단일세율 1천분의 27·1천분의 50은 공익법인등과 대통령령으로 정하는 공공주택사업자 등을 제외한 경우다.","개정":"일시적 2주택 1세대 1주택자 특례의 기간이 시행령 제4조의2제1항에서 바뀌었다(<개정 2026.9.30> 표시). 종전주택과 신규주택이 모두 조정대상지역이면 신규주택 취득일부터 2년(조정대상지역 공고일 이전 취득·계약금 지급이 확인되면 제외), 그 밖의 경우는 3년이다. 시행령 파일의 시행일은 2026.10.1이다."}},{"i":"S4-2-2-세법-11","r":"S4","g":3,"c":2,"n":35,"s":"세법","q":"다음은 소득세법시행령 제168조의6 '비사업용 토지의 기간기준'의 일부이다. ( )에 들어갈 숫자로 옳은 것은?","b":"○ 토지의 소유기간이 5년 이상인 경우에는 다음 각 목의 모두에 해당하는 기간\n가. 양도일 직전 5년 중 ( ㄱ )년을 초과하는 기간\n나. 양도일 직전 3년 중 ( ㄴ )년을 초과하는 기간\n다. 토지의 소유기간의 100분의 ( ㄷ )에 상당하는 기간을 초과하는 기간","bs":"글자","img":[],"ch":["ㄱ: 2, ㄴ: 1, ㄷ: 30","ㄱ: 2, ㄴ: 1, ㄷ: 40","ㄱ: 3, ㄴ: 2, ㄷ: 30","ㄱ: 3, ㄴ: 2, ㄷ: 40","ㄱ: 4, ㄴ: 2, ㄷ: 40"],"a":[2],"L":"세3-2","o":"기출","x":{"한줄":"소유기간 5년 이상인 토지의 비사업용 토지 기간기준은 직전 5년 중 2년 초과, 직전 3년 중 1년 초과, 소유기간의 100분의 40 초과다.","근거":[{"법령":"소득세법","조문":"제104조의3제1항","원문":"① 제104조제1항제8호에서 \"비사업용 토지\"란 해당 토지를 소유하는 기간 중 대통령령으로 정하는 기간 동안 다음 각 호의 어느 하나에 해당하는 토지를 말한다."},{"법령":"소득세법 시행령","조문":"제168조의6제1호","원문":"법 제104조의3제1항 각 호 외의 부분에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 어느 하나에 해당하는 기간을 말한다. 이 경우 기간의 계산은 일수로 한다.\n  1. 토지의 소유기간이 5년 이상인 경우에는 다음 각 목의 모두에 해당하는 기간\n    가. 양도일 직전 5년 중 2년을 초과하는 기간\n    나. 양도일 직전 3년 중 1년을 초과하는 기간\n    다. 토지의 소유기간의 100분의 40에 상당하는 기간을 초과하는 기간"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ 2, ㄴ 1은 맞고 ㄷ이 30이어서 틀리다. 소유기간의 100분의 40이다."},{"번호":2,"판정":"-","설명":"ㄱ 2, ㄴ 1, ㄷ 40이 시행령 제168조의6제1호 가목·나목·다목이다."},{"번호":3,"판정":"-","설명":"ㄱ 3, ㄴ 2, ㄷ 30은 세 칸 모두 틀리다."},{"번호":4,"판정":"-","설명":"ㄷ 40은 맞지만 ㄱ은 3년이 아니라 2년, ㄴ은 2년이 아니라 1년이다."},{"번호":5,"판정":"-","설명":"ㄷ 40은 맞지만 ㄱ은 4년이 아니라 2년, ㄴ은 2년이 아니라 1년이다."}],"개념":[{"종류":"표","제목":"비사업용 토지의 기간기준(소득세법 시행령 제168조의6)","머리":["토지 소유기간","가","나","다"],"행":[["5년 이상","양도일 직전 5년 중 2년 초과","양도일 직전 3년 중 1년 초과","소유기간의 100분의 40 초과"],["3년 이상 5년 미만","소유기간 − 3년 초과","양도일 직전 3년 중 1년 초과","소유기간의 100분의 40 초과"],["3년 미만","소유기간 − 2년 초과(소유기간 2년 미만이면 가목 적용 안 함)","소유기간의 100분의 40 초과","-"],["공통","각 목을 모두 충족하는 기간이어야 하고, 기간은 일수로 계산","-","-"]]},{"종류":"계산","제목":"소유기간 10년 토지의 기간기준 판정(예시)","단계":[{"설명":"가목: 양도일 직전 5년 중 비사업용 사용기간이 2년을 넘는지 본다(비사업용 3년이라 가정)","식":"3년 > 2년","값":"충족"},{"설명":"나목: 양도일 직전 3년 중 비사업용 사용기간이 1년을 넘는지 본다(비사업용 2년이라 가정)","식":"2년 > 1년","값":"충족"},{"설명":"다목: 소유기간 10년의 100분의 40를 구하고, 전체 비사업용 사용기간(4.5년이라 가정)과 비교한다","식":"10년 × 40% = 4년, 4.5년 > 4년","값":"충족"},{"설명":"세 목을 모두 충족하므로 그 기간 동안 비사업용 토지에 해당한다","식":"가 · 나 · 다 모두 충족","값":"비사업용 토지"}]}],"함정":"소유기간 5년 이상 구간의 숫자는 2·1·40이다. 3·2는 3년 미만과 3년 이상 5년 미만 구간의 숫자와 섞이기 쉽고, 30은 어느 구간에도 없다."}},{"i":"S4-2-2-세법-12","r":"S4","g":3,"c":2,"n":36,"s":"세법","q":"거주자 甲은 보유기간 8년, 그중 거주기간 5년인 국내 소재 1세대 1주택(고가주택)을 양도하였다. 양도 당시 실지거래가액은 20억원이고 취득가액은 8억원이며, 자본적지출액과 양도비는 합계 2억원(증명서류 있음)이다. 甲의 양도소득세 과세표준은? (단, 甲은 1세대 1주택자이고 다른 양도는 없으며 감면은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["1억 4,150만원","1억 8,950만원","1억 9,200만원","2억 6,950만원","3억 3,350만원"],"a":[2],"L":"세3-2","o":"변형","x":{"한줄":"양도차익 10억원 중 (20억−12억)/20억 = 40%인 4억원이 과세되고, 장기보유특별공제는 표 2의 보유 32% + 거주 20% = 52%에 같은 40%를 곱한 2억 800만원이라 과세표준은 1억 8,950만원이다.","근거":[{"법령":"소득세법","조문":"제89조제1항제3호","원문":"① 다음 각 호의 소득에 대해서는 양도소득에 대한 소득세(이하 \"양도소득세\"라 한다)를 과세하지 아니한다.\n  3. 다음 각 목의 어느 하나에 해당하는 주택(주택 및 이에 딸린 토지의 양도 당시 실지거래가액의 합계액이 12억원을 초과하는 고가주택은 제외한다)과 이에 딸린 토지로서 건물이 정착된 면적에 지역별로 대통령령으로 정하는 배율을 곱하여 산정한 면적 이내의 토지(이하 이 조에서 \"주택부수토지\"라 한다)의 양도로 발생하는 소득\n    가. 1세대가 1주택을 보유하는 경우로서 대통령령으로 정하는 요건을 충족하는 주택\n    나. 1세대가 1주택을 양도하기 전에 다른 주택을 대체취득하거나 상속, 동거봉양, 혼인 등으로 인하여 2주택 이상을 보유하는 경우로서 대통령령으로 정하는 주택"},{"법령":"소득세법","조문":"제95조제3항","원문":"③ 제89조제1항제3호에 따라 양도소득의 비과세대상에서 제외되는 고가주택(이에 딸린 토지를 포함한다) 및 같은 항 제4호 각 목 외의 부분 단서에 따라 양도소득의 비과세대상에서 제외되는 조합원입주권에 해당하는 자산의 양도차익 및 장기보유 특별공제액은 제1항에도 불구하고 대통령령으로 정하는 바에 따라 계산한 금액으로 한다."},{"법령":"소득세법 시행령","조문":"제160조제1항","원문":"①법 제95조제3항에 따른 고가주택(하나의 건물이 주택과 주택 외의 부분으로 복합되어 있는 경우와 주택에 딸린 토지에 주택 외의 건물이 있는 경우에는 주택 외의 부분은 주택으로 보지 않는다)에 해당하는 자산의 양도차익 및 장기보유특별공제액은 다음 각 호의 산식으로 계산한 금액으로 한다. 이 경우 해당 주택 또는 이에 부수되는 토지가 그 보유기간이 다르거나 미등기양도자산에 해당하거나 일부만 양도하는 때에는 12억원에 해당 주택 또는 이에 부수되는 토지의 양도가액이 그 주택과 이에 부수되는 토지의 양도가액의 합계액에서 차지하는 비율을 곱하여 안분계산한다.\n  1. 고가주택에 해당하는 자산에 적용할 양도차익: 법 제95조제1항에 따른 양도차익 × (양도가액 − 12억원) ÷ 양도가액\n  2. 고가주택에 해당하는 자산에 적용할 장기보유특별공제액: 법 제95조제2항에 따른 장기보유특별공제액 × (양도가액 − 12억원) ÷ 양도가액"},{"법령":"소득세법 시행령","조문":"제159조의4","원문":"법 제95조제2항 표 외의 부분 단서 및 같은 조 제5항 각 호 외의 부분에서 \"대통령령으로 정하는 1세대 1주택\"이란 각각 1세대가 양도일(주택의 매매계약을 체결한 후 해당 계약에 따라 주택을 주택 외의 용도로 용도변경하여 양도하는 경우에는 해당 주택의 매매계약일을 말한다) 현재 국내에 1주택(제155조ㆍ제155조의2ㆍ제156조의2ㆍ제156조의3 및 그 밖의 규정에 따라 1세대 1주택으로 보는 주택을 포함한다)을 보유하고 보유기간 중 거주기간이 2년 이상인 것을 말한다. 이 경우 해당 1주택이 제155조제3항 각 호 외의 부분 본문에 따른 공동상속주택인 경우 거주기간은 해당 주택에 거주한 공동상속인 중 그 거주기간이 가장 긴 사람이 거주한 기간으로 판단한다."}],"선지":[{"번호":1,"판정":"-","설명":"거주기간 5년을 8년으로 잘못 넣어 거주 32%를 적용한 값이다. 장기보유특별공제를 64%로 계산하면 4억 − 2억 5,600만 − 250만 = 1억 4,150만원이다."},{"번호":2,"판정":"-","설명":"양도차익 10억 × 40% = 4억, 장기보유특별공제 10억 × 52% × 40% = 2억 800만, 양도소득금액 1억 9,200만, 기본공제 250만 차감 후 1억 8,950만원이다."},{"번호":3,"판정":"-","설명":"양도소득 기본공제 250만원을 빼지 않은 양도소득금액이다."},{"번호":4,"판정":"-","설명":"표 2의 거주기간별 공제율 20%를 빠뜨리고 보유기간별 32%만 적용한 값이다. 4억 − 1억 2,800만 − 250만 = 2억 6,950만원이다."},{"번호":5,"판정":"-","설명":"고가주택이 아닌 일반 장기보유특별공제 표 1(8년 보유 16%)을 적용한 값이다. 4억 − 6,400만 − 250만 = 3억 3,350만원이다."}],"개념":[{"종류":"계산","제목":"1세대 1주택 고가주택의 양도소득세 과세표준","단계":[{"설명":"양도차익 = 양도가액 − 취득가액 − 자본적지출액·양도비","식":"20억 − 8억 − 2억","값":"10억원"},{"설명":"고가주택 과세비율 = (양도가액 − 12억원) ÷ 양도가액","식":"(20억 − 12억) ÷ 20억","값":"0.4"},{"설명":"과세되는 양도차익 = 양도차익 × 과세비율(시행령 제160조제1항제1호)","식":"10억 × 0.4","값":"4억원"},{"설명":"장기보유특별공제율: 1세대 1주택으로 거주기간 2년 이상이므로 표 2. 보유 8년 이상 9년 미만 32%, 거주 5년 이상 6년 미만 20%","식":"32% + 20%","값":"52%"},{"설명":"장기보유특별공제액 = 일반 공제액 × 과세비율(같은 항 제2호)","식":"10억 × 52% × 0.4","값":"2억 800만원"},{"설명":"양도소득금액 = 과세되는 양도차익 − 장기보유특별공제액","식":"4억 − 2억 800만","값":"1억 9,200만원"},{"설명":"양도소득 기본공제 연 250만원 차감","식":"1억 9,200만 − 250만","값":"1억 8,950만원(과세표준)"}]},{"종류":"표","제목":"장기보유특별공제율(소득세법 제95조제2항 표 1·표 2)","머리":["보유기간","표 2 보유기간별","표 2 거주기간별","표 1(일반) 보유기간별"],"행":[["3년 이상 4년 미만","100분의 12","2년 이상 3년 미만 100분의 8(보유 3년 이상 한정), 3년 이상 4년 미만 100분의 12","100분의 6"],["4년 이상 5년 미만","100분의 16","100분의 16","100분의 8"],["5년 이상 6년 미만","100분의 20","100분의 20","100분의 10"],["8년 이상 9년 미만","100분의 32","100분의 32","100분의 16"],["10년 이상","100분의 40","100분의 40","10년 이상 11년 미만 100분의 20, 15년 이상 100분의 30"]]}],"함정":"거주기간과 보유기간의 공제율을 따로 읽어야 한다. 거주 5년이면 보유 32%와 거주 20%를 합한다. 고가주택이라는 이유로 장기보유특별공제를 배제하지 않고, 양도차익과 같은 비율로 줄여 적용한다. 기본공제 250만원을 마지막에 뺀다.","개정":"고가주택은 양도 당시 실지거래가액 합계 12억원 초과 주택이다(소득세법 제89조제1항제3호, 시행령 제156조·제160조). 법 제89조에는 <개정 2021.12.8>, 시행령 제156조·제160조에는 <개정 2022.2.15> 표시가 붙어 있다. 옛 기출 문항의 9억원은 현행과 다르다."}},{"i":"S4-2-2-세법-13","r":"S4","g":3,"c":2,"n":37,"s":"세법","q":"소득세법령상 거주자의 국내자산 양도에 대한 양도소득세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 2개월이내에 양도소득세를 신고하여야 한다.","토지를 매매하는 거래당사자가 매매계약서의 거래가액을 실지거래가액과 다르게 적은 경우에는 해당 자산에 대하여 ｢소득세법｣에 따른 양도소득세의 비과세에 관한 규정을 적용할 때, 비과세 받을 세액에서 '비과세에 관한 규정을 적용하지 아니하였을 경우의 양도소득 산출세액'과 '매매계약서의 거래가액과 실지거래가액과의 차액' 중 큰 금액을 뺀다.","사업상의 형편으로 인하여 세대전원이 다른 시ㆍ군으로 주거를 이전하게 되어 6개월 거주한 주택을 양도하는 경우 보유기간 및 거주기간의 제한을 받지 아니하고 양도소득세가 비과세된다.","토지의 양도로 발생한 양도차손은 동일한 과세기간에 전세권의 양도로 발생한 양도소득금액에서 공제할 수 있다.","상속받은 주택과 상속개시 당시 보유한 일반주택을 국내에 각각 1개씩 소유한 1세대가 상속받은 주택을 양도하는 경우에는 국내에 1개의 주택을 소유하고 있는 것으로 보아 1세대 1주택 비과세 규정을 적용한다."],"a":[4],"L":"세3-2","o":"기출","x":{"한줄":"토지(제94조제1항제1호)와 전세권(같은 항 제2호)은 양도소득금액을 같은 호로 묶어 계산하므로 한쪽의 양도차손을 다른 쪽 양도소득금액에서 공제한다.","근거":[{"법령":"소득세법","조문":"제102조제1항","원문":"① 양도소득금액은 다음 각 호의 소득별로 구분하여 계산한다. 이 경우 소득금액을 계산할 때 발생하는 결손금은 다른 호의 소득금액과 합산하지 아니한다.\n  1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 소득\n  2. 제94조제1항제3호에 따른 소득\n  3. 제94조제1항제5호에 따른 소득\n  4. 제94조제1항제6호에 따른 소득"},{"법령":"소득세법","조문":"제102조제2항","원문":"② 제1항에 따라 양도소득금액을 계산할 때 양도차손이 발생한 자산이 있는 경우에는 제1항 각 호별로 해당 자산 외의 다른 자산에서 발생한 양도소득금액에서 그 양도차손을 공제한다. 이 경우 공제방법은 양도소득금액의 세율 등을 고려하여 대통령령으로 정한다."},{"법령":"소득세법","조문":"제105조제1항","원문":"① 제94조제1항 각 호(같은 항 제3호다목 및 같은 항 제5호는 제외한다)에서 규정하는 자산을 양도한 거주자는 제92조제2항에 따라 계산한 양도소득과세표준을 다음 각 호의 구분에 따른 기간에 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다.\n  1. 제94조제1항제1호ㆍ제2호ㆍ제4호 및 제6호에 따른 자산을 양도한 경우에는 그 양도일이 속하는 달의 말일부터 2개월. 다만, 「부동산 거래신고 등에 관한 법률」 제10조제1항에 따른 토지거래계약에 관한 허가구역에 있는 토지를 양도할 때 토지거래계약허가를 받기 전에 대금을 청산한 경우에는 그 허가일(토지거래계약허가를 받기 전에 허가구역의 지정이 해제된 경우에는 그 해제일을 말한다)이 속하는 달의 말일부터 2개월로 한다.\n  3. 제1호 및 제2호에도 불구하고 제88조제1호 각 목 외의 부분 후단에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 3개월"},{"법령":"소득세법","조문":"제91조제2항","원문":"② 제94조제1항제1호 및 제2호의 자산을 매매하는 거래당사자가 매매계약서의 거래가액을 실지거래가액과 다르게 적은 경우에는 해당 자산에 대하여 이 법 또는 이 법 외의 법률에 따른 양도소득세의 비과세 또는 감면에 관한 규정을 적용할 때 비과세 또는 감면받았거나 받을 세액에서 다음 각 호의 구분에 따른 금액을 뺀다.\n  1. 이 법 또는 이 법 외의 법률에 따라 양도소득세의 비과세에 관한 규정을 적용받을 경우: 비과세에 관한 규정을 적용하지 아니하였을 경우의 제104조제1항에 따른 양도소득 산출세액과 매매계약서의 거래가액과 실지거래가액과의 차액 중 적은 금액"},{"법령":"소득세법 시행령","조문":"제154조제1항제3호","원문":"①법 제89조제1항제3호가목에서 \"대통령령으로 정하는 요건\"이란 1세대가 양도일(주택의 매매계약을 체결한 후 해당 계약에 따라 주택을 주택 외의 용도로 용도변경하여 양도하는 경우에는 해당 주택의 매매계약일을 말한다. 이하 이 항에서 같다) 현재 국내에 1주택을 보유하고 있는 경우로서 해당 주택의 보유기간이 2년(제8항제2호에 해당하는 거주자의 주택인 경우는 3년) 이상인 것[취득 당시에 「주택법」 제63조의2제1항제1호에 따른 조정대상지역(이하 \"조정대상지역\"이라 한다)에 있는 주택의 경우에는 해당 주택의 보유기간이 2년(제8항제2호에 해당하는 거주자의 주택인 경우에는 3년) 이상이고 그 보유기간 중 거주기간이 2년 이상인 것]을 말한다. 다만, 1세대가 양도일 현재 국내에 1주택을 보유하고 있는 경우로서 제1호부터 제3호까지의 어느 하나에 해당하는 경우에는 그 보유기간 및 거주기간의 제한을 받지 않으며 제5호에 해당하는 경우에는 거주기간의 제한을 받지 않는다.\n  3. 1년이상 거주한 주택을 재정경제부령으로 정하는 취학, 근무상의 형편, 질병의 요양, 그 밖에 부득이한 사유로 양도하는 경우"},{"법령":"소득세법 시행령","조문":"제155조제2항","원문":"②상속받은 주택[조합원입주권 또는 분양권을 상속받아 사업시행 완료 후 취득한 신축주택을 포함하며, 피상속인이 상속개시 당시 2 이상의 주택{상속받은 1주택이 「도시 및 주거환경정비법」에 따른 재개발사업(이하 \"재개발사업\"이라 한다), 재건축사업(이하 \"재건축사업\"이라 한다) 또는 「빈집 및 소규모주택 정비에 관한 특례법」에 따른 소규모재건축사업, 소규모재개발사업, 가로주택정비사업, 자율주택정비사업(이하 \"소규모재건축사업등\"이라 한다)의 시행으로 2 이상의 주택이 된 경우를 포함한다}을 소유한 경우에는 다음 각 호의 순위에 따른 1주택을 말한다]과 그 밖의 주택(상속개시 당시 보유한 주택 또는 상속개시 당시 보유한 조합원입주권이나 분양권에 의하여 사업시행 완료 후 취득한 신축주택만 해당하며, 상속개시일부터 소급하여 2년 이내에 피상속인으로부터 증여받은 주택 또는 증여받은 조합원입주권이나 분양권에 의하여 사업시행 완료 후 취득한 신축주택은 제외한다. 이하 이 항에서 \"일반주택\"이라 한다)을 국내에 각각 1개씩 소유하고 있는 1세대가 일반주택을 양도하는 경우에는 국내에 1개의 주택을 소유하고 있는 것으로 보아 제154조제1항을 적용한다. 다만, 상속인과 피상속인이 상속개시 당시 1세대인 경우에는 1주택을 보유하고 1세대를 구성하는 자가 직계존속(배우자의 직계존속을 포함하며, 세대를 합친 날 현재 직계존속 중 어느 한 사람 또는 모두가 60세 이상으로서 1주택을 보유하고 있는 경우만 해당한다)을 동거봉양하기 위하여 세대를 합침에 따라 2주택을 보유하게 되는 경우로서 합치기 이전부터 보유하고 있었던 주택만 상속받은 주택으로 본다(이하 제3항, 제7항제1호, 제156조의2제7항제1호 및 제156조의3제5항제1호에서 같다)."}],"선지":[{"번호":1,"판정":"틀림","설명":"부담부증여의 채무액 부분은 양도일이 속하는 달의 말일부터 3개월 이내에 예정신고한다. 2개월은 토지·건물 등 일반 양도의 기한이다(소득세법 제105조제1항제1호·제3호)."},{"번호":2,"판정":"틀림","설명":"비과세 규정을 적용하지 않았을 때의 양도소득 산출세액과 매매계약서 거래가액·실지거래가액의 차액 중 적은 금액을 뺀다. 큰 금액이 아니다(제91조제2항제1호)."},{"번호":3,"판정":"틀림","설명":"부득이한 사유로 보유·거주 제한을 받지 않으려면 1년 이상 거주한 주택이어야 한다. 6개월 거주로는 해당하지 않는다(시행령 제154조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"토지(제94조제1항제1호)와 전세권(제2호다목)은 양도소득금액을 같은 호로 묶어 계산하므로 양도차손을 다른 자산의 양도소득금액에서 공제한다(제102조제1항제1호·제2항)."},{"번호":5,"판정":"틀림","설명":"상속주택 특례는 일반주택을 양도할 때 적용한다. 상속받은 주택을 양도할 때는 적용하지 않는다(시행령 제155조제2항)."}],"개념":[{"종류":"표","제목":"양도소득금액의 구분 계산과 양도차손 공제(소득세법 제102조)","머리":["구분","자산(제94조제1항)","양도차손 공제"],"행":[["제1호 소득","토지·건물(제1호), 부동산에 관한 권리(제2호), 기타자산(제4호)","같은 호 안의 다른 자산 양도소득금액에서 공제"],["제2호 소득","주식등(제3호)","같은 호 안에서만 공제"],["제3호 소득","파생상품등(제5호)","같은 호 안에서만 공제"],["제4호 소득","신탁 수익권(제6호)","같은 호 안에서만 공제"],["다른 호와의 관계","소득금액을 계산할 때 생긴 결손금은 다른 호의 소득금액과 합산하지 않음","제102조제1항 후단"]]},{"종류":"표","제목":"1세대 1주택 특례: 2주택이어도 1주택으로 보는 경우(소득세법 시행령 제155조)","머리":["사유","양도하는 주택","기한"],"행":[["일시적 2주택(종전 주택 취득 후 1년 이상 지나 신규 주택 취득)","종전 주택","신규 주택 취득일부터 3년. 종전·신규 주택이 모두 조정대상지역이면 2년(제1항)"],["상속주택 + 일반주택","일반주택(상속주택 양도는 해당 없음)","기한 없음(제2항)"],["60세 이상 직계존속 동거봉양 합가","먼저 양도하는 주택","합친 날부터 10년 이내(제4항)"],["혼인 합가","먼저 양도하는 주택","혼인한 날부터 10년 이내(제5항)"],["지정문화유산·등록문화유산·천연기념물등 주택 + 일반주택","일반주택","기한 없음(제6항)"],["농어촌주택(상속·이농·귀농) + 일반주택","일반주택","귀농주택은 취득한 날부터 5년 이내(제7항)"],["부득이한 사유로 취득한 수도권 밖 주택 + 일반주택","일반주택","사유가 해소된 날부터 3년 이내(제8항)"]]}],"함정":"①은 부담부증여를 일반 양도의 2개월로 적었다. ③은 거주 요건이 6개월이 아니라 1년 이상이다. ⑤는 상속받은 주택을 팔 때가 아니라 일반주택을 팔 때만 특례를 받는다. ②는 두 금액 중 적은 금액을 뺀다.","개정":"일시적 2주택 특례의 기간이 시행령 제155조제1항에서 바뀌었다(<개정 2026.9.30> 표시). 종전 주택과 신규 주택이 모두 조정대상지역이면 신규 주택 취득일부터 2년(조정대상지역 공고일 이전 취득 또는 계약금 지급 확인 시 제외), 그 밖은 3년이다. 시행령 파일의 시행일은 2026.10.1이다."}},{"i":"S4-2-2-세법-14","r":"S4","g":3,"c":2,"n":38,"s":"세법","q":"소득세법 시행령 제162조 제1항이 규정하는 양도 또는 취득의 시기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["제6호: 「민법」 제245조제1항에 따라 부동산의 소유권을 취득하는 경우에는 소유권이전등기 접수일","제5호: 증여에 의하여 취득한 자산에 대하여는 증여를 받은 날","제7호: 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따라 수용되는 경우에는 대금을 청산한 날, 수용의 개시일 또는 소유권이전등기접수일 중 빠른 날(소유권에 관한 소송으로 보상금이 공탁된 경우는 제외)","제9호: 「도시개발법」에 따른 환지처분으로 교부받은 토지의 면적이 환지처분에 의한 권리면적보다 감소된 경우 그 감소된 면적의 토지에 대한 양도시기는 환지처분의 공고가 있은 날의 다음 날","제3호: 재정경제부령이 정하는 장기할부조건의 경우에는 소유권이전등기(등록 및 명의개서를 포함) 접수일ㆍ인도일 또는 사용수익일 중 빠른 날"],"a":[1],"L":"세3-2","o":"변형","x":{"한줄":"점유취득시효로 소유권을 취득하는 경우의 취득시기는 등기접수일이 아니라 그 부동산의 점유를 개시한 날이다.","근거":[{"법령":"소득세법 시행령","조문":"제162조제1항제3호·제5호·제6호","원문":"①법 제98조 전단에서 \"대금을 청산한 날이 분명하지 아니한 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 경우를 말한다.\n  3. 재정경제부령이 정하는 장기할부조건의 경우에는 소유권이전등기(등록 및 명의개서를 포함한다) 접수일ㆍ인도일 또는 사용수익일중 빠른 날\n  5. 상속 또는 증여에 의하여 취득한 자산에 대하여는 그 상속이 개시된 날 또는 증여를 받은 날\n  6. 「민법」 제245조제1항의 규정에 의하여 부동산의 소유권을 취득하는 경우에는 당해부동산의 점유를 개시한 날"},{"법령":"소득세법 시행령","조문":"제162조제1항제7호~제9호","원문":"①법 제98조 전단에서 \"대금을 청산한 날이 분명하지 아니한 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 경우를 말한다.\n  7. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」이나 그 밖의 법률에 따라 공익사업을 위하여 수용되는 경우에는 대금을 청산한 날, 수용의 개시일 또는 소유권이전등기접수일 중 빠른 날. 다만, 소유권에 관한 소송으로 보상금이 공탁된 경우에는 소유권 관련 소송 판결 확정일로 한다.\n  8. 완성 또는 확정되지 아니한 자산을 양도 또는 취득한 경우로서 해당 자산의 대금을 청산한 날까지 그 목적물이 완성 또는 확정되지 아니한 경우에는 그 목적물이 완성 또는 확정된 날. 이 경우 건설 중인 건물의 완성된 날에 관하여는 제4호를 준용한다.\n  9. 「도시개발법」 또는 그 밖의 법률에 따른 환지처분으로 인하여 취득한 토지의 취득시기는 환지 전의 토지의 취득일. 다만, 교부받은 토지의 면적이 환지처분에 의한 권리면적보다 증가 또는 감소된 경우에는 그 증가 또는 감소된 면적의 토지에 대한 취득시기 또는 양도시기는 환지처분의 공고가 있은 날의 다음날로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"「민법」 제245조제1항(점유취득시효)으로 소유권을 취득하면 해당 부동산의 점유를 개시한 날이 취득시기다(소득세법 시행령 제162조제1항제6호)."},{"번호":2,"판정":"옳음","설명":"상속 또는 증여로 취득한 자산은 상속이 개시된 날 또는 증여를 받은 날이다(제5호)."},{"번호":3,"판정":"옳음","설명":"수용은 대금을 청산한 날, 수용의 개시일, 소유권이전등기접수일 중 빠른 날이다. 소유권에 관한 소송으로 보상금이 공탁되면 소송 판결 확정일이다(제7호)."},{"번호":4,"판정":"옳음","설명":"환지처분으로 교부받은 토지의 면적이 권리면적보다 증가 또는 감소하면 그 면적의 취득·양도시기는 환지처분 공고일의 다음 날이다(제9호 단서)."},{"번호":5,"판정":"옳음","설명":"장기할부조건은 소유권이전등기 접수일·인도일·사용수익일 중 빠른 날이다(제3호). 장기할부조건은 재정경제부령으로 정한다."}],"개념":[{"종류":"표","제목":"양도·취득시기 특례(소득세법 시행령 제162조제1항)","머리":["호","경우","양도·취득시기"],"행":[["제1호","대금을 청산한 날이 분명하지 않은 경우","등기·등록접수일 또는 명의개서일"],["제2호","대금 청산 전에 소유권이전등기를 한 경우","등기접수일"],["제3호","장기할부조건","등기접수일·인도일·사용수익일 중 빠른 날"],["제4호","자기가 건설한 건축물","사용승인서 교부일. 그 전 사실상 사용·임시사용승인이 있으면 빠른 날. 무허가는 사실상 사용일"],["제5호","상속·증여","상속이 개시된 날 또는 증여를 받은 날"],["제6호","민법 제245조제1항 점유취득시효","점유를 개시한 날"],["제7호","공익사업 수용","대금청산일·수용개시일·소유권이전등기접수일 중 빠른 날(소송 공탁은 판결 확정일)"],["제8호","완성·확정되지 않은 자산","그 목적물이 완성 또는 확정된 날"],["제9호","환지처분","환지 전 토지의 취득일. 면적 증감분은 환지처분 공고일의 다음 날"],["제9호의2","지적재조사 경계 확정으로 면적 증가","종전 토지를 취득한 날"]]},{"종류":"비교","제목":"공익사업 수용의 양도시기(제7호)","왼쪽":{"이름":"원칙","항목":["대금을 청산한 날, 수용의 개시일, 소유권이전등기접수일 중 빠른 날"]},"오른쪽":{"이름":"소유권에 관한 소송으로 보상금이 공탁된 경우","항목":["소유권 관련 소송 판결 확정일"]}}],"함정":"①은 점유취득시효를 등기 기준으로 바꿔 놓았다. 점유취득시효는 점유 개시일이다. ③의 공탁 예외와 ④의 환지 면적 증감 예외까지 알아야 옳은 선지로 확정할 수 있다."}},{"i":"S4-2-2-세법-15","r":"S4","g":3,"c":2,"n":39,"s":"세법","q":"소득세법령상 양도소득세의 양도 또는 취득시기에 관한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["대금을 청산한 날이 분명하지 아니한 경우에는 등기부ㆍ등록부 또는 명부 등에 기재된 등기ㆍ등록접수일 또는 명의개서일","상속에 의하여 취득한 자산에 대하여는 그 상속이 개시된 날","대금을 청산하기 전에 소유권이전등기를 한 경우에는 등기부에 기재된 등기접수일","자기가 건설한 건축물로서 건축허가를 받지 아니하고 건축하는 건축물에 있어서는 그 사실상의 사용일","완성되지 아니한 자산을 양도한 경우로서 해당 자산의 대금을 청산한 날까지 그 목적물이 완성되지 아니한 경우에는 해당 자산의 대금을 청산한 날"],"a":[5],"L":"세3-2","o":"기출","x":{"한줄":"완성되지 않은 자산은 대금을 청산한 날까지 완성되지 않았더라도 그 목적물이 완성 또는 확정된 날이 양도·취득시기다.","근거":[{"법령":"소득세법","조문":"제98조","원문":"자산의 양도차익을 계산할 때 그 취득시기 및 양도시기는 대금을 청산한 날이 분명하지 아니한 경우 등 대통령령으로 정하는 경우를 제외하고는 해당 자산의 대금을 청산한 날로 한다. 이 경우 자산의 대금에는 해당 자산의 양도에 대한 양도소득세 및 양도소득세의 부가세액을 양수자가 부담하기로 약정한 경우에는 해당 양도소득세 및 양도소득세의 부가세액은 제외한다."},{"법령":"소득세법 시행령","조문":"제162조제1항제1호·제2호·제4호·제5호·제8호","원문":"①법 제98조 전단에서 \"대금을 청산한 날이 분명하지 아니한 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 경우를 말한다.\n  1. 대금을 청산한 날이 분명하지 아니한 경우에는 등기부ㆍ등록부 또는 명부 등에 기재된 등기ㆍ등록접수일 또는 명의개서일\n  2. 대금을 청산하기 전에 소유권이전등기(등록 및 명의의 개서를 포함한다)를 한 경우에는 등기부ㆍ등록부 또는 명부등에 기재된 등기접수일\n  4. 자기가 건설한 건축물에 있어서는 「건축법」 제22조제2항에 따른 사용승인서 교부일. 다만, 사용승인서 교부일 전에 사실상 사용하거나 같은 조 제3항제2호에 따른 임시사용승인을 받은 경우에는 그 사실상의 사용일 또는 임시사용승인을 받은 날 중 빠른 날로 하고 건축허가를 받지 아니하고 건축하는 건축물에 있어서는 그 사실상의 사용일로 한다.\n  5. 상속 또는 증여에 의하여 취득한 자산에 대하여는 그 상속이 개시된 날 또는 증여를 받은 날\n  8. 완성 또는 확정되지 아니한 자산을 양도 또는 취득한 경우로서 해당 자산의 대금을 청산한 날까지 그 목적물이 완성 또는 확정되지 아니한 경우에는 그 목적물이 완성 또는 확정된 날. 이 경우 건설 중인 건물의 완성된 날에 관하여는 제4호를 준용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대금 청산일이 분명하지 않으면 등기·등록접수일 또는 명의개서일이다(소득세법 시행령 제162조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"상속으로 취득한 자산은 상속이 개시된 날이다(제5호)."},{"번호":3,"판정":"옳음","설명":"대금을 청산하기 전에 소유권이전등기를 하면 등기접수일이다(제2호)."},{"번호":4,"판정":"옳음","설명":"건축허가 없이 건축한 건축물은 사실상의 사용일이다(제4호 단서). 추후 받은 사용승인일이 아니다."},{"번호":5,"판정":"틀림","설명":"대금을 청산한 날까지 완성 또는 확정되지 않은 자산은 그 목적물이 완성 또는 확정된 날이다(제8호)."}],"개념":[{"종류":"비교","제목":"자기가 건설한 건축물의 취득시기(시행령 제162조제1항제4호)","왼쪽":{"이름":"허가·사용승인을 받은 건축물","항목":["건축법 제22조제2항에 따른 사용승인서 교부일","사용승인서 교부일 전에 사실상 사용하거나 임시사용승인을 받으면 사실상 사용일과 임시사용승인일 중 빠른 날"]},"오른쪽":{"이름":"건축허가 없이 건축한 건축물","항목":["그 사실상의 사용일","추후 사용승인이나 임시사용승인을 받아도 그 받은 날이 아님"]}},{"종류":"표","제목":"대금 청산을 기준으로 한 양도·취득시기","머리":["경우","시기","근거"],"행":[["원칙","대금을 청산한 날(양도소득세·부가세를 양수자가 부담하기로 약정한 금액은 대금에서 제외)","소득세법 제98조"],["청산일이 분명하지 않음","등기·등록접수일 또는 명의개서일","시행령 제162조제1항제1호"],["청산 전에 이전등기","등기접수일","같은 항 제2호"],["장기할부조건","등기접수일·인도일·사용수익일 중 빠른 날","같은 항 제3호"],["미완성·미확정 자산","목적물이 완성 또는 확정된 날(건설 중인 건물의 완성일은 제4호 준용)","같은 항 제8호"]]}],"함정":"⑤는 원칙인 대금 청산일을 그대로 적용했다. 목적물이 완성·확정되지 않은 자산은 완성·확정된 날이 시기다. ④의 사실상 사용일을 사용승인일로 바꿔 쓰면 틀리다."}},{"i":"S4-2-2-세법-16","r":"S4","g":3,"c":2,"n":40,"s":"세법","q":"소득세법령상 거주자의 부동산임대 등에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 부동산임대업에서 발생하는 사업소득이 있는 자가 사업장 소재지를 납세지로 신청한 경우 국세청장 또는 관할지방국세청장은 대통령령으로 정하는 바에 따라 사업장 소재지를 납세지로 지정할 수 있다.\nㄴ. 국외에 소재하는 주택 1개만을 소유하는 자의 해당 주택 임대소득은 비과세소득이다.\nㄷ. 광업재단을 대여하는 사업은 부동산임대업에 해당되지 않는다.\nㄹ. 해당 과세기간의 주거용 건물 임대업을 제외한 부동산임대업에서 발생한 결손금은 그 과세기간의 종합소득 과세표준을 계산할 때 공제하지 아니한다.","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":[2],"L":"세3-3","o":"기출","x":{"한줄":"ㄱ은 사업장 소재지 납세지 지정 규정에, ㄹ은 주거용 외 부동산임대업 결손금 불공제 규정에 맞고, 국외 소재 주택 임대소득은 과세되며 광업재단 대여도 부동산임대업이다.","근거":[{"법령":"소득세법","조문":"제9조제1항제1호","원문":"① 국세청장 또는 관할 지방국세청장은 다음 각 호의 어느 하나에 해당하는 경우에는 제6조부터 제8조까지의 규정에도 불구하고 대통령령으로 정하는 바에 따라 납세지를 따로 지정할 수 있다.\n  1. 사업소득이 있는 거주자가 사업장 소재지를 납세지로 신청한 경우"},{"법령":"소득세법","조문":"제12조제2호나목","원문":"다음 각 호의 소득에 대해서는 소득세를 과세하지 아니한다.\n  2. 사업소득 중 다음 각 목의 어느 하나에 해당하는 소득\n    나. 1개의 주택을 소유하는 자의 주택임대소득(제99조에 따른 기준시가가 12억원을 초과하는 주택 및 국외에 소재하는 주택의 임대소득은 제외한다) 또는 해당 과세기간에 대통령령으로 정하는 총수입금액의 합계액이 2천만원 이하인 자의 주택임대소득(2018년 12월 31일 이전에 끝나는 과세기간까지 발생하는 소득으로 한정한다). 이 경우 주택 수의 계산 및 주택임대소득의 산정 등 필요한 사항은 대통령령으로 정한다."},{"법령":"소득세법","조문":"제45조제2항","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다.\n  1. 부동산 또는 부동산상의 권리를 대여하는 사업\n  2. 공장재단 또는 광업재단을 대여하는 사업\n  3. 채굴에 관한 권리를 대여하는 사업으로서 대통령령으로 정하는 사업"},{"법령":"소득세법","조문":"제45조제3항제2호","원문":"③ 부동산임대업에서 발생한 결손금과 제1항 및 제2항 단서에 따라 공제하고 남은 결손금(이하 \"이월결손금\"이라 한다)은 해당 이월결손금이 발생한 과세기간의 종료일부터 15년 이내에 끝나는 과세기간의 소득금액을 계산할 때 먼저 발생한 과세기간의 이월결손금부터 순서대로 다음 각 호의 구분에 따라 공제한다. 다만, 「국세기본법」 제26조의2에 따른 국세부과의 제척기간이 지난 후에 그 제척기간 이전 과세기간의 이월결손금이 확인된 경우 그 이월결손금은 공제하지 아니한다.\n  2. 부동산임대업에서 발생한 이월결손금은 부동산임대업의 소득금액에서 공제한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 옳고 ㄴ이 틀려서 맞는 조합이 아니다."},{"번호":2,"판정":"-","설명":"옳은 것은 ㄱ과 ㄹ이다."},{"번호":3,"판정":"-","설명":"ㄴ과 ㄷ이 모두 틀렸다."},{"번호":4,"판정":"-","설명":"ㄷ이 틀려서 맞는 조합이 아니다."},{"번호":5,"판정":"-","설명":"ㄴ과 ㄷ이 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"사업소득이 있는 거주자가 사업장 소재지를 납세지로 신청하면 국세청장 또는 관할지방국세청장이 납세지를 따로 지정할 수 있다(소득세법 제9조제1항제1호). 거주자의 원칙적 납세지는 주소지다(제6조제1항)."},{"기호":"ㄴ","판정":"틀림","설명":"1개 주택 소유자의 주택임대소득은 비과세이지만 기준시가 12억원을 초과하는 주택과 국외에 소재하는 주택의 임대소득은 제외한다. 국외 주택 1개의 임대소득은 과세된다(제12조제2호나목)."},{"기호":"ㄷ","판정":"틀림","설명":"부동산임대업에는 부동산·부동산상의 권리 대여 외에 공장재단 또는 광업재단을 대여하는 사업과 채굴에 관한 권리를 대여하는 사업이 들어간다(제45조제2항제2호·제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"주거용 건물 임대업을 제외한 부동산임대업의 결손금은 종합소득 과세표준 계산에서 공제하지 않는다(제45조제2항). 이월결손금은 15년 이내 부동산임대업의 소득금액에서 공제한다(같은 조 제3항제2호)."}],"개념":[{"종류":"표","제목":"주택임대소득의 과세(소득세법 제12조·제25조, 시행령 제53조·제8조의2)","머리":["소유 주택","임대료(월세)","보증금 간주임대료","비고"],"행":[["국내 1주택(기준시가 12억원 이하)","비과세","해당 없음","제12조제2호나목"],["1주택이라도 기준시가 12억원 초과 또는 국외 소재","과세","해당 없음","제12조제2호나목"],["2주택","과세","기준시가 12억원 이하 주택을 빼고 센 2주택이 되고 보증금 합계가 12억원을 초과할 때","제25조제1항제2호, 시행령 제53조제1항"],["3주택 이상","과세","보증금 합계가 3억원을 초과할 때","제25조제1항제1호"],["소형주택","-","주거전용 40㎡ 이하이면서 기준시가 2억원 이하인 주택은 2026년 12월 31일까지 주택 수에 넣지 않음","제25조제1항 본문"],["주택 수 계산","-","본인과 배우자 합산, 공동소유는 지분이 가장 큰 사람 소유로 계산","시행령 제8조의2제3항"]]},{"종류":"비교","제목":"부동산임대업 결손금의 공제(소득세법 제45조)","왼쪽":{"이름":"주거용 건물 임대업을 제외한 부동산임대업","항목":["그 과세기간의 종합소득 과세표준 계산에서 결손금 공제 안 함(제2항)","이월결손금은 발생 과세기간 종료일부터 15년 이내 부동산임대업 소득금액에서만 공제(제3항제2호)","부동산·부동산상 권리 대여, 공장재단·광업재단 대여, 채굴에 관한 권리 대여 사업 포함"]},"오른쪽":{"이름":"주거용 건물 임대업","항목":["결손금을 그 과세기간의 근로소득금액·연금소득금액·기타소득금액·이자소득금액·배당소득금액에서 순서대로 공제(제1항, 제2항 단서)","공제하고 남은 이월결손금도 15년 이내 다른 소득금액에서 공제(제3항제1호)"]}}],"함정":"ㄴ은 '국외에 소재하는 주택'이 비과세 제외 대상이라는 점을 놓치기 쉽고, ㄷ은 광업재단 대여도 부동산임대업에 들어간다. 주거용 건물 임대업의 결손금만 다른 소득에서 공제된다.","개정":"2주택 소유자의 간주임대료 기준금액 12억원은 시행령 제53조제1항에 있고 <신설 2025.2.28> 표시가 붙어 있다."}}];